#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for SPI communication with MCP3008
#define CE_PIN  8
#define MOSI_PIN 10
#define MISO_PIN 9
#define SCLK_PIN 11

// MCP3008 SPI configuration
#define MCP3008_CS GPIO_ID_RPI_GPIO8 // CE0 on GPIO8
#define MCP3008_MOSI GPIO_ID_RPI_GPIO10 // MOSI on GPIO10
#define MCP3008_MISO GPIO_ID_RPI_GPIO9 // MISO on GPIO9
#define MCP3008_SCLK GPIO_ID_RPI_GPIO11 // SCLK on GPIO11

// Function prototypes
void setup_spi();
int read_mcp3008(int channel);
void handle_signals(int signum);
void cleanup();

int main() {
    // Initialize pigpio
    if (pi_init() == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pi_errstr());
        return EXIT_FAILURE;
    }

    // Setup SPI communication
    setup_spi();

    // Signal handlers for graceful shutdown
    signal(SIGINT, handle_signals);
    signal(SIGTERM, handle_signals);

    // Main loop
    while (1) {
        // Read moisture level from MCP3008 CH0
        int adc_value = read_mcp3008(0);

        // Convert ADC value to voltage and then to moisture level (assuming a linear relationship)
        float voltage = adc_value / 1023.0 * 3.3; // Assuming 3.3V reference voltage
        float moisture_level = voltage; // Assuming direct conversion for simplicity

        // Print timestamped moisture level reading
        time_t now = time(nullptr);
        struct tm timeinfo;
        localtime_r(&now, &timeinfo);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);
        printf("Moisture level at %s: %d (raw)\n", timestamp, adc_value);

        // Sleep for 1 second
        sleep(1);
    }

    // Cleanup on exit
    cleanup();

    return EXIT_SUCCESS;
}

// Function to setup SPI communication with MCP3008
void setup_spi() {
    // Set GPIO pins for SPI communication
    gpio_mode(MCP3008_CE_PIN, GPIO_MODE_OUTPUT);
    gpio_write(MCP3008_CE_PIN, 1); // CE0 high

    gpio_mode(MCP3008_MOSI_PIN, GPIO_MODE_OUTPUT);
    gpio_mode(MCP3008_MISO_PIN, GPIO_MODE_INPUT);
    gpio_mode(MCP3008_SCLK_PIN, GPIO_MODE_OUTPUT);

    // Set CE0 GPIO pin to low for chip select
    gpio_write(MCP3008_CE_PIN, 0);

    // Initialize SPI communication
    if (gpiod_spi_open(GPIOD_SPI0, 0) == -1) {
        fprintf(stderr, "Failed to open SPI device: %s\n", gpiod_strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Set SPI parameters
    gpiod_spi_set_speed(GPIOD_SPI0, 1000000); // 1 MHz
    gpiod_spi_set_mode(GPIOD_SPI0, GPIOD_SPI_MODE_0); // Mode 0 (CPOL=0, CPHA=0)
    gpiod_spi_set_chip_select(GPIOD_SPI0, MCP3008_CE_PIN);
}

// Function to read an analog value from MCP3008
int read_mcp3008(int channel) {
    int value = 0;

    // Set the channel
    gpiod_spi_write(GPIOD_SPI0, (channel << 4) | 0x01);

    // Start conversion
    gpiod_spi_transfer(GPIOD_SPI0, &channel, 1, &value, 1);

    // Check for errors
    if (gpiod_spi_get_status(GPIOD_SPI0) & GPIOD_SPI_STATUS_ERROR) {
        fprintf(stderr, "SPI transfer error: %s\n", gpiod_spi_get_error(GPIOD_SPI0));
        return -1;
    }

    return value;
}

// Signal handler for SIGINT and SIGTERM
void handle_signals(int signum) {
    // Clean up and exit
    if (pi_running()) {
        pi_cleanup();
    }
    exit(EXIT_FAILURE);
}

// Function to clean up resources
void cleanup() {
    // Close SPI device
    gpiod_spi_close(GPIOD_SPI0);

    // Shutdown pigpio
    pi_cleanup();

    // Reset GPIO pins to default state
    gpio_mode(MCP3008_CE_PIN, GPIO_MODE_INPUT);
    gpio_mode(MCP3008_MOSI_PIN, GPIO_MODE_INPUT);
    gpio_mode(MCP3008_MISO_PIN, GPIO_MODE_INPUT);
    gpio_mode(MCP3008_SCLK_PIN, GPIO_MODE_INPUT);
}

