#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>

// Define constants for ADS1115 and MLX91219
#define ADS1115_ADDR 0x48
#define ADS1115_BUS 1
#define MLX91219_SENSITIVITY 40.0 /* mV/A */
#define MLX91219_ZERO_OFFSET 2048.0 /* mid-supply voltage in mV */

// ADS1115 register addresses
#define ADS1115_CONFIG_REG 0x00
#define ADS1115_MUX_REG 0x01
#define ADS1115_PGA_REG 0x02
#define ADS1115_SAMPLING_RATE_REG 0x03

// ADS1115 register values
#define ADS1115_SINGLE_SHOT 0x08
#define ADS1115_MUX_100 0x00
#define ADS1115_PGA_4096 0x07

// Function prototypes
void setup_ads1115(void);
void read_ads1115_current(uint16_t *current);
void cleanup_ads1115(void);
void handle_signal(int signum);

int main(void) {
    // Initialize pigpio
    if (gpioInitialised() == 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    // Signal handler for SIGINT
    signal(SIGINT, handle_signal);

    // Setup ADS1115
    setup_ads1115();

    // Main loop
    while (1) {
        // Read current every 500ms
        read_ads1115_current(&current_reading);
        printf("Current: %.2f A\n", current_reading / MLX91219_SENSITIVITY);

        // Sleep for 500ms
        usleep(500000);
    }

    // Cleanup on SIGINT
    cleanup_ads1115();

    return EXIT_SUCCESS;
}

// Function to setup ADS1115
void setup_ads1115(void) {
    // Open I2C bus
    int ads1115_fd = i2cOpen(ADS1115_BUS);
    if (ads1115_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", i2cError(ads1115_fd));
        exit(EXIT_FAILURE);
    }

    // Write configuration to ADS1115
    uint8_t config_data[] = {ADS1115_SINGLE_SHOT};
    if (i2cWriteI2CBlockData(ads1115_fd, ADS1115_ADDR, ADS1115_CONFIG_REG, 1, config_data) < 0) {
        fprintf(stderr, "Failed to write configuration to ADS1115: %s\n", i2cError(ads1115_fd));
        exit(EXIT_FAILURE);
    }

    // Set MUX and PGA
    uint8_t mux_data[] = {ADS1115_MUX_100};
    if (i2cWriteI2CBlockData(ads1115_fd, ADS1115_ADDR, ADS1115_MUX_REG, 1, mux_data) < 0) {
        fprintf(stderr, "Failed to set MUX on ADS1115: %s\n", i2cError(ads1115_fd));
        exit(EXIT_FAILURE);
    }

    uint8_t pga_data[] = {ADS1115_PGA_4096};
    if (i2cWriteI2CBlockData(ads1115_fd, ADS1115_ADDR, ADS1115_PGA_REG, 1, pga_data) < 0) {
        fprintf(stderr, "Failed to set PGA on ADS1115: %s\n", i2cError(ads1115_fd));
        exit(EXIT_FAILURE);
    }

    // Set sampling rate
    uint8_t sampling_rate_data[] = {0x03, 0x00}; // 128 samples per second
    if (i2cWriteI2CBlockData(ads1115_fd, ADS1115_ADDR, ADS1115_SAMPLING_RATE_REG, 2, sampling_rate_data) < 0) {
        fprintf(stderr, "Failed to set sampling rate on ADS1115: %s\n", i2cError(ads1115_fd));
        exit(EXIT_FAILURE);
    }
}

// Function to read current from ADS1115
void read_ads1115_current(uint16_t *current) {
    // Read 16-bit data from ADS1115
    uint8_t data[2];
    if (i2cReadI2CBlockData(ads1115_fd, ADS1115_ADDR, ADS1115_CONFIG_REG, 2, data) < 0) {
        fprintf(stderr, "Failed to read ADS1115: %s\n", i2cError(ads1115_fd));
        return;
    }

    // Convert data to current
    uint16_t raw_value = (data[0] << 8) | data[1];
    *current = (raw_value - MLX91219_ZERO_OFFSET) / MLX91219_SENSITIVITY;
}

// Function to cleanup ADS1115
void cleanup_ads1115(void) {
    // Close I2C handle
    i2cClose(ads1115_fd);
}

// Signal handler for SIGINT
void handle_signal(int signum) {
    // Clean up
    cleanup_ads1115();
    // Terminate GPIO
    gpioTerminate();
    // Exit
    exit(EXIT_SUCCESS);
}

