#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <pigpio.h>
#include <stdint.h>

#define PIGPIO_ID 0  // Use the default pigpio instance

// GPIO constants
#define GPIO4 4  // BCM GPIO 4
#define CE0 8   // SPI CE0 (BCM GPIO 8)

// MCP3008 SPI constants
#define MCP3008_CS GPIO4
#define MCP3008_SCLK 7  // BCM GPIO 7
#define MCP3008_MISO -1 // Not used
#define MCP3008_MOSI 11 // BCM GPIO 11
#define MCP3008_CMD 10  // BCM GPIO 10

// Flame sensor constants
#define FLAME_SENSOR_D0 0  // D0 pin

// ADC value to temperature mapping
int adc_to_temp(int adc) {
    return (adc - 50) * (40.0 / 950.0);
}

// Function to read digital output from KY-026 Flame Sensor
int read_flame_sensor() {
    int value = digitalRead(PIGPIO_ID, GPIO4);
    return value == 1;
}

// Function to read analog value from MCP3008
int read_analog_value() {
    int value = adcRead(PIGPIO_ID, MCP3008_SCLK, MCP3008_MOSI, MCP3008_CMD, MCP3008_CS);
    return value;
}

// Main function
int main() {
    pigpio *pi = NULL;
    FILE *file = NULL;
    char line[256];
    int timestamp, flame_detected, temperature;
    int adc_value;

    // Initialize pigpio
    if (pigpioSetup(PIGPIO_ID) == -1) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    // Open SPI
    if (spiOpen(PIGPIO_ID, MCP3008_SCLK, MCP3008_MOSI, MCP3008_CMD, MCP3008_CS, 1000000) == -1) {
        fprintf(stderr, "Failed to open SPI\n");
        pigpioFinish(pi);
        return EXIT_FAILURE;
    }

    // Open file for writing
    file = fopen("flame_data.csv", "a+");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for writing\n");
        fclose(file);
        pigpioFinish(pi);
        return EXIT_FAILURE;
    }

    while (1) {
        // Get current timestamp
        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp_str[50];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Read digital output from flame sensor
        flame_detected = read_flame_sensor();

        // Read analog value from MCP3008
        adc_value = read_analog_value();

        // Map ADC value to temperature
        temperature = adc_to_temp(adc_value);

        // Construct CSV line
        sprintf(line, "%s,%d,%d", timestamp_str, flame_detected, temperature);

        // Write to file
        if (fwrite(line, sizeof(char), strlen(line), file) != strlen(line)) {
            fprintf(stderr, "Failed to write to file\n");
            fclose(file);
            pigpioFinish(pi);
            return EXIT_FAILURE;
        }

        // Close file and reopen for next write
        fclose(file);
        file = fopen("flame_data.csv", "a+");
        if (file == NULL) {
            fprintf(stderr, "Failed to reopen file for writing\n");
            pigpioFinish(pi);
            return EXIT_FAILURE;
        }
    }

    // Clean up resources on SIGINT (Ctrl+C)
    struct sigaction sa;
    sa.sa_handler = SIG_IGN; // Ignore SIGINT
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Clean up resources
    pigpioFinish(pi);
    fclose(file);

    return EXIT_SUCCESS;
}

