        sprintf(line, "%s,%d,%d", timestamp_str, flame_detected, temperature);

        // Write to file
        if (fwrite(line, sizeof(char), strlen(line), file) != strlen(line)) {
            fprintf(stderr, "Failed to write to file\n");
            fclose(file);
            pigpioFinish(pi);
            return EXIT_FAILURE;
        }

        // Close file and reopen for next write
        fclose(file);
        file = fopen("flame_data.csv", "a+");
        if (file == NULL) {
            fprintf(stderr, "Failed to reopen file for writing\n");
            pigpioFinish(pi);
            return EXIT_FAILURE;
        }
    }

    // Clean up resources on SIGINT (Ctrl+C)
    struct sigaction sa;
    sa.sa_handler = SIG_IGN; // Ignore SIGINT
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Clean up resources
    pigpioFinish(pi);
    fclose(file);

    return EXIT_SUCCESS;
}
