void read_current();
void convert_voltage_to_current(float voltage);
void handle_threshold_exceeded(float current);
void cleanup_resources();
void log_measurement(float current, const char *timestamp);

int main(int argc, char **argv) {
    // Initialize the SPI device and GPIO
    initialize_sensors();

    // Main loop
    while (1) {
        // Read current
        read_current();

        // Handle threshold exceeded
        handle_threshold_exceeded(read_current);

        // Log measurement
        log_measurement(read_current, ctime(NULL));

        // Sleep for 1 second
        sleep(1);
    }

    // Cleanup on exit
    cleanup_resources();

    return 0;
}

// Function to initialize SPI and GPIO
void initialize_sensors() {
    int spi_fd;
    struct spi_device *spi_device;
    int gpio_fd;

    // Try to open the GPIO chip
    for (const char *chip_name = gpiochip_names[0]; chip_name; chip_name = gpiochip_names[1]) {
        gpio_fd = gpiod_open(chip_name, "r");
        if (gpio_fd < 0) {
            fprintf(stderr, "Failed to open GPIO chip: %s\n", chip_name);
            exit(EXIT_FAILURE);
        }
        break;
    }

    // Open SPI device
    spi_fd = spidev_open(0, 0);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", spidev_errstr(spi_fd));
        exit(EXIT_FAILURE);
    }

    // Configure SPI
    spidev_set_mode(spi_fd, SPIDEV_MODE_0);
    spidev_set_bitrate(spi_fd, 1000000); // 1 MHz

    // Open the MCP3008 ADC channel
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &1000000) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", spidev_errstr(spi_fd));
        exit(EXIT_FAILURE);
    }

    // Open the GPIO pin for the fan
    if (gpiod_open(GPIO_FAN, GPIO_OUTPUT_OPEN_DRAIN) < 0) {
        fprintf(stderr, "Failed to open GPIO pin for fan: %s\n", gpiod_error_name(gpio_fd));
        exit(EXIT_FAILURE);
    }

    // Set up GPIO direction for reading current
    if (gpiod_direction_input(GPIO_FAN) < 0) {
        fprintf(stderr, "Failed to set GPIO pin direction: %s\n", gpiod_error_name(gpio_fd));
        exit(EXIT_FAILURE);
    }

    // Initialize sensor and ADC
    initialize_sensor();
}

// Function to read current from the sensor
void read_current() {
    int adc_value;
    float voltage, current;

    // Send SPI command to MCP3008
    if (write(spi_fd, (char *)&MCP3008_CMD, 3) != 3) {
        fprintf(stderr, "SPI write failed\n");
        return;
    }

    // Read single-ended channel 0
    if (read(spi_fd, (char *)&adc_value, 1) != 1) {
        fprintf(stderr, "SPI read failed\n");
        return;
    }

    // Convert ADC value to voltage
    voltage = (adc_value / 1024.0) * ADC_VREF;

    // Convert voltage to current using sensor sensitivity
    current = voltage / DEFAULT_SENSITIVITY;

    // Handle threshold exceeded
    handle_threshold_exceeded(current);

    // Log measurement
    log_measurement(current, ctime(NULL));
}

// Function to convert ADC voltage to current
void convert_voltage_to_current(float voltage) {
    // Assuming default sensitivity of 100 mV/A
    current = voltage / DEFAULT_SENSITIVITY;
}

// Function to handle threshold exceeded condition
void handle_threshold_exceeded(float current) {
    if (current > DEFAULT_THRESHOLD) {
        // Turn on the fan
        gpiod_set_value(GPIO_FAN, 1);
    } else {
        // Turn off the fan
        gpiod_set_value(GPIO_FAN, 0);
    }
}

// Function to cleanup resources
void cleanup_resources() {
    // Close SPI device
    close(spi_fd);

    // Release GPIO pins
    gpiod_release(GPIO_FAN);

    // Close GPIO chip file descriptor
    gpiod_close(gpio_fd);
}

