// Function: init_pigpio
void init_pigpio() {
    pi_pid = fork();
    if (pi_pid == 0) {
        pigpio *pg = pigpio_open();
        if (!pg) {
            fprintf(stderr, "Failed to open pigpio\n");
            exit(EXIT_FAILURE);
        }
        pigpio_set_mode(pg, PIGPIO_MODE_ON);
        pigpio_wait_for_start(pg);
    }
}

// Function: init_ads1115
void init_ads1115() {
    int adc_fd = open("/dev/i2c-1", O_RDWR);
    if (adc_fd == -1) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        exit(EXIT_FAILURE);
    }

    struct ads1115_config config = {
        .address = ADS1115_I2C_ADDRESS,
        .mode = ADS1115_MODE_16BIT,
        .gain = ADS1115_GAIN_X1
    };

    if (ioctl(adc_fd, I2C_SLAVE, ADS1115_I2C_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        exit(EXIT_FAILURE);
    }

    if (ioctl(adc_fd, IOCTL ADS1115 START_CONVERSION, &config) < 0) {
        fprintf(stderr, "Failed to start conversion\n");
        exit(EXIT_FAILURE);
    }

    // Wait for conversion to complete
    usleep(1000);  // Wait for 1ms
}

// Function: read_co_value
void read_co_value(uint16_t *raw_value) {
    uint8_t data[2];

    // Read raw value from ADS1115
    if (ioctl(adc_fd, IOCTL ADS1115 READ, data) < 0) {
        fprintf(stderr, "Failed to read ADS1115 data\n");
        exit(EXIT_FAILURE);
    }

    *raw_value = (data[0] << 8) | data[1];
}

// Function: convert_co_to_ppm
float convert_co_to_ppm(uint16_t raw_value) {
    if (raw_value > calibration_data[0] || raw_value < calibration_data[2]) {
        fprintf(stderr, "ADC value out of range\n");
        return 0.0;
    }

    float ppm = (raw_value - calibration_data[1]) / (calibration_data[2] - calibration_data[1]) * 10000.0;
    return ppm;
}

// Function: log_co_ppm
void log_co_ppm(float ppm) {
    char filename[] = "co_log.txt";
    FILE *file = fopen(filename, "a+");
    if (!file) {
        fprintf(stderr, "Failed to open file for logging\n");
        return;
    }

    fprintf(file, "%f %s\n", ppm, __TIME__);
    fclose(file);
}

// Function: cleanup
void cleanup() {
    if (adc_fd != -1) {
        close(adc_fd);
    }

    if (pi_pid > 0) {
        kill(pi_pid, SIGTERM);
        waitpid(pi_pid, NULL, 0);
    }
}

// Signal handler: handle_signal
void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        fprintf(stderr, "Exiting on signal %d\n", signum);
        exit(EXIT_FAILURE);
    }
}

