#define GPIO4 7
#define GPIO8 18
#define GPIO11 23
#define GPIO10 24
#define GPIO9 25

#define SPI_CLOCK_FREQ 1000000

// MCP3008 SPI configuration
#define MCP3008_CS GPIO8
#define MCP3008_SCLK GPIO11
#define MCP3008_MISO GPIO9
#define MCP3008_MOSI GPIO10

// Flame sensor pin
#define FLAME_SENSOR_GPIO GPIO4

// Flame sensor threshold for detection
#define FLAME_THRESHOLD 1023

// Linear scaling factor for temperature approximation
#define TEMPERATURE_SCALE_FACTOR 0.004

// File path for CSV data
#define FILE_PATH "flame_data.csv"

// Function prototypes
void initialize_pigpio();
int open_spi_device();
void close_spi_device(int spi_fd);
int read_mcp3008(int spi_fd, int channel);
void write_to_file(int fd, const char *data);
void cleanup();

int main() {
    // Initialize pigpio
    initialize_pigpio();

    // Open SPI device
    int spi_fd = open_spi_device();

    if (spi_fd == -1) {
        fprintf(stderr, "Error opening SPI device.\n");
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Read flame sensor
        int flame_present = digitalRead(FLAME_SENSOR_GPIO);
        if (flame_present == 1) {
            printf("Flame detected.\n");
        } else {
            printf("No flame detected.\n");
        }

        // Read temperature from MCP3008
        int adc_value = read_mcp3008(spi_fd, 0);
        float temperature = adc_value * TEMPERATURE_SCALE_FACTOR;
        printf("Temperature: %.1f°C\n", temperature);

        // Write to CSV file
        char timestamp[50];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        write_to_file(STDOUT_FILENO, timestamp);

        write_to_file(STDOUT_FILENO, ",");

        write_to_file(STDOUT_FILENO, (char *)(&adc_value), sizeof(int));
        write_to_file(STDOUT_FILENO, "\n");

        // Close SPI device on SIGINT
        if (signal(SIGINT, SIG_IGN) == SIG_ERR) {
            fprintf(stderr, "Failed to ignore SIGINT.\n");
            return EXIT_FAILURE;
        }

        // Cleanup on exit
        atexit(cleanup);
    }

    // Clean up resources
    close_spi_device(spi_fd);
    pigpio_stop();
    return EXIT_SUCCESS;
}

// Initialize pigpio
void initialize_pigpio() {
    if (pigpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        exit(EXIT_FAILURE);
    }
}

// Open SPI device
int open_spi_device() {
    int spi_fd = -1;
    if (pigpio.spi_open(0, SPI_CLOCK_FREQ) == 0) {
        spi_fd = pigpio.spi_fd();
    }
    return spi_fd;
}

// Close SPI device
void close_spi_device(int spi_fd) {
    if (spi_fd != -1) {
        pigpio.spi_close(spi_fd);
        spi_fd = -1;
    }
}

// Read MCP3008
int read_mcp3008(int spi_fd, int channel) {
    int value = 0;
    if (pigpio.spi_xfer(spi_fd, (char *)&channel, 1, (char *)&value, 1) < 0) {
        fprintf(stderr, "Error reading from MCP3008.\n");
        return -1;
    }
    return value;
}

// Write to file
void write_to_file(int fd, const char *data) {
    if (fd == STDOUT_FILENO) {
        fprintf(fd, "%s", data);
    } else {
        if (write(fd, data, strlen(data)) != strlen(data)) {
            fprintf(stderr, "Error writing to file.\n");
        }
    }
}

// Cleanup function
void cleanup() {
    close_spi_device(-1);
    pigpio_stop();
}

