// Constants
#define MIC_ADDR_1 0x48
#define MIC_ADDR_2 0x49
#define REF_PRESSURE 20e-6
#define MIC_SENSITIVITY -38
#define SAMPLE_INTERVAL_MS 100
#define ERROR_DB_VALUE -999.0

// Function prototypes
void handleSIGINT(int signum);
void handleSIGTERM(int signum);
