int main() {
    // Initialize pigpio
    pigpio *pi = NULL;
    if (pigpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error());
        return EXIT_FAILURE;
    }

    // Register signal handlers
    signal(SIGINT, handleSIGINT);
    signal(SIGTERM, handleSIGTERM);

    // Main loop
    while (1) {
        // Read microphone data
        int pressureLevel1 = readMicPressureLevel(pi, MIC_ADDR_1);
        int pressureLevel2 = readMicPressureLevel(pi, MIC_ADDR_2);

        // Handle errors
        if (pressureLevel1 == -1) {
            pressureLevel1 = ERROR_DB_VALUE;
        }
        if (pressureLevel2 == -1) {
            pressureLevel2 = ERROR_DB_VALUE;
        }

        // Convert to dB SPL
        convertDbVToDbPascal(pressureLevel1);
        convertDbVToDbPascal(pressureLevel2);

        // Log data
        time_t now = time(NULL);
        char data[256];
        sprintf(data, "%ld %ld\n", pressureLevel1, pressureLevel2);
        logDataToFile(data, now);

        // Sleep for the interval
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    // Clean up
    logDataToFile("Shutdown message", time(NULL));
    handleSIGINT(0);
    pigpio_cleanup(pi);

    return EXIT_SUCCESS;
}

