    printf("SIGINT received, shutting down...\n");
    pigpio_stop();
    exit(EXIT_SUCCESS);
}

void handleSIGTERM(int signum) {
    printf("SIGTERM received, shutting down...\n");
    pigpio_stop();
    exit(EXIT_SUCCESS);
}

// Function to read microphone pressure level
int readMicPressureLevel(pigpio *pi, int addr) {
    int value1, value2;
    if (pigpio_i2c_read(pi, addr, &value1, 1) < 0 || pigpio_i2c_read(pi, addr + 1, &value2, 1) < 0) {
        return -1;
    }
    return (value1 + value2) / 2; // Average the two readings
}

// Function to convert dBV to dB SPL using the given sensitivity and reference pressure
