    double pascal = pow(10.0, (dbV + MIC_SENSITIVITY) / 20.0);
    double referencePressure = 20e-6;
    double dbSPL = 20 * log10(pascal / referencePressure);
    printf("Converted dBV to dB SPL: %f dB SPL\n", dbSPL);
}

