void logDataToFile(char *data, time_t timestamp) {
    FILE *file = fopen("audio_log.txt", "a+");
    if (file == NULL) {
        perror("Failed to open audio_log.txt");
        return;
    }
    fprintf(file, "%s %ld\n", data, (long)timestamp);
    fclose(file);
}

