#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <pigpio.h>
#include <stdint.h>

#define PI_GPIO_ID 27 // GPIO27 for LED
#define MIC1_ADC_CHANNEL 0
#define MIC2_ADC_CHANNEL 1
#define SAMPLE_RATE_HZ 1000 // 1 ms interval
#define SAMPLE_WINDOW_MS 100 // 100 ms window
#define RMS_THRESHOLD 0.7
#define FILE_NAME "audio_events.csv"

// MCP3008 SPI configuration
#define SPI_PORT 0
#define SPI_DEVICE 0
#define SPI_MODE 0 // Mode 0: CPOL=0, CPHA=0

// ADC resolution (10 bits)
#define ADC_RESOLUTION 10

// GPIO constants
#define CE0_GPIO 8
#define CE1_GPIO 9
#define MOSI_GPIO 10
#define SCLK_GPIO 11
#define MISO_GPIO 9

// Global variables
pigpio *pi;
FILE *file;
uint8_t adc_channel;
double mic1_rms = 0.0;
double mic2_rms = 0.0;
int led_state = 0;

// Function prototypes
void spi_init();
void adc_read(uint8_t channel, int16_t *data);
void calculate_rms(int16_t *data, double *rms);
void handle_sigint();
void toggle_led(int state);
void log_event(const char *timestamp, double mic1_rms, double mic2_rms);

int main() {
    // Initialize pigpio
    pi = pigpio_open();
    if (pi == NULL) {
        fprintf(stderr, "Failed to open pigpio\n");
        return EXIT_FAILURE;
    }

    // Initialize SPI
    spi_init();

    // Set GPIOs
    gpio_mode_set(GPIO_ID_WIRE, PI_GPIO_ID, GPIO_OUTPUT);
    gpio_set_level(GPIO_ID_WIRE, PI_GPIO_ID, led_state);

    // Main loop
    while (1) {
        // Toggle LED state
        toggle_led(!led_state);

        // Sample and calculate RMS
        int16_t mic1_data[ADC_RESOLUTION];
        int16_t mic2_data[ADC_RESOLUTION];
        adc_read(MIC1_ADC_CHANNEL, mic1_data);
        adc_read(MIC2_ADC_CHANNEL, mic2_data);

        calculate_rms(mic1_data, &mic1_rms);
        calculate_rms(mic2_data, &mic2_rms);

        // Check RMS thresholds
        if (mic1_rms > RMS_THRESHOLD || mic2_rms > RMS_THRESHOLD) {
            log_event((char *)ctime(&time(0)), mic1_rms, mic2_rms);
            handle_sigint();
        }

        // Sleep to maintain 1 ms interval
        usleep(SAMPLE_RATE_HZ * 1000);
    }

    // Clean up
    close_file(&file);
    gpio_free(GPIO_ID_WIRE, PI_GPIO_ID);
    spi_close();
    pigpio_close(pi);

    return EXIT_SUCCESS;
}

// SPI initialization function
void spi_init() {
    gpio_mode_set(CE0_GPIO, CE0_GPIO, GPIO_ALT0); // CE0 to ALT0
    gpio_mode_set(CE1_GPIO, CE1_GPIO, GPIO_ALT0); // CE1 to ALT0
    gpio_set_level(CE0_GPIO, CE0_GPIO, 1); // CE0 high
    gpio_set_level(CE1_GPIO, CE1_GPIO, 1); // CE1 high

    spi_set_mode(SPI_PORT, SPI_DEVICE, SPI_MODE);
    spi_set_speed(SPI_PORT, 1000000); // 1 MHz

    // Initialize MCP3008
    spi_write(SPI_PORT, 0x6C); // Set gain to 1
    spi_write(SPI_PORT, 0x08); // Set reference voltage to 2.56V
    spi_write(SPI_PORT, 0x0C); // Set channel to 0 (MIC1)
    spi_write(SPI_PORT, 0x01); // Set channel to 1 (MIC2)
}

// ADC read function
void adc_read(uint8_t channel, int16_t *data) {
    spi_write(SPI_PORT, 0x80 | channel); // Start conversion
    usleep(5); // Wait for conversion to complete

    *data = spi_read(SPI_PORT); // Read converted data
}

// Calculate RMS function
void calculate_rms(int16_t *data, double *rms) {
    int i;
    double sum = 0.0;

    for (i = 0; i < ADC_RESOLUTION; i++) {
        sum += data[i] * data[i];
    }

    *rms = sqrt(sum / ADC_RESOLUTION);
}

// Handle SIGINT (Ctrl+C)
void handle_sigint() {
    fprintf(stderr, "SIGINT received, shutting down...\n");
    toggle_led(0); // Turn off LED
    exit(0);
}

// Toggle LED state
void toggle_led(int state) {
    led_state = !led_state;
    gpio_set_level(GPIO_ID_WIRE, PI_GPIO_ID, led_state);
}

// Log event to CSV file
void log_event(const char *timestamp, double mic1_rms, double mic2_rms) {
    char buffer[256];
    sprintf(buffer, "%s,%f,%f", timestamp, mic1_rms, mic2_rms);

    FILE *file = fopen(FILE_NAME, "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for writing: %s\n", FILE_NAME);
        return;
    }

    fprintf(file, "%s\n", buffer);
    fclose(file);
}

// Main program initialization and cleanup
int main(int argc, char **argv) {
    // Initialize global variables
    pi = NULL;
    file = NULL;

    // Main program execution
    return main();
}

