#include <Wire.h>

#define PI_GPIO_ID 17 // Warning LED GPIO
#define MLX91204_ADDR 0x29 // MLX91204 I2C address
#define ADS1115_ADDR 0x48 // ADS1115 I2C address
#define SAMPLE_RATE_HZ 10 // Sample rate in Hz
#define BUFFER_SIZE 100 // Circular buffer size
#define THRESHOLD_CURRENT 50.0 // Overcurrent threshold in A

volatile sig_atomic_t sigIntReceived = 0;

// MLX91204 register definitions
#define MLX91204_REG_STATUS 0x00
#define MLX91204_REG_CURRENT 0x01

// ADS1115 register definitions
#define ADS1115_REG_CONFIG 0x00
#define ADS1115_REG_DATA_H 0x01

// ADC conversion result scaling factor (5V full scale)
#define ADC_SCALE_FACTOR 1024.0

// Circular buffer for current readings
float currentReadings[BUFFER_SIZE];

void setup_pigpio() {
    if (pigpioSetup() == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }
}

void setup_i2c() {
    if (Wire.begin() != WL_OK) {
        fprintf(stderr, "Failed to initialize I2C: %s\n", Wire.errorString());
        exit(EXIT_FAILURE);
    }
}

void cleanup_resources() {
    if (pigpioIsRunning()) {
        pigpioStop();
        pigpioExit();
    }
    Wire.end();
}

void handle_signal(int signum) {
    sigIntReceived = 1;
    cleanup_resources();
}

void read_current_from_mlx91204() {
    float current;
    if (pigpioWrite(PI_GPIO_ID, PI_HIGH) == -1) {
        fprintf(stderr, "Failed to set warning LED GPIO high: %s\n", pigpioError());
        return;
    }

    // Write to MLX91204 to start conversion
    pigpioWrite(MLX91204_ADDR, MLX91204_REG_CURRENT, 0x01);

    // Wait for conversion to complete
    while (pigpioRead(MLX91204_ADDR, MLX91204_REG_STATUS) & 0x01) {
        // No-op
    }

    // Read current value from MLX91204
    pigpioWrite(MLX91204_ADDR, 0x00, 0x01); // Select REG_CURRENT
    current = (pigpioRead(MLX91204_ADDR, 0x01) * ADC_SCALE_FACTOR) / 1024.0;

    // Read from ADS1115
    Wire.beginTransmission(ADS1115_ADDR);
    Wire.write(ADS1115_REG_CONFIG);
    Wire.write(0x00); // Single-ended mode, channel A0
    Wire.endTransmission();

    Wire.requestFrom(ADS1115_ADDR, 1);
    float ads1115Reading = (Wire.read() * ADC_SCALE_FACTOR) / 1024.0;

    // Combine readings (assuming linear correlation)
    float combinedCurrent = (current + ads1115Reading) / 2.0;

    // Update circular buffer
    currentReadings[buf_index++] = combinedCurrent;
    if (buf_index >= BUFFER_SIZE) {
        buf_index = 0; // Wrap around
    }

    // Check for overcurrent
    float averageCurrent = (buf_index > 0) ? (1.0 / buf_index) * sum(currentReadings) : 0.0;
    if (averageCurrent > THRESHOLD_CURRENT) {
        fprintf(stderr, "Overcurrent detected! Average current: %.1fA\n", averageCurrent);
        pigpioWrite(PI_GPIO_ID, PI_LOW); // Turn off warning LED
    }
}

void main_loop() {
    while (!sigIntReceived) {
        read_current_from_mlx91204();
        if (buf_index == BUFFER_SIZE) {
            // Handle buffer overflow (optional: discard oldest reading)
        }
        usleep(100000); // 10Hz sampling rate
    }
}

int main() {
    setup_pigpio();
    setup_i2c();

    signal(SIGINT, handle_signal);

    sum = 0.0; // Initialize sum for average calculation
    buf_index = 0; // Initialize buffer index

    main_loop();

    cleanup_resources();

    return 0;
}

