#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>

// Define the I2C address and bus for the TCS34725 sensor
#define TCS34725_ADDRESS 0x29
#define I2C_BUS 1

// Sensor registers
#define REG_ID 0x12
#define REG_ATIME 0x01
#define REG_CONTROL 0x0F
#define REG_ENABLE 0x00

// Sensor ID check value
#define EXPECTED_ID 0x44

// Integration time and gain settings
#define ATIME_VALUE 0xFF
#define CONTROL_VALUE 0x01

// CSV file header
#define CSV_HEADER "clear,red,green,blue"

// Signal handler for clean shutdown
void signal_handler(int signum) {
    // Close I2C handle
    pigpio_i2c_close(i2c_handle);

    // Flush and close the CSV file
    fclose(color_log_file);

    // Terminate pigpio
    gpioTerminate();

    // Exit the program
    exit(0);
}

int main() {
    // Initialize pigpio and open the I2C bus
    int rc = pigpio_init();
    if (rc != PI_ERROR_OK) {
        fprintf(stderr, "Failed to initialize pigpio: %d\n", rc);
        return 1;
    }

    i2c_handle = pigpio_i2c_open(I2C_BUS);
    if (i2c_handle == NULL) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", pigpio_error());
        pigpio_close();
        return 1;
    }

    // Check if the sensor is present
    uint8_t id;
    rc = pigpio_i2c_read(i2c_handle, TCS34725_ADDRESS, REG_ID, &id, 1);
    if (rc != PI_ERROR_OK) {
        fprintf(stderr, "Failed to read sensor ID: %d\n", rc);
        pigpio_i2c_close(i2c_handle);
        pigpio_close();
        return 1;
    }

    if (id != EXPECTED_ID) {
        fprintf(stderr, "Sensor ID mismatch: expected 0x44, got 0x%02X\n", id);
        pigpio_i2c_close(i2c_handle);
        pigpio_close();
        return 1;
    }

    // Configure the sensor
    rc = pigpio_i2c_write(i2c_handle, TCS34725_ADDRESS, REG_ATIME, ATIME_VALUE, 1);
    if (rc != PI_ERROR_OK) {
        fprintf(stderr, "Failed to write ATIME register: %d\n", rc);
        pigpio_i2c_close(i2c_handle);
        pigpio_close();
        return 1;
    }

    rc = pigpio_i2c_write(i2c_handle, TCS34725_ADDRESS, REG_CONTROL, CONTROL_VALUE, 1);
    if (rc != PI_ERROR_OK) {
        fprintf(stderr, "Failed to write CONTROL register: %d\n", rc);
        pigpio_i2c_close(i2c_handle);
        pigpio_close();
        return 1;
    }

    // Power on and enable ADC
    rc = pigpio_i2c_write(i2c_handle, TCS34725_ADDRESS, REG_ENABLE, 0x03, 1);
    if (rc != PI_ERROR_OK) {
        fprintf(stderr, "Failed to write ENABLE register: %d\n", rc);
        pigpio_i2c_close(i2c_handle);
        pigpio_close();
        return 1;
    }

    // Wait for at least 3 ms after power-on
    usleep(3000);

    // Open CSV file for appending
    FILE *color_log_file = fopen("color_log.csv", "a+");
    if (color_log_file == NULL) {
        fprintf(stderr, "Failed to open CSV file for writing: %s\n", strerror(errno));
        pigpio_i2c_close(i2c_handle);
        pigpio_close();
        return 1;
    }

    // Write header if the file is new
    if (fseek(color_log_file, 0, SEEK_END) == -1 || feof(color_log_file)) {
        fprintf(color_log_file, "%s", CSV_HEADER);
        fseek(color_log_file, 0, SEEK_SET);
    }

    // Main loop
    while (1) {
        // Read color values
        uint16_t colors[4];
        rc = pigpio_i2c_read(i2c_handle, TCS34725_ADDRESS, REG_14, colors, 4);
        if (rc != PI_ERROR_OK) {
            fprintf(stderr, "Failed to read color values: %d\n", rc);
            if (++fail_count == 3) {
                break; // Exit after 3 consecutive failures
            } else {
                // Transient failure, print warning and continue
                fprintf(stderr, "Warning: I2C read failed. Continuing...\n");
            }
        } else {
            // Format and write to CSV
            char timestamp[23];
            time_t now = time(NULL);
            struct tm *timeinfo = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            fprintf(color_log_file, "%s, %04X, %04X, %04X, %04X\n", timestamp, colors[0], colors[1], colors[2], colors[3]);
        }

        // Sleep for 1 second
        usleep(1000000);
    }

    // Clean shutdown on SIGINT/SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Close I2C handle and CSV file
    pigpio_i2c_close(i2c_handle);
    fclose(color_log_file);

    // Terminate pigpio
    gpioTerminate();

    // Exit the program
    return 0;
}

