void read_mcp3008(int channel);
void map_adc_to_moisture(int adc);
void write_to_csv(const char *message);
void cleanup();

int main() {
    srand(time(NULL));

    // Initialize GPIO line for MCP3008 chip select
    if (gpiod_open(GPIO_CE0, GPIOD_OUT_INIT_LOW) < 0) {
        perror("Failed to open GPIO line for MCP3008 CS");
        return EXIT_FAILURE;
    }

    // Open SPI device
    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        gpiod_close(GPIO_CE0);
        return EXIT_FAILURE;
    }

    // Setup SPI
    setup_spi();

    // Main loop
    while (1) {
        // Read moisture sensor values
        int moisture1, moisture2;
        read_mcp3008(0);
        map_adc_to_moisture(moisture1);
        read_mcp3008(1);
        map_adc_to_moisture(moisture2);

        // Log to CSV file
        char timestamp[50];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        write_to_csv("%s,%d,%d\n", timestamp, moisture1, moisture2);

        // Sleep for 5 seconds
        sleep(SAMPLE_RATE_HZ);
    }

    // Cleanup
    cleanup();

    return EXIT_SUCCESS;
}

// Function to setup SPI
void setup_spi() {
    struct spi_ioc_transfer transfers[] = {
        // Transfer for reading from MCP3008
        {
            .tx_buf = NULL,
            .rx_buf = (unsigned char[]) {0x01, MCP3008_ADDR, 0x80 | (0x01 << 6)}, // Start conversion, channel 0
            .len = 2,
            .delay_usecs = 0,
        },
        {
            .tx_buf = NULL,
            .rx_buf = (unsigned char[]) {0x00}, // Stop conversion command
            .len = 1,
            .delay_usecs = 0,
        },
    };

    int rc = spidev_writeSpiTransfer(spi_fd, transfers, 2);
    if (rc != 2) {
        perror("Failed to send SPI commands");
        close(spi_fd);
        gpiod_close(GPIO_CE0);
        return;
    }
}

// Function to read MCP3008 for a given channel
void read_mcp3008(int channel) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned char[]) {0x01, MCP3008_ADDR, 0x80 | (channel << 6)}, // Start conversion, select channel
        .rx_buf = (unsigned char[2]),
        .len = 2,
        .delay_usecs = 0,
    };

    int rc = spidev_writeSpiTransfer(spi_fd, &transfer, 1);
    if (rc != 1) {
        perror("Failed to read from MCP3008");
        close(spi_fd);
        gpiod_close(GPIO_CE0);
        return;
    }

    // Read the result
    int adc = (transfer.rx_buf[1] << 8) | transfer.rx_buf[0];
    map_adc_to_moisture(adc);
}

// Function to map ADC value to moisture percentage
void map_adc_to_moisture(int adc) {
    int moisture = (adc * 100) / 1023;
    moisture = (moisture < 0) ? 0 : (moisture > 100) ? 100 : moisture;
}

// Function to write to CSV file
void write_to_csv(const char *message) {
    FILE *csv_file = fopen("moisture_log.csv", "a");
    if (!csv_file) {
        perror("Failed to open CSV file for writing");
        return;
    }

    fprintf(csv_file, "%s\n", message);
    fclose(csv_file);
}

// Function to cleanup resources
void cleanup() {
    fclose(csv_file); // Assuming csv_file was opened in main or a function called from main

    // Close SPI device
    close(spi_fd);

    // Close GPIO line
    gpiod_close(GPIO_CE0);

    // Free resources
    spidev_close();
}

