#define SENSOR_PIN 0
#define GPIO17 17
#define GPIO8 8
#define GPIO11 11
#define GPIO10 10
#define GPIO9 9

#define CURRENT_THRESHOLD 10.0
#define SENSITIVITY 0.1
#define OFFSET 0.05

volatile sig_atomic_t shutdown_requested = 0;

void handle_signal(int signum) {
    shutdown_requested = 1;
}

int main() {
    struct gpiod_dir gpio_dir;
    struct gpiod_cdt gpio_cdt;
    int spi_fd;
    int adc_value;
    float current;
    char buffer[256];
    FILE *current_log = fopen("current_log.csv", "a+");
    time_t now;
    char timestamp[50];

    if (current_log == NULL) {
        perror("Failed to open current_log.csv");
        exit(EXIT_FAILURE);
    }

    if (gpiod_cdt_open(&gpio_cdt, GPIO8) < 0) {
        perror("Failed to open GPIO8");
        fclose(current_log);
        exit(EXIT_FAILURE);
    }

    gpio_dir.direction = GPIOD_OUT_INIT_LOW;
    if (gpiod_set_data_dir(&gpio_cdt, &gpio_dir) < 0) {
        perror("Failed to set GPIO8 direction");
        gpiod_cdt_close(&gpio_cdt);
        fclose(current_log);
        exit(EXIT_FAILURE);
    }

    if (gpiod_set_value(&gpio_cdt, GPIO8, 0) < 0) {
        perror("Failed to set GPIO8 to LOW");
        gpiod_cdt_close(&gpio_cdt);
        fclose(current_log);
        exit(EXIT_FAILURE);
    }

    if ((spi_fd = open(MCP3008_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open SPI device");
        gpiod_cdt_close(&gpio_cdt);
        fclose(current_log);
        exit(EXIT_FAILURE);
    }

    while (!shutdown_requested) {
        // Set SPI chip select pin to HIGH
        if (gpiod_set_value(&gpio_cdt, GPIO8, 1) < 0) {
            perror("Failed to set GPIO8 to HIGH");
            close(spi_fd);
            gpiod_cdt_close(&gpio_cdt);
            fclose(current_log);
            exit(EXIT_FAILURE);
        }

        // Configure SPI device
        spidev_setup(TX_ADDR, RX_ADDR);

        // Send command to MCP3008 to read channel 0
        if (write(spi_fd, &SENSOR_CMD, sizeof(SENSOR_CMD)) != sizeof(SENSOR_CMD)) {
            perror("Failed to write to MCP3008");
            continue; // Retry up to 3 times
        }

        // Read ADC value
        if (read(spi_fd, &adc_value, sizeof(uint16_t)) != sizeof(uint16_t)) {
            if (errno == EINTR) {
                // Handle EINTR (interrupted system call)
                continue;
            } else {
                perror("Failed to read from MCP3008");
                break; // Exit loop after 3 failures
            }
        }

        // Convert ADC value to voltage
        float voltage = (adc_value / 1023.0) * 3.3;

        // Convert voltage to current
        current = (voltage - OFFSET) / SENSITIVITY;

        // Format timestamp and current reading
        time(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &now);
        sprintf(buffer, "%s,%f", timestamp, current);

        // Write to file
        if (fwrite(buffer, 1, strlen(buffer), current_log) != 1) {
            perror("Failed to write to current_log.csv");
            break; // Exit loop on file I/O error
        }

        // Check for overcurrent
        if (current > CURRENT_THRESHOLD) {
            // Drive GPIO17 LOW to disable the motor
            if (gpiod_set_value(&gpio_cdt, GPIO17, 0) < 0) {
                perror("Failed to set GPIO17 to LOW");
                break; // Exit loop on error
            }

            // Log the overcurrent event
            fprintf(current_log, "Overcurrent detected at %s\n", timestamp);

            // Wait for 1 second
            sleep(1);

            // Drive GPIO17 HIGH to re-enable the motor
            if (gpiod_set_value(&gpio_cdt, GPIO17, 1) < 0) {
                perror("Failed to set GPIO17 to HIGH");
                break; // Exit loop on error
            }

            // Log re-enabling the motor
            fprintf(current_log, "Motor re-enabled after %s\n", timestamp);
        }

        // Ensure graceful shutdown on SIGINT or SIGTERM
        if (shutdown_requested) {
            break;
        }
    }

    // Close SPI device and GPIO
    close(spi_fd);
    gpiod_cdt_close(&gpio_cdt);

    // Close current_log file
    fclose(current_log);

    // Clean up and exit
    printf("Shutdown requested. Exiting gracefully...\n");
    exit(EXIT_SUCCESS);
}

