void writePressureToLog(uint16_t pressure_kPa);
void handlePigpioError(int error);
void handleInterruptSignal(int signum);

int main() {
    // Initialize pigpio
    if (gpioInitialise(PIGPIO_DEFAULT_GPIO_MODE, PIGPIO_DEFAULT_SPEED) == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpioError());
        return EXIT_FAILURE;
    }

    // Open pressure log file
    openPressureLog();

    // SIGINT/SIGTERM handler
    signal(SIGINT, handleInterruptSignal);
    signal(SIGTERM, handleInterruptSignal);

    while (1) {
        uint16_t pressure_kPa;

        // Attempt to read pressure
        if (pigpioI2CReadData(PIGPIO_I2C_0, SENSOR_ADDRESS, PRESSURE_REGISTER, 2, &pressure_kPa, 1) == -1) {
            handlePigpioError(pigpioError());
            continue;
        }

        // Convert pressure to kPa
        pressure_kPa = (pressure_kPa / 65535.0) * 500.0;

        // Write to log file
        writePressureToLog(pressure_kPa);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up on exit
    closePressureLog();

    return EXIT_SUCCESS;
}

// Function to open the pressure log file
void openPressureLog() {
    pressure_log_file = fopen("pressure_log.csv", "a");
    if (!pressure_log_file) {
        fprintf(stderr, "Failed to open pressure log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Write header row
    if (fprintf(pressure_log_file, "%s,%f\n", "timestamp", 0.0) == -1) {
        fclose(pressure_log_file);
        fprintf(stderr, "Failed to write to pressure log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

// Function to write pressure to log file
void writePressureToLog(uint16_t pressure_kPa) {
    time_t now = time(NULL);
    char timestamp_str[50];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S.000Z", localtime(&now));

    if (fprintf(pressure_log_file, "%s,%f\n", timestamp_str, pressure_kPa) == -1) {
        fclose(pressure_log_file);
        fprintf(stderr, "Failed to write to pressure log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Flush and ensure data is written to file
    fflush(pressure_log_file);
}

// Handle pigpio errors
void handlePigpioError(int error) {
    fprintf(stderr, "Pigpio error: %s (Error code: %d)\n", pigpioErrorDesc(error), error);
}

