void handleInterruptSignal(int signum) {
    // Close I2C handle
    if (pigpioI2CClose(PIGPIO_I2C_0) == -1) {
        fprintf(stderr, "Failed to close I2C handle: %s\n", pigpioError());
    }

    // Flush and close the log file
    if (fclose(pressure_log_file) == -1) {
        fprintf(stderr, "Failed to close pressure log file: %s\n", strerror(errno));
    }

    // Terminate pigpio
    if (gpioTerminate() == -1) {
        fprintf(stderr, "Failed to terminate pigpio: %s\n", pigpioError());
    }
}

