#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pigpio.h>
#include <stdint.h>

#define MCP3008_CHANNEL 0
#define SPI_CLOCK_SPEED 1000000
#define SPI_MODE 0
#define GPIO27 27

// MCP3008 SPI configuration
#define SPI_CS GPIO8
#define SPI_SCLK GPIO11
#define SPI_MOSI GPIO10
#define SPI_MISO GPIO9

// Melexis MLX91209 parameters
#define MLX91209_VCC 3.3
#define MLX91209_ZERO_CURRENT_VOLTAGE (MLX91209_VCC / 2)
#define MLX91209_SENSITIVITY 66.0  // mV/A

// GPIO for safety monitor
#define GPIO_SHUTDOWN GPIO27

// Function prototypes
void setup_pigpio();
void setup_spi();
void read_adc(uint8_t channel);
void convert_adc_to_current(float adc_value);
void handle_overcurrent(float current);
void log_current(float current, const char *timestamp);
void cleanup();

int main() {
    srand(time(NULL));

    // Initialize pigpio
    setup_pigpio();

    // Setup SPI
    setup_spi();

    while (1) {
        // Sample ADC every 100ms
        uint16_t adc_value;
        read_adc(MCP3008_CHANNEL);
        float current = convert_adc_to_current(adc_value);

        // Check for overcurrent
        handle_overcurrent(current);

        // Log current with timestamp
        log_current(current, "Current: ");

        // Sleep for 100ms
        usleep(100000);
    }

    // Clean up on exit
    cleanup();

    return 0;
}

// Function: Setup pigpio
void setup_pigpio() {
    pigpio *pi = NULL;

    // Initialize pigpio
    if ((pi = pigpio_open()) == NULL) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }

    // Set GPIO27 as output for shutdown signal
    if (pigpio_direction(pi, GPIO27, PI_OUTPUT) == -1) {
        fprintf(stderr, "Failed to set GPIO27 as output\n");
        pigpio_close(pi);
        exit(EXIT_FAILURE);
    }

    // Set GPIO27 to LOW initially
    if (pigpio_write(pi, GPIO27, 0) == -1) {
        fprintf(stderr, "Failed to set GPIO27 LOW\n");
        pigpio_close(pi);
        exit(EXIT_FAILURE);
    }
}

// Function: Setup SPI
void setup_spi() {
    // Open SPI device
    if ((spi_device = pigpio_open_spi(SPI_CS, SPI_SCLK, SPI_MOSI, SPI_MISO, SPI_CLOCK_SPEED, SPI_MODE)) == NULL) {
        fprintf(stderr, "Failed to open SPI device\n");
        exit(EXIT_FAILURE);
    }

    // No need to close SPI explicitly as it will be handled in cleanup()
}

// Function: Read ADC value from MCP3008
void read_adc(uint8_t channel) {
    uint8_t command = 0x01 | (channel & 0x07); // Start bit + channel config

    // Send command to MCP3008
    if (pigpio_spi_transfer_blocking(spi_device, &command, 1) != 1) {
        fprintf(stderr, "SPI transfer failed\n");
        return;
    }

    // Read 2 bytes response (discard start bit)
    uint16_t adc_value = (pigpio_spi_transfer_blocking(spi_device, NULL, 2) << 8) | pigpio_spi_transfer_blocking(spi_device, NULL, 1);

    // Check for invalid ADC value (should be non-zero)
    if (adc_value == 0) {
        fprintf(stderr, "Invalid ADC value received\n");
        return;
    }
}

// Function: Convert ADC value to current
void convert_adc_to_current(float adc_value) {
    float voltage = adc_value * (MLX91209_VCC / 1024.0);
    float current = (voltage - MLX91209_ZERO_CURRENT_VOLTAGE) / MLX91209_SENSITIVITY;

    // Ensure current is not negative
    if (current < 0) {
        current = 0.0;
    }
}

// Function: Handle overcurrent
void handle_overcurrent(float current) {
    if (current > 10.0) {
        // Assert GPIO27 HIGH to trigger shutdown
        if (pigpio_write(pi, GPIO27, 1) == -1) {
            fprintf(stderr, "Failed to set GPIO27 HIGH\n");
        } else {
            fprintf(stderr, "OVERCURRENT detected, setting GPIO27 HIGH\n");
        }

        // Log the overcurrent event
        log_current(current, "OVERCURRENT");

        // Exit the program
        exit(EXIT_FAILURE);
    }
}

// Function: Log current with timestamp
void log_current(float current, const char *timestamp) {
    FILE *file = fopen("current_log.txt", "a+");
    if (!file) {
        fprintf(stderr, "Failed to open current_log.txt for append\n");
        return;
    }

    fprintf(file, "%s: %.2fA\n", timestamp, current);
    fclose(file);

    // Flush the buffer to ensure the log is written immediately
    fflush(file);
}

// Function: Cleanup resources
void cleanup() {
    // Close SPI device
    pigpio_close_spi(spi_device);

    // Close pigpio
    pigpio_close(pi);

    // Reset GPIO27 to LOW
    if (pigpio_write(pi, GPIO27, 0) == -1) {
        fprintf(stderr, "Failed to reset GPIO27 to LOW\n");
    }
}

