This C program uses the `pigpio` library to manage GPIO and SPI operations on a Raspberry Pi 4 Model B. It reads methane levels from a Honeywell MICROpeL Model 41000-020 Combustible Gas Sensor connected to an MCP3008 ADC via SPI. The program logs readings to `methane_log.txt` and alerts the user if the methane concentration exceeds 1000 PPM. It handles SIGINT and SIGTERM signals for graceful shutdown and includes comprehensive error handling for all critical operations.

code:
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <pigpio.h>
#include <stdint.h>

#define PIGPIO_IDR 0
#define PIGPIO_BASE 0x3F200000
#define ADS1115_I2C_ADDRESS 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONVERTDONE 0x00
#define ADS1115_REG SettlementTime 0x01
#define ADS1115_REG_CONFIG 0x02
#define ADS1115_REG_POWER_CTL 0x03
#define ADS1115_REG_GAIN 0x04
#define ADS1115_REG_OFFSET 0x05

// MLX90830 pressure sensor ratiometric parameters
#define MLX90830_OFFSET 0.5f  // 0.5V offset at 0 kPa
#define MLX90830_SENSITIVITY 0.1f // 0.1 V/kPa sensitivity

// ADC conversion result range
#define ADC_MAX_VALUE 65535

// Function prototypes
void init_pigpio();
void init_ads1115();
void read_pressure();
void convert_voltage_to_pressure(float voltage);
void log_pressure(float pressure, char* timestamp);
void cleanup();
void handle_signal(int signum);

int main() {
    // Initialize pigpio
    init_pigpio();

    // Initialize ADS1115
    init_ads1115();

    // Main loop
    while (1) {
        // Read pressure
        read_pressure();

        // Convert and log pressure
        float pressure = convert_voltage_to_pressure(ads1115_read(ADS1115_REG_DATA));
        log_pressure(pressure, ctime(&time(NULL)));

        // Sleep for 1 second
        usleep(1000000);
    }

    // Clean up resources
    cleanup();

    return 0;
}

// Function to initialize pigpio
void init_pigpio() {
    if (pigpio_init() == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }
}

// Function to initialize ADS1115
void init_ads1115() {
    int adc = pigpio_open(PIGPIO_IDR, 0);
    if (adc == -1) {
        fprintf(stderr, "Failed to open ADS1115 I2C: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }

    // Set ADS1115 configuration
    uint8_t config = ADS1115_CONFIG_16B;
    if (pigpio_write(adc, ADS1115_REG_CONFIG, (uint8_t)config) != 1) {
        fprintf(stderr, "Failed to configure ADS1115: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }

    // Set ADS1115 gain to 1 (full scale)
    if (pigpio_write(adc, ADS1115_REG_GAIN, 0x01) != 1) {
        fprintf(stderr, "Failed to set ADS1115 gain: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }

    // Set ADS1115 power control to active (start conversion)
    if (pigpio_write(adc, ADS1115_REG_POWER_CTL, 0x01) != 1) {
        fprintf(stderr, "Failed to power on ADS1115: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }
}

// Function to read pressure from MLX90830
void read_pressure() {
    float voltage;

    // Start conversion on ADS1115
    pigpio_write(adc, ADS1115_REG_CONVERTDONE, 0);

    // Wait for conversion to complete
    while (ads1115_read(ADS1115_REG_CONVERTDONE) != 0) {}

    // Read the converted value
    if (ads1115_read(ADS1115_REG_DATA) < 0) {
        fprintf(stderr, "Failed to read ADS1115 data: %s\n", pigpio_error());
        return;
    }

    voltage = (float)ads1115_read(ADS1115_REG_DATA) / ADC_MAX_VALUE * 3.3f; // Assuming 3.3V reference voltage

    // Apply offset and sensitivity to convert to pressure
    pressure = (voltage - MLX90830_OFFSET) * MLX90830_SENSITIVITY;
}

// Function to convert voltage to pressure
void convert_voltage_to_pressure(float voltage) {
    float pressure = (voltage - MLX90830_OFFSET) * MLX90830_SENSITIVITY;
    if (pressure < 0.0) pressure = 0.0; // Clamp pressure to non-negative
}

// Function to log pressure with ISO-8601 timestamp
void log_pressure(float pressure, char* timestamp) {
    char pressure_str[20];
    sprintf(pressure_str, "%f", pressure);
    FILE* file = fopen("pressure_log.txt", "a");
    if (file) {
        fprintf(file, "%s - %s\n", timestamp, pressure_str);
        fclose(file);
    } else {
        fprintf(stderr, "Failed to open or write to pressure_log.txt: %s\n", strerror(errno));
    }
}

// Function to cleanup resources
void cleanup() {
    // Stop ADS1115
    pigpio_write(adc, ADS1115_REG_POWER_CTL, 0);

    // Close ADS1115 I2C
    pigpio_close(adc);

    // Shutdown pigpio
    pigpio_shutdown();
}

// Function to handle signals (SIGINT)
void handle_signal(int signum) {
    // Graceful shutdown on SIGINT (Ctrl+C)
    cleanup();
    exit(EXIT_SUCCESS);
}

