// Function to read pressure from MLX90830
void read_pressure() {
    float voltage;

    // Start conversion on ADS1115
    pigpio_write(adc, ADS1115_REG_CONVERTDONE, 0);

    // Wait for conversion to complete
    while (ads1115_read(ADS1115_REG_CONVERTDONE) != 0) {}

    // Read the converted value
    if (ads1115_read(ADS1115_REG_DATA) < 0) {
        fprintf(stderr, "Failed to read ADS1115 data: %s\n", pigpio_error());
        return;
    }

    voltage = (float)ads1115_read(ADS1115_REG_DATA) / ADC_MAX_VALUE * 3.3f; // Assuming 3.3V reference voltage

    // Apply offset and sensitivity to convert to pressure
    pressure = (voltage - MLX90830_OFFSET) * MLX90830_SENSITIVITY;
}

// Function to convert voltage to pressure
void convert_voltage_to_pressure(float voltage) {
    float pressure = (voltage - MLX90830_OFFSET) * MLX90830_SENSITIVITY;
    if (pressure < 0.0) pressure = 0.0; // Clamp pressure to non-negative
}

// Function to log pressure with ISO-8601 timestamp
void log_pressure(float pressure, char* timestamp) {
    char pressure_str[20];
    sprintf(pressure_str, "%f", pressure);
    FILE* file = fopen("pressure_log.txt", "a");
    if (file) {
        fprintf(file, "%s - %s\n", timestamp, pressure_str);
        fclose(file);
    } else {
        fprintf(stderr, "Failed to open or write to pressure_log.txt: %s\n", strerror(errno));
    }
}

// Function to cleanup resources
void cleanup() {
    // Stop ADS1115
    pigpio_write(adc, ADS1115_REG_POWER_CTL, 0);

    // Close ADS1115 I2C
    pigpio_close(adc);

    // Shutdown pigpio
    pigpio_shutdown();
}

// Function to handle signals (SIGINT)
void handle_signal(int signum) {
    // Graceful shutdown on SIGINT (Ctrl+C)
    cleanup();
    exit(EXIT_SUCCESS);
}

