        exit(EXIT_FAILURE);
    }

    pigpioSetOverVoltage(0); // Disable over-voltage protection
}

// Function: setup_spi
void setup_spi() {
    int spi_fd;
    struct spi_ioc_transfer spi_transfer[] = {
        // MCP3208 configuration
        {
            .tx_buf = (unsigned char[]) { MCP3208_CS, 0x08 }, // Chip select, configuration register command
            .rx_buf = (unsigned char[2]) { 0, 0 }, // Expect no response
            .len = 2,
            .delay_usecs = 0
        },
        {
            .tx_buf = (unsigned char[]) { MCP3208_CS, 0x00 }, // Chip select, data register command
            .rx_buf = adc_data, // Store received data
            .len = 2,
            .delay_usecs = 0
        },
        // End of SPI transfer
        {
            .tx_buf = (unsigned char[]) { 0 }, // No transmission
            .rx_buf = (unsigned char[]) { 0 }, // No reception
            .len = 0,
            .delay_usecs = 5000 // Small delay
        }
    };

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd == -1) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (pigoWrite(SPI_CS, GPIO_ACTIVE_LOW) == -1) {
        fprintf(stderr, "Failed to set SPI CS pin: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }

    if (pigpioWrite(SPI_PORT, 0) == -1) {
        fprintf(stderr, "Failed to set SPI clock: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_PORT) == -1) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(sizeof(spi_transfer)), spi_transfer) == -1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    close(spi_fd);
}

// Function: read_humidity()
void read_humidity() {
    pigpioWrite(HUMIDITY_SENSOR_GPIO, GPIO_ACTIVE_LOW); // Activate HIH-4602-A
    usleep(10000); // Wait for stabilization

    pigpioWrite(HUMIDITY_SENSOR_GPIO, GPIO_ACTIVE_HIGH); // Deactivate HIH-4602-A

    adc_data[0] = pigpioIn(HUMIDITY_SENSOR_GPIO); // Read analog value

    // Convert ADC value to voltage
    float adc_voltage = (adc_data[0] * HIH4602_A_VCC) / 4096.0;

    // Calculate humidity using the HIH-4602-A transfer function
    humidity = (adc_voltage - HIH4602_A_VOUT_OFFSET) / HIH4602_A_SLOPE;
}

// Function: read_temperature()
void read_temperature() {
    pigpioWrite(TEMP_SENSOR_GPIO, GPIO_ACTIVE_LOW); // Activate thermistor

    // Read thermistor voltage
    adc_data[0] = pigpioIn(TEMP_SENSOR_GPIO);

    // Convert ADC value to voltage
    float adc_temperature_voltage = (adc_data[0] * HIH4602_A_VCC) / 4096.0;

    // Calculate resistance using the thermistor voltage divider equation
    float thermistor_resistance = R0 * ((HIH4602_A_VCC - adc_temperature_voltage) / HIH4602_A_VCC);

    // Calculate temperature using the thermistor Beta parameter equation
    float temperature_celsius = 1.0 / ((BETA / (273.15 + temperature_celsius)) + (log(thermistor_resistance / R0)) / (BETA * 273.15));

    // Convert to Fahrenheit if desired
    // temperature_fahrenheit = (temperature_celsius * 9/5) + 32;
}

