#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <gpiod.h>
#include <spidev.h>

#define VREF 3300  // VREF in mV
#define TMP36_OFFSET 500  // TMP36 output offset in mV
#define TMP36_SLOPE 10  // TMP36 temperature coefficient

#define MCP3208_CS 8  // GPIO8 for MCP3208 CS line
#define SPI_DEV "/dev/spidev0.0"
#define SPI_MODE 0  // SPI Mode 0
#define SPI_SPEED 1000000  // 1 MHz max speed

// Function prototypes
void init_resources();
void cleanup_resources();
int read_adc(int channel);
void write_to_csv(const char *timestamp, float temperature);
void handle_signals(int signum);

int main() {
    srand(time(NULL));

    // Initialize resources
    init_resources();

    // Main loop
    while (1) {
        // Read temperature
        int adc_value = read_adc(0);

        // Check if ADC reading is valid
        if (adc_value != 0) {
            float voltage = (adc_value / 4095.0) * VREF;
            float temperature_celsius = (voltage - TMP36_OFFSET) / TMP36_SLOPE;

            // Check if temperature is within valid range
            if (temperature_celsius >= -40.0 && temperature_celsius <= 125.0) {
                // Write to CSV file
                char timestamp[50];
                time_t now = time(NULL);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
                write_to_csv(timestamp, temperature_celsius);
            } else {
                // Handle out-of-range temperature
                printf("Temperature out of valid range (-40C to 125C)\n");
            }
        } else {
            // Handle invalid ADC reading
            printf("ADC reading failed\n");
        }

        // Sleep for 1 second
        usleep(1000000);
    }

    // Clean up resources
    cleanup_resources();

    return 0;
}

// Function to initialize resources
void init_resources() {
    // Initialize GPIO for MCP3208 CS line
    gpiod_set_data_direction(GPIO_NUM_TO_DEV(MCP3208_CS), GPIOD_DIR_OUT_INIT_LOW);
    gpiod_direction_output(GPIO_NUM_TO_DEV(MCP3208_CS), 1);

    // Open SPI device
    int spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd == -1) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    // Configure SPI device
    struct spi_device_config spi_config = {
        .speed_hz = SPI_SPEED,
        .mode = SPI_MODE,
        .bits_per_word = 8,
        .chip_select = 0,
    };

    if (spidev_setup_device(spi_fd, &spi_config) == -1) {
        perror("Failed to configure SPI device");
        exit(EXIT_FAILURE);
    }

    // Create or open CSV file for logging
    const char *csv_file = "temperature_log.csv";
    if (access(csv_file, F_OK) == -1) {
        // File does not exist, create it
        if (mkfifo(csv_file, 0666) == -1) {
            perror("Failed to create CSV file");
            exit(EXIT_FAILURE);
        }
    } else {
        // File exists, open it
        int csv_file_fd = open(csv_file, O_WRONLY | O_APPEND);
        if (csv_file_fd == -1) {
            perror("Failed to open CSV file for writing");
            exit(EXIT_FAILURE);
        }
    }
}

// Function to cleanup resources
void cleanup_resources() {
    // Close SPI device
    close(spi_fd);

    // Release GPIO line
    gpiod_set_data_direction(GPIO_NUM_TO_DEV(MCP3208_CS), GPIOD_DIR_UNINIT);
    gpiod_direction_input(GPIO_NUM_TO_DEV(MCP3208_CS));

    // Close CSV file
    close(csv_file_fd);
    remove(csv_file);
}

// Function to read ADC value from MCP3208
int read_adc(int channel) {
    struct spi_ioc_transfer transfers[] = {
        // Transfer: CS low, command, data in, CS high
        {
            .tx_buf = &channel,     // Command to read channel 0
            .rx_buf = NULL,          // No data expected
            .len = sizeof(channel), // Command length
            .cs_change = 1,          // Change CS
            .cs_high = 1,            // Set CS high after transfer
        },
        {
            .tx_buf = NULL,          // No transmit data
            .rx_buf = &adc_value,    // Store received data
            .len = sizeof(int),      // Data length
            .cs_change = 0,          // No CS change
            .cs_low = 1,             // Set CS low for transfer
        },
    };

    int ret = spidev_transfer(spi_fd, transfers, 2);

    if (ret != 2) {
        // Error occurred during SPI transfer
        perror("SPI transfer failed");
        return -1;
    }

    return adc_value;
}

// Function to write to CSV file
void write_to_csv(const char *timestamp, float temperature) {
    char line[256];
    sprintf(line, "%s,%f", timestamp, temperature);

    if (write(csv_file_fd, line, strlen(line)) != strlen(line)) {
        perror("Failed to write to CSV file");
        exit(EXIT_FAILURE);
    }
}

// Signal handler to gracefully close resources on SIGINT and SIGTERM
void handle_signals(int signum) {
    // Close resources
    cleanup_resources();

    // Forward signal to terminate the process
    if (signum == SIGINT || signum == SIGTERM) {
        _exit(EXIT_FAILURE);
    }
}

