#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_CS   8
#define SPI_MODE 0
#define SPI_SPEED 1000000

// Constants for ADXL335
#define ADXL335 sensitivity 300.0 // mV/g
#define ADXL335 zero_g_voltage 1650.0 // mV

// MCP3008 channel mapping to ADXL335 axes
#define MCP3008_X_CHANNEL 0
#define MCP3008_Y_CHANNEL 1
#define MCP3008_Z_CHANNEL 2

// Buffer size for SPI transfer
#define BUFFER_SIZE 16

// Function prototypes
void setup_pigpio();
void setup_spi();
void read_adc_values(int channel);
void compute_acceleration(float adc_values[], float *x, float *y, float *z);
void log_data(float x, float y, float z, char timestamp[20]);
void handle_impact(float x, float y, float z);
void cleanup();
void signal_handler(int signum);

int main() {
    // Initialize global variables
    FILE *impact_log = NULL;
    float x_acceleration = 0.0;
    float y_acceleration = 0.0;
    float z_acceleration = 0.0;
    char timestamp[20];

    // Signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Setup pigpio and SPI
    setup_pigpio();
    setup_spi();

    // Main loop
    while (1) {
        // Read ADC values
        read_adc_values(MCP3008_X_CHANNEL);
        read_adc_values(MCP3008_Y_CHANNEL);
        read_adc_values(MCP3008_Z_CHANNEL);

        // Compute acceleration magnitude
        compute_acceleration((float[]) {adc_values[MCP3008_X_CHANNEL], adc_values[MCP3008_Y_CHANNEL], adc_values[MCP3008_Z_CHANNEL]}, &x_acceleration, &y_acceleration, &z_acceleration);

        // Check for impact
        handle_impact(x_acceleration, y_acceleration, z_acceleration);

        // Log data
        log_data(x_acceleration, y_acceleration, z_acceleration, timestamp);

        // Sleep to maintain 100 Hz sampling rate
        usleep(100000);
    }

    // Clean up
    cleanup();

    return 0;
}

// Function: setup_pigpio
void setup_pigpio() {
    if (pigpio_init() == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }
}

// Function: setup_spi
void setup_spi() {
    if (pigpio_spi_open(0, SPI_MODE, SPI_SPEED) == -1) {
        fprintf(stderr, "Failed to open SPI: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }

    // Set CS pin as output
    if (pigpio_direction(GPIO_CS, PIGPIO_OUTPUT) == -1) {
        fprintf(stderr, "Failed to set CS pin as output: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }

    // Pull CS low
    if (pigpio_write(GPIO_CS, 0) == -1) {
        fprintf(stderr, "Failed to pull CS low: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }
}

// Function: read_adc_values
void read_adc_values(int channel) {
    char buffer[BUFFER_SIZE];
    int adc_value;

    // Set CS high
    if (pigpio_write(GPIO_CS, 1) == -1) {
        fprintf(stderr, "Failed to pull CS high: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }

    // Perform SPI transfer
    if (pigpio_spi_xfer(channel, buffer, BUFFER_SIZE) == -1) {
        fprintf(stderr, "SPI transfer failed: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }

    // Pull CS low again for next transfer
    if (pigpio_write(GPIO_CS, 0) == -1) {
        fprintf(stderr, "Failed to pull CS low: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }

    // Convert SPI data to ADC value
    adc_value = (buffer[0] << 8) | buffer[1];
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        exit(EXIT_FAILURE);
    }

    // Scale ADC value to voltage
    float adc_voltage = (adc_value / 1023.0) * 3300.0; // Assuming 3.3V reference voltage

    // Compute acceleration for ADXL335
    float acceleration = adc_voltage / ADXL335_sensitivity;
    if (acceleration < 0.0) {
        acceleration = 0.0;
    }

    printf("ADC value: %d, Voltage: %.3fV, Acceleration: %.3f g\n", adc_value, adc_voltage, acceleration);
}

// Function: compute_acceleration
void compute_acceleration(float adc_values[], float *x, float *y, float *z) {
    *x = adc_values[MCP3008_X_CHANNEL] * ADXL335_sensitivity;
    *y = adc_values[MCP3008_Y_CHANNEL] * ADXL335_sensitivity;
    *z = adc_values[MCP3008_Z_CHANNEL] * ADXL335_sensitivity;
}

// Function: log_data
void log_data(float x, float y, float z, char timestamp[20]) {
    char impact_detected[6];
    time_t now;
    struct tm timeinfo;
    char buffer[100];

    now = time(NULL);
    localtime_r(&now, &timeinfo);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    sprintf(buffer, "%s, X: %.3f g, Y: %.3f g, Z: %.3f g\n", timestamp, x, y, z);

    if (x * x + y * y + z * z > 2.0 * 9.81) {
        sprintf(impact_detected, "IMPACT DETECTED");
    } else {
        sprintf(impact_detected, "NO IMPACT");
    }

    if (impact_log == NULL) {
        impact_log = fopen("impact_log.txt", "a+");
        if (impact_log == NULL) {
            fprintf(stderr, "Failed to open impact log file: %s\n", strerror(errno));
            exit(EXIT_FAILURE);
        }
    }

    fprintf(impact_log, "%s%s", buffer, impact_detected);

    fflush(impact_log);
}

// Function: cleanup
void cleanup() {
    if (impact_log != NULL) {
        fclose(impact_log);
        impact_log = NULL;
    }

    // Close SPI
    pigpio_spi_close();

    // Close pigpio
    pigpio_cleanup();
}

// Signal handler for SIGINT
void signal_handler(int signum) {
    // Clean up on Ctrl+C
    cleanup();
}

