#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <stdint.h>

// Define the I2C bus and address for the Si1172 sensor
#define I2C_BUS 1
#define SI1172_ADDR 0x49

// Command register to trigger measurement
#define COMMAND_REG 0xC0

// FIFO/data registers for reading raw PPG samples
#define FIFO_REG 0xC1
#define IR_ADC_REG 0xC2
#define RED_ADC_REG 0xC3

// File path for logging data
#define LOG_FILE_PATH "biometric_log.csv"

// Function prototypes
void handleSIGINT(int signum);
int readSi1172(uint8_t command);
void writeToFifo(uint16_t value);
void readFromFifo(uint16_t *ir_value, uint16_t *red_value);
void logData(uint16_t hr, uint16_t spo2, int error_flag);
void cleanup();

int main() {
    // Initialize pigpio
    if (pigpioSetup() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpioError());
        return EXIT_FAILURE;
    }

    // Signal handler for Ctrl+C
    signal(SIGINT, handleSIGINT);

    // Open I2C bus
    if (i2cOpen(I2C_BUS) < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", i2cError());
        pigpioTerminate();
        return EXIT_FAILURE;
    }

    // Attempt to open the Si1172 sensor
    if (i2cOpenDevice(I2C_BUS, SI1172_ADDR) < 0) {
        fprintf(stderr, "Failed to open Si1172 sensor: %s\n", i2cError());
        i2cClose(I2C_BUS);
        pigpioTerminate();
        return EXIT_FAILURE;
    }

    // Header row for the CSV file
    const char *header = "Timestamp,HR(SPO2),Error";
    FILE *log_file = fopen(LOG_FILE_PATH, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cCloseDevice(I2C_BUS, SI1172_ADDR);
        pigpioTerminate();
        return EXIT_FAILURE;
    }
    fprintf(log_file, "%s,%d,%d,0\n", header, 0, 0);

    // Main loop
    while (1) {
        // Sample once per second
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        uint64_t timestamp = ts.tv_sec * 1000000ULL + ts.tv_nsec;

        // Write command to trigger measurement
        uint16_t command_value = COMMAND_REG;
        writeToFifo(command_value);

        // Wait for measurement to complete
        usleep(10000); // 10ms delay

        // Read raw PPG samples
        uint16_t ir_value, red_value;
        readFromFifo(&ir_value, &red_value);

        // Calculate proxy HR and SpO2 values (using raw ADC values)
        // Note: This is a placeholder and not a real conversion
        int hr_proxy = ir_value / 2; // Simplified proxy for HR
        int spo2_proxy = red_value / 2; // Simplified proxy for SpO2

        // Log data
        logData(hr_proxy, spo2_proxy, 0);

        // Flush the log file after each write
        fflush(log_file);

        // Handle Ctrl+C
        if (sigismember(SIGINT, signal(SIGINT))) {
            handleSIGINT(SIGINT);
        }
    }

    // Cleanup
    logData(0, 0, 2); // Log error on exit
    fclose(log_file);
    i2cCloseDevice(I2C_BUS, SI1172_ADDR);
    pigpioTerminate();

    return EXIT_SUCCESS;
}

// Function to handle SIGINT (Ctrl+C)
void handleSIGINT(int signum) {
    fprintf(stderr, "SIGINT received, terminating gracefully...\n");
    // Close I2C handle
    i2cClose(I2C_BUS);
    // Terminate pigpio
    pigpioTerminate();
}

// Function to write to the FIFO register
void writeToFifo(uint16_t value) {
    uint8_t command = 0xC0 | (value >> 8);
    uint8_t data = value & 0xFF;
    if (i2cWrite(I2C_BUS, SI1172_ADDR, COMMAND_REG, &command, 1) < 0) {
        fprintf(stderr, "Error writing to command register: %s\n", i2cError());
        return;
    }
    if (i2cWrite(I2C_BUS, SI1172_ADDR, FIFO_REG, &data, 1) < 0) {
        fprintf(stderr, "Error writing to FIFO register: %s\n", i2cError());
        return;
    }
}

// Function to read from FIFO/data registers
void readFromFifo(uint16_t *ir_value, uint16_t *red_value) {
    if (i2cRead(I2C_BUS, SI1172_ADDR, FIFO_REG, 2, ir_value, red_value, 1) < 0) {
        fprintf(stderr, "Error reading from FIFO register: %s\n", i2cError());
        return;
    }
}

// Function to log data to CSV file
void logData(uint16_t hr, uint16_t spo2, int error_flag) {
    char timestamp_str[20];
    time_t now = time(NULL);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(log_file, "%s,%d,%d,%d\n", timestamp_str, hr, spo2, error_flag);
}

// Cleanup function to close resources
void cleanup() {
    // No further cleanup needed beyond pigpioTerminate() and fclose()
}

