    if (rc < 0) {
        fprintf(stderr, "SPI transfer error: %s\n", strerror(errno));
        handle_spi_error();
        return -1;
    }

    adc_value = (xfer[1].rx_buf[0] << 8) | xfer[1].rx_buf[1];
    if (adc_value == 0 || adc_value == ADC_MAX_VALUE) {
