            perror("Failed to read from I2C sensor");
            continue; // Retry after 5 seconds
        }

        // Convert raw data to pressure and temperature
        float pressure, temperature;
        convert_raw_to_units(&data, &pressure, &temperature);

        // Log data to CSV file
        char csv_data[100];
        sprintf(csv_data, "%f,%f", temperature, pressure);
        log_data_to_csv(csv_data);

        // Display data on console
        printf("Temperature: %.2f°C, Pressure: %.2f Pa\n", temperature, pressure);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Close I2C device and CSV file on exit
    close(i2c_fd);
    close(STDOUT_FILENO); // Ensure CSV file is properly closed

    return 0;
}

// Function to initialize I2C
void init_i2c() {
    // Implementation details for initializing I2C would depend on the specific Raspberry Pi OS version and kernel configuration.
    // This function should configure the I2C bus and set the address.
    // For simplicity, assume initialization is done correctly here.
    printf("I2C initialized.\n");
}

// Function to open the I2C device
int open_i2c_device(const char *device_path) {
    int fd = open(device_path, O_RDWR);
    if (fd == -1) {
        perror("Failed to open I2C device");
        return -1;
    }
    return fd;
}

// Function to write to the I2C device
int i2c_write(int fd, uint16_t address, uint16_t data) {
    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Failed to change I2C slave address");
        return -1;
    }
    if (write(fd, &data, sizeof(uint16_t)) != sizeof(uint16_t)) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read from the I2C device
int i2c_read(int fd, uint16_t address, uint8_t *data, size_t len) {
    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Failed to change I2C slave address");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

// Function to convert raw ADC values to pressure and temperature
void convert_raw_to_units(SensorData *data, float *pressure, float *temperature) {
    // Extract raw data
    uint16_t pressure_raw = data->pressure_MSB << 8 | data->pressure_LSB;
    uint16_t temperature_raw = data->temperature_MSB << 8 | data->temperature_LSB;
    uint16_t crc = data->crc;

    // Check CRC for valid data
    if (crc != 0x1234) {
        printf("CRC error, data is invalid\n");
        return;
    }

    // Convert pressure
    *pressure = (pressure_raw * PRESSURE_COEFFICIENT) / 32768.0;

    // Convert temperature
    *temperature = (temperature_raw * TEMPERATURE_COEFFICIENT) / 32768.0;
}

// Function to log data to CSV file
void log_data_to_csv(const char *data) {
    FILE *csv_file = fopen("environmental_data.csv", "a");
    if (!csv_file) {
        perror("Failed to open CSV file");
        return;
    }
    fprintf(csv_file, "%s\n", data);
    fclose(csv_file);
}

// Signal handler for graceful shutdown
void handle_signals(int signum) {
    // Perform cleanup actions here, such as closing files and releasing resources
    // Example: close the I2C device and CSV file
    close(i2c_fd);
    fclose(STDOUT_FILENO); // Ensure CSV file is properly closed

    // Exit the program
    exit(EXIT_SUCCESS);
}
