#define MIC_COUNT 2
#define ADC_CHANNEL_COUNT 2
#define SPI0_CS GPIO8

// MCP3008 configuration
#define MCP3008_ADDR 0x7E

// Gain control constants
#define GAIN_MIN 1
#define GAIN_MAX 128

// Noise cancellation buffer size
#define BUFFER_SIZE (1024 * MIC_COUNT)

// Function prototypes
void init_pigpio();
void init_spi();
void read_mics(int gain);
void noise_cancellation(int *left_data, int *right_data, int *result_data, int size);
void cleanup();

int main(int argc, char **argv) {
    int gain = GAIN_MIN;
    int left_fd, right_fd, result_fd;
    int left_size, right_size, result_size;
    int left_data[BUFFER_SIZE], right_data[BUFFER_SIZE], result_data[BUFFER_SIZE];
    int left_index = 0, right_index = 0, result_index = 0;

    // Parse command-line arguments for gain
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--gain") == 0) {
            gain = atoi(argv[++i]);
            if (gain < GAIN_MIN || gain > GAIN_MAX) {
                fprintf(stderr, "Invalid gain value. Must be between %d and %d.\n", GAIN_MIN, GAIN_MAX);
                return 1;
            }
        }
    }

    // Initialize pigpio
    init_pigpio();

    // Initialize SPI
    init_spi();

    // Open SPI device files
    left_fd = open("/dev/spidev0.0", O_RDWR);
    if (left_fd == -1) {
        perror("Failed to open SPI device for left microphone");
        return 1;
    }

    right_fd = open("/dev/spidev0.0", O_RDWR);
    if (right_fd == -1) {
        perror("Failed to open SPI device for right microphone");
        close(left_fd);
        return 1;
    }

    // Read from microphones and perform noise cancellation
    while (1) {
        read_mics(gain);

        noise_cancellation(left_data, right_data, result_data, BUFFER_SIZE);

        // Output CSV data
        for (int i = 0; i < BUFFER_SIZE / 2; i++) {
            printf("%d,%d\n", result_data[result_index], i);
            result_index++;
        }

        // Handle SIGINT
        if (signal(SIGINT, SIG_IGN) == SIG_IGN) {
            // Ignore SIGINT for clean resource release
        }
    }

    // Cleanup
    cleanup();

    return 0;
}

// Function to initialize pigpio
void init_pigpio() {
    pigpio *pi = NULL;
    int error = pigpio_open(&pi);
    if (error != PI_ERROR_OK) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error_to_string(error));
        exit(1);
    }
    pigpio_set_mode(pi, pigpio_mode_headless); // Headless mode for simplicity
}

// Function to initialize SPI
void init_spi() {
    struct spi_i2c_dev *spi;
    int error = spi_i2c_dev_open(&spi, SPI0_CS, 1000000);
    if (error != 0) {
        fprintf(stderr, "Failed to initialize SPI: %s\n", strerror(errno));
        exit(1);
    }

    // Set MCP3008 address
    i2c_smbus_write_byte_data(spi, MCP3008_ADDR, 0x06); // Control register
    i2c_smbus_write_byte_data(spi, MCP3008_ADDR, 0x01); // Set channel to 0 (MISO on CH0)

    // Set SPI mode (MSB first, no clock polarity inversion, no clock phase inversion)
    error = spi_i2c_set_mode(spi, SPI_MODE_0);
    if (error != 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        exit(1);
    }

    // Enable SPI clock
    error = spi_i2c_set_speed(spi, 1000000);
    if (error != 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        exit(1);
    }
}

// Function to read from microphones with given gain
void read_mics(int gain) {
    int left_size, right_size;
    left_size = right_size = BUFFER_SIZE / 2;

    // Set gain
    pigpio_write(gain, PI_GPIO_P1, 0); // Assuming microphones are connected to GPIO pins 0 and 1

    // Read data from microphones
    for (int i = 0; i < left_size; i++) {
        left_data[left_index++] = pigpio_read(PI_GPIO_P1) / gain;
    }

    for (int i = 0; i < right_size; i++) {
        right_data[right_index++] = pigpio_read(PI_GPIO_P2) / gain;
    }
}

// Function to perform noise cancellation
void noise_cancellation(int *left_data, int *right_data, int *result_data, int size) {
    for (int i = 0; i < size; i++) {
        result_data[i] = left_data[i] - right_data[i];
    }
}

// Function to cleanup resources
void cleanup() {
    // Close SPI device files
    close(left_fd);
    close(right_fd);

    // Close SPI device
    spi_i2c_dev_close(spi);

    // Close pigpio
    pigpio_close(pi);
}

