#define BUZZER_GPIO 18
#define SPI_DEVICE "/dev/spidev0.0"
#define MCP3008_CHANNEL 0

#define MAX_RETRIES 3
#define SAMPLING_INTERVAL_MS 500

// Constants for MCP3008 configuration
#define MCP3008_MODE 0x00 // CPOL=0, CPHA=0
#define MCP3008_BITS 10
#define MCP3008_MAX_VALUE (1 << MCP3008_BITS)

// GPIO buzzer control
gpiod_device_t *buzzer_device;
gpiod_pin_t buzzer_pin;

// SPI device configuration
struct spi_device_config spi_config = {
    .bits_per_word = MCP3008_BITS,
    .max_speed_hz = 1000000, // 1 MHz
    .mode = MCP3008_MODE,
    .chip_select = 0,
};

// Function prototypes
void setup_buzzer();
void read_mcp3008(int channel, int *raw_adc);
void temperature_compensation(float voltage, float ambient_temp, float *compensated_voltage);
void log_reading(char *timestamp, int raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected);
void handle_interrupt_signal(int signum);

int main() {
    srand(time(NULL));

    // Initialize GPIO buzzer
    buzzer_device = gpiod_get_device_by_name(SPI_DEVICE);
    if (!buzzer_device) {
        fprintf(stderr, "Error: Could not find SPI device.\n");
        return EXIT_FAILURE;
    }
    buzzer_pin = gpiod_get_pin(buzzer_device, BUZZER_GPIO);
    if (gpiod_direction_output(buzzer_pin, 1)) {
        fprintf(stderr, "Error: Failed to configure GPIO %u as output.\n", BUZZER_GPIO);
        gpiod_release(buzzer_device);
        return EXIT_FAILURE;
    }

    // Open log file for writing
    FILE *log_file = fopen("flame_log.txt", "a+");
    if (!log_file) {
        fprintf(stderr, "Error: Could not open 'flame_log.txt' for writing.\n");
        return EXIT_FAILURE;
    }

    // Read ambient temperature from file
    FILE *ambient_temp_file = fopen("ambient_temp.txt", "r");
    if (!ambient_temp_file) {
        ambient_temp = 25.0;
    } else {
        char line[256];
        if (fgets(line, sizeof(line), ambient_temp_file) == NULL) {
            fclose(ambient_temp_file);
            ambient_temp = 25.0;
        } else {
            sscanf(line, "%f", &ambient_temp);
        }
        fclose(ambient_temp_file);
    }

    // Main loop
    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);

        int raw_adc;
        int retry_count = 0;
        do {
            retry_count++;
            if (retry_count > MAX_RETRIES) {
                fprintf(stderr, "Error: MCP3008 SPI transfer failed after %d retries.\n", MAX_RETRIES);
                break;
            }

            // Configure SPI device
            if (gpiod_spi_setup(&spi_config) < 0) {
                fprintf(stderr, "Error: Failed to configure SPI device.\n");
                break;
            }

            // Read ADC value
            if (read_mcp3008(MCP3008_CHANNEL, &raw_adc) < 0) {
                fprintf(stderr, "Error: Failed to read ADC value.\n");
                gpiod_spi_teardown();
                break;
            }

            // Check if ADC value is within range
            if (raw_adc < 0 || raw_adc > MCP3008_MAX_VALUE) {
                fprintf(stderr, "Warning: Received invalid ADC value %d. Retrying...\n", raw_adc);
                continue;
            }

            // Temperature compensation
            float voltage = (float)raw_adc / MCP3008_MAX_VALUE;
            float compensated_voltage = temperature_compensation(voltage, ambient_temp, &voltage);

            // Log the reading
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &ts);
            log_reading(timestamp, raw_adc, voltage, compensated_voltage, ambient_temp, (compensated_voltage > 1.0));

            // Buzzer control based on flame detection
            if (compensated_voltage > 1.0) {
                gpiod_set_value(buzzer_pin, 1); // Turn ON buzzer
            } else {
                gpiod_set_value(buzzer_pin, 0); // Turn OFF buzzer
            }
        } while (retry_count < MAX_RETRIES);

        // Handle SIGINT (Ctrl+C)
        if (signal(SIGINT, handle_interrupt_signal) == SIG_ERR) {
            fprintf(stderr, "Error: Could not install SIGINT handler.\n");
        }

        // Sleep for the interval
        usleep(SAMPLING_INTERVAL_MS * 1000);
    }

    // Clean up on exit
    log_reading("Exiting...", -1, -1.0, -1.0, ambient_temp, 0);
    fclose(log_file);
    gpiod_release(buzzer_device);
    gpiod_spi_teardown();

    return EXIT_SUCCESS;
}

// Function to read the MCP3008 ADC value
int read_mcp3008(int channel, int *raw_adc) {
    struct spi_message msg = SPI_MESSAGE_INIT();
    struct spi_transaction tx = SPI_TRANSACTION_INIT();
    int ret;

    // Set the chip select pin
    gpiod_set_value(gpiod_get_pin(buzzer_device, channel), 1);

    // Prepare the SPI message
    tx.command = 0; // Read command
    tx.data = 0; // Dummy byte
    tx.len = 3; // Start bit + 8 bits data + stop bit

    // Send the SPI message
    ret = gpiod_spi_transfer(&msg, &tx);
    if (ret < 0) {
        fprintf(stderr, "Error: SPI transfer failed.\n");
        return -1;
    }

    // Read the result
    *raw_adc = (tx.data[1] << 8) | tx.data[0];

    // Release the chip select pin
    gpiod_set_value(gpiod_get_pin(buzzer_device, channel), 0);

    return 0;
}

// Function to perform temperature compensation
void temperature_compensation(float voltage, float ambient_temp, float *compensated_voltage) {
    *compensated_voltage = voltage + (ambient_temp - 25.0) * 0.001;
}

// Signal handler for SIGINT (Ctrl+C)
void handle_interrupt_signal(int signum) {
    fprintf(stderr, "SIGINT received, terminating...\n");
    // Clean up and exit
    exit(0);
}

