#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <stdint.h>

#define MCP3008_CHANNEL 0
#define SPI_CLOCK_SPEED 1000000
#define GPIO17 17
#define WATER_LEVEL_THRESHOLD_LOW 70
#define WATER_LEVEL_THRESHOLD_HIGH 75

// Function prototypes
void initialize_pigpio_and_spi();
void read_mcp3008_value(uint8_t channel);
void handle_water_level(float water_level);
void write_json_entry(const char *timestamp, float water_level);
void cleanup();
void signal_handler(int signum);

int main() {
    // Initialize global variables
    FILE *json_file = NULL;
    pigpio *pi = NULL;
    uint8_t spi_transfer[3];
    float water_level = 0.0;

    // Signal handlers
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main program loop
    while (1) {
        // Attempt to initialize pigpio and SPI
        initialize_pigpio_and_spi();

        // Main loop logic
        if (pi == NULL) {
            fprintf(stderr, "Failed to initialize pigpio.\n");
            break;
        }

        // Read water level
        read_mcp3008_value(MCP3008_CHANNEL);

        // Handle water level based on threshold
        handle_water_level(water_level);

        // Write to JSON file
        write_json_entry(time(nullptr) ISO, water_level);

        // Sleep for 5 seconds
        usleep(5000000);

        // Check for signals and clean up
        if (pi != NULL) {
            cleanup();
        }
    }

    // Clean up resources
    if (json_file != NULL) {
        fclose(json_file);
    }
    if (pi != NULL) {
        pigpio_free(pi);
    }

    return 0;
}

// Function to initialize pigpio and SPI
void initialize_pigpio_and_spi() {
    // Initialize pigpio
    pi = pigpio_open();
    if (pi == NULL) {
        fprintf(stderr, "Failed to open pigpio.\n");
        return;
    }

    // Open SPI channel 0
    int spi_channel = 0;
    if (pigpio_spi_open(pi, SPI_CLOCK_SPEED, 0, &spi_channel) == 0) {
        fprintf(stderr, "Failed to open SPI channel.\n");
        pigpio_close(pi);
        pi = NULL;
        return;
    }

    // Set GPIO17 as output
    if (gpio_mode_set(pi, GPIO17, GPIO_OUTPUT_ON_HIGH) == -1) {
        fprintf(stderr, "Failed to set GPIO17 as output.\n");
        pigpio_spi_close(pi, spi_channel);
        pigpio_close(pi);
        pi = NULL;
        return;
    }
}

// Function to read the MCP3008 value
void read_mcp3008_value(uint8_t channel) {
    spi_transfer[0] = 0x01; // Start bit
    spi_transfer[1] = 0x80 | (channel << 4); // Command and channel
    spi_transfer[2] = 0x00; // Dummy byte

    int result = pigpio_spi_xfer(pi, spi_channel, spi_transfer, 3);

    if (result < 0) {
        pigpio_error("SPI transfer error: %s", pigpio_error_str());
        return;
    }

    // Parse the result
    uint16_t adc_value = ((spi_transfer[1] & 0x03) << 8) | spi_transfer[2];
    water_level = (float)adc_value / 1023.0 * 100.0;
}

// Function to handle water level based on thresholds
void handle_water_level(float water_level) {
    if (water_level > WATER_LEVEL_THRESHOLD_HIGH) {
        gpio_write(pi, GPIO17, 1); // Turn ON LED
    } else if (water_level < WATER_LEVEL_THRESHOLD_LOW) {
        gpio_write(pi, GPIO17, 0); // Turn OFF LED
    }
}

// Function to write a JSON entry to the file
void write_json_entry(const char *timestamp, float water_level) {
    char json_entry[] = "[{\"timestamp\": \""
                      "\"%s\", \"water_level\": %f}]";
    sprintf(json_entry, json_entry, timestamp, water_level);
    fprintf(json_file, "%s", json_entry);
    fflush(json_file);
}

// Function to clean up resources
void cleanup() {
    if (json_file != NULL) {
        fclose(json_file);
        json_file = NULL;
    }
    if (pi != NULL) {
        pigpio_close(pi);
        pi = NULL;
    }
}

// Signal handler function
void signal_handler(int signum) {
    // Clean up and exit
    cleanup();
    exit(0);
}

