#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <stdint.h>

#define SPI_CHANNEL 0
#define ADC_CHANNEL 0
#define MIN_RAW_VALUE 300
#define MAX_RAW_VALUE 700
#define MOISTURE_THRESHOLD 30
#define LOG_INTERVAL 60
#define EMAIL_RECIPIENT "you@example.com"
#define MSMTMP_CONFIG_PATH "/path/to/msmtprc"

// Function prototypes
void setup_pigpio();
void setup_spi();
void read_adc(uint16_t channel);
void calibrate_values(uint16_t *min_raw, uint16_t *max_raw);
void log_moisture(float moisture_percent);
void send_email_alert();
void handle_signals(int signum);
void cleanup();

int main(int argc, char **argv) {
    // Check command-line arguments
    if (argc != 9) {
        fprintf(stderr, "Usage: %s <spi_channel> <adc_channel> <min_raw> <max_raw> <moisture_threshold> <log_interval> <email_recipient> <msmtp_config_path>\n", argv[0]);
        return 1;
    }

    // Variables
    uint16_t min_raw_value, max_raw_value;
    float moisture_percent;
    int spi_channel = atoi(argv[1]);
    int adc_channel = atoi(argv[2]);
    char *email_recipient_str = argv[6];
    char *msmtp_config_path_str = argv[8];

    // Initialize pigpio
    setup_pigpio();

    // Setup SPI
    setup_spi(spi_channel, ADC_CHANNEL);

    // Calibrate raw values
    calibrate_values(&min_raw_value, &max_raw_value);

    // Main loop
    while (1) {
        // Read ADC value
        uint16_t raw_value = read_adc(adc_channel);

        // Calibrate and calculate moisture percentage
        moisture_percent = (float)raw_value / (float)max_raw_value * 100.0f - 100.0f;
        moisture_percent = moisture_percent > MOISTURE_THRESHOLD ? MOISTURE_THRESHOLD : moisture_percent;

        // Log moisture
        log_moisture(moisture_percent);

        // Check if moisture is below threshold and send email
        if (moisture_percent < MOISTURE_THRESHOLD) {
            send_email_alert();
        }

        // Sleep for the specified interval
        usleep(LOG_INTERVAL * 1000000);
    }

    // Clean up on SIGINT or SIGTERM
    handle_signals(SIGINT);
    handle_signals(SIGTERM);

    // Cleanup
    cleanup();

    return 0;
}

// Function to setup pigpio
void setup_pigpio() {
    pigpio *pi = NULL;
    int rc;

    // Initialize pigpio
    rc = pigpio_init();
    if (rc == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error());
        return;
    }

    pi = pigpio_new();
    if (pi == NULL) {
        fprintf(stderr, "Failed to create pigpio instance: %s\n", pigpio_error());
        pigpio_free(pi);
        pigpio_exit();
        return;
    }

    // Set GPIO mode to allow SPI
    rc = pigpio_set_mode(7, PIGPIO_OUTPUT);
    if (rc == -1) {
        fprintf(stderr, "Failed to set GPIO mode: %s\n", pigpio_error());
        pigpio_free(pi);
        pigpio_exit();
        return;
    }
}

// Function to setup SPI
void setup_spi(int spi_channel, int adc_channel) {
    int fd;
    struct spi_i2c_dev *spi_dev;
    struct spi_message *message;
    struct spi_transfer *transfer;

    // Open SPI device
    fd = open("/dev/spidev0.0", O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        return;
    }

    // Create SPI device structure
    spi_dev = (struct spi_i2c_dev *)malloc(sizeof(struct spi_i2c_dev));
    if (spi_dev == NULL) {
        fprintf(stderr, "Failed to allocate SPI device structure: %s\n", strerror(errno));
        close(fd);
        return;
    }

    // Initialize SPI device structure
    spi_dev->max_speed_hz = 500000; // 500 kHz
    spi_dev->bits_per_word = 8;
    spi_dev->mode = SPI_MODE_0; // Single-ended
    spi_dev->chip_select = spi_channel;
    spi_dev->speed = 500000;

    // Open SPI device
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &spi_dev->max_speed_hz) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        free(spi_dev);
        close(fd);
        return;
    }

    // Create SPI message and transfer
    message = spi_message_new();
    transfer = spi_transfer_new();
    transfer->tx_buf = (unsigned char *) &adc_channel; // Channel 0
    transfer->len = 1;

    // Send SPI transaction
    if (spi_message_send(message) < 0) {
        fprintf(stderr, "Failed to send SPI transaction: %s\n", strerror(errno));
        free(spi_message_get_message(message));
        free(transfer);
        spi_message_free(message);
        free(spi_dev);
        close(fd);
        return;
    }

    // Free resources
    spi_message_free(message);
    free(transfer);
    free(spi_dev);
    close(fd);
}

// Function to read ADC value
uint16_t read_adc(int channel) {
    uint16_t raw_value;

    // Send SPI transaction to read ADC value
    setup_spi(SPI_CHANNEL, channel);
    if (spi_message_send(spi_message_new()) < 0) {
        fprintf(stderr, "Failed to send SPI transaction for ADC read: %s\n", strerror(errno));
        return 0; // Return 0 on error
    }

    // Read result
    raw_value = spi_transfer_read(0, 1); // Read 1 byte (8 bits)

    // Clean up SPI
    cleanup_spi();

    return raw_value;
}

// Function to calibrate raw values
void calibrate_values(uint16_t *min_raw, uint16_t *max_raw) {
    *min_raw = MIN_RAW_VALUE;
    *max_raw = MAX_RAW_VALUE;
}

// Function to log moisture
void log_moisture(float moisture_percent) {
    char timestamp[50];
    char line[256];

    // Format timestamp
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Build log line
    sprintf(line, "%s, %f, ", timestamp, moisture_percent);

    // Append to plant_data.txt
    FILE *file = fopen("plant_data.txt", "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open plant_data.txt for append: %s\n", strerror(errno));
        return;
    }
    fprintf(file, "%s\n", line);
    fclose(file);
}

// Function to send email alert
void send_email_alert() {
    char email_body[256];
    char command[256];
    int email_fd, status;

    // Construct email body
    sprintf(email_body, "Moisture level dropped below %d%% threshold at %s", MOISTURE_THRESHOLD, time(NULL));

    // Execute msmtp with email body
    command[0] = '\0';
    strcat(command, "echo ");
    strcat(command, email_body);
    strcat(command, " | msmtp --config-file=" QUOTE(msmtp_config_path_str) QUOTE(" -a \"from=Alert <alert@example.com>\"");

    // Execute the command and check status
    email_fd = popen(command, "r");
    if (email_fd == -1) {
        fprintf(stderr, "Failed to execute email command: %s\n", strerror(errno));
        return;
    }

    // Read msmtp exit status
    status = pclose(email_fd);
    if (status != 0) {
        fprintf(stderr, "Email sending failed with status %d\n", status);
    }
}

// Function to handle signals
void handle_signals(int signum) {
    // Clean up on SIGINT or SIGTERM
    cleanup();
    exit(0);
}

// Function to cleanup resources
void cleanup() {
    if (pi != NULL) {
        pigpio_free(pi);
        pi = NULL;
    }

    // Close SPI device if open
    if (fd != -1) {
        close(fd);
        fd = -1;
    }

    // Free memory
    free(spi_dev);
}

// Ensure proper compilation and usage
int main(int argc, char **argv) {
    // ... (Main function body as provided above)

    return 0;
}

