#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <stdint.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_CLOCK_SPEED 1000000
#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define GPIO8 18

// GPIO pin for MCP3008 CE0 (active low)
#define CE_PIN 18

// Function prototypes
void spiSetup();
int spiTransfer(uint8_t address, uint8_t mode, uint16_t data);
void handleInterrupts();
void logSample(float value, char *timestamp);
void cleanup();

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <sample_rate_ms>\n", argv[0]);
        return 1;
    }

    // Parse sample rate from command line
    int sampleRateMs = atoi(argv[1]);

    // Initialize pigpio
    pigpio *pi = NULL;
    if (pigpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error());
        return 1;
    }
    pi->set_mode(pigpio::GPIO_MODE_INPUT, GPIO8); // Set GPIO8 as input for CE

    // Setup SPI
    spiSetup();

    // Open SPI device
    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd == -1) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        return 1;
    }

    // SIGINT/SIGTERM handler
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        uint16_t adcValue;
        time_t now = time(NULL);
        char timestamp[50];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));

        // Read ADC value
        if (spiTransfer(MCP3008_COMMAND, SPI_MODE, 0x00) < 0) {
            fprintf(stderr, "SPI transfer error.\n");
            continue;
        }

        adcValue = spiTransfer(MCP3008_READ_DATA, SPI_MODE, 0); // Read from channel 0

        // Calculate moisture percentage
        float moisturePercentage = (adcValue / 1023.0) * 100.0f;

        // Log the sample
        logSample(moisturePercentage, timestamp);

        usleep(sampleRateMs * 1000); // Sleep for the configured sample rate
    }

    return 0;
}

// Function to setup SPI
void spiSetup() {
    struct spi_ioc_transfer xfer[2];
    xfer[0].tx_buf = (unsigned long)&MCP3008_COMMAND;
    xfer[0].len = sizeof(MCP3008_COMMAND);
    xfer[0].speed_hz = SPI_CLOCK_SPEED;
    xfer[0].bits_per_word = 8;
    xfer[0].cs_change = 1;
    xfer[0].delay_usecs = 0;

    xfer[1].tx_buf = (unsigned long)&0; // No transmit data for read
    xfer[1].len = 0;
    xfer[1].speed_hz = SPI_CLOCK_SPEED;
    xfer[1].bits_per_word = 8;
    xfer[1].cs_change = 1;
    xfer[1].delay_usecs = 0;

    xfer[0].ce_high = 0; // CE0 is active low
    xfer[1].ce_high = 0;

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd == -1) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        return;
    }

    // Transfer configuration
    if (write(spi_fd, xfer, sizeof(xfer)) != sizeof(xfer)) {
        fprintf(stderr, "SPI transfer setup failed: %s\n", strerror(errno));
        close(spi_fd);
        return;
    }
}

// Function to perform SPI transfer
int spiTransfer(uint8_t address, uint8_t mode, uint16_t data) {
    struct spi_ioc_transfer xfer[2];
    xfer[0].tx_buf = (unsigned long)&address;
    xfer[0].len = sizeof(address);
    xfer[0].speed_hz = SPI_CLOCK_SPEED;
    xfer[0].bits_per_word = 8;
    xfer[0].cs_change = 1;
    xfer[0].delay_usecs = 0;

    xfer[1].tx_buf = (unsigned long)&data;
    xfer[1].len = sizeof(data);
    xfer[1].speed_hz = SPI_CLOCK_SPEED;
    xfer[1].bits_per_word = 8;
    xfer[1].cs_change = 1;
    xfer[1].delay_usecs = 0;

    xfer[0].ce_high = 0; // CE0 is active low
    xfer[1].ce_high = 0;

    int ret = write(spi_fd, xfer, sizeof(xfer));
    if (ret != sizeof(xfer)) {
        fprintf(stderr, "SPI transfer error: %d\n", ret);
        return -1;
    }

    return ret == sizeof(xfer);
}

// SIGINT/SIGTERM handler
void cleanup() {
    // Close SPI device
    close(spi_fd);

    // Flush and close the log file
    FILE *logFile = fopen("soil_moisture.log", "a+");
    if (logFile) {
        fprintf(logFile, "Closing log file.\n");
        fclose(logFile);
    }

    // Call gpioTerminate() to clean up pigpio resources
    if (pi) {
        gpioTerminate(pi);
        pi = NULL;
    }

    fprintf(stderr, "Exiting cleanly...\n");
}

// Function to log a sample
void logSample(float value, char *timestamp) {
    char buffer[256];
    sprintf(buffer, "%s: ADC Value: %d, Moisture Percentage: %.1f%%", timestamp, (int)adcValue, value);
    fprintf(stderr, "%s", buffer);
    fflush(stderr);
}

