#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>
#include <stdint.h>

// Define GPIO pins for SPI communication
#define CE0_GPIO_NUM 8
#define MOSI_GPIO_NUM 10
#define MISO_GPIO_NUM 9
#define SCLK_GPIO_NUM 11

// MCP3008 SPI configuration
#define MCP3008_SPI_DEVICE "/dev/spidev0.0"
#define MCP3008_SPI_SPEED 1000000
#define MCP3008_CMD_SINGLE_ENDED 0x01

// Calibration values for moisture percentage
#define DRY_ADC_VALUE 700
#define WET_ADC_VALUE 300

// Moisture percentage thresholds
#define MIN_PERCENTAGE 0
#define MAX_PERCENTAGE 100

// Function prototypes
void setup_spi();
int read_adc(uint8_t channel);
void calculate_moisture(uint16_t adc_value);
void handle_signal(int signum);

int main() {
    // Initialize signal handlers for SIGINT and SIGTERM
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Setup SPI communication
    setup_spi();

    // Main loop
    while (1) {
        // Read ADC value every 5 seconds
        struct timespec timeout = { .tv_sec = 5, .tv_nsec = 0 };
        uint16_t adc_value;

        if (nanosleep(&timeout, NULL) == -1) {
            perror("nanosleep");
            exit(EXIT_FAILURE);
        }

        adc_value = read_adc(0); // Read from channel 0

        calculate_moisture(adc_value); // Calculate moisture percentage

        printf("Raw ADC Value: %hu\n", adc_value);
        printf("Moisture Percentage: %.1f%%\n", (float)adc_value / 1023 * 100);

        // Sleep for 1 second before next reading
        usleep(1000000);
    }

    // Clean up on exit
    return 0;
}

// Function to setup SPI communication using libgpiod
void setup_spi() {
    // Open SPI device
    int spi_fd = open(MCP3008_SPI_DEVICE, O_RDWR);
    if (spi_fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    // Configure SPI device
    if (ioctl(spi_fd, GPIOD_IOCTL_SPI_CONFIG, GPIOD_SPI_CONFIG_MODE_0 |
                                   GPIOD_SPI_CONFIG_SPEED(MCP3008_SPI_SPEED) |
                                   GPIOD_SPI_CONFIG_CS_HIGH) < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    // Set GPIO pins for SPI communication
    gpiod_set_data_direction(MOSI_GPIO_NUM, GPIOD_DIR_OUT);
    gpiod_set_data_direction(MISO_GPIO_NUM, GPIOD_DIR_IN);
    gpiod_set_data_direction(SCLK_GPIO_NUM, GPIOD_DIR_OUT);
    gpiod_set_data_direction(CE0_GPIO_NUM, GPIOD_DIR_OUT);

    // Enable GPIO pins for SPI
    gpiod_enable_output(MOSI_GPIO_NUM);
    gpiod_enable_output(SCLK_GPIO_NUM);
    gpiod_enable_output(CE0_GPIO_NUM);
    gpiod_enable_input(MISO_GPIO_NUM);
}

// Function to read an ADC value from the MCP3008
int read_adc(uint8_t channel) {
    uint8_t cmd = (channel << 6) | MCP3008_CMD_SINGLE_ENDED;
    uint8_t buffer[3];

    // Write command to MCP3008
    if (write(spi_fd, &cmd, 1) != 1) {
        perror("write");
        return -1;
    }

    // Read data from MCP3008
    if (read(spi_fd, buffer, 3) != 3) {
        perror("read");
        return -1;
    }

    return (buffer[0] << 8) | buffer[1]; // Combine MSB and LSB
}

// Function to calculate moisture percentage from ADC value
void calculate_moisture(uint16_t adc_value) {
    if (adc_value < DRY_ADC_VALUE) {
        printf("Moisture level is too dry (%hu, below threshold)\n", adc_value);
        return;
    } else if (adc_value > WET_ADC_VALUE) {
        printf("Moisture level is too wet (%hu, above threshold)\n", adc_value);
        return;
    }

    // Calculate moisture percentage
    float moisture_percentage = (float)adc_value / 1023.0 * 100.0;

    printf("Moisture Percentage: %.1f%%\n", moisture_percentage);
}

// Signal handler to clean up on SIGINT/SIGTERM
void handle_signal(int signum) {
    // Close SPI device and release resources
    close(spi_fd);
    gpiod_disable_output(MOSI_GPIO_NUM);
    gpiod_disable_output(SCLK_GPIO_NUM);
    gpiod_disable_output(CE0_GPIO_NUM);
    gpiod_disable_input(MISO_GPIO_NUM);

    // Exit the program
    exit(EXIT_SUCCESS);
}

