#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <gpiod.h>
#include <stdint.h>

#define MCP3008_SPI_CS GPIO_NUM_8
#define MCP3008_SPI_SCLK GPIO_NUM_11
#define MCP3008_SPI_MOSI GPIO_NUM_10
#define MCP3008_SPI_MISO GPIO_NUM_9
#define ADC_CHANNEL 0

#define MIN_ADC_VALUE 300
#define MAX_ADC_VALUE 700

#define DELAY_MS 5000  // 5 seconds delay between readings

// Calibration constants for converting ADC value to moisture percentage
float convertADCtoMoisture(uint16_t adcValue) {
    return (adcValue - MIN_ADC_VALUE) / (MAX_ADC_VALUE - MIN_ADC_VALUE) * 100.0;
}

int main() {
    // Initialize GPIO for SPI
    int spi_fd[4];
    int ret;

    // Open GPIO pins for SPI
    ret = gpiod_open(MCP3008_SPI_CS, GPIOF_DIR_OUT);
    if (ret < 0) {
        fprintf(stderr, "Error opening GPIO %d: %s\n", MCP3008_SPI_CS, gpiod_error_string(ret));
        return EXIT_FAILURE;
    }

    ret = gpiod_open(MCP3008_SPI_SCLK, GPIOF_DIR_OUT);
    if (ret < 0) {
        fprintf(stderr, "Error opening GPIO %d: %s\n", MCP3008_SPI_SCLK, gpiod_error_string(ret));
        gpiod_close(MCP3008_SPI_CS);
        return EXIT_FAILURE;
    }

    ret = gpiod_open(MCP3008_SPI_MOSI, GPIOF_DIR_OUT);
    if (ret < 0) {
        fprintf(stderr, "Error opening GPIO %d: %s\n", MCP3008_SPI_MOSI, gpiod_error_string(ret));
        gpiod_close(MCP3008_SPI_CS);
        gpiod_close(MCP3008_SPI_SCLK);
        return EXIT_FAILURE;
    }

    ret = gpiod_open(MCP3008_SPI_MISO, GPIOF_DIR_IN);
    if (ret < 0) {
        fprintf(stderr, "Error opening GPIO %d: %s\n", MCP3008_SPI_MISO, gpiod_error_string(ret));
        gpiod_close(MCP3008_SPI_CS);
        gpiod_close(MCP3008_SPI_SCLK);
        gpiod_close(MCP3008_SPI_MOSI);
        return EXIT_FAILURE;
    }

    // Initialize SPI device
    ret = spi_bcm2835_setup(0, 1000000, SPI_MODE_0);
    if (ret < 0) {
        fprintf(stderr, "Error setting up SPI: %s\n", spi_bcm2835_get_error_string());
        gpiod_close(MCP3008_SPI_CS);
        gpiod_close(MCP3008_SPI_SCLK);
        gpiod_close(MCP3008_SPI_MOSI);
        gpiod_close(MCP3008_SPI_MISO);
        return EXIT_FAILURE;
    }

    // Open SPI device file
    ret = spidev_open(0, 0);
    if (ret < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", spidev_errstr(ret));
        spi_bcm2835_free();
        gpiod_close(MCP3008_SPI_CS);
        gpiod_close(MCP3008_SPI_SCLK);
        gpiod_close(MCP3008_SPI_MOSI);
        gpiod_close(MCP3008_SPI_MISO);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        uint16_t adcValue;
        time_t now = time(NULL);
        struct tm timeinfo;
        char buffer[80];

        // Read ADC value
        ret = spidev_read(spidev_fd, 1, &adcValue);
        if (ret < 0) {
            fprintf(stderr, "Error reading from SPI: %s\n", spidev_errstr(ret));
            break; // Exit on SPI error
        }

        // Convert ADC value to moisture percentage
        float moisturePercentage = convertADCtoMoisture(adcValue);

        // Format timestamp
        timeinfo = *localtime(&now);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", &timeinfo);

        // Log reading
        printf("Moisture: %.2f%% at %s\n", moisturePercentage, buffer);

        // Delay before next reading
        sleep(DELAY_MS);
    }

    // Clean up
    printf("Exiting...\n");

    // Close SPI device
    ret = spidev_close(spidev_fd);
    if (ret < 0) {
        fprintf(stderr, "Error closing SPI device: %s\n", spidev_errstr(ret));
    }

    // Close GPIO pins
    gpiod_close(MCP3008_SPI_CS);
    gpiod_close(MCP3008_SPI_SCLK);
    gpiod_close(MCP3008_SPI_MOSI);
    gpiod_close(MCP3008_SPI_MISO);

    // Free SPI configuration
    spi_bcm2835_free();

    return EXIT_SUCCESS;
}

