#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <stdint.h>
#include <inttypes.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define MCP3008_CHANNEL 0
#define SPI_MODE 0
#define SPI_SPEED_MHZ 1

#define SPI_CS_PIN 18 // GPIO CE0 for SPI0 on Raspberry Pi Zero W

// MCP3008 command for single-ended read, channel 0
#define MCP3008_CMD_SINGLE_ENDED 0x01

// Function prototypes
int spi_open();
int spi_config(int fd, uint8_t mode, uint32_t speed);
int spi_transfer(int fd, uint8_t* data, int len);
int close_spi_and_exit(int fd);

// Main function
int main() {
    // Signal handlers for SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = close_spi_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open SPI device
    int fd = spi_open(SPI_DEVICE);
    if (fd == -1) {
        perror("spi_open");
        return EXIT_FAILURE;
    }

    // Configure SPI
    if (spi_config(fd, SPI_MODE, SPI_SPEED_MHZ) == -1) {
        perror("spi_config");
        close(fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        uint8_t data;
        if (spi_transfer(fd, &MCP3008_CMD_SINGLE_ENDED, 1) == -1) {
            perror("spi_transfer");
            break;
        }

        // Read 10-bit value from MCP3008
        if (spi_transfer(fd, (uint8_t *)NULL, 3) == -1) {
            perror("spi_transfer");
            break;
        }

        // Extract the 10-bit value (least significant byte first)
        uint16_t adc_value = (uint16_t)((data & 0xFF) << 8) | (data >> 8);

        // Calculate moisture percentage (0-1023 range)
        float moisture_percentage = (adc_value / 1023.0) * 100.0;

        // Clamp to 0-100 range
        moisture_percentage = fminf(moisture_percentage, 100.0);

        // Print moisture percentage
        printf("Soil moisture percentage: %.2f%%\n", moisture_percentage);

        // Sleep for 5 seconds
        usleep(5000000);
    }

    // Close SPI device on exit
    close(fd);

    return EXIT_SUCCESS;
}

// Function to open SPI device
int spi_open(const char* device) {
    int fd;
    fd = open(device, O_RDWR);
    if (fd == -1) {
        perror("open");
        return -1;
    }
    return fd;
}

// Function to configure SPI settings
int spi_config(int fd, uint8_t mode, uint32_t speed) {
    struct spi_ioc_transfer xfer[2];

    xfer[0].tx_buf = (unsigned long)&MCP3008_CMD_SINGLE_ENDED;
    xfer[0].len = 1;
    xfer[0].speed_hz = speed * 1000000; // Convert MHz to Hz
    xfer[0].bits_per_word = 8;
    xfer[0].cs_change = 1;
    xfer[0].cs_low = 1;
    xfer[0].delay_usecs = 0;

    xfer[1].tx_buf = (unsigned long)NULL; // No data to send
    xfer[1].len = 3;
    xfer[1].speed_hz = speed * 1000000;
    xfer[1].bits_per_word = 8;
    xfer[1].cs_change = 1;
    xfer[1].cs_low = 0;
    xfer[1].delay_usecs = 0;

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1 || 
        ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1 ||
        ioctl(fd, SPI_IOC_MESSAGE(2), xfer) == -1) {
        perror("spi_config");
        return -1;
    }

    return 0;
}

// Function to perform SPI transfer
int spi_transfer(int fd, uint8_t* data, int len) {
    struct spi_ioc_transfer xfer[len + 1];

    xfer[0].tx_buf = (unsigned long)data;
    xfer[0].len = len;
    xfer[0].speed_hz = SPI_SPEED_MHZ * 1000000;
    xfer[0].bits_per_word = 8;
    xfer[0].cs_change = 0;
    xfer[0].cs_low = 1;
    xfer[0].delay_usecs = 0;

    for (int i = 1; i <= len; ++i) {
        xfer[i].tx_buf = (unsigned long)NULL;
        xfer[i].len = 0;
        xfer[i].speed_hz = SPI_SPEED_MHZ * 1000000;
        xfer[i].bits_per_word = 8;
        xfer[i].cs_change = 0;
        xfer[i].cs_low = 0;
        xfer[i].delay_usecs = 0;
    }

    if (ioctl(fd, SPI_IOC_MESSAGE(len + 1), xfer) == -1) {
        perror("spi_transfer");
        return -1;
    }

    return 0;
}

// Function to close SPI and exit
int close_spi_and_exit(int fd) {
    close(fd);
    exit(EXIT_SUCCESS);
}

