        // Extract the 10-bit value (least significant byte first)
        uint16_t adc_value = (uint16_t)((data & 0xFF) << 8) | (data >> 8);

        // Calculate moisture percentage (0-1023 range)
        float moisture_percentage = (adc_value / 1023.0) * 100.0;

        // Clamp to 0-100 range
        moisture_percentage = fminf(moisture_percentage, 100.0);

        // Print moisture percentage
        printf("Soil moisture percentage: %.2f%%\n", moisture_percentage);

        // Sleep for 5 seconds
        usleep(5000000);
    }

    // Close SPI device on exit
    close(fd);

    return EXIT_SUCCESS;
}

// Function to open SPI device
int spi_open(const char* device) {
    int fd;
    fd = open(device, O_RDWR);
    if (fd == -1) {
        perror("open");
        return -1;
    }
    return fd;
}

// Function to configure SPI settings
int spi_config(int fd, uint8_t mode, uint32_t speed) {
    struct spi_ioc_transfer xfer[2];

    xfer[0].tx_buf = (unsigned long)&MCP3008_CMD_SINGLE_ENDED;
    xfer[0].len = 1;
    xfer[0].speed_hz = speed * 1000000; // Convert MHz to Hz
    xfer[0].bits_per_word = 8;
    xfer[0].cs_change = 1;
    xfer[0].cs_low = 1;
    xfer[0].delay_usecs = 0;

    xfer[1].tx_buf = (unsigned long)NULL; // No data to send
    xfer[1].len = 3;
    xfer[1].speed_hz = speed * 1000000;
    xfer[1].bits_per_word = 8;
    xfer[1].cs_change = 1;
    xfer[1].cs_low = 0;
    xfer[1].delay_usecs = 0;

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1 || 
        ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1 ||
        ioctl(fd, SPI_IOC_MESSAGE(2), xfer) == -1) {
        perror("spi_config");
        return -1;
    }

    return 0;
}

// Function to perform SPI transfer
int spi_transfer(int fd, uint8_t* data, int len) {
    struct spi_ioc_transfer xfer[len + 1];

    xfer[0].tx_buf = (unsigned long)data;
    xfer[0].len = len;
    xfer[0].speed_hz = SPI_SPEED_MHZ * 1000000;
    xfer[0].bits_per_word = 8;
    xfer[0].cs_change = 0;
    xfer[0].cs_low = 1;
    xfer[0].delay_usecs = 0;

    for (int i = 1; i <= len; ++i) {
        xfer[i].tx_buf = (unsigned long)NULL;
        xfer[i].len = 0;
        xfer[i].speed_hz = SPI_SPEED_MHZ * 1000000;
        xfer[i].bits_per_word = 8;
        xfer[i].cs_change = 0;
        xfer[i].cs_low = 0;
        xfer[i].delay_usecs = 0;
    }

    if (ioctl(fd, SPI_IOC_MESSAGE(len + 1), xfer) == -1) {
        perror("spi_transfer");
        return -1;
    }

    return 0;
}

// Function to close SPI and exit
int close_spi_and_exit(int fd) {
    close(fd);
    exit(EXIT_SUCCESS);
}

