#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>
#include <gpiod.h>
#include <spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define MCP3008_ADDR 0x68
#define NUM_CHANNELS 4

#define VREF 3300  // Assuming VREF is 3.3V

// Function prototypes
void setup_spi();
void read_analog_values(int channel, float *voltages);
void handle_interrupts(int signum);
void cleanup();

int main() {
    srand(time(NULL));

    // Initialize GPIO for SPI chip select
    gpiod_set_data_direction(GPIO_NUM_TO_DEV(8), GPIOD_DIR_OUT_INIT_LOW);
    gpiod_write(GPIO_NUM_TO_LINE(8), 1);

    // Open SPI device
    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd == -1) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    // Setup SPI parameters
    setup_spi();

    // Main loop
    while (1) {
        // Sample and log data
        float voltages[NUM_CHANNELS];
        read_analog_values(0, voltages);
        write_to_csv("environmental_data.csv", voltages);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Clean up on exit
    handle_interrupts(SIGINT);
    handle_interrupts(SIGTERM);
    cleanup();

    return 0;
}

// Function to set up SPI parameters
void setup_spi() {
    struct spi_ioc_transfer transfers[NUM_CHANNELS];
    int rc;

    // Set up the SPI transfer configuration
    for (int i = 0; i < NUM_CHANNELS; i++) {
        transfers[i].tx_buf = (unsigned char *) &MCP3008_ADDR;
        transfers[i].rx_buf = NULL; // Single-ended mode, no receive data
        transfers[i].len = 1;
        transfers[i].delay_usecs = 0;
        transfers[i].speed_hz = 1000000; // 1 MHz
        transfers[i].cs_change = 1;
        transfers[i].cs_low = 1;
    }

    // Perform the SPI transactions
    rc = spidev Spi_IOC_WR_MODE | SPI_DEVICE; // Set mode to 0 (0 for Mode 0)
    if (rc < 0) {
        perror("Failed to set SPI mode");
        exit(EXIT_FAILURE);
    }

    // Send the transfers
    rc = spidev Spi_IOC_MIOC_DIO transfers, NUM_CHANNELS, 1000; // 1 ms timeout
    if (rc < 0) {
        perror("Failed to send SPI transactions");
        exit(EXIT_FAILURE);
    }
}

// Function to read analog values from MCP3008
void read_analog_values(int channel, float *voltages) {
    struct spi_ioc_transfer tx_transfer;
    unsigned char command;

    // Set up the transfer for the selected channel
    tx_transfer.tx_buf = (unsigned char *)&channel;
    tx_transfer.rx_buf = (unsigned char *)&command;
    tx_transfer.len = 1;
    tx_transfer.speed_hz = 1000000; // 1 MHz
    tx_transfer.delay_usecs = 0;
    tx_transfer.cs_change = 1;
    tx_transfer.cs_low = 1;

    // Perform the SPI transaction
    if (spidev Spi_IOC_Transfer(&tx_transfer, 1) < 0) {
        perror("Failed to read analog value");
        return;
    }

    // Calculate voltage from the 10-bit ADC value
    *voltages = (command * VREF) / 1024.0;
}

// Function to write data to CSV file
void write_to_csv(const char *filename, float *voltages) {
    FILE *file = fopen(filename, "a");
    if (!file) {
        perror("Failed to open CSV file");
        exit(EXIT_FAILURE);
    }

    // Write timestamp and voltages
    time_t now = time(NULL);
    struct tm timeinfo;
    localtime_r(&now, &timeinfo);
    char timestamp[50];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(file, "%s,%f\n", timestamp, voltages[0]);
    for (int i = 1; i < NUM_CHANNELS; i++) {
        fprintf(file, "%f,", voltages[i]);
    }
    fprintf(file, "\n");

    fclose(file);
}

// Signal handling function to ensure clean exit
void handle_interrupts(int signum) {
    // Clean up resources on SIGINT/SIGTERM
    cleanup();
    exit(EXIT_SUCCESS);
}

// Function to release resources and clean up
void cleanup() {
    // Close the SPI device
    close(spi_fd);

    // Release GPIO line
    gpiod_set_data_direction(GPIO_NUM_TO_DEV(8), GPIOD_DIR_INIT_NONE);
    gpiod_write(GPIO_NUM_TO_LINE(8), 0);

    // Close the CSV file
    fclose(NULL); // If file is NULL, it means fopen failed and there's nothing to close

    // No need to close libgpiod lines as they are automatically released on exit
}

