            log_event("Health warning: SpO2 < 95% or HR > 100 BPM at %s\n", ctime(&time(NULL)));
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up resources
    cleanup();

    return EXIT_SUCCESS;
}

// Helper functions

void init_pigpio() {
    pigpio *pi = NULL;
    if ((pi = pigpio_open(PIGPIO_ID)) == NULL) {
        fprintf(stderr, "Failed to open pigpio. Error: %s\n", pigpio_error());
        return;
    }

    // Set up I2C
    if (pigpio_i2c_setup(pi, MAX30102_I2C_ADDRESS) == -1) {
        fprintf(stderr, "Failed to set up I2C. Error: %s\n", pigpio_error());
        pigpio_close(pi);
