#define PIGPIO_ID 0  // Use the default pigpio ID

// MCP3008 SPI configuration
#define MCP3008_CS 18  // CE0 pin on Raspberry Pi Zero W
#define MCP3008_SPI_MODE 0  // SPI mode 0
#define MCP3008_SPI_SPEED 1000000  // 1 MHz
#define MCP3008_SPI_BUS 0  // SPI bus 0

// MCP3008 command and data structure
#define MCP3008_CMD_START 0x01
#define MCP3008_CMD_CONFIG (MCP3008_CMD_START << 4)  // Channel selection shifted left by 4

// Voltage reference (VREF) for MCP3008
#define VREF 3300  // 3.3V

// Function prototypes
void setup_pigpio();
void setup_spi();
void read_mcp3008(uint8_t channel);
void handle_spi_error(int error);
void write_to_csv(const char *timestamp, const char *channel, float voltage);
void cleanup();

// Main function
int main() {
    signal(SIGINT, cleanup);  // Handle Ctrl+C

    setup_pigpio();
    setup_spi();

    while (1) {
        // Read from MCP3008 every 500 ms
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        uint64_t timestamp = ts.tv_sec * 1000000 + ts.tv_nsec / 1000;

        char channel_str[3];
        float voltage;

        if (read_mcp3008(0) && read_mcp3008(1) && read_mcp3008(2)) {
            sprintf(channel_str, "%d", 0);  // Channel 0
            voltage = (read_mcp3008_r1() << 8) | read_mcp3008_r0() / VREF;
            write_to_csv(timestamp, channel_str, voltage);

            sprintf(channel_str, "%d", 1);  // Channel 1
            voltage = (read_mcp3008_r1() << 8) | read_mcp3008_r0() / VREF;
            write_to_csv(timestamp, channel_str, voltage);

            sprintf(channel_str, "%d", 2);  // Channel 2
            voltage = (read_mcp3008_r1() << 8) | read_mcp3008_r0() / VREF;
            write_to_csv(timestamp, channel_str, voltage);
        }

        usleep(500 * 1000);  // Wait 500 ms
    }

    return 0;
}

// Function to setup pigpio
void setup_pigpio() {
    if (pigpio_open(PIGPIO_ID, PIGPIO_WAIT_FOREVER) < 0) {
        fprintf(stderr, "Failed to open pigpio: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }
}

// Function to setup SPI
void setup_spi() {
    if (pigpio_spi_setup(MCP3008_CS, MCP3008_SPI_MODE, MCP3008_SPI_SPEED, MCP3008_SPI_BUS) < 0) {
        fprintf(stderr, "Failed to setup SPI: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }
}

// Function to read MCP3008
int read_mcp3008(uint8_t channel) {
    uint8_t cmd = MCP3008_CMD_START | (channel << 4);
    uint8_t rx_buf[3];

    if (pigpio_spi_transfer(1, &cmd, 1, rx_buf, 3) < 0) {
        handle_spi_error(pigpio_error());
        return 0;
    }

    // Assemble the 10-bit result
    uint16_t raw_value = (rx_buf[1] << 8) | rx_buf[2];

    return 1;
}

// Handle SPI communication errors
void handle_spi_error(int error) {
    fprintf(stderr, "SPI transfer error: %s\n", pigpio_error());
}

// Function to write to CSV file
void write_to_csv(const char *timestamp, const char *channel, float voltage) {
    FILE *file = fopen("analog_log.csv", "a");
    if (!file) {
        fprintf(stderr, "Failed to open or append to CSV file: %s\n", strerror(errno));
        return;
    }

    fprintf(file, "%s,%s,%f\n", timestamp, channel, voltage);
    fclose(file);
}

// Function to cleanup resources
void cleanup() {
    pigpio_close();
    fclose("analog_log.csv");  // Close the CSV file (assuming it was opened in setup or main)
}

