#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO and SPI constants
#define SPI0 0
#define CE0 8
#define ADC_CHANNEL 0
#define BUZZER_GPIO 24
#define THRESHOLD 500

// Function prototypes
void setup_pigpio();
void setup_spi();
void read_analog_value(int);
void control_buzzer(int value);
void cleanup();
void signal_handler(int signum);

int main() {
    // Initialize pigpio
    setup_pigpio();

    // Setup SPI and GPIO
    setup_spi();
    setup_buzzer();

    // Main loop
    while (1) {
        // Read analog value from MQ-2 sensor
        int value = read_analog_value(ADC_CHANNEL);

        // Control buzzer based on gas sensor value
        control_buzzer(value);

        // Sleep for 500 ms
        usleep(500 * 1000);
    }

    // Clean up on SIGINT
    signal(SIGINT, signal_handler);

    return 0;
}

// Function to setup pigpio
void setup_pigpio() {
    if (pigpioSetup() == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }
}

// Function to setup SPI and GPIO
void setup_spi() {
    if (pigpioSpiOpen(SPI0) == -1) {
        fprintf(stderr, "Failed to open SPI0: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }

    if (pigpioGpioMode(CE0, pigpioOUTPUT) == -1) {
        fprintf(stderr, "Failed to set CE0 as output: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }
}

// Function to read an analog value from the MQ-2 sensor
int read_analog_value(int channel) {
    int value = 0;

    if (pigpioSpiTransfer(0, SPI0, channel, 1, &value) == -1) {
        fprintf(stderr, "Failed to read analog value: %s\n", pigpioError());
        return -1;
    }

    return value;
}

// Function to control the buzzer based on the gas sensor value
void control_buzzer(int value) {
    if (value < THRESHOLD) {
        pigpioWrite(BUZZER_GPIO, 0); // Turn buzzer off
    } else {
        pigpioWrite(BUZZER_GPIO, 1); // Turn buzzer on
    }
}

// Function to cleanup SPI and GPIO resources
void cleanup() {
    pigpioSpiClose(SPI0);
    pigpioGpioSetMode(CE0, pigpioINPUT);
    gpioTerminate();
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signum) {
    cleanup();
    exit(EXIT_SUCCESS);
}

