#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <fcntl.h>
#include <unistd.h>
#include <gpiod.h>
#include <sys/spidev.h>

#define MCP3008_CS0_GPIO 8
#define MCP3008_CS1_GPIO 7
#define MCP3008_CS2_GPIO 25
#define MCP3008_MOSI_GPIO 10
#define MCP3008_MISO_GPIO 9
#define MCP3008_SCLK_GPIO 11
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define MCP3008_CHANNEL 0

int main() {
    // Initialize GPIO lines for chip selects
    gpiod_chip *cs0_chip = gpiod_get_chip(MCP3008_CS0_GPIO);
    gpiod_request_line(cs0_chip, GPIOD_OUT_HIGH);
    gpiod_request_line(cs0_chip, GPIOD_OUT_LOW);

    gpiod_chip *cs1_chip = gpiod_get_chip(MCP3008_CS1_GPIO);
    gpiod_request_line(cs1_chip, GPIOD_OUT_HIGH);
    gpiod_request_line(cs1_chip, GPIOD_OUT_LOW);

    gpiod_chip *cs2_chip = gpiod_get_chip(MCP3008_CS2_GPIO);
    gpiod_request_line(cs2_chip, GPIOD_OUT_HIGH);
    gpiod_request_line(cs2_chip, GPIOD_OUT_LOW);

    // Open SPI device
    int spi_fd = spidev_open(0, SPI_MODE);
    if (spi_fd == -1) {
        perror("spidev_open");
        exit(EXIT_FAILURE);
    }

    // Open file for writing CSV
    const char *filename = "soil_moisture_log.csv";
    int file_fd = fopen(filename, "a+");
    if (file_fd == -1) {
        perror("fopen");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Header if file is new
    if (fseek(file_fd, 0, SEEK_SET) == -1 || fprintf(file_fd, "timestamp,sensor1,sensor2,sensor3") == -1) {
        fclose(file_fd);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    fclose(file_fd);

    // Main loop
    while (1) {
        // Set chip selects
        gpiod_set_value(cs0_chip, GPIOD_LOW);
        gpiod_set_value(cs1_chip, GPIOD_LOW);
        gpiod_set_value(cs2_chip, GPIOD_LOW);

        // SPI transfer command [0x01, (0x08|0), 0x00]
        uint8_t command[3] = {0x01, (0x08 | MCP3008_CHANNEL), 0x00};
        int spi_transfer_result = write(spi_fd, command, 3);
        if (spi_transfer_result != 3) {
            fprintf(stderr, "Error writing to SPI: %d\n", spi_transfer_result);
            continue;
        }

        // Read data from MCP3008
        uint16_t adc_value;
        adc_value = (command[1] & 0x0f) << 8 | read(spi_fd, &command[2], 1);
        if (adc_value == 0) {
            fprintf(stderr, "Error reading from MCP3008: 0x%04x\n", adc_value);
            continue;
        }

        // Log data
        struct tm tm_now;
        time(&tm_now);
        char timestamp[50];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_now);

        fprintf(file_fd, "%s,%d,%d,%d\n", timestamp, adc_value & 0x01, (adc_value >> 4) & 0x0f, (adc_value >> 10));

        // Reset chip selects
        gpiod_set_value(cs0_chip, GPIOD_HIGH);
        gpiod_set_value(cs1_chip, GPIOD_HIGH);
        gpiod_set_value(cs2_chip, GPIOD_HIGH);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up on SIGINT or SIGTERM
    SIGINTHandler:
    SIGTERMHandler:
    {
        // Release GPIO lines
        gpiod_release_line(cs0_chip, GPIOD_OUT_HIGH);
        gpiod_release_line(cs0_chip, GPIOD_OUT_LOW);
        gpiod_release_chip(cs0_chip);

        gpiod_release_line(cs1_chip, GPIOD_OUT_HIGH);
        gpiod_release_line(cs1_chip, GPIOD_OUT_LOW);
        gpiod_release_chip(cs1_chip);

        gpiod_release_line(cs2_chip, GPIOD_OUT_HIGH);
        gpiod_release_line(cs2_chip, GPIOD_OUT_LOW);
        gpiod_release_chip(cs2_chip);

        // Close SPI device
        close(spi_fd);

        // Exit the program
        exit(EXIT_SUCCESS);
    }

    // SIGINT and SIGTERM handlers
    void SIGINTHandler(int signum) {
        fprintf(stderr, "SIGINT received, shutting down gracefully...\n");
        raise(SIGTERM); // Forward to SIGTERM handler
    }

    void SIGTERMHandler(int signum) {
        fprintf(stderr, "SIGTERM received, shutting down gracefully...\n");
        // Clean up and exit
    }

    return 0;
}

