int main(int argc, char **argv) {
    // Initialize global variables
    pi = NULL;
    moisture_read_count = 0;
    moisture_last_read = -1;

    // Parse command-line arguments
    if (argc < 4) {
        fprintf(stderr, "Usage: %s [-t threshold] [-d duration_seconds] [-s sleep_interval]\n", argv[0]);
        return EXIT_FAILURE;
    }

    threshold = atoi(argv[1]);
    duration_seconds = atoi(argv[2]);
    sleep_interval = atoi(argv[3]);

