// Function to set up pigpio
void setup_pigpio() {
    pi = pigpioOpen();
    if (pi == NULL) {
        fprintf(stderr, "Failed to open pigpio: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }

    pigpioSetWaitForever(pi);
}

// Function to set up SPI
void setup_spi() {
    int spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd == -1) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    struct spi_ioc_transfer transfers[] = {
        // MCP3008 configuration
        {
            .tx_buf = (unsigned char[]) { 0x01, SPI_MODE, 0x80 }, // Set mode 0, MSB first
            .rx_buf = NULL,
            .len = 2,
            .delay_usecs = 0,
        },
