            .tx_buf = (unsigned char[]) { 0x00, 0x00 }, // Chip select
            .rx_buf = (unsigned char *) &CE_GPIO,
            .len = 1,
            .delay_usecs = 100,
        },
        {
            .tx_buf = (unsigned char[]) { 0x80 }, // Start single conversion
            .rx_buf = NULL,
            .len = 1,
            .delay_usecs = 1000, // Wait for conversion
        },
        {
            .tx_buf = NULL,
            .rx_buf = (unsigned char *) &moisture_read_count,
            .len = 1,
            .delay_usecs = 1000,
        },
    };

    int ntransfers = sizeof(transfers) / sizeof(transfers[0]);

    if (pigpioSPIWrite(pi, spi_fd, transfers, ntransfers) == -1) {
        fprintf(stderr, "Failed to configure SPI: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }

    // Ensure GPIO18 is configured as an output
    if (gpioMode(pi, PUMP_GPIO, pigpioOutput) == -1) {
        fprintf(stderr, "Failed to set GPIO18 as output: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }
