        fprintf(stderr, "SPI read failed: %s\n", pigpioError());
        moisture_read_count = -1; // Mark as failed
        return -1; // Return error code
    }

    moisture_read_count++; // Increment read count

    return ret; // Return the 10-bit ADC value
}

// Function to handle moisture reading
void handle_moisture_reading(int value) {
    if (value < DRY_THRESHOLD) {
        // Log event
        log_event("Moisture too low, skipping irrigation.");
    } else if (value > WET_THRESHOLD) {
        // Log event
        log_event("Moisture too high, skipping irrigation.");
    } else {
        // Map value to percentage
        int moisture_percentage = (value - DRY_THRESHOLD) * 100 / (WET_THRESHOLD - DRY_THRESHOLD);

        // Log event
        log_event("Moisture: %.1f%%", moisture_percentage);

        // Check if threshold crossed
        if (moisture_percentage < threshold) {
            moisture_threshold_crossed = 1;
        } else {
            moisture_threshold_crossed = 0;
        }
    }

    // Handle pump activation based on threshold crossing
    if (moisture_threshold_crossed && !pump_active) {
        handle_pump_control(1);
    }
}

// Function to handle pump control
void handle_pump_control(int value) {
    if (value) {
        // Activate pump
        if (gpioWrite(pi, PUMP_GPIO, 1) == -1) {
            fprintf(stderr, "Failed to activate pump: %s\n", pigpioError());
            return;
        }
        pump_active = 1;
    } else {
        // Deactivate pump
        if (gpioWrite(pi, PUMP_GPIO, 0) == -1) {
            fprintf(stderr, "Failed to deactivate pump: %s\n", pigpioError());
            return;
        }
        pump_active = 0;
    }

    // Log pump state change
    log_event("Pump state changed: %s", pump_active ? "activated" : "deactivated");
}

// Function to log an event with timestamp
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(stderr, "[%s] %s\n", timestamp, message);
}

// Function to clean up resources
void cleanup() {
    if (pi) {
        pigpioClose(pi);
        pi = NULL;
    }

    if (spi_fd != -1) {
        close(spi_fd);
        spi_fd = -1;
    }

    // Ensure GPIO18 is off
    gpioWrite(pi, PUMP_GPIO, 0);
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    // Log signal received
    log_event("Received signal: SIG%s", (signum == SIGINT) ? "INT" : "TERM");

    // Clean up and exit
    cleanup();
    exit(EXIT_FAILURE);
}

