#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>

#define PIGPIO_ID -1  // Use the default pigpio instance

// Constants for MCP3008 and MAX4466
#define MCP3008_CS 8  // CE0 on GPIO8
#define MCP3008_SCLK 11  // CLK on GPIO11
#define MCP3008_MISO 9  // MISO on GPIO9
#define MCP3008_MOSI 10  // MOSI on GPIO10
#define MAX4466_ADC_CHANNEL 0

// SPI configuration
#define SPI_CLOCK_POLARITY pigpio.High
#define SPI_CLOCK_PHASE pigpio.Phase1
#define SPI_MODE pigpio.Mode0

// ADC resolution (10 bits)
#define ADC_RESOLUTION 1024

// EMA smoothing factor (alpha)
#define EMA_ALPHA 0.1

// Dynamic threshold margin for peak detection
#define THRESHOLD_MARGIN 0.2

// Buffer size for exponential moving average
#define EMA_BUFFER_SIZE 10

// Log file path
#define LOG_FILE_PATH "/var/log/sound_events.log"

// Global variables
pigpio *pi;
uint16_t adc_value;
double ema_values[EMA_BUFFER_SIZE];
int ema_index = 0;
double peak_value = 0.0;
double last_peak_time = 0.0;
int peak_detected = 0;

void cleanup() {
    if (pi != NULL) {
        pigpiod_free(pi);
        pi = NULL;
    }
    // Release any other resources here
}

void handle_signal(int signum) {
    cleanup();
    exit(0);
}

int main() {
    // Initialize pigpio
    pi = pigpiod_open(PIGPIO_ID);
    if (pi == NULL) {
        fprintf(stderr, "Failed to open pigpio: %s\n", pigpiod_error());
        return EXIT_FAILURE;
    }

    // Set up SPI
    if (pigpio_spi_setup(pi, MCP3008_CS, MCP3008_SCLK, MCP3008_MISO, MCP3008_MOSI, SPI_CLOCK_POLARITY, SPI_CLOCK_PHASE, SPI_MODE) == -1) {
        fprintf(stderr, "Failed to set up SPI: %s\n", pigpio_error());
        pigpiod_free(pi);
        pi = NULL;
        return EXIT_FAILURE;
    }

    // Signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (1) {
        // Sample ADC
        if (pigpio_spi_transfer(pi, MCP3008_MISO, 1, 0, ADC_RESOLUTION) == -1) {
            fprintf(stderr, "Failed to read ADC: %s\n", pigpio_error());
            continue;
        }

        adc_value = (uint16_t)(pigpio_spi_read(pi, MCP3008_MISO) * (1.0 / (1 << ADC_RESOLUTION)));

        // Update EMA
        double new_ema = EMA_ALPHA * ema_values[ema_index] + (1.0 - EMA_ALPHA) * adc_value;
        ema_values[ema_index] = new_ema;
        ema_index = (ema_index + 1) % EMA_BUFFER_SIZE;

        // Check for peak detection
        double threshold = ema_values[ema_index] * (1 + THRESHOLD_MARGIN);
        if (adc_value > threshold) {
            if (adc_value > peak_value) {
                peak_value = adc_value;
                last_peak_time = time(NULL);
                peak_detected = 1;
            }
        } else {
            peak_detected = 0;
        }

        // Log peak events
        if (peak_detected) {
            char timestamp[50];
            time_t now = time(NULL);
            struct tm tm_now;
            localtime_r(&now, &tm_now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_now);
            fprintf(LOG_FILE_PATH, "Peak detected: %s, Value: %u\n", timestamp, peak_value);
        }

        // Sleep for 10ms
        usleep(10000);
    }

    // Clean up on exit
    cleanup();

    return EXIT_SUCCESS;
}

