    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Main loop
    while (1) {
        // Read ADC
        read_adc();

        // Process reading
        process_reading(readings[0]);

        // Check threshold
        if (handle_threshold_exceeded()) {
            // GPIO27 HIGH
            gpioWritePin(PI_GPIO_NUM_27, GPIO_HIGH);
        }

        // Sleep for 1 second
        usleep(1000000);
    }

