    if (wiringPiI2CSetup(1) == -1) {
        syslog(LOG_ERR, "Failed to initialize I2C");
        exit(EXIT_FAILURE);
    }
}

// Function to read the ADC
void read_adc() {
    float voltage;
    if (wiringPiI2CRead(0x48, 0, &voltage, 1) == -1) {
        syslog(LOG_WARNING, "Failed to read ADC");
        return;
    }

    // Check if voltage is within valid range
    if (voltage < 0.0 || voltage > 3.3) {
        syslog(LOG_WARNING, "Invalid voltage reading: %f", voltage);
        return;
    }

    // Convert voltage to magnetic field strength
    float gauss = (voltage - SS49E_ZERO_FIELD) / SS49E_SENSITIVITY;

    // Store reading and update circular buffer
    readings[buf_index++] = gauss;
    if (buf_index >= BUFFER_SIZE) {
        buf_index = 0; // Circular buffer
    }
}

// Function to process a single reading
void process_reading(float voltage) {
    // Compute rolling average
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; ++i) {
        sum += readings[i];
    }
    float avg = sum / BUFFER_SIZE;

    // Check if threshold is exceeded
    if (avg > THRESHOLD_GAUSS) {
        handle_threshold_exceeded();
    }
}

// Function to handle threshold exceeded event
void handle_threshold_exceeded() {
    syslog(LOG_INFO, "Threshold exceeded: %f", readings[0]);
    gpioWritePin(PI_GPIO_NUM_27, GPIO_HIGH); // Set GPIO27 HIGH
}

