    // Stop I2C handle
    wiringPiI2CStop();

    // Reset GPIO27 to LOW
    gpioWritePin(PI_GPIO_NUM_27, GPIO_LOW);

    // Terminate pigpio
    pigpioTerminate();

    // Close syslog
    closelog();
}

