#define PIGPIO_ID -1
#define SPI0 0
#define MCP3008 0
#define CE0 8
#define GPIO17 17

#define MQTT_BROKER "your_broker_url"
#define MQTT_TOPIC_SOIL_MOISTURE "soil_moisture"
#define MQTT_TOPIC_PUMP_CONTROL "pump_control"

#define THRESHOLD_LOW 30
#define THRESHOLD_HIGH 35

volatile sig_atomic_t sigIntReceived = 0;

// MCP3008 configuration
#define MCP3008_CHANNEL 0

// MQTT callback function
void on_message(client *c, const mosq_message *msg) {
    char topic[100];
    char payload[100];

    // Extract topic and payload
    strcpy(topic, msg->topic_name);
    if (strcmp(topic, MQTT_TOPIC_PUMP_CONTROL) == 0) {
        if (strcmp(msg->payload, "on")) {
            pico_write(GPIO17, 1); // Activate relay
        } else if (strcmp(msg->payload, "off")) {
            pico_write(GPIO17, 0); // Deactivate relay
        }
    } else if (strcmp(topic, MQTT_TOPIC_SOIL_MOISTURE) == 0) {
        // Handle soil moisture message
    }
}

int main() {
    // Initialize logging
    openlog("soil_moisture_monitor", LOG_PID, LOG_USER);
    setlogmask(LOG_UPTO(LOG_INFO));

    // Signal handler for SIGINT/SIGTERM
    struct sigaction sa;
    sa.sa_handler = &signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize pigpio
    if (pico_init(PIGPIO_ID) < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }

    // Initialize SPI
    if (spi_open(SPI0) < 0) {
        syslog(LOG_ERR, "Failed to open SPI");
        pico_exit(PIGPIO_ID);
        return EXIT_FAILURE;
    }

    // Initialize MCP3008
    if (mcp3008_init(MCP3008, MCP3008_CHANNEL, 1000000) < 0) {
        syslog(LOG_ERR, "Failed to initialize MCP3008");
        spi_close(SPI0);
        pico_exit(PIGPIO_ID);
        return EXIT_FAILURE;
    }

    // Initialize MQTT
    mosquitto_connect_options opts = {
        .host_name = MQTT_BROKER,
        .port = 1883,
        .client_id = "soil_moisture_monitor",
        .callback = on_message,
    };
    if (mosquitto_connect(&opts, NULL, 0) < 0) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker");
        mcp3008_deinit(MCP3008);
        spi_close(SPI0);
        pico_exit(PIGPIO_ID);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!sigIntReceived) {
        // Read soil moisture
        int value = mcp3008_read(MCP3008);
        if (value < 0) {
            syslog(LOG_ERR, "Failed to read MCP3008");
            continue;
        }

        // Check for valid moisture reading
        if (value < 0 || value > 1023) {
            syslog(LOG_WARNING, "Invalid moisture reading: %d", value);
            continue;
        }

        // Convert to percentage
        float moisturePercentage = (float)value / 1023.0 * 100;

        // Log moisture reading
        syslog(LOG_INFO, "Moisture: %.2f%%", moisturePercentage);

        // Publish moisture reading to MQTT
        char msgBuffer[50];
        sprintf(msgBuffer, "moisture=%d", value);
        if (mosquitto_pub(NULL, MQTT_TOPIC_SOIL_MOISTURE, MQTT_QOS, msgBuffer) < 0) {
            syslog(LOG_ERR, "Failed to publish moisture reading");
        }

        // Control relay based on moisture level
        if (moisturePercentage < THRESHOLD_LOW) {
            pico_write(GPIO17, 1); // Activate relay
        } else if (moisturePercentage > THRESHOLD_HIGH) {
            pico_write(GPIO17, 0); // Deactivate relay
        }

        // Sleep for 60 seconds
        sleep(60);
    }

    // Clean up on SIGINT/SIGTERM
    sigIntReceived = 1;

    // Deactivate relay
    pico_write(GPIO17, 0);

    // Close SPI and MQTT
    spi_close(SPI0);
    mosquitto_disconnect();

    // Shutdown pigpio
    pico_cleanup(PIGPIO_ID);

    // Exit
    exit(EXIT_SUCCESS);

// Signal handler
void signal_handler(int signum) {
    sigIntReceived = 1;
}

