#include <signal.h>

#define VREF 3300.0  // 3.3V reference voltage

// MCP3008 SPI configuration
#define MCP3008_CS GPIO_NUM_8
#define MCP3008CLK GPIO_NUM_11
#define MCP3008DIN GPIO_NUM_10
#define MCP3008DOUT GPIO_NUM_9

// SPI device file descriptor
int spidev_fd = -1;

// Signal handler for SIGINT
void signal_handler(int signum) {
    fprintf(stderr, "Caught SIGINT, closing SPI device...\n");
    close(spidev_fd);
    exit(0);
}

int main() {
    // Initialize SPI device
    int ret;
    spidev_fd = open("/dev/spidev0.0", O_RDWR);
    if (spidev_fd == -1) {
        perror("Failed to open spidev0.0");
        return EXIT_FAILURE;
    }

    // Set SPI mode and configure GPIO pins
    ret = ioctl(spidev_fd, SPI_IOC_WR_MODE, &0x01);  // SPI mode 0
    if (ret < 0) {
        perror("Failed to set SPI mode");
        close(spidev_fd);
        return EXIT_FAILURE;
    }

    ret = gpio_export(MCP3008CLK, GPIO_EXPORT_DIR_OUT);
    if (ret < 0) {
        perror("Failed to export MCP3008CLK");
        close(spidev_fd);
        return EXIT_FAILURE;
    }

    ret = gpio_export(MCP3008DOUT, GPIO_EXPORT_DIR_IN);
    if (ret < 0) {
        perror("Failed to export MCP3008DOUT");
        gpio_unexport(MCP3008CLK);
        close(spidev_fd);
        return EXIT_FAILURE;
    }

    ret = gpio_export(MCP3008DIN, GPIO_EXPORT_DIR_OUT);
    if (ret < 0) {
        perror("Failed to export MCP3008DIN");
        gpio_unexport(MCP3008DOUT);
        close(spidev_fd);
        return EXIT_FAILURE;
    }

    ret = gpio_export(MCP3008_CS, GPIO_EXPORT_DIR_OUT);
    if (ret < 0) {
        perror("Failed to export MCP3008 CS");
        gpio_unexport(MCP3008DIN);
        close(spidev_fd);
        return EXIT_FAILURE;
    }

    // Set GPIO 8 as CS pin
    ret = gpio_set_value(MCP3008_CS, 0);  // Set CS low
    if (ret < 0) {
        perror("Failed to set CS low");
        gpio_unexport(MCP3008_CS);
        close(spidev_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Send command to MCP3008
        char command[] = {0x01, 0x01, 0};  // Start bit, channel 0, dummy byte
        ssize_t bytes_written = write(spidev_fd, command, sizeof(command));
        if (bytes_written != sizeof(command)) {
            perror("Failed to write to MCP3008");
            break;
        }

        // Read response from MCP3008
        uint8_t data[1];
        ssize_t bytes_read = read(spidev_fd, data, sizeof(data));
        if (bytes_read != sizeof(data)) {
            perror("Failed to read from MCP3008");
            break;
        }

        // Convert 10-bit value to voltage
        uint16_t raw_value = (data[0] << 8) | data[1];
        float voltage = (raw_value * VREF) / 1024.0;

        // Print raw value and voltage
        printf("Raw value: 0x%X (Voltage: %.3f V)\n", raw_value, voltage);

        // Delay for 500 ms
        usleep(500000);
    }

    // Clean up on SIGINT
    signal(SIGINT, signal_handler);

    // Close SPI device
    close(spidev_fd);

    return EXIT_SUCCESS;
}

