#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define MCP3008_ADDR 0x7E
#define SPI_PORT 0
#define CE_PIN 0

// Function prototypes
void handle_signal(int signum);
int spi_transfer(unsigned char data);
void adc_read(int channel, unsigned int *value);
void write_to_csv(const char *data);
void cleanup();

int main() {
    // Initialize pigpio
    if (pigpio_init() == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }

    // Install signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (1) {
        // Sample and log data every 5 seconds
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        ts.tv_sec += 5;
        clock_settime(CLOCK_REALTIME, &ts);

        unsigned int values[3];
        for (int i = 0; i < 3; ++i) {
            adc_read(i, &values[i]);
        }

        // Write to CSV file
        write_to_csv(values);

        // Sleep until next interval
        usleep(5000000); // 5 seconds
    }

    // Clean up on exit
    cleanup();

    return 0;
}

// Function to handle signals
void handle_signal(int signum) {
    // Clean up resources
    cleanup();
    exit(EXIT_SUCCESS);
}

// SPI transfer function
int spi_transfer(unsigned char data) {
    int ret = pigpio_spi_transfer(SPI_PORT, MCP3008_ADDR, data);
    if (ret < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", pigpio_error());
        return -1;
    }
    return ret;
}

// ADC read function
void adc_read(int channel, unsigned int *value) {
    unsigned char cmd = (1 << 7) | (channel << 4);
    int ret = spi_transfer(cmd);
    if (ret < 0) {
        fprintf(stderr, "SPI transfer for ADC command failed: %s\n", pigpio_error());
        return;
    }

    ret = spi_transfer(0x01);
    if (ret < 0) {
        fprintf(stderr, "SPI transfer for data failed: %s\n", pigpio_error());
        return;
    }

    *value = (unsigned int)(spi_transfer(0x00) << 8) | spi_transfer(0x00);
}

// Function to write to CSV file
void write_to_csv(const char *data) {
    FILE *file = fopen("sensor_data.csv", "a+");
    if (!file) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        return;
    }

    fprintf(file, "%s,%d\n", __TIME__, data);
    fclose(file);
}

// Cleanup function
void cleanup() {
    // Close SPI
    pigpio_spi_close(SPI_PORT);

    // Terminate pigpio
    pigpio_cleanup();
}

