- `cleanup()` releases all resources upon program termination or signal handling.

Ensure that the MCP3008 is correctly wired to the Raspberry Pi Zero W, with the CS (CE0) pin connected to the appropriate GPIO pin, and the SPI lines (MOSI, MISO, SCLK) connected accordingly. The reference voltage (`VREF`) is assumed to be 3.3V as per the Raspberry Pi's supply voltage.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <time.h>
#include <pigpio.h>
#include <linux/spidev.h>

#define GPIO17 17
#define GPIO27 27
#define THRESHOLD 500
#define PWM_FREQ 100

volatile sig_atomic_t should_exit = 0;

// Function prototypes
void setup_pigpio();
void setup_spi();
void read_adc();
void handle_noise_level(int adc_value);
void cleanup();
void signal_handler(int signum);

int main() {
    setup_pigpio();
    setup_spi();
    while (!should_exit) {
        read_adc();
        handle_noise_level(read_adc());
        usleep(10000); // 10 ms delay
    }
    cleanup();
    return 0;
}

void setup_pigpio() {
    if (pigpio_init() == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }
}

void setup_spi() {
    int spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd == -1) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    struct spi_ioc_transfer transfers[] = {
        // Transfer for MCP3008 command (write)
        {
            .tx_buf = (unsigned char[]) {0x06}, // MCP3008 command for single-ended mode
            .len = 1,
            .speed_hz = 1000000, // 1 MHz
            .bits_per_word = 8,
            .delay_usecs = 0,
        },
        // Transfer for MCP3008 data read (read)
        {
            .rx_buf = (unsigned char[]) {0},
            .len = 1,
            .speed_hz = 1000000,
            .bits_per_word = 8,
            .delay_usecs = 0,
        },
    };

    int rc = spi_write(spi_fd, transfers, 2);
    if (rc != 2) {
        fprintf(stderr, "Failed to write to SPI: %d transfers completed\n", rc);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Assume SPI is correctly configured
}

void read_adc() {
    struct spi_ioc_transfer read_transfer = transfers[1];
    read_transfer.tx_buf = (unsigned char[]) {0x01}; // MCP3008 command for single-ended read

    int rc = spi_write(spi_fd, &read_transfer, 1);
    if (rc == 1) {
        unsigned int adc_value;
        if (spi_read(spi_fd, &read_transfer, 1) == 1) {
            adc_value = read_transfer.rx_buf[0];
            if (adc_value > THRESHOLD) {
                handle_noise_level(adc_value);
                fprintf(stderr, "Noise level exceeded threshold at %s\n", ctime(&time(NULL)));
                fprintf(stderr, "Writing to vibration_log.txt...\n");
                FILE *log_file = fopen("vibration_log.txt", "a+");
                if (!log_file) {
                    fprintf(stderr, "Failed to open vibration_log.txt for writing: %s\n", strerror(errno));
                    fclose(log_file);
                    return;
                }
                fprintf(log_file, "Noise level exceeded threshold at %s\n", ctime(&time(NULL)));
                fclose(log_file);
            }
        } else {
            fprintf(stderr, "Failed to read from MCP3008: %d bytes received\n", rc);
        }
    } else {
        fprintf(stderr, "Failed to initiate SPI read: %d transfers completed\n", rc);
    }
}

void handle_noise_level(int adc_value) {
    if (adc_value > THRESHOLD) {
        int duty_cycle = (adc_value - THRESHOLD) * (PWM_FREQ / 1023);
        gpio_mode(GPIO17, GPIO_OUT);
        gpio_mode(GPIO27, GPIO_OUT);

        pigpio_write(GPIO17, duty_cycle);
        pigpio_write(GPIO27, duty_cycle);

        fprintf(stderr, "Activating motors with duty cycle %d\n", duty_cycle);
    } else {
        gpio_mode(GPIO17, GPIO_IN);
        gpio_mode(GPIO27, GPIO_IN);

