#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <stdint.h>

#define MAX9814_ADC_CHANNEL 0
#define MAX9814_MCP3008_ADDR 0x60
#define BH1750_I2C_ADDR 0x23
#define BH1750_CMD_HIGH_RES_MODE 0x11
#define SLEEP_TIME_MS 180
#define LOG_INTERVAL_MS 5000
#define CSV_FILE_PATH "tamper_log.csv"

// Constants for I2C and SPI operations
#define BH1750_REG_HIGH_RES_MODE 0x11
#define BH1750_REG_DATA_0 0x00
#define BH1750_REG_DATA_1 0x01

// Function prototypes
void initialize_devices();
void read_max9814();
void read_bh1750();
void write_to_csv(const char *data);
void handle_errors(int error);
void cleanup();

int main() {
    srand(time(NULL));
    signal(SIGINT, handle_errors);
    signal(SIGTERM, handle_errors);

    // Initialize devices
    initialize_devices();

    // Main loop
    while (1) {
        // Check for termination signals
        if (WIFEXITED(getpid())) {
            cleanup();
            break;
        }

        // Log every 5 seconds
        if ((time(NULL) % LOG_INTERVAL_MS) == 0) {
            char buffer[256];
            struct timespec ts;

            // Get current timestamp
            clock_gettime(CLOCK_REALTIME, &ts);
            strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", &ts);

            // Read sound level from MAX9814
            read_max9814();

            // Read light level from BH1750
            read_bh1750();

            // Write to CSV file
            write_to_csv(buffer);

            // Sleep for the remaining time of the interval
            usleep((LOG_INTERVAL_MS - (time(NULL) % LOG_INTERVAL_MS)) * 1000);
        }
    }

    return 0;
}

// Function to initialize devices
void initialize_devices() {
    // Initialize libgpiod for SPI and I2C access
    gpiod_init();

    // Open SPI0 CE0
    int spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd == -1) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    // Open I2C device /dev/i2c-1
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C device");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Prepare for I2C operations
    struct i2c_msg bh1750_cmd = {
        .addr = BH1750_I2C_ADDR,
        .flags = 0,
        .len = sizeof(uint16_t),
        .buf = (void *)&BH1750_CMD_HIGH_RES_MODE
    };

    // Prepare for SPI operations
    gpiod_set_data_direction(spi_fd, GPIOD_DIR_OUT_IN);
    gpiod_set_speed(spi_fd, 1000000); // 1 MHz

    // Keep I2C and SPI file descriptors
    spi_fd_resource = spi_fd;
    i2c_fd_resource = i2c_fd;
}

// Function to read sound level from MAX9814 using MCP3008
void read_max9814() {
    int adc_value;

    // Set MCP3008 channel to 0
    gpiod_set_value(spi_fd_resource, MAX9814_MCP3008_ADDR, MAX9814_ADC_CHANNEL, 1);

    // Read ADC value
    adc_value = read(spi_fd_resource, 1, (unsigned char *)&MAX9814_MCP3008_ADDR);

    // Convert ADC value to dB
    float sound_level_db = (float)adc_value * 1024.0 / 4096.0 * 20.0;
    printf("Sound level (dB): %f\n", sound_level_db);

    // Handle potential errors
    handle_errors(adc_value);
}

// Function to read light level from BH1750
void read_bh1750() {
    uint16_t lux;

    // Send high-resolution mode command to BH1750
    if (i2c_transfer(i2c_fd_resource, &bh1750_cmd, 1) != 1) {
        perror("Failed to send BH1750 command");
        return;
    }

    // Wait for BH1750 to process the command
    usleep(SLEEP_TIME_MS * 1000);

    // Read light level data from BH1750
    if (i2c_transfer(i2c_fd_resource, &bh1750_cmd, 1) != 1) {
        perror("Failed to read BH1750 data");
        return;
    }

    lux = bh1750_cmd.buf[0] << 8 | bh1750_cmd.buf[1];
    printf("Light level (lux): %d\n", lux);

    // Handle potential errors
    handle_errors(i2c_transfer(i2c_fd_resource, &bh1750_cmd, 1));
}

// Function to write data to CSV file
void write_to_csv(const char *data) {
    FILE *csv_file = fopen(CSV_FILE_PATH, "a+");
    if (!csv_file) {
        perror("Failed to open CSV file");
        return;
    }

    fprintf(csv_file, "%s,%f,%d,0\n", data, atof(&data[strlen(data) - 16]), lux, adc_value);
    fclose(csv_file);
}

// Function to handle errors and log them
void handle_errors(int error_code) {
    char error_message[256];

    // Format error message
    sprintf(error_message, "Error: %d", error_code);

    // Write error to CSV file
    write_to_csv(error_message);

    // Log error message to stdout
    printf("Error: %s\n", error_message);
}

// Function to cleanup resources
void cleanup() {
    // Close I2C and SPI file descriptors
    close(i2c_fd_resource);
    close(spi_fd_resource);

    // Release libgpiod resources
    gpiod_cleanup();
}

