#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <wiringPiSPI.h>

// Constants
#define VH400_PIN 0 // MCP3008 CH0
#define SPI_CHANNEL 0 // CE0
#define SPI_SPEED 1000000 // 1 MHz
#define WATER_PUMP_GPIO 17
#define THRESHOLD MoistureThreshold // Define threshold moisture level

// Data structure for SPI transaction
typedef struct {
    uint8_t command;
    uint8_t channel;
} SPITransaction;

// Function prototypes
void setup_pigpio();
void setup_spi();
void read_moisture();
void handle_water_pump_signal(int signum);
void cleanup_resources();

// Moisture threshold function
int MoistureThreshold(uint8_t value) {
    return value < 30 ? 1 : 0; // Check if moisture is below threshold
}

int main() {
    // Signal handler for SIGINT/SIGTERM
    signal(SIGINT, handle_water_pump_signal);
    signal(SIGTERM, handle_water_pump_signal);

    // Initialize pigpio
    setup_pigpio();

    // Setup SPI
    setup_spi();

    // Main loop
    while (1) {
        // Read moisture every 60 seconds
        read_moisture();
        usleep(6000000); // 6000000 microseconds = 60 seconds
    }

    // Clean up resources on exit
    cleanup_resources();

    return 0;
}

// Function to setup pigpio
void setup_pigpio() {
    if (pigpioSetup(0) == -1) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }
}

// Function to setup SPI
void setup_spi() {
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        fprintf(stderr, "Failed to setup SPI\n");
        exit(EXIT_FAILURE);
    }
}

// Function to read moisture
void read_moisture() {
    int attempts = 0;
    while (attempts < 3) {
        SPITransaction transaction = {0x08, VH400_PIN}; // Read command for MCP3008

        // Send SPI transaction
        if (wiringPiSPISend(transaction.command, transaction.channel) == -1) {
            fprintf(stderr, "Failed to send SPI transaction\n");
            continue;
        }

        // Receive and validate SPI response
        uint16_t value = wiringPiSPIRead();
        if (value == 0) {
            fprintf(stderr, "Failed to read value from MCP3008\n");
            continue;
        }

        // Check moisture level and activate pump if necessary
        int moisture_level = (value / 1024.0) * 3.0; // Convert 10-bit ADC value to voltage
        if (MoistureThreshold(moisture_level)) {
            gpioWrite(WATER_PUMP_GPIO, 1); // Activate pump
        } else {
            gpioWrite(WATER_PUMP_GPIO, 0); // Deactivate pump
        }

        attempts++;
        if (attempts == 3) {
            fprintf(stderr, "Failed to read moisture after 3 attempts\n");
            exit(EXIT_FAILURE);
        }
    }

    // Log timestamped reading to console
    struct tm timeinfo;
    time(&timeinfo);
    char buffer[50];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", &timeinfo);
    printf("Moisture level: %f%% at %s\n", moisture_level * 100, buffer);
}

// Function to handle SIGINT/SIGTERM
void handle_water_pump_signal(int signum) {
    // Turn off the water pump
    gpioWrite(WATER_PUMP_GPIO, 0);

    // Close SPI
    wiringPiSPIClose();

    // Shutdown pigpio
    pigpioTerminate();

    // Exit the program
    exit(EXIT_SUCCESS);
}

// Function to cleanup resources
void cleanup_resources() {
    // Close SPI
    wiringPiSPIClose();

    // Shutdown pigpio
    pigpioTerminate();
}

