#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/stat.h>

#define PIGPIO_ID -1  // Use the default pigpio instance

// Constants
#define SPI_CHANNEL 0
#define SPI_CLOCK_SPEED 1000000  // 1 MHz
#define GPIO_FAN 18
#define MAX_CO2_PPM 700

// Function prototypes
void setup_pigpio();
void setup_spi();
void read_adc();
void convert_adc_to_co2();
void handle_fan_control(int co2_ppm);
void log_data(const char *timestamp, int co2_ppm, int fan_state);
void cleanup();
void signal_handler(int signum);

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    setup_pigpio();
    setup_spi();

    while (1) {
        read_adc();
        convert_adc_to_co2();
        handle_fan_control(*co2_ppm);
        log_data(__TIME__, *co2_ppm, *fan_state);
        usleep(5000000);  // Sleep for 5 seconds
    }

    cleanup();

    return 0;
}

// Function: setup_pigpio
void setup_pigpio() {
    if (pigpio_open(&PIGPIO_ID) == -1) {
        fprintf(stderr, "Failed to open pigpio: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }
}

// Function: setup_spi
void setup_spi() {
    int spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd == -1) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    struct spi_i2c_dev *spi_dev = spi_i2c_dev_open(spi_fd, SPI_CLOCK_SPEED, 0, 0);
    if (!spi_dev) {
        fprintf(stderr, "Failed to open SPI device: %s\n", spi_i2c_dev_err(spi_fd));
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE_0) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_CLOCK_SPEED) < 0) {
        fprintf(stderr, "Failed to set SPI clock speed: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_CS_HIGH, &((unsigned int)1)) == -1) {
        fprintf(stderr, "Failed to set CS high: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Set CE0 as output to control MCP3008
    if (gpio_mode_dir(GPIO_FAN, GPIO_OUT) == -1) {
        fprintf(stderr, "Failed to set GPIO %d direction: %s\n", GPIO_FAN, gpio_error());
        exit(EXIT_FAILURE);
    }

    if (gpio_write(GPIO_FAN, 1) == -1) {
        fprintf(stderr, "Failed to set GPIO %d high: %s\n", GPIO_FAN, gpio_error());
        exit(EXIT_FAILURE);
    }
}

// Function: read_adc
void read_adc() {
    int adc_value;

    if (spi_transfer(spi_dev, 0x01, SPI_CHANNEL) == -1) {
        fprintf(stderr, "SPI transfer error: %s\n", spi_i2c_dev_err(spi_fd));
        return;
    }

    adc_value = (spi_transfer(spi_dev, 0x00, SPI_CHANNEL) & 0x0F);
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return;
    }
}

// Function: convert_adc_to_co2
void convert_adc_to_co2() {
    int co2_ppm = (adc_value * 0.5) - 50;  // Linear calibration (slope 0.5, intercept -50)
    if (co2_ppm < 0 || co2_ppm > MAX_CO2_PPM) {
        co2_ppm = 0;  // Clamp to safe range
    }
}

// Function: handle_fan_control
void handle_fan_control(int co2_ppm) {
    if (co2_ppm > MAX_CO2_PPM) {
        gpio_write(GPIO_FAN, 1);  // Turn on fan
    } else {
        gpio_write(GPIO_FAN, 0);  // Turn off fan
    }
}

// Function: log_data
void log_data(const char *timestamp, int co2_ppm, int fan_state) {
    FILE *file = fopen("air_quality.log", "a");
    if (!file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    fprintf(file, "%s,%d,%d\n", timestamp, co2_ppm, fan_state);
    fclose(file);
}

// Function: cleanup
void cleanup() {
    gpio_write(GPIO_FAN, 0);  // Turn off fan
    spi_i2c_dev_close(spi_dev);
    close(spi_fd);
    pigpio_close(PIGPIO_ID);
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    cleanup();
    exit(EXIT_SUCCESS);
}

