    if (gpio17 < 0) {
        fprintf(stderr, "Error requesting GPIO %d: %s\n", GPIO17, strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Set GPIO17 as active high
    if (gpio_direction_output(GPIO17, 1) < 0) {
        fprintf(stderr, "Error setting GPIO %d direction: %s\n", GPIO17, strerror(errno));
        gpio_release(GPIO17);
        exit(EXIT_FAILURE);
    }

    gpio_write(GPIO17, 0);  // De-energize relay initially
}

// Function: Setup SPI
void setup_spi() {
    int spi_fd;

    // Open SPI device
    spi_fd = gpiod_open(SPI0, GPIOD_OPEN_MODE_NORMAL);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %d: %s\n", SPI0, strerror(errno));
        gpiod_close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Configure SPI
    if (gpiod_spi_setup(spi_fd, MCP3008_SCLK, MCP3008_MISO, MCP3008_MOSI, MCP3008_CS, 1000000) < 0) {
        fprintf(stderr, "Error configuring SPI: %s\n", gpiod_get_error(spi_fd));
        gpiod_close(spi_fd);
        exit(EXIT_FAILURE);
    }
}

