    if (gpiod_spi_transfer(spi_fd, MCP3008_MOSI, MCP3008_SCLK, MCP3008_CS, 1, 0, &value) < 0) {
        fprintf(stderr, "Error reading from MCP3008: %s\n", gpiod_get_error(spi_fd));
        return;
    }

    // Convert raw value to distance
    float distance_cm = (float)value / 1024.0 * MAX_DISTANCE;
    if (distance_cm > MAX_DISTANCE) {
        distance_cm = MAX_DISTANCE;  // Clamp to maximum range
    }
}

