    time_t now = time(NULL);
    char buffer[256];

    // Format and write to log
    sprintf(buffer, "Proximity detected at %s", ctime(&now));
    write_to_log(buffer);

    // Energize relay for 1 second debounce delay
    gpio_write(RELAY_GPIO, 1);
    usleep(DEBOUNCE_TIME);

    // De-energize relay after debounce
    gpio_write(RELAY_GPIO, 0);
}

