    if (pi_spi_open(MCP3008_SPI_CHANNEL, MCP3008_CMD_SINGLE_ENDED, CE0, 1000000, SPI_MODE_0) != PI_ERROR_OK) {
        fprintf(stderr, "Error opening SPI: %s\n", pi_spi_error_string());
        exit(EXIT_FAILURE);
    }
