// Function to read MCP3008 ADC value for a single channel
void read_mcp3008(uint8_t channel) {
    uint16_t adc_value;
    if (pi_spi_xfer(MCP3008_CMD_SINGLE_ENDED | (channel << 5))) {
        adc_value = (pi_spi_read() << 8) | pi_spi_read();
        if (adc_value > 1023) {
            fprintf(stderr, "ADC value overflow: %d\n", adc_value);
            return;
        }
    } else {
        fprintf(stderr, "Error reading from MCP3008: %s\n", pi_spi_error_string());
        return;
    }
    return adc_value;
}

