    uint32_t sum = 0;
    for (int i = 0; i < count; i++) {
        sum += values[i];
    }
    uint16_t avg = sum / count;
    return avg;
}

// Function to map ADC average to PWM value
void map_value_to_pwm(uint16_t adc_avg, float *pwm) {
    *pwm = 100.0 - (100.0 * adc_avg / 1023.0);
}

