    if (signum == SIGINT || signum == SIGTERM) {
        // Close the valve
        pigpio_pwm_set(GPIO17, 0, 100, 100);

        // Close SPI
        pi_spi_close();

        // Close the log file
        fclose("irrigation.log");

        // Shutdown pigpio
        pi_pigpio_cleanup();
    }
}

