#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>

// Define constants for MCP3008 and SPI communication
#define MCP3008_ADDR 0x68
#define SPI_MODE 0
#define SPI_SPEED MHZ_1
#define SPI_CS GPIO8

// MCP3008 command for single-ended mode, channel 0
