// Function prototypes
void setup_pigpio();
void read_spi(uint8_t channel, uint8_t* data);
void convert_adc_to_moisture(uint16_t adc_value);
void log_data(const char* message);
void handle_spi_error(int attempts);
void cleanup();
void signal_handler(int signum);

int main() {
    // Initialize global variables
    int attempts = 0;
    uint8_t data[2];
    uint16_t adc_value;
    struct timespec timestamp;
    pid_t pid;

    // Signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup pigpio
    setup_pigpio();

    while (1) {
        // Attempt to read SPI
        if (read_spi(MCP3008_CMD_SINGLEENDED_CHAN0, data) == 0) {
            // Successfully read SPI data
            adc_value = spi_read_10bit(data[0], data[1]);
            convert_adc_to_moisture(adc_value);
            log_data("Soil Moisture: %.2f%%", adc_value / 1023.0 * 100.0);
        } else {
            // Handle SPI communication error
            handle_spi_error(attempts);
            attempts++;
            if (attempts > 5) {
                // Persistent error, skip reading and log error
                log_data("Error: Persistent SPI communication failure. Skipping reading.");
                continue;
            }
            usleep(1000 * (pow(2, attempts) - 1)); // Exponential backoff
        }

        // Wait for 5 seconds before next reading
        usleep(5000000);

        // Check for termination signals
        if (WIFSIGNALED(getpid())) {
            cleanup();
            break;
        }
    }

    // Clean up resources on exit
    cleanup();

    return 0;
}

// Function to setup pigpio
void setup_pigpio() {
    if (pigpio_open() < 0) {
        fprintf(stderr, "Failed to open pigpio: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }

    // Set SPI0 channel to output for CE0
    if (pigpio_direction(GPIO8, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO8 as output: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }

    // Set GPIO8 as low (CE0 for SPI0)
    if (pigpio_write(GPIO8, 0) < 0) {
        fprintf(stderr, "Failed to set GPIO8 low: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }
}

// Function to read SPI data from MCP3008
int read_spi(uint8_t channel, uint8_t* data) {
    int ret;

    // Set SPI CS low
    if (pigpio_write(GPIO8, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO8 high: %s\n", pigpio_error());
        return -1;
    }

    // Send MCP3008 command
    ret = pigpio_write(MCP3008_ADDR, (channel << 5) | MCP3008_CMD_SINGLEENDED_CHAN0);

    // Set SPI CS high
    if (pigpio_write(GPIO8, 0) < 0) {
        fprintf(stderr, "Failed to set GPIO8 low: %s\n", pigpio_error());
        return -1;
    }

    // Read data from MCP3008
    ret = pigpio_read(MCP3008_ADDR, 2, data);

    // Set SPI CS high
    if (pigpio_write(GPIO8, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO8 high: %s\n", pigpio_error());
        return -1;
    }

    return ret == 2; // Check if 2 bytes were read successfully
}

// Function to convert ADC value to moisture percentage
void convert_adc_to_moisture(uint16_t adc_value) {
    if (adc_value > 1023) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return;
    }

    // Convert ADC value to moisture percentage
    float moisture_percentage = (float)adc_value / 1023.0 * 100.0;
    printf("ADC Value: %d, Moisture Percentage: %.2f%%\n", adc_value, moisture_percentage);
}

// Function to log data with timestamp
void log_data(const char* message) {
    time(&timestamp);
    char log_message[256];
    strftime(log_message, sizeof(log_message), "%Y-%m-%d %H:%M:%S", &timestamp);
    fprintf(stderr, "%s: %s\n", log_message, message);
}

// Handle SPI communication errors with exponential backoff
void handle_spi_error(int attempts) {
    if (attempts > 5) {
        fprintf(stderr, "Persistent SPI communication failure after %d attempts.\n", attempts);
        return;
    }

    fprintf(stderr, "SPI communication error. Retrying in %d ms...\n", 1000 * (pow(2, attempts) - 1));
    usleep(1000 * (pow(2, attempts) - 1)); // Exponential backoff
}

// Function to cleanup resources on SIGINT/SIGTERM
void cleanup() {
    // Release all resources
    pigpio_close();
    // Ensure GPIO8 is set to a known state (high in this case)
    pigpio_write(GPIO8, 1);
}

