#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <stdint.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <libgpiod/gpiod.h>
#include <linux/pwm.h>
#include <sys/ioctl.h>
#include <stdint.h>
#include <stdbool.h>

#define TRIG_GPIO 23
#define ECHO_GPIO 24
#define PWM0_GPIO 18
#define MCP3008_CS 25
#define SPI0_DEVICE "/dev/spidev0.0"

#define MAX_DISTANCE 400.0
#define MIN_FREQ 220
#define MAX_FREQ 880

#define PWM_FREQ 50000
#define PWM_MIN_DUTY 0
#define PWM_MAX_DUTY 100

#define LDR_PIN 0
#define ADC_CHANNEL 0

// GPIO Pin Constants
#define TRIG_PIN GPIOD_NUM_23
#define ECHO_PIN GPIOD_NUM_24
#define PWM_PIN GPIOD_NUM_18

// MCP3008 Configuration
#define MCP3008_ADDR 7

// Calibration Data File Path
#define CONFIG_FILE_PATH "theremin_config.txt"

// Function prototypes
void setup_resources();
void cleanup_resources();
void read_ultrasonic();
void read_ldr();
void set_pwm_duty(uint16_t duty);
void handle_interrupt(int signum);

int main() {
    // Initialize resources
    setup_resources();

    // Signal handler for SIGINT
    signal(SIGINT, handle_interrupt);

    // Main loop
    while (1) {
        // Read ultrasonic sensor
        read_ultrasonic();

        // Read LDR
        read_ldr();

        // Set PWM duty cycle based on LDR value
        set_pwm_duty((uint16_t)(map(analogRead(), 0, 1023, PWM_MIN_DUTY, PWM_MAX_DUTY)));

        // Sleep to avoid CPU hogging
        usleep(10000);
    }

    // Clean up resources
    cleanup_resources();

    return 0;
}

// Function to setup GPIO and SPI resources
void setup_resources() {
    // Initialize libgpiod
    gpiod_init();

    // Open GPIO pins
    int trig_fd = gpiod_open(TRIG_PIN, GPIOD_OUT_INIT_HIGH);
    int echo_fd = gpiod_open(ECHO_PIN, GPIOD_OUT_INIT_HIGH);
    int pwm_fd = gpiod_open(PWM_PIN, GPIOD_OUT_INIT_LOW);

    // Open SPI device
    int spi_fd = open(SPI0_DEVICE, O_RDWR);
    if (spi_fd == -1) {
        fprintf(stderr, "Error opening SPI device\n");
        exit(EXIT_FAILURE);
    }

    // Configure SPI
    struct spi_ioc_transfer spi_config[] = {
        // MCP3008 configuration
        {
            .tx_buf = (unsigned char[]) { MCP3008_ADDR, 0x01 }, // Select MCP3008 and start conversion
            .rx_buf = (unsigned char[2]), // Buffer for data
            .len = 3,
            .delay_usecs = 0,
        },
        // No receive buffer needed for MCP3008
        { .len = 0 },
    };

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &((1 << 7) - 1)) < 0) {
        fprintf(stderr, "Error configuring SPI bits per word\n");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &PWM_FREQ) < 0) {
        fprintf(stderr, "Error configuring SPI max speed\n");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set GPIO pins to appropriate modes
    if (gpiod_set_data_direction(TRIG_PIN, GPIOD_DIR_OUT) < 0 ||
        gpiod_set_data_direction(ECHO_PIN, GPIOD_DIR_OUT) < 0 ||
        gpiod_set_data_direction(PWM_PIN, GPIOD_DIR_OUT) < 0) {
        fprintf(stderr, "Error setting GPIO directions\n");
        exit(EXIT_FAILURE);
    }

    // Cleanup resources on SIGINT
    signal(SIGINT, handle_interrupt);
}

// Function to cleanup resources
void cleanup_resources() {
    // Close GPIO and SPI resources
    gpiod_close(trig_fd);
    gpiod_close(echo_fd);
    gpiod_close(pwm_fd);
    close(spi_fd);

    // Reset GPIO pins to default state
    gpiod_set_data_direction(TRIG_PIN, GPIOD_DIR_IN);
    gpiod_set_data_direction(ECHO_PIN, GPIOD_DIR_IN);
    gpiod_set_data_direction(PWM_PIN, GPIOD_DIR_IN);
}

// Function to read the ultrasonic sensor
void read_ultrasonic() {
    uint32_t start_time;
    uint32_t duration;

    // Trigger the ultrasonic sensor
    gpiod_set_value(TRIG_PIN, 1);
    usleep(2);
    gpiod_set_value(TRIG_PIN, 0);

    start_time = microsecond();

    // Wait for echo
    while (gpiod_get_value(ECHO_PIN) == 0) {
        if (microsecond() - start_time > MAX_DISTANCE * 29) {
            fprintf(stderr, "Timeout waiting for echo\n");
            return;
        }
    }

    duration = microsecond() - start_time;

    // Calculate distance
    float distance = (duration / 29.0) * 0.034;

    // Check if distance is valid
    if (distance > MAX_DISTANCE) {
        fprintf(stderr, "Invalid distance reading\n");
        return;
    }

    // Store distance in a global variable for processing
    global_distance = distance;
}

// Function to read the LDR value using MCP3008
void read_ldr() {
    uint16_t ldr_value;

    // Write MCP3008 command to start conversion
    gpiod_set_value(MCP3008_CS, 0);
    usleep(1);
    gpiod_set_value(MCP3008_CS, 1);

    // Send conversion command
    struct spi_ioc_transfer transfer[] = {
        { .tx_buf = (unsigned char[]) { MCP3008_ADDR, 0x00 }, .len = 1 },
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        fprintf(stderr, "Error during SPI transfer\n");
        return;
    }

    // Read ADC value
    ldr_value = (spi_read(MCP3008_ADDR, ADC_CHANNEL) >> 6) & 0x3F;

    // Map LDR value to PWM duty cycle range
    set_pwm_duty((uint16_t)(map(ldr_value, 0, 1023, PWM_MIN_DUTY, PWM_MAX_DUTY)));
}

// Function to set PWM duty cycle
void set_pwm_duty(uint16_t duty) {
    uint32_t period = PWM_FREQ / (1000 / (float)duty);

    // Set PWM period
    if (ioctl(pwm_fd, PWM_SET_MODE, PWM_MODE_ON) < 0 ||
        ioctl(pwm_fd, PWM_SETPeriod, &period) < 0) {
        fprintf(stderr, "Error setting PWM duty cycle\n");
        return;
    }

    // Set PWM duty cycle
