#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <gpiod.h>
#include <spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define MCP3008_CHANNEL 0
#define GPIO8 7

// MCP3008 command and data format
#define MCP3008_CMD_START 0x01
#define MCP3008_CMD_MODE_SINGLEENDED 0x80
#define MCP3008_CMD_END 0x00

// SPI clock frequency in Hz
#define SPI_CLOCK_FREQ 1000000

// GPIO pin constants
#define CE_GPIO GPIO8

// SPI device file descriptor
int spi_fd = -1;

// Function prototypes
void setup_spi();
int read_mcp3008(int fd, uint8_t channel);
void handle_spi_error(int error);
void classify_reading(uint16_t adc_value);
void shutdown_gracefully();

// Main function
int main() {
    struct timespec start_time;
    uint16_t adc_value;
    int retry_count = 0;
    int error_count = 0;

    // Initialize GPIO for CE pin
    gpiod_set_data_direction(GPIO8, GPIOD_DIR_OUT_INIT_LOW);
    gpiod_direction_output(GPIO8, 1);

    // Attempt to open SPI device
    if ((spi_fd = open(SPI_DEVICE, O_RDWR)) == -1) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    // Setup SPI parameters
    setup_spi();

    while (1) {
        // Get current time
        clock_gettime(CLOCK_REALTIME, &start_time);

        // Attempt to read ADC value
        retry_count = 0;
        while (retry_count < 3) {
            adc_value = read_mcp3008(spi_fd, MCP3008_CHANNEL);
            if (adc_value != 0 && adc_value != 1023) {
                break;
            } else {
                handle_spi_error(0); // Handle SPI transfer error
                retry_count++;
                usleep(100000); // 100 ms delay
            }
        }

        if (retry_count == 3) {
            fprintf(stderr, "Failed to read ADC value after 3 retries. Error count: %d\n", error_count);
            break;
        }

        // Classify the reading
        classify_reading(adc_value);

        // Log the reading with timestamp
        char timestamp[50];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.000Z", &start_time);
        fprintf(stderr, "Timestamp: %s, ADC Value: %u, Classification: %s\n", timestamp, adc_value, classify_reading(adc_value) ? "Alcohol detected! Limit exceeded." : (adc_value < 20 ? "Sobriety confirmed." : "Alcohol level within acceptable range."));

        // Sleep for 1 second
        usleep(1000000);
    }

    // Graceful shutdown
    shutdown_gracefully();

    return EXIT_SUCCESS;
}

// Function to setup SPI parameters
void setup_spi() {
    struct spi_ioc_transfer transfers[] = {
        // Start condition, command, data, clock polarity, clock phase, timeout
        {
            .tx_buf = (unsigned long)&MCP3008_CMD_START,
            .rx_buf = NULL,
            .len = sizeof(MCP3008_CMD_START),
            .speed_hz = SPI_CLOCK_FREQ,
            .bits_per_word = 8,
            .cs_change = 1,
            .delay_usecs = 0,
        },
        {
            .tx_buf = (unsigned long)&(MCP3008_CMD_MODE_SINGLEENDED | (MCP3008_CHANNEL << 4)),
            .rx_buf = NULL,
            .len = 3,
            .speed_hz = SPI_CLOCK_FREQ,
            .bits_per_word = 8,
            .cs_change = 1,
            .delay_usecs = 0,
        },
        {
            .tx_buf = (unsigned long)&MCP3008_CMD_END,
            .rx_buf = NULL,
            .len = sizeof(MCP3008_CMD_END),
            .speed_hz = SPI_CLOCK_FREQ,
            .bits_per_word = 8,
            .cs_change = 1,
            .delay_usecs = 0,
        },
    };

    int ntransfers = sizeof(transfers) / sizeof(transfers[0]);

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_CLOCK_FREQ) < 0) {
        perror("Failed to set SPI clock frequency");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &0x01) < 0) {
        perror("Failed to set SPI mode to 0");
        exit(EXIT_FAILURE);
    }

    if (gpiod_set_value(GPIO8, 0) < 0) {
        perror("Failed to deassert CE");
        exit(EXIT_FAILURE);
    }

    if (spi_write_transfer(transfers, ntransfers) < 0) {
        perror("Failed to send SPI commands");
        exit(EXIT_FAILURE);
    }

    if (gpiod_set_value(GPIO8, 1) < 0) {
        perror("Failed to assert CE");
        exit(EXIT_FAILURE);
    }
}

// Function to read MCP3008 ADC value
int read_mcp3008(int fd, uint8_t channel) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)&(MCP3008_CMD_MODE_SINGLEENDED | (channel << 4)),
        .rx_buf = (unsigned long)&adc_value,
        .len = 3,
        .speed_hz = SPI_CLOCK_FREQ,
        .bits_per_word = 8,
        .cs_change = 1,
        .delay_usecs = 0,
    };

    if (spi_write_transfer(&transfer, 1) < 0) {
        perror("Failed to read from MCP3008");
        return -1;
    }

    return adc_value;
}

// Handle SPI transfer errors
void handle_spi_error(int error) {
    fprintf(stderr, "SPI transfer error: %d\n", error);
    error_count++;
}

// Classify the ADC reading
void classify_reading(uint16_t adc_value) {
    if (adc_value > 50) {
        fprintf(stderr, "Alcohol detected! Limit exceeded.\n");
    } else if (adc_value < 20) {
        fprintf(stderr, "Sobriety confirmed.\n");
    } else {
        fprintf(stderr, "Alcohol level within acceptable range.\n");
    }
}

// Function to handle SIGINT/SIGTERM for graceful shutdown
void shutdown_gracefully() {
    gpiod_set_data_direction(GPIO8, GPIOD_DIR_INIT_NONE); // Release GPIO
