        perror("Failed to set SPI mode to 0");
        exit(EXIT_FAILURE);
    }

    if (gpiod_set_value(GPIO8, 0) < 0) {
        perror("Failed to deassert CE");
        exit(EXIT_FAILURE);
    }

    if (spi_write_transfer(transfers, ntransfers) < 0) {
        perror("Failed to send SPI commands");
        exit(EXIT_FAILURE);
    }

    if (gpiod_set_value(GPIO8, 1) < 0) {
        perror("Failed to assert CE");
        exit(EXIT_FAILURE);
    }
}

// Function to read MCP3008 ADC value
int read_mcp3008(int fd, uint8_t channel) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)&(MCP3008_CMD_MODE_SINGLEENDED | (channel << 4)),
        .rx_buf = (unsigned long)&adc_value,
        .len = 3,
        .speed_hz = SPI_CLOCK_FREQ,
        .bits_per_word = 8,
        .cs_change = 1,
        .delay_usecs = 0,
    };

    if (spi_write_transfer(&transfer, 1) < 0) {
        perror("Failed to read from MCP3008");
        return -1;
    }

    return adc_value;
}

// Handle SPI transfer errors
void handle_spi_error(int error) {
    fprintf(stderr, "SPI transfer error: %d\n", error);
    error_count++;
}

// Classify the ADC reading
void classify_reading(uint16_t adc_value) {
    if (adc_value > 50) {
        fprintf(stderr, "Alcohol detected! Limit exceeded.\n");
    } else if (adc_value < 20) {
        fprintf(stderr, "Sobriety confirmed.\n");
    } else {
        fprintf(stderr, "Alcohol level within acceptable range.\n");
    }
}

// Function to handle SIGINT/SIGTERM for graceful shutdown
void shutdown_gracefully() {
    gpiod_set_data_direction(GPIO8, GPIOD_DIR_INIT_NONE); // Release GPIO
    close(spi_fd); // Close SPI device
    gpiod_cleanup(); // Clean up GPIO resources
}

