int main() {
    // Initialize global variables
    pid_t pi_pid = -1;
    int sensor_value = -1;

    // Signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Attempt to initialize pigpio
    setup_pigpio();

    // Setup SPI and MCP3008
    setup_spi();

    // Main loop
    while (1) {
        // Read sensor every 60 seconds
        struct timespec ts = { .tv_sec = 60, .tv_nsec = 0 };
        nanosleep(&ts, NULL);

        // Read sensor value
        sensor_value = read_sensor();

        // Handle pump status based on moisture level
        handle_pump_status(sensor_value);

        // Log sensor reading and pump status
        log_data(sensor_value, "ON" /* or "OFF" */);

        // Sleep for 1 second to avoid excessive logging
        usleep(1000000);
    }

    // Clean up on exit
    cleanup();

    return 0;
}

// Function to initialize pigpio
void setup_pigpio() {
    pi_pid = fork();

    if (pi_pid == 0) {
        // Child process: initialize pigpio
        if (pigpio_init() < 0) {
            fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error());
            exit(EXIT_FAILURE);
        }

        // Keep the child process alive
        while (1) {}
    } else {
        // Parent process: wait for child
        waitpid(pi_pid, NULL, 0);
    }
}

// Function to setup SPI and MCP3008
void setup_spi() {
    // Open SPI device
    int spi_fd = open("/dev/spidev0.0", O_RDWR);

    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Configure SPI
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set clock frequency
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_CLOCK_FREQ) < 0) {
        fprintf(stderr, "Failed to set SPI clock frequency: %s\n", strerror(errno));
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set chip select pin
    if (gpio_mode_set(GPIO8, GPIO_OUT) < 0) {
        fprintf(stderr, "Failed to set GPIO8 as output: %s\n", strerror(errno));
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
    gpio_set(GPIO8);

    // Open MCP3008
    if (open("/dev/mcp3008", O_RDWR) < 0) {
        fprintf(stderr, "Failed to open MCP3008: %s\n", strerror(errno));
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
}

// Function to read sensor value
int read_sensor() {
    int value = 0;

    // Write to MCP3008 to start conversion
    if (write(0, &MCP3008_CHANNEL, 1) != 1) {
        fprintf(stderr, "Failed to write to MCP3008: %s\n", strerror(errno));
        return -1;
    }

    // Wait for conversion to complete
    usleep(100);

    // Read the result
    if (read(0, &value, 1) != 1) {
        fprintf(stderr, "Failed to read from MCP3008: %s\n", strerror(errno));
        return -1;
    }

    return value;
}

// Function to handle pump status based on moisture level
void handle_pump_status(int value) {
    if (value < THRESHOLD_VALUE) {
        // Turn on the pump
        if (gpio_mode_set(GPIO18, GPIO_OUT) < 0) {
            fprintf(stderr, "Failed to set GPIO18 as output: %s\n", strerror(errno));
        } else {
            gpio_set(GPIO18); // Activate relay to turn on the pump
        }
    } else {
        // Turn off the pump
        if (gpio_mode_set(GPIO18, GPIO_IN) < 0) {
            fprintf(stderr, "Failed to set GPIO18 as input: %s\n", strerror(errno));
        } else {
            gpio_clear(GPIO18); // Deactivate relay to turn off the pump
        }
    }
}

// Function to cleanup resources
void cleanup() {
    // Turn off the pump
    handle_pump_status(-1);

    // Close SPI device and release GPIOs
    close(spi_fd);
    gpio_clear(GPIO8);

    // Close MCP3008
    close(0);

    // Close log file descriptor
    if (log_fd != -1) {
        close(log_fd);
    }

    // Clean up pigpio
    if (pi_pid != -1) {
        kill(pi_pid, SIGTERM);
        waitpid(pi_pid, NULL, 0);
    }
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    // Log the signal received
    fprintf(stderr, "Received signal %d, terminating...\n", signum);

    // Perform cleanup
    cleanup();

    // Exit the program
    exit(EXIT_FAILURE);
}

// Function to log sensor reading and pump status
void log_data(int value, const char *status) {
    char buffer[256];
    time_t now = time(NULL);
    struct tm timeinfo;
    char timestamp[20];

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    // Append to the log file
    if (log_fd == -1) {
        log_fd = fopen("irrigation.log", "a+");
        if (log_fd == NULL) {
            fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
            exit(EXIT_FAILURE);
        }
    }

    // Write to log file
    fprintf(log_fd, "%s: Sensor value: %d, Pump status: %s\n", timestamp, value, status);

    // Flush log buffer
    fflush(log_fd);
}

