        fprintf(stderr, "Failed to set MCP3008 MOSI pin to output: %s\n", gpio_error());
        return EXIT_FAILURE;
    }
    if (gpio_mode(MCP3008_MISO, GPIO_IN) == -1) {
        fprintf(stderr, "Failed to set MCP3008 MISO pin to input: %s\n", gpio_error());
        return EXIT_FAILURE;
    }
    if (gpio_mode(MCP3008_SCLK, GPIO_OUT) == -1) {
        fprintf(stderr, "Failed to set MCP3008 SCLK pin to output: %s\n", gpio_error());
        return EXIT_FAILURE;
    }
    if (gpio_mode(MAX9814_LED, GPIO_OUT) == -1) {
        fprintf(stderr, "Failed to set LED pin to output: %s\n", gpio_error());
        return EXIT_FAILURE;
    }

