        }
    }

    // Clean up on SIGINT
    sigint_received = 1;

    // Close SPI device and cleanup GPIO
    cleanup();

    return EXIT_SUCCESS;
}

// Function to calibrate ambient noise level
void calibrate() {
    uint16_t total = 0;
    uint32_t count = 0;
    while (count < (CALIBRATION_SAMPLES * 1000 / 1000)) {
        read_adc();
        total += adc_value;
        count++;
    }
    uint16_t average = total / (CALIBRATION_SAMPLES * 1000 / 1000);
    printf("Calibrated ambient noise level: %d\n", average);
}

// Function to read the ADC value
void read_adc() {
    uint16_t adc_value;
    if (pigpio_spiXfer(pi, SPI_DEVICE, 0x06, 0, 0, &adc_value, 1) != 1) {
        fprintf(stderr, "Failed to read ADC value: %s\n", pigpio_error());
        return;
    }
    adc_value = (adc_value << 8) | (pigpio_spiXfer(pi, SPI_DEVICE, 0x07, 0, 0, NULL, 1) >> 8);
    printf("ADC value: %d\n", adc_value);
}

// Function to debounce and trigger the LED
void debounce_and_trigger_led() {
    static int debounce_count = 0;
    if (debounce_count < DEBOUNCE_MS) {
        sleep(1);
        debounce_count++;
    } else {
        gpio_write(MAX9814_LED, 1); // Turn LED on
        debounce_count = 0; // Reset debounce counter
    }
}

// Signal handler to clean up on SIGINT
void handle_signal(int signum) {
    sigint_received = 1;
    printf("SIGINT received, cleaning up...\n");
    cleanup();
}

// Function to clean up resources
void cleanup() {
    if (pi != NULL) {
        gpio_free(MCP3008_CS);
        gpio_free(MCP3008_MOSI);
        gpio_free(MCP3008_MISO);
        gpio_free(MCP3008_SCLK);
        gpio_free(MAX9814_LED);
        pigpio_close(pi);
        pi = NULL;
    }
}

