#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <gpiod.h>
#include <spidev.h>

#define MCP3008_CS_GPIO 8
#define MCP3008_SPI_DEV "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SAMPLE_RATE_HZ 1000
#define SAMPLE_PERIOD_USEC (1000 / SAMPLE_RATE_HZ)

typedef struct {
    uint8_t rx_buf[3];
    uint8_t valid;
} MCP3008Read;

uint32_t clock_gettime(clockid_t clk_id, struct timespec *tp) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    tp->tv_sec = tv.tv_sec;
    tp->tv_nsec = tv.tv_usec * 1000;
    return 0;
}

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        gpiod_chip_release(MCP3008_CS_GPIO);
        close(MCP3008_SPI_DEV);
        fclose(stderr);
        exit(0);
    }
}

int main() {
    int spi_fd;
    struct spi_ioc_transfer transfers[2];
    uint32_t timestamp;
    uint8_t adc_value;
    char *log_file = "audio_log.txt";
    FILE *log = fopen(log_file, "a+");
    if (!log) {
        perror("fopen(log_file)");
        return EXIT_FAILURE;
    }

    gpiod_chip_request(MCP3008_CS_GPIO);
    if (gpiod_line_get_data(MCP3008_CS_GPIO) < 0) {
        perror("Failed to get GPIO data");
        gpiod_chip_release(MCP3008_CS_GPIO);
        fclose(log);
        return EXIT_FAILURE;
    }

    transfers[0].tx_buf = (uint8_t[]){0x01, 0x08 | 0x01, 0x00}; // Start bit, config (CH0), dummy
    transfers[0].rx_buf = (uint8_t[3]);
    transfers[0].len = 3;
    transfers[0].delay_usecs = 10;

    transfers[1].tx_buf = NULL;
    transfers[1].rx_buf = NULL;
    transfers[1].len = 0;
    transfers[1].delay_usecs = 0;

    spi_fd = open(MCP3008_SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("open(MCP3008_SPI_DEV)");
        gpiod_chip_release(MCP3008_CS_GPIO);
        fclose(log);
        return EXIT_FAILURE;
    }

    struct spi_msg mcp3008_cmd = {
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .cs_change = 1,
        .clock_polarity = SPI_POLARITY_HIGH,
        .clock_phase = SPI_PHASE_FIRST,
        .mode = SPI_MODE,
    };

    while (1) {
        timestamp = clock_gettime(CLOCK_MONOTONIC_RAW, &MCP3008Read::valid);
        if (!MCP3008Read::valid) {
            continue;
        }

        transfers[0].tx_buf[0] = 0x01; // Start bit
        transfers[0].tx_buf[1] = (uint8_t)((0x08 | 0x01) << 4); // CH0, single-ended
        transfers[0].tx_buf[2] = 0x00; // Dummy

        if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &mcp3008_cmd.speed_hz) < 0) {
            perror("SPI_IOC_WR_MAX_SPEED_HZ");
            close(spi_fd);
            gpiod_chip_release(MCP3008_CS_GPIO);
            fclose(log);
            return EXIT_FAILURE;
        }

        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfers) < 0) {
            perror("SPI transfer failed");
            close(spi_fd);
            gpiod_chip_release(MCP3008_CS_GPIO);
            fclose(log);
            return EXIT_FAILURE;
        }

        adc_value = transfers[0].rx_buf[1] | (transfers[0].rx_buf[2] << 4);
        fprintf(log, "%lu|%u\n", (unsigned long)timestamp, adc_value);

        nanosleep(&SAMPLE_PERIOD_USEC, NULL);

        gpiod_chip_release(MCP3008_CS_GPIO);
    }

    close(spi_fd);
    fclose(log);

    return EXIT_SUCCESS;
}

