// Define constants for MCP3008 and ADXL335
#define MCP_CS   8
#define MCP_MOSI 10
#define MCP_MISO 9
#define MCP_SCLK 11
#define ADXL_XOUT 0
#define ADXL_YOUT 1
#define ADXL_ZOUT 2
#define REF_VOLTAGE 3300 // 3.3V reference voltage

