#define SPI_BIT_ORDER MSB_FIRST
#define SPI_CLOCK_POLARITY RISING_EDGE

// Kalman filter parameters
#define KF_STATE_SIZE 1
#define KF observation noise std dev 0.01 // 1% of full scale g
#define KF process noise std dev 0.001 // 0.1% of full scale g

