double gain;

// MCP3008 SPI initialization function
pigpio *gp;
int spi_init() {
    if (gp == NULL) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return -1;
    }

    // Configure GPIO pins
    if (pigpio_direction(gp, MCP_CS, pigpio OUTPUT) != PIGPIO_OK) {
        fprintf(stderr, "Failed to set MCP3008 CS pin as output.\n");
        return -1;
    }

    if (pigpio_direction(gp, MCP_MOSI) != pigpio OUTPUT) {
        fprintf(stderr, "Failed to set MCP3008 MOSI pin as output.\n");
        return -1;
    }

    if (pigpio_direction(gp, MCP_MISO) != pigpio INPUT) {
        fprintf(stderr, "Failed to set MCP3008 MISO pin as input.\n");
        return -1;
    }

    if (pigpio_direction(gp, MCP_SCLK) != pigpio OUTPUT) {
        fprintf(stderr, "Failed to set MCP3008 SCLK pin as output.\n");
        return -1;
    }

    // Initialize SPI
    if (pigpio_spi_init(gp, SPI_MODE, SPI_BIT_ORDER, SPI_CLOCK_POLARITY) != PIGPIO_OK) {
        fprintf(stderr, "Failed to initialize SPI.\n");
        return -1;
    }

    return 0;
}

// MCP3008 SPI read function
int adc_read(uint8_t channel) {
    int result;

    // Set CS low to select the MCP3008
    pigpio_write(gp, MCP_CS, 0);

    // Start SPI transaction
    result = pigpio_spi_transfer(gp, channel, 0x80, 0);

    // Check for SPI bus error
    if (result != 0) {
        fprintf(stderr, "SPI bus error during ADC read.\n");
        return -1;
    }

    // Set CS high to deselect the MCP3008
    pigpio_write(gp, MCP_CS, 1);

    return result;
}

// Convert ADC reading to acceleration (mV/g) and apply Kalman filter
double convert_adc_to_accel(uint8_t adc) {
    double voltage = (adc / 1023.0) * REF_VOLTAGE;
    double acceleration = (voltage - 1500.0) / 300.0; // 300 mV/g sensitivity, 1.5V zero-g bias

    // Apply Kalman filter
    double kalman_prediction = state[0];
    double kalman_measurement = acceleration;

    gain = 0.98; // Tuning parameter for Kalman filter

    state[0] = (gain * kalman_prediction + (1 - gain) * kalman_measurement) + (gain * (kalman_measurement - kalman_prediction));

    return state[0];
}

