        return EXIT_FAILURE;
    }

    if (spi_init() != 0) {
        fprintf(stderr, "SPI initialization failed.\n");
        pigpio_close(gp);
        return EXIT_FAILURE;
    }

    while (!should_exit) {
        // Read ADC values for X, Y, Z
        uint8_t x_adc = adc_read(ADXL_XOUT);
        uint8_t y_adc = adc_read(ADXL_YOUT);
        uint8_t z_adc = adc_read(ADXL_ZOUT);

