#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod/gpiolib.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>

#define VCC 3300  // 3.3V in mV
#define V_QUIESCENT 1650  // 1.65V in mV
#define SENSITIVITY 25  // 25 mV/mT
#define DELAY_MS 100  // Sample interval in milliseconds

// GPIO pins for the Hall effect sensors
#define GPIO_HALL1 4
#define GPIO_HALL2 17
#define GPIO_HALL3 27

// File path for logging
#define LOG_FILE_PATH "magnetic_log.txt"

// Function prototypes
void setup_gpios();
void read_hall_sensors();
void handle_signal(int signum);
void cleanup();

int main() {
    // Initialize signal handler for SIGINT
    signal(SIGINT, handle_signal);

    // Setup GPIOs
    setup_gpios();

    // Main loop
    while (1) {
        read_hall_sensors();
        usleep(DELAY_MS * 1000);  // Wait for the specified delay
    }

    // Cleanup on exit
    cleanup();

    return 0;
}

// Function to set up GPIO pins
void setup_gpios() {
    int gpio_hall1, gpio_hall2, gpio_hall3;

    // Request GPIO lines for input
    gpio_hall1 = gpiod_line_request_input(GPIO_HALL1, GPIOD_DIR_IN);
    if (gpio_hall1 < 0) {
        fprintf(stderr, "Error requesting GPIO %d: %s\n", GPIO_HALL1, strerror(errno));
        return;
    }

    gpio_hall2 = gpiod_line_request_input(GPIO_HALL2, GPIOD_DIR_IN);
    if (gpio_hall2 < 0) {
        fprintf(stderr, "Error requesting GPIO %d: %s\n", GPIO_HALL2, strerror(errno));
        gpiod_line_release(gpio_hall1);
        return;
    }

    gpio_hall3 = gpiod_line_request_input(GPIO_HALL3, GPIOD_DIR_IN);
    if (gpio_hall3 < 0) {
        fprintf(stderr, "Error requesting GPIO %d: %s\n", GPIO_HALL3, strerror(errno));
        gpiod_line_release(gpio_hall1);
        gpiod_line_release(gpio_hall2);
        return;
    }

    // Successfully requested GPIOs, proceed with reading
}

// Function to read Hall effect sensors and log data
void read_hall_sensors() {
    FILE *log_file = fopen(LOG_FILE_PATH, "a+");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    float sensor1_mT, sensor2_mT, sensor3_mT;

    // Read GPIO values (HIGH = 3.3V, LOW = 0.0V)
    int hall1_value = gpiod_read(gpio_hall1);
    int hall2_value = gpiod_read(gpio_hall2);
    int hall3_value = gpiod_read(gpio_hall3);

    // Calculate V_out for each sensor
    float v_out1 = (hall1_value == 1) ? VCC : 0.0;
    float v_out2 = (hall2_value == 1) ? VCC : 0.0;
    float v_out3 = (hall3_value == 1) ? VCC : 0.0;

    // Compute magnetic field strength in mT
    sensor1_mT = (v_out1 - V_QUIESCENT) / SENSITIVITY;
    sensor2_mT = (v_out2 - V_QUIESCENT) / SENSITIVITY;
    sensor3_mT = (v_out3 - V_QUIESCENT) / SENSITIVITY;

    // Check for valid readings and log data
    if (sensor1_mT >= -100 && sensor1_mT <= 100) {
        fprintf(log_file, "%f,%f,%f\n", sensor1_mT, sensor2_mT, sensor3_mT);
    } else {
        fprintf(stderr, "Warning: Sensor 1 reading out of range (-100 mT to +100 mT)\n");
    }

    if (sensor2_mT >= -100 && sensor2_mT <= 100) {
        fprintf(log_file, "%f,%f,%f\n", sensor1_mT, sensor2_mT, sensor3_mT);
    } else {
        fprintf(stderr, "Warning: Sensor 2 reading out of range (-100 mT to +100 mT)\n");
    }

    if (sensor3_mT >= -100 && sensor3_mT <= 100) {
        fprintf(log_file, "%f,%f,%f\n", sensor1_mT, sensor2_mT, sensor3_mT);
    } else {
        fprintf(stderr, "Warning: Sensor 3 reading out of range (-100 mT to +100 mT)\n");
    }

    // Flush the log file after each write
    fflush(log_file);

    // Release GPIO lines on exit or error
    gpiod_line_release(gpio_hall1);
    gpiod_line_release(gpio_hall2);
    gpiod_line_release(gpio_hall3);
}

// Function to handle SIGINT (Ctrl+C)
void handle_signal(int signum) {
    // Clean up and exit
    fclose(LOG_FILE_PATH);
    cleanup();
    exit(0);
}

// Function to clean up resources
void cleanup() {
    // Release all remaining resources
    gpiod_line_release(gpio_hall1);
    gpiod_line_release(gpio_hall2);
    gpiod_line_release(gpio_hall3);
}

