#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>

// Define GPIO pins
#define MCP3008_CS GPIO_NUM_18 // SPI CE0 on Raspberry Pi 4
#define MCP3008_MISO GPIO_NUM_23
#define MCP3008_MOSI GPIO_NUM_19
#define MCP3008_SCLK GPIO_NUM_21
#define WATER_PUMP_GPIO GPIO_NUM_17

// MCP3008 configuration
#define MCP3008_CHANNEL 0
#define MCP3008_MODE 0 // Single-ended mode

// Threshold for water pump activation
#define MOISTURE_THRESHOLD 30

// Function prototypes
void setup_pigpio();
void setup_spi();
void read_mcp3008();
void handle_water_pump(int state);
void cleanup();
void signal_handler(int signum);

int main() {
    // Initialize global variables
    FILE *log_file = NULL;
    pid_t pi_pid = 0;
    int moisture_level;
    int pump_state = 0;

    // Signal handler for clean shutdown
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        // Open log file for writing
        if ((log_file = fopen("watering.log", "a")) == NULL) {
            fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
            break;
        }

        // Start pigpio daemon and get its PID
        if ((pi_pid = pigpio_start()) == -1) {
            fprintf(stderr, "Failed to start pigpio: %s\n", pigpio_error());
            break;
        }

        // Setup SPI and MCP3008
        setup_spi();

        // Read moisture sensor
        if (read_mcp3008()) {
            moisture_level = (uint16_t)(MCP3008_READ & 0x3FF) / 1024.0;
            if (moisture_level < MOISTURE_THRESHOLD) {
                handle_water_pump(1);
            } else {
                handle_water_pump(0);
            }
        } else {
            fprintf(log_file, "Error reading MCP3008: %s\n", pigpio_error());
        }

        // Sleep for 60 seconds
        sleep(60);

        // Cleanup before next iteration
        cleanup();
    }

    // Ensure pump is off on exit
    handle_water_pump(0);

    // Close log file and exit
    fclose(log_file);
    pigpio_stop(pi_pid);
    exit(EXIT_SUCCESS);
}

// Function to setup pigpio
void setup_pigpio() {
    if (pigpio_read(pi_pid, GPIO_WPU_PUMP, &pump_state) == 0) {
        fprintf(stderr, "Error reading pump state: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }
}

// Function to setup SPI
void setup_spi() {
    if (pigpio_spi_setup(MCP3008_CS, MCP3008_MISO, MCP3008_MOSI, MCP3008_SCLK, MCP3008_MODE) == -1) {
        fprintf(stderr, "Failed to setup SPI: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }
}

// Function to read MCP3008
int read_mcp3008() {
    uint16_t data;
    if (pigpio_spi_transfer(MCP3008_CS, MCP3008_MODE, MCP3008_CHANNEL, &data) == -1) {
        fprintf(stderr, "Error reading MCP3008: %s\n", pigpio_error());
        return 0;
    }
    return 1;
}

// Function to handle water pump state
void handle_water_pump(int state) {
    if (state) {
        fprintf(log_file, "Water pump turned ON at %s\n", ctime(&time(NULL)));
    } else {
        fprintf(log_file, "Water pump turned OFF at %s\n", ctime(&time(NULL)));
    }
}

// Function to cleanup resources
void cleanup() {
    pigpio_free();
}

// Signal handler for clean shutdown
void signal_handler(int signum) {
    fprintf(log_file, "Received signal (%d), shutting down...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

