        setup_spi();

        // Read moisture sensor
        if (read_mcp3008()) {
            moisture_level = (uint16_t)(MCP3008_READ & 0x3FF) / 1024.0;
            if (moisture_level < MOISTURE_THRESHOLD) {
                handle_water_pump(1);
            } else {
                handle_water_pump(0);
            }
        } else {
            fprintf(log_file, "Error reading MCP3008: %s\n", pigpio_error());
        }

        // Sleep for 60 seconds
        sleep(60);

        // Cleanup before next iteration
        cleanup();
    }

    // Ensure pump is off on exit
    handle_water_pump(0);

    // Close log file and exit
    fclose(log_file);
    pigpio_stop(pi_pid);
    exit(EXIT_SUCCESS);
}

