    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    // Set SPI mode and speed
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) == -1) {
        perror("ioctl: SPI_IOC_WR_MODE");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BAUDRATE, &SPI_SPEED) == -1) {
        perror("ioctl: SPI_IOC_WR_BAUDRATE");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Setup MCP3008
    setup_spi();

    // Main loop to read and log data
    while (1) {
        uint8_t channels_to_read[3] = {0, 1, 2}; // Channels 0, 1, 2
        struct timeval start, end;
        double interval;

        // Start timer
        gettimeofday(&start, NULL);

        // Read channels and log data
        for (uint8_t i = 0; i < CHANNELS; ++i) {
            uint16_t value = read_mcp3008_channel(channels_to_read[i]);
            fprintf(stderr, "Reading channel %u: %04x\n", channels_to_read[i], value);
            // Write to CSV file
            fprintf(stderr, "%d,%04x\n", start.tv_sec + i, value);
        }

        // End timer
        gettimeofday(&end, NULL);

        // Calculate interval and sleep
        interval = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_usec - start.tv_usec);
        sleep(1); // Sleep for 1 second
    }

    // Handle SIGINT
    handle_signal(SIGINT);

    // Close SPI device and release resources
    close(spi_fd);
    return 0;
}

// Function to setup SPI
void setup_spi() {
    // Set the chip select pin (CE0)
    int ce_fd = open("/sys/class/gpio/export", O_WRONLY);
    if (ce_fd == -1) {
        perror("open /sys/class/gpio/export");
        exit(EXIT_FAILURE);
    }
    write(ce_fd, "0", 2); // Export GPIO 0 as CE0
    close(ce_fd);

    int ce_gpio = gpio_export(0, GPIO_EXPORT_DIR_OUT);
    if (ce_gpio == -1) {
        perror("gpio_export");
        exit(EXIT_FAILURE);
    }

    // Set CE0 as output
    if (gpio_direction_output(ce_gpio, 1) == -1) {
        perror("gpio_direction_output");
        gpio_unexport(ce_gpio);
        exit(EXIT_FAILURE);
    }

    gpio_unexport(ce_gpio); // Unexport CE0 GPIO
}

// Function to read a single MCP3008 channel
int read_mcp3008_channel(uint8_t channel) {
    uint8_t cmd = MCP3008_CMD | (MCP3008_SINGLEENDED_MODE | (channel << 4));
    uint16_t value;

    // Write command to MCP3008
    if (write(spi_fd, &cmd, 1) != 1) {
        perror("write to MCP3008");
        return 0; // Return 0 on error
    }

    // Read 10-bit value
    if (read(spi_fd, &value, 2) != 2) {
        perror("read from MCP3008");
        return 0; // Return 0 on error
    }

    return ((value >> 4) & 0x0f) | (value & 0x0f);
}

// Signal handler for SIGINT
void handle_signal(int signum) {
    // Close the CSV file (if it was opened)
    fclose(stderr);

    // Release SPI resources
    close(spi_fd);

    // Exit gracefully
    exit(EXIT_SUCCESS);
}

