#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <sys/time.h>
#include <pico.h>
#include <mosquitto.h>
#include <cjson.h>

#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT "1883"
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_QOS 0
#define GPIO_PIN 17

// Signal handler prototypes
void handleSignal(int signum);

// MQTT callback function
void onMessage(const struct mosquitto_message *msg, void *payload) {
    cJSON *root = cJSON_Parse((char *)msg->payload);
    if (!root || cJSON_GetObjectItemCaseSensitive(root, "led_state") == NULL) {
        fprintf(stderr, "Invalid MQTT message format. Expected 'led_state' boolean.\n");
        cJSON_Delete(root);
        return;
    }

    bool ledState = cJSON_GetObjectNumberValue(cJSON_GetObjectItemCaseSensitive(root, "led_state"));
    if (ledState == TRUE) {
        gpioWrite(GPIO_PIN, 1); // Turn LED on
    } else {
        gpioWrite(GPIO_PIN, 0); // Turn LED off
    }

    cJSON_Delete(root);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Set GPIO17 as output and turn off the LED
    if (gpioSetMode(GPIO_PIN, GPIO_OUTPUT) == -1) {
        fprintf(stderr, "Failed to set GPIO17 as output: %s\n", strerror(errno));
        gpioTerminate(); // Clean up and exit
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_PIN, 0); // Turn off the LED

    // Initialize mosquitto
    mosquitto_connect_options opts = MOSQUITTO_CONNECT_DEFAULT;
    opts.callback = onMessage;
    opts.username_pw_set = 1;
    opts.username = "rpi_led_control";
    opts.password = "your_password"; // Replace with your MQTT password

    if (mosquitto_connect(NULL, MQTT_BROKER, MQTT_PORT, &opts) == 0) {
        fprintf(stderr, "Connected to MQTT broker.\n");
    } else {
        fprintf(stderr, "Failed to connect to MQTT broker: %s\n", mosquitto_last_error());
        return EXIT_FAILURE;
    }

    // Signal handler for clean shutdown
    struct sigaction sa;
    sa.sa_handler = handleSignal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main MQTT loop with exponential backoff reconnection
    int attempts = 0;
    while (1) {
        // Attempt to reconnect
        if (mosquitto_loop_start(NULL) == 0) {
            break; // Successfully reconnected
        }

        // Exponential backoff
        int delay = 1;
        do {
            fprintf(stderr, "Reconnection attempt %d failed, waiting %d seconds...\n", attempts, delay);
            sleep(delay);
            delay *= 2; // Exponential growth
        } while (delay <= 60);

        attempts++;
    }

    // Clean shutdown on SIGINT or SIGTERM
    handleSignal(SIGINT);
    handleSignal(SIGTERM);

    // Disconnect from MQTT
    mosquitto_disconnect(NULL, -1);

    // Turn off the LED
    gpioWrite(GPIO_PIN, 0);

    // Release pigpio resources
    gpioTerminate();

    return EXIT_SUCCESS;
}

// Signal handler to clean up and exit
void handleSignal(int signum) {
    fprintf(stderr, "Received signal %d, shutting down...\n", signum);
    // Perform necessary cleanup actions here if needed
    // For simplicity, this example directly exits; in a more complex program, you'd handle resources.
    exit(EXIT_FAILURE);
}

