#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

#define SOUND_SENSOR_GPIO 17
#define ALARM_LED_GPIO 18

volatile int alarm_triggered = 0;

void setup_gpios(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *sound_sensor_line, *alarm_led_line;

    // Initialize libgpiod
    if ((chip = gpiod_chip_open(GPIOD_ANY_ID, GPIOD_FLAG_NO_WAIT)) == NULL) {
        fprintf(stderr, "Failed to open GPIO chip.\n");
        exit(EXIT_FAILURE);
    }

    // Request the sound sensor GPIO line
    if ((sound_sensor_line = gpiod_line_request_one(chip, SOUND_SENSOR_GPIO, GPIOD_LINE_IN)) == NULL) {
        fprintf(stderr, "Failed to request GPIO %u.\n", SOUND_SENSOR_GPIO);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request the alarm LED GPIO line
    if ((alarm_led_line = gpiod_line_request_one(chip, ALARM_LED_GPIO, GPIOD_LINE_OUT_LOW)) == NULL) {
        fprintf(stderr, "Failed to request GPIO %u.\n", ALARM_LED_GPIO);
        gpiod_line_release(sound_sensor_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO lines for the sound sensor and alarm LED
    gpiod_line_config(sound_sensor_line, GPIOD_LINE_CONFIG_INPUT);
    gpiod_line_config(alarm_led_line, GPIOD_LINE_CONFIG_OUTPUT);

    // Set alarm LED GPIO line to low initially
    gpiod_line_value(alarm_led_line, 0);

    printf("Sound sensor reading: %d\n", gpiod_line_value_read(sound_sensor_line) ? 1 : 0);
}

void handle_alarm_triggered() {
    alarm_triggered = 1;
    gpiod_line_value(alarm_led_line, 1); // Turn LED ON
    sleep(1); // Keep LED ON for 1 second
    gpiod_line_value(alarm_led_line, 0); // Turn LED OFF
}

void cleanup_gpios(void) {
    gpiod_line_release(sound_sensor_line);
    gpiod_line_release(alarm_led_line);
    gpiod_chip_close(chip);
}

int main(void) {
    signal(SIGINT, SIG_IGN); // Ignore SIGINT to avoid double cleanup
    signal(SIGTERM, cleanup_gpios); // Clean up on SIGTERM

    setup_gpios();

    while (1) {
        if (gpiod_line_value_read(sound_sensor_line) == 0) {
            handle_alarm_triggered();
        }

        usleep(100000); // 100 ms delay

        // Check for Ctrl+C or Ctrl+Z
        if (signal(SIGINT, SIG_IGN) == SIG_ERR) {
            // SIGINT received, clean up and exit
            cleanup_gpios();
            exit(EXIT_SUCCESS);
        }
    }

    return 0;
}

