        return EXIT_FAILURE;
    }

    // Attempt to open the GPIO chip
    struct gpiod_chip *chip;
    if ((chip = gpiod_chip_open("/dev/gpiochip0", GPIOD_OPEN_FLAG_NONE)) == NULL) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request GPIO line 17
    struct gpiod_line *line;
    if ((line = gpiod_line_request(chip, 17, GPIOD_LINE_REQUEST_MODE_INPUT, "vibration-monitor")) == NULL) {
        perror("Failed to request GPIO line 17");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up falling-edge event detection
    if (gpiod_line_event_request(line, GPIOD_LINE_EVENT_FALLING_EDGE) < 0) {
        perror("Failed to request falling-edge events");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!shutdown_requested) {
        // Wait for a falling-edge event
        struct gpiod_line_event event;
        if (gpiod_line_event_wait(line, &event) < 0) {
            perror("Failed to wait for event");
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        // Read the event
        if (gpiod_line_event_read(line, &event) < 0) {
