#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>
#include <gpiod.h>

#define BMP280_ADDR 0x76
#define BMP280_CTRL_MEAS_REG 0xF4
#define BMP280_PRESSURE_REG 0xF7
#define BMP280_TEMP_REG 0xFA
#define BMP280_ID_REG 0xD0

// Calibration data from datasheet (in hex)
uint8_t bmp280_calib_data[] = {0x1A, 0x2C, 0x33, 0x4E, 0x76, 0x1A, 0x2C, 0x33};

// Function prototypes
void initialize_pigpio();
void read_bmp280_data(gpiod_i2c_handle_t *i2c_handle, uint8_t *pressure, uint16_t *temperature);
void apply_bosch_compensation(uint16_t adcPressure, uint16_t adcTemperature, uint16_t *compensatedPressure, uint16_t *compensatedTemperature);
void compute_altitude(float compensatedPressure, float compensatedTemperature, float *altitude);
void write_to_log_file(const char *message);
void cleanup_resources();

int main() {
    // Initialize pigpio
    initialize_pigpio();

    // Open I2C bus 1
    gpiod_i2c_handle_t *i2c_handle = gpiod_i2c_open(1, GPIOD_I2C_SPEED_100KHZ);
    if (i2c_handle == NULL) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        return EXIT_FAILURE;
    }

    // Check BMP280 ID register
    uint8_t id_reg;
    if (gpiod_i2c_read(i2c_handle, BMP280_ADDR, BMP280_ID_REG, &id_reg, 1) != 1) {
        fprintf(stderr, "Failed to read BMP280 ID register\n");
        gpiod_i2c_close(i2c_handle);
        return EXIT_FAILURE;
    }
    if (id_reg != 0x58) {
        fprintf(stderr, "BMP280 chip ID is incorrect (expected 0x58)\n");
        gpiod_i2c_close(i2c_handle);
        return EXIT_FAILURE;
    }

    // Read calibration data
    uint8_t calibration_data[6];
    if (gpiod_i2c_read(i2c_handle, BMP280_ADDR, BMP280_CTRL_MEAS_REG, calibration_data, 6) != 6) {
        fprintf(stderr, "Failed to read BMP280 calibration data\n");
        gpiod_i2c_close(i2c_handle);
        return EXIT_FAILURE;
    }

    // Apply calibration and configure control register
    memcpy(bmp280_calib_data, calibration_data, 6);
    apply_bosch_compensation(0, 0, &bmp280_compensated_pressure, &bmp280_compensated_temperature);
    uint8_t config_reg = bmp280_compensated_temperature >> 6;
    if (gpiod_i2c_write(i2c_handle, BMP280_ADDR, BMP280_CTRL_MEAS_REG, config_reg) != 1) {
        fprintf(stderr, "Failed to write to BMP280 control register\n");
        gpiod_i2c_close(i2c_handle);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Read pressure and temperature
        uint16_t raw_pressure;
        uint16_t raw_temperature;
        if (gpiod_i2c_read(i2c_handle, BMP280_ADDR, BMP280_PRESSURE_REG, &raw_pressure, 1) != 1 ||
            gpiod_i2c_read(i2c_handle, BMP280_ADDR, BMP280_TEMP_REG, &raw_temperature, 1) != 1) {
            fprintf(stderr, "Failed to read BMP280 raw data\n");
            break;
        }

        apply_bosch_compensation(raw_pressure, raw_temperature, &compensated_pressure, &compensated_temperature);

        // Compute altitude
        float compensated_temperature_c = compensated_temperature / 1000.0; // Convert to Celsius
        float altitude;
        compute_altitude(compensated_pressure, compensated_temperature_c, &altitude);

        // Log data
        char timestamp[50];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        write_to_log_file("Altitude: %.2f m, Temp: %.1f °C at %s\n", altitude, compensated_temperature_c, timestamp);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Cleanup resources
    cleanup_resources();

    return EXIT_SUCCESS;
}

// Function to initialize pigpio
void initialize_pigpio() {
    pigpiod *pi = NULL;
    if ((pi = pigpio_open()) == NULL) {
        fprintf(stderr, "Failed to open pigpio\n");
        return;
    }
    pigpio_set_over_voltage(pi, 1); // Ensure 3.3V logic level
    pigpio_set_mode(pi, pigpio_mode_headless); // Run headless
}

// Function to read BMP280 data
void read_bmp280_data(gpiod_i2c_handle_t *i2c_handle, uint8_t *pressure, uint16_t *temperature) {
    gpiod_i2c_write(i2c_handle, BMP280_ADDR, BMP280_PRESSURE_REG, pressure, 1);
    gpiod_i2c_read(i2c_handle, BMP280_ADDR, BMP280_TEMP_REG, temperature, 1);
}

// Function to apply Bosch compensation
void apply_bosch_compensation(uint16_t adcPressure, uint16_t adcTemperature, uint16_t *compensatedPressure, uint16_t *compensatedTemperature) {
    *compensatedPressure = adcPressure * (1.0 - bmp280_calib_data[0] * (adcTemperature >> 4));
    *compensatedTemperature = adcTemperature - bmp280_calib_data[1] * (adcPressure >> 8);
}

// Function to compute altitude from pressure
void compute_altitude(float compensatedPressure, float compensatedTemperature, float *altitude) {
    // Barometric formula: h = (P / P0)^(1/5.255) * 11150
    *altitude = (compensatedPressure / 101325.0) * pow(11150.0, 1.0 / 5.255) * (1.0 + 0.001828 * compensatedTemperature);
}

// Function to write to log file
void write_to_log_file(const char *message) {
    FILE *log_file = fopen("altitude_log.txt", "a+");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file for writing\n");
        return;
    }
    fprintf(log_file, "%s", message);
    fclose(log_file);
}

// Function to cleanup resources
void cleanup_resources() {
    gpiod_i2c_close(i2c_handle);
    pigpio_close(pi);
}

