void write_to_file();
void cleanup();

// Main function
int main() {
    // Initialize signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize pigpio
    if (pi == NULL) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    // Open SPI device
    if (pigpio_spi_open(pi, 0, 0) == -1) {
        fprintf(stderr, "Failed to open SPI device\n");
        return EXIT_FAILURE;
    }

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (!should_exit) {
        // Read temperature every 5 seconds
        read_temperature();
        sleep(5);

        // Write to file every 5 seconds
        write_to_file();
    }

    // Clean up
    cleanup();

    return EXIT_SUCCESS;
}

// Signal handler function
void handle_signal(int signum) {
    should_exit = 1;
}

// Function to read temperature from LM35 via MCP3008
void read_temperature() {
    int ret;
    float voltage;

    // Set MCP3008 channel and start bit
    uint8_t command = MCP3008_CHANNEL_0 | 0x01;

    // Attempt to write command to MCP3008
    if (pigpio_spi_transfer(pi, 0, &command, 1, 0) == -1) {
        fprintf(stderr, "Error writing to MCP3008\n");
        return;
    }

    // Read 3 bytes from MCP3008
    ret = pigpio_spi_transfer(pi, 0, NULL, 3, &voltage);

    if (ret != 3) {
        fprintf(stderr, "Error reading from MCP3008\n");
        return;
    }

    // Calculate temperature
    voltage *= LM35_SENSITIVITY;
    printf("Temperature: %.2f °C\n", voltage);

    // Store temperature in circular buffer
    temp_buffer[(int) (temp_buffer % BUFFER_SIZE)] = voltage;
}

// Function to write the circular buffer to a file
void write_to_file() {
    if ((file = fopen("temp_log.dat", "wb+")) == NULL) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }

    // Write the circular buffer to the file
    for (int i = 0; i < BUFFER_SIZE; i++) {
        fwrite(&temp_buffer[i], sizeof(float), 1, file);
    }

    // Close the file
    fclose(file);
}

// Function to clean up resources
void cleanup() {
    // Close SPI device
    pigpio_spi_close(pi, 0);

    // Close pigpio
    pigpio_close(pi);

    // Exit cleanly
    exit(EXIT_SUCCESS);
}
