#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <gpiod.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <ctype.h>

#define GPIO_NUM 17
#define FILE_NAME "flame_events.log"
#define INTERVAL 1000

// Function prototypes
void setup_gpiod();
void cleanup_gpiod();
void read_sensor();
void write_to_log(const char *timestamp, const char *pin_state);
void alarm_message(const char *message);

int main() {
    // Initialize GPIO
    setup_gpiod();

    // Main loop
    while (1) {
        // Read sensor
        read_sensor();

        // Sleep for the interval
        usleep(INTERVAL * 1000);

        // Handle SIGINT and SIGTERM
        if (signal(SIGINT, SIG_IGN) == SIG_ERR || signal(SIGTERM, SIG_IGN) == SIG_ERR) {
            fprintf(stderr, "Failed to ignore SIGINT and SIGTERM\n");
            exit(EXIT_FAILURE);
        }

        // Check for termination signal
        if (WIFEXITED(getpid())) {
            cleanup_gpiod();
            break;
        }
    }

    // Cleanup GPIO resources
    cleanup_gpiod();

    return 0;
}

// Function to setup GPIO using libgpiod
void setup_gpiod() {
    int fd;

    // Open GPIO controller
    fd = open("/dev/gpiom", O_RDONLY);
    if (fd == -1) {
        fprintf(stderr, "Failed to open GPIO controller: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO line for input with pull-down
    if (gpiod_line_config(fd, GPIO_NUM, GPIOD_LINE_CONFIG_INPUT | GPIOD_LINE_CONFIG_PULLDOWN) < 0) {
        fprintf(stderr, "Failed to configure GPIO line: %s\n", gpiod_error_string(fd));
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Close GPIO controller after configuration
    close(fd);
}

// Function to cleanup GPIO resources
void cleanup_gpiod() {
    int fd = open("/dev/gpiom", O_RDONLY);

    // Close GPIO controller
    if (fd != -1) {
        gpiod_line_unconfig(fd, GPIO_NUM);
        close(fd);
    }

    // Release resources
    if (fd != -1) {
        close(fd);
    }
}

// Function to read the flame sensor
void read_sensor() {
    int state;
    char buffer[10];

    // Read the GPIO line
    if (gpiod_line_read(fd, GPIO_NUM, &state) < 0) {
        fprintf(stderr, "Failed to read GPIO line: %s\n", gpiod_error_string(fd));
        return;
    }

    // Check if flame is detected (HIGH state)
    if (state) {
        alarm_message("Flame detected!");
    } else {
        alarm_message("No flame detected.");
    }

    // Format and write to log
    strftime(buffer, sizeof(buffer), "%F %T", localtime(&time(NULL)));
    sprintf(buffer + strlen(buffer), ",%d", GPIO_NUM);
    sprintf(buffer + strlen(buffer), ",%s", state ? "HIGH" : "LOW");

    write_to_log(buffer, state ? "HIGH" : "LOW");
}

// Function to write to the log file in CSV format
void write_to_log(const char *timestamp, const char *pin_state) {
    FILE *log_file = fopen(FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    fprintf(log_file, "%s,%s\n", timestamp, pin_state);
    fclose(log_file);
}

// Function to print an alarm message
void alarm_message(const char *message) {
    fprintf(stderr, "ALARM: %s\n", message);
}

