#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pigpio.h>
#include <stdint.h>

#define MCP3008_CHANNEL 0
#define MCP3008_SPI_PORT 0
#define MCP3008_SPI_SPEED 500000
#define MCP4725_I2C_BUS 1
#define MCP4725_I2C_ADDR 0x62

#define TMP36_OFFSET 0.5
#define TMP36_SCALE 100.0

#define ADC_MAX_VALUE 1023
#define DAC_MIN_VOLTAGE 0.0
#define DAC_MAX_VOLTAGE 3.3

FILE *logFile = NULL;

pigpio *gp = NULL;

void setup_pigpio() {
    if (pigpio_init() == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }
    gp = pigpio_new();
    if (!gp) {
        fprintf(stderr, "Failed to create pigpio instance: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }
}

void cleanup_pigpio() {
    if (gp) {
        pigpio_free(gp);
        gp = NULL;
    }
}

void setup_spi() {
    if (pigpio_spi_setup(MCP3008_SPI_PORT, MCP3008_SPI_SPEED) == -1) {
        fprintf(stderr, "Failed to setup SPI: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }
}

void cleanup_spi() {
    pigpio_spi_free();
}

void setup_i2c() {
    if (pigpio_i2c_setup(MCP4725_I2C_BUS) == -1) {
        fprintf(stderr, "Failed to setup I2C: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }
}

void cleanup_i2c() {
    pigpio_i2c_free();
}

int read_adc(uint8_t channel) {
    uint16_t adc_value = 0;
    if (pigpio_spi_transfer(gp, MCP3008_SPI_PORT, channel, MCP3008_CHANNEL, &adc_value, 1) == -1) {
        fprintf(stderr, "Failed to read ADC: %s\n", pigpio_error());
        return -1;
    }
    return adc_value;
}

float convert_adc_to_celsius(uint16_t adc_value) {
    return (adc_value - TMP36_OFFSET) * (TMP36_SCALE / ADC_MAX_VALUE);
}

void set_dac_voltage(float voltage) {
    if (pigpio_i2c_write(gp, MCP4725_I2C_BUS, MCP4725_I2C_ADDR, 0x03, (uint8_t)(voltage * 4096.0)) == -1) {
        fprintf(stderr, "Failed to write to DAC: %s\n", pigpio_error());
        return;
    }
}

void sample_and_log() {
    uint16_t adc_value = read_adc(MCP3008_CHANNEL);
    if (adc_value == 0) {
        fprintf(stderr, "ADC reading is zero, sensor might be disconnected.\n");
        return;
    }

    float temperature_celsius = convert_adc_to_celsius(adc_value);
    float dac_voltage = (temperature_celsius + TMP36_OFFSET) * (DAC_MAX_VOLTAGE / TMP36_SCALE);

    struct tm time_info;
    time_t now = time(NULL);
