    if (spiOpen(MCP3008_SCLK, MCP3008_MISO, MCP3008_MOSI, MCP3008_CS, SPI_MODE, SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to open SPI: %s\n", spiError());
        return;
    }

    // No need to configure MCP3008 as it's already set for single-ended mode
