    FILE *file = fopen("soil_data.txt", "a");
    if (!file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    fprintf(file, "%s: Moisture: %.2f%%\n", timestamp, moisturePercentage);
    fclose(file);
}

