            usleep(1000000); // 1 second delay
            gpiod_line_set_value(gpiod_get_line_by_index(i), GPIOD_LINE_OFF);
            usleep(1000000); // 1 second delay
        }

        // Small delay between cycles
        usleep(3000000); // 3 seconds
    }

    // Cleanup GPIO lines on exit
    cleanup_gpios();

    return 0;
}

// Function to set up GPIO lines
void setup_gpios(void) {
    // Open GPIO interface
    int gpioid = gpiod_open();
    if (gpioid < 0) {
        fprintf(stderr, "Failed to open GPIO interface: %s\n", gpiod_errstr(gpioid));
        exit(EXIT_FAILURE);
    }

    // Request output for each GPIO pin
    for (int i = 17; i <= 24; i++) {
        int gpio = gpiod_get_line_by_index(i);
        if (gpiod_line_request_output(gpio) < 0) {
            fprintf(stderr, "Failed to request output for GPIO %d: %s\n", i, gpiod_errstr(gpioid));
            gpiod_close(gpioid);
            exit(EXIT_FAILURE);
        }
    }

    // Set initial state of GPIO lines to LOW (inactive)
    for (int i = 17; i <= 24; i++) {
        gpiod_line_set_value(gpio, GPIOD_LINE_OFF);
    }
}

// Function to cleanup GPIO lines
void cleanup_gpios(void) {
    // Release output for each GPIO pin
    for (int i = 17; i <= 24; i++) {
        int gpio = gpiod_get_line_by_index(i);
        if (gpiod_line_release_output(gpio) < 0) {
            fprintf(stderr, "Failed to release output for GPIO %d: %s\n", i, gpiod_errstr(gpioid));
