// Define GPIO pins
#define MCP3008_CS GPIO8
#define ADC_CHANNEL 0
#define SOUND_THRESHOLD 500
#define LED_PIN GPIO16

// Function prototypes
void setup_pigpio();
void setup_spi();
void read_adc(uint16_t channel);
void handle_sound_event(uint16_t value);
void cleanup();
void signal_handler(int signum);

int main() {
    // Initialize global variables
    FILE *log_file = NULL;
    pid_t pigpio_pid = -1;
    int adc_value = 0;

    // Signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Setup pigpio and SPI
        setup_pigpio();
        setup_spi();

        // Read ADC
        adc_value = read_adc(ADC_CHANNEL);

        // Check if sound threshold exceeded
        if (adc_value > SOUND_THRESHOLD) {
            handle_sound_event(adc_value);
        }

        // Sleep for 10 ms
        usleep(10000);

        // Debounce delay after each trigger
        if (last_trigger_time == 0) {
            debounce_delay = 100; // 100 ms debounce
        } else {
            debounce_delay = 1000; // 1 second debounce after initial trigger
        }

        // Wait for debounce delay
        usleep(debounce_delay);

        // Update last trigger time
        last_trigger_time = time(NULL);
        printf("ADC value: %d\n", adc_value);

        // Check if it's time to close resources
        if (time(NULL) - start_time > 5) {
            cleanup();
            start_time = time(NULL);
        }
    }

    return 0;
}

// Function to setup pigpio
void setup_pigpio() {
    pigpio_pid = pigpio_open();
    if (pigpio_pid == -1) {
        fprintf(stderr, "Failed to open pigpio: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }

    // Set LED GPIO as output
    if (pigpio_direction(LED_PIN, PIGPIO_OUTPUT) == -1) {
        fprintf(stderr, "Failed to set LED GPIO as output: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }

    // Set MCP3008 CS GPIO as output
    if (pigpio_direction(MCP3008_CS, PIGPIO_OUTPUT) == -1) {
        fprintf(stderr, "Failed to set MCP3008 CS GPIO as output: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }
}

// Function to setup SPI
void setup_spi() {
    int spi_fd = pigpio_spi_open(MCP3008_CS, 1000000, 0);
    if (spi_fd == -1) {
        fprintf(stderr, "Failed to open SPI: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }

    // Set MCP3008 channel
    if (pigpio_spi_write(spi_fd, 0x01) == -1) {
        fprintf(stderr, "Failed to write MCP3008 channel: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }
}

// Function to read ADC value from MCP3008
void read_adc(uint16_t channel) {
    uint16_t value;

    // Write channel to MCP3008
    if (pigpio_spi_write(PIN_MCP3008_CS, (channel << 6) | 0x01) == -1) {
        fprintf(stderr, "Failed to write MCP3008 channel: %s\n", pigpio_error());
        return;
    }

    // Read ADC value
