#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <fcntl.h>
#include <pigpio.h>

// Define GPIO pins
#define GPIO17 17
#define GPIO18 18
#define GPIO27 27

// Motor control constants
#define MOTOR_FORWARD 1
#define MOTOR_REVERSE 0
#define MOTOR_SPEED 150

// Rain sensor threshold
#define RAIN_THRESHOLD 5

// SPI channel
#define SPI_CHANNEL 0

volatile sig_atomic_t shutdownFlag = 0;

// MCP3008 configuration
#define MCP3008_ADDR 0x68

// Rain level mapping
int rainLevel(int adcValue) {
    return 10 - adcValue;
}

// Function to write to log file
void writeLog(char *message) {
    FILE *logFile = fopen("rain_log.txt", "a+");
    if (logFile == NULL) {
        fprintf(stderr, "Error: Failed to open log file 'rain_log.txt'\n");
        exit(EXIT_FAILURE);
    }
    fprintf(logFile, "%s\n", message);
    fclose(logFile);
}

// Main function
int main() {
    // Signal handlers
    struct sigaction intHandler, termHandler;
    sigemptyset(&intHandler.sa_mask);
    intHandler.sa_handler = &shutdownFlag;
    sigaction(SIGINT, &intHandler, NULL);
    sigaction(SIGTERM, &termHandler, NULL);

    // Initialize pigpio
    pigpio *pi = NULL;
    if (pigpio_init() == -1) {
        fprintf(stderr, "Error: Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }
    pi = pigpio_open();
    if (pi == NULL) {
        fprintf(stderr, "Error: Failed to open pigpio connection\n");
        pigpio_close(pi);
        pigpio_free();
        return EXIT_FAILURE;
    }

    // Set up GPIO pins
    if (pi_gpio_direction(GPIO17, PI_OUTPUT) == -1 ||
        pi_gpio_direction(GPIO18, PI_OUTPUT) == -1 ||
        pi_gpio_direction(GPIO27, PI_OUTPUT) == -1) {
        fprintf(stderr, "Error: Failed to set GPIO directions\n");
        pigpio_close(pi);
        pigpio_free();
        return EXIT_FAILURE;
    }

    // Set up PWM for motor control
    if (pi_pwm_write(GPIO17, MOTOR_FORWARD, MOTOR_SPEED) == -1 ||
        pi_pwm_write(GPIO18, MOTOR_REVERSE, MOTOR_SPEED) == -1) {
        fprintf(stderr, "Error: Failed to set PWM for motor control\n");
        pigpio_close(pi);
        pigpio_free();
        return EXIT_FAILURE;
    }

    // Initialize SPI
    int spi_fd = -1;
    if ((spi_fd = open("/dev/spidev0.0", O_RDWR)) == -1) {
        fprintf(stderr, "Error: Failed to open SPI device\n");
        close(spi_fd);
        pigpio_close(pi);
        pigpio_free();
        return EXIT_FAILURE;
    }

    // MCP3008 configuration
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_CHANNEL) == -1 ||
        ioctl(spi_fd, SPI_IOC_WR_MODE, &0) == -1) {
        fprintf(stderr, "Error: Failed to configure SPI for MCP3008\n");
        close(spi_fd);
        pigpio_close(pi);
        pigpio_free();
        return EXIT_FAILURE;
    }

    // Main loop
    while (!shutdownFlag) {
        // Read rain sensor
        int adcValue = 0;
        if (writeSpiTransfer(adcValue) == -1) {
            fprintf(stderr, "Error: Failed to read rain sensor\n");
            continue;
        }

        // Convert ADC value to rain level
        int rainLevel = rainLevel(adcValue);

        // Log rain level
        writeLog("Rain level: %d\n", rainLevel);

        // Check rain threshold
        if (rainLevel >= RAIN_THRESHOLD) {
            // Close window
            if (driveMotor(MOTOR_FORWARD) == -1) {
                fprintf(stderr, "Error: Failed to close window\n");
            } else {
                sleep(3);
                driveMotor(MOTOR_REVERSE); // Open window
                sleep(3);
            }
        } else {
            // Open window
            if (driveMotor(MOTOR_REVERSE) == -1) {
                fprintf(stderr, "Error: Failed to open window\n");
            } else {
                sleep(3);
                driveMotor(MOTOR_FORWARD); // Close window
                sleep(3);
            }
        }
    }

    // Graceful shutdown on SIGINT or SIGTERM
    if (shutdownFlag) {
        // Stop motor
        if (driveMotor(MOTOR_STOP) == -1) {
            fprintf(stderr, "Error: Failed to stop motor\n");
        }

        // Close SPI
        close(spi_fd);

        // Close log file
        fclose(logFile);

        // Release resources
        pigpio_close(pi);
        pigpio_free();

        // Exit
        exit(EXIT_SUCCESS);
    }

    // Cleanup on normal exit
    // Stop motor
    if (driveMotor(MOTOR_STOP) == -1) {
        fprintf(stderr, "Error: Failed to stop motor\n");
    }

    // Close SPI
    close(spi_fd);

    // Close log file
    fclose(logFile);

    // Release resources
    pigpio_close(pi);
    pigpio_free();

    // Exit
    exit(EXIT_SUCCESS);

    return 0;
}

// Function to write a single-ended SPI transfer
int writeSpiTransfer(int *adcValue) {
    uint8_t tx[3] = {0x01, (0x08 | SPI_CHANNEL) << 4, 0x00};
    int rx[3];
    if (writeSpiTransferBlocking(spi_fd, tx, 3, rx, 3) == -1) {
        fprintf(stderr, "Error: Failed to write SPI transfer\n");
        return -1;
    }

    // Parse the result
    int adcResult = (rx[1] & 0x0F) << 4 | rx[2];
    *adcValue = adcResult;

    return 0;
}

// Function to drive the motor
int driveMotor(int direction) {
    if (pi_pwm_write(GPIO17, direction == MOTOR_FORWARD ? 1 : 0, MOTOR_SPEED) == -1) {
        fprintf(stderr, "Error: Failed to set PWM for motor direction\n");
        return -1;
    }
    return 0;
}

