#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define MIC_GPIO 26
#define DETECT_GPIO 16

// ADC threshold value for detection
#define THRESHOLD 700

// Global pigpio handle
pigpio *pi;

// Function prototypes
void setup_pigpio();
void setup_adc();
void setup_gpio();
void handle_signal(int signum);
void detect_clap();
void debounce();
void cleanup();

int main() {
    // Initialize pigpio and handle SIGINT
    pi = NULL;
    signal(SIGINT, handle_signal);

    // Try to initialize pigpio
    if (pi == NULL) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }

    // Setup functions
    setup_pigpio();
    setup_adc();
    setup_gpio();

    // Main loop
    while (1) {
        // Debounce mechanism
        debounce();

        // Check if clap detected
        if (pigpio_adead_read(pi, MIC_GPIO) >= THRESHOLD) {
            detect_clap();
        }

        // Sleep to avoid CPU hogging
        usleep(10000);
    }

    // Clean up on exit
    cleanup();

    return EXIT_SUCCESS;
}

// Function to initialize pigpio
void setup_pigpio() {
    if (pigpio_init() == -1) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        exit(EXIT_FAILURE);
    }
}

// Function to setup ADC
void setup_adc() {
    if (pigpio_adead_setup(pi, MIC_GPIO, 1, 0, 0, 0, 0, 0, 0) == -1) {
        fprintf(stderr, "Failed to setup ADC.\n");
        exit(EXIT_FAILURE);
    }
}

// Function to setup GPIO for LED
void setup_gpio() {
    if (pigpio_mode_set(pi, DETECT_GPIO, pigpioOUTPUT) == -1) {
        fprintf(stderr, "Failed to set GPIO %d to output.\n", DETECT_GPIO);
        exit(EXIT_FAILURE);
    }
}

// SIGINT handler
void handle_signal(int signum) {
    fprintf(stderr, "Received SIGINT, cleaning up...\n");
    pigpio_stop(pi);
    cleanup();
    exit(EXIT_SUCCESS);
}

// Function to detect clap
void detect_clap() {
    // Turn on the LED
    pigpio_write(pi, DETECT_GPIO, 1);

    // Print detection timestamp
    time_t now = time(nullptr);
    struct tm tm_now;
    localtime_r(&now, &tm_now);
    fprintf(stderr, "Clap detected at: %s\n", ctime(&tm_now.tm_time));

    // Wait for 500 ms
    usleep(500000);

    // Turn off the LED
    pigpio_write(pi, DETECT_GPIO, 0);

    // Apply debounce
    debounce();
}

// Function to debounce the clap detection
void debounce() {
    static int last_check = 0;

    if (pigpio_adead_read(pi, MIC_GPIO) >= THRESHOLD && (time(NULL) - last_check) >= 50) {
        last_check = time(NULL);
        detect_clap();
    }
}

// Function to cleanup resources
void cleanup() {
    if (pi != NULL) {
        pigpio_stop(pi);
        pigpio_free(pi);
    }
}

