#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>
#include <libgpiod/gpiod.h>
#include <spidev.h>

#define SPI_PORT 0
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0 // CPOL=0, CPHA=0
#define SPI_SPEED 1000000 // 1 MHz

#define GPIO17 27
#define CE0 24
#define SCLK 11
#define MOSI 10
#define MISO 9

#define DRY_THRESHOLD 800
#define WET_THRESHOLD 300
#define MOISTURE_THRESHOLD 30

#define LOG_FILE_PATH "soil_moisture.log"

void setup_spi_and_gpios();
void read_moisture();
void activate_pump(int value);
void deactivate_pump();
void handle_sigint(int signum);
void log_data(int moisture_percentage, int pump_status);

int main() {
    int fd;
    struct spi_i2c_dev *spi;
    int pump_status = 0;
    int moisture_percentage = DRY_THRESHOLD;
    int moisture_read;

    setup_spi_and_gpios();

    while (1) {
        // Open SPI device
        fd = open(SPI_DEVICE, O_RDWR);
        if (fd == -1) {
            perror("Failed to open SPI device");
            exit(EXIT_FAILURE);
        }

        // Set SPI mode
        if (spidev_open_fd(fd, SPI_PORT) == -1) {
            perror("Failed to set SPI mode");
            close(fd);
            exit(EXIT_FAILURE);
        }

        // Prepare GPIOs
        gpiod_set_data_direction(GPIO17, GPIOD_DIR_OUT_INIT_LOW);
        gpiod_set_value(GPIO17, 1); // Activate pump

        // Start timer for 60 seconds delay
        struct timespec timeout = { .tv_sec = 60, .tv_nsec = 0 };
        if (nanosleep(&timeout, NULL) == -1) {
            perror("nanosleep error");
            break; // Exit loop on error
        }

        // Read moisture level
        moisture_read = read_moisture();
        moisture_percentage = (moisture_read / 1023) * 100;

        // Check moisture level and activate pump if necessary
        if (moisture_percentage < MOISTURE_THRESHOLD) {
            activate_pump(1);
        } else {
            deactivate_pump();
        }

        // Log data
        log_data(moisture_percentage, pump_status);

        // Close SPI device after logging
        close(fd);
    }

    handle_sigint(SIGINT);

    return 0;
}

void setup_spi_and_gpios() {
    // Initialize libgpiod
    if (gpiod_init() < 0) {
        perror("gpiod_init failed");
        exit(EXIT_FAILURE);
    }

    // Configure GPIOs
    gpiod_set_direction(CE0, GPIOD_DIR_OUT_INIT_LOW);
    gpiod_set_direction(SCLK, GPIOD_DIR_OUT_INIT_LOW);
    gpiod_set_direction(MOSI, GPIOD_DIR_OUT_INIT_LOW);
    gpiod_set_direction(MISO, GPIOD_DIR_IN);

    // Configure GPIO17 as output for the relay
    gpiod_set_direction(GPIO17, GPIOD_DIR_OUT_INIT_LOW);
}

void read_moisture() {
    struct spi_ioc_transfer xfer[] = {
        // Transfer to select CE0
        {
            .tx_buf = (unsigned char[]) { 0x01 }, // CE0 high
            .rx_buf = NULL,
            .len = 1,
            .delay_usecs = 0,
        },
        {
            .tx_buf = NULL,
            .rx_buf = (unsigned char[]) { 0x00 }, // CE0 low
            .len = 1,
            .delay_usecs = 10000,
        },
        {
            .tx_buf = (unsigned char[]) { 0x80 }, // Start conversion
            .rx_buf = (unsigned char *) &moisture_read,
            .len = 1,
            .delay_usecs = 10000,
        },
        {
            .tx_buf = NULL,
            .rx_buf = NULL,
            .len = 0,
            .delay_usecs = 0,
        },
    };

    int ret = spidev_write_transfer(SPI_DEVICE, SPI_MODE, SPI_SPEED, xfer, ARRAY_SIZE(xfer));
    if (ret != ARRAY_SIZE(xfer)) {
        perror("SPI transfer failed");
        moisture_read = -1; // Indicate failure
    } else {
        moisture_read = (unsigned int) xfer[1].rx_buf[0];
    }
}

void activate_pump(int value) {
    if (gpiod_set_value(GPIO17, value) < 0) {
        perror("Failed to set GPIO17 value");
    }
}

void deactivate_pump() {
    gpiod_set_value(GPIO17, 0);
}

void handle_sigint(int signum) {
    // Turn off the pump
    deactivate_pump();

    // Close the log file
    if (unlink(LOG_FILE_PATH) == -1) {
        perror("Failed to unlink log file");
    }

    // Release all GPIO resources
    gpiod_cleanup();
}

void log_data(int moisture_percentage, int pump_status) {
    char buffer[256];
    time_t now = time(NULL);
    struct tm timeinfo;
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    sprintf(buffer, "%s: Moisture: %d%%, Pump: %d\n", timestamp, moisture_percentage, pump_status);

    FILE *log_file = fopen(LOG_FILE_PATH, "a+");
    if (log_file == NULL) {
        perror("Failed to open log file for appending");
        return;
    }

    if (fwrite(buffer, sizeof(buffer), 1, log_file) != 1) {
        perror("Failed to write to log file");
        fclose(log_file);
        return;
    }

    fclose(log_file);
}

