#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>

// Define GPIO pin numbers for SPI and LED
#define SPI_CE0_GPIO 8
#define SPI_MOSI_GPIO 9
#define SPI_MISO_GPIO 10
#define SPI_SCLK_GPIO 11
#define LED_GPIO 21

// Define constants
#define MCP3008_CHANNEL 0
#define ADC_RESOLUTION 10
#define VCC 3300 // Assuming 3.3V supply
#define THRESHOLD_MAGNETIC_FIELD 10.0
#define SENSITIVITY_MV_PER_MT 1.65

// Function prototypes
void setup_pigpio();
void setup_spi();
void read_adc(uint16_t);
void convert_voltage_to_magnetic_field(float, float);
void handle_signal(int);
void cleanup();

int main() {
    // Initialize global variables
    FILE *magnetic_log = NULL;
    pid_t pigpiopid = -1;
    int adc_value;

    // Signal handler for SIGINT
    signal(SIGINT, handle_signal);

    // Main program loop
    while (1) {
        // Read ADC value
        if (read_adc(ADC_RESOLUTION) == 0) {
            // Handle error reading ADC
            fprintf(stderr, "Error reading ADC value\n");
            continue;
        }

        // Convert ADC value to voltage
        float voltage = adc_value / (ADC_RESOLUTION * (VCC / 1023.0));

        // Convert voltage to magnetic field strength
        float field_mT = convert_voltage_to_magnetic_field(voltage, VCC);

        // Log the reading
        if (magnetic_log == NULL) {
            magnetic_log = fopen("magnetic_log.txt", "a+");
            if (magnetic_log == NULL) {
                fprintf(stderr, "Failed to open magnetic_log.txt for append\n");
                continue;
            }
        }
        fprintf(magnetic_log, "%f %d\n", field_mT, (int)time(NULL));

        // Check if magnetic field exceeds threshold
        if (field_mT > THRESHOLD_MAGNETIC_FIELD) {
            // Turn on LED
            gpio_write(LED_GPIO, 1);
        } else {
            // Turn off LED
            gpio_write(LED_GPIO, 0);
        }

        // Delay for 100 ms
        usleep(100000);

        // Cleanup on SIGINT
        if (pigpiopid != -1) {
            cleanup();
        }
    }

    // Cleanup on normal exit
    cleanup();

    return 0;
}

// Function to setup pigpio
void setup_pigpio() {
    pigpiod_init();
    pigpiopid = pigpiod_get_id();
    if (pigpiopid == -1) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }
}

// Function to setup SPI
void setup_spi() {
    if (gpio_mode(SPI_CE0_GPIO, GPIO_OUT) == 0) {
        fprintf(stderr, "Failed to set SPI CE0 pin as output\n");
        exit(EXIT_FAILURE);
    }

    if (gpio_mode(SPI_MOSI_GPIO, GPIO_OUT) == 0) {
        fprintf(stderr, "Failed to set MOSI pin as output\n");
        exit(EXIT_FAILURE);
    }

    if (gpio_mode(SPI_MISO_GPIO, GPIO_IN) == 0) {
        fprintf(stderr, "Failed to set MISO pin as input\n");
        exit(EXIT_FAILURE);
    }

    if (gpio_mode(SPI_SCLK_GPIO, GPIO_OUT) == 0) {
        fprintf(stderr, "Failed to set SCLK pin as output\n");
        exit(EXIT_FAILURE);
    }

    // Configure SPI
    int spi = pigpio.spi_open(0, SPI_MOSI_GPIO, SPI_MISO_GPIO, SPI_SCLK_GPIO, GPIO_ACTIVE_LOW);
    if (spi == -1) {
        fprintf(stderr, "Failed to open SPI device\n");
        exit(EXIT_FAILURE);
    }
}

// Function to read ADC value
uint16_t read_adc(uint16_t resolution) {
    uint16_t data = 0;
    pigpio.spi_write(spi, MCP3008_CHANNEL, 0x01); // Start conversion
    pigpio.spi_write(spi, MCP3008_CHANNEL, 0x00); // Stop conversion and read data
    data = pigpio.spi_read(spi, MCP3008_CHANNEL, 1);
    return data;
}

// Function to convert voltage to magnetic field
float convert_voltage_to_magnetic_field(float voltage, float vcc) {
    float sensitivity = SENSITIVITY_MV_PER_MT;
    float half_vcc = vcc / 2.0;
    return (voltage - half_vcc) * 1000.0 / sensitivity;
}

// Signal handler for SIGINT
void handle_signal(int signum) {
    // Clean up SPI and GPIO
    cleanup();
    exit(EXIT_SUCCESS);
}

// Function to cleanup resources
void cleanup() {
    if (magnetic_log != NULL) {
        fclose(magnetic_log);
        magnetic_log = NULL;
    }

    if (pigpiopid != -1) {
        pigpio.spi_close(spi);
        pigpiod_stop();
        pigpiod_free();
        pigpiopid = -1;
    }

    gpio_free(LED_GPIO);
}

