#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <spidev.h>

#define GPIO_NUM 17
#define SPI_DEVICE "/dev/spidev0.0"
#define ADC_CHANNEL 0

// Constants for MLX91209 and MCP3008
#define MLX91209_ADDR 0x40
#define MLX91209_CMD_READ 0x01
#define MCP3008_DEVICE 0x68

// GPIO setup for MLX91209
#define MLX91209_GPIO_DIR GPIO_OUT
#define MLX91209_GPIO_NUM GPIO_NUM

