void setup_spi();
void read_current();
void handle_signals(int signum);
void cleanup();

int main() {
    // Initialize GPIO and SPI
    setup_gpiod();
    setup_spi();

    // Signal handlers
    struct sigaction int_handler, term_handler;
    sigemptyset(&int_handler.sa_mask);
    int_handler.sa_handler = handle_signals;
    sigaction(SIGINT, &int_handler, NULL);
    int_handler.sa_handler = handle_signals;
    sigaction(SIGTERM, &int_handler, NULL);

    // Main loop
    time_t start_time;
    while (1) {
        // Get current time
        start_time = time(NULL);

        // Read and log current
        read_current();

        // Wait for 1 second
        sleep(1);
    }

    // Clean up on exit
    cleanup();

    return 0;
}

// Function to setup GPIO using libgpiod
void setup_gpiod() {
    int ret;

    // Initialize gpiod
    ret = gpiod_init();
    if (ret != 0) {
        fprintf(stderr, "Error initializing gpiod: %s\n", gpiod_errstr(ret));
        exit(EXIT_FAILURE);
    }

    // Set GPIO pin 17 to output
    ret = gpiod_direction_output(GPIO_NUM, 1);
    if (ret != 0) {
        fprintf(stderr, "Error setting GPIO %d to output: %s\n", GPIO_NUM, gpiod_errstr(ret));
        gpiod_cleanup();
        exit(EXIT_FAILURE);
    }
}

// Function to setup SPI using spidev
void setup_spi() {
    int spi_fd;

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd == -1) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Set SPI mode (CPOL=0, CPHA=0)
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE_0) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set clock rate (1 MHz)
    if (ioctl(spi_fd, SPI_IOC_WR_BAUDRATE, &SPI_BAUD_RATE) < 0) {
        fprintf(stderr, "Error setting SPI clock rate: %s\n", strerror(errno));
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
}

// Function to read current using MLX91209 and MCP3008
void read_current() {
    int adc_value;
    struct timeval tv;
    char buffer[64];

    // Read MLX91209 analog voltage
    gpiod_set_value(GPIO_NUM, 0); // Set MLX91209 to low to start conversion
    usleep(10000); // Wait for conversion (approx. 10ms)
    gpiod_set_value(GPIO_NUM, 1); // Set MLX91209 to high to read value

    // Read analog voltage from MCP3008
    adc_value = adc_read(MCP3008_DEVICE, ADC_CHANNEL);

    // Convert ADC value to current
    float current_A = adc_value * 100.0 / 1024.0; // Assuming 10-bit ADC and sensitivity of 100mV/A

    // Format and write to log file
    gettimeofday(&tv, NULL);
    sprintf(buffer, "%ld,%f\n", (long)tv.tv_sec, current_A);

    // Open log file for appending
    FILE *log_file = fopen("current_log.txt", "a+");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    // Write to log file
    fprintf(log_file, "%s", buffer);
    fclose(log_file);
}

// Signal handler for SIGINT and SIGTERM
void handle_signals(int signum) {
    // Clean up on SIGINT or SIGTERM
    cleanup();
    exit(EXIT_SUCCESS);
}

// Function to clean up resources
void cleanup() {
    // Release GPIO line
    gpiod_set_value(GPIO_NUM, 0);

    // Close SPI device
    close(spi_fd);

    // Close log file
    fclose(log_file);
}

// Helper function to read from MCP3008 over SPI
int adc_read(int spi_fd, int channel) {
    int value = 0;
    int bytes_sent = 3;

    // Start SPI transfer
    if (write(spi_fd, &channel, 1) != 1) {
        return -1; // Error writing command
    }

    // Read 10-bit ADC value (2 bytes)
    if (read(spi_fd, &value, 2) != 2) {
        return -1; // Error reading data
    }

    return value;
}

