#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <pigpio.h>
#include <stdint.h>

// Define GPIO constants
#define GPIO8  24
#define GPIO10 18
#define GPIO9  23
#define GPIO11 17

// MCP3008 SPI configuration
#define MCP3008_CHANNEL_0 0x01

// MLX91211 full-scale current in A
#define FULL_SCALE_CURRENT 50.0

// Global variables
volatile sig_atomic_t interrupt_requested = 0;
FILE *current_log_file = NULL;

// Function prototypes
void handle_interrupt(int signum);
void cleanup();

int main() {
    // Initialize pigpio
    if (gpioInitialise() == -1) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", strerror(errno));
        return 1;
    }

    // Open SPI0 with CE0 as chip select
    if (spiOpen(0, GPIO8, SPI_MODE_0, 1000000) == -1) {
        fprintf(stderr, "Failed to open SPI0: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // SIGINT handler
    signal(SIGINT, handle_interrupt);

    // Attempt to open the log file
    current_log_file = fopen("current_log.txt", "a+");
    if (current_log_file == NULL) {
        // Close SPI and terminate pigpio if log file open fails
        spiClose(0);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!interrupt_requested) {
        // Read MCP3008 channel 0
        uint8_t tx[3] = {0x01, 0x80 | (MCP3008_CHANNEL_0 << 4), 0x00};
        if (spiXfer(0, tx, 3, NULL, NULL) == -1) {
            fprintf(stderr, "SPI transfer error: %s\n", strerror(errno));
            continue;
        }

        // Convert raw code to voltage
        uint16_t raw_code = (tx[1] & 0x03) << 8 | tx[2];
        float voltage = (float)raw_code / 1023.0 * 5.0;

        // Convert voltage to current
        float current = (voltage - 2.5) * (FULL_SCALE_CURRENT / 2.5);

        // Check for valid voltage range
        if (voltage < 0.0 || voltage > 5.0) {
            fprintf(stderr, "Warning: Voltage out of range [%f, %f]\n", 0.0, 5.0);
            continue;
        }

        // Print current to log file
        char timestamp[32];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S ", localtime(&now));
        fprintf(current_log_file, "%s %f A\n", timestamp, current);

        // Delay for 100ms
        gpioDelay(100000);
    }

    // Close log file and release resources
    fclose(current_log_file);
    spiClose(0);
    gpioTerminate();

    return 0;
}

// SIGINT handler
void handle_interrupt(int signum) {
    interrupt_requested = 1;
}

// Cleanup function
void cleanup() {
    if (current_log_file != NULL) {
        fclose(current_log_file);
        current_log_file = NULL;
    }
}

