        return 1;
    }

    // Main loop
    while (!interrupt_requested) {
        // Read MCP3008 channel 0
        uint8_t tx[3] = {0x01, 0x80 | (MCP3008_CHANNEL_0 << 4), 0x00};
        if (spiXfer(0, tx, 3, NULL, NULL) == -1) {
            fprintf(stderr, "SPI transfer error: %s\n", strerror(errno));
            continue;
        }

        // Convert raw code to voltage
        uint16_t raw_code = (tx[1] & 0x03) << 8 | tx[2];
        float voltage = (float)raw_code / 1023.0 * 5.0;

        // Convert voltage to current
        float current = (voltage - 2.5) * (FULL_SCALE_CURRENT / 2.5);

        // Check for valid voltage range
        if (voltage < 0.0 || voltage > 5.0) {
            fprintf(stderr, "Warning: Voltage out of range [%f, %f]\n", 0.0, 5.0);
            continue;
        }

        // Print current to log file
        char timestamp[32];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S ", localtime(&now));
        fprintf(current_log_file, "%s %f A\n", timestamp, current);

        // Delay for 100ms
        gpioDelay(100000);
    }

    // Close log file and release resources
    fclose(current_log_file);
    spiClose(0);
    gpioTerminate();

    return 0;
}

// SIGINT handler
void handle_interrupt(int signum) {
    interrupt_requested = 1;
}

// Cleanup function
void cleanup() {
    if (current_log_file != NULL) {
        fclose(current_log_file);
        current_log_file = NULL;
    }
}

