    int line_fd2 = gpiod_line_request_input(chip_fd, SENSOR_2_GPIO);
    if (line_fd1 < 0 || line_fd2 < 0) {
        fprintf(stderr, "Error requesting input lines: %s\n", gpiod_error_name(line_fd1));
        gpiod_chip_close(chip_fd);
        return EXIT_FAILURE;
    }

    // Set debounce parameters
    const int debounce_samples = 5;
    const int debounce_time_ms = 2;

    // Signal handler for SIGINT
    signal(SIGINT, handle_signal);

    // Main loop
    while (1) {
        // Check sensor states
        int state1 = check_sensor_state(SENSOR_1_GPIO);
        int state2 = check_sensor_state(SENSOR_2_GPIO);

        // Log sensor states
        printf("Sensor 1: %d, Sensor 2: %d\n", state1, state2);

        // Check for both sensors detecting an object
        if (state1 == 0 && state2 == 0) {
            printf("ALERT: Both sensors detect object\n");
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Release resources on exit
    handle_signal(SIGINT);

    gpiod_line_release(line_fd1);
    gpiod_line_release(line_fd2);
    gpiod_chip_close(chip_fd);

    return EXIT_SUCCESS;
}

