    int count = 0;
    for (int i = 0; i < debounce_samples; ++i) {
        int value = gpiod_read(gpio);
        if (value == 0) {
            ++count;
        }
        usleep(debounce_time_ms * 1000);
    }

    // Majority value determines the state
    if (count > debounce_samples / 2) {
        return 0; // Object present
    } else {
        return 1; // No object
    }
}

// Signal handler function
void handle_signal(int signum) {
    // Release resources on SIGINT
    gpiod_line_release(SENSOR_1_GPIO);
    gpiod_line_release(SENSOR_2_GPIO);
    gpiod_chip_close(0);
    exit(EXIT_FAILURE);
}

