#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

volatile sig_atomic_t terminate_flag = 0;

// Function prototypes
void spi_setup(spi_config_t config);
int read_mcp3008(int channel);
double calculate_moisture_level(int adc_value);
void log_data(double moisture_level);
void signal_handler(int signal);

// MCP3008 SPI configuration
static spi_config_t spi_config = {
    .bits_per_word = 8,
    .max_speed_hz = SPI_BAUD,
    .mode = SPI_MODE_0,
    .cs_type = SPI_CS_HIGH,
    .chip_select = 0,
};

// Function to setup SPI
void spi_setup(spi_config_t config) {
    if (pigpio.spi_open(&config) == -1) {
        fprintf(stderr, "Failed to open SPI: %s\n", pigpio.error());
        return;
    }
}

// Function to read MCP3008 ADC value
int read_mcp3008(int channel) {
    spi_config.cs = channel; // Set the chip select pin

    int ret;
    if ((ret = pigpio.spi_write(0x01)) != 1) {
        fprintf(stderr, "Failed to write start bit: %s\n", pigpio.error());
        sleep(1); // Retry after a delay
        return read_mcp3008(channel); // Recursive call to retry
    }

    if ((ret = pigpio.spi_write(0x80 | (MCP3008_CHANNEL << 4))) != 1) {
        fprintf(stderr, "Failed to write command byte: %s\n", pigpio.error());
        sleep(1); // Retry after a delay
        return read_mcp3008(channel); // Recursive call to retry
    }

    if ((ret = pigpio.spi_read(1)) != 1) {
        fprintf(stderr, "Failed to read ADC value: %s\n", pigpio.error());
        return -1; // Return error code
    }

    uint8_t rx_buf[2];
    rx_buf[0] = (uint8_t)(pigpio.spi_read()); // Dummy byte
    rx_buf[1] = (uint8_t)(pigpio.spi_read()); // Actual ADC value

    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

    return adc_value;
}

// Function to calculate moisture level from ADC value
double calculate_moisture_level(int adc_value) {
    if (adc_value < MIN_ADC || adc_value > MAX_ADC) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return 0.0; // Return invalid moisture level
    }

    double moisture_level = 100.0 - ((adc_value - MIN_ADC) / (MAX_ADC - MIN_ADC)) * 100.0;
    moisture_level = fminf(moisture_level, 100.0); // Clamp to [0, 100]

    return moisture_level;
}

// Function to log data to CSV file
void log_data(double moisture_level) {
    char timestamp[21];
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S,", &tm);

    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        return;
    }

    fprintf(file, "%s,%.2f\n", timestamp, moisture_level);
    fclose(file);
}

// Signal handler for SIGINT
void signal_handler(int signal) {
    terminate_flag = 1;
}

int main() {
    pigpio *handle;
    int adc_value;

    // Initialize pigpio
    if ((handle = pigpio_open()) == NULL) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio.error());
        return EXIT_FAILURE;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Attempt to setup SPI
    if (spi_setup(spi_config)) {
        fprintf(stderr, "Failed to setup SPI: %s\n", pigpio.error());
        pigpio_close(handle); // Close pigpio before returning
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate_flag) {
        // Read ADC value
        adc_value = read_mcp3008(MCP3008_CHANNEL);

        // Calculate moisture level
        double moisture_level = calculate_moisture_level(adc_value);

        // Log data
        log_data(moisture_level);

        // Delay for 60 seconds
        sleep(60);
    }

    // Close SPI and terminate pigpio on exit
    spi_setup(NULL); // Close SPI
    pigpio_close(handle); // Close pigpio

    return EXIT_SUCCESS;
}

