#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <time.h>
#include <pigpio.h>
#include <libcamera/libcamera.h>

#define PIR_GPIO 17
#define DEBOUNCE_MS 200
#define CAPTURE_PATH "/home/pi/security_cam/%Y%m%d%H%M%S.jpg"
#define SNAPSHOT_CMD "/usr/bin/libcamera-still --output %s --shutter-speed=1/60 --rotation 0 --auto"

// Function prototypes
void initialize_pigpio();
void configure_gpiod_input(int gpio, int mode);
void motion_detected();
void capture_image();
void cleanup_resources();
void log_to_syslog(const char *msg);

// Global variables
pigpio *pi;
int motion_detected = 0;
pid_t child_pid = 0;

// Main function
int main() {
    // Initialize pigpio
    initialize_pigpio();
    if (pi == NULL) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Configure GPIO17 as input with pull-down resistor
    configure_gpiod_input(PIR_GPIO, GPIO_INPUT_PULLDOWN);

    // Signal handlers
    struct sigaction sa;
    sa.sa_handler = cleanup_resources;
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        // Poll GPIO every 50ms
        if (pigpio_poll(pi, PIR_GPIO, GPIO_RISING) == 0) {
            motion_detected = 1;
            motion_detected = debounce_motion_detection();
            if (motion_detected) {
                capture_image();
            }
        }

        usleep(50000); // 50ms delay
    }

    // Release resources
    cleanup_resources();

    return 0;
}

// Function to initialize pigpio
void initialize_pigpio() {
    pi = pigpio_open();
    if (pi == NULL) {
        fprintf(stderr, "Failed to open pigpio\n");
        exit(1);
    }
}

// Function to configure GPIO as input with pull-down resistor
void configure_gpiod_input(int gpio, int mode) {
    if (pigpio_set_mode(pi, gpio, mode) == 0) {
        fprintf(stderr, "Failed to set GPIO mode: %d\n", gpio);
        exit(1);
    }
}

// Function to debounce motion detection
int debounce_motion_detection() {
    int state;
    for (int i = 0; i < DEBOUNCE_MS; i++) {
        state = pigpio_get_value(pi, PIR_GPIO);
        if (state != pigpio_NO_CHANGE) {
            return 0; // Reset if state changes during debounce
        }
    }
    return 1; // Confirm motion after debounce
}

// Function to capture an image
void capture_image() {
    char path[256];
    snprintf(path, sizeof(path), "%s", CAPTURE_PATH);

    // Check if the target directory exists
    struct stat statbuf;
    if (stat(path, &statbuf) == -1) {
        perror("stat");
        return;
    }

    // Execute libcamera-still
    child_pid = fork();
    if (child_pid == 0) {
        execlp(SNAPSHOT_CMD, SNAPSHOT_CMD, path, NULL);
        perror("execlp");
        _exit(1);
    } else {
        // Wait for child process and check exit status
        int status;
        waitpid(child_pid, &status, 0);
        if (WIFEXITED(status)) {
            if (WEXITSTATUS(status) != 0) {
                fprintf(stderr, "Libcamera-still failed with exit code %d\n", WEXITSTATUS(status));
                log_to_syslog("Libcamera-still failed to capture image.");
            } else {
                fprintf(stderr, "Libcamera-still succeeded\n");
                log_to_syslog("Image captured successfully.");
            }
        } else {
            fprintf(stderr, "Libcamera-still exited with signal %d\n", WTERMSIG(status));
            log_to_syslog("Libcamera-still exited unexpectedly.");
        }
    }
}

// Function to release resources and close syslog
void cleanup_resources() {
    pigpio_close(pi);
    // Close syslog (assuming syslog was opened and used earlier)
    closelog();
}

// Function to log messages to syslog
void log_to_syslog(const char *msg) {
    syslog(LOG_INFO, "%s", msg);
}

