        fd_set readfds;
        FD_SET(fd, &readfds);
        struct timeval tv = { .tv_sec = 2, .tv_usec = 0 };
        if (select(fd + 1, &readfds, NULL, NULL, &tv) == -1) {
            perror("select");
            break;
        }

        // Check if buffer is ready for dequeueing
        if (FD_ISSET(fd, &readfds)) {
            if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
                if (errno == EAGAIN) {
                    // Gracefully handle EAGAIN
                    continue;
                } else {
                    perror("VIDIOC_DQBUF");
                    break;
                }
            }

            // Capture frame and save to file
            capture_frame(mmap_base);
            write_pgm_file(IMAGE_PREFIX ++ (framesCaptured % 1000) ".pgm", mmap_base);
            framesCaptured++;
        }

        // Check for signals
        if (sigpending(&sigset) != -1) {
            signum = sigismember(&sigset, SIGINT);
            if (signum == SIGINT) {
                printf("Caught SIGINT, exiting...\n");
                break;
            }
            signum = sigismember(&sigset, SIGTERM);
            if (signum == SIGTERM) {
                printf("Caught SIGTERM, exiting...\n");
                break;
            }
        }
    }

    // Cleanup resources
    cleanup_resources();

    // Unmap the buffer before closing the file descriptor
    munmap(mmap_base, BUFFER_SIZE);

    // Close the V4L2 device
    close(fd);

    return 0;
