#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <netinet/in.h>
#include <signal.h>
#include <errno.h>

#define VIDEO_DEVICE "/dev/video0"
#define VIDEO_WIDTH 640
#define VIDEO_HEIGHT 480
#define VIDEO_FPS 30
#define BUFFER_SIZE 1024 * 1024  // 1MB buffer size
#define FRAG_MAX_SIZE 65000
#define FRAG_HEADER_SIZE 32
#define FRAGMENTS_PER_FRAME 4

// Structure for frame metadata
typedef struct {
    uint32_t frame_index;
    uint32_t fragment_index;
    uint32_t total_fragments;
    uint32_t payload_size;
} FrameMetadata;

// Function prototypes
void setup_video_stream(int fd);
void capture_frame(int fd, void *mmap_buffer, FrameMetadata *metadata);
void send_udp_fragment(const void *data, size_t len, int fd);
void cleanup_resources();

// Signal handlers
void signal_handler(int signum) {
    switch (signum) {
        case SIGINT:
        case SIGTERM:
            printf("Stopping stream...\n");
            cleanup_resources();
            break;
        default:
            // Ignore other signals
            break;
    }
}

int main(int argc, char **argv) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return 1;
    }

    char *server_ip = argv[1];
    uint16_t server_port = htons((uint16_t)atoi(argv[2]));

    // Initialize signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open video device
    int fd = open(VIDEO_DEVICE, O_RDWR | O_NONBLOCK);
    if (fd == -1) {
        perror("open");
        return 1;
    }

    // Setup video stream
    setup_video_stream(fd);

    // Main loop
    while (1) {
        FrameMetadata metadata;
        metadata.frame_index = ++current_frame_index;
        metadata.total_fragments = FRAGMENTS_PER_FRAME;
        metadata.payload_size = BUFFER_SIZE;

        void *mmap_buffer = mmap(NULL, BUFFER_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
        if (mmap_buffer == MAP_FAILED) {
            perror("mmap");
            break; // Exit on mmap failure
        }

        capture_frame(fd, mmap_buffer, &metadata);

        // Send UDP fragments
        for (int i = 0; i < FRAGMENTS_PER_FRAME; ++i) {
            size_t fragment_size = FRAG_MAX_SIZE - FRAG_HEADER_SIZE;
            if (metadata.payload_size < fragment_size) {
                // Frame too small to be fragmented
                break;
            }

            const void *fragment_start = metadata.frame_index * metadata.payload_size + i * fragment_size;
            size_t fragment_len = fragment_size;

            send_udp_fragment((const void *)fragment_start, fragment_len, server_fd);
        }

        munmap(mmap_buffer, BUFFER_SIZE);
    }

    // Cleanup resources
    cleanup_resources();

    return 0;
}

// Function to setup video stream
void setup_video_stream(int fd) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers reqbuf;
    struct v4l2_buffer buf[4];

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        return;
    }

    if (cap.capability & V4L2_CAP_VIDEO_MMAP) {
        fmt.type = V4L2_BUF_TYPE_VIDEO_MMAP;
        fmt.fmt.pix.width = VIDEO_WIDTH;
        fmt.fmt.pix.height = VIDEO_HEIGHT;
        fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;

        if (ioctl(fd, VIDIOCGFORMAT, &fmt) < 0) {
            perror("VIDIOCGFORMAT");
            return;
        }

        reqbuf.count = 4;
        reqbuf.type = V4L2_BUF_TYPE_VIDEO_MMAP;
        if (ioctl(fd, VIDIOCSREQUEST, &reqbuf) < 0) {
            perror("VIDIOCSREQUEST");
            return;
        }

        // Map buffers
        for (int i = 0; i < 4; ++i) {
            if (ioctl(fd, VIDIOCGBUF, &buf[i]) < 0) {
                perror("VIDIOCGBUF");
                return;
            }

            mmap_buffer_start[i] = (uint8_t *)mmap(NULL, buf[i].m.size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf[i].m.offset);
            if (mmap_buffer_start[i] == MAP_FAILED) {
                perror("mmap buffer start");
                return;
            }
        }
    } else {
        fprintf(stderr, "Device does not support mmap streaming\n");
        return;
    }
}

// Function to capture a frame
void capture_frame(int fd, void *mmap_buffer, FrameMetadata *metadata) {
    struct v4l2_buffer buf;
    buf.type = V4L2_BUF_TYPE_VIDEO_MMAP;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("VIDIOC_QBUF");
        return;
    }

    // Wait for frame to be available
    while (1) {
        if (ioctl(fd, VIDIOCSBUF, &buf) < 0) {
            perror("VIDIOCSBUF");
            return;
        }

        if (buf.timestamp.tv_sec == 0 && buf.timestamp.tv_usec == 0) {
            // Frame is ready
            break;
        }
    }

    // Copy frame data to metadata buffer
    memcpy(metadata->frame_index * BUFFER_SIZE, mmap_buffer, buf.m.size);

    // Notify the receiver about the frame
    metadata->fragment_index = 0;
    metadata->payload_size = buf.m.size;

    // Send frame metadata
    send_udp_fragment((const void *)&metadata, FRAG_HEADER_SIZE, server_fd);
}

// Function to send UDP fragment
void send_udp_fragment(const void *data, size_t len, int fd) {
    struct sockaddr_in dest;
    socklen_t addrlen = sizeof(dest);

    // Initialize destination address
    dest.sin_family = AF_INET;
    inet_pton(AF_INET, server_ip, &dest.sin_addr);

    // Send fragment
    if (sendto(fd, data, len, 0, (struct sockaddr *)&dest, sizeof(dest)) < 0) {
        perror("sendto");
        return;
    }
}

// Function to cleanup resources
void cleanup_resources() {
    for (int i = 0; i < 4; ++i) {
        munmap(mmap_buffer_start[i], mmap_buffer_start[i] + mmap_buffer_end[i]);
    }

    close(fd);
}

// Global variables
int server_fd = -1; // UDP socket descriptor
uint32_t current_frame_index = 0;
uint32_t mmap_buffer_start[4];
uint32_t mmap_buffer_end[4];

// Ensure no undefined symbols
void __attribute__((constructor)) init_resources() {
    server_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (server_fd == -1) {
        perror("socket");
        exit(1);
    }

    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(server_port);

    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("bind");
        close(server_fd);
        exit(1);
    }
}

