#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <errno.h>
#include <signal.h>
#include <v4l2/v4l2.h>

#define VIDEO_DEVICE "/dev/video0"
#define IMAGE_FILE "image.jpg"
#define BUFFER_COUNT 4
#define MJPEG_FORMAT V4L2_PIX_FMT_MJPEG

// Structure for buffer information
struct v4l2_buffer {
    __u32 index;
    __u32 length;
    __u32 type;
    __u32 __reserved[2];
};

// Structure for video device capabilities
struct v4l2_capability {
    __u32 type;
    __u32 vendor;
    __u32 product;
    __u32 version;
    __u32 extension;
    __u32 card Cap;
    __u32 interface Cap;
};

// Function prototypes
void handle_signal(int signum);
int open_device_and_query_caps();
int request_format_and_buffers();
int start_streaming();
int stop_streaming_and_cleanup();

int main() {
    // Initialize signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the video device
    int fd = open_device_and_query_caps();
    if (fd == -1) {
        perror("Failed to open video device");
        return 1;
    }

    // Request format and buffers
    if (request_format_and_buffers(fd) == -1) {
        perror("Failed to request format and buffers");
        close(fd);
        return 1;
    }

    // Start streaming
    if (start_streaming(fd) == -1) {
        stop_streaming_and_cleanup();
        perror("Failed to start streaming");
        return 1;
    }

    // Wait for SIGINT/SIGTERM to stop
    printf("Press Ctrl+C to stop and clean up...\n");

    // Handle signal to stop cleanly
    handle_signal(SIGINT);
    handle_signal(SIGTERM);

    // Stop streaming and clean up
    stop_streaming_and_cleanup();

    // Close the device and file descriptors
    close(fd);
    close(1); // Close stdout for good measure
    close(2); // Close stderr

    return 0;
}

// Signal handler to stop streaming and clean up
void handle_signal(int signum) {
    stop_streaming_and_cleanup();
    printf("Streaming stopped cleanly on signal %d\n", signum);
}

// Function to open the device and query capabilities
int open_device_and_query_caps() {
    int fd = open(VIDEO_DEVICE, O_RDWR | O_NONBLOCK);
    if (fd == -1) {
        perror("Failed to open video device");
        return -1;
    }

    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Failed to query capabilities");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & (V4L2_CAP_VIDEO_CAPTURE | V4L2_CAP_STREAMING))) {
        fprintf(stderr, "Device does not support video capture and streaming\n");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to request the desired format and buffers
int request_format_and_buffers(int fd) {
    struct v4l2_format fmt;
    fmt.type = MJPEG_FORMAT;
    fmt.fmt.pix.width = 1920;
    fmt.fmt.pix.height = 1080;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Failed to set format");
        close(fd);
        return -1;
    }

    struct v4l2_requestbuffers reqbuf;
    reqbuf.count = BUFFER_COUNT;
    reqbuf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (ioctl(fd, VIDIOC_REQBUFS, &reqbuf) < 0) {
        perror("Failed to request buffers");
        close(fd);
        return -1;
    }

    struct v4l2_buffer *buffers = malloc(BUFFER_COUNT * sizeof(struct v4l2_buffer));
    if (!buffers) {
        perror("Failed to allocate buffer memory");
        close(fd);
        return -1;
    }

    if (ioctl(fd, VIDIOC_QUERYBUF, buffers) < 0) {
        perror("Failed to query buffers");
        free(buffers);
        close(fd);
        return -1;
    }

    return 0;
}

// Function to start streaming
int start_streaming(int fd) {
    if (ioctl(fd, VIDIOC_STREAMON, &struct v4l2_streamon { .streamid = 0 }) < 0) {
        perror("Failed to start streaming");
        stop_streaming_and_cleanup();
        return -1;
    }

    return 0;
}

// Function to stop streaming and clean up
int stop_streaming_and_cleanup() {
    if (ioctl(fd, VIDIOC_STREAMOFF, &struct v4l2_streamoff { .streamid = 0 }) < 0) {
        perror("Failed to stop streaming");
        return -1;
    }

    // Unmap and free all buffers
    for (int i = 0; i < BUFFER_COUNT; i++) {
        if (mmap(NULL, buffers[i].length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buffers[i].index) == MAP_FAILED) {
            perror("Failed to mmap buffer");
            return -1;
        }
        munmap(buffers[i].map, buffers[i].length);
        free(buffers[i]);
    }

    // Close the file descriptor and release resources
    close(fd);

    return 0;
}

// Ensure the program behaves correctly on SIGINT or SIGTERM
void handle_signal(int signum) {
    stop_streaming_and_cleanup();
    printf("Streaming stopped cleanly on signal %d\n", signum);
}

