#include <stdbool.h>

#define SERVO_MIN 25
#define SERVO_MAX 125
#define STEP_SIZE 5
#define PWM_PERIOD_MS 20
#define PWM_MAX 1000
#define PWM_MIN 50

volatile sig_atomic_t should_exit = 0;

// Function prototypes
void setup_servos();
void poll_buttons_and_control_servos();
void cleanup();

// Main function
int main() {
    // Initialize GPIO
    if (gpiod_chip_open(GPIOD, "bcm2835") < 0) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", gpiod_get_name(gpiod_chip_open_errno(GPIOD)));
        exit(EXIT_FAILURE);
    }

    // Register signal handler for SIGINT
    signal(SIGINT, cleanup);

    // Set up servos and buttons
    setup_servos();

    // Main loop
    while (!should_exit) {
        poll_buttons_and_control_servos();
        usleep(PWM_PERIOD_MS * 1000); // Wait for 20 ms
    }

    // Clean up GPIO resources
    cleanup();

    return 0;
}

// Function to setup servos
void setup_servos() {
    struct gpiod_chip *chip = gpiod_chip_get(GPIOD);
    struct gpiod_pin *pan_pin = gpiod_pin_new(chip, GPIOD_PIN_04, GPIOD_PINMODE_OUTPUT);
    struct gpiod_pin *tilt_pin = gpiod_pin_new(chip, GPIOD_PIN_05, GPIOD_PINMODE_OUTPUT);

    if (!pan_pin || !tilt_pin) {
        fprintf(stderr, "Error creating pan or tilt GPIO pins: %s\n", gpiod_get_name(gpiod_pin_new_errno(pan_pin)));
        exit(EXIT_FAILURE);
    }

    gpiod_pin_set_value(pan_pin, SERVO_MIN * 1000 / PWM_MAX);
    gpiod_pin_set_value(tilt_pin, SERVO_MIN * 1000 / PWM_MAX);

    gpiod_pin_set_direction(pan_pin, GPIOD_PINOUTPUT);
    gpiod_pin_set_direction(tilt_pin, GPIOD_PINOUTPUT);

    gpiod_pin_set_pull_mode(pan_pin, GPIOD_PULLUP);
    gpiod_pin_set_pull_mode(tilt_pin, GPIOD_PULLUP);

    gpiod_pin_add_to_line_request_region(pan_pin, "pan_servo");
    gpiod_pin_add_to_line_request_region(tilt_pin, "tilt_servo");
}

// Function to poll buttons and control servos
void poll_buttons_and_control_servos() {
    struct gpiod_line *line_pan = gpiod_line_request_one(chip, GPIOD_PIN_06, GPIOD_LINEINPUT);
    struct gpiod_line *line_tilt = gpiod_line_request_one(chip, GPIOD_PIN_07, GPIOD_LINEINPUT);
    struct gpiod_line *line_pan_left = gpiod_line_request_one(chip, GPIOD_PIN_08, GPIOD_LINEINPUT);
    struct gpiod_line *line_tilt_down = gpiod_line_request_one(chip, GPIOD_PIN_09, GPIOD_LINEINPUT);

    if (!line_pan || !line_tilt || !line_pan_left || !line_tilt_down) {
        fprintf(stderr, "Error requesting GPIO lines: %s\n", gpiod_get_name(gpiod_line_request_one_errno(line_pan)));
        exit(EXIT_FAILURE);
    }

    // Poll buttons
    int pan_button_state = gpiod_line_get_value(line_pan);
    int tilt_button_state = gpiod_line_get_value(line_tilt);
    int pan_left_button_state = gpiod_line_get_value(line_pan_left);
    int tilt_down_button_state = gpiod_line_get_value(line_tilt_down);

    if (pan_button_state && (SERVO_MAX - current_pan_position) > STEP_SIZE) {
        current_pan_position += STEP_SIZE;
        gpiod_pin_set_value(pan_pin, current_pan_position * 1000 / PWM_MAX);
    } else if (pan_left_button_state && current_pan_position > 25) {
        current_pan_position -= STEP_SIZE;
        gpiod_pin_set_value(pan_pin, current_pan_position * 1000 / PWM_MAX);
    }

    if (tilt_button_state && (SERVO_MAX - current_tilt_position) > STEP_SIZE) {
        current_tilt_position += STEP_SIZE;
        gpiod_pin_set_value(tilt_pin, current_tilt_position * 1000 / PWM_MAX);
    } else if (tilt_down_button_state && current_tilt_position > 25) {
        current_tilt_position -= STEP_SIZE;
        gpiod_pin_set_value(tilt_pin, current_tilt_position * 1000 / PWM_MAX);
    }

    // Release lines after use
    gpiod_line_release(line_pan);
    gpiod_line_release(line_tilt);
    gpiod_line_release(line_pan_left);
    gpiod_line_release(line_tilt_down);

    // Check if we should exit due to SIGINT
    should_exit = true;
}

// Function to clean up resources
void cleanup() {
    // Release GPIO chip
    gpiod_chip_close(GPIOD);

    // Free all allocated pins
    while (gpiod_pin_list_length()) {
        gpiod_pin_free(gpiod_pin_list_pop());
    }

    printf("Exiting due to SIGINT\n");
}

// Global variables
int current_pan_position = SERVO_MIN * 1000 / PWM_MAX;
int current_tilt_position = SERVO_MIN * 1000 / PWM_MAX;

// Main loop function
int main_loop() {
    return main();
}

// Entry point for the program
int main(int argc, char **argv) {
    if (argc != 1) {
        fprintf(stderr, "Usage: %s\n", argv[0]);
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);

    return main_loop();
}

