        return 1;
    }

    // Open video device
    int fd = open(VIDEO_DEV, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "Error opening video device %s\n", VIDEO_DEV);
        return 1;
    }

    // Get V4L2 capabilities
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying V4L2 capabilities\n");
        close(fd);
        return 1;
    }

    // Check if device supports the requested format
    struct v4l2_format fmt;
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    // Allocate and map buffer
    V4L2Buffer buffer;
    buffer.data = malloc(BUFFER_SIZE);
    if (!buffer.data) {
        fprintf(stderr, "Error allocating buffer memory\n");
        close(fd);
        return 1;
    }
    if (mmap(NULL, BUFFER_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0) == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer memory: %s\n", strerror(errno));
        free(buffer.data);
        close(fd);
        return 1;
    }

    // Queue buffer for capture
    if (ioctl(fd, VIDIOC_QBUF, &buffer.buf) < 0) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        munmap(buffer.data, BUFFER_SIZE);
        free(buffer.data);
        close(fd);
        return 1;
    }

    // Select for frame readiness
    fd_set readfds;
    struct timeval timeout = {2, 0};
    FD_SET(fd, &readfds);
    if (select(fd + 1, &readfds, NULL, NULL, &timeout) < 0) {
        fprintf(stderr, "Error in select: %s\n", strerror(errno));
        munmap(buffer.data, BUFFER_SIZE);
        free(buffer.data);
        close(fd);
        return 1;
    }

    // Stream on and wait for frame
    if (ioctl(fd, VIDIOC_STREAMON, &buffer.buf) < 0) {
        fprintf(stderr, "Error streaming on: %s\n", strerror(errno));
        munmap(buffer.data, BUFFER_SIZE);
        free(buffer.data);
        close(fd);
        return 1;
    }

    // Dequeue the captured frame
    if (ioctl(fd, VIDIOC_DQBUF, &buffer.buf) < 0) {
        fprintf(stderr, "Error dequeuing frame: %s\n", strerror(errno));
        munmap(buffer.data, BUFFER_SIZE);
        free(buffer.data);
        close(fd);
        return 1;
    }

    // Convert YUYV to RGB24 here
    yuyvToRgb24(buffer.data->data, buffer.data->data, 640, 480);

    // Apply box blur
    boxBlur(buffer.data->data, buffer.data->data, 640, 480);

    // Save as JPEG
    struct jpeg_compress_struct cinfo;
    jpeg_create_compress(&cinfo);
    jpeg_stdio_dest(&cinfo, stdout);
    jpeg_set_quality(&cinfo, JPEG_QUALITY, TRUE);

    // Write the image data to the JPEG stream
    jpeg_write_scanlines(&cinfo, &buffer.data->data, 1);

    // Clean up libjpeg
    jpeg_destroy_compress(&cinfo);

    // Close the video device and release resources
    close(fd);
    munmap(buffer.data->data, BUFFER_SIZE);
    free(buffer.data->data);

    return 0;
}

