    struct timeval timeout = {2, 0};
    FD_SET(fd, &readfds);
    if (select(fd + 1, &readfds, NULL, NULL, &timeout) < 0) {
        fprintf(stderr, "Error in select: %s\n", strerror(errno));
        munmap(buffer.data, BUFFER_SIZE);
        free(buffer.data);
        close(fd);
        return 1;
    }

    // Stream on and wait for frame
    if (ioctl(fd, VIDIOC_STREAMON, &buffer.buf) < 0) {
        fprintf(stderr, "Error streaming on: %s\n", strerror(errno));
        munmap(buffer.data, BUFFER_SIZE);
        free(buffer.data);
        close(fd);
        return 1;
    }

    // Dequeue the captured frame
    if (ioctl(fd, VIDIOC_DQBUF, &buffer.buf) < 0) {
        fprintf(stderr, "Error dequeuing frame: %s\n", strerror(errno));
        munmap(buffer.data, BUFFER_SIZE);
        free(buffer.data);
        close(fd);
        return 1;
    }

    // Convert YUYV to RGB24 here
    yuyvToRgb24(buffer.data->data, buffer.data->data, 640, 480);

    // Apply box blur
    boxBlur(buffer.data->data, buffer.data->data, 640, 480);

    // Save as JPEG
    struct jpeg_compress_struct cinfo;
    jpeg_create_compress(&cinfo);
    jpeg_stdio_dest(&cinfo, stdout);
    jpeg_set_quality(&cinfo, JPEG_QUALITY, TRUE);

    // Write the image data to the JPEG stream
    jpeg_write_scanlines(&cinfo, &buffer.data->data, 1);

    // Clean up libjpeg
    jpeg_destroy_compress(&cinfo);

    // Close the video device and release resources
    close(fd);
    munmap(buffer.data->data, BUFFER_SIZE);
    free(buffer.data->data);

    return 0;
}
