#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <video4linux2.h>

#define VIDEO_DEVICE "/dev/video0"

int main() {
    int fd = -1;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_fract frame_interval;
    int i, count;
    int autofocus_supported = 0;

    // Check if the device exists
    if ((fd = open(VIDEO_DEVICE, O_RDONLY | O_NONBLOCK)) == -1) {
        perror("Failed to open video device");
        return EXIT_FAILURE;
    }

    // Query capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP failed");
        close(fd);
        return EXIT_FAILURE;
    }

    // Check if the device is a camera
    if (cap.type != V4L2_TYPE_CAMERA) {
        printf("Device is not a camera\n");
        close(fd);
        return EXIT_FAILURE;
    }

    // Query focus auto control
    if (ioctl(fd, VIDIOC_QUERYCTRL, &cap) == -1) {
        perror("VIDIOC_QUERYCTRL failed");
        close(fd);
        return EXIT_FAILURE;
    }
    if (cap.caps & V4L2_CAP_AUTOFOCUS) {
        autofocus_supported = 1;
    } else {
        printf("Camera does not support autofocus\n");
    }

    // Enumerate frame sizes
    if (ioctl(fd, VIDIOC_ENUM_FMT, &fmt) == -1) {
        perror("VIDIOC_ENUM_FMT failed");
        close(fd);
        return EXIT_FAILURE;
    }
    count = 0;
    while (ioctl(fd, VIDIOC_G_FMT, &fmt) == 0) {
        fmt.fmt.pix.width = fmt.fmt.pix.width;
        fmt.fmt.pix.height = fmt.fmt.pix.height;
        printf("Frame size: %dx%d\n", fmt.fmt.pix.width, fmt.fmt.pix.height);
        count++;
    }
    if (count == 0) {
        printf("No supported frame sizes found\n");
    }

    // Enumerate frame intervals
    if (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frame_interval) == -1) {
        perror("VIDIOC_ENUM_FRAMEINTERVALS failed");
        close(fd);
        return EXIT_FAILURE;
    }
    count = 0;
    while (ioctl(fd, VIDIOC_G_FRAMEINTERVAL, &frame_interval) == 0) {
        printf("Frame interval: %d fps\n", frame_interval.den / frame_interval.num);
        count++;
    }
    if (count == 0) {
        printf("No supported frame intervals found\n");
    }

    // Close the device
    close(fd);

    // Exit with success if no fatal errors occurred
    return EXIT_SUCCESS;
}

