// Function to set up GPIO pins and servos
void setup_servos_and_buttons(void) {
    // Configure GPIO pins for buttons with internal pull-ups
    gpioMode(6, GPIO_INPUT_PULLUP);
    gpioMode(7, GPIO_INPUT_PULLUP);
    gpioMode(8, GPIO_INPUT_PULLUP);
    gpioMode(9, GPIO_INPUT_PULLUP);

    // Initialize servos to center position (1500 microseconds)
    gpioServo(4, 1500);
    gpioServo(5, 1500);

    printf("Pan servo on GPIO4, Tilt servo on GPIO5\n");
    printf("UP button on GPIO6, DOWN button on GPIO7\n");
    printf("LEFT button on GPIO8, RIGHT button on GPIO9\n");
    printf("Center position: 1500 microseconds\n");
}

// Function to handle button presses
void handle_button_presses(int buttons) {
    int pan_button = (buttons & (1 << 6)) != 0;
    int tilt_button = (buttons & (1 << 7)) != 0;
    int left_button = (buttons & (1 << 8)) != 0;
    int right_button = (buttons & (1 << 9)) != 0;

    if (pan_button) {
        if (gpioServo(4) < 1000) {
            gpioServo(4, 1000);
        } else if (gpioServo(4) > 2000) {
            gpioServo(4, 2000);
        } else {
            gpioServo(4, gpioServo(4) + 10);
        }
    }

    if (tilt_button) {
        if (gpioServo(5) < 1000) {
            gpioServo(5, 1000);
        } else if (gpioServo(5) > 2000) {
            gpioServo(5, 2000);
        } else {
            gpioServo(5, gpioServo(5) + 10);
        }
    }

    if (left_button) {
        if (gpioServo(4) > 1000) {
            gpioServo(4, 1000);
        } else {
            gpioServo(4, gpioServo(4) - 10);
        }
    }

    if (right_button) {
        if (gpioServo(5) < 2000) {
            gpioServo(5, 2000);
        } else {
            gpioServo(5, gpioServo(5) - 10);
        }
    }
