#include <string.h>
#include <ctype.h>
#include <curl/curl.h>
#include <libcamera/libcamera.h>
#include <pigpio.h>

#define PIR_GPIO 17
#define PIR_PIN 11
#define MOTION_CAPTURE_DIR "motion_captures"
#define JPEG_QUALITY 85
#define DEBOUNCE_TIME 2000

// Function prototypes
void initialize_pigpio();
void configure_gpio_input(int gpio);
void handle_motion_detection();
void capture_image_and_send_to_server(const char *filename);
void cleanup_resources();
void signal_handler(int signum);

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <server_ip>:<server_port>\n", argv[0]);
        return 1;
    }

    char *server_address = argv[1];
    char *parts[] = {server_address, ":80", NULL};
    CURL *curl = curl_easy_init();

    if (!curl) {
        fprintf(stderr, "Failed to initialize libcurl.\n");
        return 1;
    }

    curl_easy_setopt(curl, CURLOPT_URL, parts[0]);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    initialize_pigpio();
    if (PIR_GPIO == -1) {
        fprintf(stderr, "Failed to configure GPIO %d.\n", PIR_GPIO);
        return 1;
    }
    configure_gpio_input(PIR_GPIO);

    while (1) {
        if (pigpio_check_for_motion(PIR_PIN)) {
            handle_motion_detection();
        }
        usleep(100000);
    }

    cleanup_resources();

    curl_easy_cleanup(curl);
    return 0;
}

void initialize_pigpio() {
    if (pigpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return;
    }
}

void configure_gpio_input(int gpio) {
    if (gpio_set_direction(PIR_GPIO, GPIO_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d direction to input.\n", PIR_GPIO);
        return;
    }
    if (gpio_set_pull_mode(PIR_GPIO, GPIO_PULLDOWN) < 0) {
        fprintf(stderr, "Failed to set GPIO %d pull mode to down.\n", PIR_GPIO);
        return;
    }
}

void handle_motion_detection() {
    char filename[256];
    char timestamp[32];
    char motion_status[8];

    snprintf(filename, sizeof(filename), "%s/%s.jpg", MOTION_CAPTURE_DIR, "motion");
    struct libcamera_time ts;
    libcamera_time_init(&ts);
    libcamera_get_timestamp(&ts);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%06lu", &ts.time);
    strcpy(motion_status, "detected");

    FILE *file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file %s for writing.\n", filename);
        return;
    }

    if (libcamera_still(filename, JPEG_QUALITY) < 0) {
        fprintf(stderr, "Failed to capture image.\n");
        fclose(file);
        return;
    }

    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, "{\"filename\": \""
        "\"%s\", \"timestamp\": \"%s\", \"motion\": \"%s\", \"gpio\": %d}\n",
        filename, timestamp, motion_status, PIR_GPIO);
    curl_easy_perform(curl);

    fclose(file);
}

void capture_image_and_send_to_server(const char *filename) {
    // This function is a simplified version for demonstration purposes.
    // In a real application, you would handle the libcamera_still call and
    // the curl POST request more robustly, including error checking and cleanup.
    // Here, we assume successful image capture and HTTP POST operation.
}

void cleanup_resources() {
    gpioTerminate();
    curl_global_cleanup();
}

void signal_handler(int signum) {
    fprintf(stderr, "Caught signal %d, performing clean shutdown...\n", signum);
    cleanup_resources();
    exit(0);
}

