#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <libgpiod/gpiod.h>
#include <libcamera/libcamera.h>
#include <dirent.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <ctype.h>
#include <sys/time.h>

#define PIR_GPIO 17
#define PIR_PIN 11
#define IMAGES_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"

#define TIMEOUT_MS 50
#define CAPTURE_CMD "libcamera-still -o %s --width 640 --height 480 -q 85 --timeout 2000 --nopreview"

struct timespec timeout;
struct timeval timestamp;
char buffer[128];

void setup_pir() {
    int gpio_dev;
    struct gpiod gpio;

    if (gpiod_chip_open(&gpio, GPIOD_CHIP_NAME) < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    gpio_dev = gpiod_get_index_by_name(&gpio, "bcm2835-gpio", PIR_GPIO);
    if (gpio_dev < 0) {
        perror("Failed to get GPIO index");
        exit(EXIT_FAILURE);
    }

    if (gpiod_direction_input(gpio_dev) < 0) {
        perror("Failed to set GPIO direction");
        exit(EXIT_FAILURE);
    }

    if (gpiod_get_value(gpio_dev) == 0) {
        printf("PIR sensor is not HIGH initially, assuming it's configured correctly.\n");
    } else {
        printf("PIR sensor is HIGH initially, waiting for falling edge...\n");
    }

    timeout.tv_sec = 0;
    timeout.tv_nsec = TIMEOUT_MS * 1000000;

    while (1) {
        if (gpiod_get_value(gpio_dev) == 0) {
            printf("Falling edge detected, debouncing...\n");
            if (nanosleep(&timeout, NULL) == -1) {
                perror("nanosleep");
                exit(EXIT_FAILURE);
            }
            break;
        }
        usleep(10000); // 10ms debounce
    }

    printf("PIR sensor detected falling edge, ready for motion detection.\n");
}

void capture_image(char *filename) {
    int fd;
    pid_t pid;

    fd = open(filename, O_CREAT | O_WRONLY | O_TRUNC, S_IRUSR | S_IWUSR);
    if (fd == -1) {
        perror("Failed to open file for writing");
        exit(EXIT_FAILURE);
    }

    pid = fork();
    if (pid == -1) {
        perror("Failed to fork");
        exit(EXIT_FAILURE);
    }

    if (pid == 0) { // Child process
        char *command = malloc(strlen(CAPTURE_CMD) + strlen(filename) + 1);
        strcpy(command, CAPTURE_CMD);
        strcat(command, " ");
        strcat(command, filename);

        if (system(command) != 0) {
            fprintf(stderr, "Failed to capture image: %s\n", command);
            close(fd);
            exit(EXIT_FAILURE);
        }

        close(fd);
        exit(EXIT_SUCCESS);
    }

    close(fd);
}

void handle_motion() {
    char timestamp_str[32];
    struct tm tm;
    time_t now = time(NULL);

    localtime_r(&now, &tm);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y%m%d_%H%M%S", &tm);

    char filename[256];
    snprintf(filename, sizeof(filename), "%s/%s_%s.jpg", IMAGES_DIR, timestamp_str, "pir");

    capture_image(filename);
    fprintf(LOG_FILE, "Motion detected at %s, image captured to %s\n", timestamp_str, filename);
}

int main() {
    setup_pir();

    while (1) {
        int value;
        ssize_t bytes_read;

        if ((bytes_read = read(gpio_dev, &value, sizeof(value))) == -1) {
            perror("Failed to read GPIO value");
            exit(EXIT_FAILURE);
        }

        if (value == 0) {
            handle_motion();
        }

        // Handle SIGINT and SIGTERM
        if (bytes_read == -1 && errno == EINTR) {
            // Interrupted system call, continue
            continue;
        } else if (bytes_read == -1) {
            perror("Error reading GPIO value");
            break;
        }
    }

    // Release resources on exit
    gpiod_chip_close(&gpio);

    return 0;
}

