#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <errno.h>

#define VIDEO_DEVICE "/dev/video0"
#define VIDEO_WIDTH 640
#define VIDEO_HEIGHT 480
#define CROP_WIDTH 200
#define CROP_HEIGHT 150
#define YUV_BUFFER_SIZE (CROP_WIDTH * CROP_HEIGHT * 2)

typedef struct {
    uint8_t y0, u, y1, v;
} YUVMacroblock;

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers reqbuf;
    struct v4l2_buffer buf;
    void *map;
    ssize_t bytes_read;
    YUVMacroblock *yuv_frame = malloc(YUV_BUFFER_SIZE);
    int sigint_handler = 0;

    // Open the video device
    fd = open(VIDEO_DEVICE, O_RDWR);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    // Query device capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        close(fd);
        exit(EXIT_FAILURE);
    }
    if (cap.capabilities & V4L2_CAP_VIDEO_CAPTURE) {
        printf("Device is a video capture device.\n");
    } else {
        fprintf(stderr, "Device is not a video capture device.\n");
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Set up the format
    fmt.type = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.width = VIDEO_WIDTH;
    fmt.fmt.pix.height = VIDEO_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    // Request buffers
    reqbuf.count = 1;
    reqbuf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_REQBUFS, &reqbuf) < 0) {
        perror("VIDIOC_REQBUFS");
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Query the buffer size
    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("VIDIOC_QUERYBUF");
        close(fd);
        exit(EXIT_FAILURE);
    }
    map = mmap(0, buf.memory.size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.memory.moffset);
    if (map == MAP_FAILED) {
        perror("mmap");
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Start streaming
    if (ioctl(fd, VIDIOC_STREAMON, &buf) < 0) {
        perror("VIDIOC_STREAMON");
        munmap(map, buf.memory.size);
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Handle Ctrl-C cleanly
    sigint_handler = signal(SIGINT, SIG_IGN);
    sigint_handler = signal(SIGTERM, sigint_handler);

    // Main loop to capture and process frames
    while (1) {
        struct timeval timeout = {2, 0};
        fd_set readfds;
        FD_SET(fd, &readfds);

        // Wait for data with a timeout
        if (select(fd + 1, &readfds, NULL, NULL, &timeout) == -1 && errno == EINTR) {
            continue;
        } else if (select(fd + 1, &readfds, NULL, NULL, &timeout) == -1) {
            perror("select");
            break;
        }

        // Dequeue the buffer
        if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            perror("VIDIOC_DQBUF");
            continue;
        }

        // Verify captured frame dimensions
        if (buf.width != VIDEO_WIDTH || buf.height != VIDEO_HEIGHT) {
            fprintf(stderr, "Captured frame dimensions do not match requested values.\n");
            break;
        }

        // Copy the frame to YUV buffer
        bytes_read = fread(yuv_frame, sizeof(YUVMacroblock), YUV_BUFFER_SIZE, map);
        if (bytes_read != YUV_BUFFER_SIZE) {
            perror("fread");
            continue;
        }

        // Crop the region
        for (int i = 0; i < YUV_BUFFER_SIZE / 4; i++) {
            int y = yuv_frame[i].y0;
            int u = yuv_frame[i + 1].u;
            int y1 = yuv_frame[i + 2].y1;
            int v = yuv_frame[i + 3].v;

            // Crop region starting at (100, 50) with size 200x150
            if (i >= 100 * 2 && i < (100 + 200) * 2 && (i / 2) >= 50 * 2 && (i / 2) < (50 + 150) * 2) {
                cropped_yuv[(i * 2)++] = y;
                cropped_yuv[(i * 2)++] = u;
                cropped_yuv[(i * 2)++] = y1;
                cropped_yuv[(i * 2)++] = v;
            }
        }

        // Save cropped frame
        FILE *out = fopen("cropped.yuv", "wb");
        if (!out) {
            perror("fopen");
            continue;
        }
        fwrite(cropped_yuv, sizeof(YUVMacroblock), YUV_BUFFER_SIZE / 4, out);
        fclose(out);

        // Stop streaming and clean up
        if (sigint_handler) {
            signal(SIGINT, sigint_handler);
            signal(SIGTERM, SIG_DFL);
        }
        ioctl(fd, VIDIOC_STREAMOFF, &buf);
        munmap(map, buf.memory.size);
        close(fd);
        free(yuv_frame);
    }

    return 0;
}

