#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PIGPIO_PORT 17 // GPIO 17 for pan servo
#define PIGPIO_TILT_PORT 18 // GPIO 18 for tilt servo
#define SERVO_MIN_PULSE 500 // Minimum pulse width for 0 degrees
#define SERVO_MAX_PULSE 2500 // Maximum pulse width for 180 degrees
#define STEP_SIZE 5 // Step size in degrees
#define NEUTRAL_ANGLE 90 // Neutral angle in degrees
#define DELAY_MS 100 // Delay in milliseconds between commands

// Function prototypes
void setup_pigpio();
void handle_input(char command);
void set_servo_position(int angle);
void cleanup_pigpio();
void handle_signal(int signum);

int main() {
    // Initialize pigpio
    setup_pigpio();

    // Set initial servo positions to neutral
    set_servo_position(NEUTRAL_ANGLE);

    // Signal handler for SIGINT and 'q' input
    signal(SIGINT, handle_signal);
    char input;
    while (1) {
        // Read user input
        printf("Enter command (u/d/l/r/q to quit): ");
        scanf("%c", &input);

        // Handle 'q' input to quit
        if (input == 'q') {
            cleanup_pigpio();
            exit(0);
        }

        // Handle input commands
        handle_input(input);
    }

    // Clean up pigpio resources
    cleanup_pigpio();

    return 0;
}

// Function to setup pigpio
void setup_pigpio() {
    if (pigpioSetup(0) == -1) {
        fprintf(stderr, "Failed to initialize pigpio. Error: %s\n", pigpioError());
        exit(1);
    }

    // Set GPIO ports for servo control
    if (pigpioWriteFuncSet(PIGPIO_PORT, pigpioOutputActiveHigh, 1) == -1 ||
        pigpioWriteFuncSet(PIGPIO_TILT_PORT, pigpioOutputActiveHigh, 1) == -1) {
        fprintf(stderr, "Failed to set GPIO ports for servo control. Error: %s\n", pigpioError());
        exit(1);
    }
}

// Function to handle user input
void handle_input(char command) {
    int angle;

    switch (command) {
        case 'u':
            angle = NEUTRAL_ANGLE - STEP_SIZE;
            if (angle < 0) {
                angle = 0;
            }
            set_servo_position(angle);
            break;
        case 'd':
            angle = NEUTRAL_ANGLE + STEP_SIZE;
            if (angle > 180) {
                angle = 180;
            }
            set_servo_position(angle);
            break;
        case 'l':
            angle = NEUTRAL_ANGLE - STEP_SIZE;
            if (angle < 0) {
                angle = 0;
            }
            set_servo_position(angle);
