// SSD1306 Display Configuration
#define OLED_RESET 0
#define OLED_DC GPIO26
#define OLED_CS GPIO24
#define OLED_RESET_GPIO GPIO17
#define OLED_SDA GPIO10
#define OLED_SCL GPIO9

// I2C Address for SSD1306
#define SSD1306_ADDRESS 0x3C

// GPIO Pin Definitions
#define GPIO26 18
#define GPIO24 22
#define GPIO17 11
#define GPIO10 5
#define GPIO9 7

// Font Data
const uint8_t font_bits[][5] = {
    {0b00000, 0b10000, 0b01000, 0b00100, 0b00001},
    {0b00010, 0b11000, 0b01010, 0b01100, 0b00011},
    {0b00001, 0b10100, 0b01100, 0b11100, 0b00011},
    {0b00011, 0b10110, 0b01111, 0b11111, 0b00001},
    {0b00111, 0b11110, 0b11111, 0b01111, 0b00111},
    // Add more characters as needed
};

// Bitmap Font Width and Height
#define FONT_WIDTH 5
#define FONT_HEIGHT 7

// OLED Display Configuration
#define OLED_WIDTH 128
#define OLED_HEIGHT 64

// CPU Temperature and Usage Variables
float cpu_temperature;
float cpu_usage;

// Main Function
int main() {
    // Initialize pigpio
    if (pigpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error());
        return EXIT_FAILURE;
    }

    // Open GPIO pins
    if ((gpio_mode_export(GPIO26, GPIO_OUT) == -1) ||
        (gpio_mode_export(GPIO24, GPIO_OUT) == -1) ||
        (gpio_mode_export(GPIO17, GPIO_OUT) == -1) ||
        (gpio_mode_export(GPIO10, GPIO_IN) == -1) ||
        (gpio_mode_export(GPIO9, GPIO_IN) == -1)) {
        fprintf(stderr, "Failed to export GPIO pins: %s\n", strerror(errno));
        pigpio_cleanup();
        return EXIT_FAILURE;
    }

    // Set GPIO pins to appropriate modes
    if (gpio_direction_export(GPIO26, GPIO_OUTPUT) == -1 ||
        gpio_direction_export(GPIO24, GPIO_OUTPUT) == -1 ||
        gpio_direction_export(GPIO17, GPIO_OUTPUT) == -1 ||
        gpio_direction_input(GPIO10) == -1 ||
        gpio_direction_input(GPIO9) == -1) {
        fprintf(stderr, "Failed to set GPIO modes: %s\n", strerror(errno));
        pigpio_cleanup();
        return EXIT_FAILURE;
    }

    // Initialize OLED Display
    if (ssd1306_init(OLED_RESET_GPIO, OLED_DC, OLED_CS, SSD1306_ADDRESS, OLED_SDA, OLED_SCL) == SSD1306_ERROR) {
        fprintf(stderr, "Failed to initialize OLED display: %s\n", ssd1306_error());
        pigpio_cleanup();
        return EXIT_FAILURE;
    }

    // CPU Temperature and Usage Reading Loop
    while (1) {
        // Read CPU temperature
        char temp_str[20];
        if ((temp_file = fopen("/sys/class/thermal/thermal_zone0/temp", "r")) == NULL) {
            sprintf(temp_str, "Error reading temperature: %s");
        } else {
            if (fscanf(temp_file, "%f", &cpu_temperature) != 1) {
                fclose(temp_file);
                sprintf(temp_str, "Error reading temperature");
            } else {
                fclose(temp_file);
                temp_str[0] = '\0';
            }
        }

        // Read CPU usage
        char usage_str[20];
        if ((proc_file = fopen("/proc/stat", "r")) == NULL) {
            sprintf(usage_str, "Error reading CPU usage: %s");
        } else {
            char line[256];
            while (fgets(line, 256, proc_file) != NULL) {
                if (strncmp(line, "cpu ", 4) == 0) {
                    char *end;
                    char *token = strtok_r(line + 4, " ", &end);
                    if (sscanf(token, "%f", &cpu_usage) != 1) {
                        fclose(proc_file);
                        sprintf(usage_str, "Error reading CPU usage");
                    } else {
                        fclose(proc_file);
                        usage_str[0] = '\0';
                    }
                    break;
                }
            }
        }

        // Display Temperature and Usage
        if (ssd1306_display_clear(OLED_RESET) == SSD1306_ERROR) {
            fprintf(stderr, "Failed to clear OLED display: %s\n", ssd1306_error());
            break;
        }

        // Convert temperature to string
        char temp_str_display[10];
        sprintf(temp_str_display, "%0.1f", cpu_temperature);

        // Convert usage to string
        char usage_str_display[10];
        sprintf(usage_str_display, "%0.1f", cpu_usage * 100);

        // Draw text on OLED
        if (ssd1306_text_string(OLED_RESET, 0, 0, FONT_HEIGHT / 2, temp_str_display) != SSD1306_ERROR) {
            fprintf(stderr, "Failed to draw temperature on OLED: %s\n", ssd1306_error());
            break;
        }
        if (ssd1306_text_string(OLED_RESET, OLED_WIDTH / 8, 0, FONT_HEIGHT / 2, usage_str_display) != SSD1306_ERROR) {
            fprintf(stderr, "Failed to draw CPU usage on OLED: %s\n", ssd1306_error());
            break;
        }

        // Update display
        if (ssd1306_display_update(OLED_RESET) == SSD1306_ERROR) {
            fprintf(stderr, "Failed to update OLED display: %s\n", ssd1306_error());
            break;
        }

        // Sleep for 1 second
        usleep(1000000);
    }

    // Clean up
    ssd1306_display_power_off(OLED_RESET);
    gpio_unexport(GPIO26);
    gpio_unexport(GPIO24);
    gpio_unexport(GPIO17);
    gpio_unexport(GPIO10);
    gpio_unexport(GPIO9);
    pigpio_cleanup();

    return EXIT_SUCCESS;
}

// Signal Handler for SIGINT
void signal_handler(int signum) {
    fprintf(stderr, "Caught SIGINT, exiting gracefully...\n");
    // Release resources here
    // Example: Close files, release GPIOs, etc.
    exit(EXIT_FAILURE);
}

