#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <wiringPiI2C.h>

// Constants
#define GPIO_PIN 17
#define CALIBRATION_PULSES_PER_LITER 450
#define LCD_ADDRESS 0x27
#define LCD_LINE_LENGTH 16

// Global variables
pigpio *pi;
FILE *flow_log_file;
int flow_rate_lpm = 0;
unsigned long total_volume_liters = 0;
unsigned long last_log_time = 0;
wiringPiI2C *i2c;
char lcd_message[LCD_LINE_LENGTH];

void setup_pigpio() {
    if (pi == NULL) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }
}

void setup_i2c() {
    if (wiringPiI2CSetup(1) == -1) {
        fprintf(stderr, "Failed to setup I2C bus 1\n");
        exit(EXIT_FAILURE);
    }
    if (wiringPiI2CWrite(1, LCD_ADDRESS, 0x00) != 0) {
        fprintf(stderr, "Failed to write to LCD address 0x27\n");
        exit(EXIT_FAILURE);
    }
    if (wiringPiI2CRead(1, LCD_ADDRESS, 0x00, 1) != 1) {
        fprintf(stderr, "Failed to read from LCD address 0x27\n");
        exit(EXIT_FAILURE);
    }
    i2c = wiringPiI2CNew();
}

void cleanup() {
    if (i2c != NULL) {
        wiringPiI2CDelete(i2c);
        i2c = NULL;
    }
    if (pi != NULL) {
        pigpiodFree(pi);
        pi = NULL;
    }
}

void read_flow_sensor() {
    int count = 0;
    if (pigpioPinRead(GPIO_PIN) == 0) {
        while (pigpioPinRead(GPIO_PIN) == 0) {
            count++;
        }
    }
    flow_rate_lpm = count * (1.0 / CALIBRATION_PULSES_PER_LITER);
    total_volume_liters += flow_rate_lpm;
    last_log_time = millis();
}

void update_lcd() {
    sprintf(lcd_message, "Flow Rate: %.2f LPM, Volume: %.2f L", flow_rate_lpm, (total_volume_liters / 1000.0));
    if (wiringPiI2CWrite(1, LCD_ADDRESS, 0x80) != 0) {
        fprintf(stderr, "Failed to write to LCD command register\n");
        return;
    }
    if (wiringPiI2CWrite(1, LCD_ADDRESS, (uint8_t *)lcd_message, strlen(lcd_message)) != strlen(lcd_message)) {
        fprintf(stderr, "Failed to write to LCD data register\n");
        return;
    }
}

void handle_signal(int signum) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    setup_pigpio();
    setup_i2c();

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        read_flow_sensor();
        update_lcd();

        if (millis() - last_log_time >= 1000) {
            fprintf(stderr, "Flow Rate: %.2f LPM, Volume: %.2f L\n", flow_rate_lpm, total_volume_liters);
            last_log_time = millis();
        }

        // Sleep for 10 seconds between LCD updates
        if (millis() - (last_update_time + 10000) >= 10000) {
            last_update_time = millis();
            update_lcd();
        }
    }

    return 0;
}

