#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <wiringPiI2C.h>

#define PI_GPIO 17 // GPIO17 for YF-S201 sensor
#define PI_GPIO_ALERT 18 // GPIO18 for alert (optional)
#define SENSOR_CAL_FACTOR 7.5 // Calibration factor: 7.5 pulses per liter
#define I2C_BUS 1 // I2C bus 1
#define I2C_ADDR 0x27 // PCF8574 address 0x27

volatile int flowPulses = 0;
float flowRate = 0.0;
int lastPulseTime = 0;

// Function prototypes
void setupPigpio();
void setupGPIO();
void setupFlowSensor();
void setupLCD();
void measureFlow();
void handleSignals(int signum);
void cleanup();

int main() {
    signal(SIGINT, handleSignals);
    signal(SIGTERM, handleSignals);

    setupPigpio();
    setupGPIO();
    setupFlowSensor();
    setupLCD();

    while (1) {
        measureFlow();
        printf("Flow Rate: %f L/min\n", flowRate);
        fflush(stdout);
        usleep(100000); // Sleep for 0.1 seconds
    }

    return 0;
}

// Function: setupPigpio
void setupPigpio() {
    if (pigpioSetup() == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }
}

// Function: setupGPIO
void setupGPIO() {
    if (gpioMode(PI_GPIO, GPIO_INPUT) == -1) {
        fprintf(stderr, "Failed to set GPIO %d to input: %s\n", PI_GPIO, strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (gpioMode(PI_GPIO_ALERT, GPIO_OUTPUT_LOW) == -1) {
        fprintf(stderr, "Failed to set GPIO %d to output low: %s\n", PI_GPIO_ALERT, strerror(errno));
        exit(EXIT_FAILURE);
    }
}

// Function: setupFlowSensor
void setupFlowSensor() {
    if (gpioDigitalRead(PI_GPIO) == 0) {
        fprintf(stderr, "Flow sensor not detected on GPIO %d\n", PI_GPIO);
        exit(EXIT_FAILURE);
    }

    // Initialize flow rate to 0
    flowPulses = 0;
    lastPulseTime = pigpioGetTime();

    // Start monitoring GPIO for pulses
    pigpioDigitalMode(PI_GPIO, pigpio_INPUT_PULSE_LOW);
    pigpioAddWatch(PI_GPIO, measureFlow, NULL);
}

// Function: setupLCD
void setupLCD() {
    if (wiringPiI2CSetup(I2C_BUS) == -1) {
        fprintf(stderr, "Failed to setup I2C bus: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (i2cWrite(I2C_BUS, I2C_ADDR, 0x04, 0x12) != 2) {
        fprintf(stderr, "Failed to write to LCD: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

// Function: measureFlow
void measureFlow() {
    int currentPulse = gpioDigitalRead(PI_GPIO);

    if (currentPulse) {
        flowPulses++;
        lastPulseTime = pigpioGetTime();

        // Calculate flow rate in liters per minute
        float timeElapsed = pigpioGetTime() - lastPulseTime;
        float flowRateValue = (flowPulses * SENSOR_CAL_FACTOR) / 60.0;

        // Update flow rate
        flowRate = flowRateValue;

        // Clear alert flag
        gpioDigitalWrite(PI_GPIO_ALERT, 0);
    } else {
        // No pulses detected for a while, consider sensor absent
        if (pigpioGetTime() - lastPulseTime > 60000) {
            fprintf(stderr, "Sensor absent for 1 minute.\n");
            flowRate = 0.0;
        }
    }
}

// Function: handleSignals
void handleSignals(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        cleanup();
        exit(EXIT_SUCCESS);
    }
}

// Function: cleanup
void cleanup() {
    pigpioStopWatch(PI_GPIO);
    pigpioShutdown();
    wiringPiI2CShutdown();
    gpioFree(PI_GPIO);
    gpioFree(PI_GPIO_ALERT);
}

