#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_ROWS 8
#define NUM_COLUMNS 8
#define DELAY_MS 150

// GPIO pins configuration
#define ROW_PINS {2, 3, 4, 17, 27, 22, 10, 9}
#define COLUMN_PINS {14, 15, 18, 23, 24, 25, 8, 7}

// Function prototypes
void setup_gpios(void);
void cleanup_gpios(void);
void animate_column(int column);
void handle_signal(int signum);

int main(void) {
    // Initialize GPIO chip
    if (gpiod_chip_open(GPIOD, "bcm2835") < 0) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    // Set up GPIO pins for rows and columns
    setup_gpios();

    // Install signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (1) {
        // Wait for user interrupt
        if (gpiod_is_closed(GPIOD)) {
            break;
        }
        usleep(1000000); // 1 second delay
    }

    // Clean up GPIO resources
    cleanup_gpios();

    return EXIT_SUCCESS;
}

// Function to setup GPIO pins
void setup_gpios(void) {
    int ret;

    // Iterate over row pins
    for (int i = 0; i < NUM_ROWS; ++i) {
        ret = gpiod_line_request_output(GPIOD, ROW_PINS[i], GPIO_OUTPUT_LOW);
        if (ret < 0) {
            perror("gpiod_line_request_output for row pin");
            exit(EXIT_FAILURE);
        }
    }

    // Iterate over column pins
    for (int i = 0; i < NUM_COLUMNS; ++i) {
        ret = gpiod_line_request_output(GPIOD, COLUMN_PINS[i], GPIO_OUTPUT_LOW);
        if (ret < 0) {
            perror("gpiod_line_request_output for column pin");
            exit(EXIT_FAILURE);
        }
    }
}

// Function to animate a single column
void animate_column(int column) {
    // Set the column cathode LOW and all row anodes HIGH
    gpiod_set_value(GPIOD, COLUMN_PINS[column], GPIO_OUTPUT_LOW);
    for (int i = 0; i < NUM_ROWS; ++i) {
        gpiod_set_value(GPIOD, ROW_PINS[i], GPIO_OUTPUT_HIGH);
    }

    // Wait for the delay
    usleep(DELAY_MS * 1000);

    // Clear the matrix by setting all column cathodes HIGH and all row anodes LOW
    for (int i = 0; i < NUM_COLUMNS; ++i) {
        gpiod_set_value(GPIOD, COLUMN_PINS[i], GPIO_OUTPUT_HIGH);
    }
    for (int i = 0; i < NUM_ROWS; ++i) {
        gpiod_set_value(GPIOD, ROW_PINS[i], GPIO_OUTPUT_LOW);
    }

    // Move to the next column
    if (column < NUM_COLUMNS - 1) {
        animate_column(column + 1);
    }
}

// Function to handle signals (SIGINT, SIGTERM)
void handle_signal(int signum) {
    // Clean up GPIO resources
    cleanup_gpios();

    // Exit the program
    exit(EXIT_SUCCESS);
}

// Function to cleanup GPIO resources
void cleanup_gpios(void) {
    // Iterate over row pins and release them
    for (int i = 0; i < NUM_ROWS; ++i) {
        gpiod_line_release(GPIOD, ROW_PINS[i]);
    }

    // Iterate over column pins and release them
    for (int i = 0; i < NUM_COLUMNS; ++i) {
        gpiod_line_release(GPIOD, COLUMN_PINS[i]);
    }

    // Close the GPIO chip
    gpiod_chip_close(GPIOD);
}

