void read_distance(struct pigpio *gp) {
    uint16_t data_low, data_high;
    int ret;

    // Start measurement
    ret = pigpio_i2c_write(gp, I2C_BUS, I2C_ADDRESS, &VL53L3CX_REG_START_MEASUREMENT, 1);
    if (ret != 1) {
        fprintf(stderr, "Error starting measurement\n");
        return;
    }

    // Wait for measurement to complete
    usleep(5000); // Wait for a reasonable amount of time

    // Read data from the sensor
    ret = pigpio_i2c_read(gp, I2C_BUS, I2C_ADDRESS, &data_low, 2);
    if (ret != 2) {
        fprintf(stderr, "Error reading distance data\n");
        return;
