    ret = pigpio_i2c_read(gp, I2C_BUS, I2C_ADDRESS, &data_high, 2);
    if (ret != 2) {
        fprintf(stderr, "Error reading distance data\n");
        return;
    }

    // Combine low and high bytes to form the 16-bit distance measurement
    uint16_t distance = (data_low << 8) | data_high;

    // Print distance and timestamp
    char timestamp[50];
    time_t t = time(NULL);
    struct tm *timeinfo = localtime(&t);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("Distance: %u cm at %s\n", distance, timestamp);
