#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdint.h>

// Define the I2C address and registers
#define SI1145_ADDR 0x60
#define PART_ID_REG 0x00
#define COMMAND_REG 0x18

// Function prototypes
void handleSIGINT(int signum);
int i2cWrite(uint8_t addr, uint8_t reg, uint8_t data);
int i2cRead(uint8_t addr, uint8_t reg, uint8_t *data);

// Main function
int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", gpioError());
        return EXIT_FAILURE;
    }

    // Install SIGINT handler
    signal(SIGINT, handleSIGINT);

    // Check if the sensor is present
    if (i2cWrite(SI1145_ADDR, PART_ID_REG, 0x00) != 0) {
        fprintf(stderr, "Sensor not found or I2C write failed.\n");
        return EXIT_FAILURE;
    }

    // Read PART ID register to verify sensor
    uint8_t partId;
    if (i2cRead(SI1145_ADDR, PART_ID_REG, &partId) != 0) {
        fprintf(stderr, "Failed to read PART ID register.\n");
        return EXIT_FAILURE;
    }

    if (partId != 0x45) {
        fprintf(stderr, "Expected PART ID 0x45, got 0x%02X.\n", partId);
        return EXIT_FAILURE;
    }

    // Initialize the sensor
    if (i2cWrite(SI1145_ADDR, COMMAND_REG, 0x01) != 0) {
        fprintf(stderr, "Failed to initialize sensor.\n");
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Sample every 500 ms
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        ts.tv_sec += 500 / 1000;
        ts.tv_nsec += (500 % 1000) * 1000000;

        // Read ambient light and proximity data
        uint8_t ambientLight;
        uint8_t proximity;
        if (i2cRead(SI1145_ADDR, SI1145_AMBIENT_LIGHT_REG, &ambientLight) != 0) {
            fprintf(stderr, "Failed to read ambient light.\n");
            continue;
        }
        if (i2cRead(SI1145_ADDR, SI1145_PROXIMITY_REG, &proximity) != 0) {
            fprintf(stderr, "Failed to read proximity.\n");
            continue;
        }

        // Log readings with ISO-8601 timestamp
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%03uZ", &ts);
        fprintf(stderr, "Ambient Light: %u, Proximity: %u, Timestamp: %s\n", ambientLight, proximity, timestamp);

        // Sleep for 500 ms
        usleep(500 * 1000);
    }

    // SIGINT handler
    void handleSIGINT(int signum) {
        // Close I2C handle
        if (i2cClose() != 0) {
            fprintf(stderr, "Failed to close I2C handle.\n");
        }

        // Flush and close the log file
        if (fclose(stderr) != 0) {
            fprintf(stderr, "Failed to close log file.\n");
        }

        // Terminate GPIO
        if (gpioTerminate() < 0) {
            fprintf(stderr, "Failed to terminate GPIO.\n");
        }
    }

    return EXIT_SUCCESS;
}

