// Function to set up GPIO lines
void setup_gpios(void) {
    // Open GPIO chip by name "gpiochip4"
    char *chip_name = "gpiochip4";
    gpio_chip_fd = gpiod_chip_open_by_name(chip_name);
    if (gpio_chip_fd == -1) {
        // Fall back to "gpiochip0" if "gpiochip4" is not available
        chip_name = "gpiochip0";
        gpio_chip_fd = gpiod_chip_open_by_name(chip_name);
        if (gpio_chip_fd == -1) {
            fprintf(stderr, "Failed to open GPIO chip.\n");
            exit(EXIT_FAILURE);
        }
    }

    // Open GPIO lines
    int sensor_gpio_fd = gpiod_pin_open(gpio_chip_fd, SENSOR_GPIO, GPIOD_DIR_IN);
    if (sensor_gpio_fd == -1) {
        fprintf(stderr, "Failed to open GPIO pin %d (input).\n", SENSOR_GPIO);
        gpiod_chip_close(gpio_chip_fd);
        exit(EXIT_FAILURE);
    }

    int led_gpio_fd = gpiod_pin_open(gpio_chip_fd, LED_GPIO, GPIOD_DIR_OUT);
    if (led_gpio_fd == -1) {
        fprintf(stderr, "Failed to open GPIO pin %d (output).\n", LED_GPIO);
        gpiod_pin_close(sensor_gpio_fd);
        gpiod_chip_close(gpio_chip_fd);
        exit(EXIT_FAILURE);
    }

    // Set LED GPIO as output
    gpiod_pin_direction(led_gpio_fd, GPIOD_DIR_OUT);

    // Keep track of GPIO resources
    int gpio_resources[2] = {sensor_gpio_fd, led_gpio_fd};
}

// Function to poll the sensor and blink the LED
void poll_sensor_and_blink_led(void) {
    struct timespec ts;
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char timestamp[50];

    // Format timestamp in ISO 8601 UTC format
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    // Read sensor value
    int sensor_value = gpiod_pin_read(sensor_gpio_fd);
    if (sensor_value == DETECTED_THRESHOLD) {
        // Blink LED for 100 ms
        gpiod_pin_write(led_gpio_fd, 1); // Turn LED ON
        usleep(LED_BLINK_MS * 1000); // Wait 100 ms
        gpiod_pin_write(led_gpio_fd, 0); // Turn LED OFF

        // Log detection
        log_detection(timestamp);
    }

    // Poll again after 100 ms
    ts.tv_sec = now + POLL_INTERVAL_MS / 1000;
    ts.tv_nsec = 0;
    nanosleep(&ts, NULL);
}

// Function to log a detection event
void log_detection(char *message) {
    FILE *log_file = fopen("proximity.log", "a+");
    if (!log_file) {
        perror("Failed to open proximity.log for writing");
        return;
    }

    fprintf(log_file, "%s\n", message);
    fclose(log_file);
}

// Error handling for resource release
void cleanup_resources(void) {
    if (sensor_gpio_fd != -1) {
        gpiod_pin_close(sensor_gpio_fd);
    }
    if (led_gpio_fd != -1) {
        gpiod_pin_close(led_gpio_fd);
    }
    gpiod_chip_close(gpio_chip_fd);
}

// SIGINT and SIGTERM handlers
void sigint_handler(int signum) {
    fprintf(stderr, "Caught SIGINT, cleaning up...\n");
    cleanup_resources();
    exit(EXIT_FAILURE);
}

void sigterm_handler(int signum) {
    fprintf(stderr, "Caught SIGTERM, cleaning up...\n");
    cleanup_resources();
    exit(EXIT_FAILURE);
}

// Install signal handlers
void install_signal_handlers(void) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    sa.sa_handler = sigterm_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGTERM, &sa, NULL);
}

// Main program initialization
int main(void) {
    // Initialize logging
    setup_gpios();
    install_signal_handlers();
    while (1) {
        poll_sensor_and_blink_led();
    }
    return 0;
}
