#define SI1145_ADDR 0x60

// Sensor registers
#define PART_ID_REG 0x00
#define HW_KEY_REG 0x07
#define CH_LIST_REG 0x4F
#define COMMAND_REG 0x30
#define PS1_REG_LOW 0x18
#define PS1_REG_HIGH 0x19
#define ALS_VIS_REG_LOW 0x22
#define ALS_VIS_REG_HIGH 0x23

// Sensor commands
#define ALS_FORCE_CMD 0x06
#define PS_FORCE_CMD 0x07

// Sensor data ranges
#define PS1_MAX 4095
#define ALS_MAX 4095

// CSV file name
