        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
        log_data(timestamp, ps1, als_vis);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    cleanup();

    return 0;
}

// Function to initialize pigpio
void init_pigpio() {
    if (gpioInitialise(PI_GPIO_ID) == -1) {
        fprintf(stderr, "Error initializing GPIO: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

// Function to initialize SI1145 sensor
void init_si1145() {
    if (pigpioI2CWrite(SI1145_ADDR, COMMAND_REG, ALS_FORCE_CMD) != 0) {
        fprintf(stderr, "Error writing to SI1145: %s\n", pigpioI2CError());
        exit(EXIT_FAILURE);
    }
    if (pigpioI2CWrite(SI1145_ADDR, COMMAND_REG, PS_FORCE_CMD) != 0) {
        fprintf(stderr, "Error writing to SI1145: %s\n", pigpioI2CError());
        exit(EXIT_FAILURE);
    }
    if (pigpioI2CWrite(SI1145_ADDR, CH_LIST_REG, 0x03) != 0) {
        fprintf(stderr, "Error writing to CH_LIST: %s\n", pigpioI2CError());
        exit(EXIT_FAILURE);
    }
}

// Function to read SI1145 data
void read_si1145_data(uint16_t *ps1, uint16_t *als_vis) {
    if (pigpioI2CRead(SI1145_ADDR, PART_ID_REG, &uint8_t(0x45)) != 0) {
        fprintf(stderr, "Error reading PART_ID: %s\n", pigpioI2CError());
        *ps1 = 0;
        *als_vis = 0;
        return;
    }

    if (pigpioI2CWrite(SI1145_ADDR, HW_KEY_REG, 0x17) != 0) {
        fprintf(stderr, "Error writing to HW_KEY: %s\n", pigpioI2CError());
        return;
    }

    if (pigpioI2CRead(SI1145_ADDR, PS1_REG_LOW, &uint8_t(0)) != 0 ||
        pigpioI2CRead(SI1145_ADDR, PS1_REG_HIGH, &uint8_t(0)) != 0) {
        fprintf(stderr, "Error reading PS1: %s\n", pigpioI2CError());
        *ps1 = 0;
        return;
    }

    *ps1 = (uint16_t) ((uint8_t) pigpioI2CRead(SI1145_ADDR, PS1_REG_LOW) << 8) | (uint8_t) pigpioI2CRead(SI1145_ADDR, PS1_REG_HIGH);

    if (pigpioI2CRead(SI1145_ADDR, ALS_VIS_REG_LOW, &uint8_t(0)) != 0 ||
        pigpioI2CRead(SI1145_ADDR, ALS_VIS_REG_HIGH, &uint8_t(0)) != 0) {
        fprintf(stderr, "Error reading ALS_VIS: %s\n", pigpioI2CError());
        *als_vis = 0;
        return;
    }

    *als_vis = (uint16_t) ((uint8_t) pigpioI2CRead(SI1145_ADDR, ALS_VIS_REG_LOW) << 8) | (uint8_t) pigpioI2CRead(SI1145_ADDR, ALS_VIS_REG_HIGH);
}

// Function to log data to CSV file
void log_data(const char *timestamp, uint16_t ps1, uint16_t als_vis) {
    FILE *file = fopen(CSV_FILE_NAME, "a");
    if (!file) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        return;
    }

    fprintf(file, "%s, %d, %d\n", timestamp, ps1, als_vis);
    fclose(file);
}

// Function to cleanup resources
void cleanup() {
    fclose(STDOUT_FILENO); // Ensure file is flushed and closed
    pigpioTerminate();
}

// SIGINT handler
void sigint_handler(int signum) {
    cleanup();
    exit(EXIT_SUCCESS);
}

