#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <gpiod.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>

#define TRIGGER_GPIO 17
#define ECHO_GPIO 27
#define TRIGGER_PIN -1
#define ECHO_PIN -1
#define DIVIDER_RESISTOR 2000
#define VCC_RESISTOR 1000

#define TIMEOUT_MS 30000
#define MIN_DISTANCE_CM 15
#define MAX_DISTANCE_CM 400

// Function prototypes
void setup_gpios(void);
void measure_distance(struct gpiod_dir *dir, struct gpiod_value *value);
void handle_edge_event(struct gpiod_edge_event *event);
void write_to_log(const char *message);
void cleanup_resources(void);
void signal_handler(int signum);

int main(void) {
    struct gpiod_dir *trigger_dir;
    struct gpiod_dir *echo_dir;
    struct gpiod_value trigger_value;
    struct gpiod_value echo_value;
    struct gpiod_edge_event edge_event;
    int trigger_fd;
    int echo_fd;
    int log_fd;
    char buffer[256];
    sigset_t sigset;
    int ret;

    // Initialize signal handlers
    sigemptyset(&sigset);
    sigaddset(&sigset, SIGINT);
    sigaddset(&sigset, SIGTERM);
    sigprocmask(SIG_BLOCK, &sigset, NULL);

    // Setup GPIOs
    setup_gpios();

    // Main loop
    while (1) {
        // Poll GPIOs
        ret = gpiod_poll(&trigger_dir, &echo_dir, TIMEOUT_MS);
        if (ret < 0) {
            fprintf(stderr, "Error polling GPIOs: %s\n", gpiod_error_str());
            break;
        }

        // Trigger the ultrasonic sensor
        gpiod_value_set(&trigger_value, TRIGGER_GPIO, GPIOD_OUT_HIGH);
        ret = gpiod_value_write(&trigger_value);
        if (ret < 0) {
            fprintf(stderr, "Error triggering GPIO: %s\n", gpiod_error_str());
            break;
        }
        usleep(10000); // 10 microseconds

        // Measure echo
        measure_distance(trigger_dir, &echo_value);
        handle_edge_event(&edge_event);

        // Process the measurement
        if (edge_event.time.tv_sec != 0 && edge_event.time.tv_nsec != 0) {
            double distance_cm = (edge_event.time.tv_sec * 1000000000.0 + edge_event.time.tv_nsec / 1000000.0) * 34300.0 / 2.0;
            if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
                continue;
            }

            if (distance_cm < 15) {
                write_to_log("Time to water the plant!\n");
            } else {
                write_to_log("Distance: %.2f cm\n", distance_cm);
            }
        } else {
            write_to_log("Sensor error or timeout\n");
        }

        // Sleep for 60 seconds
        sleep(60);
    }

    // Clean up resources
    cleanup_resources();

    // Restore signal mask
    sigprocmask(SIG_SETMASK, &sigset, NULL);

    return 0;
}

// Function to setup GPIOs
void setup_gpios(void) {
    int trigger_fd;
    int echo_fd;

    // Initialize GPIO directories
    ret = gpiod_open(&trigger_dir, TRIGGER_GPIO, GPIOD_DIR_OUT_INIT_HIGH);
    if (ret < 0) {
        fprintf(stderr, "Error opening trigger GPIO: %s\n", gpiod_error_str());
        return;
    }

    ret = gpiod_open(&echo_dir, ECHO_GPIO, GPIOD_DIR_IN);
    if (ret < 0) {
        fprintf(stderr, "Error opening echo GPIO: %s\n", gpiod_error_str());
        gpiod_dir_free(&trigger_dir);
        return;
    }

    // Set up voltage divider for echo pin
    ret = gpiod_set_direction(ECHO_GPIO, GPIOD_DIR_IN);
    if (ret < 0) {
        fprintf(stderr, "Error setting echo GPIO direction: %s\n", gpiod_error_str());
        gpiod_dir_free(&echo_dir);
        gpiod_dir_free(&trigger_dir);
        return;
    }

    // Trigger GPIO setup
    ret = gpiod_set_value_direction(TRIGGER_GPIO, GPIOD_VALUE_DIR_OUT);
    if (ret < 0) {
        fprintf(stderr, "Error setting trigger GPIO direction: %s\n", gpiod_error_str());
        gpiod_dir_free(&trigger_dir);
        gpiod_dir_free(&echo_dir);
        return;
    }

    trigger_fd = gpiod_get_fd(TRIGGER_GPIO);
    if (trigger_fd == -1) {
        fprintf(stderr, "Error getting trigger GPIO file descriptor: %s\n", gpiod_error_str());
        gpiod_dir_free(&trigger_dir);
        gpiod_dir_free(&echo_dir);
        return;
    }

    // Echo GPIO setup with voltage divider
    ret = gpiod_set_pull_mode(ECHO_GPIO, GPIOD_PULLUP);
    if (ret < 0) {
        fprintf(stderr, "Error setting echo GPIO pull mode: %s\n", gpiod_error_str());
        close(trigger_fd);
        gpiod_dir_free(&trigger_dir);
        gpiod_dir_free(&echo_dir);
        return;
    }

    echo_fd = gpiod_get_fd(ECHO_GPIO);
    if (echo_fd == -1) {
        fprintf(stderr, "Error getting echo GPIO file descriptor: %s\n", gpiod_error_str());
        close(trigger_fd);
        gpiod_dir_free(&trigger_dir);
        gpiod_dir_free(&echo_dir);
        return;
    }

    // Log file setup
    log_fd = open("distance_log.txt", O_APPEND | O_WRONLY, 0644);
    if (log_fd == -1) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(echo_fd);
        close(trigger_fd);
        gpiod_dir_free(&trigger_dir);
        gpiod_dir_free(&echo_dir);
        return;
    }
}

// Function to measure distance
void measure_distance(struct gpiod_dir *dir, struct gpiod_value *value) {
    int ret;

    // Set GPIO value to low
    gpiod_value_set(value, GPIOD_OUT_LOW);
    ret = gpiod_value_write(value);
    if (ret < 0) {
        fprintf(stderr, "Error setting trigger GPIO value: %s\n", gpiod_error_str());
        return;
    }

    // Wait for echo to rise
    ret = gpiod_edge_get(dir, ECHO_GPIO, GPIOD_EDGE_RISING, &edge_event, TIMEOUT_MS);
    if (ret < 0) {
        fprintf(stderr, "Error waiting for echo: %s\n", gpiod_error_str());
        return;
    }

    // If no edge event detected, treat as sensor absent
    if (edge_event.time.tv_sec == 0 && edge_event.time.tv_nsec == 0) {
        fprintf(stderr, "Sensor absent\n");
        return;
    }

    // Set GPIO value to high to stop triggering
    gpiod_value_set(value, GPIOD_OUT_HIGH);
    ret = gpiod_value_write(value);
    if (ret < 0) {
        fprintf(stderr, "Error setting trigger GPIO value: %s\n", gpiod_error_str());
        return;
    }

    // Measure echo pulse width
    ret = gpiod_value_read(value, &echo_value);
    if (ret < 0) {
        fprintf(stderr, "Error reading echo GPIO value: %s\n", gpiod_error_str());
        return;
    }

    // Compute distance
    double pulse_seconds = (echo_value.value.tv_sec * 1000000000 + echo_value.value.tv_nsec / 1000000.0) - (edge_event.time.tv_sec * 1000000000 + edge_event.time.tv_nsec / 1000000.0);
    if (pulse_seconds <= 0) {
