// Function to setup GPIOs
void setup_gpios(void) {
    int trigger_fd;
    int echo_fd;

    // Initialize GPIO directories
    ret = gpiod_open(&trigger_dir, TRIGGER_GPIO, GPIOD_DIR_OUT_INIT_HIGH);
    if (ret < 0) {
        fprintf(stderr, "Error opening trigger GPIO: %s\n", gpiod_error_str());
        return;
    }

    ret = gpiod_open(&echo_dir, ECHO_GPIO, GPIOD_DIR_IN);
    if (ret < 0) {
        fprintf(stderr, "Error opening echo GPIO: %s\n", gpiod_error_str());
        gpiod_dir_free(&trigger_dir);
        return;
    }

    // Set up voltage divider for echo pin
    ret = gpiod_set_direction(ECHO_GPIO, GPIOD_DIR_IN);
    if (ret < 0) {
        fprintf(stderr, "Error setting echo GPIO direction: %s\n", gpiod_error_str());
        gpiod_dir_free(&echo_dir);
        gpiod_dir_free(&trigger_dir);
        return;
    }

    // Trigger GPIO setup
    ret = gpiod_set_value_direction(TRIGGER_GPIO, GPIOD_VALUE_DIR_OUT);
    if (ret < 0) {
        fprintf(stderr, "Error setting trigger GPIO direction: %s\n", gpiod_error_str());
        gpiod_dir_free(&trigger_dir);
        gpiod_dir_free(&echo_dir);
        return;
    }

    trigger_fd = gpiod_get_fd(TRIGGER_GPIO);
    if (trigger_fd == -1) {
        fprintf(stderr, "Error getting trigger GPIO file descriptor: %s\n", gpiod_error_str());
        gpiod_dir_free(&trigger_dir);
        gpiod_dir_free(&echo_dir);
        return;
    }

    // Echo GPIO setup with voltage divider
    ret = gpiod_set_pull_mode(ECHO_GPIO, GPIOD_PULLUP);
    if (ret < 0) {
