#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>
#include <time.h>

// Define the I2C bus and address constants
#define I2C_BUS 1
#define I2C_ADDR 0x39

// Sensor configuration register values
#define ENABLE_REG 0x80
#define ATIME_REG 0x81
#define WTIME_REG 0x83
#define PPULSE_REG 0x8E
#define CONTROL_REG 0xF1
#define CONFIG2_REG 0x90

#define SENSOR_ID_REG 0x92
#define THRESHOLD_PROXIMITY 200

// Sensor register addresses for RGB and proximity
#define RGB_REG_START 0x96
#define RGB_REG_END 0x9B
#define PROXIMITY_REG 0x9C

// Function prototypes
void handleSIGINT(int signum);
void handleSIGTERM(int signum);
void readSensorData(uint8_t* data, int length);
void writeSensorRegisters(uint8_t* data, int length);
void initializeSensor();
void cleanupResources();
void logData(const char* timestamp, uint16_t r, uint16_t g, uint16_t b, uint8_t proximity);

int main() {
    // Initialize pigpio
    pigpio *pi = NULL;
    if (pigpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error());
        return EXIT_FAILURE;
    }
    pi->set_mode(pigpio::GPIO_MODE_I2C);

    // Signal handlers
    struct sigaction sigIntHandler, sigTermHandler;
    sigemptyset(&sigIntHandler.sa_mask);
    sigIntHandler.sa_handler = handleSIGINT;
    sigaction(SIGINT, &sigIntHandler, NULL);
    sigemptyset(&sigTermHandler.sa_mask);
    sigTermHandler.sa_handler = handleSIGTERM;
    sigaction(SIGTERM, &sigTermHandler, NULL);

    // Main loop
    while (1) {
        // Check for termination signals
        if (sigpending(&sigIntHandler.sa_mask)) {
            int sig = sigpending(&sigIntHandler.sa_mask);
            if (sig == SIGINT || sig == SIGTERM) {
                handleSIGINT(sig);
                break;
            }
        }

        // Initialize sensor if not already done
        if (!initialized) {
            initializeSensor();
            initialized = 1;
        }

        // Attempt to read sensor data
        uint8_t data[32]; // Enough space for all registers
        if (pigpio_i2c_read(pi, I2C_BUS, I2C_ADDR, RGB_REG_START, data, sizeof(data)) < 0) {
            fprintf(stderr, "I2C read error, re-initializing sensor.\n");
            cleanupResources();
            initializeSensor();
        } else {
            readSensorData(data, sizeof(data) - RGB_REG_START);

            // Check proximity
            if (data[PROXIMITY_REG] > THRESHOLD_PROXIMITY) {
                logData(time(nullptr), data[RGB_REG_START], data[RGB_REG_START + 1], data[RGB_REG_START + 2], data[PROXIMITY_REG]);
            }
        }
    }

    // Clean up resources
    cleanupResources();

    // Exit the program
    return EXIT_SUCCESS;
}

// Function to handle SIGINT and SIGTERM
void handleSIGINT(int signum) {
    fprintf(stderr, "SIGINT received, shutting down gracefully...\n");
    pigpio_stop(pi);
    cleanupResources();
    exit(EXIT_SUCCESS);
}

void handleSIGTERM(int signum) {
    fprintf(stderr, "SIGTERM received, shutting down gracefully...\n");
    pigpio_stop(pi);
    cleanupResources();
    exit(EXIT_SUCCESS);
}

// Function to read sensor data
void readSensorData(uint8_t* data, int length) {
    // Read RGB values
    for (int i = RGB_REG_START; i < RGB_REG_START + length; i++) {
        data[i] = pigpio_i2c_read(pi, I2C_BUS, I2C_ADDR, i, NULL, 1);
    }

    // Read proximity value
    data[PROXIMITY_REG] = pigpio_i2c_read(pi, I2C_BUS, I2C_ADDR, PROXIMITY_REG, NULL, 1);
}

// Function to write sensor configuration registers
void writeSensorRegisters(uint8_t* data, int length) {
    // Write configuration registers
    for (int i = 0; i < length; i++) {
        pigpio_i2c_write(pi, I2C_BUS, I2C_ADDR, data[i], 1);
    }

    // Verify sensor ID
    if (pigpio_i2c_read(pi, I2C_BUS, I2C_ADDR, SENSOR_ID_REG) != 0xAB) {
        fprintf(stderr, "Sensor ID mismatch, re-initializing.\n");
        cleanupResources();
        initializeSensor();
    }
}

// Function to initialize the sensor
void initializeSensor() {
    // Write configuration registers
    uint8_t configData[] = {
        // Enable, ATIME, WTIME, PPULSE, CONTROL, CONFIG2
        ENABLE_REG, 0x03, ATIME_REG, 0xDB, WTIME_REG, 0xF6, PPULSE_REG, 0x87, CONTROL_REG, 0x03, CONFIG2_REG, 0x01
    };
    writeSensorRegisters(configData, sizeof(configData));

    // Initialize as true
    initialized = 1;
}

// Function to cleanup resources
void cleanupResources() {
    // Close I2C handle
    pigpio_i2c_close(pi, I2C_BUS);

    // Close CSV file (assuming it's opened elsewhere in the program)
    // fclose(csvFile);

    // Release pigpio resources
    pigpio_free(pi);
}

// Function to log data to CSV file
void logData(const char* timestamp, uint16_t r, uint16_t g, uint16_t b, uint8_t proximity) {
    // Assuming csvFile is a FILE* opened for appending
    fprintf(csvFile, "%s,%d,%d,%d,%d\n", timestamp, r, g, b, proximity);
}

