        return;
    }

    // Check for falling edge
    if (value == 0) {
        perform_range_measurement();
    }
}

// Function to perform a range measurement
void perform_range_measurement() {
    uint8_t sys_range_start = 0x01;
    uint8_t result_interrupt_status;
    uint16_t distance;

    // Write to SYSRANGE_START
    if (pi_i2c_write(i2c_handle, SYSRANGE_START, &sys_range_start, 1) != 1) {
        fprintf(stderr, "Failed to write to SYSRANGE_START: %s\n", pi_errstr());
        return;
    }

    // Poll RESULT_INTERRUPT_STATUS with timeout
    for (int i = 0; i < 100; i++) {
        if (pi_i2c_read(i2c_handle, RESULT_INTERRUPT_STATUS, &result_interrupt_status, 1) != 1) {
            fprintf(stderr, "Failed to read RESULT_INTERRUPT_STATUS: %s\n", pi_errstr());
            break;
        }

        // Check if the interrupt bit is set
        if (result_interrupt_status & 0x01) {
            break;
        }

        usleep(1000); // 1 ms timeout
    }

    // If timeout occurred, log an error and return
    if (i == 100) {
        fprintf(stderr, "Timeout during range measurement.\n");
        return;
    }

    // Read the range result
    if (pi_i2c_read(i2c_handle, RESULT_RANGE_STATUS, &distance, 2) != 2) {
        fprintf(stderr, "Failed to read RESULT_RANGE_STATUS: %s\n", pi_errstr());
        return;
    }

