    distance = (distance & 0x0FFF) << 8 | (distance & 0x00FF);

    // Clear the interrupt
    if (pi_i2c_write(i2c_handle, SYSTEM_INTERRUPT_CLEAR, &sys_range_start, 1) != 1) {
        fprintf(stderr, "Failed to write to SYSTEM_INTERRUPT_CLEAR: %s\n", pi_errstr());
        return;
    }
}

