#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <wiringPiI2C.h>

#define PIGPIO_PORT 0  // Use the default GPIO port
#define BCM_GPIO_17 17 // GPIO 17 on Raspberry Pi

// TDK InvenSense ICU-20201 I2C address and register offsets
#define I2C_ADDRESS 0x6A
#define REG_MEASURE 0x00

// GPIO for LED
#define LED_GPIO BCM_GPIO_17

// File for logging distance measurements
const char *LOG_FILE = "distance_log.txt";

// Function prototypes
void setup_pigpio();
void setup_i2c();
void read_distance();
void handle_distance_under_20cm();
void cleanup_resources();
void signal_handler(int signum);

int main() {
    // Initialize pigpio and I2C
    setup_pigpio();
    setup_i2c();

    // Install signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        read_distance();
        handle_distance_under_20cm();
    }

    // Clean up resources on exit
    cleanup_resources();

    return 0;
}

// Function to setup pigpio
void setup_pigpio() {
    if (pigpioSetup(PIGPIO_PORT) == -1) {
        fprintf(stderr, "Failed to setup pigpio: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }
}

// Function to setup I2C
void setup_i2c() {
    if (wiringPiI2CSetup(1) == -1) {
        fprintf(stderr, "Failed to setup I2C bus 1: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

// Function to read distance from the sensor
void read_distance() {
    int distance;

    // Check if sensor is present and I2C communication is successful
    if (wiringPiI2CWrite(I2C_ADDRESS, REG_MEASURE, 1) == -1) {
        fprintf(stderr, "Failed to read from sensor: %s\n", strerror(errno));
        return;
    }

    distance = wiringPiI2CRead(I2C_ADDRESS, REG_MEASURE, 1)[0];

    // Convert distance to cm (assuming sensor returns in mm)
    distance /= 10;

    // Log the distance with timestamp
    char timestamp[50];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
    fprintf(LOG_FILE, "%s, Distance: %.1f cm\n", timestamp, distance);

    // Handle distance under 20 cm
    handle_distance_under_20cm();
}

// Function to handle distance under 20 cm
void handle_distance_under_20cm() {
    if (distance < 20) {
        // Turn on LED
        pigpioWrite(LED_GPIO, 1);
    } else {
        // Turn off LED
        pigpioWrite(LED_GPIO, 0);
    }
}

// Function to cleanup resources
void cleanup_resources() {
    // Stop I2C
    wiringPiI2CStop(1);

    // Release I2C
    wiringPiI2CRelease();

    // Stop pigpio
    pigpioStop();

    // Release pigpio
    pigpioRelease();
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    // Clean up resources on SIGINT and SIGTERM
    cleanup_resources();
    exit(EXIT_SUCCESS);
}

