#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <stdint.h>

// Define the I2C address and register addresses for the Si1182 sensor
#define SI1182_ADDRESS 0x60
#define PROXIMITY_REGISTER 0x18
#define AMBIENT_LIGHT_REGISTER 0x16

// Function prototypes
void handleSIGINT(int signum);
int i2cRead(uint8_t address, uint16_t registerAddress, uint16_t* data);
void writeToLog(const char* message);

// Main function
int main() {
    // Initialize pigpio
    if (gpiod_init() == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", gpiod_errstr());
        return EXIT_FAILURE;
    }

    // Signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, handleSIGINT);

    // Open the log file for appending
    FILE* logFile = fopen("biometric_log.txt", "a+");
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpiod_cleanup();
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Read proximity data
        uint16_t proximityData;
        if (i2cRead(SI1182_ADDRESS, PROXIMITY_REGISTER, &proximityData) < 0) {
            // Retry up to 3 times
            for (int retry = 0; retry < 3; ++retry) {
                if (i2cRead(SI1182_ADDRESS, PROXIMITY_REGISTER, &proximityData) >= 0) {
                    break;
                }
                usleep(1000); // Wait 1ms before retrying
            }
            // If still failed, handle error
            fprintf(logFile, "Failed to read proximity data after 3 retries.\n");
            continue;
        }
        writeToLog("Proximity data: %hu\n", proximityData);

        // Read ambient light data
        uint16_t ambientLightData;
        if (i2cRead(SI1182_ADDRESS, AMBIENT_LIGHT_REGISTER, &ambientLightData) < 0) {
            // Retry up to 3 times
            for (int retry = 0; retry < 3; ++retry) {
                if (i2cRead(SI1182_ADDRESS, AMBIENT_LIGHT_REGISTER, &ambientLightData) >= 0) {
                    break;
                }
                usleep(1000); // Wait 1ms before retrying
            }
            // If still failed, handle error
            fprintf(logFile, "Failed to read ambient light data after 3 retries.\n");
            continue;
        }
        writeToLog("Ambient light data: %hu\n", ambientLightData);

        // Log the timestamp
        time_t now = time(NULL);
        struct tm* timeinfo = localtime(&now);
        char timestamp[50];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
        fprintf(logFile, "Timestamp: %s\n", timestamp);

        // Sleep for 500ms
        usleep(500000);
    }

    // Clean up on SIGINT
    handleSIGINT(SIGINT);

    // Close the log file and release resources
    fclose(logFile);
    gpiod_cleanup();

    return EXIT_SUCCESS;
}

// Function to handle SIGINT
void handleSIGINT(int signum) {
    fprintf(stderr, "SIGINT received, cleaning up...\n");
    // Close the log file and release resources
    fclose(logFile);
    gpiod_cleanup();
    exit(EXIT_FAILURE); // Terminating the process
}

// Function to read data from the Si1182 sensor over I2C
int i2cRead(uint8_t address, uint16_t registerAddress, uint16_t* data) {
    int ret;
    ret = gpiod_i2c_write(address, (uint8_t)registerAddress);
    if (ret < 0) {
        fprintf(stderr, "Failed to write register address: %s\n", gpiod_errstr());
        return ret;
    }

    ret = gpiod_i2c_read(address, 2, data);
    if (ret < 0) {
        fprintf(stderr, "Failed to read data: %s\n", gpiod_errstr());
        return ret;
    }

    return 0;
}

// Function to write to the log file
void writeToLog(const char* message) {
    fprintf(logFile, "%s\n", message);
}

