        char timestamp[50];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
        fprintf(logFile, "Timestamp: %s\n", timestamp);

        // Sleep for 500ms
        usleep(500000);
    }

    // Clean up on SIGINT
    handleSIGINT(SIGINT);

    // Close the log file and release resources
    fclose(logFile);
    gpiod_cleanup();

    return EXIT_SUCCESS;
}

// Function to handle SIGINT
void handleSIGINT(int signum) {
    fprintf(stderr, "SIGINT received, cleaning up...\n");
    // Close the log file and release resources
    fclose(logFile);
    gpiod_cleanup();
    exit(EXIT_FAILURE); // Terminating the process
}

