int i2cRead(uint8_t address, uint16_t registerAddress, uint16_t* data) {
    int ret;
    ret = gpiod_i2c_write(address, (uint8_t)registerAddress);
    if (ret < 0) {
        fprintf(stderr, "Failed to write register address: %s\n", gpiod_errstr());
        return ret;
    }

    ret = gpiod_i2c_read(address, 2, data);
    if (ret < 0) {
        fprintf(stderr, "Failed to read data: %s\n", gpiod_errstr());
        return ret;
    }

    return 0;
}

