#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/time.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SENSOR_ADDRESS 0x50
#define COMMAND_FRAME {0x50, 0x0A, 0x00, 0x01}
#define RESPONSE_HEADER 0x50
#define DISTANCE_OFFSET 11
#define DISTANCE_LENGTH 2

// Function prototypes
void handle_interrupt(int signum);
int i2c_open_device();
int i2c_write(uint8_t *data, size_t length);
int i2c_read(uint8_t *data, size_t length);
void calculate_average_distance(uint16_t distances[10]);
void log_intrusion(uint16_t distance);
void close_resources();

// Main function
int main() {
    int i2c_fd = -1;
    uint8_t command[4] = COMMAND_FRAME;
    uint8_t response[15];
    uint16_t distances[10] = {0};
    struct timeval start_time, end_time;
    int i;

    // Open I2C device
    i2c_fd = i2c_open_device();
    if (i2c_fd == -1) {
        perror("i2c_open_device");
        return EXIT_FAILURE;
    }

    // Sample the sensor 10 times
    for (i = 0; i < 10; ++i) {
        // Write command to sensor
        if (i2c_write(command, 4) != 4) {
            perror("i2c_write");
            break;
        }

        // Wait at least 10 ms
        usleep(10000);

        // Read response from sensor
        if (i2c_read(response, 15) != 15) {
            perror("i2c_read");
            break;
        }

        // Validate response header
        if (response[0] != RESPONSE_HEADER) {
            fprintf(stderr, "Invalid response header\n");
            break;
        }

        // Extract distance from response
        memcpy(&distances[i], &response[DISTANCE_OFFSET], DISTANCE_LENGTH);

        // Calculate average distance
        calculate_average_distance(distances);

        // Check for intrusion
        if (distances[0] < 1000) {
            log_intrusion(distances[0]);
        }
    }

    // Close resources
    close_resources();

    return EXIT_SUCCESS;
}

// Function to handle SIGINT (Ctrl+C)
void handle_interrupt(int signum) {
    // Close I2C file descriptor and log files
    close(i2c_fd);
    close(STDOUT_FILENO); // Assuming 'intrusion_log.txt' is written to stdout
    close(STDERR_FILENO); // Assuming 'intrusion_log.txt' is written to stderr
    exit(EXIT_FAILURE);
}

// Function to open I2C device
int i2c_open_device() {
    int fd;
    fd = open(I2C_DEVICE, O_RDWR);
    if (fd == -1) {
        perror("open");
        return -1;
    }
    return fd;
}

// Function to write to the I2C device
int i2c_write(uint8_t *data, size_t length) {
    int bytes_written;
    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("i2c_write ioctl");
        return -1;
    }

    bytes_written = write(i2c_fd, data, length);
    if (bytes_written != length) {
        perror("write");
        return -1;
    }

    return bytes_written;
}

// Function to read from the I2C device
int i2c_read(uint8_t *data, size_t length) {
    int bytes_read;
    if (ioctl(i2c_fd, I2C_RDWR, (char *)data) < 0) {
        perror("i2c_read ioctl");
        return -1;
    }

    bytes_read = read(i2c_fd, data + length - bytes_read, length - bytes_read);
    if (bytes_read < 0) {
        perror("read");
        return -1;
    }

    return bytes_read;
}

// Function to calculate the average distance
void calculate_average_distance(uint16_t distances[10]) {
    uint16_t total_distance = 0;
    for (int i = 0; i < 10; ++i) {
        total_distance += distances[i];
    }

    for (int i = 0; i < 10; ++i) {
        distances[i] /= 10;
    }
}

// Function to log an intrusion
void log_intrusion(uint16_t distance) {
    struct tm tm;
    time(&tm);
    char intrusion_log_text[256] = "Intrusion detected at: ";
    strftime(intrusion_log_text, sizeof(intrusion_log_text), "%Y-%m-%d %H:%M:%S", &tm);
    sprintf(intrusion_log_text + strlen(intrusion_log_text), "Distance: %d mm", distance);
    fprintf(STDOUT_FILENO, "%s\n", intrusion_log_text);
    fprintf(STDERR_FILENO, "%s\n", intrusion_log_text);
}

// Function to close resources
void close_resources() {
    close(i2c_fd);
    // Close log files (assuming they were opened elsewhere)
    // close(log_file_fd);
}

