    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open I2C bus 1
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) == -1) {
        perror("Failed to open I2C bus 1");
        return EXIT_FAILURE;
    }

    // Check if I2C bus is accessible
    if (ioctl(i2c_fd, I2C_SLAVE, MLX75030_ADDR) == -1) {
