    // Initialize global variables
    pi_pigpiod *pp = NULL;
    int running = 1;

    // Install signal handler for SIGINT
    signal(SIGINT, handle_signal);

    // Attempt to initialize pigpio
    if ((pp = pi_open()) == NULL) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pi_error());
        exit(EXIT_FAILURE);
    }

    // Set up GPIO and I2C
    setup_pigpio();

    // Main loop
    while (running) {
        // Wait for 500 ms
        usleep(500 * 1000);

        // Read data from OPT3101
        read_opt3101_data(pp);

        // Check if SIGINT was received
        if (running) {
            if (kbhit() && getch() == 'q') {
                running = 0;
            }
        }
    }

    // Clean up resources
    cleanup_pigpio();

    return 0;
}

