    int distance, ambient_light, error_flags;

    // Attempt to read from the OPT3101
    if (pi_i2c_write(pp, OPT3101_ADDRESS, 0x00, 2, NULL) == -1) {
        fprintf(stderr, "Failed to write to OPT3101: %s\n", pi_error());
        return;
    }

    // Read response
    if (pi_i2c_read(pp, OPT3101_ADDRESS, 0x00, 6, &distance, &ambient_light, &error_flags) == -1) {
        fprintf(stderr, "Failed to read from OPT3101: %s\n", pi_error());
        return;
    }

    // Output the readings
    printf("Distance: %d, Ambient Light: %d, Error Flags: 0x%X\n", distance, ambient_light, error_flags);
}

