#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <ctype.h>
#include <signal.h>
#include <unistd.h>
#include <termios.h>
#include <pigpio.h>

#define RADAR_UART "/dev/serial0"
#define RADAR_MAGIC_WORD "\x02\x01\x04\x03\x06\x05\x08\x07"
#define RANGE_BINS 64
#define RANGE_RESOLUTION 0.0486
#define THRESHOLD_METERS 1.0
#define GPIO_PIN 17
#define LED_ON_TIME 2000

// Function prototypes
void setup_uart(const char *uart_device);
void read_radar_data(void);
void process_radar_data(uint8_t *data);
void handle_intrusion(double distance);
void cleanup_resources(void);
