// Global variables
FILE *intrusion_log_file = NULL;
pigpio *pi = NULL;
int gpio_mode = GPIO_OFF;

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO and UART
    pi = pigpioOpen();
    if (pi == NULL) {
        fprintf(stderr, "Failed to open pigpio\n");
        exit(EXIT_FAILURE);
    }
    gpio_mode = pigpioInMode(GPIO_PIN);
    if (gpio_mode != GPIO_OFF) {
        fprintf(stderr, "Failed to set GPIO pin to output mode\n");
        pigpioClose(pi);
        exit(EXIT_FAILURE);
    }
    setup_uart(RADAR_UART);

    // Main loop
    while (1) {
        read_radar_data();
        if (process_radar_data()) {
            handle_intrusion(get_radar_distance());
        }
    }

    // Clean up resources
    cleanup_resources();

    return 0;
}

// Function to setup UART
void setup_uart(const char *uart_device) {
    struct termios options;
    int fd = open(uart_device, O_RDWR | O_NOCTTY);
    if (fd == -1) {
        perror("Failed to open UART");
        exit(EXIT_FAILURE);
    }

    tcgetattr(fd, &options);
    // Configure baud rate, stop bits, parity, etc., as per radar sensor specs
    // Example configuration (adjust as per radar specs):
    // options.c_cflag = B9600 | CS8 | CLOCAL | CREAD;
    // options.c_iflag = IGNPAR | IXON;
    // options.c_lflag = ICANON;
    // options.c_oflag = 0;

    // Set new configuration
    struct termios new_options = options;
    new_options.c_iflag &= ~(IGNPAR | IXON);
    new_options.c_lflag &= ~(ICANON);
    tcsetattr(fd, TCSANOW, &new_options);

    intrusion_log_file = fopen("intrusion_log.csv", "a");
    if (intrusion_log_file == NULL) {
        perror("Failed to open intrusion log file");
        fclose(fd);
        exit(EXIT_FAILURE);
    }
}

// Function to read radar data
void read_radar_data() {
    char buffer[8 + RANGE_BINS * 2]; // 8 bytes for magic word + 128 bytes for data
    int bytes_read;

    // Read magic word
    if (fgets(buffer, sizeof(buffer), RADAR_UART) == NULL) {
        perror("Failed to read magic word");
        return;
    }
    if (strncmp(buffer, RADAR_MAGIC_WORD, 8) != 0) {
        fprintf(stderr, "Invalid magic word received\n");
        return;
    }

    // Read remaining data
    bytes_read = fread(buffer + 8, 1, RANGE_BINS * 2, RADAR_UART);
    if (bytes_read != RANGE_BINS * 2) {
        perror("Failed to read radar data");
        return;
    }

    // Process the data
    process_radar_data(buffer + 8);
}

// Function to process radar data
void process_radar_data(uint8_t *data) {
    double distance = 0.0;
    for (int i = 0; i < RANGE_BINS; ++i) {
        // Convert little-endian 16-bit integer to host order
        uint16_t range = ((data[i * 2] << 8) | data[i * 2 + 1]);
        distance += range * RANGE_RESOLUTION;
    }

    // Check if distance is below threshold
    if (distance < THRESHOLD_METERS) {
        handle_intrusion(distance);
    }
}

// Function to handle intrusion
void handle_intrusion(double distance) {
    char timestamp[50];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(intrusion_log_file, "%s,%f\n", timestamp, distance);

    // Activate LED for 2 seconds
    gpioMode(pi, GPIO_PIN, GPIO_OUTPUT);
    gpioWrite(pi, GPIO_PIN, 1); // Turn on LED
    usleep(LED_ON_TIME * 1000000); // Wait for 2 seconds
    gpioWrite(pi, GPIO_PIN, 0); // Turn off LED
}

// Function to cleanup resources
void cleanup_resources(void) {
    fclose(intrusion_log_file);
    tcsetattr(RADAR_UART, TCSANOW, &options); // Reset UART settings
    pigpioClose(pi);
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    // Clean up resources immediately
    cleanup_resources();
    exit(EXIT_FAILURE);
}

