#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <gpiod.h>
#include <signal.h>

#define SENSOR_GPIO 17
#define BUZZER_GPIO 18
#define OBSTACLE_DETECTED 0
#define BUZZER_PIN 1

// Function prototypes
void setup_gpios(void);
void handle_signal(int signum);
void read_sensor_and_handle_obstacle(void);
void log_state_transition(const char *timestamp, int state);
