    // Initialize signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Setup GPIOs
    setup_gpios();

    // Main loop
    while (1) {
        read_sensor_and_handle_obstacle();
        usleep(100000); // Poll every 100 ms
    }

    // Cleanup GPIOs on exit
    cleanup_gpios();

    return 0;
}

// Function to setup GPIOs
void setup_gpios(void) {
    // Open GPIO controller
    int ret = gpiod_open(&gpiod, GPIOD_DIR_DEV);
    if (ret < 0) {
        perror("gpiod_open");
        exit(EXIT_FAILURE);
    }

    // Request GPIO lines
    ret = gpiod_request_line(&gpiod, SENSOR_GPIO, GPIOD_OUT_INIT_LOW);
    if (ret < 0) {
        perror("gpiod_request_line");
        gpiod_close(&gpiod);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_request_line(&gpiod, BUZZER_GPIO, GPIOD_OUT_INIT_HIGH);
    if (ret < 0) {
        perror("gpiod_request_line");
        gpiod_close(&gpiod);
        exit(EXIT_FAILURE);
    }
}

// Function to handle signals
void handle_signal(int signum) {
    // Clean up GPIOs on SIGINT and SIGTERM
    cleanup_gpios();
    exit(EXIT_SUCCESS);
}

