void read_sensor_and_handle_obstacle(void) {
    int state;
    struct timespec timestamp;

    // Read sensor state
    ret = gpiod_get_value(&gpiod, SENSOR_GPIO, &state);
    if (ret < 0) {
        perror("gpiod_get_value");
        return;
    }

    // Log state transition
    log_state_transition(time(nullptr)->tm_strftime("%Y-%m-%dT%H:%M:%S.%f"), state);

    // Check for obstacle
    if (state == OBSTACLE_DETECTED) {
        gpiod_set_value(&gpiod, BUZZER_GPIO, BUZZER_PIN);
    } else {
        gpiod_set_value(&gpiod, BUZZER_GPIO, 0);
    }
}

// Function to log state transition
void log_state_transition(const char *timestamp, int state) {
    FILE *file = fopen("obstacle_log.txt", "a+");
    if (!file) {
        perror("fopen");
        return;
    }

    fprintf(file, "%s, state: %d\n", timestamp, state);
    fclose(file);
}

