void cleanup_gpios(void) {
    // Release GPIO lines
    gpiod_release_line(&gpiod, SENSOR_GPIO);
    gpiod_release_line(&gpiod, BUZZER_GPIO);

    // Close GPIO controller
    gpiod_close(&gpiod);
}

