// Define GPIO pin for alert
#define ALERT_PIN 17

// Function prototypes
void i2c_init();
void i2c_read(uint8_t address, uint16_t reg, uint16_t *data);
void gpio_set_mode(int pin, int mode);
void gpio_set_level(int pin, int level);
void cleanup();

int main() {
    // Initialize pigpio
    if (pi_gpiod_init() == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pi_error_str());
        return EXIT_FAILURE;
    }

    // Initialize I2C
    i2c_init();

    // Set up GPIO for alert
    gpio_set_mode(ALERT_PIN, GPIO_OUTPUT);
    gpio_set_level(ALERT_PIN, 0); // Low initially

    FILE *log_file = NULL;
    char timestamp[50];
    uint16_t distance;

    while (1) {
        // Check for shutdown request
        if (pi_pigpio_is_running() && (read(0, &distance, sizeof(distance)) == -1)) {
            fprintf(stderr, "Error reading distance: %s\n", strerror(errno));
            continue;
        }

        // Read distance from sensor
        if (i2c_read(0x69, 0x31, &distance.hi) || i2c_read(0x69, 0x32, &distance.lo)) {
            fprintf(stderr, "I2C read error\n");
            continue;
        }

        // Convert distance to cm
        distance = (distance.hi << 8) | distance.lo;
        float cm = (float)distance / 343.2; // Speed of sound in air (approx. 343.2 m/s)

        // Format timestamp
        time_t now = time(NULL);
        struct tm tm = *localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

        // Write to log file
        if ((log_file = fopen("distance_log.txt", "a")) == NULL) {
            fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
            continue;
        }
        fprintf(log_file, "%s, Distance: %.2f cm\n", timestamp, cm);

        // Check for alert condition
        if (cm < 10.0) {
            gpio_set_level(ALERT_PIN, 1); // High for alert
        } else {
            gpio_set_level(ALERT_PIN, 0); // Low to turn off alert
        }

        // Close log file on each write to prevent file descriptor leak
        fclose(log_file);
    }

    // Cleanup on SIGINT/SIGTERM
    SIGINT       = SIG_DFL; // Restore default SIGINT handler
    SIGTERM      = SIG_DFL; // Restore default SIGTERM handler
    cleanup();    // Release all resources

    return EXIT_SUCCESS;
}

