void i2c_init() {
    int rc;
    rc = i2c_dev_init(1); // Use I2C bus 1
    if (rc < 0) {
        fprintf(stderr, "Failed to initialize I2C: %s\n", strerror(rc));
        return;
    }
}

// Function to read from I2C
void i2c_read(uint8_t address, uint16_t reg, uint16_t *data) {
    int rc;
    rc = i2c_transfer(i2c_dev_get_handle(1), (uint8_t *) &address, 1, (uint8_t *) data, 2, 0);
    if (rc != 2) {
        fprintf(stderr, "I2C read error: %d\n", rc);
    }
}

// Function to set GPIO mode and level
void gpio_set_mode(int pin, int mode) {
    int rc;
    rc = pi_gpiom_mode(pin, mode);
    if (rc != 0) {
        fprintf(stderr, "Failed to set GPIO mode: %s\n", pi_error_str());
    }
}

void gpio_set_level(int pin, int level) {
    int rc;
    rc = pi_gpiowrite(pin, level);
    if (rc != 0) {
        fprintf(stderr, "Failed to set GPIO level: %s\n", pi_error_str());
    }
}

// Function to clean up resources
void cleanup() {
    // Release I2C resources
    i2c_dev_free_handle(i2c_dev_get_handle(1));

    // Release GPIO resources
    pi_gpiod_free();

    // Exit cleanly
    exit(0);
}

