code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>

#define PIGPIO_ID -1
#define VL53L1X_I2C_ADDRESS 0x29
#define VL53L1X_MODEL_ID_REG 0x010F
#define VL53L1X_SYSTEM_MODE_START_REG 0x007
#define VL53L1X_SYSRANGE_START_REG 0x000
#define VL53L1X_RESULT_INT_STATUS_REG 0x013
#define VL53L1X_RESULT_RANGE_STATUS_REG 0x078
#define VL53L1X_SYSTEM_INT_CLEAR_REG 0x014

// Function prototypes
void initialize_pigpio();
void initialize_i2c();
void cleanup_resources();
void handle_signal(int signum);

// Constants for distance thresholds
#define STOP_THRESHOLD 300
#define APPROACH_THRESHOLD 600
#define SLOW_THRESHOLD 1200

// Global variables
FILE* distance_log_file = NULL;
char distance_log_file_path[100] = {0};
pigpio *pi = NULL;
i2c_dev *i2c_dev = NULL;

// Function to initialize pigpio
void initialize_pigpio() {
    if (pigpio_init(PIGPIO_ID) == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }
    pi = pigpio_new();
    if (pi == NULL) {
        fprintf(stderr, "Failed to create pigpio instance: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }
}

// Function to initialize I2C
void initialize_i2c() {
    if (i2c_dev_open(1, 0, VL53L1X_I2C_ADDRESS) < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", i2c_strerror(-1));
        exit(EXIT_FAILURE);
    }
    i2c_dev = i2c_dev_new();
    if (i2c_dev == NULL) {
        fprintf(stderr, "Failed to create I2C device: %s\n", i2c_strerror(errno));
        exit(EXIT_FAILURE);
    }
}

// Function to cleanup resources
void cleanup_resources() {
    if (i2c_dev) {
        i2c_dev_free(i2c_dev);
        i2c_dev = NULL;
    }
    if (pi) {
        pigpio_free(pi);
        pi = NULL;
    }
    if (distance_log_file != NULL) {
        fclose(distance_log_file);
        distance_log_file = NULL;
    }
}

// Signal handler for SIGINT and SIGTERM
void handle_signal(int signum) {
    fprintf(stderr, "Received signal %d, shutting down gracefully...\n", signum);
    cleanup_resources();
    exit(EXIT_SUCCESS);
}

int main() {
    // Initialize pigpio and I2C
    initialize_pigpio();
    initialize_i2c();

    // Check if the sensor is present
    uint8_t model_id;
    if (i2c_dev_read(i2c_dev, VL53L1X_MODEL_ID_REG, &model_id, 1) != 1) {
        fprintf(stderr, "Failed to read model ID: %s\n", i2c_strerror(errno));
        return EXIT_FAILURE;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Sensor model ID is not 0xEA. Sensor not detected.\n");
        return EXIT_FAILURE;
    }

    // Perform software reset
    if (i2c_dev_write(i2c_dev, VL53L1X_SYSTEM_MODE_START_REG, 0x00) != 1) {
        fprintf(stderr, "Failed to write to SYSTEM_MODE_START: %s\n", i2c_strerror(errno));
        return EXIT_FAILURE;
    }
    usleep(2000); // Wait 2 ms

    // Begin continuous ranging
    if (i2c_dev_write(VL53L1X_SYSTEM_MODE_START_REG, 0x01) != 1) {
        fprintf(stderr, "Failed to write to SYSTEM_MODE_START: %s\n", i2c_strerror(errno));
        return EXIT_FAILURE;
    }

    // Poll for SYSRANGE_START bit clear
    while (1) {
        if (i2c_dev_read(VL53L1X_SYSRANGE_START_REG, &uint8_t(0), 1) == 1) {
            break; // Bit cleared, continue with ranging
        }
        usleep(100000); // Wait up to 100 ms
        if (errno != 0) {
            fprintf(stderr, "Error waiting: %s\n", strerror(errno));
            return EXIT_FAILURE;
        }
    }

    // Main ranging loop
    while (1) {
        // Poll for data-ready interrupt
        if (i2c_dev_read(VL53L1X_RESULT_INT_STATUS_REG, &uint8_t(0), 1) == 1) {
            uint16_t distance_mm;
            if (i2c_dev_read(VL53L1X_RESULT_RANGE_STATUS_REG + 10, &distance_mm, 2) != 2) {
                fprintf(stderr, "Failed to read distance: %s\n", i2c_strerror(errno));
                continue;
            }
            distance_mm = (distance_mm << 8) | (distance_mm & 0x00FF); // Convert to big-endian

            // Clear interrupt
            if (i2c_dev_write(VL53L1X_SYSTEM_INT_CLEAR_REG, 0x01) != 1) {
                fprintf(stderr, "Failed to write to SYSTEM_INT_CLEAR: %s\n", i2c_strerror(errno));
                continue;
            }

            // Append to log file
            char timestamp[10];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            fprintf(distance_log_file, "%s,%d\n", timestamp, distance_mm);

            // Print parking guidance message
            if (distance_mm < STOP_THRESHOLD) {
                fprintf(stderr, "STOP: Distance < %d mm\n", STOP_THRESHOLD);
            } else if (distance_mm >= STOP_THRESHOLD && distance_mm <= APPROACH_THRESHOLD) {
                fprintf(stderr, "APPROACH: %d <= Distance < %d mm\n", STOP_THRESHOLD, APPROACH_THRESHOLD);
            } else if (distance_mm >= APPROACH_THRESHOLD && distance_mm <= SLOW_THRESHOLD) {
                fprintf(stderr, "SLOW: %d <= Distance < %d mm\n", APPROACH_THRESHOLD, SLOW_THRESHOLD);
            } else {
                fprintf(stderr, "CLEAR: Distance > %d mm\n", SLOW_THRESHOLD);
            }
        }
        usleep(100000); // Wait 100 ms between readings
    }

    // Handle signals
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Clean up on exit
    cleanup_resources();

    return EXIT_SUCCESS;
}

