#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdint.h>

// Define the I2C address of the MLX75030 sensor
#define MLX75030_ADDRESS 0x5A

// Function prototypes
void handleSIGINT(int signum);
void handleSIGTERM(int signum);
void i2cWrite(uint8_t reg, uint8_t data);
void i2cRead(uint8_t reg, uint8_t *data);
void measureDistance();
void writeDistanceToFile(const char *timestamp, double distance_cm);
void cleanup();

// Main function
int main() {
    // Initialize pigpio
    if (gpiod_init() == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", gpiod_errstr());
        return EXIT_FAILURE;
    }

    // Install signal handlers
    signal(SIGINT, handleSIGINT);
    signal(SIGTERM, handleSIGTERM);

    // Main loop
    while (1) {
        measureDistance();
        writeDistanceToFile(get_seconds(), (double)gpiod_i2c_read(MLX75030_ADDRESS, 0x00));
        usleep(100000); // 100 ms delay
    }

    // Clean up resources
    cleanup();

    return EXIT_SUCCESS;
}

// Signal handlers
void handleSIGINT(int signum) {
    fprintf(stderr, "SIGINT received, exiting gracefully...\n");
    exit(0);
}

void handleSIGTERM(int signum) {
    fprintf(stderr, "SIGTERM received, exiting gracefully...\n");
    exit(0);
}

// I2C write function
void i2cWrite(uint8_t reg, uint8_t data) {
    if (gpiod_i2c_write(MLX75030_ADDRESS, &reg, 1) != 1 || gpiod_i2c_write(MLX75030_ADDRESS, &data, 1) != 1) {
        fprintf(stderr, "I2C write error: %s\n", gpiod_errstr());
        return;
    }
}

// I2C read function
void i2cRead(uint8_t reg, uint8_t *data) {
    if (gpiod_i2c_read(MLX75030_ADDRESS, &reg, 1) != 1) {
        fprintf(stderr, "I2C read error: %s\n", gpiod_errstr());
        return;
    }

    if (gpiod_i2c_read(MLX75030_ADDRESS, data, 2) != 2) {
        fprintf(stderr, "I2C read error: %s\n", gpiod_errstr());
        return;
    }
}

// Measure distance
void measureDistance() {
    // Write command to trigger measurement
    i2cWrite(0x00, 0x01);

    // Delay to allow sensor to complete measurement
    usleep(10000); // 10 ms delay

    // Read distance data
    uint8_t data[2];
    i2cRead(0x00, data);

    // Convert data to distance in cm
    double distance_cm = (data[0] << 8) | data[1];
    fprintf(stderr, "Measured distance: %.1f cm\n", distance_cm);
}

// Write distance to file
void writeDistanceToFile(const char *timestamp, double distance_cm) {
    FILE *file = fopen("distance_log.csv", "a");
    if (!file) {
        fprintf(stderr, "Failed to open 'distance_log.csv' for appending: %s\n", strerror(errno));
        return;
    }

    fprintf(file, "%s,%f\n", timestamp, distance_cm);
    fclose(file);
}

// Cleanup function
void cleanup() {
    // Close file if it's open
    if (file != NULL) {
        fclose(file);
    }

    // Stop pigpio
    gpiod_stop();
    gpiod_free();
}

