#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27

// GPIO mode constants
#define GPIO_MODE_OUT 1
#define GPIO_MODE_IN 0

// Debounce constants
#define DEBOUNCE_MS 50

// Log file name
const char *LOG_FILE_NAME = "proximity_log.txt";

// Function prototypes
void initialise_pigpio();
void setup_sensors();
void poll_sensors();
void handle_signal(int signum);
void cleanup();

int main() {
    // Initialize pigpio
    initialise_pigpio();

    // Setup sensors
    setup_sensors();

    // Main loop
    while (1) {
        poll_sensors();
    }

    // Clean up on exit
    cleanup();

    return 0;
}

// Function to initialize pigpio
void initialise_pigpio() {
    if (pigpioSetup(0) == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }

    printf("Pigpio initialized successfully.\n");
}

// Function to setup sensors
void setup_sensors() {
    int sensor_1_mode;
    int sensor_2_mode;

    // Set GPIO 17 and 27 to output for TCRT5000 IR LED
    if (gpioSetMode(SENSOR_1_GPIO, GPIO_MODE_OUT) == -1) {
        fprintf(stderr, "Failed to set GPIO %d to output: %s\n", SENSOR_1_GPIO, pigpioError());
        exit(EXIT_FAILURE);
    }
    if (gpioSetMode(SENSOR_2_GPIO, GPIO_MODE_OUT) == -1) {
        fprintf(stderr, "Failed to set GPIO %d to output: %s\n", SENSOR_2_GPIO, pigpioError());
        exit(EXIT_FAILURE);
    }

    // Set GPIO 17 and 27 to input for TCRT5000 IR receiver
    sensor_1_mode = gpioSetMode(SENSOR_1_GPIO, GPIO_MODE_IN);
    if (sensor_1_mode == -1) {
        fprintf(stderr, "Failed to set GPIO %d to input: %s\n", SENSOR_1_GPIO, pigpioError());
        exit(EXIT_FAILURE);
    }
    sensor_2_mode = gpioSetMode(SENSOR_2_GPIO, GPIO_MODE_IN);
    if (sensor_2_mode == -1) {
        fprintf(stderr, "Failed to set GPIO %d to input: %s\n", SENSOR_2_GPIO, pigpioError());
        exit(EXIT_FAILURE);
    }

    printf("Sensors setup successfully.\n");
}

// Function to poll sensors
void poll_sensors() {
    struct timespec timestamp;
    int sensor_1_state;
    int sensor_2_state;

    // Get current time for ISO 8601 UTC timestamp
    clock_gettime(CLOCK_REALTIME, &timestamp);

    // Read sensor states
    sensor_1_state = gpioRead(SENSOR_1_GPIO);
    sensor_2_state = gpioRead(SENSOR_2_GPIO);

    // Debounce sensor states
    if (sensor_1_state != last_sensor_1_state) {
        last_sensor_1_state = sensor_1_state;
        if (sensor_1_state == 0) {
            // Detected obstacle
            char event_type[10];
            sprintf(event_type, "DETECTED");
            write_log(timestamp.tv_sec, timestamp.tv_nsec, sensor_1_state, event_type);
        } else {
            // Path cleared
            char event_type[10];
            sprintf(event_type, "CLEARED");
            write_log(timestamp.tv_sec, timestamp.tv_nsec, sensor_1_state, event_type);
        }
    }

    if (sensor_2_state != last_sensor_2_state) {
        last_sensor_2_state = sensor_2_state;
        if (sensor_2_state == 0) {
            // Detected obstacle
            char event_type[10];
            sprintf(event_type, "DETECTED");
            write_log(timestamp.tv_sec, timestamp.tv_nsec, sensor_2_state, event_type);
        } else {
            // Path cleared
            char event_type[10];
            sprintf(event_type, "CLEARED");
            write_log(timestamp.tv_sec, timestamp.tv_nsec, sensor_2_state, event_type);
        }
    }

    // Wait for debounce period
    usleep(DEBOUNCE_MS * 1000);
}

// Function to handle signals (SIGINT, SIGTERM)
void handle_signal(int signum) {
    // Graceful shutdown
    printf("Received signal %d, shutting down...\n", signum);
    cleanup();
    pigpioTerminate();
    exit(EXIT_SUCCESS);
}

// Function to write to log file
void write_log(int year, int month, int day, int state, const char *event_type) {
    FILE *log_file = fopen(LOG_FILE_NAME, "a+");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE_NAME);
        exit(EXIT_FAILURE);
    }

    fprintf(log_file, "Timestamp: %04d-%02d-%02d %02d:%02d:%02d - Sensor %d: %s - Event: %s\n",
            year, month, day, hour, minute, second, (state == 0 ? 1 : 2), state, event_type);
    fclose(log_file);
}

// Function to cleanup resources
void cleanup() {
    // Close log file
    fclose(LOG_FILE_HANDLE);

    // Reset GPIO modes to avoid conflicts
    gpioSetMode(SENSOR_1_GPIO, GPIO_MODE_OUT);
    gpioSetMode(SENSOR_2_GPIO, GPIO_MODE_OUT);

    // Terminate pigpio
    pigpioTerminate();
}

// Initialize LOG_FILE_HANDLE for logging
FILE *LOG_FILE_HANDLE = NULL;

// Main program execution
int main() {
    // Initialize pigpio
    initialise_pigpio();

    // Setup sensors
    setup_sensors();

    // Register signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (1) {
        poll_sensors();
    }

    // Clean up on exit
    cleanup();

    return 0;
}

