#define I2C_DEVICE_PATH "/dev/i2c-1"
#define SENSOR_ADDR 0x49
#define MEAS_TRIGGER_REG 0x04
#define MEAS_STATUS_REG 0x06
#define DIST_HIGH_REG 0x08
#define DIST_LOW_REG 0x09
#define TIMEOUT_MS 50

// Helper function to perform I2C write-then-read transaction
int i2c_read_reg(uint8_t addr, uint8_t reg, uint8_t* data) {
    int fd = open(I2C_DEVICE_PATH, O_RDWR);
    if (fd == -1) {
        perror("open");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("ioctl(I2C_SLAVE)");
        close(fd);
        return -1;
    }

    // Write to the register
    if (write(fd, &reg, 1) != 1) {
        perror("write to register");
        close(fd);
        return -1;
    }

    // Read from the register
    if (read(fd, data, 1) != 1) {
        perror("read from register");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

int main() {
    const char* csv_file_name = "distance_log.csv";
    FILE* csv_file = fopen(csv_file_name, "a+");
    if (csv_file == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    struct timespec start_time;
    struct timespec end_time;
    uint16_t distance_mm = 0;
    int sample_count = 0;

    while (1) {
        // Prepare for measurement
        start_time.tv_sec = time(NULL);
        start_time.tv_nsec = 0;

        // Trigger measurement
        if (i2c_read_reg(SENSOR_ADDR, MEAS_TRIGGER_REG, &((uint8_t*)&distance_mm)[0]) < 0) {
            fprintf(stderr, "Failed to trigger measurement: %s\n", strerror(errno));
            continue;
        }

        // Wait for measurement to complete
        struct timespec timeout = { .tv_sec = 0, .tv_nsec = TIMEOUT_MS * 1000000 };
        while (1) {
            end_time = *(&start_time);
            if (nanosleep(&timeout, &timeout) == -1 && errno == EINTR) {
                // Interrupted sleep, retry
                continue;
            }
            if (end_time.tv_sec > start_time.tv_sec || (end_time.tv_sec == start_time.tv_sec && end_time.tv_nsec >= start_time.tv_nsec)) {
                break;
            }
        }

        // Read distance data
        if (i2c_read_reg(SENSOR_ADDR, DIST_HIGH_REG, &distance_mm >> 8) ||
            i2c_read_reg(SENSOR_ADDR, DIST_LOW_REG, &distance_mm & 0xFF) < 0) {
            fprintf(stderr, "Failed to read distance: %s\n", strerror(errno));
            continue;
        }

        // Format and write to CSV
        char timestamp[50];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%fZ", &start_time);
        fprintf(csv_file, "%s,%u\n", timestamp, distance_mm);

        // Sample every 500 ms
        sleep(500);
        sample_count++;
    }

    // Clean up on SIGINT/SIGTERM
    if (signal(SIGINT) == SIG_DFL && signal(SIGTERM) == SIG_DFL) {
        signal(SIGINT, SIG_IGN); // Ignore SIGINT
        signal(SIGTERM, SIG_IGN); // Ignore SIGTERM
    }

    printf("Exiting...\n");
    fclose(csv_file);
    return 0;
}

