#define I2C_ADDR 0x29
#define I2C_REG_CONFIG 0x00
#define I2C_REG_MODE 0x01
#define I2C_REG_RANGE 0x02
#define I2C_REG_ZONE_COUNT 0x03
#define I2C_REG_ZONE_START 0x04
#define I2C_REG_ZONE_DATA 0x05

#define ZONE_COUNT 64
#define INTERVAL_MS 500

// Sensor configuration values
#define CONFIG_REG_VALUE 0x00 // 8x8 grid mode
#define MODE_REG_VALUE 0x01 // Start measurement mode
#define RANGE_REG_VALUE 0x06 // 0.3m - 9.0m range

// Zone related constants
#define ZONE_START_ADDRESS 0x20
#define ZONE_DATA_LENGTH 8

// Function prototypes
void setup_i2c();
void read_zone_data(int fd);
void handle_signal(int signum);

int main() {
    // Initialize I2C
    setup_i2c();

    // Install signal handler for SIGINT
    signal(SIGINT, handle_signal);

    // Main loop
    while (1) {
        // Wait for the interval
        usleep(1000 * INTERVAL_MS);

        // Read zone data
        read_zone_data(I2C_DEVICE);

        // Print zone distances
        for (int i = 0; i < ZONE_COUNT; i++) {
            printf("Zone %d: %d cm\n", i + ZONE_START_ADDRESS, (read_zone_data(I2C_DEVICE) >> (8 * i)) & 0xFF);
        }
    }

    // Clean up
    close(I2C_DEVICE);
    return 0;
}

// Function to setup I2C communication
void setup_i2c() {
    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    struct i2c_msg msg[2];
    msg[0].addr = I2C_ADDR;
    msg[0].buf = &CONFIG_REG_VALUE;
    msg[0].len = 1;

    msg[1].addr = I2C_ADDR;
    msg[1].buf = &MODE_REG_VALUE;
    msg[1].len = 1;

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    if (write(fd, msg, sizeof(msg)) != sizeof(msg)) {
        perror("write");
        exit(EXIT_FAILURE);
    }

    msg[0].buf = &RANGE_REG_VALUE;
    msg[0].len = 1;
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    if (write(fd, msg, sizeof(msg)) != sizeof(msg)) {
        perror("write");
        exit(EXIT_FAILURE);
    }
}

// Function to read zone data from the sensor
void read_zone_data(int fd) {
    struct i2c_msg msg[ZONE_COUNT];
    for (int i = 0; i < ZONE_COUNT; i++) {
        msg[i].addr = I2C_ADDR;
        msg[i].buf = (char *)(&ZONE_START_ADDRESS + i);
        msg[i].len = ZONE_DATA_LENGTH;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    if (write(fd, msg, ZONE_COUNT * sizeof(struct i2c_msg)) != ZONE_COUNT * sizeof(struct i2c_msg)) {
        perror("write");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < ZONE_COUNT; i++) {
        int data = read(fd, (char *)(&ZONE_DATA_LENGTH * i), ZONE_DATA_LENGTH);
        if (data != ZONE_DATA_LENGTH) {
            perror("read");
            exit(EXIT_FAILURE);
        }
    }
}

// Signal handler for SIGINT
void handle_signal(int signum) {
    printf("Caught SIGINT, exiting gracefully...\n");
    close(I2C_DEVICE);
    exit(EXIT_SUCCESS);
}

