#define RANGE_START_REGISTER 0x0009
#define INTERRUPT_STATUS_REGISTER 0x0046
#define DISTANCE_HIGH_REGISTER 0x0096
#define DISTANCE_LOW_REGISTER 0x0097

// Function prototypes
