void cleanup();

// Global variables
pigpio *pi;
volatile uint8_t interrupt_triggered = 0;
int i2c_handle = -1;

// Main function
int main() {
    // Initialize pigpio
    pi = pigpioOpen();
    if (pi == NULL) {
        fprintf(stderr, "Failed to open pigpio: %s\n", pigpioError());
        return EXIT_FAILURE;
    }

    // Install signal handlers
    signal(SIGINT, handleInterrupts);
    signal(SIGTERM, handleInterrupts);

    // Attempt to open I2C bus 1
    i2c_handle = pigpioI2COpen(pi, 1);
    if (i2c_handle == -1) {
        fprintf(stderr, "Failed to open I2C bus 1: %s\n", pigpioI2CError());
        pigpioClose(pi);
        return EXIT_FAILURE;
    }

    // Initialize the sensor
    if (!writeI2C(pi, i2c_handle, VL53L4CX_ADDRESS, SOFT_RESET_REGISTER, 0x00)) {
        fprintf(stderr, "Failed to soft reset sensor: %s\n", pigpioI2CError());
        closeI2C(pi, i2c_handle);
        pigpioClose(pi);
        return EXIT_FAILURE;
    }
    usleep(10000); // Wait 10 ms

    if (!writeI2C(pi, i2c_handle, VL53L4CX_ADDRESS, RANGE_START_REGISTER, 0x00)) {
        fprintf(stderr, "Failed to start ranging: %s\n", pigpioI2CError());
        closeI2C(pi, i2c_handle);
        pigpioClose(pi);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Poll interrupt status register
        if (!readI2C(pi, i2c_handle, VL53L4CX_ADDRESS, INTERRUPT_STATUS_REGISTER, &interrupt_triggered)) {
            fprintf(stderr, "Failed to read interrupt status: %s\n", pigpioI2CError());
            break; // Exit loop on I2C failure
        }

        if (interrupt_triggered) {
            // Read distance data
            uint16_t distance = readI2C(pi, i2c_handle, VL53L4CX_ADDRESS, DISTANCE_HIGH_REGISTER, &uint16_t(0)) |
                                (readI2C(pi, i2c_handle, VL53L4CX_ADDRESS, DISTANCE_LOW_REGISTER, &uint16_t(0)) << 8);

            // Log the result with a timestamp
            char timestamp_str[50];
            time_t rawtime = time(NULL);
            struct tm *timeinfo = localtime(&rawtime);
            strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S.%06lu", timeinfo);
            fprintf(stderr, "Timestamp: %s, Distance: %d mm\n", timestamp_str, distance / 1000.0);

            // Clear the interrupt flag
            writeI2C(pi, i2c_handle, VL53L4CX_ADDRESS, INTERRUPT_STATUS_REGISTER, 0x00);
        } else {
            // Skip this cycle if no interrupt
            continue;
        }

        // Poll every 500 ms
        usleep(500000);
    }

    // Cleanup on SIGINT or SIGTERM
    cleanup();

    // Close I2C handle and terminate pigpio
    closeI2C(pi, i2c_handle);
    pigpioClose(pi);

    return EXIT_SUCCESS;
}

// Function to handle SIGINT and SIGTERM
