    // Check if I2C bus is available
    if (pigpioI2CBusAvailable(I2C_BUS) == 0) {
        fprintf(stderr, "I2C bus %d not available\n", I2C_BUS);
        return;
    }

    // Open I2C bus
    int i2c_fd = pigpioI2CBusOpen(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %d: %s\n", I2C_BUS, pigpioError());
        pigpioI2CBusClose(i2c_fd);
        return;
    }

    // Write to reset register
    if (pigpioI2CWrite(i2c_fd, VL53L1X_ADDRESS, SOFT_RESET_REG, 0x01) < 0) {
        fprintf(stderr, "Failed to reset VL53L1X: %s\n", pigpioError());
        pigpioI2CBusClose(i2c_fd);
        return;
    }

    // Set I2C slave address
    if (pigpioI2CWrite(i2c_fd, VL53L1X_ADDRESS, I2C_SLAVE_REG, 0x01) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", pigpioError());
        pigpioI2CBusClose(i2c_fd);
        return;
    }

    // Set continuous ranging mode
    if (pigpioI2CWrite(i2c_fd, VL53L1X_ADDRESS, SYSTEM_MODE_START_REG, 0x07) < 0) {
        fprintf(stderr, "Failed to set continuous ranging mode: %s\n", pigpioError());
        pigpioI2CBusClose(i2c_fd);
        return;
    }

    // Configure distance register for final corrected distance in mm
    if (pigpioI2CWrite(i2c_fd, VL53L1X_ADDRESS, RESULT_FINAL_CROSSTALK_CORRECTED_DISTANCE_MM_REG, 0x00) < 0) {
        fprintf(stderr, "Failed to configure distance register: %s\n", pigpioError());
        pigpioI2CBusClose(i2c_fd);
        return;
    }

    // Close I2C bus
    pigpioI2CBusClose(i2c_fd);
}

