    int distance_mm;

    // Attempt to read distance
    if (pigpioI2CRead(VL53L1X_ADDRESS, RESULT_FINAL_CROSSTALK_CORRECTED_DISTANCE_MM_REG, &distance_mm, 1) < 0) {
        fprintf(stderr, "Failed to read distance: %s\n", pigpioError());
        return;
    }

    // Check if distance is below 100 mm to activate buzzer
    if (distance_mm < 100) {
        handle_buzzer(distance_mm);
    } else {
        // Distance above 100 mm, deactivate buzzer
        pigpioWrite(BUZZER_PIN, 0);
    }
}

// Function to handle buzzer based on distance
void handle_buzzer(int distance) {
    if (distance < 100) {
        // Activate buzzer
        pigpioWrite(BUZZER_PIN, 1);
