#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SERVO_PIN 17
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SOUND_SPEED 343.0
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define SERVO_MIN_PULSE 1000
#define SERVO_MAX_PULSE 2000
#define TIMEOUT_MS 50

volatile sig_atomic_t should_exit = 0;

void handle_signal(int signum) {
    should_exit = 1;
}

int main() {
    // Initialize pigpio and check for failure
    pigpio *pi = NULL;
    if (pigpio_init() == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_errstr());
        return EXIT_FAILURE;
    }

    // Install signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Configure GPIO pins
    if (pi_gpio_config_output(pi, TRIGGER_PIN, 1) == -1) {
        fprintf(stderr, "Failed to configure trigger pin as output: %s\n", pigpio_errstr());
        pigpio_free(pi);
        return EXIT_FAILURE;
    }
    if (pi_gpio_config_input(pi, ECHO_PIN) == -1) {
        fprintf(stderr, "Failed to configure echo pin as input: %s\n", pigpio_errstr());
        pigpio_free(pi);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!should_exit) {
        // Measure distance
        int pulse_width_us;
        if (pi_gpio_get_level(pi, ECHO_PIN) == 1) {
            // Echo pin is high, indicating a valid reading
            pulse_width_us = pi_us_to_ns(pi_gpio_get_pulsewidth(pi, ECHO_PIN));
            if (pulse_width_us > TIMEOUT_MS * 1000) {
                // Timeout, invalid reading
                fprintf(stderr, "Sensor timeout: %d us\n", pulse_width_us);
                continue;
            }

            // Calculate distance
            float distance_cm = (pulse_width_us / SOUND_SPEED) * 100;
            if (distance_cm < MIN_DISTANCE || distance_cm > MAX_DISTANCE) {
                fprintf(stderr, "Invalid distance: %f cm\n", distance_cm);
                continue;
