#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <sys/msg.h>
#include <unistd.h>

// Define message structure for POSIX message queue
struct msg_data {
    int distance;
};

// Function prototypes
void initialize_pigpio();
void initialize_i2c();
void reset_vl53l1x();
void configure_timing();
void start_ranging();
void read_distance();
void handle_distance(short distance);
void cleanup_resources();
void signal_handler(int signum);

int main() {
    // Initialize pigpio
    initialize_pigpio();

    // Initialize I2C
    initialize_i2c();

    // Check sensor model ID
    if (VL53L1X_ModelID() != 0xEA) {
        fprintf(stderr, "Sensor model ID mismatch. Exiting...\n");
        return EXIT_FAILURE;
    }

    // Perform software reset
    reset_vl53l1x();

    // Configure timing budget
    configure_timing();

    // Start ranging
    start_ranging();

    // Signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        read_distance();
        usleep(50000); // Wait 50 ms
    }

    // Clean up on SIGINT
    cleanup_resources();

    return EXIT_SUCCESS;
}

// Function to initialize pigpio
void initialize_pigpio() {
    if (pi_pigpio_error() != PI_NO_ERROR) {
        fprintf(stderr, "Error initializing pigpio. Exiting...\n");
        exit(EXIT_FAILURE);
    }
}

// Function to initialize I2C
void initialize_i2c() {
    int rc;
    struct pigpio *pi = pigpio.pi();

    // Open I2C bus 1
    if ((rc = pi_i2c_open(pi, 1)) != PI_NO_ERROR) {
        fprintf(stderr, "Error opening I2C bus 1. Exiting...\n");
        exit(EXIT_FAILURE);
    }

    // Check if the sensor is present on I2C address 0x29
    if (pi_i2c_write(pi, 1, 0x29, 0x00, 1) != PI_NO_ERROR) {
        fprintf(stderr, "Error writing to I2C address 0x29. Exiting...\n");
        exit(EXIT_FAILURE);
    }

    // Read back to verify write
    if (pi_i2c_read(pi, 1, 0x29, 0x00, 1) != PI_NO_ERROR) {
        fprintf(stderr, "Error reading from I2C address 0x29. Exiting...\n");
        exit(EXIT_FAILURE);
    }

    // Close I2C bus 1
    pi_i2c_close(pi, 1);
}

// Function to reset VL53L1X
void reset_vl53l1x() {
    if (pi_i2c_write(pi, 1, 0x00, 0x00, 1) != PI_NO_ERROR) {
        fprintf(stderr, "Error writing to reset register. Exiting...\n");
        exit(EXIT_FAILURE);
    }
    if (pi_i2c_write(pi, 1, 0x00, 0x01, 1) != PI_NO_ERROR) {
        fprintf(stderr, "Error writing to reset register. Exiting...\n");
        exit(EXIT_FAILURE);
    }
}

// Function to configure timing budget
void configure_timing() {
    if (pi_i2c_write(pi, 1, 0x01, 0x00, 1) != PI_NO_ERROR) {
        fprintf(stderr, "Error writing to timing budget register. Exiting...\n");
        exit(EXIT_FAILURE);
    }
}

// Function to start ranging
void start_ranging() {
    if (pi_i2c_write(pi, 1, 0x80, 0x01, 1) != PI_NO_ERROR) {
        fprintf(stderr, "Error writing to ranging register. Exiting...\n");
        exit(EXIT_FAILURE);
    }
}

// Function to read distance
void read_distance() {
    short distance;

    // Poll data-ready bit
    if (pi_i2c_read(pi, 1, 0x89, &distance, 2) != PI_NO_ERROR) {
        fprintf(stderr, "Error reading data-ready bit. Exiting...\n");
        exit(EXIT_FAILURE);
    }

    // Check if data ready
    if (distance & 0x01) {
        // Read distance data
        if (pi_i2c_read(pi, 1, 0x96, &distance, 2) != PI_NO_ERROR) {
            fprintf(stderr, "Error reading distance data. Exiting...\n");
            exit(EXIT_FAILURE);
        }

        // Handle distance
        handle_distance(distance);
    } else {
        fprintf(stderr, "No data ready. Skipping ranging.\n");
    }
}

// Function to handle distance measurement
void handle_distance(short distance) {
    if (distance < 100) {
        // Activate buzzer on GPIO 23
        if (gpio_mode_set(pi, GPIO23, GPIO_OUTPUT) != PI_NO_ERROR) {
            fprintf(stderr, "Error setting GPIO 23 to output. Exiting...\n");
            exit(EXIT_FAILURE);
        }
        gpio_write(pi, GPIO23, 1); // Buzzer on
    }
}

// Function to clean up resources
void cleanup_resources() {
    // Stop ranging
    pi_i2c_write(pi, 1, 0x80, 0x00, 1);

    // Close I2C bus 1
    pi_i2c_close(pi, 1);

    // Release pigpio handle
    pigpio_free(pi);

    // Clean up POSIX message queue
    msq_unlink("distance_queue");
}

// Signal handler for SIGINT
void signal_handler(int signum) {
    // Clean up resources
    cleanup_resources();
    exit(EXIT_FAILURE);
}

