#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define TRIGGER_GPIO 17
#define ECHO_GPIO 27
#define BUZZER_GPIO 22
#define SPEED_OF_SOUND_CM_PER_S 34300
#define MIN_DISTANCE_CM 2
#define MAX_DISTANCE_CM 400
#define INTERVAL_MS 100

// Global variables
pigpio *pi;
volatile uint32_t echo_time;
int buzzer_state = 0;

// Function prototypes
void initialize_pigpio();
void setup_gpios();
void handle_interrupt();
void compute_distance(uint32_t echo_time);
void display_distance();
void handle_buzzer();
void cleanup();
void signal_handler(int signum);

int main() {
    // Initialize global variables
    pi = NULL;
    echo_time = 0;

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Attempt to initialize pigpio
    if (pi == NULL) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    // Set up GPIOs
    initialize_pigpio();
    setup_gpios();

    // Main loop
    while (1) {
        // Wait for interrupt
        if (gpioWaitForEdge(TRIGGER_GPIO, GPIO_RISING, 0) == 0) {
            handle_interrupt();
        }

        // Check and display distance every INTERVAL_MS milliseconds
        if (millis() - last_distance_time >= INTERVAL_MS) {
            compute_distance(echo_time);
            display_distance();
            last_distance_time = millis();
        }

        // Handle buzzer based on distance
        handle_buzzer();

        // Sleep to avoid CPU hogging
        usleep(10000);
    }

    // Clean up on exit
    cleanup();

    return EXIT_SUCCESS;
}

// Function to initialize pigpio
void initialize_pigpio() {
    if (pigpioSetup(0) == -1) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }
}

// Function to setup GPIOs
void setup_gpios() {
    if (gpioMode(TRIGGER_GPIO, GPIO_OUTPUT_PP) == -1) {
        fprintf(stderr, "Failed to set TRIGGER_GPIO to output\n");
        exit(EXIT_FAILURE);
    }

    if (gpioMode(ECHO_GPIO, GPIO_INPUT) == -1) {
        fprintf(stderr, "Failed to set ECHO_GPIO to input\n");
        exit(EXIT_FAILURE);
    }

    if (gpioMode(BUZZER_GPIO, GPIO_OUTPUT_PP) == -1) {
        fprintf(stderr, "Failed to set BUZZER_GPIO to output\n");
        exit(EXIT_FAILURE);
    }

    // Set trigger GPIO to LOW
    gpioWrite(TRIGGER_GPIO, 0);

    // Register alert for echo GPIO
    if (gpioSetAlertFuncEx(ECHO_GPIO, alert_handler, NULL) == -1) {
        fprintf(stderr, "Failed to register echo GPIO alert\n");
        exit(EXIT_FAILURE);
    }
}

// Interrupt handler for echo GPIO
void alert_handler(void *arg) {
    uint32_t now = micros();

    // Avoid overflow by checking against wraparound
    if (now - echo_time >= (uint32_t)(PI_MAX_TICKS * 1000)) {
        echo_time = now;
    }

    // Compute distance
    compute_distance(echo_time);
}

// Function to compute distance from echo time
void compute_distance(uint32_t echo_time) {
    uint32_t duration = echo_time - (uint32_t)(gpioRead(TRIGGER_GPIO) * 1000); // Convert to ms

    if (duration > 20000) { // Maximum duration for valid echo (20ms)
        fprintf(stderr, "Invalid reading: echo timeout or out of range\n");
        return;
    }

    float distance_cm = (duration * SPEED_OF_SOUND_CM_PER_S) / 2000.0; // Distance in cm

    if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
        fprintf(stderr, "Invalid reading: out of valid range\n");
        return;
    }

    printf("Distance: %.1f cm\n", distance_cm);
}

// Function to display distance
void display_distance() {
    printf("Distance: %.1f cm\n", echo_time_to_distance());
}

// Function to convert micros to distance
float echo_time_to_distance() {
    uint32_t echo_time_us = micros() - last_echo_time;
    return (float)echo_time_us * SPEED_OF_SOUND_CM_PER_S / (2 * 1000000.0); // Convert to cm and divide by 2 for round trip
}

// Function to handle buzzer based on distance
void handle_buzzer() {
    if (distance_cm < 30) {
        buzzer_state = 1; // Turn on buzzer
    } else {
        buzzer_state = 0; // Turn off buzzer
    }

    if (buzzer_state) {
        gpioWrite(BUZZER_GPIO, 1); // Turn on buzzer
    } else {
        gpioWrite(BUZZER_GPIO, 0); // Turn off buzzer
    }
}

// Function to cleanup resources
void cleanup() {
    if (pi != NULL) {
        gpioTerminate();
        pigpioTerminate(pi);
    }
}

// Signal handler for SIGINT
void signal_handler(int signum) {
    // Clean up on SIGINT
    cleanup();
    exit(EXIT_SUCCESS);
}

