#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24

// Constants
#define SPEED_OF_SOUND_CM_PER_S 343
#define TICKS_PER_MS 1000 // Approximate ticks per millisecond
#define MAX_DISTANCE_CM 30000 // Maximum distance threshold
#define MIN_DISTANCE_MS 100 // Minimum valid pulse width in microseconds

// Function prototypes
void initialize_pigpio(void);
void cleanup_resources(void);
void measure_distance(void);
void handle_interrupts(int signum);
void log_measurement(char* timestamp, int distance_cm);

// Global variables
pigpio *pi;
FILE *distance_log_file;
int last_triggered_time_ms = 0;

// Main function
int main(void) {
    // Initialize pigpio with error checking
    initialize_pigpio();

    // Register signal handlers
    signal(SIGINT, handle_interrupts);
    signal(SIGTERM, handle_interrupts);

    // Main loop
    while (1) {
        measure_distance();
        usleep(200 * 1000); // Wait 200 ms
    }

    // Clean up on exit
    cleanup_resources();

    return 0;
}

// Function to initialize pigpio with error checking
void initialize_pigpio(void) {
    pi = pigpioOpen();

    if (pi == NULL) {
        fprintf(stderr, "Failed to open pigpio: %s\n", pigpioError());
        exit(1);
    }

    // Set TRIG pin as output
    if (pigpioWrite(pi, TRIG_PIN, 1) == -1) {
        fprintf(stderr, "Failed to set TRIG pin as output: %s\n", pigpioError());
        pigpioClose(pi);
        exit(1);
    }

    // Set ECHO pin as input with pull-down
    if (pigpioMode(pi, ECHO_PIN, pigpioInputPullDown) == -1) {
        fprintf(stderr, "Failed to set ECHO pin as input with pull-down: %s\n", pigpioError());
        pigpioClose(pi);
        exit(1);
    }

    // Register alert callback
    if (pigpioSetAlert(pi, ECHO_PIN, pigpioEdgeBoth, measure_distance, NULL) == -1) {
        fprintf(stderr, "Failed to set alert callback: %s\n", pigpioError());
        pigpioClose(pi);
        exit(1);
    }
}

// Function to handle interrupts (SIGINT, SIGTERM)
void handle_interrupts(int signum) {
    fprintf(stderr, "Interrupt received: shutting down...\n");
    cleanup_resources();
    pigpioClose(pi);
    exit(0);
}

// Function to measure distance
void measure_distance(void) {
    // Trigger the sensor
    pigpioWrite(pi, TRIG_PIN, 1);
    usleep(10); // 10 microseconds pulse

    // Wait for echo
    int rising_edge_tick = 0;
    int falling_edge_tick = 0;

    while (pigpioWaitForEdge(pi, ECHO_PIN, pigpioEdgeRising, &rising_edge_tick) == 0) {
        falling_edge_tick = pigpioWaitForEdge(pi, ECHO_PIN, pigpioEdgeFalling, NULL);
    }

    // Calculate pulse duration
    int pulse_duration_us = falling_edge_tick - rising_edge_tick;

    // Check for wraparound
    if (pulse_duration_us > 0xFFFFFFFF) {
        pulse_duration_us -= 0xFFFFFFFF; // Correct for wraparound
    }

    // Validate pulse width
    if (pulse_duration_us < MIN_DISTANCE_MS * TICKS_PER_MS || pulse_duration_us > MAX_DISTANCE_CM * TICKS_PER_CM) {
        fprintf(stderr, "Warning: Rejected reading due to invalid pulse width (%d us)\n", pulse_duration_us);
        return;
    }

    // Calculate distance in cm
    int distance_cm = (pulse_duration_us * SPEED_OF_SOUND_CM_PER_S) / (2 * TICKS_PER_MS);

    // Log the measurement
    char timestamp[50];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
    log_measurement(timestamp, distance_cm);

    last_triggered_time_ms = (int)(now - (time_t)(last_triggered_time_ms * 1000)) / 1000;
}

// Function to log a measurement
void log_measurement(char* timestamp, int distance_cm) {
    char buffer[256];
    sprintf(buffer, "%s, %d cm", timestamp, distance_cm);

    // Append to distance_log.txt
    if (fopen("distance_log.txt", "a") == NULL) {
        fprintf(stderr, "Failed to open distance_log.txt for append: %s\n", strerror(errno));
        return;
    }

    fprintf(distance_log_file, "%s\n", buffer);
    fflush(distance_log_file);
}

// Function to cleanup resources
void cleanup_resources(void) {
    // Close the log file
    if (distance_log_file != NULL) {
        fclose(distance_log_file);
        distance_log_file = NULL;
    }

    // Release GPIO resources
    pigpioClose(pi);
}

