    while (1) {
        handle_gate_state();
        usleep(100000); // Sleep for 100ms
    }

    // Clean up resources
    cleanup_resources();

    return EXIT_SUCCESS;
}

// Function to setup pigpio
void setup_pigpio() {
    if (pi_pigpio_init() == -1) {
        fprintf(stderr, "Error initializing pigpio\n");
        return;
    }
}

// Function to setup VL53L1X
