    // Check if the sensor model is valid
    if (pi_i2c_read(VL53L1X_I2C_BUS, VL53L1X_ADDRESS, 0x0f) != 0x15) {
        fprintf(stderr, "Invalid VL53L1X model detected\n");
        return -1;
    }

    // Set up I2C communication
    if (pi_i2c_write(VL53L1X_I2C_BUS, VL53L1X_ADDRESS, 0x06) == -1) {
        fprintf(stderr, "Error writing to VL53L1X\n");
        return -1;
    }

    // Set up GPIO pins for VL53L1X
    if (gpio_mode_input(GPIO_SHUTDOWN) == -1 || gpio_mode_input(GPIO_INTERRUPT) == -1) {
        fprintf(stderr, "Error setting VL53L1X GPIO pins as input\n");
        return -1;
    }

    return 0;
}

