    // Cleanup GPIO pins
    gpio_free(GPIO_SHUTDOWN);
    gpio_free(GPIO_INTERRUPT);

    // Shutdown pigpio
    pi_pigpio_cleanup();
}

// Signal handler for clean exit
void signal_handler(int signum) {
    // Clean up resources
    cleanup_resources();
    exit(EXIT_SUCCESS);
