#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>

// Define GPIO pins for the gate actuator
#define GATE_OPEN_PIN 18
#define GATE_CLOSE_PIN 19

// Define VL53L1X I2C address and register offsets
#define VL53L1X_ADDRESS 0x29
#define VL53L1X_REG_REGISTER_STATUS 0x20
#define VL53L1X_REG_REGISTER_RANGING_MODE 0x21
#define VL53L1X_REG_REGISTER_RANGING_DATA_LOW 0x22
#define VL53L1X_REG_REGISTER_RANGING_DATA_HIGH 0x23

// Initialize pigpio and setup signal handlers
pigpio *gp;
void signal_handler(int signum) {
    if (gp != NULL) {
        fclose(logfile);
        gpioTerminate(gp);
        close(gp->i2c);
        gp = NULL;
    }
    exit(0);
}

int main() {
    // Initialize pigpio and setup GPIO pins
    gp = pigpioOpen();
    if (gp == NULL) {
        fprintf(stderr, "Failed to open pigpio: %s\n", pigpioError());
        return EXIT_FAILURE;
    }

    gpioMode(GATE_OPEN_PIN, GPIO_OUTPUT);
    gpioMode(GATE_CLOSE_PIN, GPIO_INPUT);
    gpioWrite(GATE_OPEN_PIN, 0); // Ensure gate is closed initially

    // Open log file for writing
    FILE *logfile = fopen("gate_events.log", "a+");
    if (logfile == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        pigpioClose(gp);
        return EXIT_FAILURE;
    }

    // Signal handler registration
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Soft reset VL53L1X
    uint8_t resetCommand = 0x0F;
    if (i2cWriteI2CBlockData(gp->i2c, VL53L1X_ADDRESS, &resetCommand, 1, 1) != 1) {
        fprintf(stderr, "Failed to reset VL53L1X: %s\n", pigpioError());
        fclose(logfile);
        gpioClose(gp, GATE_OPEN_PIN);
        gpioClose(gp, GATE_CLOSE_PIN);
        pigpioClose(gp);
        return EXIT_FAILURE;
    }

    // Configure ranging mode and start ranging
    uint8_t rangingMode = 0x01;
    if (i2cWriteI2CBlockData(gp->i2c, VL53L1X_ADDRESS, &rangingMode, 1, 1) != 1) {
        fprintf(stderr, "Failed to set ranging mode: %s\n", pigpioError());
        fclose(logfile);
        gpioClose(gp, GATE_OPEN_PIN);
        gpioClose(gp, GATE_CLOSE_PIN);
        pigpioClose(gp);
        return EXIT_FAILURE;
    }

    while (1) {
        // Start ranging
        if (i2cWriteI2CBlockData(gp->i2c, VL53L1X_ADDRESS, &VL53L1X_REG_REGISTER_RANGING_MODE, 1, 1) != 1) {
            fprintf(stderr, "Failed to start ranging: %s\n", pigpioError());
            continue;
        }

        // Wait for ranging to complete
        uint16_t timeout = 500; // 500 ms timeout
        while (true) {
            uint16_t lowData = 0, highData = 0;
            if (i2cReadI2CBlockData(gp->i2c, VL53L1X_ADDRESS, &lowData, 1, 2) != 2) {
                fprintf(stderr, "Failed to read ranging data: %s\n", pigpioError());
                break;
            }
            highData = (highData << 8) | lowData;

            // Calculate distance
            uint16_t distance = (highData << 8) | lowData;
            distance /= 16; // Convert from 16-bit register value to mm

            // Check if object is within 200 mm
            if (distance <= 200) {
                // Open the gate
                gpioWrite(GATE_OPEN_PIN, 1);
                gpioWrite(GATE_CLOSE_PIN, 0);
                // Log the event
                char timestamp[50];
                time_t now = time(NULL);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.000Z", localtime(&now));
                fprintf(logfile, "Opened gate at %s\n", timestamp);
            } else {
                // Close the gate
                gpioWrite(GATE_OPEN_PIN, 0);
                gpioWrite(GATE_CLOSE_PIN, 1);
                // Log the event
                fprintf(logfile, "Closed gate at %s\n", timestamp);
            }

            // Check for termination signal
            if (gp != NULL) {
                if (pigpioCheckSignal(gp) == PI_SIGINT || pigpioCheckSignal(gp) == PI_SIGTERM) {
                    break;
                }
            }

            // Polling delay
            usleep(100000); // 100 ms delay
        }

        // Reset ranging mode after completion
        if (i2cWriteI2CBlockData(gp->i2c, VL53L1X_ADDRESS, &VL53L1X_REG_REGISTER_RANGING_MODE, 1, 1) != 1) {
            fprintf(stderr, "Failed to reset ranging mode: %s\n", pigpioError());
        }
    }

    // Clean up resources
    fclose(logfile);
    gpioClose(gp, GATE_OPEN_PIN);
    gpioClose(gp, GATE_CLOSE_PIN);
    pigpioClose(gp);

    return EXIT_SUCCESS;
}

