#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>

// Define GPIO pins
#define GPIO24 18
#define GPIO17 22
#define GPIO18 23

// Define VL53L1X I2C address and register offsets
#define VL53L1X_ADDRESS 0x29
#define RESET_REG 0x0000
#define START_MEASUREMENT_REG 0x0001
#define DATA_READY_REG 0x0089
#define DISTANCE_REG_HIGH 0x0096
#define DISTANCE_REG_LOW 0x0097

// Motor control constants
#define THRESHOLD_FORWARD 100
#define THRESHOLD_BACKWARD 300

// Function prototypes
void setup_pigpio();
void setup_i2c();
void read_distance();
void control_motor(uint16_t distance);
void cleanup();

// Global variables
pigpio *pi;
i2c_dev *i2c_dev;
uint16_t distance;

// Signal handler for SIGINT/SIGTERM
void signal_handler(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    cleanup();
    exit(0);
}

int main() {
    // Initialize pigpio
    setup_pigpio();

    // Set up GPIO pins
    if (gpioMode(GPIO24, GPIO_OUT) != PI_ERROR) {
        printf("Failed to set GPIO24 as output\n");
        return 1;
    }
    if (gpioMode(GPIO17, GPIO_OUT) != PI_ERROR) {
        printf("Failed to set GPIO17 as output\n");
        return 1;
    }
    if (gpioMode(GPIO18, GPIO_OUT) != PI_ERROR) {
        printf("Failed to set GPIO18 as output\n");
        return 1;
    }

    // Set up I2C
    if (i2c_open(1, 0, &i2c_dev) != I2C_OK) {
        printf("Failed to open I2C bus 1\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Trigger distance reading on GPIO24 rising edge
        if (pigpioISR(GPIO24, PI_RISING, (void *) &read_distance) != PI_ERROR) {
            printf("Failed to set ISR for GPIO24\n");
            continue;
        }

        read_distance();

        uint16_t distance_read = (distance >> 8) | distance;
        control_motor(distance_read);

        // Log distance and motor state
        printf("Distance: %u cm, Motor State: %s\n", distance_read, distance_read < THRESHOLD_FORWARD ? "Forward" : (distance_read > THRESHOLD_BACKWARD ? "Backward" : "Stopped"));
    }

    // Clean up on exit
    cleanup();

    return 0;
}

// Function to setup pigpio
void setup_pigpio() {
    pi = pigpioOpen();
    if (pi == NULL) {
        fprintf(stderr, "Failed to open pigpio\n");
        exit(1);
    }
    pigpioSetOverrun(pi, 0); // Disable overrun
}

// Function to setup I2C
void setup_i2c() {
    if (i2c_start(i2c_dev) != I2C_OK) {
        printf("Failed to start I2C transaction\n");
        return;
    }
    i2c_write(i2c_dev, VL53L1X_ADDRESS, RESET_REG, 0x00);
    usleep(1000); // Wait 1 ms
    i2c_write(i2c_dev, VL53L1X_ADDRESS, START_MEASUREMENT_REG, 0x01);
}

// Function to read distance from VL53L1X
void read_distance() {
    uint8_t data_ready;

    // Poll data ready bit
    while (true) {
        if (i2c_read(i2c_dev, VL53L1X_ADDRESS, DATA_READY_REG, &data_ready, 1) != I2C_OK) {
            // Retry with exponential backoff
            if (i2c_try_start(i2c_dev) == I2C_OK) {
                i2c_write(i2c_dev, VL53L1X_ADDRESS, DATA_READY_REG, 0x00);
                usleep(100); // Initial backoff
                continue;
            }
            // Maximum retries
            printf("Failed to read data ready bit after multiple retries\n");
            return;
        }
        if (data_ready) {
            break;
        }
    }

    // Read distance
    uint16_t high, low;
    if (i2c_read(i2c_dev, VL53L1X_ADDRESS, DISTANCE_REG_HIGH, &high, 2) != I2C_OK ||
        i2c_read(i2c_dev, VL53L1X_ADDRESS, DISTANCE_REG_LOW, &low, 2) != I2C_OK) {
        printf("Failed to read distance\n");
        return;
    }

    distance = (high << 8) | low;
}

// Function to control the motor based on distance
void control_motor(uint16_t distance) {
    if (distance < THRESHOLD_FORWARD) {
        // Forward
        gpioWrite(GPIO17, 1);
        gpioWrite(GPIO18, 0);
    } else if (distance > THRESHOLD_BACKWARD) {
        // Backward
        gpioWrite(GPIO17, 0);
        gpioWrite(GPIO18, 1);
    } else {
        // Stop
        gpioWrite(GPIO17, 0);
        gpioWrite(GPIO18, 0);
    }
