#include <unistd.h>

#define GPIO_NUM_17  17
#define GPIO_NUM_18  18
#define GPIO_NUM_27  27
#define GPIO_NUM_22  22

#define I2C_ADDR 0x5A
#define TOUCH_REG_STATUS_0 0x00
#define TOUCH_REG_STATUS_1 0x01
#define REGISTER_SOFT_RESET 0x80

#define ELE_CONFIG_RUN 0x0C
#define ELE_CONFIG_STOP 0x00

#define MHDR_BASELINE_FILTER 0x01
#define NHDR_BASELINE_FILTER 0x01
#define NCLR_BASELINE_FILTER 0x0E
#define FDLR_BASELINE_FILTER 0x00

#define TOUCH_THRESHOLD 0x0B
#define AUTO_CONFIG_5A 0x0B
#define AUTO_CONFIG_5D 0xC8
#define AUTO_CONFIG_5E 0x82
#define AUTO_CONFIG_5F 0xB4

#define LED_PATTERN_0 0b0000
#define LED_PATTERN_1 0b0001
#define LED_PATTERN_2 0b0010
#define LED_PATTERN_3 0b0011

volatile sig_atomic_t should_exit = 0;

void handle_signal(int signum) {
    should_exit = 1;
}

int main() {
    struct gpio_desc *gpio_pins[4] = {gpiod_get_desc(GPIO_NUM_17), gpiod_get_desc(GPIO_NUM_18),
                                      gpiod_get_desc(GPIO_NUM_27), gpiod_get_desc(GPIO_NUM_22)};
    struct i2c_dev *i2c_dev;
    int i2c_fd;
    int status_0, status_1;
    unsigned char data;
    struct timespec ts;

    // Initialize GPIO pins as outputs
    for (int i = 0; i < 4; ++i) {
        if (gpiod_direction_output(gpio_pins[i], 0) < 0) {
            fprintf(stderr, "Error setting GPIO %d as output\n", GPIO_NUM_i);
            return EXIT_FAILURE;
        }
    }

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device\n");
        return EXIT_FAILURE;
    }

    // Initialize I2C device
    i2c_dev = i2c_new_device(i2c_fd, I2C_ADDR);
    if (!i2c_dev) {
        fprintf(stderr, "Error initializing I2C device\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Soft reset the MPR121
    if (i2c_smbus_write_byte_data(i2c_dev, REGISTER_SOFT_RESET, 0x63) != 0x63) {
        fprintf(stderr, "Error during soft reset\n");
        i2c_del_device(i2c_dev);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Verify the sensor by reading back a known register
    if (i2c_smbus_read_byte_data(i2c_dev, 0x0F) != 0x0F) {
        fprintf(stderr, "Sensor verification failed\n");
        i2c_del_device(i2c_dev);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize MPR121
    data = MHDR_BASELINE_FILTER | NHDR_BASELINE_FILTER | NCLR_BASELINE_FILTER | FDLR_BASELINE_FILTER;
    if (i2c_smbus_write_byte_data(i2c_dev, 0x00, data) != data) {
        fprintf(stderr, "Error writing MHDR/NHDR/NCLR/FDLR\n");
        i2c_del_device(i2c_dev);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    data = AUTO_CONFIG_5A | AUTO_CONFIG_5D | AUTO_CONFIG_5E | AUTO_CONFIG_5F;
    if (i2c_smbus_write_byte_data(i2c_dev, 0x5A, data) != data) {
        fprintf(stderr, "Error writing auto-configuration registers\n");
        i2c_del_device(i2c_dev);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Enable all electrodes in run mode
    data = ELE_CONFIG_RUN;
    if (i2c_smbus_write_byte_data(i2c_dev, 0x00, data) != data) {
        fprintf(stderr, "Error enabling electrodes\n");
        i2c_del_device(i2c_dev);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!should_exit) {
        // Poll touch status registers
        if (i2c_smbus_read_word_data(i2c_dev, TOUCH_REG_STATUS_0) == 0x0000 &&
            i2c_smbus_read_word_data(i2c_dev, TOUCH_REG_STATUS_1) == 0x0000) {
            // No electrode detected
            fprintf(stderr, "No electrode detected\n");
            continue;
        }

        // Read electrode status
        status_0 = i2c_smbus_read_byte_data(i2c_dev, TOUCH_REG_STATUS_0);
        status_1 = i2c_smbus_read_byte_data(i2c_dev, TOUCH_REG_STATUS_1);

        // Map electrode to LED pattern
        int electrode_index = (status_0 & 0x0F) + (status_1 & 0x0F) * 16;
        int active_pattern = LED_PATTERN_0;

        switch (electrode_index) {
            case 0: active_pattern = LED_PATTERN_0; break;
            case 1: active_pattern = LED_PATTERN_1; break;
            case 2: active_pattern = LED_PATTERN_2; break;
            case 3: active_pattern = LED_PATTERN_3; break;
            default: // Should not happen
                fprintf(stderr, "Invalid electrode index\n");
                continue;
        }

        // Set active LED pattern
        for (int pin = 0; pin < 4; ++pin) {
            if (active_pattern & (1 << pin)) {
                gpiod_set_value(gpio_pins[pin], 1);
            } else {
                gpiod_set_value(gpio_pins[pin], 0);
            }
        }

        // Log proximity event with timestamp
        ts.tv_sec = time(NULL);
        ts.tv_nsec = 0;
        fprintf(stderr, "Proximity detected on electrode %d at %s\n", electrode_index, ctime(&ts));

        // Sleep for 50 ms
        usleep(50000);
    }

    // Clean up GPIO and I2C resources
    for (int i = 0; i < 4; ++i) {
        gpiod_set_value(gpio_pins[i], 0);
    }
    i2c_del_device(i2c_dev);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

