#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <gpiod.h>

#define GPIO_PIN 27
#define MPR121_I2C_BUS 1
#define MPR121_ADDRESS 0x5A
#define TOUCH_THRESHOLD 0x0A
#define RELEASE_THRESHOLD 0x05

// Function prototypes
void setup_pigpio();
void setup_gpiod();
void setup_mpr121();
void handle_proximity_detection();
void cleanup();
void signal_handler(int signum);

int main() {
    // Initialize pigpio and gpiod
    setup_pigpio();
    setup_gpiod();

    // Setup MPR121
    setup_mpr121();

    // Signal handler for SIGINT/SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        handle_proximity_detection();
        usleep(1000000); // 1 second delay
    }

    // Clean up on exit
    cleanup();

    return 0;
}

// Function to setup pigpio
void setup_pigpio() {
    if (pigpioSetup(0) == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }
}

// Function to setup gpiod
void setup_gpiod() {
    if (gpiod_open() < 0) {
        fprintf(stderr, "Failed to open GPIO: %s\n", gpiod_get_name());
        exit(EXIT_FAILURE);
    }

    if (gpiod_direction_output(GPIO_PIN, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO %d to output: %s\n", GPIO_PIN, gpiod_get_name());
        exit(EXIT_FAILURE);
    }
}

// Function to setup MPR121
void setup_mpr121() {
    if (i2c_open(MPR121_I2C_BUS) < 0) {
        fprintf(stderr, "Failed to open I2C bus %d: %s\n", MPR121_I2C_BUS, i2c_get_name());
        exit(EXIT_FAILURE);
    }

    if (i2c_smbus_write_byte_data(MPR121_I2C_BUS, MPR121_ADDRESS, 0x01) < 0) {
        fprintf(stderr, "Failed to write to MPR121: %s\n", i2c_get_error_string());
        exit(EXIT_FAILURE);
    }

    if (i2c_smbus_read_byte_data(MPR121_I2C_BUS, MPR121_ADDRESS) != 0x05) {
        fprintf(stderr, "MPR121 device ID mismatch: expected 0x05, got 0x%X\n", i2c_smbus_read_byte_data(MPR121_I2C_BUS, MPR121_ADDRESS));
        exit(EXIT_FAILURE);
    }

    if (i2c_smbus_write_byte_data(MPR121_I2C_BUS, MPR121_ADDRESS, TOUCH_THRESHOLD) < 0 ||
        i2c_smbus_write_byte_data(MPR121_I2C_BUS, MPR121_ADDRESS, RELEASE_THRESHOLD) < 0) {
        fprintf(stderr, "Failed to write thresholds: %s\n", i2c_get_error_string());
        exit(EXIT_FAILURE);
    }

    // Configure other MPR121 registers
    i2c_smbus_write_byte_data(MPR121_I2C_BUS, MPR121_ADDRESS, 0x02); // FFI
    i2c_smbus_write_byte_data(MPR121_I2C_BUS, MPR121_ADDRESS, 0x03); // SFI
    i2c_smbus_write_byte_data(MPR121_I2C_BUS, MPR121_ADDRESS, 0x04); // ESI
    i2c_smbus_write_byte_data(MPR121_I2C_BUS, MPR121_ADDRESS, 0x06); // Debounce
    i2c_smbus_write_byte_data(MPR121_I2C_BUS, MPR121_ADDRESS, 0x07); // AFE config

    // Baseline filtering
