#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <stdint.h>
#include <string.h>
#include <gpiod.h>

#define TRIGGER_GPIO 17
#define ECHO_GPIO 18
#define SPEED_OF_SOUND 343.0 // m/s
#define CM_PER_M 0.0343 // cm per microsecond

volatile sig_atomic_t sigIntFlag = 0;

void handleSigInt(int signum) {
    sigIntFlag = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *trigger_line, *echo_line;
    uint32_t pulse_us, echo_us, distance_cm;
    FILE *distance_log = fopen("distance_log.txt", "a+");
    char timestamp[50];

    if (gpiod_chip_open(&chip, GPIOD_CHIP_RASPBERRY_PI_0) < 0) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(chip, TRIGGER_GPIO, GPIOD_LINE_MODE_OUTPUT, GPIOD_LINE_DIR_OUT) < 0) {
        perror("gpiod_line_request_output (trigger)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(chip, ECHO_GPIO, GPIOD_LINE_MODE_INPUT, GPIOD_LINE_DIR_IN) < 0) {
        perror("gpiod_line_request_input (echo)");
        gpiod_line_release(chip, TRIGGER_GPIO);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (!sigIntFlag) {
        // Trigger sequence
        gpiod_line_set_value(chip, TRIGGER_GPIO, 0); // Trigger low
        usleep(5); // Hold low for 5 microseconds
        gpiod_line_set_value(chip, TRIGGER_GPIO, 1); // Trigger high
        usleep(10); // Pulse high for 10 microseconds
        gpiod_line_set_value(chip, TRIGGER_GPIO, 0); // Trigger low

        // Wait for echo rising edge with 30 ms timeout
        struct timespec timeout = { .tv_sec = 0, .tv_nsec = 30000000 };
        if (gpiod_line_get_value(chip, ECHO_GPIO) == 0) {
            fprintf(distance_log, "Error: Sensor absent.\n");
            continue;
        }

        // Measure echo pulse width with 30 ms timeout
        pulse_us = 0;
        while (gpiod_line_get_value(chip, ECHO_GPIO) == 1 && nanosleep(&timeout, NULL) > 0) {
            pulse_us++;
        }

        // Compute distance
        echo_us = pulse_us;
        distance_cm = (echo_us * SPEED_OF_SOUND * CM_PER_M) / 2000.0;

        // Validate distance
        if (distance_cm < 2.0 || distance_cm > 400.0) {
            fprintf(distance_log, "Error: Distance out of range (%.1f cm)\n", distance_cm);
            continue;
        }

        // Format and write timestamp
        time_t rawtime = time(NULL);
        struct tm *timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%.3fZ", timeinfo);

        fprintf(distance_log, "%s, Distance: %.1f cm\n", timestamp, distance_cm);

        // Flush the log file
        fflush(distance_log);
    }

    // Release resources on SIGINT
    if (sigIntFlag) {
        gpiod_line_release(chip, TRIGGER_GPIO);
        gpiod_line_release(chip, ECHO_GPIO);
        fclose(distance_log);
        gpiod_chip_close(chip);

        printf("SIGINT received. Cleaning up and exiting.\n");
        exit(EXIT_SUCCESS);
    }

    // Release resources
    gpiod_line_release(chip, TRIGGER_GPIO);
    gpiod_line_release(chip, ECHO_GPIO);
    gpiod_chip_close(chip);

    printf("Exiting normally.\n");
    return EXIT_SUCCESS;
}

