This C program uses the libgpiod library to interact with GPIO pins on a Raspberry Pi Zero W to measure distance with an HC-SR04 ultrasonic sensor. It handles GPIO resource management, error checking, and resource release on all exit paths, including SIGINT handling. The program logs distance readings to a file every second, formatted with an ISO 8601 UTC timestamp, and gracefully handles sensor absence and distance out of range errors.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define DIVIDER_RESISTOR 1000 // 1 kOhm
#define LOAD_RESISTOR 2000   // 2 kOhm
#define MAX_DISTANCE 4000.0  // Maximum expected distance in meters

// GPIO pin numbers for BCM mode
#define TRIGGER_GPIO 17
#define ECHO_GPIO 18

// Function prototypes
void setup_pigpio();
void setup_hc_sr04();
void measure_distance();
void handle_interrupt(int);
void cleanup();
void signal_handler(int signum);

// Global variables
pigpio *pi;
FILE *distance_log;
unsigned long last_trigger_time = 0;
unsigned long pulse_width = 0;
unsigned long timestamp;

// ISR function pointer
volatile void (*isr_func)(void);

// Main function
int main() {
    // Initialize pigpio and setup HC-SR04
    setup_pigpio();
    setup_hc_sr04();

    // Set up ISR
    isr_func = handle_interrupt;
    pi->gpioSetISRFuncEx(TRIGGER_GPIO, GPIO_ACTIVE_LOW, isr_func, 0);

    // Signal handler for clean shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        measure_distance();
        fprintf(distance_log, "%lu %lf\n", timestamp, (float) pulse_width * 343.0 / 2000000.0);
        usleep(1000000); // Wait 1 second
        last_trigger_time = timestamp;
    }

    // Clean up
    cleanup();

    return 0;
}

// Function to setup pigpio
void setup_pigpio() {
    pi = pigpioOpen();
    if (pi == NULL) {
        fprintf(stderr, "Failed to open pigpio\n");
        exit(EXIT_FAILURE);
    }

    if (pigpioSetupInterrupts(pi) == -1) {
        fprintf(stderr, "Failed to setup interrupts\n");
        pigpioClose(pi);
        exit(EXIT_FAILURE);
    }
}

// Function to setup HC-SR04
void setup_hc_sr04() {
    // Configure GPIO pins for TRIG and ECHO
    if (pi->gpioMode(TRIGGER_GPIO, GPIO_OUTPUT_PP) == -1) {
        fprintf(stderr, "Failed to set TRIGGER GPIO mode\n");
        exit(EXIT_FAILURE);
    }
    if (pi->gpioWrite(TRIGGER_GPIO, GPIO_LOW) == -1) {
        fprintf(stderr, "Failed to set TRIGGER GPIO low\n");
        exit(EXIT_FAILURE);
    }

    if (pi->gpioMode(ECHO_GPIO, GPIO_INPUT_LEV) == -1) {
        fprintf(stderr, "Failed to set ECHO GPIO mode\n");
        exit(EXIT_FAILURE);
    }

    // Set up voltage divider
    if (pi->gpioWrite(DIVIDER_PIN, GPIO_LOW) == -1 || pi->gpioWrite(LOAD_PIN, GPIO_LOW) == -1) {
        fprintf(stderr, "Failed to set voltage divider pins low\n");
        exit(EXIT_FAILURE);
    }

    // Enable internal pull-up on TRIGGER_GPIO
    if (pi->gpioPullUp(TRIGGER_GPIO) == -1) {
        fprintf(stderr, "Failed to enable pull-up on TRIGGER_GPIO\n");
        exit(EXIT_FAILURE);
    }
}

// Function to measure distance
void measure_distance() {
    unsigned long now = pi->milliTime();
    if (now - last_trigger_time > 1000) { // Trigger once per second
        last_trigger_time = now;
        pi->gpioWrite(TRIGGER_GPIO, GPIO_HIGH);
        pi->gpioWrite(TRIGGER_GPIO, GPIO_LOW);

        // Wait for echo
        while (pi->gpioRead(ECHO_GPIO) == 0) {
            // No echo detected, possibly due to noise or object too close
            if (pi->milliTime() - last_trigger_time > 100) {
                fprintf(stderr, "Timeout waiting for echo\n");
                return;
            }
        }

        pulse_width = pi->milliTime() - now; // Calculate pulse width
        if (pulse_width < 58 || pulse_width > 25000) { // Check for valid pulse width
            fprintf(stderr, "Invalid pulse width detected\n");
            return;
        }
    }
}

// Interrupt Service Routine (ISR)
void handle_interrupt(int pin) {
    if (pin == TRIGGER_GPIO) {
        // Ignore trigger signal as it's already handled in measure_distance
        return;
    }

    // Handle echo signal
    pulse_width = pi->milliTime() - isr_func->last_time;
    isr_func->last_time = pi->milliTime();
    if (pulse_width > 0 && pulse_width <= 25000) { // Valid echo pulse width
        measure_distance();
    }
}

// Function to cleanup and close resources
void cleanup() {
    if (distance_log != NULL) {
        fclose(distance_log);
        distance_log = NULL;
    }

    pi->gpioClearInterrupt(TRIGGER_GPIO); // Clear interrupt for TRIGGER_GPIO
    pi->gpioTerminateInterrupts();

    pigpioClose(pi);
    pi = NULL;
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    cleanup();
    exit(EXIT_SUCCESS);
}

