    // Wait for ranging to complete
    usleep(5000);

    // Read distance from registers 0x0089 and 0x008A
    if (gpiod_i2c_transfer(I2C_ADDRESS, NULL, 0, (uint8_t *){0x89, 0x00}, 2, (uint8_t *){0x00, 0}, 2) != 2) {
