#define SPEED_OF_SOUND_CM_PER_S 34300
#define VALID_RANGE_CM 2.0f, 400.0f
#define SAMPLING_INTERVAL_MS 100
#define MOVING_AVERAGE_WINDOW_SIZE 5
#define SERVO_MIN_PULSE_WIDTH_US 500
#define SERVO_MAX_PULSE_WIDTH_US 2500
#define SERVO_DEFAULT_ANGLE 90.0f

// Global Variables
volatile sig_atomic_t sigIntFlag = 0;
pigpio *pi;
double lastTriggerTime;
double echoTime;
double distance;
int servoAngle;
int servoPulseWidth;
int servoError;
FILE *distanceLog;

// Function prototypes
void initializePigpio();
void initializeServo();
void handleSIGINT(int);
void measureDistance();
void updateServoAngle(double distance);
void writeToCSV(const char *message);
void alertHandler(pigpio *pi, int channel, int value);

// Main Function
int main() {
    // Initialize global variables
    pi = NULL;
    servoAngle = SERVO_DEFAULT_ANGLE;
    servoError = 0;
    distanceLog = NULL;

    // Signal handler for SIGINT
    signal(SIGINT, handleSIGINT);

    // Initialize pigpio and servo
    initializePigpio();
    initializeServo();

    // Main loop
    while (!sigIntFlag) {
        // Trigger the ultrasonic sensor
        lastTriggerTime = pi_pwm_write(pi, PIGPIO_TRIGGER_GPIO, 1, 10);
        pi_pwm_write(pi, PIGPIO_TRIGGER_GPIO, 0);

        // Wait for echo
        while (echoTime == 0) {
            // Check for timeout
            if (pi_time() - lastTriggerTime > 30) {
                echoTime = -1.0;
                servoAngle = SERVO_DEFAULT_ANGLE;
                break;
            }
        }

        // Measure distance
        distance = calculateDistance(echoTime);
        updateServoAngle(distance);

        // Write to CSV
        writeToCSV("Timestamp,Distance(cm),Servo Angle(°)");
        writeToCSV(fprintf("%f,%f,%f", pi_time(), distance, servoAngle));

        // Sleep to avoid excessive CPU usage
        usleep(SAMPLING_INTERVAL_MS * 1000000);
    }

    // Clean up on SIGINT
    handleSIGINT(SIGINT);

    // Close resources and terminate pigpio
    if (pi != NULL) {
        gpioTerminate(pi);
        pi = NULL;
    }

    return 0;
}

// Helper Functions

// Initialize pigpio
void initializePigpio() {
    if (pi_init() == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }
}

// Initialize servo
void initializeServo() {
    if (gpio_mode(SERVO_GPIO, GPIO_MODE_PWM_OUTPUT) == -1) {
        fprintf(stderr, "Failed to set servo pin to PWM output: %s\n", strerror(errno));
        servoError = -1;
        return;
    }

    if (gpio_pwm_write(SERVO_GPIO, 1500) == -1) {
        fprintf(stderr, "Failed to set initial servo position: %s\n", strerror(errno));
        servoError = -1;
        return;
    }
}

// Handle SIGINT
void handleSIGINT(int sig) {
    sigIntFlag = 1;
}

// Calculate distance from pulse width
double calculateDistance(double pulseWidth) {
    if (pulseWidth < 0 || pulseWidth > 200000) {
        return -1.0; // Out of range
    }

    double distance = (pulseWidth * SPEED_OF_SOUND_CM_PER_S) / 58000.0; // 58 cm/us
    return distance;
}

// Update servo angle based on distance
void updateServoAngle(double distance) {
    if (distance < VALID_RANGE_CM.min || distance > VALID_RANGE_CM.max) {
        servoAngle = SERVO_DEFAULT_ANGLE;
        return;
    }

    // Non-linear (logarithmic) mapping
    double mappedDistance = (distance - VALID_RANGE_CM.min) / (VALID_RANGE_CM.max - VALID_RANGE_CM.min);
    mappedDistance = log(mappedDistance + 1.0); // Apply logarithm to map to [0, 1]
    mappedDistance = (mappedDistance * 180.0) - 90.0; // Map to servo angle range

    // Clamp the angle to valid range
    if (mappedDistance < 0) {
        mappedDistance = 0;
    } else if (mappedDistance > 180) {
        mappedDistance = 180;
    }

    servoAngle = (int) mappedDistance; // Convert to integer for PWM
}

// Write to CSV file
void writeToCSV(const char *message) {
    if (distanceLog == NULL) {
        distanceLog = fopen("distance_log.csv", "a");
        if (distanceLog == NULL) {
            fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
            return;
        }
    }

    fprintf(distanceLog, "%s\n", message);
    fflush(distanceLog);
}

// Alert handler for echo pulse width
void alertHandler(pigpio *pi, int channel, int value) {
    if (value > 0) {
        echoTime = pi_time(); // Capture current time
        distance = calculateDistance((double)value * 58); // Convert to cm using 58 us/cm
        lastTriggerTime = echoTime;

        // Share data with the main thread
        sigIntFlag = 1; // Signal to main thread to process the new distance
    }
}

