    // Initialize pigpio
    pigpio *pi = NULL;
    if (pigpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error());
        return EXIT_FAILURE;
    }

    // Install SIGINT handler
    signal(SIGINT, handleSIGINT);

    // Initialize the sensor
    initializeSensor(pi);

    // Main loop
    while (1) {
        readDistance(pi);
        usleep(50000); // Sleep for 50 ms
    }

    // Clean up resources
    cleanupResources(pi);

    // Exit
    pigpio_cleanup(pi);
    return EXIT_SUCCESS;
}

// Function to initialize the sensor
void initializeSensor(pigpio *pi) {
    // Check if I2C is available
    if (pigpio_i2c_available(pi) == 0) {
        fprintf(stderr, "I2C not available.\n");
        return;
    }

    // Open I2C bus 1
    int i2c_fd = pigpio_i2c_open(pi, 1);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus 1: %s\n", pigpio_error());
        return;
    }

    // Initialize the sensor with the STMicroelectronics sequence
    uint8_t command[] = {0x0f, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
    if (pigpio_i2c_write(i2c_fd, VL53L1X_ADDRESS, command, 10) != 10) {
        fprintf(stderr, "Failed to write to VL53L1X: %s\n", pigpio_error());
        pigpio_i2c_close(i2c_fd);
        return;
    }

    // Enable signal rate check
    command[0] = 0x0f;
    command[1] = 0x01;
    if (pigpio_i2c_write(i2c_fd, VL53L1X_ADDRESS, command, 2) != 2) {
        fprintf(stderr, "Failed to enable signal rate check: %s\n", pigpio_error());
        pigpio_i2c_close(i2c_fd);
        return;
    }

    // Configure cross-talk compensation
    command[0] = 0x0f;
    command[1] = 0x02;
    command[2] = 0x00; // Cross-talk compensation setting
    if (pigpio_i2c_write(i2c_fd, VL53L1X_ADDRESS, command, 3) != 3) {
        fprintf(stderr, "Failed to configure cross-talk compensation: %s\n", pigpio_error());
        pigpio_i2c_close(i2c_fd);
        return;
    }

    // Start ranging
    command[0] = 0x0f;
    command[1] = 0x03;
    if (pigpio_i2c_write(i2c_fd, VL53L1X_ADDRESS, command, 2) != 2) {
        fprintf(stderr, "Failed to start ranging: %s\n", pigpio_error());
        pigpio_i2c_close(i2c_fd);
        return;
    }

    // Store I2C handle for future use
    sensorI2c_fd = i2c_fd;
}

// Function to read distance
void readDistance(pigpio *pi) {
    // Read distance from the sensor
    uint16_t distance;
    if (pigpio_i2c_read(sensorI2c_fd, VL53L1X_ADDRESS, &distance, 2) != 2) {
        fprintf(stderr, "Failed to read distance: %s\n", pigpio_error());
        return;
    }

    // Check if distance is below warning threshold
    if (distance < 200) {
        // Set GPIO17 HIGH to activate warning LED
        pigpio_write(GPIO17_PIN, 1);
    } else {
        // Set GPIO17 LOW to deactivate warning LED
        pigpio_write(GPIO17_PIN, 0);
    }

    // Store the distance in the circular buffer
    distanceBuffer[BUFFER_SIZE - 1] = distance;
    distanceBuffer[--BUFFER_SIZE] = 0; // Wrap around the buffer

    // Print the last 10 readings
    for (int i = 0; i < BUFFER_SIZE; ++i) {
        printf("Distance: %d mm\n", distanceBuffer[i]);
    }
}

// SIGINT handler
void handleSIGINT(int signum) {
    // Turn off the warning LED
    pigpio_write(GPIO17_PIN, 0);

    // Close the I2C handle
    pigpio_i2c_close(sensorI2c_fd);

    // Clean up resources
    cleanupResources(pi);

    // Exit the program
    exit(0);
}

// Function to cleanup resources
void cleanupResources(pigpio *pi) {
    // Close I2C handle
    pigpio_i2c_close(sensorI2c_fd);

    // Close pigpio
    pigpio_close(pi);
}

// GPIO pin constants
#define GPIO17_PIN 17

// Main program execution
int main() {
    return main();
}

