#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>

#define PI_GPIO_NUM 27
#define SI1102_ADDR 0x60
#define DEFAULT_THRESHOLD 1000

// Global variables
pigpio *pi;
uint8_t i2c_bus = 1;
uint16_t proximity_value;
uint16_t threshold;
FILE *log_file;
volatile sig_atomic_t interrupt_flag = 0;

// Function prototypes
void setup_pigpio();
void setup_i2c();
void setup_gpio();
void handle_proximity();
void cleanup();

int main(int argc, char **argv) {
    // Parse command-line arguments
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <i2c_address> <threshold>\n", argv[0]);
        return 1;
    }

    i2c_bus = strtol(argv[1], NULL, 0); // Convert i2c address string to integer
    threshold = strtol(argv[2], NULL, 0); // Convert threshold string to integer

    // Initialize pigpio
    setup_pigpio();

    // Set up I2C and GPIO
    setup_i2c();
    setup_gpio();

    // Start the I2C interrupt thread
    pthread_t i2c_thread;
    if (pthread_create(&i2c_thread, NULL, &handle_proximity, NULL) != 0) {
        fprintf(stderr, "Failed to create I2C interrupt thread\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Check interrupt flag
        if (interrupt_flag) {
            handle_proximity();
            interrupt_flag = 0; // Clear flag
        }

        // Sleep to avoid 100% CPU usage
        usleep(10000);
    }

    // Clean up on SIGINT
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    return 0;
}

// Function: setup_pigpio
void setup_pigpio() {
    pi = pigpioOpen();
    if (pi == NULL) {
        fprintf(stderr, "Failed to open pigpio\n");
        return;
    }

    if (pigpioInterruptEnable(pi, PI_GPIO_NUM, 1) == -1) {
        fprintf(stderr, "Failed to enable GPIO interrupt\n");
    }
}

// Function: setup_i2c
void setup_i2c() {
    if (pigpioI2CInit(pi, i2c_bus) == -1) {
        fprintf(stderr, "Failed to initialize I2C bus %d\n", i2c_bus);
        return;
    }

    if (pigpioI2CWrite(pi, SI1102_ADDR, 0x08, 0) == -1 ||
        pigpioI2CRead(pi, SI1102_ADDR, 0x09, &proximity_value) == -1) {
        fprintf(stderr, "Failed to read proximity value\n");
        return;
    }

    // Convert proximity value to 16-bit integer
    proximity_value = (proximity_value << 8) | pigpioI2CRead(pi, SI1102_ADDR, 0x09);
}

// Function: setup_gpio
void setup_gpio() {
    if (pigpioModeSet(pi, PI_GPIO_NUM, pigpioOUTPUT) == -1) {
        fprintf(stderr, "Failed to set GPIO %d to output\n", PI_GPIO_NUM);
        return;
    }

    if (pigpioDigitalWrite(pi, PI_GPIO_NUM, 0) == -1) {
        fprintf(stderr, "Failed to set GPIO %d to low\n", PI_GPIO_NUM);
        return;
    }

    if (pigpioInterruptEnable(pi, PI_GPIO_NUM, 1) == -1) {
        fprintf(stderr, "Failed to enable GPIO interrupt\n");
        return;
    }
}

// Function: handle_proximity
void handle_proximity() {
    uint16_t proximity_value_read;
    if (pigpioI2CRead(pi, SI1102_ADDR, 0x08, &proximity_value_read) == -1 ||
        pigpioI2CRead(pi, SI1102_ADDR, 0x09, &proximity_value_read) == -1) {
        fprintf(stderr, "Failed to read proximity value\n");
        return;
    }

    proximity_value = (proximity_value_read << 8) | proximity_value_read;

    // Compare with threshold and log
    if (proximity_value > threshold) {
        fprintf(log_file, "%s %u ALERT\n", ctime(&time(NULL)), proximity_value);
    } else {
        fprintf(log_file, "%s %u SAFE\n", ctime(&time(NULL)), proximity_value);
    }

    // Clear interrupt flag
    interrupt_flag = 1;
}

// Function: cleanup
void cleanup() {
    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    // Close I2C handle
    pigpioI2CClose(pi, i2c_bus);

    // Close pigpio
    pigpioClose(pi);

    // Disable GPIO interrupt
    pigpioInterruptDisable(pi, PI_GPIO_NUM);

    // Clean up thread
    pthread_join(i2c_thread, NULL);
}

