    if (pi == NULL) {
        fprintf(stderr, "Failed to open pigpio: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }

    pigpioSetOverVoltage(pi, 1); // Enable over-voltage protection
    pigpioSetOverTemp(pi, 1);   // Enable over-temperature protection
}

// Function to cleanup pigpio
void cleanup_pigpio() {
    pigpioClose(pi);
}

// Signal handler to stop PWM and cleanup
void handle_signal(int signum) {
    stop_pwm();
    cleanup_pigpio();
    exit(EXIT_SUCCESS);
}

// Function to measure distance using HC-SR04
