    int trigger = 23;
    int echo = 24;

    // Trigger the sensor
    if (pigpioWrite(pi, trigger, 1) == -1) {
        fprintf(stderr, "Error triggering HC-SR04: %s\n", pigpioError());
        return;
    }

    // Wait for the trigger pulse to complete
    if (pigpioWaveTxBusy(pi, trigger) == 1) {
        fprintf(stderr, "Error waiting for trigger pulse: %s\n", pigpioError());
        return;
    }

    // Send the echo command and wait for the echo
    if (pigpioWrite(pi, echo, 1) == -1 || pigpioWaveTxBusy(pi, echo) > 200) {
        fprintf(stderr, "Error measuring distance: %s\n", pigpioError());
        return;
    }

    // Read the echo pulse width
    uint32_t echo_time = pigpioMilliTime();
    pigpioWrite(pi, echo, 0);
    uint32_t stop_time = pigpioMilliTime();

    if (stop_time - echo_time > 200) {
        fprintf(stderr, "Echo timeout: %s\n", pigpioError());
        return;
    }

    // Calculate distance
    uint32_t distance = (echo_time - stop_time) / 29.0;
    previous_distance = distance;
    set_frequency(distance);
}

// Function to set the frequency based on distance
void set_frequency(int distance) {
    double log_distance = log(distance / 2.0) / log(50.0);
    current_frequency = 200 * exp(log_distance) + 200; // Frequency range 200 Hz to 2000 Hz
}

// Function to start PWM output for the speaker
void start_pwm(int frequency) {
    int pwm_pin = 18;
    if (pigpioPWMWrite(pi, pwm_pin, frequency, 0) == -1) {
        fprintf(stderr, "Error starting PWM: %s\n", pigpioError());
        return;
    }
}

// Function to stop PWM output
void stop_pwm() {
    pigpioPWMStop(pi, 18);
}

