#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define MIN_FREQ 200
#define MAX_FREQ 2000
#define MIN_DIST 5
#define MAX_DIST 50
#define TRIGGER_GPIO 23
#define ECHO_GPIO 24
#define BUZZER_GPIO 18

// Global variables
pigpio *pi;
unsigned int distance;
unsigned int frequency;
unsigned int lastDistance;
int buzzerState = 0;

// Function prototypes
void setup_pigpio();
void handleSIGINT(int signum);
void read_distance();
void calculate_frequency();
void start_buzzer();
void stop_buzzer();

int main() {
    // Initialize global variables
    distance = 0;
    lastDistance = 0;
    frequency = MIN_FREQ;
    pi = NULL;

    // Register SIGINT handler
    signal(SIGINT, handleSIGINT);

    // Attempt to initialize pigpio
    if (pi == NULL) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    // Set GPIO modes
    if (piGPIOSetMode(TRIGGER_GPIO, GPIO_OUT_PP) != PI_ERROR) {
        fprintf(stderr, "Failed to set TRIGGER_GPIO mode\n");
        exit(EXIT_FAILURE);
    }
    if (piGPIOSetMode(ECHO_GPIO, GPIO_IN_PP) != PI_ERROR) {
        fprintf(stderr, "Failed to set ECHO_GPIO mode\n");
        exit(EXIT_FAILURE);
    }
    if (piGPIOSetMode(BUZZER_GPIO, GPIO_OUT_PP) != PI_ERROR) {
        fprintf(stderr, "Failed to set BUZZER_GPIO mode\n");
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Read distance
        read_distance();

        // Calculate frequency based on distance
        calculate_frequency();

        // Start buzzer with calculated frequency
        start_buzzer();

        // Delay for 10 ms
        usleep(10000);

        // Print distance and frequency
        printf("Distance: %u cm, Frequency: %u Hz\n", distance, frequency);

        // Check for SIGINT and stop buzzer if received
        handleSIGINT(0);
    }

    // Clean up
    stop_buzzer();
    piGPIOFree(pi);
    piFree(pi);

    return EXIT_SUCCESS;
}

// Function to initialize pigpio
void setup_pigpio() {
    pi = pigpioOpen();
    if (pi == NULL) {
        fprintf(stderr, "Failed to open pigpio\n");
        exit(EXIT_FAILURE);
    }
}

// SIGINT handler
void handleSIGINT(int signum) {
    stop_buzzer();
    piClose(pi);
    exit(EXIT_SUCCESS);
}

// Function to read distance using HC-SR04
void read_distance() {
    unsigned int pulseWidth;

    // Set trigger low
    piWriteDigital(TRIGGER_GPIO, 0);

    // Send 10 us high pulse
    usleep(10);
    piWriteDigital(TRIGGER_GPIO, 1);
    usleep(10);
    piWriteDigital(TRIGGER_GPIO, 0);

    // Measure echo pulse width
    pulseWidth = piPulseIn(ECHO_GPIO, 0);

    // Timeout if pulse width is too long
    if (pulseWidth > 100000) {
        distance = lastDistance;
        printf("Timeout error, using last valid distance\n");
    } else {
        distance = pulseWidth / 58; // Assuming 58 cm/us conversion
        lastDistance = distance;
    }
}

// Function to calculate frequency based on distance
void calculate_frequency() {
    unsigned int minFreq, maxFreq;

    // Map distance to frequency
    minFreq = MIN_FREQ;
    maxFreq = MAX_FREQ;
    if (distance < MIN_DIST) {
        minFreq = MIN_FREQ;
    } else if (distance > MAX_DIST) {
        maxFreq = MAX_FREQ;
    }

    // Linear interpolation within the range
    frequency = minFreq + (maxFreq - minFreq) * (MAX_DIST - distance) / (MAX_DIST - MIN_DIST);
    // Clamp frequency to the valid range
    if (frequency < minFreq) frequency = minFreq;
    if (frequency > maxFreq) frequency = maxFreq;
}

// Function to start the buzzer with a given frequency
void start_buzzer() {
    if (buzzerState) {
        piWriteDigital(BUZZER_GPIO, 0); // Stop buzzer
    }
    buzzerState = 1;
    piWriteDigital(BUZZER_GPIO, 1); // Start buzzer
    piHW_PWMStart(pi, BUZZER_GPIO, 0, 1, frequency); // Use hardware PWM
}

// Function to stop the buzzer
void stop_buzzer() {
    buzzerState = 0;
    piWriteDigital(BUZZER_GPIO, 0); // Stop buzzer
}

