This C program uses the `pigpio` library to control a piezo buzzer connected to GPIO18 for synthesizing a theremin-like instrument. It reads the distance from an HC-SR04 ultrasonic sensor connected to GPIO23 (trigger) and GPIO24 (echo), maps this distance to a frequency between 200 Hz and 2000 Hz, and outputs this frequency to the buzzer using hardware PWM for smooth tone changes. The program handles initialization errors, GPIO mode setting errors, distance read timeouts, and gracefully stops the buzzer and cleans up resources on SIGINT (Ctrl+C).

code:
#include <stdio.h>
#include <signal.h>
#include <pigpio.h>

volatile sig_atomic_t should_exit = 0;

// Function prototypes
void handleSIGINT(int signum);
void measureDistance();
void cleanup();

int main() {
    // Initialize pigpio
    if (gpiod_init() == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", gpiod_errstr());
        return 1;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, handleSIGINT);

    while (!should_exit) {
        measureDistance();
        usleep(500000); // Wait 500 ms
    }

    // Clean up resources
    cleanup();

    return 0;
}

// Signal handler for SIGINT
void handleSIGINT(int signum) {
    should_exit = 1;
}

// Function to measure distance using HC-SR04
void measureDistance() {
    int triggerPin = 17;
    int echoPin = 18;

    // Set trigger pin as output, initially low
    if (gpiod_direction_output(gpiod_get_channel(triggerPin), 0) == -1) {
        fprintf(stderr, "Failed to set trigger pin %d as output: %s\n", triggerPin, gpiod_errstr());
        return;
    }

    // Set echo pin as input
    if (gpiod_direction_input(gpiod_get_channel(echoPin)) == -1) {
        fprintf(stderr, "Failed to set echo pin %d as input: %s\n", echoPin, gpiod_errstr());
        return;
    }

    // Send trigger pulse
    if (gpiod_write(gpiod_get_channel(triggerPin), 1, 10) == -1) {
        fprintf(stderr, "Failed to send trigger pulse: %s\n", gpiod_errstr());
        return;
    }

    // Measure echo pulse width with 50 ms timeout
    int pulseWidth = gpiod_read(gpiod_get_channel(echoPin));
    if (pulseWidth == -1) { // Timeout
        fprintf(stderr, "Echo pulse measurement timed out: %s\n", gpiod_errstr());
        return;
    }

    // Compute distance in cm
    float distance = (float)pulseWidth / 2.0 / 29.1;

    // Reject readings below 2 cm or above 400 cm
    if (distance < 2.0 || distance > 400.0) {
        printf("Invalid reading\n");
    } else {
        printf("Distance: %.2f cm\n", distance);
        if (distance < 10.0) {
            printf("Too close!\n");
        }
    }
}

// Function to cleanup resources
void cleanup() {
    // Stop pigpio
    gpiod_stop();

    // Close GPIO channels
    for (int i = 17; i <= 18; i++) {
        if (gpiod_is_open(i)) {
            gpiod_close(i);
        }
    }
}

