    // Reject readings below 2 cm or above 400 cm
    if (distance < 2.0 || distance > 400.0) {
        printf("Invalid reading\n");
    } else {
        printf("Distance: %.2f cm\n", distance);
        if (distance < 10.0) {
            printf("Too close!\n");
        }
    }
}

// Function to cleanup resources
void cleanup() {
    // Stop pigpio
    gpiod_stop();

    // Close GPIO channels
    for (int i = 17; i <= 18; i++) {
        if (gpiod_is_open(i)) {
            gpiod_close(i);
        }
    }
}

