    pigpio *pi = NULL;
    if ((pi = pigpio_open()) == NULL) {
        fprintf(stderr, "Error: Failed to open pigpio.\n");
        close_spi();
        return EXIT_FAILURE;
    }

    // Setup GPIO for chip select
    if (gpio_mode(CHIP_SELECT_GPIO, GPIO_OUTPUT) == -1) {
