    while (1) {
        float distance;
        // Trigger measurement
        spi_xfer(&REG_MEASURE_TRIGGER, 1);

        // Read low and high bytes of distance
        uint8_t low_byte;
        uint8_t high_byte;
        spi_xfer(&REG_MEASUREMENT_LOW, 1);
        low_byte = spi_xfer(NULL, 1)[0];
        spi_xfer(&REG_MEASUREMENT_HIGH, 1);
        high_byte = spi_xfer(NULL, 1)[0];

        distance = (high_byte << 8) | low_byte;

