        fprintf(stderr, "SPI not initialized.\n");
        return;
    }

    if (write(SPI_DEVICE, tx_buffer, len) != len) {
        fprintf(stderr, "Error writing to SPI.\n");
        return;
    }

    if (read(SPI_DEVICE, tx_buffer, len) != len) {
        fprintf(stderr, "Error reading from SPI.\n");
    }
}

// Function to close SPI device and release resources
void close_spi() {
    if (spi_fd != -1) {
        close(spi_fd);
        spi_fd = -1;
    }
}

// Function to log distance with timestamp
void log_distance(float distance) {
    char timestamp[50];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(stderr, "Distance: %f mm at %s\n", distance, timestamp);
}

