    uint8_t set_range = 0x00;
    spi_xfer(&set_range, 1);

    // Write to trigger a measurement
    spi_xfer(&REG_MEASURE_TRIGGER, 1);
}

// Function to cleanup resources
void cleanup() {
    // No cleanup actions needed beyond closing SPI and releasing GPIO
}

