#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI1175_ADDR 0x60
#define SI1175_REG_LOW 0x22
#define SI1175_REG_HIGH 0x23

// Function prototypes
void error_handler(int signum);
void read_light_value(uint8_t *low_byte, uint8_t *high_byte);
void write_timestamp_and_value_to_csv(const char *timestamp_str, uint16_t light_value);

int main() {
    // Initialize signal handler for SIGINT and SIGTERM
    signal(SIGINT, error_handler);
    signal(SIGTERM, error_handler);

    // Open the I2C device
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Check if the I2C device is properly opened
    if (ioctl(i2c_fd, I2C_SLAVE, SI1175_ADDR) == -1) {
        perror("Failed to acquire I2C slave");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Get the current time
        time_t now = time(NULL);
        struct tm *time_info = localtime(&now);
        char timestamp_str[50];

        // Format the timestamp in ISO-8601
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", time_info);

        uint8_t low_byte, high_byte;
        read_light_value(&low_byte, &high_byte);

        // Write the timestamp and light value to the CSV file
        write_timestamp_and_value_to_csv(timestamp_str, (low_byte << 8) | high_byte);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Close the I2C file descriptor and the log file
    close(i2c_fd);
    fclose(stderr);

    return 0;
}

// Signal handler to clean up on SIGINT or SIGTERM
void error_handler(int signum) {
    // Close the I2C file descriptor and the log file
    close(i2c_fd);
    fclose(stderr);

    // Exit the program
    exit(EXIT_FAILURE);
}

// Function to read the light value from the sensor
void read_light_value(uint8_t *low_byte, uint8_t *high_byte) {
    uint16_t light_value = 0;

    // Read the low byte
    if (ioctl(i2c_fd, I2C_READ, SI1175_REG_LOW) == -1) {
        perror("Failed to read low byte");
        return;
    }
    *low_byte = (uint8_t)(read(0, &low_byte, 1)); // Read the actual byte

    // Read the high byte
    if (ioctl(i2c_fd, I2C_READ, SI1175_REG_HIGH) == -1) {
        perror("Failed to read high byte");
        return;
    }
    *high_byte = (uint8_t)(read(0, &high_byte, 1)); // Read the actual byte

    // Combine the bytes to form the 16-bit light value
    light_value = (uint16_t)(*low_byte << 8) | *high_byte;
}

// Function to write the timestamp and light value to the CSV file
void write_timestamp_and_value_to_csv(const char *timestamp_str, uint16_t light_value) {
    FILE *csv_file = fopen("proximity_log.csv", "a");
    if (!csv_file) {
        perror("Failed to open CSV file");
        return;
    }

    fprintf(csv_file, "%s, %04X\n", timestamp_str, light_value);
    fclose(csv_file);
}

