#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>

#define PIGPIO_ID 0  // Use the default pigpio ID

// Si1120 I2C address and registers
#define SI1120_ADDRESS 0x60
#define SI1120_REG_PART_ID 0x00
#define SI1120_REG_RESET 0x01
#define SI1120_REG_ALS_LOW 0x22
#define SI1120_REG_ALS_HIGH 0x23
#define SI1120_REG_PROX_LOW 0x18
#define SI1120_REG_PROX_HIGH 0x19

// Maximum retry attempts for I2C operations
#define MAX_RETRIES 3

// Function prototypes
void setup_pigpio();
void read_si1120(uint16_t* alson, uint16_t* proxson);
void handle_interrupt(int signum);
void write_reg(uint8_t reg, uint8_t value);
void read_reg(uint8_t reg, uint8_t* value);
void timestamp(char* time_str);
void log_data(uint16_t alson, uint16_t proxson);
void cleanup();

int main() {
    // Initialize pigpio
    setup_pigpio();

    // Signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, handle_interrupt);

    uint16_t alson;
    uint16_t proxson;
    char timestamp[50];
    FILE* log_file = fopen("si1120_log.txt", "a");

    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    while (1) {
        // Attempt to read data from the sensor
        for (int i = 0; i < MAX_RETRIES; ++i) {
            write_reg(SI1120_REG_RESET, SI1120_REG_RESET);
            if (i < MAX_RETRIES - 1) {
                usleep(10000); // 10 ms delay
            }

            read_reg(SI1120_REG_ALS_LOW, &alson);
            read_reg(SI1120_REG_ALS_HIGH, &alson);
            read_reg(SI1120_REG_PROX_LOW, &proxson);
            read_reg(SI1120_REG_PROX_HIGH, &proxson);

            // Combine ALS and Proximity readings into 16-bit values
            uint16_t alson_combined = (uint16_t)(alson << 8) | proxson;
            uint16_t proxson_combined = (uint16_t)(proxson << 8) | alson;

            timestamp(timestamp);
            log_data(alson_combined, proxson_combined);
