#define SI1182_ADDR 0x39
#define SI1182_PART_ID_REG 0x00
#define SI1182_MEASUREMENT_RATE_REG 0x08
#define SI1182_AMBIENT_LIGHT_REG 0x22
#define SI1182_PROXIMITY_REG 0x24

#define I2C_DEVICE "/dev/i2c-1"

void close_resources_and_exit(int status) {
    if (fd >= 0) {
        close(fd);
        fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    printf("Exiting due to signal or error.\n");
    exit(status);
}

void handle_i2c_error(int error) {
    fprintf(stderr, "I2C error: %d\n", error);
    close_resources_and_exit(EXIT_FAILURE);
}

int main() {
    int fd;
    char buffer[4];
    struct timeval tv;
    time_t timestamp;
    FILE *log_file = NULL;
    ssize_t bytes_read;

    // Open I2C device
    fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        close_resources_and_exit(EXIT_FAILURE);
    }

    // Initialize log file
    log_file = fopen("biometric_log.txt", "a+");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close_resources_and_exit(EXIT_FAILURE);
    }

    // Initialize sensor
    if (ioctl(fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        handle_i2c_error(errno);
    }

    // Verify part ID
    if (ioctl(fd, I2C_READ, SI1182_PART_ID_REG) < 0) {
        handle_i2c_error(errno);
        printf("Sensor not detected.\n");
        close_resources_and_exit(EXIT_FAILURE);
    }
    if (read(fd, buffer, 1) != 1) {
        handle_i2c_error(errno);
    }
    if (buffer[0] != 0x12) {
        printf("Invalid part ID. Sensor may not be Si1182-A-GM.\n");
        close_resources_and_exit(EXIT_FAILURE);
    }

    // Configure measurement rate
    if (ioctl(fd, I2C_WRITE, SI1182_MEASUREMENT_RATE_REG) < 0) {
        handle_i2c_error(errno);
    }
    if (write(fd, &0x07, 1) != 1) {
        handle_i2c_error(errno);
    }

    // Main loop
    while (1) {
        // Get current time
        gettimeofday(&tv, NULL);
        timestamp = tv.tv_sec * 1000 + tv.tv_usec / 1000;

        // Read ambient light and proximity data
        if (ioctl(fd, I2C_READ, SI1182_AMBIENT_LIGHT_REG) < 0 ||
            read(fd, buffer, 2) != 2) {
            handle_i2c_error(errno);
            continue;
        }
        uint16_t ambient_light = (buffer[0] << 8) | buffer[1];
        if (ambient_light > 0x7FFF) {
            fprintf(stderr, "Ambient light value out of range: %04x\n", ambient_light);
            continue;
        }

        if (ioctl(fd, I2C_READ, SI1182_PROXIMITY_REG) < 0 ||
            read(fd, buffer, 2) != 2) {
            handle_i2c_error(errno);
            continue;
        }
        uint16_t proximity = (buffer[0] << 8) | buffer[1];
        if (proximity > 0x7FFF) {
            fprintf(stderr, "Proximity value out of range: %04x\n", proximity);
            continue;
        }

        // Convert ambient light to lux
        float lux = ambient_light * 0.1;

        // Log data
        fprintf(log_file, "%s,%f,%04x,%04x\n", ctime(&timestamp), lux, proximity, ambient_light);

        // Print to stdout
        printf("Timestamp: %s, Lux: %.1f, Proximity: %04x\n",
               ctime(&timestamp), lux, proximity);

        // Sleep for 100ms
        usleep(100000);
    }

    // Close resources on exit
    close_resources_and_exit(EXIT_SUCCESS);

    return 0;
}

