#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define the I2C address of the Si1145 sensor
#define SI1145_ADDRESS 0x60

// Define the registers and their initialisation values
#define HW_KEY_REG 0x07
#define MEAS_RATE_REG 0x06
#define INT_REG 0x1A
#define ALS_VIS_IR_ADC_COUNTER_REG 0x21
#define ALS_VIS_ADC_GAIN_REG 0x24
#define PS_ADC_COUNTER_REG 0x22
#define PS_LED21_REG 0x0C
#define PS_LED3_REG 0x0F
#define PS_ADC_MISC_REG 0x11
#define PS_ADC_GAIN_REG 0x0D
#define COMMAND_REG 0x80

#define PS1_DATA0_REG 0x16
#define PS1_DATA1_REG 0x17

// Function prototypes
void initialise_sensor(struct pigpiod *pig);
void read_proximity(struct pigpiod *pig);
void handle_interrupts(int signum);
void cleanup();

// Main function
int main() {
    struct pigpiod *pig;
    int i2c_fd = -1;
    char proximity_log_path[] = "proximity_log.txt";
    time_t now;
    FILE *proximity_log = NULL;

    // Initialize pigpio
    if ((pig = gpioInitialise()) == NULL) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", gpioGetError(pig));
        return EXIT_FAILURE;
    }

    // Open I2C device
    if ((i2c_fd = i2cOpen(pig, SI1145_ADDRESS)) == -1) {
        fprintf(stderr, "Failed to open I2C device: %s\n", i2cGetErrorString(i2c_fd));
        gpioTerminate(pig);
        return EXIT_FAILURE;
    }

    // Install signal handlers
    signal(SIGINT, handle_interrupts);
    signal(SIGTERM, handle_interrupts);

    // Open proximity log file
    proximity_log = fopen(proximity_log_path, "a+");
    if (proximity_log == NULL) {
        fprintf(stderr, "Failed to open proximity log file: %s\n", strerror(errno));
        i2cClose(i2c_fd);
        gpioTerminate(pig);
        return EXIT_FAILURE;
    }

    // Initial sensor setup
    initialise_sensor(pig);

    // Main loop
    while (1) {
        read_proximity(pig);
        now = time(NULL);
        fprintf(proximity_log, "%s, Proximity: %u\n", ctime(&now), (unsigned int)(((unsigned char)read_proximity(pig)[0]) << 8 | read_proximity(pig)[1]));
        fflush(proximity_log);
    }

    // Clean up on exit
    cleanup();

    return EXIT_SUCCESS;
}

// Function to initialise the Si1145 sensor
void initialise_sensor(struct pigpiod *pig) {
    int ret;

    // Write to hardware key register
    ret = i2cWriteByteData(i2c_fd, SI1145_ADDRESS, HW_KEY_REG, 0x03);
    if (ret < 0) {
        fprintf(proximity_log, "Failed to write to HW_KEY_REG: %s\n", i2cGetErrorString(i2c_fd));
        return;
    }

    // Write to MEAS_RATE register
    ret = i2cWriteByteData(i2c_fd, SI1145_ADDRESS, MEAS_RATE_REG, 0x02);
    if (ret < 0) {
        fprintf(proximity_log, "Failed to write to MEAS_RATE_REG: %s\n", i2cGetErrorString(i2c_fd));
        return;
    }

    // Write to INT register
    ret = i2cWriteByteData(i2c_fd, SI1145_ADDRESS, INT_REG, 0x00);
    if (ret < 0) {
        fprintf(proximity_log, "Failed to write to INT_REG: %s\n", i2cGetErrorString(i2c_fd));
        return;
    }

    // Write to ALS_VIS_IR_ADC_COUNTER register
    ret = i2cWriteByteData(i2c_fd, SI1145_ADDRESS, ALS_VIS_IR_ADC_COUNTER_REG, 0x0B);
    if (ret < 0) {
        fprintf(proximity_log, "Failed to write to ALS_VIS_IR_ADC_COUNTER_REG: %s\n", i2cGetErrorString(i2c_fd));
        return;
    }

    // Write to ALS_VIS_ADC_GAIN register
    ret = i2cWriteByteData(i2c_fd, SI1145_ADDRESS, ALS_VIS_ADC_GAIN_REG, 0x00);
    if (ret < 0) {
        fprintf(proximity_log, "Failed to write to ALS_VIS_ADC_GAIN_REG: %s\n", i2cGetErrorString(i2c_fd));
        return;
    }

    // Write to PS_ADC_COUNTER register
    ret = i2cWriteByteData(i2c_fd, SI1145_ADDRESS, PS_ADC_COUNTER_REG, 0x49);
    if (ret < 0) {
        fprintf(proximity_log, "Failed to write to PS_ADC_COUNTER_REG: %s\n", i2cGetErrorString(i2c_fd));
        return;
    }

    // Write to PS_LED21 register
    ret = i2cWriteByteData(i2c_fd, SI1145_ADDRESS, PS_LED21_REG, 0x03);
    if (ret < 0) {
        fprintf(proximity_log, "Failed to write to PS_LED21_REG: %s\n", i2cGetErrorString(i2c_fd));
        return;
    }

    // Write to PS_LED3 register
    ret = i2cWriteByteData(i2c_fd, SI1145_ADDRESS, PS_LED3_REG, 0x0F);
    if (ret < 0) {
        fprintf(proximity_log, "Failed to write to PS_LED3_REG: %s\n", i2cGetErrorString(i2c_fd));
        return;
    }

    // Write to PS_ADC_MISC register
    ret = i2cWriteByteData(i2c_fd, SI1145_ADDRESS, PS_ADC_MISC_REG, 0x03);
    if (ret < 0) {
        fprintf(proximity_log, "Failed to write to PS_ADC_MISC_REG: %s\n", i2cGetErrorString(i2c_fd));
        return;
    }

    // Write to PS_ADC_GAIN register
    ret = i2cWriteByteData(i2c_fd, SI1145_ADDRESS, PS_ADC_GAIN_REG, 0x07);
    if (ret < 0) {
        fprintf(proximity_log, "Failed to write to PS_ADC_GAIN_REG: %s\n", i2cGetErrorString(i2c_fd));
        return;
    }

    // Write to COMMAND register
    ret = i2cWriteByteData(i2c_fd, SI1145_ADDRESS, COMMAND_REG, 0x03);
    if (ret < 0) {
        fprintf(proximity_log, "Failed to write to COMMAND_REG: %s\n", i2cGetErrorString(i2c_fd));
        return;
    }

