    ret = i2cWriteByteData(i2c_fd, SI1145_ADDRESS, INT_REG, 0x00);
    if (ret < 0) {
        fprintf(proximity_log, "Failed to write to INT_REG: %s\n", i2cGetErrorString(i2c_fd));
        return;
    }

    // Write to ALS_VIS_IR_ADC_COUNTER register
    ret = i2cWriteByteData(i2c_fd, SI1145_ADDRESS, ALS_VIS_IR_ADC_COUNTER_REG, 0x0B);
