// Function prototypes
void setupHC_SR04();
void measureDistance();
void handleInterrupt(int rising, int falling);
void buzzerControl(int distance);
void cleanup();

// Global variables
pigpio *pi;
volatile uint32_t startTime = 0;
volatile uint32_t stopTime = 0;
int distanceBelowThreshold = 0;

// Interrupt handler for HC-SR04 echo pin
void interruptHandler(void *data) {
    int risingEdge = (gpioRead(GPIO_ECHO) & (1 << GPIO_ECHO_RISING));
    int fallingEdge = (gpioRead(GPIO_ECHO) & (1 << GPIO_ECHO_FALLING));

    if (risingEdge) {
        startTime = pi->getTime();
    }
    if (fallingEdge) {
        stopTime = pi->getTime();
    }

    measureDistance();
}

// Main function
int main() {
    // Initialize pigpio and check for errors
    pi = pigpioOpen();
    if (pi == NULL) {
        fprintf(stderr, "Failed to open pigpio: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }

    // Set up GPIO pins
    setupHC_SR04();

    // Set up interrupt for echo pin
    gpioSetAlertFuncEx(GPIO_ECHO, GPIO_RISING, fallingEdge, interruptHandler, NULL);

    // Signal handler for Ctrl+C
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Main loop
    while (1) {
        measureDistance();
        buzzerControl(distanceBelowThreshold);

        // Print distance every second
        if (pi->getTime() - startTime >= 1000000) {
            printf("Distance: %.2f cm\n", (double)(stopTime - startTime) * 0.0343 / 2.0);
            distanceBelowThreshold = (stopTime - startTime) * 0.0343 / 2.0 < 20.0;
        }

        // Delay to avoid excessive CPU usage
        gpioDelay(100);
    }

    // Clean up resources
    cleanup();

    return 0;
}

// Function to set up HC-SR04
void setupHC_SR04() {
    // Trigger pin as output
    if (gpioSetMode(GPIO_TRIGGER, GPIO_OUTPUT_OUPUT) == -1) {
        fprintf(stderr, "Failed to set GPIO_TRIGGER to output: %s\n", pigpioError());
        return;
    }

    // Echo pin as input with rising/falling edge alert
    if (gpioSetAlertFuncEx(GPIO_ECHO, GPIO_RISING, NULL, NULL) == -1) {
        fprintf(stderr, "Failed to set GPIO_ECHO alert: %s\n", pigpioError());
        return;
    }

    // Buzzer pin as output
    if (gpioSetMode(GPIO_Buzzer, GPIO_OUTPUT_OUPUT) == -1) {
        fprintf(stderr, "Failed to set GPIO_Buzzer to output: %s\n", pigpioError());
        return;
    }
}

// Function to measure distance
