    // Generate 10 us trigger pulse
    gpioWrite(GPIO_TRIGGER, 1);
    gpioDelay(10);
    gpioWrite(GPIO_TRIGGER, 0);

    // Wait for echo
    while (gpioRead(GPIO_ECHO) == 0) {
        // No-op
    }
}

