void buzzerControl(int distance) {
    if (distance < 20) {
        gpioWrite(GPIO_Buzzer, 1);
    } else {
        gpioWrite(GPIO_Buzzer, 0);
    }
}

// Function to clean up resources and exit
void cleanup() {
    // Close pigpio and release resources
    pigpioClose(pi);
    pi = NULL;
}

