#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18
#define SERVO_MIN_PULSE 500 // 0 degrees
#define SERVO_MAX_PULSE 2500 // 180 degrees
#define SERVO_MIN_DISTANCE 200 // cm
#define SERVO_MAX_DISTANCE 110 // cm
#define TIMEOUT_MS 100 // ms for distance measurement and servo update

// Global variables
pigpio *pi;
float distance = -1.0; // Initialized to indicate an error state
int servo_angle = 0; // Degrees

// Function prototypes
void setup_pigpio();
void measure_distance();
void set_servo_angle(float angle);
void handle_signal(int signum);

// Main function
int main() {
    // Initialize global variables
    pi = NULL;
    signal(SIGINT, handle_signal);

    // Attempt to initialize pigpio
    if (pi == NULL) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    // Set up GPIO pins
    if (piGPIOInit(TRIGGER_PIN, GPIO_OUTPUT_PP) < 0 || piGPIOInit(ECHO_PIN, GPIO_INPUT_PP) < 0) {
        fprintf(stderr, "Failed to initialize GPIO pins\n");
        piGPIOFree(pi);
        return EXIT_FAILURE;
    }

    // Setup servo pin as output
    if (piGPIOInit(SERVO_PIN, GPIO_OUTPUT_PP) < 0) {
        fprintf(stderr, "Failed to initialize servo pin\n");
        piGPIOFree(pi);
        return EXIT_FAILURE;
    }

    // Start continuous loop
    while (1) {
        measure_distance();
        set_servo_angle(distance);
        usleep(TIMEOUT_MS * 1000); // Wait for 100 ms
    }

    // Clean up on SIGINT
    handle_signal(SIGINT);

    // Graceful exit
    piGPIOFree(pi);
    piFree(pi);
    return EXIT_SUCCESS;
}

// Function to initialize pigpio
void setup_pigpio() {
    pi = pigpioOpen();
    if (pi == NULL) {
        fprintf(stderr, "Failed to open pigpio\n");
        exit(EXIT_FAILURE);
    }
}

// Function to measure distance using HC-SR04
void measure_distance() {
    // Set trigger pin high and low
    piGPIOWrite(TRIGGER_PIN, GPIO_HIGH);
    piGPIODelay(2);
    piGPIOWrite(TRIGGER_PIN, GPIO_LOW);

    // Start timer
    float start_time = piPicoTime();

    // Wait for echo pin to go high
    while (piGPIORead(ECHO_PIN) == GPIO_LOW) {
        // Check for timeout
        if (piPicoTime() - start_time > TIMEOUT_MS) {
            distance = -1.0; // Return error distance
            break;
        }
    }

    // Stop timer
    float end_time = piPicoTime();
    float duration = end_time - start_time;

    // Calculate distance
    int distance_us = duration * (340 / 2); // Speed of sound in air (approx. 340 m/s)
    distance = (distance_us / 29) * 0.01; // Convert microseconds to cm

    // Handle invalid distance (e.g., due to echo timeout)
    if (distance < 0) {
        distance = -1.0;
    }
}

// Function to set servo angle based on distance
void set_servo_angle(float angle) {
    int pulse_width = SERVO_MIN_PULSE + (SERVO_MAX_PULSE - SERVO_MIN_PULSE) * (angle - SERVO_MIN_DISTANCE / (SERVO_MAX_DISTANCE - SERVO_MIN_DISTANCE));

    // Ensure pulse width is within valid range
    if (pulse_width < SERVO_MIN_PULSE || pulse_width > SERVO_MAX_PULSE) {
        pulse_width = SERVO_MIN_PULSE; // Clamp to minimum if too low, maximum if too high
    }

    // Set servo pulse width
    piGPIOWrite(SERVO_PIN, GPIO_HIGH);
    piGPIODelay(pulse_width);
    piGPIOWrite(SERVO_PIN, GPIO_LOW);
}

// Signal handler for SIGINT
void handle_signal(int signum) {
    // Stop the servo
    set_servo_angle(0.0);

    // Clean up pigpio
    piGPIOFree(pi);
    piFree(pi);

    // Exit the program
    exit(EXIT_SUCCESS);
}

