#define VL53L1X_REG_MODEL_ID 0x010F
#define VL53L1X_REG_DISTANCE_HIGH 0x101
#define DETECTION_THRESHOLD 200
#define HYSTERESIS 50

FILE *logFile;
pigpio *pi;

void open_log_file() {
    const char *logFileName = "gate_log.txt";
    logFile = fopen(logFileName, "a+");
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", logFileName);
        exit(EXIT_FAILURE);
    }
}

void close_log_file() {
    if (logFile != NULL) {
        fclose(logFile);
        logFile = NULL;
    }
}

void open_pigpio() {
    pi = pigpioOpen();
    if (pi == NULL) {
        fprintf(stderr, "Failed to open pigpio: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }
}

void close_pigpio() {
    if (pi != NULL) {
        pigpioClose(pi);
        pi = NULL;
    }
}

void i2c_init() {
    if (pigpioI2CInit(pi, I2C_BUS) == 0) {
        fprintf(stderr, "Failed to initialize I2C bus %d: %s\n", I2C_BUS, pigpioI2CError());
        exit(EXIT_FAILURE);
    }
}

void i2c_release() {
    pigpioI2CRelease();
}

void write_i2c(uint8_t reg, uint8_t data) {
    if (pigpioI2CWrite(pi, I2C_BUS, VL53L1X_ADDR, reg, data) == 0) {
        fprintf(stderr, "Failed to write to I2C: %s\n", pigpioI2CError());
        exit(EXIT_FAILURE);
    }
}

void read_i2c(uint8_t reg, uint8_t *data) {
    if (pigpioI2CRead(pi, I2C_BUS, VL53L1X_ADDR, reg, data) == 0) {
        fprintf(stderr, "Failed to read from I2C: %s\n", pigpioI2CError());
        exit(EXIT_FAILURE);
    }
}

void servo_control(uint16_t pulse_width) {
    if (pigpioPWMWrite(pi, SERVO_PIN, pulse_width) == 0) {
        fprintf(stderr, "Failed to write servo PWM: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }
}

void detect_object() {
    uint8_t model_id;
    uint16_t distance;

    // Read model ID to verify sensor
    if (read_i2c(VL53L1X_REG_MODEL_ID, &model_id) == 0) {
        fprintf(stderr, "Failed to read model ID: %s\n", pigpioI2CError());
        exit(EXIT_FAILURE);
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Incorrect model ID detected: 0x%X\n", model_id);
        exit(EXIT_FAILURE);
    }

    // Set timing budget and start ranging
    if (write_i2c(VL53L1X_REG_timingBudget, 0x0F) == 0 ||
        write_i2c(VL53L1X_REG_startRanging, 0x01) == 0) {
        fprintf(stderr, "Failed to configure sensor: %s\n", pigpioI2CError());
        exit(EXIT_FAILURE);
    }

    // Read distance
    if (read_i2c(VL53L1X_REG_DISTANCE_HIGH, &distance) == 0) {
        fprintf(stderr, "Failed to read distance: %s\n", pigpioI2CError());
        exit(EXIT_FAILURE);
    }

    // Check distance and control servo
    if (distance < DETECTION_THRESHOLD) {
        servo_control(2000); // Open gate
        fprintf(logFile, "Object detected at %d mm, gate opened at %s\n",
                distance, ctime(&time(NULL)));
    } else if (distance > DETECTION_THRESHOLD + HYSTERESIS) {
        servo_control(1000); // Close gate
        fprintf(logFile, "Object moved away, gate closed at %s\n",
                ctime(&time(NULL)));
    }
}

int main() {
    open_log_file();
    open_pigpio();
    i2c_init();

    while (1) {
        detect_object();
        sleep(1); // Adjust sleep time as needed
    }

    close_pigpio();
    i2c_release();
    close_log_file();

    return 0;
}

