#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18
#define MAX_DISTANCE_CM 400
#define MIN_DISTANCE_CM 2
#define SERVO_MIN_PULSE 500 // 0 degrees
#define SERVO_MAX_PULSE 2500 // 180 degrees
#define PULSE_TO_DEGREES 10 // 10 us trigger pulse to degrees conversion
#define SOUND_SPEED_CM_PER_MS 343
#define TIMEOUT_MS 50 // 50 ms timeout

// Function prototypes
void initialize_pigpio();
void measure_distance();
void set_servo_angle(float distance);
void handle_signal(int signum);

int main() {
    // Initialize pigpio
    if (initialize_pigpio() == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }

    // Signal handler for Ctrl+C
    signal(SIGINT, handle_signal);

    while (1) {
        measure_distance();
        set_servo_angle(measured_distance);
        printf("Distance: %.2f cm, Angle: %.1f degrees\n", measured_distance, (measured_distance * PULSE_TO_DEGREES / MAX_DISTANCE_CM));
        usleep(100000); // 100 ms delay
    }

    // Clean shutdown
    pigpio_stop();
    pigpio_free();

    return 0;
}

// Function to initialize pigpio
int initialize_pigpio() {
    int rc = pigpio_open(PIGPIO_DEFAULT_PORT, 0);
    if (rc == -1) {
        fprintf(stderr, "Failed to open pigpio: %s\n", pigpio_error());
        return -1;
    }

    return rc;
}

// Function to measure distance using HC-SR04
void measure_distance() {
    int rc = pigpio_write(TRIGGER_PIN, 1); // Trigger pulse
    if (rc == -1) {
        fprintf(stderr, "Failed to trigger HC-SR04: %s\n", pigpio_error());
        return;
    }

    rc = pigpio_wait_for_edge(ECHO_PIN, pigpio_RISING, TIMEOUT_MS);
    if (rc == -1) {
        fprintf(stderr, "Timeout waiting for echo from HC-SR04: %s\n", pigpio_error());
        return;
    }

    rc = pigpio_read_us(ECHO_PIN);
    if (rc == -1) {
        fprintf(stderr, "Failed to read echo pulse width: %s\n", pigpio_error());
        return;
    }

    uint32_t pulse_duration_us = rc;
    if (pulse_duration_us == 0) {
        // Division by zero protection
        return;
    }

    float distance_cm = (pulse_duration_us * SOUND_SPEED_CM_PER_MS * 0.0343) / 2;
    if (distance_cm < MIN_DISTANCE_CM) {
        distance_cm = MIN_DISTANCE_CM; // Map below 20 cm to 0 degrees
    } else if (distance_cm > MAX_DISTANCE_CM) {
        distance_cm = MAX_DISTANCE_CM; // Map above 200 cm to 180 degrees
    }

    set_servo_angle(distance_cm);
}

// Function to set the servo angle based on distance
void set_servo_angle(float distance) {
    float angle = (distance * PULSE_TO_DEGREES / MAX_DISTANCE_CM) - 90; // Linear mapping to degrees
    if (angle < 0) {
        angle = 0; // Ensure angle is non-negative
    } else if (angle > 180) {
        angle = 180; // Ensure angle does not exceed 180 degrees
    }

    int rc = pigpio_servo(SERVO_PIN, (int)angle);
    if (rc == -1) {
        fprintf(stderr, "Failed to set servo angle: %s\n", pigpio_error());
    }
}

// Signal handler for SIGINT (Ctrl+C)
void handle_signal(int signum) {
    pigpio_servo(SERVO_PIN, 0); // Stop the servo
    pigpio_close(); // Close pigpio cleanly
    exit(EXIT_SUCCESS); // Exit with success
}

