#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>

// Define the conversion factors for temperature and humidity
#define TEMP_CONVERSION_FACTOR 175.72
#define HUMIDITY_CONVERSION_FACTOR 125.0

// I2C address and registers for Si7005
#define SI7005_ADDRESS 0x40
#define CONFIG_REGISTER 0x03
#define TEMPERATURE_REGISTER 0x01
#define HUMIDITY_REGISTER 0x02

// Time interval in seconds for logging readings
#define LOG_INTERVAL 2

// Function prototypes
void initialize_pigpio();
void initialize_i2c();
void read_sensors(struct pigpio *gp);
void handle_signal(int signum);

int main() {
    struct pigpio *gp;
    int i2c_bus = 1;
    int sensor_readings;

    // Initialize pigpio
    initialize_pigpio();

    // Initialize I2C
    initialize_i2c(i2c_bus);

    // Main loop
    while (1) {
        // Wait for the logging interval
        sleep(LOG_INTERVAL);

        // Read sensors
        sensor_readings = read_sensors(gp);

        // Print readings
        printf("Temperature: %.1f°C, Humidity: %.1f%%\n", (sensor_readings.temperature * TEMP_CONVERSION_FACTOR) / 65536.0 - 46.85, (sensor_readings.humidity * HUMIDITY_CONVERSION_FACTOR) / 65536.0 - 6.0);

        // Handle SIGINT
        if (signal(SIGINT, handle_signal) == SIG_ERR) {
            perror("Failed to install SIGINT handler");
            exit(EXIT_FAILURE);
        }
    }

    // Clean up on exit
    close_i2c(i2c_bus);
    pigpio_free(gp);

    return 0;
}

// Function to initialize pigpio
void initialize_pigpio() {
    if (pigpio_init() == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_errstr());
        exit(EXIT_FAILURE);
    }
}

// Function to initialize I2C on the specified bus
void initialize_i2c(int bus) {
    if (gpiod_i2c_open(bus) == -1) {
        fprintf(stderr, "Failed to open I2C bus %d: %s\n", bus, gpiod_error_string());
        exit(EXIT_FAILURE);
    }
}

// Function to read sensors using pigpio and I2C
int read_sensors(struct pigpio *gp) {
    int config_value_written;
    uint16_t temperature_raw, humidity_raw;

    // Write to CONFIG register to select internal temperature sensor and disable heater
    config_value_written = pigpio_write(gp, SI7005_ADDRESS, CONFIG_REGISTER, 0x00);
    if (config_value_written != 1) {
        fprintf(stderr, "Failed to write to CONFIG register: %s\n", pigpio_errstr());
        close_i2c(gpiod_i2c_get_bus_number());
        return -1;
    }
    usleep(10000); // Wait 10 ms

    // Write to temperature register
    config_value_written = pigpio_write(gp, SI7005_ADDRESS, TEMPERATURE_REGISTER, 0x00);
    if (config_value_written != 1) {
        fprintf(stderr, "Failed to write to temperature register: %s\n", pigpio_errstr());
        close_i2c(gpiod_i2c_get_bus_number());
        return -1;
    }
    usleep(10000); // Wait 10 ms for conversion

    // Read temperature
    temperature_raw = pigpio_read(gp, SI7005_ADDRESS, TEMPERATURE_REGISTER);
    if (temperature_raw == 0) {
        fprintf(stderr, "Failed to read temperature: %s\n", pigpio_errstr());
        close_i2c(gpiod_i2c_get_bus_number());
        return -1;
    }

    // Read humidity
    config_value_written = pigpio_write(gp, SI7005_ADDRESS, HUMIDITY_REGISTER, 0x00);
    if (config_value_written != 1) {
        fprintf(stderr, "Failed to write to humidity register: %s\n", pigpio_errstr());
        close_i2c(gpiod_i2c_get_bus_number());
        return -1;
    }
    usleep(10000); // Wait 10 ms for conversion

    humidity_raw = pigpio_read(gp, SI7005_ADDRESS, HUMIDITY_REGISTER);
    if (humidity_raw == 0) {
        fprintf(stderr, "Failed to read humidity: %s\n", pigpio_errstr());
        close_i2c(gpiod_i2c_get_bus_number());
        return -1;
    }

    // Convert readings
    float temperature = (TEMP_CONVERSION_FACTOR * temperature_raw) / 65536.0 - 46.85;
    float humidity = (HUMIDITY_CONVERSION_FACTOR * humidity_raw) / 65536.0 - 6.0;

    return 0;
}

// Signal handler for SIGINT
void handle_signal(int signum) {
    fprintf(stderr, "SIGINT received, shutting down gracefully...\n");
    close_i2c(gpiod_i2c_get_bus_number());
    pigpio_free(gp);
    exit(EXIT_SUCCESS);
}

