#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>

// Define the I2C address and registers
#define I2C_ADDRESS 0x68
#define WHO_AM_I_REG 0x00
#define PWR_MGMT_1_REG 0x6B
#define SAMPLE_RATE_DIVIDER_REG 0x19
#define ACCEL_CONFIG_REG 0x1C
#define GYRO_CONFIG_REG 0x1B
#define DATA_REG 0x3B

// Register values for desired configurations
#define ACCEL_CONFIG_VALUE 0x08 // ±2 g range
#define GYRO_CONFIG_VALUE 0x01 // ±250 deg/s range

// Function prototypes
void handleSIGINT(int signum);
void handleSIGTERM(int signum);
void i2cReadI2CBlockData(pigpio *pi, uint8_t address, uint8_t reg, uint8_t *data, size_t len);
void parseData(const uint8_t *data, float *accelX, float *accelY, float *accelZ, float *gyroX, float *gyroY, float *gyroZ, float *temp);

int main() {
    // Initialize pigpio
    pigpio *pi = NULL;
    if ((pi = pigpio_open()) == NULL) {
        fprintf(stderr, "Failed to open pigpio\n");
        return EXIT_FAILURE;
    }

    // Register signal handlers
    signal(SIGINT, handleSIGINT);
    signal(SIGTERM, handleSIGTERM);

    // Check if the sensor is present
    if (i2cReadI2CByte(pi, I2C_ADDRESS, WHO_AM_I_REG) != 0x68) {
        fprintf(stderr, "Sensor not found (WHO_AM_I: 0x%X)\n", i2cReadI2CByte(pi, I2C_ADDRESS, WHO_AM_I_REG));
        return EXIT_FAILURE;
    }

    // Reset the sensor
    if (i2cWriteI2CByte(pi, I2C_ADDRESS, PWR_MGMT_1_REG, 0x06) != 1) {
        fprintf(stderr, "Failed to reset sensor (PWR_MGMT_1: 0x06)\n");
        return EXIT_FAILURE;
    }
    sleep(1); // Wait for stabilization

    // Clear the sleep bit
    if (i2cWriteI2CByte(pi, I2C_ADDRESS, PWR_MGMT_1_REG, 0x20) != 1) {
        fprintf(stderr, "Failed to clear sleep bit (PWR_MGMT_1: 0x20)\n");
        return EXIT_FAILURE;
    }

    // Set sample rate divider
    if (i2cWriteI2CByte(pi, I2C_ADDRESS, SAMPLE_RATE_DIVIDER_REG, 0x07) != 1) {
        fprintf(stderr, "Failed to set sample rate divider (0x07)\n");
        return EXIT_FAILURE;
    }

    // Configure accelerometer and gyroscope
    if (i2cWriteI2CByte(pi, I2C_ADDRESS, ACCEL_CONFIG_REG, ACCEL_CONFIG_VALUE) != 1) {
        fprintf(stderr, "Failed to configure accelerometer (ACCEL_CONFIG: 0x08)\n");
        return EXIT_FAILURE;
    }
    if (i2cWriteI2CByte(pi, I2C_ADDRESS, GYRO_CONFIG_REG, GYRO_CONFIG_VALUE) != 1) {
        fprintf(stderr, "Failed to configure gyroscope (GYRO_CONFIG: 0x01)\n");
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Read data
        uint8_t data[14];
        if (i2cReadI2CBlockData(pi, I2C_ADDRESS, DATA_REG, data, 14) != 14) {
            fprintf(stderr, "Failed to read data from sensor\n");
            break; // Exit loop on critical error
        }

        // Parse data
        float accelX, accelY, accelZ;
        float gyroX, gyroY, gyroZ;
        float temp;
        parseData(data, &accelX, &accelY, &accelZ, &gyroX, &gyroY, &gyroZ, &temp);

        // Print data
        printf("Accelerometer: X=%f, Y=%f, Z=%f\n", accelX, accelY, accelZ);
        printf("Gyroscope: X=%f, Y=%f, Z=%f\n", gyroX, gyroY, gyroZ);
        printf("Temperature: %f°C\n", temp);

        // Sleep for 100 ms
        sleep(0.1);
    }

    // Clean-up
    i2cClose(pi);
    gpioTerminate(pi);

    // Shutdown message
    printf("Shutting down...\n");

    // Exit
    return EXIT_SUCCESS;
}

// Handle SIGINT and SIGTERM
void handleSIGINT(int signum) {
    printf("SIGINT received, shutting down...\n");
    exit(0);
}

void handleSIGTERM(int signum) {
    printf("SIGTERM received, shutting down...\n");
    exit(0);
}

// Function to read a byte from a specified register
int i2cReadI2CByte(pigpio *pi, uint8_t address, uint8_t reg) {
    uint8_t data;
    if (i2cReadI2CByte(pi, address, reg, &data, 1) != 1) {
        fprintf(stderr, "Failed to read I2C byte (reg: 0x%X)\n", reg);
        return 0;
    }
    return data;
}

// Function to write a byte to a specified register
int i2cWriteI2CByte(pigpio *pi, uint8_t address, uint8_t reg, uint8_t value) {
    if (i2cWriteI2CByte(pi, address, reg, &value, 1) != 1) {
        fprintf(stderr, "Failed to write I2C byte (reg: 0x%X, value: 0x%X)\n", reg, value);
        return 0;
    }
    return 1;
}

// Function to read a block of data from a specified register
int i2cReadI2CBlockData(pigpio *pi, uint8_t address, uint8_t reg, uint8_t *data, size_t len) {
    int bytesRead = 0;
    while (len > 0) {
        uint8_t byte;
        if (i2cReadI2CByte(pi, address, reg, &byte, 1) != 1) {
            return bytesRead;
        }
        data[bytesRead++] = byte;
        reg++;
        if (reg >= 0x3F) { // End of data register range
            break;
        }
    }
    return bytesRead;
}

// Function to parse the data block
void parseData(const uint8_t *data, float *accelX, float *accelY, float *accelZ, float *gyroX, float *gyroY, float *gyroZ, float *temp) {
    // Big-endian conversion for int16 values
    *accelX = (float)((data[0] << 8) | data[1]);
    *accelY = (float)((data[2] << 8) | data[3]);
    *accelZ = (float)((data[4] << 8) | data[5]);

    *gyroX = (float)((data[6] << 8) | data[7]);
    *gyroY = (float)((data[8] << 8) | data[9]);
    *gyroZ = (float)((data[10] << 8) | data[11]);

    *temp = (float)((data[12] << 8) | data[13]); // Temperature in 0.5°C steps
}

