#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>

// Define the polynomial for CRC-8 calculation
#define CRC_POLYNOMIAL 0x31

// Function prototypes
void handleSIGINT(int signum);
void handleSIGTERM(int signum);
int readFromSHT40(uint8_t command, uint8_t address, uint8_t* data, int length);
void validateCRC(uint8_t* data, int length, uint8_t crc);

int main() {
    // Initialize pigpio
    int pi = pigpioOpen();
    if (pi == -1) {
        fprintf(stderr, "Failed to open pigpio: %s\n", pigpioError());
        return EXIT_FAILURE;
    }

    // Register signal handlers
    signal(SIGINT, handleSIGINT);
    signal(SIGTERM, handleSIGTERM);

    // Main loop
    while (1) {
        // Wait for 5 seconds
        usleep(5000000);

        // Attempt to read from the SHT40
        uint8_t command = 0xFD; // High-repeatability measurement command
        uint8_t address = 1; // I2C bus 1
        uint8_t data[6]; // Buffer for 6 bytes of data
        int length = 6;

        if (readFromSHT40(command, address, data, length) < 0) {
            fprintf(stderr, "Error reading from SHT40: %s\n", pigpioError());
            continue; // Re-open the I2C bus for the next attempt
        }

        // Validate CRC
        uint8_t crc1 = data[5];
        uint8_t crc2 = data[6];
        validateCRC(data, length, CRC_POLYNOMIAL);

        // Convert raw values
        int temperature = -45 + 175 * (data[1] / 65535);
        int humidity = -6 + 125 * (data[3] / 65535);

        // Clamp values to 0-100%
        temperature = clamp(temperature, 0, 100);
        humidity = clamp(humidity, 0, 100);

        // Print readings
        printf("Temperature: %.1f°C, Humidity: %.1f%%\n", temperature, humidity);

        // Close I2C handle and cleanup
        pigpioClose();
        exit(0);
    }
}

// Function to read from the SHT40
int readFromSHT40(uint8_t command, uint8_t address, uint8_t* data, int length) {
    int ret;
    // Open I2C bus 1
    ret = pigpioI2COpen(1);
    if (ret < 0) {
        fprintf(stderr, "Failed to open I2C bus 1: %s\n", pigpioError());
        return -1;
    }

    // Write command and address to the SHT40
    ret = pigpioI2CWrite(address, command, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to write to SHT40: %s\n", pigpioError());
        pigpioI2CClose(1);
        return -1;
    }

    // Wait at least 10 ms
    usleep(10000);

    // Read 6 bytes
    ret = pigpioI2CRead(address, data, length, 1000);
    if (ret < 0) {
        fprintf(stderr, "Failed to read from SHT40: %s\n", pigpioError());
        pigpioI2CClose(1);
        return -1;
    }

    return 0;
}

// Function to validate CRC
void validateCRC(uint8_t* data, int length, uint8_t crc) {
    uint8_t crcCalculated = crc;

    for (int i = 0; i < length; i++) {
        crcCalculated = (crcCalculated ^ data[i]) & 0x80;
        if (crcCalculated) crcCalculated = crcCalculated << 1;
        crcCalculated = crcCalculated ^ CRC_POLYNOMIAL;
    }

    if (crcCalculated != data[length - 1]) {
        fprintf(stderr, "CRC error detected!\n");
    }
}

// Clamp function
int clamp(int value, int min, int max) {
    return (value >= min && value <= max) ? value : (value < min ? min : max);
}

// Signal handlers
void handleSIGINT(int signum) {
    fprintf(stderr, "SIGINT received, shutting down gracefully...\n");
    pigpioClose();
    exit(0);
}

void handleSIGTERM(int signum) {
    fprintf(stderr, "SIGTERM received, shutting down gracefully...\n");
    pigpioClose();
    exit(0);
}

