// Polynomial for CRC-8 calculation
uint8_t crc8Poly[8] = {0x00, 0x07, 0x04, 0x02, 0x01, 0x08, 0x03, 0x05};

// Function to calculate CRC-8
uint8_t crc8(uint8_t *data, uint8_t len) {
    uint8_t crc = 0xFF;
    for (uint8_t i = 0; i < len; i++) {
        crc = (crc ^ data[i]) & 0x80;
        if (crc) crc = crc ^ crc8Poly[7];
        crc8Poly >>= 1;
        if (!crc8Poly) crc8Poly = crc8Poly[7] << 7;
    }
    return crc;
}

// Main function
int main() {
    // Initialize pigpio
    pigpio *pi = NULL;
    if (pigpio_open(PIGPIO_ID) == -1) {
        fprintf(stderr, "Failed to open pigpio: %s\n", pigpio_error());
        return EXIT_FAILURE;
    }
    pi = pigpio_new();
    if (!pi) {
        fprintf(stderr, "Failed to create pigpio instance: %s\n", pigpio_error());
        pigpio_close(pi);
        return EXIT_FAILURE;
    }

    // Open the sensor I2C device
    if (gpiod_i2c_open(1) == -1) {
        fprintf(stderr, "Failed to open I2C bus 1: %s\n", gpiod_error());
        pigpio_close(pi);
        return EXIT_FAILURE;
    }

    // Write command to start continuous measurement
    if (gpiod_i2c_write(1, SENSOR_ADDR, CMD_CONT_MEAS, 1) == -1) {
        fprintf(stderr, "Failed to write command to sensor: %s\n", gpiod_error());
        gpiod_i2c_close(1);
        pigpio_close(pi);
        return EXIT_FAILURE;
    }

    // Wait for 1 ms
    usleep(1000);

    // Poll the sensor every second
    while (1) {
        // Read data from the sensor
        uint8_t data[9] = {0};
        if (gpiod_i2c_read(1, SENSOR_ADDR, 9, data) == -1) {
            fprintf(stderr, "Failed to read from sensor: %s\n", gpiod_error());
            break; // Exit on bus error
        }

        // Calculate CRC-8 for data
        uint8_t crc = crc8(data, 8);
        if (data[8] != crc) {
            fprintf(stderr, "CRC error in sensor data\n");
            break; // Exit on CRC error
        }

        // Extract pressure and temperature
        uint16_t pressure = (data[0] << 8) | data[1];
        uint16_t temperature = (data[2] << 8) | data[3];

        // Convert raw values to actual measurements
        float pressurePa = pressure * pressureScaleFactor / 65535.0;
        float temperatureC = temperature * temperatureScaleFactor / 65535.0;

        // Format timestamp and data for CSV
        char timestamp[50];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.000Z", localtime(&now));
        char line[256];
        sprintf(line, "%s,%f,%f", timestamp, pressurePa, temperatureC);

        // Write to CSV file
        FILE *file = fopen("pressure_log.csv", "a");
        if (!file) {
            fprintf(stderr, "Failed to open or append to CSV file: %s\n", strerror(errno));
            break;
        }
        fprintf(file, "%s\n", line);
        fclose(file);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up resources
    gpiod_i2c_close(1);
    pigpio_close(pi);

    return EXIT_SUCCESS;
}
