#define CRC_INIT_VALUE 0xFF

// Temperature and humidity conversion factors
#define TEMP_CONVERSION_FACTOR 175
#define HUMIDITY_CONVERSION_FACTOR 65535

// I2C file descriptor
int i2c_fd = -1;

// Function to calculate CRC-8
uint8_t crc8(uint8_t *buf, uint16_t len) {
    uint8_t crc = CRC_INIT_VALUE;
    for (uint16_t i = 0; i < len; i++) {
        crc = (crc ^ buf[i]) & 0xFF;
        for (uint8_t bit = 0; bit < 8; bit++) {
            if ((crc & 0x80) != 0) {
                crc <<= 1;
                crc ^= CRC_POLYNOMIAL;
            }
            crc <<= 1;
        }
    }
    return crc;
}

// Function to convert raw temperature and humidity
float convertTemperature(uint16_t raw) {
    return (-45 + (TEMP_CONVERSION_FACTOR * raw) / 65535.0);
}

float convertHumidity(uint16_t raw) {
    return (100.0 * raw / 65535);
}

void handleSIGINT(int signum) {
