        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Open log file
    FILE *logfile = fopen("sht40_log.txt", "a+");
    if (logfile == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void writeMeasurementCommand(uint8_t *command) {
    if (write(i2c_fd, command, sizeof(*command)) != sizeof(*command)) {
        perror("Failed to write measurement command");
        close(i2c_fd);
        fclose(logfile);
        exit(EXIT_FAILURE);
    }
}

void readMeasurementResponse(uint8_t *response, uint16_t maxBytes) {
    if (read(i2c_fd, response, maxBytes) != maxBytes) {
        perror("Failed to read measurement response");
        close(i2c_fd);
        fclose(logfile);
        exit(EXIT_FAILURE);
    }

    // Check CRC
    uint8_t crcReceived = response[4];
    uint8_t crcCalculated = crc8(response, 6);
    if (crcReceived != crcCalculated) {
        fprintf(logfile, "CRC error in measurement response, retrying...\n");
        return;
    }
}

void closeResources() {
    // Close I2C file descriptor and log file
    close(i2c_fd);
    fclose(logfile);
}

int main() {
