    uint8_t command[2] = {SHT40_CMD_READ_HUMIDITY_AND_TEMPERATURE, 0};
    uint16_t temperatureRaw, humidityRaw;
    uint8_t response[6];
    uint8_t crc;
    struct timespec timestamp;
    time_t now;

    // Open I2C and log file
    openI2CAndLogFile();

    while (1) {
        // Wait for 5 seconds
        struct timespec timeout = {5, 0};
        clock_gettime(CLOCK_REALTIME, &now);
        while ((clock_gettime(CLOCK_REALTIME, &timestamp) - now) < timeout.tv_nsec / 1000000) {
            struct timespec remaining = {timeout.tv_nsec - (clock_gettime(CLOCK_REALTIME, &timestamp) - now), 0};
            nanosleep(&remaining, NULL);
        }

        // Write measurement command
        writeMeasurementCommand(command);

        // Wait at least 10 ms for measurement to complete
        usleep(10000);

        // Read measurement response
        readMeasurementResponse(response, 6);

        // Convert and validate readings
        temperatureRaw = response[0] | (response[1] << 8);
        humidityRaw = response[2] | (response[3] << 8);

        float temperature = convertTemperature(temperatureRaw);
        float humidity = convertHumidity(humidityRaw);

        // Log the readings with timestamp
        timestamp.tv_sec = now;
        strftime((char *)(&timestamp.tv_nsec), 9, "%Y-%m-%d %H:%M:%S", localtime(&timestamp.tv_sec));
        fprintf(logfile, "Temperature: %.2f°C, Humidity: %.2f%% (%s)\n", temperature, humidity, (char *)(&timestamp.tv_nsec));

        // Check for SIGINT
        if (signal(SIGINT, handleSIGINT) == SIGINT) {
            break;
        }
    }

    // Close resources on exit
    closeResources();

    return 0;
}

