#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>
#include <stdint.h>

#define PIGPIO_IDR 0
#define PIPIO_EC 1
#define SDP31_ADDR 0x28
#define TRIGGER_CMD 0x21
#define READ_CMD 0x96
#define NUM_READ_BYTES 6

volatile sig_atomic_t should_exit = 0;

// Function prototypes
void handleSignals(int signum);
void setupPigpio();
void setupI2C();
void readSensirionSDP31(uint8_t command, uint8_t* data, int len);
void convertAndLog(float pressure_pa, float temperature_c);
void cleanup();

int main() {
    // Setup signal handlers
    signal(SIGINT, handleSignals);
    signal(SIGTERM, handleSignals);

    setupPigpio();
    setupI2C();

    while (!should_exit) {
        // Sample every 100 ms
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        ts.tv_nsec += 100000000; // 100 ms
        clock_nanosleep(CLOCK_REALTIME, &ts, NULL, NULL);

        // Attempt to read from the sensor
        uint8_t command[2] = {TRIGGER_CMD, READ_CMD};
        uint8_t data[NUM_READ_BYTES];
        int attempts = 0;
        do {
            if (pigpio_i2cWriteDevice(PIGPIO_IDR, SDP31_ADDR, command, 2) < 0) {
                fprintf(stderr, "Failed to write to SDP31: %s\n", pigpio_errstr(pigpio_lasterror()));
                attempts++;
                if (attempts > 2) {
                    fprintf(stderr, "Giving up after 3 attempts.\n");
                    break;
                }
                usleep(attempts * 1000 * 1000); // Exponential backoff
            } else {
                if (pigpio_i2cReadDevice(PIGPIO_IDR, SDP31_ADDR, data, NUM_READ_BYTES) < 0) {
                    fprintf(stderr, "Failed to read from SDP31: %s\n", pigpio_errstr(pigpio_lasterror()));
                    attempts++;
                    if (attempts > 2) {
                        fprintf(stderr, "Giving up after 3 attempts.\n");
                        break;
                    }
                    usleep(attempts * 1000 * 1000); // Exponential backoff
                } else {
                    // Process the data
                    float rawPressure = (data[0] << 8) | data[1];
                    float rawTemperature = (data[3] << 8) | data[4];
                    convertAndLog(rawPressure / 60.0, rawTemperature / 200.0);

                    // Reset trigger command
                    command[0] = TRIGGER_CMD;
                    command[1] = READ_CMD;
                    pigpio_i2cWriteDevice(PIGPIO_IDR, SDP31_ADDR, command, 2);
                }
            }
        } while (attempts < 3);

        // Handle SIGINT and SIGTERM
        if (should_exit) {
            cleanup();
            return 0;
        }
    }

    // Cleanup on exit
    cleanup();

    return 0;
}

// Signal handler to set the exit flag
void handleSignals(int signum) {
    should_exit = true;
}

// Setup pigpio
void setupPigpio() {
    if (pigpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_errstr(pigpio_lasterror()));
        exit(EXIT_FAILURE);
    }
}

// Setup I2C
void setupI2C() {
    if (pigpio_i2cOpen(PIGPIO_IDR, PIPIO_EC) < 0) {
        fprintf(stderr, "Failed to open I2C: %s\n", pigpio_errstr(pigpio_lasterror()));
        exit(EXIT_FAILURE);
    }
}

