    if (pigpio_i2cWriteDevice(PIGPIO_IDR, SDP31_ADDR, command, 2) < 0) {
        fprintf(stderr, "Failed to write to SDP31: %s\n", pigpio_errstr(pigpio_lasterror()));
        return;
    }

    if (pigpio_i2cReadDevice(PIGPIO_IDR, SDP31_ADDR, data, len) < 0) {
        fprintf(stderr, "Failed to read from SDP31: %s\n", pigpio_errstr(pigpio_lasterror()));
        return;
    }
}

// Convert and log data
void convertAndLog(float pressure_pa, float temperature_c) {
    char timestamp[50];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    FILE* logFile = fopen("airflow.log", "a");
    if (!logFile) {
        fprintf(stderr, "Failed to open airflow.log for appending: %s\n", strerror(errno));
        return;
    }

    fprintf(logFile, "%s,%f,%f\n", timestamp, pressure_pa, temperature_c);
    fclose(logFile);
}

// Cleanup function
void cleanup() {
    fclose(logFile); // Assuming logFile was opened in main or a function called from main
    pigpio_i2cClose();
    pigpioTerminate();
}

