void read_sensor(int i2c_bus, uint8_t address, int command, float *temperature, float *humidity) {
    int ret;
    pigpio_i2c_write(i2c_bus, address, (uint8_t)command);

    // Poll until measurement is ready
    while (pigpio_i2c_read(i2c_bus, address, 2, NULL, &ret) != 2) {
        if (ret == -1) {
            fprintf(stderr, "I2C read failed: %s\n", pigpio_error());
            return; // Exit on bus error
        } else if (ret == 0) {
            // Measurement not ready yet
            usleep(20000); // Wait up to 20 ms
        }
    }

    // Convert raw values
    *temperature = (175.72 * (uint16_t)pigpio_i2c_read(i2c_bus, address, 0) / 65536.0) - 46.85;
    *humidity = (125.0 * (uint16_t)pigpio_i2c_read(i2c_bus, address, 1) / 65536.0) - 6.0;

    // Clamp humidity to 0-100%
    *humidity = fminf(*humidity, HUMIDITY_MAX);
    *humidity = fmaxf(*humidity, HUMIDITY_MIN);
}

