    // Close I2C handle
    pigpio_i2c_close(1);

    // Terminate pigpio
    pigpio_cleanup();

    // Close any open file
    fclose(stderr);
    fclose(stdout);
}

// Cleanup function
void cleanup() {
    // Close any open file
    fclose(stderr);
    fclose(stdout);

    // Terminate pigpio
    pigpio_cleanup();
}

