#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>

#define SENSOR_ADDR 0x25
#define CMD_MEASURE 0x362F
#define CRC_VALUE 0x55

// Sensor data structure
typedef struct {
    uint8_t pressure[3];
    uint8_t crc_pressure;
    uint8_t temperature[3];
    uint8_t crc_temperature;
    uint8_t scale_factor[3];
    uint8_t crc_scale_factor;
} SensorData;

// Function prototypes
void init_i2c();
void read_sensor(SensorData *data);
void validate_crc(uint8_t word, uint8_t crc);
void write_to_log(const char *message);
void cleanup();

int main() {
    // Initialize I2C
    init_i2c();

    // File descriptor for log file
    int log_fd = fopen("airflow_data.txt", "a+");
    if (log_fd == -1) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    // Loop indefinitely, handling SIGINT and SIGTERM
    while (1) {
        // Read sensor data
        SensorData data;
        read_sensor(&data);

        // Validate CRCs
        validate_crc(data.crc_pressure, data.pressure[2]);
        validate_crc(data.crc_temperature, data.temperature[2]);
        validate_crc(data.crc_scale_factor, data.scale_factor[2]);

        // Convert raw data to Pa and °C
        float pressure_in_pa = (data.pressure[0] + data.pressure[1] << 8 + data.pressure[2] << 16) / data.scale_factor[0];
        float temperature_in_c = (data.temperature[0] + data.temperature[1] << 8 + data.temperature[2] << 16) / 200.0 - 45.0;

        // Write to log file
        char timestamp_str[50];
        time_t now = time(NULL);
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&now));
        write_to_log("%s,%f,%f\n", timestamp_str, pressure_in_pa, temperature_in_c);

        // Sleep for 100 ms
        usleep(100000);

        // Handle SIGINT and SIGTERM
        if (signal(SIGINT, SIG_IGN) == SIG_IGN && signal(SIGTERM, SIG_IGN) == SIG_IGN) {
            // Clean up on signal
            cleanup();
            exit(EXIT_SUCCESS);
        }
    }

    // Cleanup on normal exit
    cleanup();

    return 0;
}

// Function to initialize I2C
void init_i2c() {
    int fd;
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd == -1) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set I2C address and enable I2C interface
    if (ioctl(fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to set I2C address");
        exit(EXIT_FAILURE);
    }

    // Open log file for writing
    log_fd = fopen("airflow_data.txt", "a+");
    if (log_fd == -1) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

// Function to read sensor data
void read_sensor(SensorData *data) {
    uint8_t command[2] = {CMD_MEASURE, 0}; // Command to start measurement
    uint8_t response[9]; // Buffer for 9 bytes response

    // Write command to sensor
    if (write(fd, command, sizeof(command)) != sizeof(command)) {
        perror("Failed to write command to sensor");
        return;
    }

    // Read response from sensor
    if (read(fd, response, sizeof(response)) != sizeof(response)) {
        perror("Failed to read response from sensor");
        return;
    }

    // Populate sensor data structure
    data->pressure = response;
    data->crc_pressure = response[8];
    data->temperature = &response[3];
    data->crc_temperature = response[9];
    data->scale_factor = &response[6];
    data->crc_scale_factor = response[10];
}

// Function to validate CRC
void validate_crc(uint8_t word, uint8_t crc) {
    uint8_t calculated_crc = crc8(word);
    if (calculated_crc != crc) {
        fprintf(stderr, "CRC error in data: %02X (expected %02X)\n", calculated_crc, crc);
        exit(EXIT_FAILURE);
    }
}

// Function to write to log file
void write_to_log(const char *message) {
    if (fwrite(message, strlen(message), 1, log_fd) != 1) {
        perror("Failed to write to log file");
        exit(EXIT_FAILURE);
    }
}

// Function to cleanup resources
void cleanup() {
    // Close I2C file descriptor
    close(fd);

    // Close log file
    fclose(log_fd);
}

// CRC8 function implementation (for simplicity, assuming a basic CRC8 algorithm)
uint8_t crc8(const uint8_t *buf, size_t len) {
    uint8_t crc = 0;
    for (size_t i = 0; i < len; i++) {
        crc ^= buf[i];
        for (int j = 0; j < 8; j++) {
            if ((crc & 1) == 1) {
                crc = (crc >> 1) ^ 0x07;
            } else {
                crc >>= 1;
            }
        }
    }
    return crc;
}

