#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SENSOR_ADDR 0x25
#define CMD_CONT_MEAS 0x362F
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

#define PRESSURE_SCALE_FACTOR 240
#define TEMPERATURE_SCALE 200
#define TEMPERATURE_OFFSET (-45)

// CRC-8 function
uint8_t crc8(uint8_t *buf, uint8_t len, uint8_t polynomial, uint8_t init) {
    uint8_t crc = init;
    for (uint8_t i = 0; i < len; i++) {
        crc ^= *buf++;
        for (uint8_t j = 8; j; j--) {
            if ((crc & 1) == 1) {
                crc = (crc >> 1) ^ polynomial;
            } else {
                crc >>= 1;
            }
        }
    }
    return crc;
}

int main() {
    // Open I2C device
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd == -1) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Prepare buffer for command and response
    uint8_t cmd[3] = {CMD_CONT_MEAS, 0x00, 0x00}; // Command with address and register
    uint8_t response[6];
    uint8_t crc_high, crc_low;

    // Prepare CRC variables
    uint8_t crc_high_temp, crc_low_temp;

    // File descriptor for logging
    int log_fd = fopen("airflow_data.txt", "a+");
    if (log_fd == NULL) {
        perror("Failed to open log file");
        close(fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Write command to sensor
        if (write(fd, cmd, sizeof(cmd)) != sizeof(cmd)) {
            fprintf(log_fd, "Error writing to sensor: %d\n", errno);
            close(log_fd);
            close(fd);
            return EXIT_FAILURE;
        }

        // Read response from sensor
        if (read(fd, response, sizeof(response)) != sizeof(response)) {
            fprintf(log_fd, "Error reading from sensor: %d\n", errno);
            close(log_fd);
            close(fd);
            return EXIT_FAILURE;
        }

        // Calculate CRC for pressure and temperature
        crc_high = crc8(response, 2, CRC_POLYNOMIAL, CRC_INIT);
        crc_low = crc8(response + 2, 2, CRC_POLYNOMIAL, CRC_INIT);

        // Validate CRC
        if (crc_high != response[3] || crc_low != response[4]) {
            fprintf(log_fd, "CRC error detected, data might be corrupted\n");
            continue;
        }

        // Convert raw pressure and temperature
        uint16_t pressure = (response[0] << 8) | response[1];
        float temperature_c = ((response[2] << 8) | response[3]) - TEMPERATURE_OFFSET / TEMPERATURE_SCALE;

        // Convert to Pa and °C
        float pressure_pa = pressure * PRESSURE_SCALE_FACTOR;
        float temperature_celsius = temperature_c;

        // Log data
        char timestamp[50];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_fd, "%s, Pressure: %.2f Pa, Temperature: %.1f °C\n", timestamp, pressure_pa, temperature_celsius);

        // Sleep for at least 1ms between measurements
        usleep(1000);
    }

    // Close resources
    fclose(log_fd);
    close(fd);

    return EXIT_SUCCESS;
}

