#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>

// Define the GPIO pin for the fan and the I2C bus/device address
#define FAN_GPIO 18
#define I2C_BUS 1
#define SENSOR_ADDRESS 0x40

// Constants for Hold Master commands
#define TEMPERATURE_CMD 0xE3
#define HUMIDITY_CMD 0xE5

// Conversion factors
#define TEMPERATURE_CONVERSION 175.72
#define HUMIDITY_CONVERSION 125.0

// Circular buffer size
#define BUFFER_SIZE 60

// Buffer for temperature and humidity readings
struct reading {
    uint16_t temperature;
    uint16_t humidity;
} readings[BUFFER_SIZE];

// Global pigpio handle
pigpio *pi;

// Signal handler for SIGINT
void signal_handler(int signum) {
    printf("Received SIGINT, shutting down...\n");
    // Turn off the fan
    gpioWritePin(FAN_GPIO, 0);

    // Close I2C handle
    if (pi) {
        pigpiodClose(pi);
        pi = NULL;
    }

    // Call gpioTerminate() to clean up GPIO resources
    gpioTerminate();

    // Exit the program
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (pi == NULL) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    // Set up the GPIO pin for the fan
    if (gpioMode(FAN_GPIO, GPIO_OUTPUT_ON_HIGH) == -1) {
        fprintf(stderr, "Failed to set GPIO %d to output\n", FAN_GPIO);
        return EXIT_FAILURE;
    }

    // Set up the I2C bus
    if (pigpioI2COpen(pi, I2C_BUS) == -1) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        return EXIT_FAILURE;
    }

    // Signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Check if the sensor is present
        uint8_t status;
        if (pigpioI2CWrite(pi, I2C_BUS, SENSOR_ADDRESS, TEMPERATURE_CMD, &status) == -1) {
            if (pigpioI2CWrite(pi, I2C_BUS, SENSOR_ADDRESS, HUMIDITY_CMD, &status) == -1) {
                // Retry up to 3 times
                for (int i = 0; i < 3; i++) {
                    if (pigpioI2CWrite(pi, I2C_BUS, SENSOR_ADDRESS, TEMPERATURE_CMD, &status) == -1 ||
