#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdint.h>

#define PIGPIO_ID 0  // Use the default GPIO ID

// SCD40 I2C address and commands
#define SCD40_ADDRESS 0x62
#define START_MEASUREMENT_CMD 0x21B1
#define DATA_READY_FLAG 0xE4B8
#define READ_DATA_CMD 0xEC05
#define CRC_POLYNOMIAL 0x31
#define INIT_CRC 0xFF

// Sensor data structure
typedef struct {
    uint16_t co2_ppm;
    float temperature_c;
    float humidity_pct;
} SensorData;

// Function prototypes
void setup_pigpio();
void setup_i2c(int);
void send_start_periodic_measurement();
void read_scd40_data();
void verify_crc(uint16_t word);
void log_air_quality(SensorData data);
void cleanup();
void handle_signal(int signum);

int main() {
    signal(SIGINT, handle_signal);

    // Setup pigpio
    setup_pigpio();

    // Setup I2C
    setup_i2c(PIGPIO_ID);

    // Main loop
    while (1) {
        send_start_periodic_measurement();
        sleep(5000); // Poll every 5 seconds

        // Check if data is ready
        if (pigpio_i2c_read(PIGPIO_ID, SCD40_ADDRESS, DATA_READY_FLAG) == 0) {
            read_scd40_data();
            log_air_quality(SensorData{.co2_ppm = read_data[0], .temperature_c = (175 * read_data[1]) / (0xFFFF), .humidity_pct = (100 * read_data[2]) / (0xFFFF)});
        } else {
            fprintf(stderr, "Data not ready. Waiting...\n");
        }
    }

    // Cleanup on exit
    cleanup();

    return 0;
}

// Function to setup pigpio
void setup_pigpio() {
    if (pigpio_init(PIGPIO_ID) == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }
}

// Function to setup I2C
void setup_i2c(int gpio_id) {
    if (pigpio_i2c_open(gpio_id) == -1) {
        fprintf(stderr, "Failed to open I2C: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }
}

// Function to send the start periodic measurement command
void send_start_periodic_measurement() {
    if (pigpio_i2c_write(PIGPIO_ID, SCD40_ADDRESS, START_MEASUREMENT_CMD) == -1) {
        fprintf(stderr, "Failed to send start measurement command: %s\n", pigpio_error());
        sleep(1); // Retry after a short delay
        send_start_periodic_measurement();
    }
}

// Function to read data from SCD40
void read_scd40_data() {
    uint8_t buffer[10]; // 9 bytes + 1 for command
    buffer[0] = READ_DATA_CMD;
    if (pigpio_i2c_read(PIGPIO_ID, SCD40_ADDRESS, buffer, sizeof(buffer)) != sizeof(buffer)) {
        fprintf(stderr, "Failed to read data: %s\n", pigpio_error());
        return;
    }

    // Read 6 data bytes and 3 CRC bytes
    uint16_t crc_word = 0;
    for (int i = 1; i < 9; i += 2) {
        crc_word = (crc_word << 8) | buffer[i];
        verify_crc(crc_word);
    }
}

// Function to verify CRC-8 checksum
void verify_crc(uint16_t word) {
    uint8_t crc = (word >> 8) ^ (word & 0xFF) ^ INIT_CRC;
    for (int i = 0; i < 4; ++i) {
        if (crc == 0) break;
        crc = crc << 1;
        if (crc & 0x80) crc ^= CRC_POLYNOMIAL;
    }
    if (crc != 0) {
        fprintf(stderr, "CRC error detected.\n");
        exit(EXIT_FAILURE);
    }
}

// Function to log air quality data
void log_air_quality(SensorData data) {
    FILE *file = fopen("air_quality.log", "a");
    if (!file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        fclose(file);
        exit(EXIT_FAILURE);
    }

    fprintf(file, "%s,%d,%f,%f,%f\n", asctime(localtime()), data.co2_ppm, data.temperature_c, data.humidity_pct);
    fclose(file);
}

// Function to cleanup resources
void cleanup() {
    pigpio_i2c_close(PIGPIO_ID);
    pigpio_cleanup();
}

// Signal handler for SIGINT (Ctrl+C)
void handle_signal(int signum) {
    fprintf(stderr, "Received SIGINT, stopping measurement...\n");
    send_stop_periodic_measurement();
    cleanup();
    exit(EXIT_SUCCESS);
}

// Function to send stop periodic measurement command
void send_stop_periodic_measurement() {
    if (pigpio_i2c_write(PIGPIO_ID, SCD40_ADDRESS, 0x3F86) == -1) {
        fprintf(stderr, "Failed to send stop measurement command: %s\n", pigpio_error());
    }
}

