#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>
#include <stdbool.h>

// Define constants for I2C address and commands
#define SENSIRION_ADDRESS 0x62
#define START_MEASUREMENT_CMD 0x21B1
#define GET_DATA_READY_STATUS_CMD 0xE4B8
#define READ_MEASUREMENT_CMD 0xEC05
#define STOP_MEASUREMENT_CMD 0x3F86

// Sensor data structure
typedef struct {
    uint16_t co2;
    uint16_t temperature;
    uint16_t humidity;
    uint8_t crc1;
    uint8_t crc2;
} SensorReading;

// CRC-8 function
uint8_t crc8(uint8_t *buf, uint8_t len) {
    uint8_t crc = 0xFF;
    for (uint8_t i = 0; i < len; i++) {
        crc ^= buf[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x01) {
                crc = (crc >> 1) ^ 0x07;
            } else {
                crc >>= 1;
            }
        }
    }
    return crc;
}

// Circular buffer for readings
static struct {
    SensorReading readings[20];
    uint8_t head;
    uint8_t tail;
} co2SensorBuffer;

// Global pigpio handle
pigpio *gp;

// Global GPIO 17 pin
int gpio17;

// Signal handlers
void signal_handler(int signum) {
    if (gp != NULL) {
        // Stop sensor, close I2C, release GPIO, and shutdown pigpio
        stop_periodic_measurement();
        close_i2c();
        release_gpio(gpio17);
        pigpio_stop(gp);
        printf("Graceful shutdown triggered.\n");
        exit(0);
    }
}

int main() {
    // Initialize pigpio
    gp = pigpio_open();
    if (gp == NULL) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }

    // Initialize GPIO 17 as output
    gpio17 = pigpio_open(17, GPIO_OUTPUT);
    if (gpio17 == -1) {
        fprintf(stderr, "Failed to initialize GPIO 17.\n");
        pigpio_close(gp);
        return EXIT_FAILURE;
    }

    // Set GPIO 17 as output
    pigpio_write(gp, gpio17, 1);

    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    int i2c_fd = open_i2c(gp, SENSIRION_ADDRESS, I2C_READ | I2C_WRITE);
    if (i2c_fd == -1) {
        fprintf(stderr, "Failed to initialize I2C.\n");
        pigpio_close(gp);
        close(gpio17);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Start periodic measurement
        pigpio_i2c_write(gp, i2c_fd, START_MEASUREMENT_CMD);

        // Poll until data ready
        while (pigpio_i2c_read(gp, i2c_fd, GET_DATA_READY_STATUS_CMD) & 1) {
            // Wait for 5 seconds
            usleep(5000000);
        }

        // Read measurement
        SensorReading reading;
        reading.crc1 = pigpio_i2c_read(gp, i2c_fd, READ_MEASUREMENT_CMD);
        reading.crc2 = pigpio_i2c_read(gp, i2c_fd, READ_MEASUREMENT_CMD + 2);
        reading.co2 = (reading.data[0] << 8) | reading.data[1];
        reading.temperature = (reading.data[2] << 8) | reading.data[3];
        reading.humidity = (reading.data[4] << 8) | reading.data[5];

        // Validate CRC-8
        if (crc8(reading.data, 6) != reading.crc1 || crc8(reading.data + 2, 2) != reading.crc2) {
            fprintf(stderr, "CRC error in sensor reading.\n");
            continue;
        }

        // Log reading to buffer
        co2SensorBuffer.head = (co2SensorBuffer.head + 1) % 20;
        co2SensorBuffer.readings[co2SensorBuffer.head].co2 = reading.co2;
        co2SensorBuffer.readings[co2SensorBuffer.head].temperature = reading.temperature;
        co2SensorBuffer.readings[co2SensorBuffer.head].humidity = reading.humidity;

        // Check CO2 level and control LED
        if (reading.co2 > 1000) {
            pigpio_write(gp, gpio17, 1); // Turn on LED
        } else {
            pigpio_write(gp, gpio17, 0); // Turn off LED
        }

        // Print reading
        printf("CO2: %d ppm, Temp: %d°C, Humidity: %d%%\n", reading.co2, reading.temperature, reading.humidity);

        // Wait for 5 seconds
        usleep(5000000);
    }

    // Stop periodic measurement on exit
    stop_periodic_measurement();

    // Close I2C and release GPIO
    close_i2c();
    release_gpio(gpio17);

    // Shutdown pigpio
    pigpio_close(gp);

    return EXIT_SUCCESS;
}

