    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    int i2c_fd = open_i2c(gp, SENSIRION_ADDRESS, I2C_READ | I2C_WRITE);
    if (i2c_fd == -1) {
        fprintf(stderr, "Failed to initialize I2C.\n");
        pigpio_close(gp);
        close(gpio17);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Start periodic measurement
        pigpio_i2c_write(gp, i2c_fd, START_MEASUREMENT_CMD);

        // Poll until data ready
        while (pigpio_i2c_read(gp, i2c_fd, GET_DATA_READY_STATUS_CMD) & 1) {
            // Wait for 5 seconds
            usleep(5000000);
        }

        // Read measurement
        SensorReading reading;
        reading.crc1 = pigpio_i2c_read(gp, i2c_fd, READ_MEASUREMENT_CMD);
        reading.crc2 = pigpio_i2c_read(gp, i2c_fd, READ_MEASUREMENT_CMD + 2);
        reading.co2 = (reading.data[0] << 8) | reading.data[1];
        reading.temperature = (reading.data[2] << 8) | reading.data[3];
        reading.humidity = (reading.data[4] << 8) | reading.data[5];

        // Validate CRC-8
        if (crc8(reading.data, 6) != reading.crc1 || crc8(reading.data + 2, 2) != reading.crc2) {
            fprintf(stderr, "CRC error in sensor reading.\n");
            continue;
        }

        // Log reading to buffer
        co2SensorBuffer.head = (co2SensorBuffer.head + 1) % 20;
        co2SensorBuffer.readings[co2SensorBuffer.head].co2 = reading.co2;
        co2SensorBuffer.readings[co2SensorBuffer.head].temperature = reading.temperature;
        co2SensorBuffer.readings[co2SensorBuffer.head].humidity = reading.humidity;

        // Check CO2 level and control LED
        if (reading.co2 > 1000) {
            pigpio_write(gp, gpio17, 1); // Turn on LED
        } else {
            pigpio_write(gp, gpio17, 0); // Turn off LED
        }

        // Print reading
        printf("CO2: %d ppm, Temp: %d°C, Humidity: %d%%\n", reading.co2, reading.temperature, reading.humidity);

        // Wait for 5 seconds
        usleep(5000000);
    }

    // Stop periodic measurement on exit
    stop_periodic_measurement();

    // Close I2C and release GPIO
    close_i2c();
    release_gpio(gpio17);

    // Shutdown pigpio
    pigpio_close(gp);

    return EXIT_SUCCESS;
}
