#define TMP05_GPIO 4 // GPIO4 (physical pin 7) for TMP05 SDA

// Constants
#define TMP05_MAX_THRESHOLD 50 // 50 ms timeout for edge detection
#define TMP05_MIN_THRESHOLD 0 // Minimum threshold for valid TH
#define TMP05_MAX_TEMPERATURE 150 // Maximum valid temperature in °C
#define TMP05_MIN_TEMPERATURE -40 // Minimum valid temperature in °C

// Function prototypes
void handleSIGINT(int signum);
void handleSIGTERM(int signum);
void readTemperature();
void writeToLog(char *message);
void cleanup();

// Main function
int main() {
    // Initialize pigpio
    if (piOpen() == -1) {
        fprintf(stderr, "Failed to open pigpio: %s\n", piError());
        return EXIT_FAILURE;
    }

    // Register signal handlers
    signal(SIGINT, handleSIGINT);
    signal(SIGTERM, handleSIGTERM);

    // Main loop
    while (1) {
        readTemperature();
        usleep(5000000); // Sleep for 5 seconds
    }

    // Clean up
    cleanup();

    return EXIT_SUCCESS;
}

// Signal handlers
void handleSIGINT(int signum) {
    fprintf(stderr, "SIGINT received, shutting down...\n");
    cleanup();
    exit(EXIT_FAILURE);
}

void handleSIGTERM(int signum) {
    fprintf(stderr, "SIGTERM received, shutting down...\n");
    cleanup();
    exit(EXIT_FAILURE);
}

// Function to read temperature
void readTemperature() {
    int th = 0, tl = 0;
    int attempts = 0;
    struct timespec ts;
    char message[256];

    // Attempt to read temperature
    while (1) {
        // Reset counters and timestamp
        th = 0;
        tl = 0;
        attempts++;

        // Wait for edge on TMP05 GPIO
        if (gpioRead(TMP05_GPIO) == 0) {
            // Falling edge detected
            if (gpioWaitEdge(TMP05_GPIO, GPIOFallingEdge, TMP05_MAX_THRESHOLD) == -1) {
                fprintf(stderr, "Failed to wait for falling edge: %s\n", piError());
                break;
            }
        } else {
            // Rising edge detected
            if (gpioWaitEdge(TMP05_GPIO, GPIO RisingEdge, TMP05_MAX_THRESHOLD) == -1) {
                fprintf(stderr, "Failed to wait for rising edge: %s\n", piError());
                break;
            }
        }

        // Measure high pulse width (TH) and total cycle width (TL)
        if (gpioRead(TMP05_GPIO) == 1) {
            // High state detected
            if (gpioWaitHigh(TMP05_GPIO, TMP05_MAX_THRESHOLD) == -1) {
                fprintf(stderr, "Failed to wait for high state: %s\n", piError());
                break;
            }
            th = micros(); // Capture high pulse start time
        }

        // Capture total cycle end time
        if (gpioRead(TMP05_GPIO) == 0) {
            tl = micros(); // Capture total cycle end time
        }

        // Check for division by zero and invalid TL
        if (tl == 0) {
            fprintf(stderr, "TL is zero, cannot calculate temperature.\n");
            break;
        }

        // Calculate temperature
        float temperature = 4215 - (2143 * (float)th / tl);

        // Check temperature validity and log
        if (temperature >= TMP05_MIN_TEMPERATURE && temperature <= TMP05_MAX_TEMPERATURE) {
            // Format timestamp
            time_t rawtime = time(NULL);
            struct tm *timeinfo = localtime(&rawtime);
            char timestamp[50];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

            // Append to log file
            writeToLog("Temperature: %.1f °C at %s\n", temperature, timestamp);

            // Log 'SENSOR MALFUNCTION' after 3 consecutive failures
            if (attempts >= 3) {
                writeToLog("SENSOR MALFUNCTION\n");
            }
        } else {
            fprintf(stderr, "Temperature out of valid range: %f °C\n", temperature);
        }
    }

    // Reset GPIO pin state
    gpioWrite(TMP05_GPIO, 1); // Set GPIO high to reset TMP05
}

// Function to write to log file
void writeToLog(char *message) {
    FILE *file = fopen("temperature_log.txt", "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open 'temperature_log.txt' for append: %s\n", strerror(errno));
        return;
    }

    fprintf(file, "%s", message);
    fclose(file);
}

// Function to clean up resources
void cleanup() {
    // Close log file
    fclose(NULL);

    // Close pigpio
    piClose();
}

