#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>

// Constants
#define SHT35_ADDR 0x44
#define SHT35_CMD_READ_HUMIDITY 0x24
#define SHT35_CMD_READ_TEMPERATURE 0x25
#define SHT35_TIMEOUT_MS 15000
#define MAX_RETRIES 3
#define SINUSOIDAL_AMPLITUDE 2
#define SINUSOIDAL_PERIOD_MS 3600000

// Sensor data structure
typedef struct {
    uint16_t humidity;
    uint16_t temperature;
    uint8_t crc;
} SensorData;

// Sensirion SHT35 conversion functions
float convertHumidity(uint16_t rawHumidity) {
    return (float)rawHumidity * 125.0 / 65535.0;
}

float convertTemperature(uint16_t rawTemperature) {
    return (float)(rawTemperature - 500) * 0.031832 / 65535.0;
}

// Check CRC validity
bool isValidCrc(uint8_t crc) {
    return (crc == (uint8_t)((uint16_t)(SensorData.humidity << 8) | SensorData.temperature));
}

// Main function
int main() {
    // Signal handlers
    struct sigaction intHandler, termHandler;
    sigemptyset(&intHandler.sa_mask);
    intHandler.sa_handler = SIG_IGN;
    sigaction(SIGINT, &intHandler, NULL);
    intHandler.sa_handler = SIG_IGN;
    sigaction(SIGTERM, &intHandler, NULL);

    // Initialize pigpio
    pigpio *pi = NULL;
    if (pigpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error());
        return EXIT_FAILURE;
    }
    pi = pigpio_open();

    // I2C setup
    if (pigpio_i2c_open(pi, 1) < 0) {
        fprintf(stderr, "Failed to open I2C bus 1: %s\n", pigpio_error());
        pigpio_close(pi);
        return EXIT_FAILURE;
    }

    // Log file setup
    FILE *logFile = NULL;
    if ((logFile = fopen("environmental_data.txt", "a")) == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        pigpio_i2c_close(pi);
        pigpio_close(pi);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Simulate sinusoidal offset
        float timeInSeconds = (float)time(NULL) / 60.0;
        float offsetTemperature = SINUSOIDAL_AMPLITUDE * sin(M_PI * 2 * timeInSeconds / SINUSOIDAL_PERIOD_MS);
        float offsetHumidity = SINUSOIDAL_AMPLITUDE * sin(M_PI * 2 * timeInSeconds / (SINUSOIDAL_PERIOD_MS * 5));

        // Sensor read attempt
        int retryCount = 0;
        do {
            // Disable clock stretching
            pigpio_i2c_write(pi, SHT35_ADDR, SHT35_CMD_READ_HUMIDITY, 0x00, 0, 0, SHT35_TIMEOUT_MS);
            if (pigpio_i2c_read(pi, SHT35_ADDR, 2, &SensorData.humidity, &SensorData.crc) < 0) {
                fprintf(stderr, "Failed to read humidity: %s\n", pigpio_error());
                if (retryCount < MAX_RETRIES) {
                    fprintf(stderr, "Retrying in 1 second...\n");
                    sleep(1);
                    retryCount++;
                } else {
                    SensorData.humidity = 0;
                    SensorData.crc = 0xFF;
                }
                continue;
            }

            if (!isValidCrc(SensorData.crc)) {
                fprintf(stderr, "Invalid CRC for humidity.\n");
                continue;
            }

            // Read temperature
            pigpio_i2c_write(pi, SHT35_ADDR, SHT35_CMD_READ_TEMPERATURE, 0x00, 0, 0, SHT35_TIMEOUT_MS);
            if (pigpio_i2c_read(pi, SHT35_ADDR, 2, &SensorData.temperature, &SensorData.crc) < 0) {
                fprintf(stderr, "Failed to read temperature: %s\n", pigpio_error());
                if (retryCount < MAX_RETRIES) {
                    fprintf(stderr, "Retrying in 1 second...\n");
                    sleep(1);
                    retryCount++;
                } else {
                    SensorData.temperature = 0;
                    SensorData.crc = 0xFF;
                }
                continue;
            }

            if (!isValidCrc(SensorData.crc)) {
                fprintf(stderr, "Invalid CRC for temperature.\n");
                continue;
            }

            // Convert and apply sinusoidal offset
            float humidity = convertHumidity(SensorData.humidity);
            float temperature = convertTemperature(SensorData.temperature);
            humidity += offsetHumidity;
            temperature += offsetTemperature;

            // Log data
            char timestamp[50];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%03uZ", localtime(&now));
            fprintf(logFile, "%s, Humidity: %.2f%% RH, Temperature: %.1f°C\n", timestamp, humidity * 100, temperature);

        } while (retryCount < MAX_RETRIES);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up on exit
    if (pi) {
        pigpio_close(pi);
    }
    if (logFile) {
        fclose(logFile);
    }

    return EXIT_SUCCESS;
}

