// Define constants for SDP810 sensor communication
#define SDP810_ADDRESS 0x25
#define SDP810_CMD_READ_CONTINUOUS_MEASUREMENT 0x362F
#define SDP810_CRC_LENGTH 1

// Sensor data structure
typedef struct {
    uint16_t pressure_MSB;
    uint16_t pressure_LSB;
    uint8_t crc_pressure;
    uint16_t temperature_MSB;
    uint16_t temperature_LSB;
    uint8_t crc_temperature;
    uint8_t scale_factor[3];
} SDP810_DATA;

// CRC-8 function
uint8_t crc8(uint8_t *buf, size_t len) {
    uint8_t crc = 0;
    for (size_t i = 0; i < len; i++) {
        crc ^= buf[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 1) {
                crc = (crc >> 1) ^ 0x07;
            } else {
                crc >>= 1;
            }
        }
    }
    return crc;
}

// Function to convert raw pressure to Pa
float convertPressure(uint16_t raw_pressure) {
    return (raw_pressure / SDP810_SCALE_FACTOR[0]) - 1000.0;
}

// Function to convert raw temperature to °C
float convertTemperature(uint16_t raw_temperature) {
    return (raw_temperature / 200.0) - 45.0;
}

// Main function
int main() {
    // Signal handlers for graceful shutdown
    struct sigaction intHandler, termHandler;
    sigemptyset(&intHandler.sa_mask);
    intHandler.sa_handler = SIG_IGN;
    sigaction(SIGINT, &intHandler, NULL);
    intHandler.sa_handler = SIG_IGN;
    sigaction(SIGTERM, &intHandler, NULL);

    // Initialize pigpio
    pigpio *pi = NULL;
    if (pigpio_init() == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error());
        return EXIT_FAILURE;
    }
    pi = pigpio_open();

    // Open I2C bus 1
    if (pigpio_i2c_open(pi, 1) == -1) {
        fprintf(stderr, "Failed to open I2C bus 1: %s\n", pigpio_error());
        pigpio_close(pi);
        return EXIT_FAILURE;
    }

    // File descriptor for logging
    int fd = fopen("airflow.dat", "wb+");
    if (fd == -1) {
        fprintf(stderr, "Failed to open airflow.dat for writing: %s\n", strerror(errno));
        pigpio_i2c_close(pi, 1);
        pigpio_close(pi);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Send command to SDP810
        uint8_t cmd[2] = {SDP810_CMD_READ_CONTINUOUS_MEASUREMENT, 0};
        if (pigpio_i2c_write(pi, 1, SDP810_ADDRESS, cmd, 2) == -1) {
            fprintf(stderr, "Failed to write command to SDP810: %s\n", pigpio_error());
            break;
        }

        // Wait for conversion
        uint32_t timeout = 1000; // 1 second timeout
        while (pigpio_i2c_read(pi, 1, SDP810_ADDRESS, NULL, 0, &timeout) < 9) {
            if (timeout == 0) {
                fprintf(stderr, "Timeout reading from SDP810\n");
                break;
            }
            usleep(1000); // Short pause
        }

        // Read data from SDP810
        uint8_t data[9];
        if (pigpio_i2c_read(pi, 1, SDP810_ADDRESS, data, 9) == -1) {
            fprintf(stderr, "Failed to read data from SDP810: %s\n", pigpio_error());
            break;
        }

        // Validate CRCs
        if (crc8(data, 8) != data[7] || crc8(&data[2], 6) != data[8]) {
            fprintf(stderr, "CRC error detected, data is invalid\n");
            break;
        }

        // Convert and print data
        SDP810_DATA sensor_data;
        sensor_data.pressure_MSB = data[0];
        sensor_data.pressure_LSB = data[1];
        sensor_data.crc_pressure = data[2];
        sensor_data.temperature_MSB = data[3];
        sensor_data.temperature_LSB = data[4];
        sensor_data.crc_temperature = data[5];
        sensor_data.scale_factor[0] = data[6];
        sensor_data.scale_factor[1] = data[7];
        sensor_data.scale_factor[2] = data[8];

        float pressure = convertPressure(sensor_data.pressure_MSB << 8 | sensor_data.pressure_LSB);
        float temperature = convertTemperature(sensor_data.temperature_MSB << 8 | sensor_data.temperature_LSB);

        // Write data to file
        fwrite(&pressure, sizeof(float), 1, fd);
        fwrite(&temperature, sizeof(float), 1, fd);

        // Log data
        printf("Pressure: %.2f Pa, Temperature: %.1f°C\n", pressure, temperature);
    }

    // Close resources on exit
    fclose(fd);
    pigpio_i2c_close(pi, 1);
    pigpio_close(pi);

    return EXIT_SUCCESS;
}

