    if (ret < 0) {
        fprintf(stderr, "I2C write failed: %s\n", pigpioI2CErrstr());
        return ret;
    }

    // Read response
    ret = pigpioI2CRead(addr, 0, data + len, 3, crc);
    if (ret < 0) {
        fprintf(stderr, "I2C read failed: %s\n", pigpioI2CErrstr());
        return ret;
    }

    // Validate CRC
    return validateCRC8(*crc);
}

// Function to validate CRC-8 using polynomial 0x31
int validateCRC8(uint8_t crc) {
    return (crc ^ (crc >> 4) ^ (crc >> 5) ^ (crc >> 7)) == 0x31;
}
