#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>

// Define constants
#define SENSOR_ADDR 0x28
#define I2C_BUS_NUM 1
#define FAN_GPIO 18
#define FLOW_MIN_COUNT 1638
#define FLOW_MAX_COUNT 14745
#define SLPM_MIN 0
#define SLPM_MAX 10
#define SAMPLE_INTERVAL_MS 100

// Function prototypes
void setup_pigpio();
void handle_signal(int signum);
void read_sensor(uint16_t *flow_count);
void convert_flow(uint16_t flow_count, float *flow_rate_SLPM);
void set_pwm_duty(float duty_cycle);
void log_flow(float pressure_Pa);
void cleanup();

int main() {
    // Initialize global variables
    pid_t pid = -1;
    uint16_t flow_count;
    float flow_rate_SLPM;
    int error;

    // Signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Setup pigpio
    setup_pigpio();

    // Main loop
    while (1) {
        // Read sensor
        error = read_sensor(&flow_count);
        if (error != 0) {
            fprintf(stderr, "Error reading sensor: %d\n", error);
            break;
        }

        // Convert flow count to SLPM
        convert_flow(flow_count, &flow_rate_SLPM);

        // Set PWM duty cycle
        set_pwm_duty(flow_rate_SLPM);

        // Log flow rate
        log_flow(flow_rate_Pa);

        // Sleep for the interval
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    // Clean up
    cleanup();

    return 0;
}

// Function to setup pigpio
void setup_pigpio() {
    if (pigpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }

    // Set up GPIO for fan control
    if (pigpio_set_mode(FAN_GPIO, pigpio_PWM_OUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d to PWM output: %s\n", FAN_GPIO, pigpio_error());
        exit(EXIT_FAILURE);
    }

    // Set up I2C for sensor communication
    if (pigpio_i2c_open(I2C_BUS_NUM) < 0) {
        fprintf(stderr, "Failed to open I2C bus %d: %s\n", I2C_BUS_NUM, pigpio_error());
        exit(EXIT_FAILURE);
    }
}

// Function to handle signals
void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        // Graceful shutdown
        pigpio_stop();
        cleanup();
        exit(EXIT_SUCCESS);
    }
}

// Function to read the sensor
int read_sensor(uint16_t *flow_count) {
    int error;

    // Open I2C device
    error = pigpio_i2c_open(I2C_BUS_NUM);
    if (error != 0) {
        fprintf(stderr, "Failed to open I2C bus %d: %s\n", I2C_BUS_NUM, pigpio_error());
        return error;
    }

    // Write address and read command
    error = pigpio_i2c_write(I2C_BUS_NUM, SENSOR_ADDR, 0x03, 0); // Read command
    if (error != 0) {
        fprintf(stderr, "Failed to write to sensor: %d\n", error);
        pigpio_i2c_close(I2C_BUS_NUM);
        return error;
    }

    // Read response
    error = pigpio_i2c_read(I2C_BUS_NUM, SENSOR_ADDR, 1, flow_count);
    if (error != 0) {
        fprintf(stderr, "Failed to read from sensor: %d\n", error);
        pigpio_i2c_close(I2C_BUS_NUM);
        return error;
    }

    // Mask status bits and shift right
    *flow_count = (*flow_count & 0x1F00) >> 10;

    pigpio_i2c_close(I2C_BUS_NUM);
    return 0;
}

// Function to convert flow count to SLPM
void convert_flow(uint16_t flow_count, float *flow_rate_SLPM) {
    float pressure_Pa;

    // Linear conversion based on given counts
    pressure_Pa = (float)flow_count / (FLOAT_MAX / (FLOW_MAX_COUNT - FLOW_MIN_COUNT)) * (SLPM_MAX - SLPM_MIN) + SLPM_MIN;

    *flow_rate_SLPM = pressure_Pa;
}

// Function to set PWM duty cycle
void set_pwm_duty(float duty_cycle) {
    int duty_cycle_int;

    duty_cycle_int = (int)(duty_cycle * 1000.0 + 0.5); // Map to 0-1000 range
    pigpio_write(FAN_GPIO, duty_cycle_int);
}

// Function to log flow rate
void log_flow(float pressure_Pa) {
    char timestamp[50];
    time_t now = time(NULL);
    struct tm timeinfo;
    char buffer[256];

    // Format timestamp
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&now));
    strcpy(timestamp, buffer);

    // Append pressure and write to file
    FILE *log_file = fopen("flow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file for writing: %s\n", strerror(errno));
        return;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, pressure_Pa);
    fclose(log_file);
}

// Function to cleanup resources
void cleanup() {
    // Close I2C handle
    pigpio_i2c_close(-1);

    // Close log file
    fclose(stderr);

    // Stop PWM on GPIO
    pigpio_stop(FAN_GPIO);

    // Shutdown pigpio
    pigpio_cleanup();
}

