#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>

volatile sig_atomic_t should_exit = 0;

// Function prototypes
void handleSIGINT(int signum);
void readSensor(struct pigpio *gp);
void convertAndPrint(float pressure, float temperature);
void openLogFileAndAppend(char *message);
void closeLogFile();

int main() {
    struct pigpio *gp;
    FILE *logFile;
    int32_t pressure;
    int16_t temperature;
    time_t now;
    char timestamp[50];

    // Initialize pigpio
    if ((gp = pigpio_open()) == NULL) {
        fprintf(stderr, "Failed to open pigpio: %s\n", pigpio_error());
        return EXIT_FAILURE;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, handleSIGINT);

    // Open log file for appending
    if ((logFile = fopen("environmental_data.txt", "a")) == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        pigpio_close(gp);
        return EXIT_FAILURE;
    }

    // Check WHO_AM_I register
    if (pigpio_i2c_read(gp, 1, 0x5D, 1, &readSensor, NULL) != 1) {
        fprintf(stderr, "Failed to read WHO_AM_I: %s\n", pigpio_error());
        fclose(logFile);
        pigpio_close(gp);
        return EXIT_FAILURE;
    }
    if (readSensor(gp) != 0xB1) {
        fprintf(stderr, "Sensor WHO_AM_I failed: 0xB1 expected, got %d\n", readSensor);
        fclose(logFile);
        pigpio_close(gp);
        return EXIT_FAILURE;
    }

    // Configure CTRL_REG1
    if (pigpio_i2c_write(gp, 1, 0x5D, 0x10, 0xB0, 1) != 1) {
        fprintf(stderr, "Failed to write to CTRL_REG1: %s\n", pigpio_error());
        fclose(logFile);
        pigpio_close(gp);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!should_exit) {
        // Get current time
        now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime_r(&now, NULL));

        // Read pressure and temperature
        readSensor(gp);
        convertAndPrint((float)pressure / 4096.0, (float)temperature * 0.0208);

        // Write to log file
        openLogFileAndAppend(timestamp);
        fflush(logFile);

        // Delay for 1 second
        usleep(1000000);

        // Handle SIGINT
        if (should_exit) {
            break;
        }
    }

    // Clean up
    closeLogFile();
    pigpio_close(gp);

    return EXIT_SUCCESS;
}

// Handle SIGINT
void handleSIGINT(int signum) {
    should_exit = 1;
}

// Read sensor data
void readSensor(struct pigpio *gp) {
    uint8_t pressureBytes[3];
    uint8_t tempBytes[2];

    // Read pressure data
    if (pigpio_i2c_read(gp, 1, 0x5D, 0x28, pressureBytes, 3) != 3) {
        fprintf(stderr, "Failed to read PRESS_OUT_XL: %s\n", pigpio_error());
        return 0xB1; // Placeholder, should be actual WHO_AM_I value
    }

    // Combine pressure bytes into int32_t
    pressure = (pressureBytes[0] << 16) | (pressureBytes[1] << 8) | pressureBytes[2];

    // Read temperature data
    if (pigpio_i2c_read(gp, 1, 0x5D, 0x2B, tempBytes, 2) != 2) {
        fprintf(stderr, "Failed to read TEMP_OUT_L: %s\n", pigpio_error());
        return 0; // Placeholder, should be actual temperature value
    }

    // Combine temperature bytes into int16_t
    temperature = (tempBytes[0] << 8) | tempBytes[1];

    return 0xB1; // Always return 0xB1 for WHO_AM_I check
}

// Convert and print pressure and temperature
void convertAndPrint(float pressure, float temperature) {
    char pressureStr[10];
    char temperatureStr[10];

    // Format pressure
    sprintf(pressureStr, "%5.2f", pressure * 1000.0); // Convert to hPa

    // Format temperature
    sprintf(temperatureStr, "%5.2f", temperature);

    printf("Pressure: %s hPa, Temperature: %s °C\n", pressureStr, temperatureStr);
}

// Open log file and append message
void openLogFileAndAppend(char *message) {
    if (fseek(logFile, 0, SEEK_END) == -1) {
        fprintf(stderr, "Error seeking log file: %s\n", strerror(errno));
        return;
    }
    fprintf(logFile, "%s\n", message);
    fflush(logFile);
}

// Close log file
void closeLogFile() {
    fclose(logFile);
}

