#define DATA_READY_COMMAND 0x0202

// SCD30 Data structure
typedef struct {
    uint8_t crc8[2]; // CRC bytes
    uint16_t co2_ppm; // CO2 concentration in ppm
    uint16_t temp_c; // Temperature in degrees Celsius
    uint16_t hum_rh; // Humidity in %RH
} SCD30Reading;

// SCD30 CRC-8 function
uint8_t calculate_sc30_crc8(uint8_t *data, uint8_t len) {
    uint8_t crc = 0xFF;
    for (uint8_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x01) {
                crc = (crc >> 1) ^ 0x31;
            } else {
                crc >>= 1;
            }
        }
    }
    return crc;
}

