        uint8_t data_ready;
        if (i2cWriteDevice(SCD30_ADDRESS, DATA_READY_COMMAND, &data_ready, 1) == -1) {
            fprintf(stderr, "Failed to write to SCD30: %s\n", strerror(errno));
            continue;
        }

        // Poll data ready flag
        if (data_ready != 0x02) {
            fprintf(stderr, "SCD30 not ready: 0x%02X\n", data_ready);
            continue;
        }

        // Read data from SCD30
        SCD30Reading reading;
        if (i2cReadDevice(SCD30_ADDRESS, READ_COMMAND, &reading, 18) == -1) {
            fprintf(stderr, "Failed to read from SCD30: %s\n", strerror(errno));
            continue;
