        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", localtime(&now));
        fprintf(stderr, "Timestamp: %s, CO2: %04X, Temp: %04X, Humidity: %02X\n", timestamp,
                reading.co2_ppm, reading.temp_c, reading.hum_rh);

        // Drive ventilation system based on CO2 levels
        if (reading.co2_ppm < 800) {
            fprintf(stderr, "Ventilation: OFF (CO2 < 800 ppm)\n");
