#define START_COMMAND 0x36
#define CONTINUOUS_MEASUREMENT_COMMAND 0x2F

// CRC constants for SDP32
#define SDP32_CRC_POLYNOMIAL 0x07
#define SDP32_CRC_TABLE {0x00, 0x07, 0x06, 0x03, 0x05, 0x04, 0x0E, 0x0B, 0x0D, 0x09, 0x0C, 0x01, 0x08, 0x0A}

// Function prototypes
