    // Initialize pigpio
    setup_pigpio();

    // Check command-line argument for sampling interval
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <milliseconds>\n", argv[0]);
        return 1;
    }

    int sampling_interval_ms = atoi(argv[1]);

    // Signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);

        unsigned char data[9];
        int crc_ok = 0;

        // Send continuous measurement command
        pigpio_i2c_write(SDP32_ADDRESS, START_COMMAND);
        pigpio_i2c_write(SDP32_ADDRESS, CONTINUOUS_MEASUREMENT_COMMAND);

        // Read data from sensor
        if (pigpio_i2c_read(SDP32_ADDRESS, data, 9) != 9) {
            fprintf(stderr, "Error reading from SDP32 sensor.\n");
            exit(1);
        }

        // Check CRC for pressure, temperature, and scale-factor
        for (int i = 0; i < 3; i++) {
            uint16_t word = (data[i] << 8) | data[i + 1];
            uint8_t crc = SDP32_CRC_TABLE[(word & 0xFF) ^ (word >> 8)];

            if (crc != (word & 0x07)) {
                fprintf(stderr, "CRC error detected in data word 0x%X.\n", word);
                break;
            }

            crc_ok++;
        }

        if (crc_ok != 3) {
            fprintf(stderr, "CRC errors detected. Sensor data is invalid.\n");
            break;
        }

        // Convert raw pressure to Pa
        uint16_t raw_pressure = (data[0] << 8) | data[1];
