#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define HDC1000_ADDR 0x40
#define TEMP_REG 0x00
#define CONFIG_REG 0x02

// Constants for conversion
#define TEMP_CONVERSION ((float)65536.0 * 165.0 / 1024.0 - 40.0)
#define HUMID_CONVERSION ((float)65536.0 * 100.0 / 1024.0)

void handle_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
}

void cleanup_and_exit(int status) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(status);
}

void signal_handler(int signum) {
    cleanup_and_exit(0);
}

int main() {
    // Initialize signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    int i2c_fd = -1;
    char dev_name[10] = "/dev/i2c-1";
    i2c_fd = open(dev_name, O_RDWR);
    if (i2c_fd == -1) {
        handle_error("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Configure HDC1000
    if (ioctl(i2c_fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        handle_error("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Write to configuration register
    uint8_t config_data = 0x20; // Bit 12 set for combined temp and humidity
    if (write(i2c_fd, &config_data, 1) != 1) {
        handle_error("Failed to write to configuration register");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Write to temperature register
        if (write(i2c_fd, &TEMP_REG, 1) != 1) {
            handle_error("Failed to write to temperature register");
            continue;
        }

        // Wait for conversion (fixed delay)
        usleep(20000);

        // Read temperature and humidity
        uint8_t data[4];
        if (read(i2c_fd, data, 4) != 4) {
            handle_error("Failed to read from HDC1000");
            continue;
        }

        // Convert raw data to temperature and humidity
        float temperature = (data[0] / 65536.0) * TEMP_CONVERSION - 40.0;
        float humidity = (data[1] / 65536.0) * HUMID_CONVERSION;

        // Print readings
        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);

        // Sleep for 5 seconds
        usleep(5000000);
    }

    // Close I2C file descriptor on exit
    cleanup_and_exit(EXIT_SUCCESS);
}

