#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <wiringPiI2C.h>

// Define the I2C bus and address constants
#define I2C_BUS 1
#define PRESSURE_SENSOR_ADDRESS 0x60

// Function prototypes
void setup_pigpio();
void setup_i2c();
void read_pressure();
void handle_signal(int signum);

int main() {
    // Initialize pigpio
    setup_pigpio();

    // Set up I2C
    setup_i2c();

    // Signal handler for SIGINT and SIGTERM
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (1) {
        read_pressure();
        usleep(500 * 1000); // Sleep for 500 ms
    }

    // Clean up on exit
    cleanup();

    return 0;
}

// Function to initialize pigpio
void setup_pigpio() {
    if (pigpioSetup() == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }
}

// Function to initialize I2C
void setup_i2c() {
    if (wiringPiI2CSetup(I2C_BUS) == -1) {
        fprintf(stderr, "Failed to set up I2C bus: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

// Function to read pressure from the sensor
void read_pressure() {
    int result;
    struct pigpio *pgpio = pigpioGpio();

    // Check if the sensor is present
    if (pigpioI2CWrite(pgpio, I2C_BUS, PRESSURE_SENSOR_ADDRESS, 0x00, 1) == -1) {
        fprintf(stderr, "Error writing to sensor: %s\n", pigpioError());
        return;
    }

    // Read pressure data
    result = pigpioI2CRead(pgpio, I2C_BUS, PRESSURE_SENSOR_ADDRESS, 0x00, 6);

    if (result < 0) {
        fprintf(stderr, "Error reading from sensor: %s\n", pigpioError());
        return;
    }

    // Print the pressure value with a timestamp
    char buffer[32];
    time_t rawtime = time(NULL);
    struct tm *timeinfo = localtime(&rawtime);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S ", timeinfo);

    printf("%s Pressure: %d\n", buffer, result);
}

// Function to handle SIGINT and SIGTERM signals
void handle_signal(int signum) {
    // Clean up resources
    cleanup();

    // Exit the program
    exit(EXIT_SUCCESS);
}

// Function to clean up resources
void cleanup() {
    // Stop pigpio
    pigpioStop();

    // Release I2C bus
    wiringPiI2CRelease();
}

