#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_DEVICE_PATH "/dev/i2c-1"
#define SENSOR_ADDRESS 0x60
#define PRESSURE_REG_MSByte 0xAA
#define PRESSURE_REG_LSB 0xAB
#define SCALE_FACTOR 0.1

void handle_error(const char *operation, int error_number) {
    fprintf(stderr, "Error during %s: %s\n", operation, strerror(error_number));
}

int main() {
    int i2c_fd;
    struct timeval tv;
    struct timespec ts;
    uint16_t pressure_raw;
    int measurement_success;

    // Open I2C device
    i2c_fd = open(I2C_DEVICE_PATH, O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Check if we have the correct permissions
    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) == -1) {
        handle_error("ioctl(I2C_SLAVE)", errno);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // SIGINT/SIGTERM handler
    struct sigaction sa;
    sa.sa_handler = SIG_IGN; // Ignore the signals
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        // Get current time
        gettimeofday(&tv, NULL);
        ts.tv_sec = tv.tv_sec;
        ts.tv_nsec = tv.tv_usec * 1000;

        // Trigger measurement
        measurement_success = ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS);
        if (!measurement_success) {
            handle_error("ioctl(I2C_SLAVE)", errno);
            continue;
        }

        // Read pressure registers
        if (read(i2c_fd, &pressure_raw, 2) != 2) {
            handle_error("read", errno);
            continue;
        }

        // Convert raw pressure to kPa
        float pressure_kPa = (pressure_raw >> 8) * SCALE_FACTOR + (pressure_raw & 0xFF) * (SCALE_FACTOR / 256.0);

        // Print timestamp and pressure reading
        printf("Pressure: %.2f kPa (at %s)\n", pressure_kPa, ctime(&ts));

        // Sleep for 1 second
        usleep(1000000);
    }

    // Close I2C file descriptor on exit
    close(i2c_fd);

    return EXIT_SUCCESS;
}

