#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_ADDR 0x25
#define SDA_GPIO 2
#define SCL_GPIO 3
#define I2C_BUS_NUM 1

#define CRC_POLYNOMIAL 0x31
#define CRC_INIT_VALUE 0xFF

#define COMMAND_READ_MEASUREMENT 0x362F
#define NUM_READ_BYTES 9

// Function prototypes
void i2c_init();
int i2c_write(uint8_t addr, uint8_t reg, uint8_t data);
int i2c_read(uint8_t addr, uint8_t reg, uint8_t *data, size_t len);
int validate_crc(uint8_t *data, size_t len, uint8_t polynomial, uint8_t init_value);

int main() {
    // Initialize I2C
    i2c_init();

    // File for logging
    FILE *pressure_log = fopen("pressure_log.txt", "a+");
    if (pressure_log == NULL) {
        perror("Failed to open pressure_log.txt");
        exit(EXIT_FAILURE);
    }

    // Loop indefinitely
    while (1) {
        struct timeval tv;
        uint8_t measurement_data[NUM_READ_BYTES];
        int pressure, temperature;

        // Get current time
        gettimeofday(&tv, NULL);

        // Send command to sensor
        if (i2c_write(I2C_ADDR, 0x00, COMMAND_READ_MEASUREMENT) < 0) {
            fprintf(pressure_log, "Failed to write command to sensor\n");
            continue;
        }

        // Wait for 45 ms
        usleep(45000);

        // Read measurement data
        if (i2c_read(I2C_ADDR, 0x00, measurement_data, NUM_READ_BYTES) < 0) {
            fprintf(pressure_log, "Failed to read from sensor\n");
            continue;
        }

        // Validate CRCs
        if (!validate_crc(measurement_data, NUM_READ_BYTES, CRC_POLYNOMIAL, CRC_INIT_VALUE)) {
            fprintf(pressure_log, "CRC validation failed\n");
            continue;
        }

        // Extract pressure and temperature
        pressure = measurement_data[0] / 60.0;
        temperature = measurement_data[1] / 200.0;

        // Log data
        fprintf(pressure_log, "%ld,%f,%f\n", tv.tv_sec, pressure, temperature);

        // Close I2C device file
        close(I2C_BUS_NUM);
    }

    // Clean up on SIGINT/SIGTERM
    atexit(cleanup);

    return 0;

}

// Function to initialize I2C
void i2c_init() {
    int i2c_fd;

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set I2C device address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

// Function to write to I2C device
int i2c_write(uint8_t addr, uint8_t reg, uint8_t data) {
    if (ioctl(i2c_fd, I2C_WRITE, (char *) &reg) < 0) {
        perror("Failed to write register");
        return -1;
    }

    if (write(i2c_fd, &data, 1) != 1) {
        perror("Failed to write data");
        return -1;
    }

    return 0;
}

// Function to read from I2C device
int i2c_read(uint8_t addr, uint8_t reg, uint8_t *data, size_t len) {
    if (ioctl(i2c_fd, I2C_READ, (char *) &reg) < 0) {
        perror("Failed to read register");
        return -1;
    }

    if (read(i2c_fd, data, len) != len) {
        perror("Failed to read data");
        return -1;
    }

    return 0;
}

// Function to validate CRC
int validate_crc(uint8_t *data, size_t len, uint8_t polynomial, uint8_t init_value) {
    uint8_t crc = init_value;
    for (size_t i = 0; i < len; i++) {
        crc = (crc ^ data[i]) & 0xFF;
        crc = (crc >> 8) ^ (crc << 8) ^ (uint8_t)(polynomial & 0xFF);
        if (crc == 0) {
            return 1; // CRC is valid
        }
        crc = crc & 0xFF;
    }

    return 0; // CRC is not valid
}

// Cleanup function to close I2C and file descriptors on exit
void cleanup() {
    if (I2C_BUS_NUM != -1) {
        close(I2C_BUS_NUM);
    }

    if (pressure_log != NULL) {
        fclose(pressure_log);
        pressure_log = NULL;
    }
}

