#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdint.h>

#define PIGPIO_DEFAULT_PORT 1800
#define I2C_BUS 1
#define PRESSURE_SENSOR_ADDRESS 0x40
#define SCALE_FACTOR 0.01
#define SAFE_PRESSURE_RANGE_MIN 200
#define SAFE_PRESSURE_RANGE_MAX 250

// Function prototypes
void handleSIGINTSIGTERM(void);
void readPressure(uint16_t* pressure);
void writeCSVHeader();
void writeCSVData(const char* timestamp, double pressure_kPa);
void cleanup();

int main() {
    // Initialize pigpio
    if (gpioInitialise() == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", gpioError());
        return EXIT_FAILURE;
    }

    // Attempt to open I2C bus 1
    if (i2cOpen(I2C_BUS) == -1) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", i2cError());
        gpioTerminate(); // Close pigpio
        return EXIT_FAILURE;
    }

    // Attempt to read from the pressure sensor
    uint16_t pressure;
    while (1) {
        readPressure(&pressure);

        // Check if pressure is within safe range
        if (pressure < SAFE_PRESSURE_RANGE_MIN || pressure > SAFE_PRESSURE_RANGE_MAX) {
            fprintf(stderr, "Warning: Pressure %hu kPa is outside safe range [%.1f, %.1f] kPa\n", pressure, SAFE_PRESSURE_RANGE_MIN, SAFE_PRESSURE_RANGE_MAX);
        }

        // Write to CSV file
        char timestamp[50];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.", localtime(&now));
        writeCSVData(timestamp, pressure * SCALE_FACTOR);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Clean up
    cleanup();

    return EXIT_SUCCESS;
}

// Function to read pressure from the sensor
void readPressure(uint16_t* pressure) {
    if (i2cReadI2CBlockData(PRESSURE_SENSOR_ADDRESS, 0x00, 2, pressure) == -1) {
        fprintf(stderr, "Failed to read pressure sensor data: %s\n", i2cError());
        // Retry once
        i2cClose(I2C_BUS);
        i2cOpen(I2C_BUS);
        readPressure(pressure);
        return;
    }
}

// Function to write CSV header
void writeCSVHeader() {
    FILE* file = fopen("pressure_log.csv", "a+");
    if (file == NULL) {
        fprintf(stderr, "Failed to open CSV file for writing: %s\n", strerror(errno));
        return;
    }
    fprintf(file, "timestamp,pressure_kPa\n");
    fclose(file);
}

// Function to write CSV data
void writeCSVData(const char* timestamp, double pressure_kPa) {
    FILE* file = fopen("pressure_log.csv", "a+");
    if (file == NULL) {
        fprintf(stderr, "Failed to open CSV file for writing: %s\n", strerror(errno));
        return;
    }
    fprintf(file, "%s,%f\n", timestamp, pressure_kPa);
    fclose(file);
}

// Function to handle SIGINT and SIGTERM
void handleSIGINTSIGTERM(void) {
    // Write remaining data to CSV file
    writeCSVData("Exiting...", -1.0);

    // Close and flush CSV file
    fclose(stdout); // Ensure CSV file is properly closed
    fclose(stderr);

    // Close I2C bus
    i2cClose(I2C_BUS);

    // Clean up pigpio
    gpioTerminate();
}

// Cleanup function to release resources
void cleanup() {
    // Close I2C bus
    i2cClose(I2C_BUS);

    // Close CSV file
    fclose(stdout); // Ensure CSV file is properly closed
    fclose(stderr);
}

