#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pigpio.h>
#include <stdint.h>

#define PI_GPIO_ID 0  // Raspberry Pi GPIO ID
#define SENSOR_ADDRESS 0x27  // HIH6130 I2C address
#define I2C_BUS_NUMBER 1  // I2C bus number

// Constants for HIH6130 register addresses and data format
#define HIH6130_MEASURE_REG 0x00
#define HIH6130_STATUS_REG 0x01

// HIH6130 raw data to temperature and humidity conversion factors
const float raw_to_temp_factor = 165.0 / 16383.0;
const float raw_to_humidity_factor = 100.0 / 16383.0;

// Function prototypes
void read_humidity_and_temperature(pigpio *pi);
void print_timestamp_and_data(const char *prefix, int temperature, int humidity);
void handle_interrupts(int signum);

int main() {
    // Initialize pigpio library
    pigpio *pi = NULL;
    if (pigpio_init() == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error());
        return EXIT_FAILURE;
    }

    // Open the GPIO interface
    if (pi_open(GPIO_ID_RASPBERRY_PI) == -1) {
        fprintf(stderr, "Failed to open GPIO: %s\n", pigpio_error());
        pigpio_cleanup(pi);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Sample every 5 seconds
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        if ((ts.tv_sec % 5) == 0) {
            read_humidity_and_temperature(pi);
        }

        // Handle interrupts (e.g., SIGINT)
        handle_interrupts(0);
    }

    // Clean up resources
    print_timestamp_and_data("END", 0, 0);
    pigpio_cleanup(pi);

    return EXIT_SUCCESS;
}

// Function to read humidity and temperature from HIH6130
void read_humidity_and_temperature(pigpio *pi) {
    int temperature, humidity;
    uint8_t status;

    // Write measurement command to HIH6130
    if (pigpio_i2c_write(pi, I2C_BUS_NUMBER, SENSOR_ADDRESS, HIH6130_MEASURE_REG, 0) == -1) {
        fprintf(stderr, "Failed to write to HIH6130: %s\n", pigpio_error());
        return;
    }

    // Wait for measurement (approx. 40 ms)
    usleep(40000);

    // Read status register
    if (pigpio_i2c_read(pi, I2C_BUS_NUMBER, SENSOR_ADDRESS, HIH6130_STATUS_REG, 1, &status) == -1) {
        fprintf(stderr, "Failed to read status from HIH6130: %s\n", pigpio_error());
        return;
    }

    // Check status bits
    if ((status & 0x01) == 0) {
        fprintf(stderr, "Sensor not present or failed measurement.\n");
        return;
    }

    // Read raw temperature and humidity data
    if (pigpio_i2c_read(pi, I2C_BUS_NUMBER, SENSOR_ADDRESS, 0x00, 4, &temperature) == -1 ||
        pigpio_i2c_read(pi, I2C_BUS_NUMBER, SENSOR_ADDRESS, 0x01, 4, &humidity) == -1) {
        fprintf(stderr, "Failed to read data from HIH6130: %s\n", pigpio_error());
        return;
    }

    // Convert raw data to temperature and humidity
    temperature = (temperature * raw_to_temp_factor) - 40.0;
    humidity = (humidity * raw_to_humidity_factor);

    // Log the data
    print_timestamp_and_data("Temperature: ", temperature, humidity);
}

// Function to print timestamp and data
void print_timestamp_and_data(const char *prefix, int temperature, int humidity) {
    char timestamp[50];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));

    FILE *file = fopen("environmental_data.log", "a");
    if (file) {
        fprintf(file, "%s %d %d\n", timestamp, temperature, humidity);
        fclose(file);
    } else {
        fprintf(stderr, "Failed to open file for writing: %s\n", strerror(errno));
    }
}

// Function to handle interrupts (e.g., SIGINT)
void handle_interrupts(int signum) {
    fprintf(stderr, "Received signal %d, exiting...\n", signum);
    // Clean up resources
    pigpio_close(GPIO_ID_RASPBERRY_PI);
    pigpio_cleanup(NULL);
    exit(EXIT_FAILURE);
}

