void read_humidity_and_temperature(pigpio *pi) {
    int temperature, humidity;
    uint8_t status;

    // Write measurement command to HIH6130
    if (pigpio_i2c_write(pi, I2C_BUS_NUMBER, SENSOR_ADDRESS, HIH6130_MEASURE_REG, 0) == -1) {
        fprintf(stderr, "Failed to write to HIH6130: %s\n", pigpio_error());
        return;
    }

    // Wait for measurement (approx. 40 ms)
    usleep(40000);

    // Read status register
    if (pigpio_i2c_read(pi, I2C_BUS_NUMBER, SENSOR_ADDRESS, HIH6130_STATUS_REG, 1, &status) == -1) {
        fprintf(stderr, "Failed to read status from HIH6130: %s\n", pigpio_error());
        return;
    }

    // Check status bits
    if ((status & 0x01) == 0) {
        fprintf(stderr, "Sensor not present or failed measurement.\n");
        return;
    }

    // Read raw temperature and humidity data
    if (pigpio_i2c_read(pi, I2C_BUS_NUMBER, SENSOR_ADDRESS, 0x00, 4, &temperature) == -1 ||
        pigpio_i2c_read(pi, I2C_BUS_NUMBER, SENSOR_ADDRESS, 0x01, 4, &humidity) == -1) {
        fprintf(stderr, "Failed to read data from HIH6130: %s\n", pigpio_error());
        return;
    }

    // Convert raw data to temperature and humidity
    temperature = (temperature * raw_to_temp_factor) - 40.0;
    humidity = (humidity * raw_to_humidity_factor);

    // Log the data
    print_timestamp_and_data("Temperature: ", temperature, humidity);
