// Function to read pressure using SENT protocol
void read_pressure() {
    int tick_count = 0;
    int status_nibble = 0;
    int data_nibble1 = 0, data_nibble2 = 0, data_nibble3 = 0;
    int checksum_nibble = 0;
    int raw_value = 0;

    // Wait for synchronization pulse
    while (tick_count < SYNC_TICKS) {
        tick_count++;
        if (pigpioReadDigital(GPIO_NUM) == 1) {
            break;
        }
    }

    if (tick_count >= SYNC_TICKS + VALID_PULSE_WIDTH_MAX) {
        fprintf(stderr, "Sensor absent or bus error: Synchronization pulse timeout.\n");
        return;
    }

    // Read status nibble
    for (int i = 0; i < STATUS_NIBBLE; i++) {
        tick_count++;
        if (pigpioReadDigital(GPIO_NUM) == 1) {
            status_nibble <<= 1;
            if (tick_count >= VALID_PULSE_WIDTH_MAX) {
                fprintf(stderr, "Bus error: Status nibble pulse width too long.\n");
                return;
            }
        }
    }

    // Read data nibbles
    for (int i = 0; i < DATA_NIBBLES; i++) {
        data_nibble1 = 0;
        for (int j = 0; j < 4; j++) {
            tick_count++;
            if (pigpioReadDigital(GPIO_NUM) == 1) {
                data_nibble1 <<= 1;
                if (tick_count >= VALID_PULSE_WIDTH_MAX) {
                    fprintf(stderr, "Bus error: Data nibble pulse width too long.\n");
                    return;
                }
            }
        }

        data_nibble2 = 0;
        for (int j = 0; j < 4; j++) {
            tick_count++;
            if (pigpioReadDigital(GPIO_NUM) == 1) {
                data_nibble2 <<= 1;
                if (tick_count >= VALID_PULSE_WIDTH_MAX) {
                    fprintf(stderr, "Bus error: Data nibble pulse width too long.\n");
                    return;
                }
            }
        }

        data_nibble3 = 0;
        for (int j = 0; j < 4; j++) {
            tick_count++;
            if (pigpioReadDigital(GPIO_NUM) == 1) {
                data_nibble3 <<= 1;
                if (tick_count >= VALID_PULSE_WIDTH_MAX) {
                    fprintf(stderr, "Bus error: Data nibble pulse width too long.\n");
                    return;
                }
            }
        }

        // Calculate checksum
        checksum_nibble = (status_nibble + data_nibble1 + data_nibble2 + data_nibble3) % 16;

        // Validate checksum
        if (checksum_nibble != pigpioReadDigital(GPIO_NUM)) {
            fprintf(stderr, "Bus error: Checksum mismatch.\n");
            return;
        }

        // Convert raw value to pressure
        raw_value = (data_nibble1 << 4) + (data_nibble2 << 2) + data_nibble3;
        float pressure = (raw_value * RAW_TO_PRESSURE_SCALE) + RAW_TO_PRESSURE_OFFSET;

        // Log pressure reading
        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
        fprintf(pressure_log_file, "%s, Pressure: %.2f Pa\n", timestamp, pressure);

        // Reset GPIO for next reading
        pigpioWriteDigital(GPIO_NUM, 0);
    }
}

// Function to handle signals
void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        fprintf(stderr, "Received SIGINT or SIGTERM, shutting down.\n");
        piClose();
        fclose(pressure_log_file);
        exit(EXIT_FAILURE);
    }
}

// Function to cleanup resources
void cleanup() {
    if (pressure_log_file != NULL) {
        fclose(pressure_log_file);
        pressure_log_file = NULL;
    }

    if (piPid != -1) {
        piClose();
        piPid = -1;
    }
}

