    if (piI2CWrite(pi, 1, TMP117_REG_ID, 1, (uint8_t *) &TMP117_ID_EXPECTED, 1) != 1) {
        fprintf(stderr, "Failed to read device ID from TMP117: %s\n", pigError());
        piClose(pi);
        return EXIT_FAILURE;
    }
    if (TMP117_ID_EXPECTED != 0x0117) {
        fprintf(stderr, "TMP117 device ID does not match expected value (0x0117).\n");
        piClose(pi);
        return EXIT_FAILURE;
