    if (file == NULL) {
        fprintf(stderr, "Failed to open file for writing: %s\n", strerror(errno));
        piClose(pi);
        return EXIT_FAILURE;
    }

    // Main loop to read and write temperature every 60 seconds
    struct timespec interval = { .tv_sec = 60, .tv_nsec = 0 };
    while (1) {
