#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>

// Define buffer size
#define BUFFER_SIZE 1024

// TMP117 temperature register address
#define TMP117_REG_TEMPERATURE 0x00

// Temperature resolution in °C per LSB
#define TEMPERATURE_RESOLUTION 0x0001

// I2C bus number
#define I2C_BUS 1

// Default TMP117 address
#define TMP117_ADDRESS 0x48

// File path for temperature log
#define FILE_PATH "temperature_log.dat"

// Circular buffer for temperature readings
uint16_t temperatureBuffer[BUFFER_SIZE];

// Current index in the circular buffer
size_t bufferIndex = 0;

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    // Flush the buffer to file
    fwrite(temperatureBuffer, sizeof(uint16_t), bufferIndex, FILE);

    // Release resources
    pigDel(pi);
    close(i2cFile);

    // Exit the program
    exit(0);
}

int main() {
    // Initialize pigpio
    int pi = pigOpen();
    if (pi == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigError());
        return EXIT_FAILURE;
    }

    // Open I2C bus
    int i2cFile = pigI2COpen(pi, I2C_BUS);
    if (i2cFile == -1) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", pigI2CError());
        pigDel(pi);
        return EXIT_FAILURE;
    }

    // Set up signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read temperature from TMP117
        uint16_t temperature;
        if (pigI2CRead(pi, i2cFile, TMP117_ADDRESS, TMP117_REG_TEMPERATURE, &temperature, 2) == -1) {
            fprintf(stderr, "Failed to read temperature: %s\n", pigI2CError());
            continue;
        }

        // Convert temperature from raw value to °C
        temperature *= TEMPERATURE_RESOLUTION;
        temperature >>= 8; // Convert to °C

        // Store temperature in circular buffer
        temperatureBuffer[bufferIndex++] = temperature;
        if (bufferIndex == BUFFER_SIZE) {
            bufferIndex = 0; // Wrap around
        }

        // Sample every 5 seconds
        sleep(5);

        // Persist buffer to file on every sample and on exit
        if (bufferIndex > 0) {
            fwrite(temperatureBuffer, sizeof(uint16_t), bufferIndex, FILE);
            bufferIndex = 0; // Reset buffer for next sample
        }

        // Check for graceful shutdown signal
        if (signal(SIGINT) == SIG_IGN || signal(SIGTERM) == SIG_IGN) {
            signal(SIGINT, signal_handler);
            signal(SIGTERM, signal_handler);
        }
    }

    // Close I2C bus and release resources on exit
    pigI2CClose(i2cFile);
    pigDel(pi);

    return EXIT_SUCCESS;
}

