// Define the resolution for temperature conversion
#define TEMP_RESOLUTION 7812.5

// Function prototypes
void handleSIGINT(int signum);
int readTemperature(pi_pigpiod *pp);
void writeTemperature(pi_pigpiod *pp, int temperature);

// Main function
int main() {
    // Initialize pigpio
    if (piOpen() == -1) {
        fprintf(stderr, "Failed to open pigpio: %s\n", piError());
        return EXIT_FAILURE;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, handleSIGINT);

    // Attempt to initialize I2C up to 3 times
    for (int i = 0; i < 3; ++i) {
        if (piI2COpen(1) == -1) {
            fprintf(stderr, "Failed to open I2C bus 1: %s\n", piError());
            piClose();
            return EXIT_FAILURE;
        }
        break; // Exit loop if successful
    }

    // Main loop
    while (1) {
        // Read temperature
        int temperature = readTemperature(NULL);

        // Handle temperature reading
        if (temperature != -127) { // Sensor present and valid reading
            writeTemperature(NULL, temperature);
        } else {
            fprintf(stderr, "Sensor not responding or invalid reading.\n");
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Clean shutdown on SIGINT
    handleSIGINT(SIGINT);

    // Close I2C handle and exit
    piClose();
    return EXIT_SUCCESS;
}

// Function to read temperature from TMP117
int readTemperature(pi_pigpiod *pp) {
    int temperature;
    if (piI2CWrite(1, 0x48, 0x00, 2) == -1) {
        fprintf(stderr, "Failed to write to TMP117: %s\n", piError());
        return -127; // Indicate sensor absent or bus error
    }

    if (piI2CRead(1, 0x48, 0x00, 2, &temperature) == -1) {
        fprintf(stderr, "Failed to read from TMP117: %s\n", piError());
        return -127; // Indicate sensor absent or bus error
    }

    // Convert temperature from 16-bit two's complement
    temperature = (temperature * TEMP_RESOLUTION) / 65535;

    // Handle negative temperatures correctly
    if (temperature < 0) {
        temperature += 65535;
    }

    return temperature;
}

// Function to write temperature to log file
void writeTemperature(pi_pigpiod *pp, int temperature) {
    char logFileName[] = "temperature_log.txt";
    FILE *file = fopen(logFileName, "a");

    if (file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", logFileName);
        return;
    }

    fprintf(file, "%s, Temperature: %.1f C\n", 
            localtime(&time(NULL))->tm_year + 1900, 
            temperature);
    fclose(file);
}

// Signal handler for SIGINT
void handleSIGINT(int signum) {
    fprintf(stderr, "Received SIGINT, shutting down gracefully...\n");
    piClose(); // Close pigpio
    exit(EXIT_SUCCESS); // Terminate the program
}

