#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

#define GPIO_PIN 4
#define DHT11_LOW_TIME_MS 18
#define DHT11_HIGH_TIME_MS 80
#define BIT_LOW_TIME_MS 50
#define BIT_HIGH_THRESHOLD_MS 70
#define TIMEOUT_MS 20000

FILE *logFile = NULL;
pigpio *gp = NULL;

void setup_pigpio() {
    if (gp == NULL) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        exit(EXIT_FAILURE);
    }
    gpioModeSet(gp, GPIO_PIN, GPIO_OUTPUT);
    gpioWrite(gp, GPIO_PIN, 0); // Pull low
    usleep(DHT11_LOW_TIME_MS * 1000); // Wait for 18ms
    gpioWrite(gp, GPIO_PIN, 1); // Pull high
}

void cleanup_pigpio() {
    if (gp != NULL) {
        gpioTerminate(gp);
        gp = NULL;
    }
}

void handle_signal(int signum) {
    cleanup_pigpio();
    fclose(logFile);
    exit(EXIT_SUCCESS);
}

void bit_bang(uint8_t bit) {
    usleep(BIT_LOW_TIME_MS * 1000);
    usleep(bit == 0 ? BIT_LOW_TIME_MS * 1000 : BIT_HIGH_THRESHOLD_MS * 1000);
}

void read_dht11() {
    uint8_t data[5];
    uint8_t checksum = 0;

    // Pull line low
    gpioWrite(gp, GPIO_PIN, 0);
    usleep(DHT11_LOW_TIME_MS * 1000);

    // Send start signal
    gpioWrite(gp, GPIO_PIN, 1);
    usleep(80 * 1000);

    // Read response
    for (int i = 0; i < 5; i++) {
        data[i] = 0;
        // Bit bang for each bit
        for (int j = 0; j < 8; j++) {
            bit_bang(0);
            if (gpioRead(gp, GPIO_PIN) == 0) {
                data[i] |= (1 << j);
            }
        }

        // Calculate checksum
        checksum += data[i];
    }

    // Checksum validation
    if (checksum % 256 != data[4]) {
        fprintf(stderr, "Checksum failed.\n");
        return;
    }

    // Write data to file
    char timestamp[50];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
    fprintf(logFile, "DHT11 reading at %s: Humidity: %u, Temperature: %u\n", timestamp, data[0], data[2]);
}

int main() {
    struct sigaction sa;
