    logFile = fopen("dht11_readings.txt", "a+");
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        exit(EXIT_FAILURE);
    }

    while (1) {
        setup_pigpio();
        read_dht11();
        sleep(2000); // Sample every 2 seconds
    }

    return 0;
}
