#define PIGPIO_ID 0  // Use the default pigpio ID

// SHT31-D sensor I2C address and command
#define SHT31_ADDR 0x44
#define SHT31_MEAS_CMD 0x2C06

// CRC polynomial and initial value
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT_VALUE 0xFF

// Temperature and humidity conversion factors
#define TEMP_CONVERSION_FACTOR 175
#define HUMIDITY_CONVERSION_FACTOR 65535

// Maximum retry attempts for I2C transactions
#define MAX_RETRIES 3

// Function prototypes
void init_pigpio();
void open_i2c_bus(int bus_num);
void close_i2c_bus();
int i2c_write(uint8_t address, uint8_t command, uint8_t *data, size_t length);
int i2c_read(uint8_t address, uint8_t command, uint8_t *data, size_t length);
bool validate_crc(uint8_t data[], size_t length, uint8_t polynomial, uint8_t init_value);
void log_data(const char *timestamp, float temperature, float humidity);
void handle_signals(int signum);

int main() {
    srand(time(NULL));

    // Initialize pigpio
    init_pigpio();

    // Set up I2C bus 1
    open_i2c_bus(1);

    // Main loop
    while (1) {
        // Attempt to read data from the sensor
        uint8_t data[6];
        int retries = 0;
        do {
            int result = i2c_write(SHT31_ADDR, SHT31_MEAS_CMD, &SHT31_MEAS_CMD, 1);
            if (result != 1) {
                fprintf(stderr, "Failed to write command to SHT31-D: %d\n", result);
                break;
            }

            result = i2c_read(SHT31_ADDR, 0x00, data, 6);
            if (result != 6) {
                fprintf(stderr, "Failed to read from SHT31-D: %d\n", result);
                break;
            }

            // Validate CRC
            if (!validate_crc(data, 6, CRC_POLYNOMIAL, CRC_INIT_VALUE)) {
                fprintf(stderr, "CRC validation failed\n");
                break;
            }

            // Convert raw data to temperature and humidity
            float temperature = -45 + (TEMP_CONVERSION_FACTOR * (data[1] & 0xFF));
            float humidity = (HUMIDITY_CONVERSION_FACTOR * (data[3] & 0xFF)) / 100.0;

            // Log data
            log_data(timegm(localtime(&time(NULL))) / 1000, temperature, humidity);

            // Exit after successful reading
            break;
        } while (retries++ < MAX_RETRIES);

        // Wait for 5 seconds before next reading
        sleep(5);
    }

    // Handle signals
    handle_signals(SIGINT);
    handle_signals(SIGTERM);

    // Clean up
    close_i2c_bus();
    pigpio_cleanup();

    return 0;
}

// Function to initialize pigpio
void init_pigpio() {
    if (pi_pigpio_error() != PIGPIO_OK) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pi_pigpio_error_str());
        exit(EXIT_FAILURE);
    }
}

// Function to open I2C bus
void open_i2c_bus(int bus_num) {
    if (pigpio_i2c_open(bus_num) != PIGPIO_OK) {
        fprintf(stderr, "Failed to open I2C bus %d: %s\n", bus_num, pigpio_i2c_error_str());
        exit(EXIT_FAILURE);
    }
}

// Function to close I2C bus
void close_i2c_bus() {
    pigpio_i2c_close();
}

// Function to write to the I2C bus
int i2c_write(uint8_t address, uint8_t command, uint8_t *data, size_t length) {
    int result = pigpio_i2c_write(address, command, data, length);
    if (result != PIGPIO_OK) {
        fprintf(stderr, "Failed to write to I2C: %s\n", pigpio_i2c_error_str());
        return result;
    }
    return PIGPIO_OK;
}

// Function to read from the I2C bus
int i2c_read(uint8_t address, uint8_t command, uint8_t *data, size_t length) {
    int result = pigpio_i2c_read(address, command, data, length);
    if (result != PIGPIO_OK) {
        fprintf(stderr, "Failed to read from I2C: %s\n", pigpio_i2c_error_str());
        return result;
    }
    return PIGPIO_OK;
}

// Function to validate CRC
bool validate_crc(uint8_t data[], size_t length, uint8_t polynomial, uint8_t init_value) {
    uint8_t crc = init_value;
    for (size_t i = 0; i < length; ++i) {
        crc = (crc ^ data[i]) & 0xFF;
        crc = (crc << 1) | (crc >> 7);
        if (crc & 0x80) crc ^= polynomial;
    }
    return crc == data[length];
}

// Function to log data with ISO-8601 timestamp
void log_data(const char *timestamp, float temperature, float humidity) {
    FILE *file = fopen("sht31d_data.log", "a+");
    if (!file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    fprintf(file, "%s,%.1f,%.1f\n", timestamp, temperature, humidity);
    fclose(file);
}

// Function to handle signals
void handle_signals(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        // Graceful shutdown
        close_i2c_bus();
        pigpio_cleanup();
        exit(EXIT_SUCCESS);
    }
}

