            fprintf(stderr, "Failed to seek cct_log.csv to beginning: %s\n", strerror(errno));
            continue;
        }
        if (fprintf(cct_log, "Timestamp,Average_CCT\n") == -1) {
            fclose(cct_log);
            fprintf(stderr, "Failed to write header to cct_log.csv: %s\n", strerror(errno));
            continue;
        }

        // Read device ID from both sensors
        uint16_t device_id_1 = read_adpd105(0x64, ADPD105_DEVICE_ID_REGISTER);
        uint16_t device_id_2 = read_adpd105(0x65, ADPD105_DEVICE_ID_REGISTER);

        // Check if device IDs are correct
        if (device_id_1 != 0x2A || device_id_2 != 0x2A) {
