// Function to calculate CCT using McCamy's formula
double mccamy_cct(uint16_t red, uint16_t green, uint16_t blue) {
    double R = (double)red / 65535.0;
    double G = (double)green / 65535.0;
    double B = (double)blue / 65535.0;

    double X = R * 0.4124 + G * 0.3576 + B * 0.1805;
    double Y = R * 0.2126 + G * 0.7152 + B * 0.0722;
    double Z = R * 0.0193 + G * 0.1192 + B * 0.9505;

    double CCT = 5935.0 * (1.0 + 0.000308 * X + 0.000617 * Y);
    return CCT;
}

