    // Signal handler for SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize pigpio
    if (pigpio_init() == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error());
        return EXIT_FAILURE;
    }

    // Open I2C bus 1
    if (pigpio_i2c_open(1) == -1) {
        fprintf(stderr, "Failed to open I2C bus 1: %s\n", pigpio_error());
        pigpio_exit();
        return EXIT_FAILURE;
    }

    // Function to read from ADPD105
    uint16_t read_adpd105(uint8_t address, uint8_t register_address) {
        uint16_t data;
        if (pigpio_i2c_readI2CBlockData(1, address, 1, &register_address, &data, 2) == -1) {
            fprintf(stderr, "Failed to read from ADPD105: %s\n", pigpio_error());
            return 0; // Return 0 to indicate failure
        }
        return data;
    }

    // Function to write to ADPD105
    void write_adpd105(uint8_t address, uint8_t register_address, uint16_t value) {
        if (pigpio_i2c_writeI2CBlockData(1, address, 1, &register_address, &value, 2) == -1) {
            fprintf(stderr, "Failed to write to ADPD105: %s\n", pigpio_error());
        }
    }

    // Main loop
    while (1) {
        // Check if the file exists and write header if not
        FILE *cct_log = fopen("cct_log.csv", "a+");
        if (!cct_log) {
            fprintf(stderr, "Failed to open cct_log.csv for writing: %s\n", strerror(errno));
            continue;
        }
        if (fseek(cct_log, 0, SEEK_SET) == -1) {
            fclose(cct_log);
            fprintf(stderr, "Failed to seek cct_log.csv to beginning: %s\n", strerror(errno));
            continue;
        }
        if (fprintf(cct_log, "Timestamp,Average_CCT\n") == -1) {
            fclose(cct_log);
            fprintf(stderr, "Failed to write header to cct_log.csv: %s\n", strerror(errno));
            continue;
        }

        // Read device ID from both sensors
        uint16_t device_id_1 = read_adpd105(0x64, ADPD105_DEVICE_ID_REGISTER);
        uint16_t device_id_2 = read_adpd105(0x65, ADPD105_DEVICE_ID_REGISTER);

        // Check if device IDs are correct
        if (device_id_1 != 0x2A || device_id_2 != 0x2A) {
            fprintf(stderr, "Device ID mismatch: Expected 0x2A, got 0x%X and 0x%X\n", device_id_1, device_id_2);
            continue;
        }

        // Read color data
        uint16_t red_1 = read_adpd105(0x64, ADPD105_RED_REGISTER);
        uint16_t green_1 = read_adpd105(0x66, ADPD105_GREEN_REGISTER);
        uint16_t blue_1 = read_adpd105(0x68, ADPD105_BLUE_REGISTER);

        uint16_t red_2 = read_adpd105(0x64, ADPD105_RED_REGISTER);
        uint16_t green_2 = read_adpd105(0x66, ADPD105_GREEN_REGISTER);
        uint16_t blue_2 = read_adpd105(0x68, ADPD105_BLUE_REGISTER);

        // Calculate CCT for each sensor
        double cct_1 = mccamy_cct(red_1, green_1, blue_1);
        double cct_2 = mccamy_cct(red_2, green_2, blue_2);

        // Compute average CCT
        double average_cct = (cct_1 + cct_2) / 2.0;

        // Write average CCT to CSV
        fprintf(cct_log, "%ld,%f\n", (long)(pigpio_get_time()/1000), average_cct);

        // Close file handle
        fclose(cct_log);

        // Sleep for 1 second
        sleep(1);
    }

    // Cleanup on exit
    cleanup:

    // Close I2C bus
    pigpio_i2c_close(1);

    // Terminate pigpio
    pigpio_exit();

    return EXIT_SUCCESS;
}

// Function to handle cleanup on SIGINT/SIGTERM
void cleanup() {
    // Close file handles
    fclose(stderr);
    fclose(stdout);
    fclose(cct_log);

    // Release I2C bus
    pigpio_i2c_close(1);

    // Terminate pigpio
    pigpio_exit();
}
