#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pigpio.h>
#include <stdint.h>

#define PIGPIO_IDR 0
#define PIPIO_GPIO_NUM_I2C 7

// Sensor I2C address and registers
#define SENSOR_ADDRESS 0x60
#define RAW_PRESSURE_REGISTER 0x0A2C
#define RAW_TEMPERATURE_REGISTER 0x0A2E

// Conversion constants
#define OUTPUT_MIN 0
#define OUTPUT_MAX 32768
#define P_MIN_KPA 0
#define P_MAX_KPA 800
#define TEMP_CONVERSION_FACTOR 0.01
#define TEMP_OFFSET -40

// Function prototypes
void initialize_pigpio();
void initialize_i2c();
void read_pressure_and_temperature(uint16_t *pressure_raw, uint16_t *temperature_raw);
void convert_pressure(uint16_t raw_pressure, uint16_t pressure_kPa);
void convert_temperature(uint16_t raw_temperature, float temperature_C);
void log_data(const char *timestamp, uint16_t pressure_kPa, float temperature_C);
void handle_errors(const char *operation, int error);
void cleanup_resources();
void run_indefinitely();

int main() {
    srand(time(NULL));

    // Initialize pigpio and I2C
    initialize_pigpio();
    initialize_i2c();

    uint16_t pressure_raw;
    uint16_t temperature_raw;

    while (1) {
        // Read pressure and temperature
        if (pigpio_i2c_read(PIGPIO_IDR, SENSOR_ADDRESS, RAW_PRESSURE_REGISTER, &pressure_raw) != 0) {
            handle_errors("Failed to read pressure register", pigpio_i2c_error());
        }
        if (pigpio_i2c_read(PIGPIO_IDR, SENSOR_ADDRESS, RAW_TEMPERATURE_REGISTER, &temperature_raw) != 0) {
            handle_errors("Failed to read temperature register", pigpio_i2c_error());
        }

        // Convert and log data
        convert_pressure(pressure_raw, pressure_kPa);
        convert_temperature(temperature_raw, temperature_C);
        log_data(asctime(localtime()), pressure_kPa, temperature_C);

        // Sleep for 2 seconds
        sleep(2);
    }

    // Clean up resources on exit
    cleanup_resources();

    return 0;
}

// Function to initialize pigpio
void initialize_pigpio() {
    if (pi_pigpio_init() == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }
}

// Function to initialize I2C
void initialize_i2c() {
    if (pigpio_i2c_init(PIPIO_GPIO_NUM_I2C) == -1) {
        fprintf(stderr, "Failed to initialize I2C: %s\n", pigpio_i2c_error());
        exit(EXIT_FAILURE);
    }
}

// Function to read pressure and temperature from the sensor
void read_pressure_and_temperature(uint16_t *pressure_raw, uint16_t *temperature_raw) {
    pigpio_i2c_write(PIGPIO_IDR, SENSOR_ADDRESS, RAW_PRESSURE_REGISTER, 0);
    pigpio_i2c_read(PIGPIO_IDR, SENSOR_ADDRESS, RAW_PRESSURE_REGISTER, pressure_raw);
    pigpio_i2c_write(PIGPIO_IDR, SENSOR_ADDRESS, RAW_TEMPERATURE_REGISTER, 0);
    pigpio_i2c_read(PIGPIO_IDR, SENSOR_ADDRESS, RAW_TEMPERATURE_REGISTER, temperature_raw);
}

// Function to convert raw pressure to kPa
void convert_pressure(uint16_t raw_pressure, uint16_t pressure_kPa) {
    if (raw_pressure < OUTPUT_MIN || raw_pressure > OUTPUT_MAX) {
        fprintf(stderr, "Pressure reading out of range: %u\n", raw_pressure);
        return;
    }
    pressure_kPa = (raw_pressure - OUTPUT_MIN) * (P_MAX_KPA - P_MIN_KPA) / (OUTPUT_MAX - OUTPUT_MIN);
}

// Function to convert raw temperature to Celsius
void convert_temperature(uint16_t raw_temperature, float temperature_C) {
    temperature_C = (raw_temperature * TEMP_CONVERSION_FACTOR) - TEMP_OFFSET;
}

// Function to log data with timestamp
void log_data(const char *timestamp, uint16_t pressure_kPa, float temperature_C) {
    FILE *log_file = fopen("pressure_log.txt", "a+");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file for writing: %s\n", strerror(errno));
        return;
    }
    fprintf(log_file, "%s: Pressure: %.2f kPa, Temperature: %.1f °C\n", timestamp, pressure_kPa, temperature_C);
    fclose(log_file);
}

// Function to handle errors and log them
void handle_errors(const char *operation, int error) {
    char error_message[256];
    sprintf(error_message, "Failed to %s: %s", operation, strerror(error));
    fprintf(stderr, "%s\n", error_message);
}

// Function to cleanup resources
void cleanup_resources() {
    fclose(log_file);
    pigpio_i2c_uninit(PIPIO_GPIO_NUM_I2C);
    pigpioTerminate();
}

// Run the program indefinitely
void run_indefinitely() {
    while (1) {
        // Main loop logic here
    }
}

