#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>

// Define the size of the circular buffer
#define BUFFER_SIZE 60

// Global variables
pigpio *pi;
uint8_t i2c_bus = 1;
uint8_t lm75_address = 0x48;
volatile sig_atomic_t should_exit = 0;
int fan_pin = 18; // BCM GPIO numbering
double running_average = 0.0;
uint16_t temperature;
uint8_t buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
void setup_pigpio();
void setup_i2c();
void read_temperature();
void handle_fan_control(double temperature);
void handle_signal(int signum);
void cleanup();

int main() {
    // Initialize signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Setup
    setup_pigpio();
    setup_i2c();

    // Main loop
    while (!should_exit) {
        read_temperature();
        handle_fan_control(temperature);
        if (buffer_index >= BUFFER_SIZE) {
            buffer_index = 0; // Circular buffer
        }
        running_average = (running_average * (BUFFER_SIZE - 1)) + (temperature / BUFFER_SIZE);
    }

    // Cleanup
    cleanup();

    return 0;
}

// Function: setup_pigpio
void setup_pigpio() {
    pi = pigpioOpen();
    if (pi == NULL) {
        fprintf(stderr, "Failed to open pigpio: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }
}

// Function: setup_i2c
void setup_i2c() {
    if (pigpioI2COpen(pi, i2c_bus) == 0) {
        fprintf(stderr, "Failed to open I2C bus %u: %s\n", i2c_bus, pigpioI2CError());
        exit(EXIT_FAILURE);
    }
}

// Function: read_temperature
void read_temperature() {
    if (pigpioI2CWrite(pi, i2c_bus, lm75_address, 0x00, 2) == 0) {
        fprintf(stderr, "Failed to read temperature: %s\n", pigpioI2CError());
        return;
    }

    temperature = pigpioI2CRead(pi, i2c_bus, lm75_address, 2);
    convert_temperature(temperature);
}

// Function: convert_temperature
void convert_temperature(uint16_t raw_temperature) {
    // Convert from 9-bit signed format to degrees Celsius
    int temperature_celsius = ((raw_temperature & 0x7F) << 1) - (raw_temperature & 0x80);
    temperature_celsius *= 0.5;
}

// Function: handle_fan_control
void handle_fan_control(double temperature) {
    if (temperature > 28.0) {
        pigpioWrite(pi, fan_pin, 1); // Turn fan on
    } else if (temperature < 26.0) {
        pigpioWrite(pi, fan_pin, 0); // Turn fan off
    }
}

// Function: handle_signal
void handle_signal(int signum) {
    should_exit = 1;
}

// Function: cleanup
void cleanup() {
    if (pi != NULL) {
        pigpioClose(pi);
        pi = NULL;
    }
    if (pigpioI2COpen(pi, i2c_bus) != 0) {
        pigpioI2CClose(pi, i2c_bus);
    }
}

