void validateCRC(uint8_t receivedCRC);
void convertRawValues(uint16_t rawPressure, uint16_t rawTemperature);
void logData(const char* timestamp, float pressure, float temperature);
void cleanup();

int main() {
    // Initialize pigpio
    if (gpioInitialise(PIGPIO_IDR) == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

