                if (measurement.pressure / SCALE_FACTOR_PRESSURE > MAX_PRESSURE_THRESHOLD) {
                    fprintf(stderr, "Warning: Pressure exceeds threshold (%.1f Pa)\n", measurement.pressure / SCALE_FACTOR_PRESSURE);
                }
            } else {
                fprintf(stderr, "CRC mismatch, measurement invalid\n");
            }

