    int ret;
    ret = pigpioI2CWrite(PIGPIO_ADDR, address, COMMAND_READ_MEASUREMENT, 0, 9, measurement->crc8);
    if (ret != 9) {
        fprintf(stderr, "Failed to write command to sensor: %d\n", ret);
        return -1;
    }

    // Wait for 45 ms
    usleep(45000);

    ret = pigpioI2CRead(PIGPIO_ADDR, address, measurement->pressure, measurement->temperature, measurement->crc8);
    if (ret != 3) {
        fprintf(stderr, "Failed to read from sensor: %d\n", ret);
        return -1;
    }

    // Validate CRC
    validateCRC(measurement->crc8);

    return 0;
}

// Function to validate CRC
void validateCRC(uint8_t receivedCRC) {
    uint8_t calculatedCRC = 0xFF;
    for (int i = 0; i < 8; ++i) {
        calculatedCRC = (calculatedCRC ^ (measurement->pressure >> (7 - i))) & 0x01;
        calculatedCRC = (calculatedCRC ^ (measurement->temperature >> (7 - i))) & 0x01;
        calculatedCRC = (calculatedCRC ^ (receivedCRC >> (7 - i))) & 0x01;
    }

    if (calculatedCRC != receivedCRC) {
        fprintf(stderr, "CRC mismatch\n");
    }
}

// Function to convert raw values
void convertRawValues(uint16_t rawPressure, uint16_t rawTemperature) {
    measurement.pressure = (rawPressure * SCALE_FACTOR_PRESSURE) / 65535;
    measurement.temperature = (rawTemperature * SCALE_FACTOR_TEMPERATURE) / 65535;
}

// Function to clean up resources
void cleanup() {
    // Close log file
    if (fclose(logfile) == EOF) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
    }

    // Close I2C handle
    pigpioI2CClose();

    // Terminate GPIO
    gpioTerminate();
}

