#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <stdint.h>
#include <gpiod.h>
#include <errno.h>

#define I2C_DEVICE_PATH "/dev/i2c-1" // Adjust for your actual I2C bus path
#define I2C_SLAVE_ADDR 0x4A
#define TEMP_REGISTER 0x00
#define LED_GPIO_PIN 17

// Function prototypes
void i2c_read_temperature(uint8_t slave_addr, int fd, uint16_t *temperature);
void handle_temperature(uint16_t temperature);
void cleanup_resources();
void signal_handler(int signum);

int main() {
    // Initialize GPIO
    int gpio_fd;
    if ((gpio_fd = gpiod_open(GPIO_DEVICE_PATH, GPIOD_OPEN_RWS)) < 0) {
        perror("gpiod_open");
        return EXIT_FAILURE;
    }

    // Open I2C device
    int i2c_fd;
    if ((i2c_fd = open(I2C_DEVICE_PATH, O_RDWR)) < 0) {
        perror("open");
        gpiod_close(gpio_fd);
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_SLAVE_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        gpiod_close(gpio_fd);
        return EXIT_FAILURE;
    }

    // LED GPIO configuration
    struct gpiod_chip *led_chip;
    if ((led_chip = gpiod_get_chip(gpio_fd, LED_GPIO_PIN)) == NULL) {
        perror("gpiod_get_chip");
        gpiod_close(gpio_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Set LED GPIO to output mode
    if (gpiod_direction_output(led_chip, LED_GPIO_PIN, 1) < 0) {
        perror("gpiod_direction_output");
        gpiod_put_chip(led_chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    uint16_t temperature;
    while (1) {
        // Read temperature from I2C
        if (i2c_read_temperature(I2C_SLAVE_ADDR, i2c_fd, &temperature) < 0) {
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            break;
        }

        // Handle temperature
        handle_temperature(temperature);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Clean up resources
    cleanup_resources();

    // Exit on signal
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return EXIT_SUCCESS;
}

// Function to read temperature from the STTS2004 sensor
void i2c_read_temperature(uint8_t slave_addr, int fd, uint16_t *temperature) {
    uint8_t command[2] = {0x00, 0x00}; // Read from register 0x00
    int bytes_written;

    // Write command to sensor
    if (write(fd, command, sizeof(command)) != sizeof(command)) {
        perror("write to I2C");
        return;
    }

    // Read response
    bytes_written = read(fd, temperature, sizeof(*temperature));
    if (bytes_written != sizeof(*temperature)) {
        perror("read from I2C");
        return;
    }
}

// Function to handle temperature and control the LED
void handle_temperature(uint16_t temperature) {
    uint16_t combined_temp = (temperature >> 8) | (temperature & 0xFF);
    combined_temp >>= 4; // Right shift by 4 bits
    float celsius = combined_temp * 0.0625;

    if (celsius > 28) {
        gpiod_set_value(led_chip, LED_GPIO_PIN, 1); // Turn LED on
    } else if (celsius < 27) {
        gpiod_set_value(led_chip, LED_GPIO_PIN, 0); // Turn LED off
    }
}

// Function to release all resources
void cleanup_resources() {
    gpiod_put_chip(led_chip); // Release LED GPIO resources
    close(i2c_fd); // Close I2C file descriptor
}

// Signal handler to clean up on SIGINT/SIGTERM
void signal_handler(int signum) {
    cleanup_resources();
    exit(EXIT_SUCCESS);
}

