#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdint.h>

// Define the polynomial for CRC-8 calculation
uint8_t crc8_poly = 0x31;

// Function prototypes
void handleSIGINT(int signum);
void read_sensirion_data(uint8_t* data, int len, uint8_t* crc);
void convert_and_log(float pressure, float temperature);

// Main function
int main() {
    // Initialize pigpio library
    if (gpioInitialised() == 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return EXIT_FAILURE;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, handleSIGINT);

    // I2C bus and sensor address
    const int i2c_bus = 1;
    const uint8_t sensor_address = 0x25;

    // Variables for reading data
    uint8_t data[9];
    uint8_t crc_pressure, crc_temperature;

    // Main loop
    while (1) {
        // Send continuous measurement command
        data[0] = 0x36;
        data[1] = 0x2F;
        if (pigpioI2CWrite(i2c_bus, sensor_address, 2, data) != 2) {
            fprintf(stderr, "Failed to send command to sensor\n");
            break;
        }

        // Wait for at least 45 ms
        usleep(45000);

        // Read data from the sensor
        if (pigpioI2CRead(i2c_bus, sensor_address, 9, data) != 9) {
            fprintf(stderr, "Failed to read data from sensor\n");
            break;
        }

        // Calculate CRC for pressure and temperature readings
        crc_pressure = crc8(data, 4, crc8_poly, 0xFF);
        crc_temperature = crc8(data + 4, 4, crc8_poly, 0xFF);

        // Check CRC validity
        if (crc_pressure != data[2] || crc_temperature != data[6]) {
            fprintf(stderr, "CRC error detected, invalid data\n");
            break;
        }

        // Convert raw readings
        float pressure = (data[0] << 8) | data[1];
        float temperature = (data[4] << 8) | data[5];
        float scale_factor = (data[8] << 8) | data[9];

        // Convert and log data
        convert_and_log(pressure / scale_factor, temperature / 200.0);

        // Clean up and exit on SIGINT
        handleSIGINT(SIGINT);
    }

    // Clean up resources
    pigpioTerminate();

    return EXIT_SUCCESS;
}

// Function to handle SIGINT (Ctrl+C)
void handleSIGINT(int signum) {
    fprintf(stderr, "SIGINT received, terminating gracefully...\n");
    exit(EXIT_FAILURE);
}

// Function to convert and log data
void convert_and_log(float pressure, float temperature) {
    char timestamp[50];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(stderr, "Pressure: %.2f Pa, Temperature: %.2f °C at %s\n", pressure, temperature, timestamp);
}

// CRC-8 calculation function
uint8_t crc8(const uint8_t* data, int len, uint8_t poly, uint8_t init) {
    uint8_t crc = init;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if ((crc & 1) == 1) {
                crc = (crc >> 1) ^ poly;
            } else {
                crc >>= 1;
            }
        }
    }
    return crc;
}

