void i2c_transaction(gpiod_i2c_handle_t *handle, uint8_t command, uint8_t *response, size_t response_len, int attempts) {
    int rc;
    for (int i = 0; i < attempts; i++) {
        rc = gpiod_i2c_write(handle, SI7021_ADDR, command, 1);
        if (rc != 0) {
            fprintf(stderr, "I2C write failed: %s\n", gpiod_error_string(rc));
            sleep(1); // Wait before retrying
            continue;
        }

        rc = gpiod_i2c_read(handle, SI7021_ADDR, response, response_len, 1);
        if (rc != response_len) {
            fprintf(stderr, "I2C read failed: %s\n", gpiod_error_string(rc));
            sleep(1); // Wait before retrying
            continue;
        }

        break; // Success
    }

    if (i == attempts) {
        fprintf(stderr, "Failed to read from Si7021 sensor.\n");
    }
}

