void handle_sigint_and_sigterm() {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

// Clean up and exit with status
void cleanup_and_exit(int status) {
    if (i2c_handle) {
        gpiod_i2c_close(i2c_handle);
        i2c_handle = NULL;
    }

    // Simulate flushing environment log (actual flushing depends on the environment)
    fflush(environment_log);

    // Exit with the specified status
    exit(status);
}

