    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    // Initialize pigpio and I2C
    initialize_pigpio_and_i2c();

    // Main loop
    while (1) {
        // Read temperature and humidity
        read_hdc1080();

        // Convert and log the readings
