        sleep(5);
    }

    return 0;
}

// Function to initialize pigpio and open I2C bus
void initialize_pigpio_and_i2c() {
    if (pigpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }

    if (gpiod_i2c_open(1, GPIOD_I2C_SPEED_100KHZ) < 0) {
        fprintf(stderr, "Failed to open I2C bus 1: %s\n", gpiod_error());
        pigpio_cleanup();
        exit(EXIT_FAILURE);
    }
}

// Function to configure the HDC1080 sensor
void configure_hdc1080() {
    uint16_t config_reg = 0x0800; // 14-bit resolution for both temperature and humidity

    if (gpiod_i2c_write(HDC1080_ADDRESS, CONFIG_REGISTER, &config_reg, 1) < 0) {
        fprintf(stderr, "Failed to write to configuration register: %s\n", gpiod_error());
        pigpio_cleanup();
        exit(EXIT_FAILURE);
    }
}

// Function to read temperature and humidity from the HDC1080 sensor
void read_hdc1080() {
    uint16_t read_temp_reg = TEMP_REGISTER;
    uint16_t read_humidity_reg = HUMIDITY_REGISTER;

    if (gpiod_i2c_write(HDC1080_ADDRESS, read_temp_reg, &read_temp_reg, 1) < 0 ||
        gpiod_i2c_write(HDC1080_ADDRESS, read_humidity_reg, &read_humidity_reg, 1) < 0) {
        fprintf(stderr, "Failed to write to read registers: %s\n", gpiod_error());
        return;
    }

    // Wait for conversion (at least 20 ms)
    usleep(20000);

    uint16_t raw_temperature, raw_humidity;
    if (gpiod_i2c_read(HDC1080_ADDRESS, read_temp_reg, &raw_temperature, 1) < 0 ||
        gpiod_i2c_read(HDC1080_ADDRESS, read_humidity_reg, &raw_humidity, 1) < 0) {
        fprintf(stderr, "Failed to read temperature and humidity: %s\n", gpiod_error());
        return;
    }

    // Convert raw values to temperature and humidity
    convert_values(raw_temperature, raw_humidity);
}

// Function to convert raw values to temperature and humidity
void convert_values(uint16_t raw_temp, uint16_t raw_humidity) {
    float temperature_C = (raw_temp / 65536.0) * 165.0 - 40.0;
    float humidity_percent = (raw_humidity / 65536.0) * 100.0;
}

// Function to log a reading with timestamp
void log_reading(char* timestamp, float temperature, float humidity) {
    FILE *enviro_log = fopen("enviro_log.txt", "a+");
    if (enviro_log == NULL) {
        fprintf(stderr, "Failed to open enviro_log.txt for writing: %s\n", strerror(errno));
        return;
    }

    fprintf(enviro_log, "%s,%.1f,%d.0\n", timestamp, temperature, humidity);
    fclose(enviro_log);
}

// Function to clean up and exit on SIGINT/SIGTERM
void cleanup_and_exit(int sig) {
    // Close I2C handle
    gpiod_i2c_close(1);

    // Clean up pigpio
    pigpio_cleanup();

    // Exit the program
    exit(EXIT_SUCCESS);
}

