#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdint.h>
#include <string.h>

#define PIGPIO_IDR 0
#define PIPIO_EC 1
#define PIPIO_ED 2
#define PIPIO_EO 3

#define SDP810_ADDR 0x25
#define SDP810_CMD_READ 0x3615
#define SDP810_CRC_POLYNOMIAL 0x31
#define SDP810_INIT_CRC 0xFF

// Sensor data structure
typedef struct {
    uint16_t pressure;
    uint16_t temperature;
    uint8_t crcPressure;
    uint8_t crcTemperature;
    uint16_t scaleFactor;
} SDP810_Data;

// Function prototypes
void handleSIGINT(int signum);
void i2cRead(SDP810_Data* data);
void convertAndLog(const SDP810_Data* data);
void cleanup();

int main() {
    // Initialize pigpio
    if (gpioInitialise() == -1) {
        fprintf(stderr, "Error initializing pigpio: %s\n", pigpioError());
        return EXIT_FAILURE;
    }

    // Open I2C bus 1
    if (i2cOpen(1) == -1) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate(); // Close pigpio
        return EXIT_FAILURE;
    }

    // Open log file for appending
    FILE* logFile = fopen("hvac_pressure_log.txt", "a+");
    if (logFile == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(1); // Close I2C bus
        gpioTerminate(); // Close pigpio
        return EXIT_FAILURE;
    }

    // Signal handler for Ctrl+C
    signal(SIGINT, handleSIGINT);

    // Main loop
    while (1) {
        // Send command to sensor
        SDP810_Data data;
        i2cWrite(SDP810_ADDR, SDP810_CMD_READ, 0);

        // Wait at least 50 ms
        usleep(50000);

        // Read data from sensor
        i2cRead(&data);

        // Check CRCs
        if (data.crcPressure != (data.pressure << 4) | data.initCRC) {
            fprintf(logFile, "%lu, Error, CRC Pressure failed\n", (long)time(NULL));
            continue;
        }
        if (data.crcTemperature != (data.temperature << 4) | data.initCRC) {
            fprintf(logFile, "%lu, Error, CRC Temperature failed\n", (long)time(NULL));
            continue;
        }

        // Convert and log valid readings
        convertAndLog(&data);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Cleanup on SIGINT
    handleSIGINT(SIGINT);

    // Close I2C bus and log file
    i2cClose(1);
    fclose(logFile);

    // Terminate pigpio
    gpioTerminate();

    return EXIT_SUCCESS;
}

// Function to read data from the SDP810 sensor over I2C
void i2cRead(SDP810_Data* data) {
    // Write command to read data
    i2cWrite(SDP810_ADDR, SDP810_CMD_READ, 0);

    // Wait for the sensor to respond
    usleep(50000);

    // Read data from the sensor
    uint8_t buffer[10];
    if (i2cRead(SDP810_ADDR, buffer, 10) != 10) {
        fprintf(stderr, "Error reading from SDP810 sensor: %s\n", i2cError());
        return;
    }

    // Extract pressure and temperature data
    data->pressure = buffer[0] | (buffer[1] << 8);
    data->temperature = buffer[2] | (buffer[3] << 8);
    data->crcPressure = buffer[4];
    data->crcTemperature = buffer[5];
    data->scaleFactor = (buffer[6] << 8) | buffer[7];
}

// Function to convert and log the readings
void convertAndLog(const SDP810_Data* data) {
    double pressure_Pa = (data->pressure / data->scaleFactor) * 100.0;
    double temperature_C = data->temperature / 200.0;

    // Format and write to log file
    char timestamp_str[23];
    time_t now = time(NULL);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(logFile, "%s, %f, %f\n", timestamp_str, pressure_Pa, temperature_C);
}

// Function to handle SIGINT (Ctrl+C)
void handleSIGINT(int signum) {
    // Close I2C handle and flush/close log file
    i2cClose(1);
    fclose(logFile);

    // Exit the program
    exit(EXIT_FAILURE);
}

// Function to cleanup resources
void cleanup() {
    // No specific cleanup needed beyond what's handled in SIGINT handler
}

