#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>
#include <stdint.h>
#include <string.h>

#define PIGPIO_IDR 0
#define PIGPIO_BASE 0x3F200000
#define SCD40_I2C_ADDRESS 0x62
#define SCD40_START_MEASUREMENT 0x21B1
#define SCD40_READ_MEASUREMENT 0xE000
#define SCD40_STOP_MEASUREMENT 0x3F86
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT_VALUE 0xFF

volatile sig_atomic_t running = 1;
volatile sig_atomic_t stopSignal = 0;

struct SCD40Reading {
    uint16_t co2;
    float temperature;
    float humidity;
    time_t timestamp;
};

pthread_t loggingThread;

struct SCD40Reading readData[100];

FILE *csvFile;
FILE *errorFile;

void *loggingThreadFunc(void *arg) {
    char buffer[1024];
    time_t now;
    FILE *logFile;
    int i;

    logFile = fopen("/var/log/scd40_data/timestamped.csv", "a+");
    if (!logFile) {
        perror("Failed to open CSV file for logging");
        return NULL;
    }

    while (running) {
        now = time(NULL);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S,", localtime(&now));
        fprintf(logFile, "%s,", buffer);

        for (i = 0; i < 100 && readData[i].timestamp != 0; i++) {
            fprintf(logFile, "%d,%f,%f,%f,", readData[i].timestamp, readData[i].co2, readData[i].temperature, readData[i].humidity);
        }

        if (i == 100) {
            break; // No new data to write
        }

        fprintf(logFile, "\n");
    }

    fclose(logFile);

    // Flush remaining buffer data to a final CSV file
    logFile = fopen("/var/log/scd40_data/final.csv", "a+");
    if (logFile) {
        for (i = 0; i < 100 && readData[i].timestamp != 0; i++) {
            fprintf(logFile, "%d,%d,%f,%f,", readData[i].timestamp, readData[i].co2, readData[i].temperature, readData[i].humidity);
        }
        fprintf(logFile, "\n");
        fclose(logFile);
    }

    return NULL;
}

void handleSIGINT(int signum) {
    stopSignal = 1;
}

int validateCRC(uint8_t data[2], uint8_t crc) {
    uint8_t crc_value = CRC_INIT_VALUE;
    for (int i = 0; i < 2; i++) {
        crc_value = (crc_value ^ data[i]) & 0xFF;
        crc_value = (crc_value << 1) | (crc_value & 0x01) ^ (CRC_POLYNOMIAL & 0x01);
        if (CRC_POLYNOMIAL)
            CRC_POLYNOMIAL >>= 1;
    }
    return crc_value == crc;
}

void startMeasurement() {
    pigpioWriteReg32(PIGPIO_BASE + PIGPIO_IDR, PIGPIO_IDR_ENABLE);
    pigpioOpen(0, &pi);
    pigpioI2CSetSpeed(pi, 100000); // Set I2C speed to 100kHz
    pigpioI2CSetAddress(pi, SCD40_I2C_ADDRESS);
    pigpioI2CStart(pi);
    pigpioWrite(pi, SCD40_START_MEASUREMENT);
    usleep(1000000); // Wait 1 second
}

void readMeasurement() {
    pigpioI2CWrite(pi, SCD40_READ_MEASUREMENT, (uint8_t *) &readData[0], 9);
    for (int i = 0; i < 3; i++) {
        if (!validateCRC(&readData[i * 2], readData[i * 2 + 1])) {
            fprintf(stderr, "CRC error for reading %d\n", i);
            return;
        }
    }
}

void stopMeasurement() {
    pigpioI2CStop(pi);
    pigpioClose(pi);
    pigpioWriteReg32(PIGPIO_BASE + PIGPIO_IDR, PIGPIO_IDR_DISABLE);
}

int main() {
    char logDir[256];
    char *csvFileName;
    int fd;

    // Initialize logging directory
    snprintf(logDir, sizeof(logDir), "/var/log/scd40_data/");
    if (!mkdir(logDir, 0755)) {
        perror("Failed to create log directory");
        return EXIT_FAILURE;
    }

    // Open CSV file for logging
    csvFileName = fopen(logDir "/timestamped.csv", "w+");
    if (!csvFileName) {
        perror("Failed to open CSV file for logging");
        return EXIT_FAILURE;
    }

    // Open error log file
    errorFile = fopen("/var/log/scd40_error.log", "a+");
    if (!errorFile) {
        perror("Failed to open error log file");
        fclose(csvFileName);
        return EXIT_FAILURE;
    }

    // Initialize thread
    pthread_create(&loggingThread, NULL, loggingThreadFunc, NULL);

    // Main loop
    while (running) {
        if (stopSignal) {
            stopMeasurement();
            stopSignal = 0;
            break;
        }

        startMeasurement();
        readMeasurement();

        // Convert readings
        for (int i = 0; i < 100; i++) {
            if (readData[i].co2 && readData[i].temperature && readData[i].humidity) {
                readData[i].timestamp = time(NULL);
                readData[i].co2 /= 256; // Convert from 12-bit to ppm
                readData[i].temperature = -45 + 175 * (readData[i].temperature / 65535.0);
                readData[i].humidity = 100 * (readData[i].humidity / 65535.0);
            }
        }

        // Check if buffer is full and flush to CSV
        if (i >= 100) {
            pthread_mutex_lock(&readDataMutex);
            if (i == 100) {
                pthread_cond_signal(&readDataCondVar);
            } else {
                pthread_cond_wait(&readDataCondVar, &readDataMutex);
            }
            pthread_mutex_unlock(&readDataMutex);
        }
    }

    // Stop logging thread
    pthread_join(loggingThread, NULL);

    // Flush remaining buffer data to final CSV file
    for (int i = 0; i < 100 && readData[i].timestamp != 0; i++) {
        fprintf(errorFile, "%d,%d,%f,%f,", readData[i].timestamp, readData[i].co2, readData[i].temperature, readData[i].humidity);
    }
    fprintf(errorFile, "\n");

    fclose(csvFile);
    fclose(errorFile);

    return EXIT_SUCCESS;
}

