            fprintf(stderr, "Failed to write to pressure register: %s\n", strerror(errno));
            return;
        }

        // Wait 10 ms
        usleep(10000);

        // Read pressure data
        if (i2cRead(PRESSURE_REG, PRESSURE_REG_LENGTH, pressureData, PRESSURE_REG_LENGTH) < 0) {
            fprintf(stderr, "Failed to read pressure data: %s\n", strerror(errno));
            return;
        }

        // Convert pressure data to hPa
        float pressureValue = pressureData[0] * PRESSURE_CONVERSION_FACTOR + pressureData[1] * 0.0625;

        // Read temperature data
        if (i2cRead(TEMP_REG, TEMP_REG_LENGTH, &temperatureData, 1) < 0) {
            fprintf(stderr, "Failed to read temperature data: %s\n", strerror(errno));
            return;
        }

        // Convert temperature data to Celsius
        float temperatureValue = temperatureData * TEMP_CONVERSION_FACTOR;

        // Append timestamped data to environmental_data.txt
        char timestamp[50];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%fZ", localtime(&now));
        FILE *file = fopen("environmental_data.txt", "a+");
        if (file == NULL) {
            fprintf(stderr, "Failed to open environmental_data.txt for append: %s\n", strerror(errno));
            fclose(file);
            return;
        }
        fprintf(file, "%s, Pressure: %.2f hPa, Temperature: %.1f °C\n", timestamp, pressureValue, temperatureValue);
        fclose(file);

        // Print to stdout
        printf("Pressure: %.2f hPa, Temperature: %.1f °C\n", pressureValue, temperatureValue);
    }

    // SIGINT handler
    void handleSIGINT(int signum) {
        fprintf(stderr, "SIGINT received, exiting gracefully...\n");
        _exit(0); // Exit immediately
    }
