#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define PIGPIO_ID 0  // Use the default pigpio instance
#define I2C_BUS 1    // I2C bus 1
#define MLX90614_ADDR 0x5A  // Default address of the MLX90614
#define GPIO_FAN 18  // GPIO 18 for controlling the fan

// Function prototypes
void handleSIGINTSIGTERM(void);
void readTemperature(struct pigpio *pgpio, float *ambient, float *object);
void controlFan(struct pigpio *pgpio, float objectTemp);
void cleanupResources(struct pigpio *pgpio);

int main() {
    struct pigpio *pgpio;
    float ambientTemp, objectTemp;
    int i2cOpenResult, readResult;
    time_t timestamp;

    // Initialize pigpio
    if ((pgpio = pigpio_open(PIGPIO_ID)) == NULL) {
        fprintf(stderr, "Failed to open pigpio: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }

    // Register signal handlers
    signal(SIGINT, handleSIGINTSIGTERM);
    signal(SIGTERM, handleSIGINTSIGTERM);

    // Attempt to open I2C bus 1
    if ((i2cOpenResult = pigpio_i2c_open(pgpio, I2C_BUS)) != PIGPIO_OK) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", pigpio_i2c_error());
        pigpio_close(pgpio);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        timestamp = time(NULL);
        // Attempt to read temperatures up to 3 times if necessary
        for (i = 0; i < 3; i++) {
            if ((readResult = pigpio_i2c_read(pgpio, I2C_BUS, MLX90614_ADDR, 0x06, &ambientTemp)) != PIGPIO_OK) {
                fprintf(stderr, "Failed to read ambient temperature: %s\n", pigpio_i2c_error());
                sleep(10); // Delay before retrying
                continue;
            }
            if ((readResult = pigpio_i2c_read(pgpio, I2C_BUS, MLX90614_ADDR, 0x07, &objectTemp)) != PIGPIO_OK) {
                fprintf(stderr, "Failed to read object temperature: %s\n", pigpio_i2c_error());
                sleep(10); // Delay before retrying
                continue;
            }
            break; // Successful reads, proceed to processing
        }

        if (i == 3) {
            fprintf(stderr, "Failed to read temperatures after 3 attempts.\n");
            continue; // Skip this iteration
        }

        // Control the fan based on object temperature
        controlFan(pgpio, objectTemp);

        // Log the readings
        FILE *temperature_log = fopen("temperature_log.txt", "a+");
        if (temperature_log != NULL) {
            fprintf(temperature_log, "%s: Ambient: %.1f °C, Object: %.1f °C\n", ctime(&timestamp), ambientTemp, objectTemp);
            fclose(temperature_log);
        }

        // Delay for 2 seconds
        sleep(2);
    }

    // Cleanup resources on SIGINT/SIGTERM
    handleSIGINTSIGTERM();

    // Close I2C bus and pigpio
    cleanupResources(pgpio);

    return 0;
}

// Handle SIGINT and SIGTERM signals
void handleSIGINTSIGTERM(void) {
    fprintf(stderr, "Shutting down...\n");
    cleanupResources(NULL);
    pigpio_close(pgpio);
    exit(EXIT_SUCCESS);
}

// Read temperature from the MLX90614 sensor
void readTemperature(struct pigpio *pgpio, float *ambient, float *object) {
    int readResult;

    // Attempt to read ambient temperature
    if ((readResult = pigpio_i2c_read(pgpio, I2C_BUS, MLX90614_ADDR, 0x06, ambient)) != PIGPIO_OK) {
        fprintf(stderr, "Failed to read ambient temperature: %s\n", pigpio_i2c_error());
        return;
    }

    // Convert raw ambient temperature to Celsius
    *ambient = (*ambient * 0.02) - 273.15;

    // Attempt to read object temperature
    if ((readResult = pigpio_i2c_read(pgpio, I2C_BUS, MLX90614_ADDR, 0x07, object)) != PIGPIO_OK) {
        fprintf(stderr, "Failed to read object temperature: %s\n", pigpio_i2c_error());
        return;
    }

    // Convert raw object temperature to Celsius
    *object = (*object * 0.02) - 273.15;
}

// Control the cooling fan based on object temperature with hysteresis
void controlFan(struct pigpio *pgpio, float objectTemp) {
    if (objectTemp > 30.0) {
        // Turn the fan on
        pigpio_write(pgpio, GPIO_FAN, 1);
    } else if (objectTemp < 28.0) {
        // Turn the fan off
        pigpio_write(pgpio, GPIO_FAN, 0);
    }
}

// Cleanup resources
void cleanupResources(struct pigpio *pgpio) {
    if (pgpio != NULL) {
        pigpio_i2c_close(I2C_BUS);
        pigpio_close(pgpio);
    }
}

