#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <ctype.h>
#include <pigpio.h>
#include <stdint.h>

#define PIGPIO_PORT 0
#define SHT40_ADDR 0x44
#define SHT40_CMD 0xFD
#define SHT40_READ_LEN 6

// Sensor data conversion functions
float convertTemperature(uint16_t raw_T) {
    return -45 + 175 * (raw_T / 65535.0);
}

float convertHumidity(uint16_t raw_RH) {
    return -6 + 125 * (raw_RH / 65535.0);
}

// Clamping humidity to 0-100%
float clampHumidity(float rh) {
    return fminf(rh, 100.0);
}

// Main function
int main() {
    // Signal handlers
    struct sigaction intHandler, termHandler;
    sigemptyset(&intHandler.sa_mask);
    intHandler.sa_handler = SIG_IGN;
    sigaction(SIGINT, &intHandler, NULL);
    sigemptyset(&termHandler.sa_mask);
    termHandler.sa_handler = cleanup;
    sigaction(SIGTERM, &termHandler, NULL);

    // Initialize pigpio
    if (pigpioSetup(PIGPIO_PORT) == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpioError());
        return EXIT_FAILURE;
    }

    // Attempt to claim I2C bus 1
    if (pigpioI2CClaim(PIGPIO_PORT, 1) == -1) {
        fprintf(stderr, "Failed to claim I2C bus 1: %s\n", pigpioError());
        pigpioExit();
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Attempt to communicate with the SHT40 sensor
        for (int retry = 0; retry < 3; ++retry) {
            pigpioI2CWrite(PIGPIO_PORT, SHT40_ADDR, SHT40_CMD);
            usleep(10000); // Wait at least 10 ms

            uint8_t data[6];
            if (pigpioI2CRead(PIGPIO_PORT, SHT40_ADDR, data, SHT40_READ_LEN) == -1) {
                fprintf(stderr, "Failed to read from SHT40: %s\n", pigpioError());
                continue;
            }

            uint16_t raw_T = (data[0] << 8) | data[1];
            uint16_t raw_RH = (data[2] << 8) | data[3];

            float temperature = convertTemperature(raw_T);
            float humidity = convertHumidity(raw_RH);
            humidity = clampHumidity(humidity);

            // Construct and send HTTP response
            char response[256];
            sprintf(response, "HTTP/1.1 200 OK\r\n"
                             "Content-Type: text/html\r\n"
                             "Content-Length: %zu\r\n"
                             "\r\n",
                             strlen("<html><body>Temperature: %.2f°C, Humidity: %.2f%%</body></html>") + 1);
            write(8080, response, strlen(response));

            sprintf(response, "<html><body>Temperature: %.2f°C, Humidity: %.2f%%</body></html>",
                     temperature, humidity);
            write(8080, response, strlen(response));
        }

