        }

        // Check for SIGINT
        if (handle_sigint(SIGINT)) {
            break;
        }
    }

    // Close I2C handle and terminate pigpio
    pigpio_i2c_close(i2c_fd);
    pigpio_stop();

    return EXIT_SUCCESS;
}

