        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

// Function to read temperature from TMP102
int read_temperature(uint8_t bus, int address, float *temperature) {
    int i2c_fd = pigpio_i2c_open(bus, NULL);
    if (i2c_fd == -1) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }

    // Write to TMP102 register 0x00
    uint8_t command = 0x01; // Read temperature command
    pigpio_i2c_write(i2c_fd, address, &command, 1);

    // Read two bytes from register 0x00
    uint8_t data[2];
    pigpio_i2c_read(i2c_fd, address, data, 2);

    // Combine the two bytes into a 12-bit value
    uint16_t raw_temperature = (data[0] << 8) | data[1];

    // Shift right by 4 bits and convert to Celsius
    *temperature = (raw_temperature >> 4) * 0.0625;

    // Close I2C handle
    pigpio_i2c_close(i2c_fd);

    return 0;
}

// Function to write to CSV file
void write_to_csv(const char *timestamp, float temperature) {
    FILE *csv_file = fopen("temperature_log.csv", "a");
    if (!csv_file) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        return;
    }

    fprintf(csv_file, "%s,%f\n", timestamp, temperature);
    fclose(csv_file);
}

// Function to handle SIGINT
int handle_sigint(int signum) {
    // Close I2C handle and terminate pigpio
    pigpio_i2c_close(-1);
    pigpio_stop();

    // Exit gracefully
    return 1;
}

