#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>

// Define GPIO pin for pigpio termination
#define PI_GPIO_NUM 7

// Define maximum retry count for I2C operations
#define MAX_RETRIES 5

// Sensor I2C address and registers
#define I2C_ADDRESS 0x40
#define MEASUREMENT_CONFIG_REG 0x0E
#define CONFIG_REG 0x0F
#define TEMPERATURE_REG 0x00
#define HUMIDITY_REG 0x02

volatile sig_atomic_t should_exit = 0;

// Function prototypes
void handleInterrupt(int signum);
void readTemperatureAndHumidity();
void cleanup();

int main() {
    // Initialize pigpio
    if (gpioInitialise() == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Install signal handler for Ctrl+C
    signal(SIGINT, handleInterrupt);

    // Main loop
    while (!should_exit) {
        // Wait for 5 seconds
        sleep(5);

        // Attempt to read temperature and humidity
        if (readTemperatureAndHumidity()) {
            continue;
        }

        // If failed, retry up to MAX_RETRIES
        if (++failedAttempts >= MAX_RETRIES) {
            fprintf(stderr, "Failed to read sensor data after %d attempts.\n", failedAttempts);
            break;
        }

        // Wait for a short period before retrying
        sleep(1);
    }

    // Clean up
    cleanup();

    // Terminate pigpio
    gpioTerminate();

    return EXIT_SUCCESS;
}

// Signal handler for Ctrl+C
void handleInterrupt(int signum) {
    should_exit = 1;
}

// Function to read temperature and humidity
int readTemperatureAndHumidity() {
    int retries = 0;
    while (true) {
        // Write to MEASUREMENT_CONFIG to start measurement
        if (pigpioI2CWrite(I2C_ADDRESS, MEASUREMENT_CONFIG_REG, 0x01) < 0) {
            fprintf(stderr, "Failed to write to MEASUREMENT_CONFIG: %s\n", pigpioError());
            return 0;
        }

        // Poll MEASUREMENT_CONFIG until bit 0 clears or timeout
        while ((pigpioI2CRead(I2C_ADDRESS, MEASUREMENT_CONFIG_REG) & 0x01) != 0) {
            if (retries++ >= MAX_RETRIES) {
                fprintf(stderr, "Timeout while waiting for measurement configuration bit to clear.\n");
                return 0;
            }
            sleep(1); // Short delay to avoid busy loop
        }

        // Read temperature and humidity
        uint16_t tempRaw = pigpioI2CRead(I2C_ADDRESS, TEMPERATURE_REG);
        uint16_t humRaw = pigpioI2CRead(I2C_ADDRESS, HUMIDITY_REG);

        // Convert raw values to temperature and humidity
        int temperature = (tempRaw / 65536) * 165 - 40;
        int humidity = (humRaw / 65536) * 100;

        // Check for NAK (sensor absent) or bus error
        if ((tempRaw == 0xFFFF) || (humRaw == 0xFFFF)) {
            fprintf(stderr, "Sensor absent or bus error detected.\n");
            return 0;
        }

        return 1; // Success
    }
}

// Function to cleanup resources
void cleanup() {
    // Close I2C handle
    pigpioI2CClose();

    // Terminate GPIO
    gpioTerminate();
}

