#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>

// Define the CRC polynomial and initial value
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT_VALUE 0xFF

// Sensor address and command for continuous measurement
#define SDP800_ADDRESS 0x25
#define CONTINUOUS_MEASUREMENT_CMD 0x362F

// Sensor data structure
typedef struct {
    uint16_t pressure;
    uint16_t temperature;
    uint8_t crcPressure;
    uint8_t crcTemperature;
} SensorData;

// Function prototypes
void initializePigpio();
void handleSIGINT(int signum);
void readSensorData(uint8_t command);
void checkCRC(uint8_t data, uint8_t crc);
void printSensorData(const SensorData *data);
void cleanup();

int main() {
    // Signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, handleSIGINT);

    // Initialize pigpio
    initializePigpio();

    // Main loop
    while (1) {
        // Wait for 500 ms
        struct timespec timeout = { .tv_sec = 0, .tv_nsec = 500000000 };
        nanosleep(&timeout, NULL);

        // Send continuous measurement command
        readSensorData(CONTINUOUS_MEASUREMENT_CMD);

        // Read sensor data
        SensorData data;
        readSensorData(0x00); // Read 6 bytes

        // Check CRC and print data
        checkCRC(data.crcPressure, data.crcTemperature);
        printSensorData(&data);

        // Cleanup resources
        cleanup();
    }

    return 0;
}

// Function to initialize pigpio
void initializePigpio() {
    if (pigpioSetup(0) == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }

    // Open I2C bus 1
    if (pigpioI2COpen(1) == -1) {
        fprintf(stderr, "Failed to open I2C bus 1: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }
}

// Function to handle SIGINT signal
void handleSIGINT(int signum) {
    // Clean up resources
    cleanup();

    // Exit the program
    exit(EXIT_SUCCESS);
}

// Function to read sensor data
void readSensorData(uint8_t command) {
    if (pigpioI2CWrite(SDP800_ADDRESS, command, 1) == -1) {
        fprintf(stderr, "Failed to write command to sensor: %s\n", pigpioError());
        return;
    }

    // Wait for measurement completion (about 45 ms)
    uint32_t timeout = 45000;
    while (pigpioI2CReadTimeout(SDP800_ADDRESS, 6, &timeout) == -1) {
        if (errno != EAGAIN) {
            fprintf(stderr, "Failed to read from sensor: %s\n", strerror(errno));
            return;
        }
    }
}

// Function to check CRC
void checkCRC(uint8_t data, uint8_t crc) {
    uint8_t calculatedCRC = crc8(data, CRC_POLYNOMIAL, CRC_INIT_VALUE);

    if (calculatedCRC != crc) {
        fprintf(stderr, "CRC error for data: %02X, expected %02X, got %02X\n", data, crc, calculatedCRC);
        exit(EXIT_FAILURE);
    }
}

// Function to print sensor data
void printSensorData(const SensorData *data) {
    printf("Pressure: %04X, Temperature: %04X, CRC Pressure: %02X, CRC Temperature: %02X\n",
           data->pressure, data->temperature, data->crcPressure, data->crcTemperature);
}

// Function to cleanup resources
void cleanup() {
    // Close I2C bus
    pigpioI2CClose(1);

    // Terminate pigpio
    pigpioTerminate();
}

