    uint32_t timeout = 45000;
    while (pigpioI2CReadTimeout(SDP800_ADDRESS, 6, &timeout) == -1) {
        if (errno != EAGAIN) {
            fprintf(stderr, "Failed to read from sensor: %s\n", strerror(errno));
            return;
        }
    }
}

// Function to check CRC
void checkCRC(uint8_t data, uint8_t crc) {
    uint8_t calculatedCRC = crc8(data, CRC_POLYNOMIAL, CRC_INIT_VALUE);

    if (calculatedCRC != crc) {
        fprintf(stderr, "CRC error for data: %02X, expected %02X, got %02X\n", data, crc, calculatedCRC);
        exit(EXIT_FAILURE);
    }
}

// Function to print sensor data
void printSensorData(const SensorData *data) {
    printf("Pressure: %04X, Temperature: %04X, CRC Pressure: %02X, CRC Temperature: %02X\n",
           data->pressure, data->temperature, data->crcPressure, data->crcTemperature);
}

// Function to cleanup resources
void cleanup() {
    // Close I2C bus
    pigpioI2CClose(1);

    // Terminate pigpio
    pigpioTerminate();
}

