    while (fgets(line, sizeof(line), profile_file)) {
        char *tokens[3] = { line, NULL, NULL };
        float time_seconds, target_temp_celsius;

        // Parse line into time and temperature
        if (sscanf(line, "%f,%f", &time_seconds, &target_temp_celsius) != 2) {
            fprintf(stderr, "Invalid temperature profile line: %s\n", line);
            continue;
        }

        // Process temperature profile
        float setpoint = target_temp_celsius;
        float output;
        pid_controller(0, setpoint, PID_GAIN, PID_INTEGRAL_TIME, PID_DERIVATIVE_TIME, &output);

