    }

    fclose(profile_file);

    // Clean up resources
    cleanup_resources();

    return 0;
}

// PID controller function
void pid_controller(uint16_t temp, float setpoint, float kp, float ki, float kd, float *output) {
    float error = setpoint - temp;
    *output = kp * error + ki * (error - prev_error) + kd * (error - last_error);
    prev_error = error;
    last_error = error;
}

// MAX6675 read temperature function
void max6675_read_temperature(uint8_t command) {
    int fd;
    struct spi_ioc_transfer tx[] = {
        SPI_IOC_MESSAGE(1),
        SPI_XFER(TXBUF(command)),
        SPI_XFER(RXBUF(2)),
    };

    fd = open(SPI_DEVICE, O_RDWR);
    if (fd == -1) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) == -1) {
        perror("Failed to set SPI speed");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, SPI_IOC_MESSAGE(sizeof(tx)), tx) == -1) {
        perror("Failed to send SPI transaction");
        exit(EXIT_FAILURE);
    }

    close(fd);
}

// Setup SPI communication
void setup_spi() {
    int spi_speed = 1000000; // 1 MHz
    struct spi_ioc_transfer settings[] = {
        SPI_IOC_MESSAGE(1),
        SPI_XFER(TXBUF(spi_speed)),
        SPI_XFER(RXBUF(0)),
    };

    if (ioctl(SPI_DEVICE, SPI_IOC_WR_MODE, &SPI_MODE_0) == -1) {
        perror("Failed to set SPI mode");
        exit(EXIT_FAILURE);
    }

    if (ioctl(SPI_DEVICE, SPI_IOC_WR_BAUDRATE, &spi_speed) == -1) {
        perror("Failed to set SPI baudrate");
        exit(EXIT_FAILURE);
    }

    if (ioctl(SPI_DEVICE, SPI_IOC_MESSAGE(sizeof(settings)), settings) == -1) {
        perror("Failed to set SPI settings");
        exit(EXIT_FAILURE);
    }
}

// Setup GPIO using libgpiod
void setup_gpiod() {
    gpiod_set_data_direction(GPIO_RELAY, GPIODIRECTION_OUTPIN);
    gpiod_direction_output(GPIO_RELAY, 1); // Set GPIO17 as output
}

// Write temperature data to log file
void write_to_log(float temperature) {
    FILE *log_file = fopen(REFLOW_LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open reflow log file");
        exit(EXIT_FAILURE);
    }

    fprintf(log_file, "%f\n", temperature);
    fclose(log_file);
}

// Cleanup resources
void cleanup_resources() {
    gpiod_free gpio_rel;
    close(SPI_DEVICE);
}

// Signal handler for clean exit
void signal_handler(int signum) {
    // Clean up resources immediately
    cleanup_resources();
    exit(EXIT_SUCCESS);
}

