#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <gpiod.h>
#include <math.h>

#define GPIO_RELAY 17
#define GPIO_PWM 18
#define GPIO_TEMPERATURE 4

#define DS18B20_PATH "/sys/bus/w1/devices/28-000006acef4c/w1_slave"

#define SETPOINT_ARG 1
#define KP_ARG 2
#define KI_ARG 3
#define KD_ARG 4

#define LOG_FILE_PATH "greenhouse.log"

int main(int argc, char *argv[]) {
    // Check for required arguments
    if (argc < 5) {
        fprintf(stderr, "Usage: %s <setpoint> <Kp> <Ki> <Kd>\n", argv[0]);
        return EXIT_FAILURE;
    }

    double setpoint = atof(argv[SETPOINT_ARG]);
    double kp = atof(argv[KP_ARG]);
    double ki = atof(argv[KI_ARG]);
    double kd = atof(argv[KD_ARG]);

    // Initialize GPIO
    int relay_fd = gpiod_open(GPIO_RELAY, GPIOD_OPEN_OWN);
    if (relay_fd < 0) {
        perror("Failed to open GPIO relay");
        return EXIT_FAILURE;
    }

    int pwm_fd = gpiod_open(GPIO_PWM, GPIOD_OPEN_OWN);
    if (pwm_fd < 0) {
        perror("Failed to open GPIO PWM");
        gpiod_close(relay_fd);
        return EXIT_FAILURE;
    }

    // Initialize PID controller
    double error;
    double prev_error = 0;
    double output = 0;
    double last_temperature;

    // Open DS18B20 sensor file
    char ds18b20_path[256];
    strcpy(ds18b20_path, DS18B20_PATH);
    int sensor_fd = open(ds18b20_path, O_RDONLY);
    if (sensor_fd < 0) {
        perror("Failed to open DS18B20 sensor");
        gpiod_close(relay_fd);
        gpiod_close(pwm_fd);
        close(sensor_fd);
        return EXIT_FAILURE;
    }

    // Read temperature
    while (1) {
        char temp_data[9];
        ssize_t bytes_read = read(sensor_fd, temp_data, 9);
        if (bytes_read < 0) {
            perror("Failed to read from DS18B20");
            break;
        }

        // Check CRC
        char crc;
        bytes_read = fscanf(sensor_fd, "%c", &crc);
        if (bytes_read != 1 || crc != '\n') {
            fprintf(stderr, "CRC error in temperature reading\n");
            break;
        }

        // Parse temperature
        char temp_str[9];
        bytes_read = fscanf(sensor_fd, "%9s", temp_str);
        if (bytes_read != 1) {
            fprintf(stderr, "Failed to parse temperature reading\n");
            break;
        }

        double temperature = atof(temp_str) / 1000.0;
        if (temperature == last_temperature) {
            output = 0; // No change in temperature, no PID output
        } else {
            error = temperature - setpoint;
            output = kp * error + ki * (error - prev_error) + kd * (error - prev_error / (double) 0.01);
            prev_error = error;
        }

        // Update PID output and PWM duty cycle
        int duty_cycle = (int)(output * 1023.0); // 0-1023 range for PWM
        gpiod_set_value(pwm_fd, duty_cycle);

        // Log data
        struct tm time_info;
        time(&time_info);
        char log_entry[256];
        sprintf(log_entry, "%s %lf %lf %lf %d\n",
                ctime(&time_info.tm_time),
                temperature,
                setpoint,
                output,
                duty_cycle);

        // Append to log file
        FILE *log_file = fopen(LOG_FILE_PATH, "a+");
        if (log_file == NULL) {
            perror("Failed to open log file for appending");
            break;
        }
        fwrite(log_entry, sizeof(log_entry[0]), strlen(log_entry), log_file);
        fclose(log_file);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up
    gpiod_set_value(pwm_fd, 0); // Set PWM to 0
    gpiod_close(pwm_fd);
    gpiod_close(relay_fd);
    close(sensor_fd);

    return EXIT_SUCCESS;
}

