#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <libgpiod.h>
#include <stdint.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>

#define I2C_ADDR 0x38
#define DEHUMIDIFIER_GPIO 17

// AHT20 commands and data structure
#define AHT20_CMD_MEASURE 0xAC
#define AHT20_CMD_START 0xBE
#define AHT20_CMD_END 0x00

#define AHT20_DATA_LEN 6

typedef struct {
    uint8_t crc;
    uint8_t t;
    uint8_t pressure;
    uint8_t humidity;
    uint16_t temperature;
    uint16_t altitude;
} aht20_data;

// Function prototypes
void aht20_init();
int read_aht20(uint8_t addr, uint8_t command, uint8_t* data, int len);
void handle_dehumidifier(bool active);

int main() {
    // Initialize GPIO and I2C
    if (gpiod_open(GPIOD_DIR_OUTPUT, DEHUMIDIFIER_GPIO) < 0) {
        perror("Failed to open GPIO");
        exit(EXIT_FAILURE);
    }
    if (libgpiod_i2c_open("/dev/i2c-1") < 0) {
        perror("Failed to open I2C");
        exit(EXIT_FAILURE);
    }

    // Install signal handlers
    struct sigaction sa;
    sa.sa_handler = SIG_IGN;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        // Check for signals
        if (sigpending(&sa)) {
            sigprocmask(SIG_UNBLOCK, &sa.sa_mask, NULL);
            if (sa.sa_handler == SIGINT) {
                printf("SIGINT received, exiting...\n");
                break;
            }
            if (sa.sa_handler == SIGTERM) {
                printf("SIGTERM received, exiting...\n");
                break;
            }
            sigprocmask(SIG_BLOCK, &sa.sa_mask, NULL);
        }

        // AHT20 initialization
        aht20_init();

        // Poll AHT20 every 5 seconds
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        ts.tv_sec += 5;
        clock_nanosleep(CLOCK_REALTIME, 0, &ts, NULL);

        // Attempt to read AHT20 data
        uint8_t data[AHT20_DATA_LEN];
        int bytes_read = read_aht20(I2C_ADDR, AHT20_CMD_MEASURE, data, AHT20_DATA_LEN);

        if (bytes_read < AHT20_DATA_LEN) {
            // Retry I2C transaction up to 3 times
            for (int i = 0; i < 3; ++i) {
                usleep(10000); // 10 ms delay
                bytes_read = read_aht20(I2C_ADDR, AHT20_CMD_MEASURE, data, AHT20_DATA_LEN);
                if (bytes_read == AHT20_DATA_LEN) {
                    break;
                }
            }

            // If still failed, log error and continue
            if (bytes_read < AHT20_DATA_LEN) {
                fprintf(stderr, "Failed to read AHT20 data after retries\n");
                continue;
            }
        }

        // Check if sensor is calibrated and not busy
        if (data[1] != 0x00) {
            fprintf(stderr, "AHT20 not calibrated or busy\n");
            continue;
        }

        // Process humidity reading
        float humidity = (float)data[3] / 256.0;
        if (humidity > 60.0) {
            handle_dehumidifier(true);
        } else if (humidity < 55.0) {
            handle_dehumidifier(false);
        }

        // Log reading with timestamp
        char buffer[256];
        time_t now = time(NULL);
        struct tm tm_now;
        localtime_r(&now, &tm_now);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", &tm_now);
        fprintf(stderr, "Humidity: %.1f%% at %s\n", humidity * 100, buffer);
    }

    // Clean up on exit
    gpiod_close(DEHUMIDIFIER_GPIO);
    libgpiod_i2c_close();

    return 0;
}

// AHT20 initialization function
void aht20_init() {
    uint8_t cmd_start[] = { AHT20_CMD_START, 0x00 };
    uint8_t cmd_end[] = { AHT20_CMD_END, 0x00 };

    libgpiod_i2c_write(I2C_ADDR, cmd_start, 2);
    usleep(5000); // Wait for initialization
    libgpiod_i2c_write(I2C_ADDR, cmd_end, 2);
}

// Function to read data from AHT20 sensor
int read_aht20(uint8_t addr, uint8_t command, uint8_t* data, int len) {
    int bytes_read = 0;
    while (bytes_read < len) {
        ssize_t ret = libgpiod_i2c_write(addr, command, 1);
        if (ret < 0) {
            fprintf(stderr, "I2C write error: %s\n", strerror(errno));
            return bytes_read;
        }
        ret = libgpiod_i2c_read(addr, data + bytes_read, 1);
        if (ret < 1) {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            return bytes_read;
        }
        bytes_read++;
    }

    return bytes_read;
}

// Function to handle the dehumidifier relay
void handle_dehumidifier(bool active) {
    if (active) {
        gpiod_set_data(DEHUMIDIFIER_GPIO, GPIOD_DATA_HIGH);
    } else {
        gpiod_set_data(DEHUMIDIFIER_GPIO, GPIOD_DATA_LOW);
    }
}

