#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/stat.h>
#include <sys/mman.h>
#include <errno.h>
#include <time.h>
#include <syslog.h>

#define SENSOR_ADDR 0x40
#define I2C_DEVICE "/dev/i2c-1"
#define POST_URL "http://api.example.com/humidity"
#define POST_BODY "{\"humidity\":%u}"

#define BUF_SIZE 1024

// Structure for HTU21D sensor data
typedef struct {
    uint8_t crc;
    uint8_t command;
    uint16_t t;
    uint16_t h;
} HTU21D_Data;

// Function prototypes
void i2c_init();
int i2c_read(uint8_t addr, uint8_t reg, void *data, size_t len);
int i2c_write(uint8_t addr, uint8_t reg, uint8_t data);
void http_post(char *url, char *body);
void handle_signal(int signum);
void cleanup();

int main() {
    struct sigaction sa;
    struct tm *tm;
    time_t now;
    char buffer[BUF_SIZE];
    int i2c_fd, http_fd;
    HTU21D_Data data;

    // Set up signal handlers
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize I2C
    i2c_init();

    while (1) {
        // Check for signals
        if (wait(NULL) > 0) {
            break;
        }

        // Get current time
        now = time(NULL);
        tm = localtime(&now);

        // Convert time to a string
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm);

        // Read humidity data from the sensor
        if (i2c_read(SENSOR_ADDR, 0x00, &data, sizeof(data)) < 0) {
            syslog(LOG_ERR, "I2C read error: %s", strerror(errno));
            continue;
        }

        // Check if CRC is valid
        if (data.crc != 0x00) {
            syslog(LOG_ERR, "CRC mismatch from HTU21D sensor");
            continue;
        }

        // Format humidity data for POST request
        sprintf(buffer, POST_BODY, data.h);

        // Perform HTTP POST
        http_post(POST_URL, buffer);

        // Log the operation
        syslog(LOG_INFO, "Humidity posted at %s: %s", time_str, buffer);
    }

    // Clean up resources
    cleanup();

    return 0;
}

// Function to initialize I2C
void i2c_init() {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd == -1) {
        syslog(LOG_ERR, "Failed to open I2C device: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Ensure I2C device is writable
    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address: %s", strerror(errno));
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

// Function to read from the I2C device
int i2c_read(uint8_t addr, uint8_t reg, void *data, size_t len) {
    int bytes_read = 0;

    // Write register address to the sensor
    if (i2c_write(addr, reg, 0) < 0) {
        return -1;
    }

    // Read data from the sensor
    bytes_read = read(i2c_fd, data, len);

    // Check for NACK or other I2C errors
    if (bytes_read != len) {
        syslog(LOG_ERR, "I2C read error: %s", strerror(errno));
        return -1;
    }

    return bytes_read;
}

// Function to write to the I2C device
int i2c_write(uint8_t addr, uint8_t reg, uint8_t data) {
    int bytes_written = 0;

    // Write register address and data to the sensor
    if (write(i2c_fd, &reg, 1) < 0 || write(i2c_fd, &data, 1) < 0) {
        return -1;
    }

    bytes_written = 2;

    // Check for write errors
    if (bytes_written != 2) {
        syslog(LOG_ERR, "I2C write error: %s", strerror(errno));
        return -1;
    }

    return bytes_written;
}

// Function to perform HTTP POST
void http_post(char *url, char *body) {
    struct sockaddr_in server_addr;
    int sockfd;

    // Initialize the server address structure
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(80); // Assuming HTTP port 80
    // Assuming the server's IP address is 127.0.0.1
    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);

    // Create a socket
    sockfd = socket(AF_INET, SOCK_STREAM, 0);

    // Connect to the server
    if (connect(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        syslog(LOG_ERR, "Failed to connect to HTTP server: %s", strerror(errno));
        close(sockfd);
        return;
    }

    // Prepare POST data
    size_t post_len = strlen(body) + 1;

    // Send POST data
    if (write(sockfd, body, post_len) != post_len) {
        syslog(LOG_ERR, "Failed to send POST data: %s", strerror(errno));
        close(sockfd);
        return;
    }

    // Close the socket
    close(sockfd);
}

// Signal handler to perform cleanup and exit
void handle_signal(int signum) {
    syslog(LOG_INFO, "Received signal %d, exiting...", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

// Function to clean up resources
void cleanup() {
    // Close I2C file descriptor
    close(i2c_fd);

    // Close HTTP socket (if it was opened)
    if (http_fd != -1) {
        close(http_fd);
    }
}

