#define TMP117_ADDR 0x48
#define TMP117_REG_TEMPERATURE 0x00

// AHT20 I2C address and commands
#define AHT20_ADDR 0x38
#define INIT_CMD 0xBE
#define MEASURE_CMD AHT20_MEASURE_CMD

// Sensor data interpretation
#define AHT20_HUMIDITY_OFFSET 0x1FA0
#define AHT20_TEMPERATURE_OFFSET 0x1FE0

// TMP117 temperature interpretation
#define TMP117_TEMP_OFFSET 0x0000
#define TMP117_SCALE 0x07E0

// GPIO for PIR sensor
#define PIR_INPUT_LINE gpiochip4_line_17

// GPIO direction for PIR input
#define PIR_INPUT_DIR GPIO_DIR_IN

// Maximum I2C retries
#define MAX_RETRIES 3

// Backoff time in ms
#define BACKOFF_MS 10

// CSV header
#define CSV_HEADER "Timestamp,Temperature(C),Humidity(%),MotionDetected"

// Function prototypes
void init_sensors(void);
int read_tpm117_temp(int fd);
int read_aht20(int fd);
int check_pir_status(void);
void log_data(float temperature, float humidity, int motion_detected);
void cleanup_resources(void);
void signal_handler(int signum);

int main(void) {
    srand(time(NULL));
    struct timespec ts;
    int fd_i2c, fd_tpm117, fd_aht20;
    int pir_status;
    float temperature, humidity;
    char buffer[AHT20_DATA_LENGTH];
    unsigned int retries = 0;

    // Initialize sensors
    init_sensors();

    while (1) {
        // Check PIR status
        pir_status = check_pir_status();

        // Sample sensors
        if (!pir_status) {
            temperature = read_tpm117_temp(fd_tpm117);
            humidity = read_aht20(fd_aht20);

            // Log data
            log_data(temperature, humidity, pir_status);

            // Handle signals
            signal_handler(SIGINT);
            signal_handler(SIGTERM);
        }

        // Sleep for 1 second
        ts.tv_sec = 1;
        ts.tv_nsec = 0;
        nanosleep(&ts, NULL);
    }

    // Clean up resources
    cleanup_resources();

    return 0;
}

// Function to initialize sensors
void init_sensors(void) {
    // Open I2C device
    fd_i2c = open("/dev/i2c-1", O_RDWR);
    if (fd_i2c == -1) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Set I2C device address
    i2c_set_address(fd_i2c, TMP117_ADDR);

    // Open TMP117 device
    fd_tpm117 = open("/dev/i2c-1", O_RDWR);
    if (fd_tpm117 == -1) {
        perror("Failed to open TMP117");
        close(fd_i2c);
        exit(EXIT_FAILURE);
    }

    // Open AHT20 device
    fd_aht20 = open("/dev/i2c-1", O_RDWR);
    if (fd_aht20 == -1) {
        perror("Failed to open AHT20");
        close(fd_tpm117);
        close(fd_i2c);
        exit(EXIT_FAILURE);
    }

    // Set AHT20 address and send init command
    i2c_master_send(fd_aht20, (uint8_t *) &INIT_CMD, 3);
    usleep(100); // Wait for initialization

    // Set AHT20 address and send measure command
    i2c_master_send(fd_aht20, (uint8_t *) &MEASURE_CMD, 3);
    buffer[0] = 0; // Busy bit
    for (int i = 1; i < AHT20_DATA_LENGTH; i++) {
        buffer[i] = i2c_master_recv(fd_aht20, 1, 0);
    }

    // Check sensor presence
    if (!check_pir_status()) {
        printf("PIR sensor not detected. Continuing without motion detection.\n");
    }
}

// Function to read temperature from TMP117
int read_tpm117_temp(int fd) {
    uint16_t raw_temp;
    int ret;

    ret = i2c_read_block_data(fd, TMP117_REG_TEMPERATURE, 1, &raw_temp, 1);
    if (ret != 1) {
        printf("Error reading TMP117 temperature.\n");
        return -1;
    }

    // Convert raw temperature to Celsius
    float temperature_c = (raw_temp >> TMP117_TEMP_OFFSET) * TMP117_SCALE / 65535.0;
    return temperature_c;
}

// Function to read humidity and temperature from AHT20
int read_aht20(int fd) {
    uint16_t humidity_raw, temperature_raw;
    int ret;

    // Read humidity raw value
    ret = i2c_read_block_data(fd, AHT20_HUMIDITY_OFFSET, 2, &humidity_raw, 2);
    if (ret != 2) {
        printf("Error reading AHT20 humidity.\n");
        return -1;
    }

    // Convert humidity raw value to percentage
    float humidity = (humidity_raw >> AHT20_HUMIDITY_OFFSET) * 0.0625;
    humidity += 0.5; // Add offset

    // Read temperature raw value
    ret = i2c_read_block_data(fd, AHT20_TEMPERATURE_OFFSET, 2, &temperature_raw, 2);
    if (ret != 2) {
        printf("Error reading AHT20 temperature.\n");
        return -1;
    }

    // Convert temperature raw value to Celsius
    float temperature_c = (temperature_raw >> AHT20_TEMPERATURE_OFFSET) * 0.0625;
    return temperature_c;
}

// Function to check PIR sensor status
int check_pir_status(void) {
    int val;

    // Read GPIO 17 value
    gpiod_get_value_relaxed(GPIO_DIR_IN, PIR_INPUT_LINE, &val);

    // PIR high means motion detected
    return val ? 1 : 0;
}

// Function to log data
void log_data(float temperature, float humidity, int motion_detected) {
    char timestamp[50];
    char line[256];

    // Format timestamp
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Build CSV line
    snprintf(line, sizeof(line), "%s,%f,%f,%d", timestamp, temperature, humidity, motion_detected);

    // Append to log file
    FILE *log_file = fopen("logger.csv", "a");
    if (log_file) {
        fprintf(log_file, "%s\n", line);
        fclose(log_file);
    } else {
        perror("Failed to open log file for append");
    }
}

// Function to cleanup resources
void cleanup_resources(void) {
    if (fd_tpm117 > 0) {
        close(fd_tpm117);
    }
    if (fd_aht20 > 0) {
        close(fd_aht20);
    }
    if (fd_i2c > 0) {
        close(fd_i2c);
    }
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    // Clean up resources immediately
    cleanup_resources();
    exit(EXIT_FAILURE);
}

