#include <time.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>

#define RAIN_SENSOR_GPIO 17
#define ENA_GPIO 22
#define IN1_GPIO 23
#define IN2_GPIO 24

#define DELAY_MS 5000  // 5 seconds delay

// Function prototypes
void setup_gpios();
void handle_rain_detection();
void handle_signal(int signum);
void cleanup();

int main() {
    // Initialize signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Set up GPIOs
    setup_gpios();

    // Main loop
    while (1) {
        // Poll the rain sensor every 2 seconds
        time_t now = time(NULL);
        struct timespec sleep_duration;
        sleep_duration.tv_sec = 2;
        sleep_duration.tv_nsec = 0;

        if (clock_nanosleep(CLOCK_REALTIME, &sleep_duration, NULL, NULL) == -1) {
            perror("clock_nanosleep");
            exit(EXIT_FAILURE);
        }

        // Check rain sensor
        if (gpiod_read(RAIN_SENSOR_GPIO) == 0) {
            handle_rain_detection();
        }

        // Sleep for the remainder of the 2 seconds
        usleep((2 - (time(NULL) - now)) * 1000000);
    }

    // Clean up on exit
    cleanup();

    return 0;
}

// Function to setup GPIOs
void setup_gpios() {
    int ena_status;
    int in1_status;
    int in2_status;

    // Open GPIO controller
    if (gpiod_open() < 0) {
        fprintf(stderr, "Failed to open GPIO controller: %s\n", gpiod_errstr(gpiod_errno()));
        exit(EXIT_FAILURE);
    }

    // Set ENA GPIO as output
    if (gpiod_direction_output(GPIOD_DIR_OUT, ENA_GPIO) < 0) {
        fprintf(stderr, "Failed to set ENA GPIO as output: %s\n", gpiod_errstr(gpiod_errno()));
        gpiod_close();
        exit(EXIT_FAILURE);
    }
    ena_status = gpiod_write(GPIOD_OUT_VALUE, 1); // Enable motor driver

    // Set IN1 and IN2 GPIOs as inputs
    if (gpiod_direction_input(GPIOD_DIR_IN, IN1_GPIO) < 0 ||
        gpiod_direction_input(GPIOD_DIR_IN, IN2_GPIO) < 0) {
        fprintf(stderr, "Failed to set IN1 and IN2 GPIOs as inputs: %s\n", gpiod_errstr(gpiod_errno()));
        gpiod_close();
        exit(EXIT_FAILURE);
    }

    // Initialize motor direction
    gpiod_write(GPIOD_OUT_VALUE, 0); // Set IN1 low (motor off)
    gpiod_write(GPIOD_OUT_VALUE, 1); // Set IN2 high (motor forward)
    gpiod_close();
}

// Function to handle rain detection
void handle_rain_detection() {
    fprintf(stderr, "Rain detected, starting motor...\n");

    // Enable motor for 5 seconds
    ena_status = gpiod_write(GPIOD_OUT_VALUE, 1); // Enable motor driver
    sleep(DELAY_MS);
    ena_status = gpiod_write(GPIOD_OUT_VALUE, 0); // Disable motor driver

    // Reset motor direction
    gpiod_write(GPIOD_OUT_VALUE, 0); // Set IN1 low (motor off)
    gpiod_write(GPIOD_OUT_VALUE, 1); // Set IN2 high (motor forward)
    gpiod_close();
}

// Function to handle signals (SIGINT, SIGTERM)
void handle_signal(int signum) {
    fprintf(stderr, "Received signal %d, exiting...\n", signum);
    // Clean up GPIOs
    cleanup();
    exit(EXIT_SUCCESS);
}

// Function to cleanup GPIOs and release resources
void cleanup() {
    // Close GPIO controller
    gpiod_close();

    // Print cleanup message
    fprintf(stderr, "GPIO resources released.\n");
}

