#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// GPIO pins for the RGB LED
#define RED_GPIO 17
#define GREEN_GPIO 22
#define BLUE_GPIO 27

// Function to map CPU load to RGB color
int mapLoadToColor(int load) {
    if (load <= 0) return 0; // Green (0, 255, 0) for 0% load
    if (load <= 50) return 255; // Yellow (255, 255, 0) for 50% load
    return 255; // Red (255, 0, 0) for 100% load
}

// Function to set PWM values for RGB LED based on CPU load
void setRgbPwm(int red, int green, int blue) {
    int red_pwm = mapLoadToColor((int)(100 * (getload() / 100)));
    int green_pwm = mapLoadToColor((int)(100 * (getload() / 100)));
    int blue_pwm = 0; // Assuming 0% blue for simplicity

    // Ensure PWM values are within 0-255 range
    red_pwm = (red_pwm > 255) ? 255 : red_pwm;
    green_pwm = (green_pwm > 255) ? 255 : green_pwm;

    // Set PWM values using pigpio
    if (pigpioSetup()) {
        fprintf(stderr, "Failed to initialize pigpio. Error: %s\n", pigpioError());
        exit(1);
    }

    pigpioWrite(RED_GPIO, red_pwm);
    pigpioWrite(GREEN_GPIO, green_pwm);
    pigpioWrite(BLUE_GPIO, blue_pwm);
}

// Signal handlers
void signalHandler(int signum) {
    // Turn off the LED fully by setting all channels to 0
    pigpioWrite(RED_GPIO, 0);
    pigpioWrite(GREEN_GPIO, 0);
    pigpioWrite(BLUE_GPIO, 0);

    // Clean up and exit
    pigpioTerminate();
    exit(0);
}

int main() {
    // Initialize signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    // Main loop
    while (1) {
        // Sample CPU load and update LED color
        setRgbPwm(mapLoadToColor(getload()), mapLoadToColor(getload()), 0);

        // Sleep for 500 ms
        usleep(500000);
    }

    return 0;
}

