#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <signal.h>
#include <pigpio.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <json/json.h>

#define BMP280_ADDR 0x76
#define BMP280_REG_CHIP_ID 0xD0
#define BMP280_REG_CALIBRATION 0x88
#define BMP280_REG_MEASUREMENT_DATA 0xF7
#define BMP280_FORCE_MODE_REG 0xF4

// BMP280 Calibration Data (24 bytes)
static const uint8_t bmp280_cal_data[] = {
    0x2D, 0x00, 0x00, 0x00, 0x2D, 0x00, 0x00, 0x00,
    0x2D, 0x00, 0x00, 0x00, 0x2D, 0x00, 0x00, 0x00,
    0x2D, 0x00, 0x00, 0x00, 0x2D, 0x00, 0x00, 0x00
};

// BMP280 64-bit Temperature Compensation Formula
static const uint32_t bmp280_temp_comp[] = {
    0x1B, 0x08, 0x1A, 0x2A, 0x08, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
};

// BMP280 64-bit Pressure Compensation Formula
static const uint32_t bmp280_pres_comp[] = {
    0x1B, 0x08, 0x1A, 0x2A, 0x08, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
};

// JSON object for BMP280 data
static const char *bmp280_data_json_str = "{\"temperature\":0.0,\"pressure\":0.0}";

int main() {
    // Signal handlers for SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize pigpio
    if (pigpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error());
        return EXIT_FAILURE;
    }

    // Open I2C device
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        pigpio_cleanup();
        return EXIT_FAILURE;
    }

    // Set I2C address and direction
    if (i2c_smbus_write_byte_data(i2c_fd, BMP280_ADDR, 0x20) < 0) {
        fprintf(stderr, "Failed to write to BMP280: %s\n", strerror(errno));
        close(i2c_fd);
        pigpio_cleanup();
        return EXIT_FAILURE;
    }

    // Verify chip ID
    uint8_t chip_id;
    if (i2c_smbus_read_byte_data(i2c_fd, BMP280_ADDR, BMP280_REG_CHIP_ID) != BMP280_REG_CHIP_ID) {
        fprintf(stderr, "Invalid chip ID, expected 0x58\n");
        close(i2c_fd);
        pigpio_cleanup();
        return EXIT_FAILURE;
    }
    chip_id = i2c_smbus_read_byte_data(i2c_fd, BMP280_ADDR, BMP280_REG_CHIP_ID);
    if (chip_id != 0x58) {
        fprintf(stderr, "Chip ID mismatch, expected 0x58\n");
        close(i2c_fd);
        pigpio_cleanup();
        return EXIT_FAILURE;
    }

    // Read calibration data
    if (i2c_smbus_read_i2c_block_data(i2c_fd, BMP280_ADDR, BMP280_REG_CALIBRATION, sizeof(bmp280_cal_data)) != sizeof(bmp280_cal_data)) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(i2c_fd);
        pigpio_cleanup();
        return EXIT_FAILURE;
    }

    // Apply temperature compensation
    uint32_t raw_temperature = i2c_smbus_read_word_data(i2c_fd, BMP280_REG_TEMPERATURE);
    uint32_t compensated_temperature = raw_temperature * bmp280_temp_comp[0] + bmp280_temp_comp[1];
    compensated_temperature += (raw_temperature << 8) * bmp280_temp_comp[2] + (raw_temperature << 16) * bmp280_temp_comp[3];
    compensated_temperature += (raw_temperature << 24) * bmp280_temp_comp[4];

    // Apply pressure compensation
    uint32_t raw_pressure = i2c_smbus_read_word_data(i2c_fd, BMP280_REG_PRESSURE);
    uint32_t compensated_pressure = raw_pressure * bmp280_pres_comp[0] + bmp280_pres_comp[1];
    compensated_pressure += (raw_pressure << 8) * bmp280_pres_comp[2] + (raw_pressure << 16) * bmp280_pres_comp[3];
    compensated_pressure += (raw_pressure << 24) * bmp280_pres_comp[4];

    // Convert to float and format as JSON
    float temperature = (float)compensated_temperature / 2.0e4;
    float pressure = (float)compensated_pressure / 1.0e3;
    char json_str[256];
    sprintf(json_str, "{\"temperature\":%.2f,\"pressure\":%.2f}", temperature, pressure);

    // Send data over UDP
    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(5000);
    server_addr.sin_addr.s_addr = inet_addr("192.168.1.100");

    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock == -1) {
        fprintf(stderr, "Failed to create UDP socket: %s\n", strerror(errno));
        close(i2c_fd);
        pigpio_cleanup();
        return EXIT_FAILURE;
    }

    if (sendto(sock, json_str, strlen(json_str), 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "Failed to send UDP message: %s\n", strerror(errno));
        close(sock);
        close(i2c_fd);
        pigpio_cleanup();
        return EXIT_FAILURE;
    }

    // Wait for 5 seconds before next measurement
    sleep(5);

    // Clean up resources
    close(sock);
    close(i2c_fd);
    pigpio_cleanup();

    return EXIT_SUCCESS;
}

// Function to clean up resources on SIGINT/SIGTERM
void cleanup(int signum) {
    // Close resources and exit
    close(i2c_fd);
    pigpio_cleanup();
    exit(EXIT_FAILURE);
}

