void initialise_pigpio_and_spi();
void read_temperature_and_control_fan();
void handle_signal(int signum);
void print_buffer();
void cleanup();

int main() {
    // Initialize global variables
    pi = NULL;
    initialise_pigpio_and_spi();

    // Set up signal handler
    signal(SIGINT, handle_signal);

    // Main loop
    while (!should_exit) {
        read_temperature_and_control_fan();
        usleep(1000000); // 1 second delay
    }

    // Clean up
    cleanup();

    return 0;
}

// Function: initialise_pigpio_and_spi
void initialise_pigpio_and_spi() {
    if (pi == NULL) {
        pi = gpioInitialise();

        if (pi == NULL) {
            fprintf(stderr, "Failed to initialise pigpio\n");
            return;
        }

        spiOpen(pi, MAX31855_SPI_CHANNEL, 500000, 0); // 500 kHz, mode 0

        if (SPI_FAILED(spiXfer(pi, MAX31855_SPI_CHANNEL, 0, (uint32_t[]) {MAX31855_REG_TEMPERATURE | MAX31855_FFT}, 1, NULL, NULL))) {
            fprintf(stderr, "Failed to open SPI channel or read temperature\n");
            return;
        }
    }
}

// Function: read_temperature_and_control_fan
void read_temperature_and_control_fan() {
    if (buffer_index >= BUFFER_SIZE) {
        buffer_index = 0; // Wrap around the circular buffer
    }

    uint32_t timestamp = time(NULL);
    int16_t temperature;
    uint8_t duty_cycle;

    if (SPI_FAILED(spiXfer(pi, MAX31855_SPI_CHANNEL, 0, (uint32_t[]) {0}, 1, &temperature, sizeof(int16_t)))) {
        fprintf(stderr, "SPI transfer error reading temperature\n");
        return;
    }

    // Check MAX31855 fault bits
    if ((temperature & 0x8000) != 0) {
        fprintf(stderr, "MAX31855 fault detected: %d\n", temperature);
        return;
    }

    if ((temperature & 0x0100) != 0) {
        fprintf(stderr, "OC fault detected\n");
        return;
    }

    if ((temperature & 0x0200) != 0) {
        fprintf(stderr, "SCG fault detected\n");
        return;
    }

    if ((temperature & 0x0400) != 0) {
        fprintf(stderr, "SCV fault detected\n");
        return;
    }

    // Determine PWM duty cycle based on temperature
    if (temperature < 25) {
        duty_cycle = 0;
    } else if (temperature <= 40) {
        duty_cycle = (temperature - 25) * 2;
    } else if (temperature <= 60) {
        duty_cycle = 200 - (temperature - 40) * 10;
    } else {
        duty_cycle = 255;
    }

    buffer[buffer_index].timestamp = timestamp;
    buffer[buffer_index].temperature = temperature;
    buffer[buffer_index].duty_cycle = duty_cycle;

    // Update the fan PWM duty cycle
    if (SPI_FAILED(gpioPWMWrite(pi, GPIO18, duty_cycle))) {
        fprintf(stderr, "Failed to set PWM duty cycle on GPIO18\n");
    }
}

// Function: handle_signal
void handle_signal(int signum) {
    should_exit = 1;
}

// Function: print_buffer
void print_buffer() {
    for (int i = 0; i < BUFFER_SIZE; i++) {
        if (buffer[i].timestamp != 0) {
            printf("Timestamp: %u, Temperature: %d°C, Duty Cycle: %u\n", buffer[i].timestamp, buffer[i].temperature, buffer[i].duty_cycle);
        }
    }
}

// Function: cleanup
void cleanup() {
    if (pi != NULL) {
        gpioFree(pi);
        spiClose(pi, MAX31855_SPI_CHANNEL);
        pi = NULL;
    }

    // No need to free the buffer as it's local and stack-allocated
}

