#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>
#include <time.h>

// Define constants for BMP180 I2C address and register offsets
#define BMP180_ADDRESS 0x77
#define BMP180_OSS_REG 0x2E
#define BMP180_OCR_REG 0x2F
#define BMP180_TEMPL_REG 0x2C
#define BMP180_PRESS_REG 0x2D

// Function prototypes
void setup_pigpio();
void setup_bmp180(int gpio);
void read_bmp180_data(uint8_t oversampling);
void write_bmp180_config(uint8_t oversampling);
void handle_interrupt(int);
void cleanup();

// Global variables
pigpio *pi;
int bmp180_gpio;
FILE *altitude_log;

// Function to setup pigpio
void setup_pigpio() {
    if (pi == NULL) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }
}

// Function to setup BMP180 on GPIO2 with falling edge interrupt
void setup_bmp180(int gpio) {
    if (bmp180_gpio < 0) {
        fprintf(stderr, "Failed to configure BMP180 on GPIO pin\n");
        exit(EXIT_FAILURE);
    }

    // Configure GPIO pin as input with internal pull-up
    if (piGPIOSetMode(pi, bmp180_gpio, GPIO_INPUT_PULLUP) == -1) {
        fprintf(stderr, "Error setting GPIO pin mode\n");
        exit(EXIT_FAILURE);
    }

    // Enable falling edge interrupt on GPIO pin
    if (piGPIOSetInterrupt(pi, bmp180_gpio, GPIO_FALLING_EDGE) == -1) {
        fprintf(stderr, "Error setting GPIO pin interrupt\n");
        exit(EXIT_FAILURE);
    }

    // Register interrupt handler
    if (signal(SIGINT, handle_interrupt) == SIG_ERR) {
        fprintf(stderr, "Failed to register interrupt handler\n");
        exit(EXIT_FAILURE);
    }
}

// Function to read BMP180 data with specified oversampling
void read_bmp180_data(uint8_t oversampling) {
    uint8_t config;
    uint16_t crc;
    int16_t temperature;
    int16_t pressure;

    // Write oversampling setting to BMP180
    if (pigpioWriteReg8(pi, BMP180_ADDRESS, BMP180_OSS_REG, oversampling) == -1) {
        fprintf(stderr, "Error writing oversampling setting\n");
        return;
    }

    // Read configuration register to verify setting
    if (pigpioReadReg8(pi, BMP180_ADDRESS, BMP180_OCR_REG, &config) == -1) {
        fprintf(stderr, "Error reading configuration register\n");
        return;
    }

    // Read temperature and pressure data
    if (pigpioReadReg16(pi, BMP180_ADDRESS, BMP180_TEMPL_REG, &temperature) == -1 ||
        pigpioReadReg16(pi, BMP180_ADDRESS, BMP180_PRESS_REG, &pressure) == -1 ||
        (crc = pigpioReadReg16(pi, BMP180_ADDRESS, BMP180_PR_CON, 0)) != 0x2B) {
        fprintf(stderr, "Error reading BMP180 data or CRC check failed\n");
        return;
    }

    // Check CRC
    if (crc != 0x2B) {
        fprintf(stderr, "CRC check failed\n");
        return;
    }

    // Log data
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char timestamp[50];
    sprintf(timestamp, "%d-%02d-%02d %02d:%02d:%02d", timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_day, timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec);

    fprintf(altitude_log, "%s,%d,%d\n", timestamp, temperature, pressure);
}

// Function to write BMP180 configuration with specified oversampling
void write_bmp180_config(uint8_t oversampling) {
    uint8_t config;

    // Calculate configuration register value
    config = (oversampling & 0x07) | (0x80 >> (8 - oversampling));

    // Write configuration register
    if (pigpioWriteReg8(pi, BMP180_ADDRESS, BMP180_OCR_REG, &config) == -1) {
        fprintf(stderr, "Error writing configuration register\n");
        return;
    }
}

// Interrupt handler for SIGINT (Ctrl+C)
void handle_interrupt(int signum) {
    // Clean up resources
    cleanup();

    // Exit the program
    exit(EXIT_SUCCESS);
}

// Function to cleanup resources
void cleanup() {
    // Close the file
    if (altitude_log != NULL) {
        fclose(altitude_log);
        altitude_log = NULL;
    }

    // Close I2C handle
    if (pigpioI2CClose(pi) == -1) {
        fprintf(stderr, "Error closing I2C handle\n");
    }

    // Release GPIO pin
    if (piGPIOUnsetInterrupt(pi, bmp180_gpio) == -1) {
        fprintf(stderr, "Error releasing GPIO pin interrupt\n");
    }
    if (piGPIOSetMode(pi, bmp180_gpio, GPIO_INPUT) == -1) {
        fprintf(stderr, "Error resetting GPIO pin mode\n");
    }

    // Close pigpio
    if (pi != NULL) {
        pigpioFree(pi);
        pi = NULL;
    }
}

int main() {
    // Initialize pigpio
    setup_pigpio();

    // Set up BMP180 on GPIO2
    setup_bmp180(2);

    // Open I2C bus 1
    if (pigpioI2COpen(pi, 1) == -1) {
        fprintf(stderr, "Error opening I2C bus 1\n");
        return EXIT_FAILURE;
    }

    // Open file for logging
    if ((altitude_log = fopen("altitude_log.txt", "a")) == NULL) {
        fprintf(stderr, "Failed to open altitude_log.txt for writing\n");
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Poll at 1-second intervals
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        ts.tv_sec += 1;

        // Wait for the next second
        if (clock_nanosleep(CLOCK_REALTIME, 0, &ts, NULL) == -1) {
            fprintf(stderr, "Error sleeping\n");
            return EXIT_FAILURE;
        }

        // Read and log BMP180 data with OSS=3
        read_bmp180_data(3);
    }

    // SIGINT handler will be called when Ctrl+C is pressed
    return 0;
}

