#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <ctype.h>

#define BME280_ADDR 0x76
#define I2C_BUS_NUM 1

// BME280 register addresses
#define REG_TEMPERATURE     0x88
#define REG_HUMIDITY         0x2C
#define REG_PRESSURE         0x30
#define REG_CHIP_ID          0x00

// BME280 data request register
#define BME280_CMD_TEMP      0x2E
#define BME280_CMD_HUMIDITY   0x2F
#define BME280_CMD_PRESSURE   0x2A

// BME280 data output register
#define BME280_DATA_OUT      0x88

// BME280 data size
#define BME280_DATA_SIZE     1

// BME280 data request command
#define BME280_CMD_REQUEST  (BME280_CMD_TEMP | BME280_CMD_HUMIDITY | BME280_CMD_PRESSURE)

// Function prototypes
void bme280_init(void);
void bme280_read(int fd, uint8_t reg, uint8_t *data);
void bme280_write(int fd, uint8_t reg, uint8_t data);
void bme280_check_chip_id(int fd);
void handle_signal(int signum);
void write_to_csv(const char *line);
void cleanup_resources(void);

int main() {
    srand(time(NULL));

    // Initialize BME280
    bme280_init();

    // Open I2C device
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd == -1) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set I2C address and direction
    if (ioctl(fd, I2C_SLAVE, BME280_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Signal handler for SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        // Read sensor data
        uint8_t data[BME280_DATA_SIZE];
        bme280_read(fd, BME280_CMD_REQUEST, data);

        // Check chip ID
        bme280_check_chip_id(fd);

        // Format and write to CSV
        char timestamp[23];
        time_t now = time(NULL);
        struct tm tm = *localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

        char line[256];
        snprintf(line, sizeof(line), "%s,%d,%d,%d", timestamp, data[REG_TEMPERATURE], (data[REG_HUMIDITY] << 8) | data[REG_HUMIDITY_H], (data[REG_PRESSURE] << 8) | data[REG_PRESSURE_H]);

        write_to_csv(line);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up resources
    cleanup_resources();

    return 0;
}

// Function to initialize BME280
void bme280_init() {
    // No initialization needed for BME280, it's ready after power-up.
    // Just ensure the I2C communication is set up correctly.
}

// Function to read from BME280
void bme280_read(int fd, uint8_t reg, uint8_t *data) {
    uint8_t cmd = BME280_CMD_REQUEST | reg;
    if (ioctl(fd, I2C_WRITE, &cmd) < 0) {
        perror("Failed to write command");
        return;
    }

    if (ioctl(fd, I2C_READ, data) < 0) {
        perror("Failed to read data");
        return;
    }
}

// Function to write to BME280
void bme280_write(int fd, uint8_t reg, uint8_t data) {
    uint8_t cmd = BME280_CMD_REQUEST | reg;
    if (ioctl(fd, I2C_WRITE, &cmd) < 0) {
        perror("Failed to write command");
        return;
    }

    if (ioctl(fd, I2C_WRITE, &data) < 0) {
        perror("Failed to write data");
        return;
    }
}

// Function to check BME280 chip ID
void bme280_check_chip_id(int fd) {
    uint8_t chip_id;
    bme280_read(fd, REG_CHIP_ID, &chip_id);

    if (chip_id != 0x60) {
        fprintf(stderr, "BME280 chip ID is incorrect (expected 0x60)\n");
        exit(EXIT_FAILURE);
    }
}

// Signal handler to clean up resources on SIGINT/SIGTERM
void handle_signal(int signum) {
    // Clean up resources
    cleanup_resources();

    // Exit the program
    exit(EXIT_SUCCESS);
}

// Function to write data to CSV file
void write_to_csv(const char *line) {
    FILE *csv_file = fopen("bme280_log.csv", "a+");
    if (!csv_file) {
        perror("Failed to open CSV file");
        return;
    }

    fprintf(csv_file, "%s\n", line);
    fclose(csv_file);
}

// Function to cleanup resources
void cleanup_resources(void) {
    // Close I2C device
    close(fd);

    // Remove CSV file
    unlink("bme280_log.csv");
}

