#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define BMP180_ADDRESS 0x77
#define BMP180_REG_CALIB 0xAA
#define BMP180_REG_OSS 0xF4
#define PRESSURE_THRESHOLD 5
#define BUFFER_SIZE (60 * 1000) // 60 seconds of data

volatile sig_atomic_t should_exit = 0;

// Circular buffer for pressure readings
struct pressure_reading {
    time_t timestamp;
    float pressure;
} readings[BUFFER_SIZE];

// Function prototypes
void setup_pigpio();
void setup_bmp180();
void read_pressure();
void calculate_rolling_average(float[], int, int);
void handle_pressure_deviation(float, float);
void cleanup_resources();
void signal_handler(int signum);

int main() {
    // Initialize pigpio
    setup_pigpio();

    // Setup BMP180
    setup_bmp180();

    // Main loop
    while (!should_exit) {
        // Read pressure
        read_pressure();

        // Calculate rolling average
        calculate_rolling_average(readings, 0, BUFFER_SIZE);

        // Check for pressure deviation
        handle_pressure_deviation(readings[0].pressure, BUFFER_SIZE / 60);

        // Sleep for 50 ms
        usleep(50000);
    }

    // Clean up resources
    cleanup_resources();

    return 0;
}

// Function to setup pigpio
void setup_pigpio() {
    if (pigpioSetup() == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }

    // Set up hardware timer for 50 ms interval
    if (gpioSetTimerFuncEx(0, 50, 0, 0, 0, 0, NULL) == -1) {
        fprintf(stderr, "Failed to set timer: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }
}

// Function to setup BMP180
