// Function to read temperature from thermal zone 0
int read_temperature() {
    char temp_file[100];
    sprintf(temp_file, "/sys/class/thermal/thermal_zone0/temp");
    int temp_fd = open(temp_file, O_RDONLY);
    if (temp_fd == -1) {
        fprintf(stderr, "Failed to open temperature file: %s\n", temp_file);
        return -1;
    }

    char buffer[10];
    if (fread(buffer, 1, 10, temp_fd) != 10) {
        fprintf(stderr, "Failed to read temperature: %s\n", temp_file);
        close(temp_fd);
        return -1;
    }

    buffer[10] = '\0'; // Null terminate the string
    int temperature = atoi(buffer);
    close(temp_fd);
    return temperature;
}

// Function to map temperature to duty cycle
int map_temperature_to_duty(int temperature) {
    if (temperature < TEMP_LOW || temperature > TEMP_HIGH) {
        return MIN_DUTY; // Clamp outside the range
    }

    float duty_cycle = (temperature - TEMP_LOW) / (TEMP_HIGH - TEMP_LOW) * (MAX_DUTY - MIN_DUTY) + MIN_DUTY;
    return (int)duty_cycle;
}

// Function to write duty cycle to PWM pin
int write_duty_cycle(int duty_cycle) {
    if (pi_pgid == -1) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return -1;
    }

    int result = pgm_writepigpio(PWM_PIN, duty_cycle);
    if (result == -1) {
        fprintf(stderr, "Failed to write duty cycle to GPIO: %s\n", pigpio_errstr(pigpio_lasterror()));
        return -1;
    }

    return 0;
}

// Function to log temperature and duty cycle
void log_data(int temperature, int duty_cycle) {
    time_t now = time(NULL);
    struct tm timeinfo;
    localtime_r(&now, &timeinfo);

    char log_entry[256];
    sprintf(log_entry, "%s\t%u°C\t%u%%\n", ctime(&timeinfo.tm_sec).data, temperature, duty_cycle);

    if (fan_log_file == NULL) {
        fan_log_file = fopen("fan_log.txt", "a+");
        if (fan_log_file == NULL) {
            fprintf(stderr, "Failed to open log file: %s\n", "fan_log.txt");
            exit(1);
        }
    }

    if (fwrite(log_entry, 1, sizeof(log_entry), fan_log_file) == 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", "fan_log.txt");
        fclose(fan_log_file);
        fan_log_file = NULL;
        exit(1);
    }
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    if (pi_pgid != -1) {
        pgm_close(pi_pgid);
        pi_pgid = -1;
    }

    if (fan_log_file != NULL) {
        fclose(fan_log_file);
        fan_log_file = NULL;
    }

    printf("Stopping fan and exiting...\n");
    exit(0);
}

int main() {
    // Initialize pigpio
    pi_pgid = pgm_new();
    if (pi_pgid == -1) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    // Set PWM frequency
    int result = pgm_set_freq(pi_pgid, PWM_FREQ);
    if (result == -1) {
        fprintf(stderr, "Failed to set PWM frequency: %s\n", pigpio_errstr(pigpio_lasterror()));
        pgm_delete(pi_pgid);
        pi_pgid = -1;
        return 1;
    }

    while (1) {
        int temperature = read_temperature();
        if (temperature == -1) {
            fprintf(stderr, "Failed to read temperature.\n");
            continue;
        }

        int duty_cycle = map_temperature_to_duty(temperature);

        log_data(temperature, duty_cycle);

        // Sleep for 5 seconds
        sleep(5);
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}
