#include <signal.h>
#include <pigpio.h>
#include <stdint.h>
#include <stdbool.h>

#define PIGPIO_ID -1
#define GPIO18 18
#define MAX31865_SPI_CS 0
#define MAX31865_SPI_MODE 1
#define MAX31865_SPI_SPEED 500000

#define CONFIG_REG 0x80
#define CONFIG_ENABLE_VBIAS 0xC1
#define RTD_CODE_REG_0x01 0x01
#define RTD_CODE_REG_0x02 0x02
#define FAULT_STATUS_REG 0x07

#define R_REF 430
#define R_NOMINAL_PT100 100
#define R0 138.5
#define A 3.9083E-3
#define B -5.775E-7

typedef struct {
    float target_temperature;
    float kp;
    float ki;
    float kd;
} PIDConfig;

void pid_calc(float error, float prev_error, float kp, float ki, float kd, float *output) {
    float derivative = (error - prev_error) / (float) 100;
    *output = kp * error + ki * (error - prev_error) + kd * derivative;
    prev_error = error;
}

int read_spi_reg(uint8_t reg_addr) {
    int ret;
    pigpio.pi_write(GPIO18, 1); // Set GPIO18 high to enable pull-up
    ret = pigpio.pi_write(PIGPIO_ID, 0x80 | reg_addr); // Write register address
    if (ret != 0) {
        fprintf(stderr, "Error writing to SPI register: %d\n", ret);
        return -1;
    }
    ret = pigpio.pi_read(PIGPIO_ID, 1); // Read the register value
    if (ret != 1) {
        fprintf(stderr, "Error reading SPI register: %d\n", ret);
        return -1;
    }
    return ret;
}

void initialize_max31865() {
    uint8_t config_reg = CONFIG_ENABLE_VBIAS;
    pigpio.pi_write(PIGPIO_ID, config_reg);
    pigpio.pi_write(PIGPIO_ID, 0x00); // Clear all faults
    pigpio.pi_write(PIGPIO_ID, 0x80); // Write configuration register
}

void read_rtd_code() {
    uint16_t msb = read_spi_reg(RTD_CODE_REG_0x01);
    uint16_t lsb = read_spi_reg(RTD_CODE_REG_0x02);
    uint16_t rtd_code = (msb << 8) | lsb;
    uint16_t fault_status = read_spi_reg(FAULT_STATUS_REG);
    if ((fault_status & 0x01) != 0) { // Check fault bit
        fprintf(stderr, "MAX31865 fault detected: %d\n", fault_status);
        exit(1);
    }
}

void convert_rtd_code_to_resistance(uint16_t rtd_code) {
    uint16_t rtd_value = rtd_code / 32768 * R_REF;
    float resistance = rtd_value;
}

void convert_resistance_to_temperature(float resistance) {
    float t = ((R0 * (resistance - R_NOMINAL_PT100)) / (A + B * resistance));
    if (t < 0) {
        t = 0.0; // Prevent negative temperature
    }
}

