    if (argc < 2) {
        fprintf(stderr, "Usage: %s <config.json>\n", argv[0]);
        return 1;
    }

    FILE *config_file = fopen(argv[1], "r");
    if (config_file == NULL) {
        fprintf(stderr, "Failed to open config file: %s\n", argv[1]);
        return 1;
    }

    PIDConfig config;
    if (json_load_file(config_file, &config) != 0) {
        fprintf(stderr, "Failed to parse config file: %s\n", config_file);
        fclose(config_file);
        return 1;
    }
    fclose(config_file);

    if (pigpio_check_version() < 19) {
        fprintf(stderr, "pigpio version 19 or higher required.\n");
        return 1;
    }

    pigpio *pi = NULL;
    if ((pi = pigpio_open()) == NULL) {
        fprintf(stderr, "Failed to open pigpio: %s\n", pigpio_error());
        return 1;
    }

    initialize_max31865();

    bool running = true;
    while (running) {
        pid_calc((config.target_temperature - read_temperature()), 0.0, config.kp, config.ki, config.kd, &duty_cycle);

        if (duty_cycle > 1000.0 || duty_cycle < 0.0) {
            duty_cycle = 1000.0; // Clamp duty cycle to valid range
        }

        if (duty_cycle > 0) {
            pigpio.pi_write(GPIO18, duty_cycle); // Set PWM duty cycle
        } else {
            pigpio.pi_write(GPIO18, 0); // Turn off heater
        }

        // Check for temperature exceed, SPI read failure, or MAX31865 faults
        if (read_temperature() > config.target_temperature || 
            pigpio_error() != 0 || 
            read_spi_reg(0x00) != 0x00) {
            fprintf(stderr, "Critical error detected, shutting down.\n");
            duty_cycle = 0;
            running = false;
        }

        usleep(100000); // Sleep for 100 ms
    }

    // Clean up
    pigpio_close(pi);
    exit(0);

    // Helper functions

    float read_temperature() {
        uint16_t rtd_code = read_rtd_code();
        convert_rtd_code_to_resistance(rtd_code);
        convert_resistance_to_temperature(resistance);
        return resistance;
    }

    void handle_signal(int signum) {
        fprintf(stderr, "Signal received, shutting down.\n");
        pigpio.pi_write(GPIO18, 0); // Turn off heater
        pigpio_close(pi);
        exit(0);
    }

    int json_load_file(const char *filename, PIDConfig *config) {
        char buffer[4096];
        FILE *file = fopen(filename, "r");
        if (!file) {
            return -1;
        }

        char *json_str;
        size_t len;
        if ((json_str = malloc(4096)) == NULL) {
            fclose(file);
            return -1;
        }

        len = fread(json_str, 1, 4096, file);
        fclose(file);

        if (json_load(json_str, json_str) != 1) {
            free(json_str);
            return -1;
        }

        if (config != NULL) {
            *config = *(PIDConfig *)json_str;
        }

        free(json_str);
        return 0;
    }
