#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <errno.h>
#include <linux/i2c-dev.h>

#define BMP180_ADDR 0x77
#define TEMP_THRESHOLD 30.0
#define PRESSURE_THRESHOLD 950.0
#define MAX_RETRIES 3

// BMP180 register addresses
#define BMP180_CMD 0x00
#define BMP180_READ_STATUS 0x02
#define BMP180_CONVERSION_TIME 0x03
#define BMP180_PRESSURE 0x05
#define BMP180_TEMP 0x06

// BMP180 calibration values
#define CALIB_TEMP_OFFSET 25
#define CALIB_PRESSURE_OFFSET 50
#define CALIB_PRESSURE_SCALE 2

// Function prototypes
void bmp180_init();
int bmp180_read(uint8_t reg);
void bmp180_write(uint8_t reg, uint8_t data);
void handle_breach(float temperature, float pressure);
void cleanup();

int main() {
    int i2c_fd = -1;
    int retries = 0;
    struct timespec ts;
    float temperature, pressure;
    char breach_log_path[] = "/path/to/breach_log.txt";

    // Open I2C device
    while ((i2c_fd = open("/dev/i2c-1", O_RDWR)) == -1 && retries < MAX_RETRIES) {
        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to open I2C bus after %d attempts\n", MAX_RETRIES);
            exit(EXIT_FAILURE);
        }
        sleep(1);
        retries++;
    }

    if (i2c_fd == -1) {
        fprintf(stderr, "Failed to open I2C bus\n");
        exit(EXIT_FAILURE);
    }

    // Initialize BMP180
    bmp180_init();

    // Main loop
    while (1) {
        // Read BMP180 status
        if (bmp180_read(BMP180_READ_STATUS) & 0x08) {
            // Conversion is complete
            bmp180_read(BMP180_CONVERSION_TIME);
            ts.tv_sec = (uint32_t)(bmp180_read(BMP180_CONVERSION_TIME) << 8) | bmp180_read(BMP180_CONVERSION_TIME + 1);
            ts.tv_nsec = 0;

            // Read temperature and pressure
            bmp180_read(BMP180_TEMP);
            temperature = bmp180_calc_temperature();
            bmp180_read(BMP180_PRESSURE);
            pressure = bmp180_calc_pressure();

            // Check for breaches
            handle_breach(temperature, pressure);

            // Write to breach log
            fprintf(breach_log_path, "%s %f°C %f hPa\n", ctime(&ts), temperature, pressure);
        } else {
            // Wait for conversion
            sleep(1);
        }
    }

    // Cleanup
    cleanup();

    return 0;
}

// BMP180 initialization function
void bmp180_init() {
    bmp180_write(BMP180_CMD, 0x2E); // Set control register to 0x2E
}

// BMP180 read function
int bmp180_read(uint8_t reg) {
    uint8_t data;
    int ret = 0;

    do {
        ret = ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDR | reg);
        if (ret < 0) {
            fprintf(stderr, "Error: ioctl failed with %d\n", ret);
            return -1;
        }
        ret = read(i2c_fd, &data, 1);
        if (ret != 1) {
            fprintf(stderr, "Error: read failed with %d\n", ret);
            return -1;
        }
    } while (ret != 1);

    return ret;
}

// BMP180 write function
void bmp180_write(uint8_t reg, uint8_t data) {
    int ret = 0;

    do {
        ret = ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDR | reg);
        if (ret < 0) {
            fprintf(stderr, "Error: ioctl failed with %d\n", ret);
            return;
        }
        ret = write(i2c_fd, &data, 1);
        if (ret != 1) {
            fprintf(stderr, "Error: write failed with %d\n", ret);
            return;
        }
    } while (ret != 1);

    return;
}

// BMP180 calculation function
float bmp180_calc_temperature() {
    uint16_t temp;
    uint8_t b1, b0;

    bmp180_read(BMP180_TEMP);
    b1 = bmp180_read(BMP180_TEMP + 1);
    b0 = bmp180_read(BMP180_TEMP + 2);

    return (float)((int16_t)(b1 << 8 | b0) * (1.0 / (CALIB_TEMP_OFFSET + CALIB_TEMP_SCALE * (b1 >> 7))));
}

float bmp180_calc_pressure() {
    uint16_t pressure;
    uint8_t b3, b2, b1, b0;

    bmp180_read(BMP180_PRESSURE);
    b3 = bmp180_read(BMP180_PRESSURE + 1);
    b2 = bmp180_read(BMP180_PRESSURE + 2);
    b1 = bmp180_read(BMP180_PRESSURE + 3);
    b0 = bmp180_read(BMP180_PRESSURE + 4);

    pressure = (float)((int16_t)(b3 << 8 | b2) * (1.0 / (CALIB_PRESSURE_OFFSET + CALIB_PRESSURE_SCALE * (b3 >> 7))));
    return pressure;
}

// Handle breach
void handle_breach(float temperature, float pressure) {
    if (temperature > TEMP_THRESHOLD || pressure < PRESSURE_THRESHOLD) {
        fprintf(stderr, "Temperature breach: %f°C\n", temperature);
        fprintf(stderr, "Pressure breach: %f hPa\n", pressure);
    }
}

// Cleanup function
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

// Signal handling for SIGINT and SIGTERM
void signal_handler(int signum) {
    fprintf(stderr, "Caught signal %d, exiting...\n", signum);
    exit(EXIT_FAILURE);
}

int main(int argc, char **argv) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Start main loop
    main();

    return 0;
}

