}

float bmp180_calc_pressure() {
    uint16_t pressure;
    uint8_t b3, b2, b1, b0;

    bmp180_read(BMP180_PRESSURE);
    b3 = bmp180_read(BMP180_PRESSURE + 1);
    b2 = bmp180_read(BMP180_PRESSURE + 2);
    b1 = bmp180_read(BMP180_PRESSURE + 3);
    b0 = bmp180_read(BMP180_PRESSURE + 4);

    pressure = (float)((int16_t)(b3 << 8 | b2) * (1.0 / (CALIB_PRESSURE_OFFSET + CALIB_PRESSURE_SCALE * (b3 >> 7))));
