}

// Function: setup_spi
void setup_spi() {
    // Configure SPI
    spi_set_mode(SPI_SPEED, SPI_MODE_0);
    spi_set_polarity(SPI_POLARITY_LOW, SPI_EDGE_FALLING);
    spi_set_phase(SPI_PHASE_0);

    // Set GPIO pins for SPI
    gpio_mode(SENSE, GPIO_INPUT);
    gpio_mode(SPI_CS, GPIO_OUTPUT);
    gpio_write(SPI_CS, 1); // Set CS high

    // Initialize MAX31855
    spi_write(SPI_CS, MAX31855_CS);
    spi_write(SPI_SCK, 0x00); // Reset
    spi_write(SPI_SCK, 0x00);
    spi_write(SPI_SCK, 0x00); // Read ID
    uint8_t id = spi_read(SPI_MISO);
    if (id != 0x14) {
        fprintf(stderr, "MAX31855 ID mismatch, aborting\n");
        exit(EXIT_FAILURE);
    }

    // Set SPI pins for MAX31855
    gpio_mode(MAX31855_SCK, GPIO_OUTPUT);
    gpio_mode(MAX31855_MISO, GPIO_INPUT);
    gpio_mode(MAX31855_MOSI, GPIO_OUTPUT);
}

// Function: read_temperature
