    // Write command to read temperature
    spi_write(SPI_CS, 0x00); // Read temperature command
    spi_write(SPI_SCK, 0x00);
    spi_write(SPI_SCK, 0x00);

    // Read temperature data
    uint16_t temp_raw = spi_read(SPI_MISO);
    spi_read(SPI_SCK, 0x00); // Read ID again for error check
    uint8_t id = spi_read(SPI_MISO);
    if (id != 0x14) {
        fprintf(stderr, "SPI read error or MAX31855 fault, setting duty cycle to 0%\n");
        duty_cycle = 0;
        return;
    }

    // Convert raw temperature to Celsius
    double temp_celsius = (temp_raw * 0.25) - 273.15;
    current_temp = temp_celsius;
}

// Function: control_heater
void control_heater() {
    double error = current_temp - TARGET_TEMPERATURE;
    int duty_cycle_set = pi_analog_write(RELAY_GPIO, error * MAX_DUTY_CYCLE);

    // Anti-windup
    if (duty_cycle_set > MAX_DUTY_CYCLE) {
        duty_cycle_set = MAX_DUTY_CYCLE;
    }

    duty_cycle = duty_cycle_set;
}

// Function: handle_errors
void handle_errors() {
    if (spi_err) {
        fprintf(stderr, "SPI read failure, setting duty cycle to 0%\n");
        duty_cycle = 0;
    }
}

