void pi_controller(int current_temp, int target_temp) {
    double error = current_temp - target_temp;
    int duty_cycle_proportional = error * PI_CONTROLLER_GAIN;

    // Anti-windup
    if (duty_cycle_proportional > 0 && duty_cycle >= MAX_DUTY_CYCLE) {
        duty_cycle_proportional = 0;
    }

    duty_cycle += duty_cycle_proportional;
}

