    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Free pigpio resources
    if (pi != NULL) {
        pigpio_free(pi);
        pi = NULL;
    }

    // Exit the program
    exit(EXIT_SUCCESS);
