#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// GPIO pins for common-anode RGB LED
#define GPIO_R 17
#define GPIO_G 18
#define GPIO_B 27
#define COMMON_ANODE 3

// Temperature thresholds (m°C)
#define THRESHOLD_BLUE 40000
#define THRESHOLD_GREEN 60000

volatile sig_atomic_t should_exit = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    should_exit = 1;
}

int main() {
    // Initialize pigpio library
    int rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", gpioError());
        exit(EXIT_FAILURE);
    }

    // Set up GPIO pins for PWM
    int r_pin = gpioPwmSetup(GPIO_R, 0, 255, 0); // Invert duty cycle for common-anode
    int g_pin = gpioPwmSetup(GPIO_G, 0, 255, 0);
    int b_pin = gpioPwmSetup(GPIO_B, 0, 255, 0);

    // Signal handler registration
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!should_exit) {
        // Read CPU temperature
        FILE *temp_file = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
        if (!temp_file) {
            fprintf(stderr, "Failed to open temperature file: %s\n", strerror(errno));
            continue;
        }

        long temp_mdeg;
        if (fread(&temp_mdeg, sizeof(long), 1, temp_file) != 1 || ferror(temp_file)) {
            fprintf(stderr, "Failed to read temperature: %s\n", strerror(errno));
            fclose(temp_file);
            continue;
        }

        // Calculate RGB values based on temperature
        if (temp_mdeg < THRESHOLD_BLUE) {
            // Solid Blue
            int r = 0;
            int g = 0;
            int b = 255;
        } else if (temp_mdeg < THRESHOLD_GREEN) {
            // Solid Green
            int r = 0;
            int g = 255;
            int b = 0;
        } else {
            // Solid Red
            int r = 255;
            int g = 0;
            int b = 0;
        }

        // Invert duty cycle for common-anode LED
        int new_r_pwm = 255 - r;
        int new_g_pwm = 255 - g;
        int new_b_pwm = 255 - b;

        // Set PWM values
        gpioPwmWrite(r_pin, new_r_pwm);
        gpioPwmWrite(g_pin, new_g_pwm);
        gpioPwmWrite(b_pin, new_b_pwm);

        // Print current temperature and RGB values
        printf("Temperature: %ld m°C, RGB: (%d, %d, %d)\n", temp_mdeg, new_r_pwm, new_g_pwm, new_b_pwm);

        // Close the temperature file
        fclose(temp_file);
    }

    // Clean up on exit
    gpioPwmUnset(GPIO_R);
    gpioPwmUnset(GPIO_G);
    gpioPwmUnset(GPIO_B);

    gpioTerminate();

    return 0;
}

