#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <curl/curl.h>
#include <pigpio.h>

#define PI_GPIO_ID 4 // BCM 4, physical pin 7
#define DHT22_PIN 4
#define DHT22_DATA_LOW_TIME_MS 1

// Constants for DHT22 communication
#define DHT22_START_BIT 11111111
#define DHT22_DATA_BIT 00000001

// Sensor data structure
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
void initializePigpio();
void sendStartSignal(int pin);
void readDht22(SensorData *data);
void validateChecksum(uint8_t data[5]);
void postDataToServer(SensorData data);
void handleSignals(int signum);
void cleanup();

int main() {
    // Initialize global variables
    SensorData sensorData;
    int attempts = 3;
    int exitCode = 0;

    // Signal handlers
    signal(SIGINT, handleSignals);
    signal(SIGTERM, handleSignals);

    // Initialize pigpio
    initializePigpio();

    while (attempts > 0) {
        // Attempt to read sensor data
        if (readDht22(&sensorData) == 0) {
            // Validate and post data
            validateChecksum(sensorData.data);
            if (postDataToServer(&sensorData) == CURLE_OK) {
                printf("Sensor data posted successfully.\n");
                attempts--;
            } else {
                printf("Error posting data: %s\n", curl_easy_strerror(curl_easy_getinfo(curl)));
            }
        } else {
            // Handle sensor absent or other error
            printf("Sensor reading failed. Retrying...\n");
        }
    }

    // Clean up resources
    cleanup();

    // Exit with error code if any retry failed
    exitCode = 1;

    return exitCode;
}

// Helper functions

void initializePigpio() {
    if (piGPIOSetup() == -1) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        exit(EXIT_FAILURE);
    }
}

void sendStartSignal(int pin) {
    piWriteDigital(PIN_GPIO_ID, pin, 0); // Pull GPIO low
    usleep(DHT22_DATA_LOW_TIME_MS * 1000); // Wait for 1 ms
    piWriteDigital(PIN_GPIO_ID, pin, 1); // Release GPIO
}

void readDht22(SensorData *data) {
    int pin = PI_GPIO_ID;
    uint8_t data[5];

    // Send start signal
    sendStartSignal(pin);

    // Read 40 bits
    for (int i = 0; i < 40 / 8; i++) {
        piWriteDigital(PIN_GPIO_ID, pin, 0); // Pull GPIO low
        data[i * 8] = piReadDigital(PIN_GPIO_ID, pin); // Read data bit
        piWriteDigital(PIN_GPIO_ID, pin, 1); // Release GPIO
    }

    // Ensure data is valid (non-zero start bit and checksum)
    if (data[0] != DHT22_START_BIT || validateChecksum(data)) {
        return -1;
    }

    // Parse data
    sensorData.temperature = (float)data[1] * 0.125 + 240.0;
    sensorData.humidity = (float)data[2] * 0.25 + 40.0;

    return 0;
}

void validateChecksum(uint8_t data[5]) {
    uint8_t checksum = (data[0] ^ data[1] ^ data[2] ^ data[3] ^ data[4]);

    if (checksum != data[5]) {
        printf("Checksum error, data invalid.\n");
        return;
    }
}

void postDataToServer(SensorData data) {
    CURL *curl;
    CURLcode res;

    curl = curl_easy_init();
    if(curl) {
        curl_easy_setopt(curl, CURLOPT_URL, "http://yourserver.com/api/humidity");
        curl_easy_setopt(curl, CURLOPT_POST, 1);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, "{\"temperature\": " 
            "{\"temperature\": " "%.2f", data.temperature) 
            ", \"humidity\": " "{\"humidity\": " "%.2f", data.humidity) 
            "}" );

        res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            fprintf(stderr, "Curl operation failed: %s\n", curl_easy_strerror(res));
        } else {
            printf("Sensor data posted successfully.\n");
        }

        curl_easy_cleanup(curl);
    }
}

void handleSignals(int signum) {
    // Clean up resources on SIGINT and SIGTERM
    cleanup();
    exit(EXIT_FAILURE);
}

void cleanup() {
    // Release resources
    if (piGPIOCleanup() == -1) {
        fprintf(stderr, "Failed to cleanup pigpio.\n");
    }

    // Free curl handle if initialized
    if (curl) {
        curl_easy_cleanup(curl);
    }
}

