// Function: Setup pigpio
void setup_pigpio() {
    if (pi_pigpio_error() != PI_NO_ERROR) {
        fprintf(stderr, "Error initializing pigpio: %s\n", pi_pigpio_error_string());
        exit(EXIT_FAILURE);
    }

    // Set GPIO4 as input with internal pull-up
    if (pi_gpio_direction(GPIO_TRIGGER, PI_INPUT) != PI_NO_ERROR) {
        fprintf(stderr, "Error setting GPIO4 direction: %s\n", pi_gpio_error_string());
        exit(EXIT_FAILURE);
    }
    if (pi_gpio_set_pull_up(GPIO_TRIGGER, PI_PULL_UP) != PI_NO_ERROR) {
        fprintf(stderr, "Error setting GPIO4 pull-up: %s\n", pi_gpio_error_string());
        exit(EXIT_FAILURE);
    }
}

// Function: Setup BMP180
void setup_bmp180() {
    if (i2c_open(BMP180_I2C_BUS) != I2C_OK) {
        fprintf(stderr, "Error opening I2C bus: %s\n", i2c_strerror(I2C_ERROR));
        exit(EXIT_FAILURE);
    }

    if (i2c_smbus_write_byte_data(BMP180_I2C_BUS, BMP180_I2C_ADDR, 0x02) != I2C_OK) {
        fprintf(stderr, "Error writing to BMP180: %s\n", i2c_strerror(I2C_ERROR));
        exit(EXIT_FAILURE);
    }

    // Read calibration coefficients
    uint16_t calib_data[7];
    if (i2c_smbus_read_i2c_block_data(BMP180_I2C_BUS, BMP180_I2C_ADDR, 0xAA, 7, calib_data) != I2C_OK) {
        fprintf(stderr, "Error reading BMP180 calibration data: %s\n", i2c_strerror(I2C_ERROR));
        exit(EXIT_FAILURE);
    }

    if (memcmp(bmp180_calib, calib_data, 7) != 0) {
        fprintf(stderr, "Invalid BMP180 calibration data. Sensor may be faulty.\n");
        exit(EXIT_FAILURE);
    }

    // Set oversampling
    if (bmp180_set_config(BMP180_OSS) != BMP180_OK) {
        fprintf(stderr, "Error setting BMP180 configuration: %s\n", bmp180_error_string());
        exit(EXIT_FAILURE);
    }
}

// Function: Read BMP180 pressure and temperature
void read_bmp180(uint16_t *pressure, uint16_t *temperature) {
    bmp180_set_resolution(BMP180_RES_0p25); // 0.25 hPa resolution
    bmp180_measure();
    *pressure = bmp180_readPressure();
    *temperature = bmp180_readTemperature();
}

// Function: Toggle logging state
void toggle_logging(bool state) {
    if (state) {
        pi_set_watchdog(200000); // 200 ms watchdog timeout
    } else {
        pi_unset_watchdog();
    }

    // Debounce GPIO4 using pigpio tick comparison
    static uint32_t last_trigger = 0;
    if (pi_pigpio_get_time() - last_trigger >= 200000) { // 200 ms debounce
        last_trigger = pi_pigpio_get_time();
        if (pi_gpio_level(GPIO_TRIGGER) == PI_LOW) {
            // Falling edge detected
            toggle_logging(!state);
        }
    }
}

// Function: Handle interrupt (falling edge on GPIO4)
void handle_interrupt(int signum) {
    // Falling edge detected on GPIO4
    toggle_logging(!toggle_logging()); // Toggle logging state
}

// Function: Log pressure to file
void log_pressure(float pressure) {
    FILE *file = fopen(PRESSURE_LOG_FILE, "a+");
    if (!file) {
        fprintf(stderr, "Error opening file for writing: %s\n", strerror(errno));
        return;
    }

    fprintf(file, "%f hPa\n", pressure);
    fclose(file);
}

// Function: Cleanup and exit on SIGINT
void cleanup() {
    i2c_close();
    pi_pigpio_stop();
    pi_cleanup();
    printf("SIGINT received. Closing resources and exiting.\n");
    exit(EXIT_SUCCESS);
}

