    int pin = GPIO_PIN;
    int rc;

    // Pull GPIO pin low for start signal
    pigpioWrite(pin, 0);
    usleep(START_SIGNAL_MS * 1000); // 1 ms
    pigpioWrite(pin, 1); // High for start signal
    usleep(START_SIGNAL_US); // 20-40 µs

    // Release GPIO pin
    pigpioWrite(pin, 0);

    // Read GPIO pin for 40-bit response
    for (int i = 0; i < 40; ++i) {
        rc = pigpioRead(pin);
        if (rc < 0) {
            syslog(LOG_ERR, "Failed to read GPIO pin: %s", pigpioErrorString(rc));
            return;
        }
        data->humidity = (data->humidity << 1) | rc; // LSB first
    }

    // Validate checksum
    int checksum = (data->humidity & 0x80) + (data->humidity & 0x7F);
    if (checksum != 0xFF) {
        syslog(LOG_ERR, "Checksum failed, DHT22 data invalid");
        return;
    }

    // Sensor reading successful
