        return;
    }

    // Check HTTP response code
    char *response = curl_easy_getinfo(curl_handle, CURLINFO_RESPONSE_CODE, NULL);
    if (response[0] != '2') {
        syslog(LOG_ERR, "Non-2xx HTTP response code: %s", response);
        return;
