        read_temperature();

        // Determine fan state based on temperature
        int fan_state = (temp_celsius < 4500) ? 0 : ((temp_celsius < 5500) ? 1 : ((temp_celsius < 6500) ? 2 : 3));

        // Check if the desired state is within bounds
        if (fan_state > MAX_FAN_STATE) {
            fan_state = MAX_FAN_STATE;
        }

        // Write fan state
        write_fan_state(fan_state);

        // Check if temperature changed to log a message
        if (last_temp_celsius != temp_celsius) {
            log_fan_change("Changed fan state to %d at %s", fan_state, ctime(&current_time));
        }

        // Sleep for 5 seconds
        usleep(5000);

        // Check for shutdown signals
        handle_signals(0);
    }

    // Close files on exit
    close(TEMP_FILE);
    close(COOLING_DEVICE);

    return 0;
}

// Function to open necessary files
void open_files() {
    TEMP_FILE_fd = open(TEMP_FILE, O_RDONLY);
    if (TEMP_FILE_fd == -1) {
        perror("Failed to open temperature file");
        exit(EXIT_FAILURE);
    }

    COOLING_DEVICE_fd = open(COOLING_DEVICE, O_WRONLY);
    if (COOLING_DEVICE_fd == -1) {
        perror("Failed to open cooling device file");
        close(TEMP_FILE_fd);
        exit(EXIT_FAILURE);
    }
}

// Function to read the CPU temperature
void read_temperature() {
    char temp_str[10];
    ssize_t bytes_read;

    // Attempt to read temperature
    do {
        bytes_read = read(TEMP_FILE_fd, temp_str, sizeof(temp_str) - 1);
        if (bytes_read > 0) {
            temp_celsius = (int)(temp_str[0] - '0') * 1000;
            last_temp_celsius = temp_celsius;
        }
    } while (bytes_read == -1 && errno == EINTR);

    if (bytes_read == -1) {
        perror("Failed to read temperature");
        // Retry on the next loop iteration
    }
}

// Function to write the fan state to the cooling device
void write_fan_state(int state) {
    char state_str[3];
    sprintf(state_str, "%d", state);

    // Attempt to write the fan state
    if (write(COOLING_DEVICE_fd, state_str, strlen(state_str)) != strlen(state_str)) {
        perror("Failed to write fan state");
        // Retry on the next loop iteration
    }
}

// Function to handle SIGINT and SIGTERM signals
void handle_signals(int signum) {
    // Stop the fan and log the shutdown
    write_fan_state(0);
    fprintf(stderr, "Shutting down fan and exiting due to signal %d\n", signum);

    // Exit cleanly
    exit(EXIT_SUCCESS);
}

// Function to log a fan speed change with a timestamp
void log_fan_change(const char *message) {
    time_t now = time(NULL);
    char buffer[100];

    // Format the log message with timestamp
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S ", localtime(&now));
    strcat(buffer, message);

    // Write to the log file
    FILE *log_file = fopen(LOG_FILE_PATH, "a+");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s\n", buffer);
    fclose(log_file);
}

