#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <pigpio.h>
#include <stdint.h>

#define GPIO18 18
#define MAX31855_CS GPIO8
#define MAX31855_CLK GPIO11
#define MAX31855_DO GPIO9

#define TARGET_TEMPERATURE 50
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01

// Constants for MAX31855 communication
#define MAX31855_ADDR 0x28
#define MAX31855_READ_INPUT 0x00
#define MAX31855_READ_FAULT 0x02

// PID constants
#define PID_GAIN_Kp Kp
#define PID_GAIN_Ki Ki
#define PID_GAIN_Kd Kd

// Heater control variables
int heater_pwm_fd = -1;
int heater_pwm;

// SPI communication variables
int spi_fd = -1;
uint8_t spi_buf[4];
int spi_mode = SPI_MODE_0; // 500 kHz
int spi_speed_hz = 500000;

// PID variables
float error;
float output;
float last_temperature;

// Heater log file
FILE *heater_log;

// Function prototypes
void setup_pigpio();
void setup_spi();
void read_temperature();
void pid_calculation(float temperature);
void control_heater(float duty_cycle);
void handle_spi_error();
void handle_max31855_fault();
void handle_temperature_limits();
void cleanup_resources();

// Main function
int main() {
    signal(SIGINT, cleanup_resources);
    signal(SIGTERM, cleanup_resources);

    setup_pigpio();
    setup_spi();
    heater_pwm_fd = open("/dev/pigpio", O_RDWR);
    if (heater_pwm_fd == -1) {
        fprintf(stderr, "Failed to open /dev/pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    heater_pwm = pigpio_open(heater_pwm_fd, 0);
    if (heater_pwm == -1) {
        fprintf(stderr, "Failed to open GPIO pin %d: %s\n", GPIO18, pigpio_error());
        close(heater_pwm_fd);
        return EXIT_FAILURE;
    }

    heater_log = fopen("heater_log.txt", "a+");
    if (!heater_log) {
        fprintf(stderr, "Failed to open heater_log.txt: %s\n", strerror(errno));
        fclose(heater_pwm);
        close(heater_pwm_fd);
        return EXIT_FAILURE;
    }

    pid_calculation(TARGET_TEMPERATURE);

    while (1) {
        // Read temperature
        read_temperature();

        // PID calculation
        output = pid_calculation(last_temperature);

        // Control heater
        control_heater(output);

        // Log data
        fprintf(heater_log, "Temperature: %.1f°C, PWM: %d, PID Output: %.2f\n",
                last_temperature, heater_pwm, output);

        // Sleep for 1 second
        usleep(1000000);
    }

    fclose(heater_log);
    control_heater(0.0); // Disable heater
    pigpio_close(heater_pwm);
    close(heater_pwm_fd);

    return EXIT_SUCCESS;
}

// Function to setup pigpio
void setup_pigpio() {
    if (pigpio_init() == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }
}

// Function to setup SPI communication
void setup_spi() {
    struct spi_ioc_transfer xfer[2];

    xfer[0].tx_buf = spi_buf;
    xfer[0].rx_buf = NULL;
    xfer[0].len = 4;
    xfer[0].speed_hz = spi_speed_hz;
    xfer[0].bits_per_word = 8;
    xfer[0].cs_change = 1;
    xfer[0].delay_usecs = 0;

    xfer[1].tx_buf = NULL;
    xfer[1].rx_buf = NULL;
    xfer[1].len = 0;
    xfer[1].speed_hz = spi_speed_hz;
    xfer[1].bits_per_word = 8;
    xfer[1].cs_change = 1;
    xfer[1].delay_usecs = 0;

    xfer[0].ce_change = 1;
    xfer[1].ce_change = 1;

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd == -1) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &spi_mode) == -1) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BAUDRATE, &spi_speed_hz) == -1) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (mmap(NULL, 4096, PROT_READ | PROT_WRITE, MAP_SHARED, spi_fd, 0) == MAP_FAILED) {
        fprintf(stderr, "Failed to mmap SPI device: %s\n", strerror(errno));
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Start SPI transfer
    if (write(spi_fd, xfer, sizeof(xfer)) != 2) {
        fprintf(stderr, "Failed to start SPI transfer: %s\n", strerror(errno));
        munmap(NULL, 4096);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
}

// Function to read temperature from MAX31855
void read_temperature() {
    uint16_t raw_data;

    // Write command to read input
    spi_buf[0] = MAX31855_READ_INPUT;
    spi_buf[1] = MAX31855_ADDR;
    spi_buf[2] = 0; // Command byte
    spi_buf[3] = 0; // Not used

    write(spi_fd, spi_buf, 4);

    // Read response
    if (read(spi_fd, spi_buf, 4) != 4) {
        handle_spi_error();
        return;
    }

    raw_data = (spi_buf[0] << 8) | spi_buf[1];

    // Convert raw data to temperature
    float temperature = (raw_data * 0.25) - 273.15; // Assuming 0°C reference

    last_temperature = temperature;
}

// PID calculation function
void pid_calculation(float temperature) {
    error = temperature - TARGET_TEMPERATURE;
    output = Kp * error + Ki * (error - last_error) + Kd * (error - previous_error);
    previous_error = error;
    last_error = error;
}

// Function to control the heater based on PID output
void control_heater(float duty_cycle) {
    if (duty_cycle < 0.0 || duty_cycle > 100.0) {
        fprintf(heater_log, "Invalid duty cycle: %f\n", duty_cycle);
        return;
    }

    if (ioctl(heater_pwm_fd, GPIO_SET, duty_cycle) == -1) {
        fprintf(stderr, "Failed to set GPIO18 duty cycle: %s\n", strerror(errno));
        return;
    }

    fprintf(heater_log, "Heater duty cycle set to: %d%%\n", (int)(duty_cycle * 100));
}

// Function to handle SPI communication errors
void handle_spi_error() {
    fprintf(heater_log, "SPI communication error.\n");
    control_heater(0.0); // Disable heater
}

// Function to handle MAX31855 fault bits
void handle_max31855_fault() {
    uint8_t fault_bits = MAX31855_READ_FAULT;

    if ((fault_bits & 0x01) != 0) { // Open circuit
        fprintf(heater_log, "Open circuit detected.\n");
        control_heater(0.0); // Disable heater
    }

    if ((fault_bits & 0x02) != 0) { // Short to GND
        fprintf(heater_log, "Short to GND detected.\n");
        control_heater(0.0); // Disable heater
    }

    if ((fault_bits & 0x04) != 0) { // Short to VCC
        fprintf(heater_log, "Short to VCC detected.\n");
        control_heater(0.0); // Disable heater
    }
}

// Function to handle temperature limits
void handle_temperature_limits() {
    if (last_temperature < 0.0) {
        fprintf(heater_log, "Temperature below 0°C detected. Disabling heater.\n");
        control_heater(0.0);
    } else if (last_temperature > 100.0) {
        fprintf(heater_log, "Temperature above 100°C detected. Disabling heater.\n");
        control_heater(0.0);
    }
}

// Function to clean up resources on SIGINT/SIGTERM
void cleanup_resources() {
    control_heater(0.0); // Disable heater
    pigpio_close(heater_pwm);
    close(heater_pwm_fd);
    fclose(heater_log);

    // Close SPI device and release memory mapping
    close(spi_fd);
    munmap(NULL, 4096);
}

