#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define PWM_FREQ 25000
#define MIN_TEMP 40
#define MAX_TEMP 70

FILE *fp;
char buffer[256];
int temp_fd;
pid_t pid;

// Function prototypes
void cleanup();
void handle_signal(int signum);

int main() {
    // Initialize pigpio
    if (pgpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the temperature file
    temp_fd = open("/sys/class/thermal/thermal_zone0/temp", O_RDONLY);
    if (temp_fd == -1) {
        fprintf(stderr, "Failed to open temperature file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Set up signal handler to clean up
    pid = fork();
    if (pid == 0) {
        // Child process: run the main loop
        while (1) {
            // Poll temperature
            char temp_str[10];
            if (fgets(buffer, sizeof(buffer), stdin) != NULL) {
                break; // Exit on SIGINT/SIGTERM
            }
            if (fread(temp_str, 1, 10, temp_fd) == 10) {
                int temp_celsius = atoi(temp_str);
                float duty_cycle = (float)((temp_celsius - MIN_TEMP) / (MAX_TEMP - MIN_TEMP)) * 100.0;

                // Set PWM duty cycle
                if (pgpio_set_PWM_duty(GPIO_PIN, duty_cycle / 100.0 * PWM_FREQ) < 0) {
                    fprintf(stderr, "Failed to set PWM duty cycle: %s\n", pigpio_error());
                    break;
                }

                // Log data
                time_t now = time(NULL);
                struct tm timeinfo;
                localtime_r(&now, &timeinfo);
                char log_entry[256] = "Timestamp,Temp(°C),DutyCycle%";
                strftime(log_entry, sizeof(log_entry), "%F %T,%f", &timeinfo);
                strcat(log_entry, ",");
                strcat(log_entry, temp_str);
                strcat(log_entry, ",");

                // Write to CSV file
                if (fp == NULL) {
                    fp = fopen("cooling_log.csv", "a");
                    if (fp == NULL) {
                        fprintf(stderr, "Failed to open/write to CSV file: %s\n", strerror(errno));
                        break;
                    }
                }
                fprintf(fp, "%s,%d,%f\n", log_entry, temp_celsius, duty_cycle);

                // Sleep for 5 seconds
                sleep(5);
            } else {
                fprintf(stderr, "Failed to read temperature: %s\n", strerror(errno));
                break;
            }
        }

        // Clean up in child on exit
        cleanup();
    } else {
        // Parent process: wait for child and handle signals
        while (waitpid(pid, NULL, 0) != -1);
        // Ensure cleanup even if fork failed
        cleanup();
    }

    // Close temperature file and exit
    fclose(temp_fd);
    pigpio_cleanup();
    return 0;
}

// Cleanup function
void cleanup() {
    if (fp != NULL) {
        fclose(fp);
        fp = NULL;
    }
    if (temp_fd != -1) {
        close(temp_fd);
        temp_fd = -1;
    }
}

// Signal handler
void handle_signal(int signum) {
    fprintf(stderr, "Received signal %d, shutting down...\n", signum);
    // Turn off the fan
    pgpio_set_PWM_duty(GPIO_PIN, 0);
    // Exit the program
    exit(EXIT_SUCCESS);
}

