#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>

// Define I2C addresses for the multiplexer mapped sensors
#define SLF3S_ADDR_1 0x08
#define SLF3S_ADDR_2 0x09

// SLF3S-1300F continuous measurement command
#define CMD_CONTINUOUS_MEASUREMENT 0x3608

// CRC-8 polynomial
uint8_t crc8_table[256] = {
    // ... precomputed CRC-8 table ...
};

// Function to calculate CRC-8 of a byte
uint8_t calculate_crc8(uint8_t data) {
    uint8_t crc = 0;
    for (int i = 0; i < 8; i++) {
        if (crc & 1) {
            crc = (crc >> 1) ^ crc8_table[(crc >> 7) & 0x01];
        } else {
            crc = crc >> 1;
        }
    }
    return crc;
}

// Function to read and validate SLF3S-1300F data
int read_and_validate_slf3s(uint8_t address, FILE *log_file) {
    int retries = 3;
    while (retries--) {
        int result = pigpio_i2c_read(address, 3, NULL);
        if (result > 0) {
            uint8_t data[3] = {pigpio_i2c_data(0), pigpio_i2c_data(1), pigpio_i2c_data(2)};
            uint8_t crc = calculate_crc8(data[2]);

            if (data[2] == crc) {
                float flow1 = (float)data[0] * 0.01;
                float flow2 = (float)data[1] * 0.01;
                fprintf(log_file, "%s,%f,%f\n", 
                        gmtime(&time(NULL)) + tm_strftime("%Y-%m-%d %H:%M:%S"), 
                        flow1, flow2);
                return 0; // Success
            } else {
                // CRC failed, retry
                fprintf(stderr, "SLF3S-1300F CRC error on address %d, retrying...\n", address);
            }
        } else {
            fprintf(stderr, "Failed to read from SLF3S-1300F on address %d, retrying...\n", address);
        }
        // Wait for a short period before retrying
        usleep(100000);
    }
    // If all retries fail, log an error and exit
    fprintf(stderr, "Failed to read from SLF3S-1300F on address %d after %d retries.\n", address, retries);
    return -1;
}

int main() {
    // Initialize pigpio
    pigpio *pi = NULL;
    if (pigpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }
    pi = pigpio_open();

    // Set up signal handlers for clean shutdown
    struct sigaction sa;
    sa.sa_handler = SIG_IGN; // Ignore SIGINT/SIGTERM for daemon processes
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    FILE *log_file = fopen("flow_log.txt", "a+");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open flow_log.txt for writing.\n");
        pigpio_close(pi);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Poll both sensors
        int flow1_result = read_and_validate_slf3s(SLF3S_ADDR_1, log_file);
        if (flow1_result < 0) {
            break; // Exit on fatal error
        }

        int flow2_result = read_and_validate_slf3s(SLF3S_ADDR_2, log_file);
        if (flow2_result < 0) {
            break; // Exit on fatal error
        }
    }

    // Clean shutdown
    fclose(log_file);
    pigpio_close(pi);

    // Release resources
    pi = NULL;

    return EXIT_SUCCESS;
}

