#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define PULSE_THRESHOLD 1

// Mutex for thread-safe access to the pulse counter
pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    fprintf(stderr, "Received signal %d, shutting down...\n", signum);
    pigpio_stop();
    fclose(logfile);
    pthread_mutex_destroy(&pulse_mutex);
    exit(EXIT_SUCCESS);
}

// Interrupt Service Routine (ISR) for GPIO 18
void gpiointerrupt(int channel) {
    static int pulse_count = 0;
    if (gpio_input(channel) == GPIO_RISING) {
        // Increment pulse counter only for rising edges
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

int main() {
    // Initialize pigpio
    if (pigpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error());
        return EXIT_FAILURE;
    }

    // Register GPIO interrupt for GPIO 18
    if (pigpio_request_irq(GPIO_PIN, gpiointerrupt, 0, 0, "MLX90254 ISR") < 0) {
        fprintf(stderr, "Failed to register GPIO interrupt: %s\n", pigpio_error());
        pigpio_uninit();
        return EXIT_FAILURE;
    }

    // Open log file for appending and flushing
    FILE *logfile = fopen("rpm_log.txt", "a+");
    if (logfile == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        pigpio_uninit();
        return EXIT_FAILURE;
    }

    // Main thread loop
    while (1) {
        struct timespec start, end;
        int rpm;

        // Start timer
        clock_gettime(CLOCK_MONOTONIC, &start);

        // Wait for a second
        usleep(1000000);

        // End timer
        clock_gettime(CLOCK_MONOTONIC, &end);

        // Calculate RPM
        rpm = (pulse_count * 60) / (double)(end.tv_sec - start.tv_sec);

        // Log RPM with timestamp
        fprintf(logfile, "Timestamp: %lld, RPM: %.2f\n", (long long)start.tv_sec, rpm);

        // Reset pulse counter
        pulse_count = 0;

        // Mutex protection for safe access
        pthread_mutex_lock(&pulse_mutex);
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);
    }

    // Clean up on SIGINT/SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Graceful shutdown
    pigpio_stop();
    fclose(logfile);
    pthread_mutex_destroy(&pulse_mutex);

    return EXIT_SUCCESS;
}

