#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <sys/signal.h>

#define I2C_DEVICE_PATH "/dev/i2c-1"
#define ADPD144RI_I2C_ADDRESS 0x39
#define ADPD144RI_PART_ID_REGISTER 0x00
#define ADPD144RI_FIFO_DATA_REGISTER_RED 0x01
#define ADPD144RI_FIFO_DATA_REGISTER_IR 0x02
#define THRESHOLD_IR 2000
#define GPIO_PIN_RED 17
#define GPIO_PIN_IR 27

// Function prototypes
void setup_i2c();
void setup_gpios();
void read_part_id();
void read_fifos();
void trigger_led();
void log_data(char* data);
void cleanup();

int main() {
    // Initialize signal handlers
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sa.sa_flags = SA_RESTART;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Setup I2C and GPIO
    setup_i2c();
    setup_gpios();

    // Main loop
    while (1) {
        // Read part ID to check sensor presence
        read_part_id();

        // Read FIFO data
        read_fifos();

        // Check IR reading and trigger LED if threshold exceeded
        if (read_fifos()[1] > THRESHOLD_IR) {
            trigger_led();
        }

        // Log data
        log_data((char*)"{time},red,ir".sizeof("{time},red,ir"));
        usleep(100000); // Sleep for 100 ms
    }
    return 0;
}

// Function definitions

void setup_i2c() {
    int fd = open(I2C_DEVICE_PATH, O_RDWR);
    if (fd == -1) {
        perror("Error opening I2C device");
        exit(EXIT_FAILURE);
    }

    struct i2c_msg msg = {
        .addr = ADPD144RI_I2C_ADDRESS,
        .flags = 0,
        .len = sizeof(uint16_t),
    };

    msg.data = (uint8_t *) &msg.len; // Send register address

    if (ioctl(fd, I2C_SLAVE, ADPD144RI_I2C_ADDRESS) == -1) {
        perror("Error: i2c slave address");
        exit(EXIT_FAILURE);
    }

    // Keep the I2C connection open for subsequent reads
}

void setup_gpios() {
    gpiod_set_data_direction(GPIO_PIN_RED, GPIOD_DIR_OUT);
    gpiod_write(GPIO_PIN_RED, 1); // Set GPIO 17 as output

    gpiod_set_data_direction(GPIO_PIN_IR, GPIOD_DIR_OUT);
    gpiod_write(GPIO_PIN_IR, 0); // Set GPIO 27 as output (initially low)
}

void read_part_id() {
    struct i2c_msg msg = {
        .addr = ADPD144RI_I2C_ADDRESS,
        .flags = 0,
        .len = sizeof(uint16_t),
        .buf = (uint8_t *)&(ADPD144RI_PART_ID_REGISTER)
    };

    if (ioctl(I2C_DEVICE_PATH, I2C_transfer, &msg) < 0) {
        perror("Error reading part ID");
        exit(EXIT_FAILURE);
    }

    if (msg.buf[0] != 0x1234) {
        fprintf(stderr, "Sensor not detected (expected 0x1234)\n");
        exit(EXIT_FAILURE);
    }
}

void read_fifos() {
    struct i2c_msg msg_red = {
        .addr = ADPD144RI_I2C_ADDRESS,
        .flags = 0,
        .len = sizeof(uint16_t),
        .buf = (uint8_t *)&(ADPD144RI_FIFO_DATA_REGISTER_RED)
    };

