#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <libgpiod/gpiod.h>

#define MAX9814_OUT_GPIO 17
#define MAX9814_GAIN_GPIO 18
#define GAIN_LOW_LEVEL 0

// Function prototypes
void setup_gpios(void);
void handle_signal(int signum);
void poll_and_log_peak(int gpio, const char *filename);
void cleanup(void);

int main(void) {
    // Initialize libgpiod
    if (gpiod_init() < 0) {
        perror("gpiod_init");
        exit(EXIT_FAILURE);
    }

    // Set up GPIO pins
    setup_gpios();

    // Signal handler for SIGINT and SIGTERM
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (1) {
        poll_and_log_peak(MAX9814_OUT_GPIO, "audio_log.txt");
        usleep(10000); // 10 ms delay
    }

    // Clean up resources on exit
    cleanup();

    return 0;
}

// Function to set up GPIO pins
void setup_gpios(void) {
    struct gpiod_device *gpiodev;
    struct gpiod_pin *out_pin, *gain_pin;

    // Open GPIO device
    gpiodev = gpiod_get_by_name("gpiochip0");
    if (!gpiodev) {
        perror("gpiod_get_by_name");
        exit(EXIT_FAILURE);
    }

    // Open OUT pin
    out_pin = gpiod_pin_new(gpiodev, MAX9814_OUT_GPIO);
    if (!out_pin) {
        perror("gpiod_pin_new (OUT)");
        gpiod_device_free(gpiodev);
        exit(EXIT_FAILURE);
    }

    // Set OUT pin as input
    if (gpiod_pin_direction(out_pin, GPIOD_DIR_IN) < 0) {
        perror("gpiod_pin_direction (OUT, IN)");
        gpiod_pin_free(out_pin);
        gpiod_device_free(gpiodev);
        exit(EXIT_FAILURE);
    }

    // Open GAIN pin
    gain_pin = gpiod_pin_new(gpiodev, MAX9814_GAIN_GPIO);
    if (!gain_pin) {
        perror("gpiod_pin_new (GAIN)");
        gpiod_pin_free(out_pin);
        gpiod_device_free(gpiodev);
        exit(EXIT_FAILURE);
    }

    // Set GAIN pin as output and LOW for 60dB gain
    if (gpiod_pin_direction(gain_pin, GPIOD_DIR_OUT) < 0 ||
        gpiod_pin_value(gain_pin) != GAIN_LOW_LEVEL) {
        perror("gpiod_pin_direction (GAIN, OUT) or setting GAIN_LOW_LEVEL");
        gpiod_pin_free(gain_pin);
        gpiod_pin_free(out_pin);
        gpiod_device_free(gpiodev);
        exit(EXIT_FAILURE);
    }

    gpiod_pin_free(out_pin);
    gpiod_pin_free(gain_pin);
    gpiod_device_free(gpiodev);
}

// Function to poll and log a peak
void poll_and_log_peak(int gpio, const char *filename) {
    struct timespec timestamp;
    struct gpiod_value value;
    int level;

    // Get current time
    clock_gettime(CLOCK_REALTIME, &timestamp);

    // Poll GPIO pin
    if (gpiod_get_value(gpiod_get_pin(gpiodev, gpio), &value) < 0) {
        perror("gpiod_get_value");
        return;
    }

    // Check for rising edge
    level = value.value;
    if (level > 0) {
        // Log the peak
        char timestamp_str[50];
        strftime(timestamp_str, sizeof(timestamp_str), "%F %T ", &timestamp);

        FILE *file = fopen(filename, "a");
        if (!file) {
            perror("fopen");
            return;
        }

        fprintf(file, "%s 1\n", timestamp_str);
        fclose(file);

        // Release the GPIO value
        gpiod_value_free(&value);
    }

    // Clean up
    gpiod_value_free(&value);
}

// Function to clean up resources
void cleanup(void) {
    // Close and free resources
    gpiod_device_free(gpiodev);
}

// Signal handler to clean up on SIGINT/SIGTERM
void handle_signal(int signum) {
    // Clean up resources
    cleanup();
    exit(EXIT_SUCCESS);
}

