#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>

// Define the CRC-8 polynomial and initial value
uint8_t crc8_poly = 0x31;
uint8_t crc8_init = 0xFF;

// Function to calculate CRC-8
uint8_t crc8(uint8_t *buf, uint8_t len) {
    uint8_t crc = crc8_init;
    for (uint8_t i = 0; i < len; i++) {
        crc ^= *buf++;
        for (uint8_t j = 8; j > 0; j--) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ crc8_poly;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to convert raw flow value to uL/min
float raw_to_flow_rate(uint16_t raw_value) {
    // Assuming the raw value is directly proportional to flow rate in uL/min
    return (float)raw_value / 1000.0;
}

// Main function
int main() {
    // Signal handler for SIGINT (Ctrl+C)
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Initialize pigpio
    pigpio *pi = NULL;
    if (pigpio_init() == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error());
        return EXIT_FAILURE;
    }
    pi = pigpio_new();

    // Open I2C bus 1
    int i2c_fd = -1;
    if (i2c_open(1, 0) == -1) {
        fprintf(stderr, "Failed to open I2C bus 1: %s\n", i2c_strerror(-1));
        pigpio_free(pi);
        pigpio_exit();
        return EXIT_FAILURE;
    }

    // Sensor address and command
    uint8_t sensor_address = 0x36;
    uint16_t command = 0x3608;

    // File path for CSV log
    const char *log_file_path = "flow_log.csv";

    // Open log file in append mode
    FILE *log_file = fopen(log_file_path, "a+");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", log_file_path);
        fclose(i2c_fd);
        i2c_close(1);
        pigpio_free(pi);
        pigpio_exit();
        return EXIT_FAILURE;
    }

    // Variables for flow rate and CRC check
    uint16_t flow_rate;
    uint8_t crc8_value;

    // Main loop
    while (1) {
        // Send command to start continuous measurement
        if (i2c_write(sensor_address, &command, 2) == -1) {
            fprintf(stderr, "Failed to write command: %s\n", i2c_strerror(-1));
            continue;
        }

        // Wait for 1000 ms
        struct timespec timeout = { 1000, 0 };
        if (nanosleep(&timeout, NULL) == -1) {
            fprintf(stderr, "Failed to sleep: %s\n", strerror(errno));
            continue;
        }

        // Read 3 bytes from the sensor
        if (i2c_read(sensor_address, 3, NULL) == -1) {
            fprintf(stderr, "Failed to read from sensor: %s\n", i2c_strerror(-1));
            continue;
        }

        // Extract raw flow value and CRC-8
        uint8_t data[3];
        data[0] = (uint8_t)(read16big(&data[1])); // MSB first
        crc8_value = data[2];

        // Validate CRC-8
        if (crc8(data, 3) != crc8_value) {
            fprintf(stderr, "CRC check failed, skipping reading.\n");
            continue;
        }

        // Convert raw flow value to uL/min
        flow_rate = raw_to_flow_rate(data[0]);

        // Log the flow rate
        char timestamp[23];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S,", localtime(&now));
        fprintf(log_file, "%s,%.3f\n", timestamp, flow_rate);

        // Flush and close log file
        fflush(log_file);
        fclose(log_file);

        // Close I2C handle on SIGINT
        sa.sa_handler = NULL; // Reset handler
        sigaction(SIGINT, &sa, NULL);
    }

    // Cleanup on SIGINT
    void cleanup(int signum) {
        fprintf(stderr, "SIGINT received, terminating...\n");
        fclose(log_file);
        i2c_close(1);
        pigpio_free(pi);
        pigpio_exit();
        exit(EXIT_SUCCESS);
    }

    return EXIT_SUCCESS;
}

