#include <stdlib.h>
#include <time.h>
#include <pigpio.h>
#include <stdint.h>

#define PIGPIO_ID 0  // Use the default pigpio ID

// Constants for the VOC sensor
#define SENSOR_ADDRESS 0x70
#define TVOC_REG_OFFSET 1
#define TVOC_DATA_LENGTH 2
#define EC02_REG_OFFSET 5
#define EC02_DATA_LENGTH 2
#define IAQ_CLAMP_MIN 0
#define IAQ_CLAMP_MAX 100

// Function prototypes
void init_pigpio();
void cleanup_pigpio();
int i2c_read(uint8_t address, uint8_t reg, uint8_t* data, size_t length);
int i2c_write(uint8_t address, uint8_t reg, const uint8_t* data, size_t length);
void compute_iaq(uint16_t tvoc, uint16_t e_co2, float* iaq);
void log_air_quality(const char* timestamp, float iaq, uint16_t tvoc, uint16_t e_co2);

int main() {
    srand(time(NULL)); // Seed random number generator for simplicity

    // Initialize pigpio
    init_pigpio();

    // Main loop
    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);

        uint8_t tvoc_data[2];
        uint8_t e_co2_data[2];
        int tvoc_read_ret = i2c_read(SENSOR_ADDRESS, TVOC_REG_OFFSET, tvoc_data, TVOC_DATA_LENGTH);
        if (tvoc_read_ret != 0) {
            fprintf(stderr, "Error reading TVOC data: %d\n", tvoc_read_ret);
            continue;
        }

        int e_co2_read_ret = i2c_read(SENSOR_ADDRESS, EC02_REG_OFFSET, e_co2_data, EC02_DATA_LENGTH);
        if (e_co2_read_ret != 0) {
            fprintf(stderr, "Error reading eCO2 data: %d\n", e_co2_read_ret);
            continue;
        }

        float tvoc_ppb = (float)tvoc_data[0] + (float)tvoc_data[1] * 256;
        float e_co2_ppm = (float)e_co2_data[0] + (float)e_co2_data[1] * 256;

        compute_iaq(&tvoc_ppb, e_co2_ppm, &iaq);

        // Log air quality
        char timestamp[50];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &ts);
        log_air_quality(timestamp, iaq, tvoc_ppb, e_co2_ppm);

        // Sleep for 5 seconds
        usleep(5000000);
    }

    // Cleanup
    cleanup_pigpio();

    return 0;
}

// Function to initialize pigpio
void init_pigpio() {
    if (pigpio_open(PIGPIO_ID) == -1) {
        fprintf(stderr, "Failed to open pigpio: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }
}

// Function to cleanup pigpio
void cleanup_pigpio() {
    pigpio_close();
}

// Function to read from the I2C sensor
int i2c_read(uint8_t address, uint8_t reg, uint8_t* data, size_t length) {
    int ret = pigpio_i2c_read(address, reg, data, length);
    if (ret != length) {
        fprintf(stderr, "I2C read error: %d\n", ret);
        return ret;
    }
    return 0;
}

// Function to write to the I2C sensor (not used in this program)
int i2c_write(uint8_t address, uint8_t reg, const uint8_t* data, size_t length) {
    int ret = pigpio_i2c_write(address, reg, data, length);
    if (ret != length) {
        fprintf(stderr, "I2C write error: %d\n", ret);
        return ret;
    }
    return 0;
}

// Function to compute the IAQ index
void compute_iaq(float* tvoc, float e_co2, float* iaq) {
    *iaq = fminf(fmaxf(100 - (tvoc / 10.0), IAQ_CLAMP_MIN), IAQ_CLAMP_MAX);
}

// Function to log air quality to a CSV file
void log_air_quality(const char* timestamp, float iaq, uint16_t tvoc, uint16_t e_co2) {
    FILE* file = fopen("air_quality_log.csv", "a");
    if (!file) {
        fprintf(stderr, "Failed to open air_quality_log.csv for writing: %s\n", strerror(errno));
        return;
    }

    fprintf(file, "%s,IAQ,%u,%u\n", timestamp, (unsigned int)iaq, (unsigned int)tvoc, (unsigned int)e_co2);
    fclose(file);
}

