#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TOUCH_THRESHOLD_MS 5000
#define TOUCH_SENSOR_GPIO 17
#define TOUCH_SENSOR_PIN 11
#define CONSUMER_LABEL "ttp223_tamper"

volatile sig_atomic_t should_exit = 0;

void handle_signal(int signum) {
    should_exit = 1;
}

int main() {
    // Initialize libgpiod
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    ret = gpiod_chip_open("gpiochip0", GPIOD_OPEN_BY_NAME);
    if (ret) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", gpiod_strerror(ret));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_get_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to get gpiochip0: %s\n", gpiod_strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line = gpiod_line_request_one(chip, TOUCH_SENSOR_GPIO, GPIOD_LINE_IN, CONSUMER_LABEL);
    if (!line) {
        fprintf(stderr, "Failed to request line %d: %s\n", TOUCH_SENSOR_GPIO, gpiod_strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (!should_exit) {
        // Poll the line every 100 ms
        struct timespec timeout = { .tv_sec = 0, .tv_nsec = 100000000 };
        ret = gpiod_line_poll(line, &timeout);
        if (ret == -ETIMEDOUT) {
            // Timeout, continue polling
            continue;
        } else if (ret) {
            // Error occurred
            fprintf(stderr, "Error polling line: %s\n", gpiod_strerror(ret));
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        // Check if the sensor is touched
        int value = gpiod_line_get_value(line);
        if (value) {
            // Sensor is touched
            struct timespec start_time;
            clock_gettime(CLOCK_MONOTONIC, &start_time);

            // Wait for 5 seconds of continuous touch
            while (clock_gettime(CLOCK_MONOTONIC, &start_time) - start_time < (5 * 1000 * 1000)) {
                if (!gpiod_line_get_value(line)) {
                    // Sensor released, reset timer
                    break;
                }
            }

            // Intrusion alert
            printf("Intrusion Alert!\n");
            // Reset the touched state
            gpiod_line_set_value(line, 0);
        } else {
            // Sensor is not touched
        }

        // Cleanup on exit
        gpiod_line_release(line);
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

