#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <stdint.h>
#include <alsa/asoundlib.h>
#include <gpiod.h>

#define MIC_GPIO 17
#define MIC_DEVICE "/dev/snd/pcmC0D0c"
#define SAMPLE_RATE 48000
#define BIT_DEPTH 16
#define BUFFER_SIZE (1024 * 2) // 2 bytes per sample

// Function prototypes
void setup_audio_capture();
void handle_interrupts(int signum);
void cleanup();

int main() {
    signal(SIGINT, handle_interrupts);
    setup_audio_capture();
    while (1) {
        // Simulate data acquisition here
        // In a real scenario, replace this with actual I2S data acquisition
        uint8_t left_channel[BUFFER_SIZE];
        uint8_t right_channel[BUFFER_SIZE];

        // Fill left_channel and right_channel with simulated data
        // Example: left_channel[i] = (uint8_t)((i % 256) * 128 + 128); // Simple sine wave simulation

        // Process the data here to extract 24-bit samples and convert to 16-bit
        for (size_t i = 0; i < BUFFER_SIZE; i++) {
            uint32_t raw_sample = (left_channel[i] << 8) | right_channel[i];
            uint16_t pcm_sample = (raw_sample >> 8); // Extract 16-bit sample
            // Write to file
            write_audio_sample_to_file(pcm_sample);
        }
    }
    cleanup();
    return 0;
}

void setup_audio_capture() {
    // Initialize ALSA
    alsa_init();
    alsa_open(MIC_DEVICE, 0);

    // Initialize GPIO for L/R select pin
    gpiod_set_data_direction(MIC_GPIO, GPIOD_DIR_OUT);
    gpiod_write(MIC_GPIO, 1); // Set GPIO 17 to high (select left channel)

    // Open PCM device for reading
    int pcm_fd = open(MIC_DEVICE, O_RDONLY);
    if (pcm_fd == -1) {
        fprintf(stderr, "Error opening PCM device: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Set up PCM parameters
    snd_pcm_t *pcm_handle = snd_pcm_open_alsa(pcm_fd, "capture", SND_PCM_STREAM_CAPTURE, 0);
    if (pcm_handle == NULL) {
        fprintf(stderr, "Error opening PCM device: %s\n", snd_strerror(errno));
        close(pcm_fd);
        exit(EXIT_FAILURE);
    }

    snd_pcm_set_params(pcm_handle, SAMPLE_RATE, BIT_DEPTH, BUFFER_SIZE, SND_PCM_FORMAT_S16_LE);
    if (snd_pcm_prepare(pcm_handle) < 0) {
        fprintf(stderr, "Error preparing PCM: %s\n", snd_strerror(snd_pcm_prepare(pcm_handle)));
        snd_pcm_close(pcm_handle);
        close(pcm_fd);
        exit(EXIT_FAILURE);
    }

    // Allocate buffer for data
    snd_pcm_sframes_t bytes_written;
    void *buffer = malloc(BUFFER_SIZE * sizeof(uint16_t));
    if (buffer == NULL) {
        fprintf(stderr, "Error allocating buffer: %s\n", strerror(errno));
        snd_pcm_close(pcm_handle);
        close(pcm_fd);
        exit(EXIT_FAILURE);
    }
}

void handle_interrupts(int signum) {
    // Clean up on SIGINT (Ctrl+C)
    cleanup();
    exit(EXIT_SUCCESS);
}

void cleanup() {
    // Close PCM device
    snd_pcm_drop(pcm_handle);
    snd_pcm_drain(pcm_handle);
    snd_pcm_close(pcm_handle);

    // Release GPIO
    gpiod_write(MIC_GPIO, 0); // Set GPIO 17 to low

    // Close PCM device file descriptor
    close(pcm_fd);

    // Free buffer
    free(buffer);

    // Close ALSA
    alsa_close();
}

// Function to write a single 16-bit PCM sample to the file
void write_audio_sample_to_file(uint16_t pcm_sample) {
    // Open or truncate the file for writing
    int file_fd = open("audio_capture.pcm", O_WRONLY | O_CREAT, 0644);
    if (file_fd == -1) {
        fprintf(stderr, "Error opening file for writing: %s\n", strerror(errno));
        return;
    }

    // Write the sample
    ssize_t bytes_written = write(file_fd, &pcm_sample, sizeof(uint16_t));
    if (bytes_written != sizeof(uint16_t)) {
        fprintf(stderr, "Error writing sample to file: %s\n", strerror(errno));
        close(file_fd);
        return;
    }

    // Close the file after writing
    close(file_fd);
}

