void write_audio_sample_to_file(uint16_t pcm_sample) {
    // Open or truncate the file for writing
    int file_fd = open("audio_capture.pcm", O_WRONLY | O_CREAT, 0644);
    if (file_fd == -1) {
        fprintf(stderr, "Error opening file for writing: %s\n", strerror(errno));
        return;
    }

    // Write the sample
    ssize_t bytes_written = write(file_fd, &pcm_sample, sizeof(uint16_t));
    if (bytes_written != sizeof(uint16_t)) {
        fprintf(stderr, "Error writing sample to file: %s\n", strerror(errno));
        close(file_fd);
        return;
    }

    // Close the file after writing
    close(file_fd);
}
