#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>

// Define the magic number and struct for configuration
#define MAGIC_NUMBER 0x52444144
typedef struct {
    uint32_t startFrequency; // 77 GHz
    uint32_t endFrequency;   // 79 GHz
    uint16_t chirps;
    uint16_t samples;
    uint32_t framePeriod;    // 100 ms
} Config;

// Function prototypes
void setup_pigpio();
void setup_spi(int spi_channel);
void handle_spi_transfer_error(int error);
void write_log_header(FILE *log_file);
void read_and_log_heatmap_data(uint8_t *data, size_t length);
void cleanup_resources();
void signal_handler(int signum);

int main() {
    // Initialize global variables
    FILE *log_file = NULL;
    Config config;
    config.startFrequency = 77000000;
    config.endFrequency = 79000000;
    config.chirps = 64;
    config.samples = 256;
    config.framePeriod = 100; // in microseconds

    // Signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main program flow
    setup_pigpio();
    setup_spi(0);
    log_file = fopen("heatmap_log.bin", "wb");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    write_log_header(log_file);

    int frame_number = 0;
    uint32_t timestamp;
    while (1) {
        // Assert GPIO trigger
        pigpio_write(23, 1);

        // Wait for data-ready interrupt
        while (!pigpio_wait_oneshot(24)) {
        }

        // Read heatmap data
        uint8_t *data = malloc(32768);
        if (data == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }

        read_and_log_heatmap_data(data, 32768);

        // Increment frame number
        frame_number++;

        // Handle SIGINT/SIGTERM
        if (signal_pending(SIGINT) || signal_pending(SIGTERM)) {
            cleanup_resources();
            break;
        }
    }

    // Cleanup resources
    cleanup_resources();

    // Close log file and SPI
    fclose(log_file);
    pigpio_close();
    return 0;
}

// Function to setup pigpio
void setup_pigpio() {
    if (pigpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }
}

// Function to setup SPI channel 0
void setup_spi(int spi_channel) {
    if (pigpio_spi_init(spi_channel, 1000000, 0) < 0) {
        fprintf(stderr, "Failed to initialize SPI channel %d: %s\n", spi_channel, pigpio_error());
        exit(EXIT_FAILURE);
    }
}

// Function to handle SPI transfer errors
void handle_spi_transfer_error(int error) {
    fprintf(stderr, "SPI transfer error: %d\n", error);
    pigpio_spi_stop();
    cleanup_resources();
    exit(EXIT_FAILURE);
}

// Function to write log file header
void write_log_header(FILE *log_file) {
    // Write magic number
    fwrite(&MAGIC_NUMBER, sizeof(MAGIC_NUMBER), 1, log_file);

    // Write 8-byte timestamp
    timestamp = pigpio_get_time();
    fwrite(&timestamp, sizeof(uint32_t), 1, log_file);

    // Write configuration struct
    config.startFrequency = 77000000;
    config.endFrequency = 79000000;
    config.chirps = 64;
    config.samples = 256;
    config.framePeriod = 100000; // 100 ms in microseconds
    fwrite(&config, sizeof(Config), 1, log_file);
}

// Function to read and log heatmap data
void read_and_log_heatmap_data(uint8_t *data, size_t length) {
    // Write data to log file
    fwrite(data, sizeof(uint8_t), length, log_file);

    // Update frame number in log file (optional, for debugging)
    fprintf(log_file, "Frame %u\n", frame_number);
}

// Function to cleanup resources
void cleanup_resources() {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    pigpio_spi_stop();
    pigpio_close();
}

// Signal handler function
void signal_handler(int signum) {
    fprintf(stderr, "Caught signal %d, exiting...\n", signum);
    cleanup_resources();
    exit(EXIT_FAILURE);
}

