        usleep(100000); // Poll every 100 milliseconds
    }

    // Clean up on exit
    cleanup();

    return 0;
}

// Function to initialize libgpiod
void setup_gpiod() {
    // Check if opening GPIO device fails
    gpiod_device *gpiod;
    int ret = gpiod_open(&gpiod, GPIOD_DIR_DEV, GPIOD_OPEN_BY_NAME);
    if (ret < 0) {
        perror("gpiod_open");
        exit(EXIT_FAILURE);
    }

    // Check if GPIO chip can be opened
    gpiod_chip *chip;
    ret = gpiod_get_chip(gpiod, GPIO_NUM);
    if (ret < 0) {
        perror("gpiod_get_chip");
        gpiod_close(gpiod);
        exit(EXIT_FAILURE);
    }

    // Ensure GPIO pin is configured as input
    ret = gpiod_set_direction(chip, GPIO_NUM, GPIOD_DIR_INPUT);
    if (ret < 0) {
        perror("gpiod_set_direction");
        gpiod_release_chip(chip);
        gpiod_close(gpiod);
        exit(EXIT_FAILURE);
    }
}

// Function to poll the flame sensor
void poll_flame_sensor() {
    // Read the GPIO pin state
    gpiod_value_t value;
    ret = gpiod_get_value(chip, GPIO_NUM, &value);
    if (ret < 0) {
        perror("gpiod_get_value");
        return;
    }

    // Check for state transition
    if (value.value == 1) {
        log_state('1');
    } else {
        log_state('0');
    }

    // Alert on state change
    if (value.value != last_value) {
        printf("%s at %s\n", ALERT_MSG, ctime(&now));
        last_value = value.value;
    }

    // Sleep for 100 milliseconds
    usleep(100000);
}

// Function to handle SIGINT and SIGTERM signals
void handle_signal(int signum) {
    // Graceful shutdown
    printf("Received signal %d, shutting down...\n", signum);
    poll_flame_sensor(); // Ensure current state is logged
    cleanup();
    exit(EXIT_SUCCESS);
}

// Function to log the state to 'flame_log.txt'
void log_state(char state) {
    FILE *file;
    time_t now = time(NULL);
    char timestamp[50];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", localtime(&now));

    // Open or create 'flame_log.txt'
    file = fopen("flame_log.txt", "a+");
    if (!file) {
        perror("fopen flame_log.txt");
        return;
    }

    // Write the timestamp and state to the file
    fprintf(file, "%s: %c\n", timestamp, state);
    fclose(file);
}

// Function to clean up resources
void cleanup() {
    // Close GPIO device
    gpiod_close(gpiod);

    // Release GPIO chip
    gpiod_release_chip(chip);

    // Close 'flame_log.txt'
    fclose(file);
}

// Main program initialization
int file_fd = fileno(file); // Assuming 'file' is the file pointer from log_state()
