void cleanup_pigpio();
void read_opt3001(uint16_t *lux);
void handle_i2c_error(int error);
void write_log(const char *message);
void timestamp(char *time_str);

int main(int argc, char *argv[]) {
    int i2c_error;
    uint16_t lux;
    char time_str[50];
    FILE *log_file = NULL;

    // Initialize pigpio
    init_pigpio();

    // Attempt to open the log file
    if ((log_file = fopen("light_data.txt", "a")) == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return EXIT_FAILURE;
