        // Convert lux value
        uint8_t exponent = lux >> 12;
        uint16_t mantissa = lux & 0x0FFF;
        lux = 0.01 * (1 << exponent) * mantissa;

        // Format and write timestamped lux value to log
        timestamp(time_str);
        write_log(" lux: %lu %s", lux, time_str);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up on SIGINT/SIGTERM
    if (signal(SIGINT, SIG_IGN) == SIG_ERR || signal(SIGTERM, SIG_IGN) == SIG_ERR) {
        fprintf(stderr, "Failed to ignore SIGINT and SIGTERM\n");
        return EXIT_FAILURE;
