#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

volatile sig_atomic_t should_exit = 0;

void signal_handler(int signum) {
    should_exit = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret, status;
    time_t now;
    char buffer[50];

    // Initialize libgpiod
    if ((ret = gpiod_chip_open(&chip, "gpiochip-bcm2835", GPIOD_OPEN_BY_NAME | GPIOD_OPEN_FOR_READING)) < 0) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", gpiod_strerror(ret));
        return EXIT_FAILURE;
    }

    // Request the GPIO line
    if ((ret = gpiod_chip_request_lines(chip, 1, GPIOD_LINE_REQUEST_BY_NUMBER, 17)) < 0) {
        fprintf(stderr, "Error requesting GPIO line 17: %s\n", gpiod_strerror(ret));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request the line as input with pull-up enabled
    if ((ret = gpiod_line_config(line, GPIOD_LINE_CONFIG_INPUT, GPIOD_PULLUP_ENABLED)) < 0) {
        fprintf(stderr, "Error configuring line as input with pull-up: %s\n", gpiod_strerror(ret));
        gpiod_line_release(line);
        gpiod_chip_release_lines(chip, 1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!should_exit) {
        // Get the current time
        now = time(NULL);
        // Format the timestamp
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&now));

        // Read the GPIO line value
        if ((ret = gpiod_line_request_get_value(line, &status)) < 0) {
            fprintf(stderr, "Error reading GPIO line value: %s\n", gpiod_strerror(ret));
            continue;
        }

        if (status == 0) {
            fprintf(stderr, "Flame Detected: YES\n");
        } else {
            fprintf(stderr, "Flame Detected: NO\n");
        }

        // Print the status with the timestamp
        fprintf(stderr, "Timestamp: %s\n", buffer);
    }

    // Clean up resources
    gpiod_line_release(line);
    gpiod_chip_release_lines(chip, 1);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

