#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// GPIO numbers for the KY-033 3-Way Tracing Sensor
#define GPIO_LEFT 17
#define GPIO_CENTER 18
#define GPIO_RIGHT 27

// Function prototypes
void initialise_pigpio();
void cleanup_pigpio();
void read_sensors_and_print();
void handle_signals(int signum);

int main() {
    // Initialize pigpio
    if (gpioInitialise() == -1) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", gpioError());
        exit(EXIT_FAILURE);
    }

    // Register signal handlers
    signal(SIGINT, handle_signals);
    signal(SIGTERM, handle_signals);

    // Main loop
    while (1) {
        read_sensors_and_print();
        usleep(50000); // Sleep for 50 ms
    }

    // Cleanup on exit
    cleanup_pigpio();

    return 0;
}

// Function to initialise pigpio
void initialise_pigpio() {
    if (gpioInitialise() == -1) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", gpioError());
        exit(EXIT_FAILURE);
    }
}

// Function to cleanup pigpio resources
void cleanup_pigpio() {
    gpioFree();
}

// Function to read sensors and print values
void read_sensors_and_print() {
    int left_value, center_value, right_value;

    // Set GPIO modes
    if (gpioSetMode(GPIO_LEFT, GPIO_INPUT) == -1) {
        fprintf(stderr, "Failed to set GPIO %d to input: %s\n", GPIO_LEFT, gpioError());
        exit(EXIT_FAILURE);
    }
    if (gpioSetMode(GPIO_CENTER, GPIO_INPUT) == -1) {
        fprintf(stderr, "Failed to set GPIO %d to input: %s\n", GPIO_CENTER, gpioError());
        exit(EXIT_FAILURE);
    }
    if (gpioSetMode(GPIO_RIGHT, GPIO_INPUT) == -1) {
        fprintf(stderr, "Failed to set GPIO %d to input: %s\n", GPIO_RIGHT, gpioError());
        exit(EXIT_FAILURE);
    }

    // Read sensor values
    left_value = gpioRead(GPIO_LEFT);
    center_value = gpioRead(GPIO_CENTER);
    right_value = gpioRead(GPIO_RIGHT);

    // Print values
    printf("Left: %d, Center: %d, Right: %d\n", left_value, center_value, right_value);
}

// Signal handler to gracefully terminate
void handle_signals(int signum) {
    // Clean up pigpio resources
    cleanup_pigpio();

    // Terminate the program
    exit(EXIT_SUCCESS);
}

