#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

#define TOUCH_SENSOR_CHIP_NAME "ttc,tcp,tts,ttc2,tcp2,tts2"
#define TOUCH_SENSOR_GPIO_PINS {2, 3, 4, 5, 6, 7, 8, 9}

// Function prototypes
void setup_touch_sensor();
void read_touch_sensor();
void cleanup();
void handle_signal(int signum);

int main() {
    // Initialize signal handler for SIGINT
    signal(SIGINT, handle_signal);

    // Setup touch sensor
    setup_touch_sensor();

    // Main loop
    while (1) {
        read_touch_sensor();
        // Sleep for 100ms
        usleep(100000);
    }

    // Cleanup on exit
    cleanup();

    return 0;
}

// Function to setup the touch sensor
void setup_touch_sensor() {
    // Open the GPIO chip
    int chip_fd = gpiod_open(TOUCH_SENSOR_CHIP_NAME, "r");
    if (chip_fd == -1) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", gpiod_error(chip_fd));
        exit(EXIT_FAILURE);
    }

    // Iterate through each GPIO pin and configure it for input
    for (int i = 0; i < sizeof(TOUCH_SENSOR_GPIO_PINS) / sizeof(int); i++) {
        int gpio_pin = TOUCH_SENSOR_GPIO_PINS[i];

        // Open the GPIO line
        int line_fd = gpiod_open(gpio_pin, "r");
        if (line_fd == -1) {
            fprintf(stderr, "Error opening GPIO line %d: %s\n", gpio_pin, gpiod_error(line_fd));
            gpiod_close(chip_fd);
            exit(EXIT_FAILURE);
        }

        // Configure the GPIO line for input
        if (gpiod_direction_input(line_fd) == -1) {
            fprintf(stderr, "Error configuring GPIO line %d for input: %s\n", gpio_pin, gpiod_error(line_fd));
            gpiod_close(line_fd);
            gpiod_close(chip_fd);
            exit(EXIT_FAILURE);
        }

        // Close the line after configuration
        gpiod_close(line_fd);
    }

    // Close the chip after all lines are configured
    gpiod_close(chip_fd);
}

// Function to read the touch sensor
void read_touch_sensor() {
    // Open the GPIO chip
    int chip_fd = gpiod_open(TOUCH_SENSOR_CHIP_NAME, "r");
    if (chip_fd == -1) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", gpiod_error(chip_fd));
        return;
    }

    // Read the state of each GPIO pin connected to the touch sensor
    for (int i = 0; i < sizeof(TOUCH_SENSOR_GPIO_PINS) / sizeof(int); i++) {
