    pigpio *pi = NULL;

    // Attempt to initialize pigpio
    if ((pi = pigpioOpen()) == NULL) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }

    // Verify successful initialization
    if (pigpioStatus(pi) != PIGPIO_OK) {
