    for (i = 2; i <= 9; i++) {
        // Check if the GPIO pin is valid
        if (gpioMode(pi, i, GPIO_INPUT) == -1) {
            fprintf(stderr, "Failed to set GPIO %d to input: %s\n", i, pigpioError());
            return; // Abort on failure
        }

        // Set pull-down resistor
        if (gpioSetPullUpDown(pi, i, GPIO_PULLDOWN) == -1) {
            fprintf(stderr, "Failed to set pull-down on GPIO %d: %s\n", i, pigpioError());
            return; // Abort on failure
        }
    }

    // If we got here, all GPIOs were successfully configured
}

