    struct timespec ts;
    int i;

    // Initialize a timestamp
    clock_gettime(CLOCK_REALTIME, &ts);

    // Poll and log the state of each channel
    for (i = 0; i < 8; i++) {
        int state = gpioRead(pi, i);

        // Format and print the state
        printf("[%ld us] CH%d=%d ", (long)ts.tv_nsec + 100000, i + 1, state ? 1 : 0);
    }

    // Simulate a delay to ensure 100ms interval
    usleep(100000);
}

// Cleanup function to release resources
void cleanupAndExit() {
    // Release resources
    gpioTerminate(pi);
    pigpioClose(pi);

    // Exit the program
    exit(0);
