// Function prototypes
void setup_hall_sensors(pigpio *pi);
void read_hall_sensors(pigpio *pi);
void cleanup_resources(pigpio *pi);
void handle_signal(int signum);

int main() {
    // Initialize global variables
    pigpio *pi = NULL;
    int sensor1_state = HIGH;
    int sensor2_state = HIGH;

    // Signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, handle_signal);

    // Attempt to initialize pigpio
    if ((pi = pigpio_open()) == NULL) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }

    // Set up GPIO pins for the Hall sensors
    setup_hall_sensors(pi);

    // Main loop
    while (1) {
        // Read the state of the Hall sensors every 500 ms
        read_hall_sensors(pi);
        sleep(500); // Sleep for 500 ms
    }

    // Clean up resources on exit
    cleanup_resources(pi);

    // Close pigpio connection
    pigpio_close(pi);

    return 0;
}

// Function to set up the GPIO pins for the Hall sensors
void setup_hall_sensors(pigpio *pi) {
    // BCM GPIO 4 for first sensor
    if (pigpio_direction(pi, 4, GPIO_OUT) == -1) {
        fprintf(stderr, "Error setting GPIO 4 direction: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }
    pigpio_write(pi, 4, HIGH);

    // BCM GPIO 5 for second sensor
    if (pigpio_direction(pi, 5, GPIO_OUT) == -1) {
        fprintf(stderr, "Error setting GPIO 5 direction: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }
    pigpio_write(pi, 5, HIGH);
}

// Function to read the state of the Hall sensors
void read_hall_sensors(pigpio *pi) {
    // Read state of GPIO 4
    if (pigpio_read(pi, 4) == LOW) {
        sensor1_state = LOW;
    } else {
        sensor1_state = HIGH;
    }

    // Read state of GPIO 5
    if (pigpio_read(pi, 5) == LOW) {
        sensor2_state = LOW;
    } else {
        sensor2_state = HIGH;
    }

    // Log the states to the console
    printf("Sensor 1: %s\nSensor 2: %s\n", sensor1_state == HIGH ? "HIGH" : "LOW", sensor2_state == HIGH ? "HIGH" : "LOW");
}

// Function to clean up resources and handle SIGINT
void cleanup_resources(pigpio *pi) {
    // Release GPIO pins
    pigpio_free(pi, 4);
    pigpio_free(pi, 5);

    // Close pigpio connection
    pigpio_close(pi);
}

// Signal handler for SIGINT
void handle_signal(int signum) {
    // Clean up resources
    cleanup_resources(NULL);

    // Exit the program
    exit(EXIT_SUCCESS);
}

