#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <gpiod.h>
#include <ctype.h>

#define TOUCH_SENSOR_GPIO_PINS {3, 5, 7, 11, 13, 15, 19, 21} // GPIO numbers for TTP226 channels
#define NUM_TOUCH_SENSEORS sizeof(TOUCH_SENSOR_GPIO_PINS) / sizeof(int)

#define POLL_INTERVAL_MS 50
#define TIMESTAMP_FORMAT "%Y-%m-%dT%H:%M:%S.%03uZ"

void setup_gpiod();
void cleanup_gpiod();
void poll_and_print_touch_sensors();
void sigint_handler(int signum);

int main() {
    struct gpiod_chip *chip;
    int rc;

    // Setup libgpiod
    setup_gpiod();

    // Register SIGINT handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        poll_and_print_touch_sensors();
        usleep(POLL_INTERVAL_MS * 1000); // Wait for POLL_INTERVAL_MS milliseconds
    }

    // Cleanup
    cleanup_gpiod();

    return 0;
}

void setup_gpiod() {
    chip = gpiod_chip_open_by_name("bcm2835-gpio", GPIOD_OPEN_BY_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", gpiod_error_str(gpiod_get_error()));
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < NUM_TOUCH_SENSEORS; ++i) {
        int gpio = TOUCH_SENSOR_GPIO_PINS[i];

        // Request GPIO line as input with bias disabled
        rc = gpiod_line_request gpio, GPIOD_LINE_INPUT | GPIOD_LINE_BIAS_DISABLE;
        if (rc < 0) {
            fprintf(stderr, "Failed to request GPIO line %d: %s\n", gpio, gpiod_error_str(gpiod_get_error()));
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
    }
}

void cleanup_gpiod() {
    for (int i = 0; i < NUM_TOUCH_SENSEORS; ++i) {
        int gpio = TOUCH_SENSOR_GPIO_PINS[i];

        // Release GPIO line
        gpiod_line_release(gpio);
    }

    gpiod_chip_close(chip);
}

void poll_and_print_touch_sensors() {
    struct timespec ts;
    char buffer[256];
    char *timestamp;

    // Get current time
    clock_gettime(CLOCK_REALTIME, &ts);

    // Format timestamp
    strftime(buffer, sizeof(buffer), TIMESTAMP_FORMAT, gmtime(&ts.tv_sec));
    timestamp = buffer;

    // Poll and print sensor states
    for (int i = 0; i < NUM_TOUCH_SENSEORS; ++i) {
        int gpio = TOUCH_SENSOR_GPIO_PINS[i];

        // Read GPIO line state
        int state = gpiod_line_get_value(gpio);
        if (state) {
            printf("%s,%d,%d\n", timestamp, i + 1, 1); // ISO-8601 timestamp, channel index, state (1 for high)
        } else {
            printf("%s,%d,%d\n", timestamp, i + 1, 0); // ISO-8601 timestamp, channel index, state (0 for low)
        }
    }
}

void sigint_handler(int signum) {
    // Gracefully exit on SIGINT
    printf("SIGINT received, exiting...\n");
    exit(EXIT_SUCCESS);
}

