// Define the I2C address and register addresses for the Si1145 sensor
#define SI1145_ADDRESS 0x60
#define HW_KEY_REGISTER 0x17
#define CHLIST_REGISTER 0x01
#define ALS_FORCE_COMMAND 0x06

// Define the register offsets for UV index and Visible ALS data
#define UV_INDEX_OFFSET 0x08
#define ALS_VIS_OFFSET 0x0A

// Function prototypes
void setup_pigpio();
void handle_signals(int signum);
void read_sensor_data(uint8_t* uv_index, uint8_t* als_visible);
void write_to_sensor(uint8_t command, uint8_t data);
void print_and_log_data(uint8_t uv_index, uint8_t als_visible);
void cleanup();

int main() {
    // Initialize pigpio
    setup_pigpio();

    // Register signal handlers
    signal(SIGINT, handle_signals);
    signal(SIGTERM, handle_signals);

    // Main loop
    while (1) {
        // Read sensor data
        uint8_t uv_index;
        uint8_t als_visible;
        read_sensor_data(&uv_index, &als_visible);

        // Print and log data
        print_and_log_data(uv_index, als_visible);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Clean up resources
    cleanup();

    return 0;
}

// Function to setup pigpio
void setup_pigpio() {
    if (pigpioSetup(0) == -1) {
        fprintf(stderr, "Failed to setup pigpio: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }
}

// Function to handle signals
void handle_signals(int signum) {
    // Clean up resources and exit
    cleanup();
    exit(EXIT_SUCCESS);
}

// Function to read sensor data
void read_sensor_data(uint8_t* uv_index, uint8_t* als_visible) {
    // Write to HW_KEY register
    write_to_sensor(ALS_FORCE_COMMAND, 0x17);

    // Configure CHLIST register
    write_to_sensor(CHLIST_REGISTER, 0x01);

    // Wait for the sensor to stabilize
    usleep(10000);

    // Read UV index and Visible ALS data
    *uv_index = readI2C(SI1145_ADDRESS + UV_INDEX_OFFSET);
    *als_visible = readI2C(SI1145_ADDRESS + ALS_VIS_OFFSET);
}

// Function to write to the sensor
void write_to_sensor(uint8_t command, uint8_t data) {
    if (pigpioI2CWrite(SI1145_ADDRESS, command, data) == -1) {
        fprintf(stderr, "Error writing to Si1145: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }
}

// Function to print and log data
void print_and_log_data(uint8_t uv_index, uint8_t als_visible) {
    // Format data for CSV
    char timestamp[20];
    sprintf(timestamp, "%d-%02d-%02d,%02d:%02d:%02d", 
            (int)time(NULL), 
            (int)(time(NULL) / 3600), 
            (int)((time(NULL) / 60) % 60), 
            (int)(time(NULL) % 60));

    // Write to CSV file
    FILE* file = fopen("uv_als_log.csv", "a");
    if (!file) {
        fprintf(stderr, "Failed to open CSV file for writing: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    fprintf(file, "%s,%u,%u\n", timestamp, uv_index, als_visible);
    fclose(file);
}

// Function to cleanup resources
void cleanup() {
    // Close CSV file
    if (ferror(fileno(stdout))) {
        fprintf(stderr, "Error closing CSV file: %s\n", strerror(errno));
    } else {
        fclose(stdout);
    }

    // Shutdown pigpio
    pigpioTerminate();
}

