#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <time.h>
#include <stdint.h>
#include <string.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SENSOR_ADDRS {0x36, 0x37}
#define START_MEASUREMENT_CMD 0x3608
#define MEASUREMENT_REG 0x00
#define FLOW_REG_OFFSET 0
#define TEMP_REG_OFFSET 2
#define CRC_REG_OFFSET 4
#define FLOW_SCALE_FACTOR 0.036
#define ALARM_GPIO 17
#define ALARM_THRESHOLD 0.5

// Sensirion SLF3S-0600F CRC polynomial and initial value
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT_VALUE 0xFF

// Function prototypes
void i2c_read(uint8_t addr, uint8_t reg, uint8_t *data, size_t len);
void i2c_write(uint8_t addr, uint8_t cmd, uint8_t *data, size_t len);
int check_crc(uint16_t flow);
void alarm_handler(int signum);
void cleanup();

int main() {
    struct gpiod_dir *dir;
    int i2c_fd, gpio_fd;
    uint8_t buffer[9];
    uint16_t flow1, flow2;
    float avg_flow_rate;
    int sensor_count = 0;
    int error;

    // Initialize GPIO
    dir = gpiod_open(ALARM_GPIO, GPIOD_OUT_INIT_LOW);
    if (dir == NULL) {
        perror("gpiod_open");
        exit(EXIT_FAILURE);
    }

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    // Initialize variables
    avg_flow_rate = 0.0;
    alarm_handler(0); // Reset alarm state

    // Main loop
    while (1) {
        // Read from each sensor
        for (int sensor = 0; sensor < 2; ++sensor) {
            if (sensor_count == 0) {
                // Initialize the first sensor
                i2c_write(SENSOR_ADDRS[sensor], START_MEASUREMENT_CMD, NULL, 0);
                usleep(100000); // Wait 100 ms
            }

            error = i2c_read(SENSOR_ADDRS[sensor], MEASUREMENT_REG, buffer, 9);
            if (error) {
                fprintf(stderr, "Error reading from sensor %d: %s\n", sensor, strerror(error));
                continue; // Skip this sensor's reading for the cycle
            }

            flow1 = (buffer[FLOW_REG_OFFSET] << 8) | buffer[FLOW_REG_OFFSET + 1];
            if (check_crc(flow1)) {
                avg_flow_rate += flow1 * FLOW_SCALE_FACTOR;
                sensor_count++;
            } else {
                fprintf(stderr, "CRC error for sensor %d\n", sensor);
            }
        }

        // Calculate average flow rate
        avg_flow_rate /= sensor_count;

        // Handle alarm based on average flow rate
        if (avg_flow_rate < ALARM_THRESHOLD) {
            alarm_handler(1); // Set alarm high
        } else {
            alarm_handler(0); // Set alarm low
        }

        // Log average flow rate
        fprintf(stderr, "Average flow rate: %.2f ml/min\n", avg_flow_rate);

        // Sleep for 1 second
        usleep(1000000);

        // Clean up on SIGINT/SIGTERM
        if (signal(SIGINT, alarm_handler) == SIG_ERR || signal(SIGTERM, alarm_handler) == SIG_ERR) {
            perror("signal");
            exit(EXIT_FAILURE);
        }
    }

    // Clean up on exit
    cleanup();

    return 0;
}

// Function to read from I2C device
void i2c_read(uint8_t addr, uint8_t reg, uint8_t *data, size_t len) {
    struct i2c_msg msg = {
        .addr = addr,
        .flags = 0,
        .len = len,
        .buf = data
    };

    int rc = ioctl(i2c_fd, I2C_SLAVE, addr);
    if (rc < 0) {
        perror("ioctl I2C_SLAVE");
        return;
    }

    rc = read(i2c_fd, data, len);
    if (rc != len) {
        fprintf(stderr, "Error reading from I2C: %d bytes read\n", rc);
        return;
    }
}

// Function to write to I2C device
void i2c_write(uint8_t addr, uint8_t cmd, uint8_t *data, size_t len) {
    struct i2c_msg msg = {
        .addr = addr,
        .flags = 0,
        .len = len,
        .buf = data
    };

    int rc = ioctl(i2c_fd, I2C_SLAVE, addr);
    if (rc < 0) {
        perror("ioctl I2C_SLAVE");
        return;
    }

    rc = write(i2c_fd, &cmd, 1);
    if (rc != 1) {
        fprintf(stderr, "Error writing to I2C: %d bytes written\n", rc);
        return;
    }
}

// Check CRC for Sensirion SLF3S-0600F flow measurement
int check_crc(uint16_t flow) {
    uint8_t crc = CRC_INIT_VALUE;
    for (uint8_t bit = 0; bit < 16; ++bit) {
        if ((flow & 0x8000) != 0) {
            crc ^= CRC_POLYNOMIAL;
        }
        flow <<= 1;
        crc <<= 1;
    }
    return crc == (uint8_t)(crc & 0xFF);
}

// Signal handler for SIGINT and SIGTERM
void alarm_handler(int signum) {
    if (signum == SIGINT) {
        printf("SIGINT received, exiting...\n");
    } else if (signum == SIGTERM) {
        printf("SIGTERM received, exiting...\n");
    }

    // Release GPIO
    gpiod_set_data_dir(dir, GPIOD_OUT_INIT_NONE);
    gpiod_close(dir);

    // Close I2C file descriptors
    close(i2c_fd);

    // Close log file (if opened)
    // Assuming 'flow_log.txt' is opened elsewhere in the program
    // close(open("flow_log.txt", O_APPEND | O_WRONLY));

    exit(EXIT_SUCCESS);
}

// Cleanup function
void cleanup() {
    // Release resources
    // Close any open files, release GPIO, etc.
    // Example: close(log_file_descriptor);
    // gpiod_remove(dir);
    // ...
}

