#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define BUFFER_SIZE 100
#define GPIO_PIN 4
#define ALERT_THRESHOLD 0

// Structure to hold buffer entry
typedef struct {
    time_t timestamp;
    int reading;
} BufferEntry;

// Circular buffer implementation
static BufferEntry buffer[BUFFER_SIZE];

static size_t buffer_index = 0;

// Function to handle signal and print buffer contents
static void handleSignal(int signum) {
    if (buffer_index == 0) return; // No entries to print

    printf("Alerts:\n");
    for (size_t i = 0; i < buffer_index; ++i) {
        time_t timestamp = buffer[i].timestamp;
        int reading = buffer[i].reading;
        printf("%lu: %d\n", timestamp, reading);
    }

    // Reset buffer index
    buffer_index = 0;
}

// Main function
int main() {
    // Initialize pigpio and check for errors
    pigpio *pi = NULL;
    if ((pi = pigpio_open()) == NULL) {
        fprintf(stderr, "Failed to open pigpio: %s\n", pigpio_error());
        return 1;
    }

    // Configure GPIO pin 4 as input with pull-up
    if (pigpio_inout_set(pi, GPIO_PIN, 1, 1) == -1) {
        fprintf(stderr, "Failed to configure GPIO %d: %s\n", GPIO_PIN, pigpio_error());
        pigpio_close(pi);
        return 1;
    }

    // Signal handler for SIGINT (Ctrl+C)
    struct sigaction sa;
    sa.sa_handler = handleSignal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        pigpio_close(pi);
        return 1;
    }

    // Main loop
    while (1) {
        int reading = pigpio_get(pi, GPIO_PIN);
        if (reading == ALERT_THRESHOLD) {
            // Record timestamp and reading
            time_t now = time(NULL);
            buffer[buffer_index].timestamp = now;
            buffer[buffer_index].reading = reading;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        }

        // Poll every 50 ms
        usleep(50000);

        // Check for Ctrl+C
        if (sigpending(&sa.sa_mask) && SA_SIGINFO & sa.sa_flags) {
            handleSignal(SIGINT);
        }
    }

    // Release resources on exit
    pigpio_close(pi);

    return 0;
}

