#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_ADDR 0x55
#define MODE_CONTROL_REG 0x1D
#define OPERATING_STATUS_REG 0x1B
#define ACCEL_X_REG 0x2A
#define ACCEL_Y_REG 0x2C
#define ACCEL_Z_REG 0x2E

#define SCALE_FACTOR 0.0009765625

// Function prototypes
void initialize_sensor();
void read_accelerations(uint8_t reg);
void convert_g_to_raw(int16_t value);
void write_to_mode_control_reg(uint8_t value);
void handle_interrupts(int signum);

int main() {
    // Signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_interrupts;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open I2C device
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Initialize sensor
    initialize_sensor();

    // Main loop
    while (1) {
        // Read operating status
        uint8_t operating_status;
        if (read_from_reg(i2c_fd, OPERATING_STATUS_REG, &operating_status) < 0) {
            perror("Failed to read operating status");
            continue;
        }

        // Check if sensor is active
        if (operating_status & 0x01) {
            // Sensor is active, proceed with reading accelerations
            read_accelerations(ACCEL_X_REG);
            read_accelerations(ACCEL_Y_REG);
            read_accelerations(ACCEL_Z_REG);

            // Convert raw values to g
            convert_g_to_raw(ACCEL_X_REG);
            convert_g_to_raw(ACCEL_Y_REG);
            convert_g_to_raw(ACCEL_Z_REG);

            // Write to CSV file
            write_to_csv("fan_health.csv", time(NULL), (float)ACCEL_X_REG * SCALE_FACTOR, (float)ACCEL_Y_REG * SCALE_FACTOR, (float)ACCEL_Z_REG * SCALE_FACTOR);
        } else {
            // Sensor is not active, wait and retry
            sleep(0.5);
        }
    }

    // Close resources on exit
    close(i2c_fd);
    close(STDOUT_FILENO); // Ensure CSV file is properly closed

    return 0;
}

// Function to initialize the sensor
void initialize_sensor() {
    // Write to MODE_CONTROL register to activate the sensor
    write_to_mode_control_reg(0x10);
    // Wait for sensor to become active
    struct timespec timeout = {1, 0};
    nanosleep(&timeout, NULL);
    if (operating_status & 0x01) {
        printf("Sensor activated successfully.\n");
    } else {
        perror("Sensor did not become active within 1 second");
        exit(EXIT_FAILURE);
    }
}

// Function to read from a specified I2C register
int read_from_reg(int fd, uint8_t reg, uint8_t *data) {
    if (ioctl(fd, I2C_READ, (char *) &reg) < 0) {
        perror("Failed to read from register");
        return -1;
    }
    *data = (uint8_t) (read(fd, data, 1) & 0xFF);
    return 0;
}

// Function to write to a specified I2C register
void write_to_mode_control_reg(uint8_t value) {
    if (ioctl(i2c_fd, I2C_WRITE, &value) < 0) {
        perror("Failed to write to register");
    }
}

// Function to convert raw acceleration value to g
void convert_g_to_raw(int16_t value) {
    int raw_acceleration = value * SCALE_FACTOR;
    printf("Acceleration (g): %.6f\n", raw_acceleration);
}

// Function to handle interrupts (SIGINT/SIGTERM)
void handle_interrupts(int signum) {
    // Close I2C and CSV file descriptors
    close(i2c_fd);
    close(STDOUT_FILENO);

    // Clean exit
    printf("Exiting due to user interrupt.\n");
    exit(EXIT_SUCCESS);
}

// Helper function to write to CSV file
void write_to_csv(const char *filename, time_t timestamp, double x_g, double y_g, double z_g) {
    FILE *csv_file = fopen(filename, "a");
    if (!csv_file) {
        perror("Failed to open CSV file for append");
        return;
    }

    // Write header if it's the first time
    if (fseek(csv_file, 0, SEEK_SET) == 0 && feof(csv_file) == 0) {
        fprintf(csv_file, "Timestamp,X(g),Y(g),Z(g)\n");
    }

    // Write data row
    fprintf(csv_file, "%s,%f,%f,%f\n", ctime(&timestamp), x_g, y_g, z_g);
    fclose(csv_file);
}

