void setup_pigpio();
void initialize_sensors();
void read_sensors();
void handle_signal(int signum);
void cleanup();

int main() {
    // Signal handler for SIGINT and SIGTERM
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize pigpio
    setup_pigpio();

    // Initialize sensors
    initialize_sensors();

    // Main loop
    while (1) {
        // Read sensors
        read_sensors();

        // Check for obstacles
        if (gpioRead(SENSOR_1_GPIO) == 0 || gpioRead(SENSOR_2_GPIO) == 0) {
            gpioWrite(LED_GPIO, 1); // Turn LED ON
        } else {
            gpioWrite(LED_GPIO, 0); // Turn LED OFF
        }
    }

    // Clean up resources
    cleanup();

    return 0;
}

