    if (gpioSetMode(SENSOR_1_GPIO, GPIO_MODE_OUT) == -1) {
        fprintf(stderr, "Failed to set SENSOR_1 GPIO mode: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    if (gpioSetMode(SENSOR_2_GPIO, GPIO_MODE_OUT) == -1) {
        fprintf(stderr, "Failed to set SENSOR_2 GPIO mode: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

