#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <stdint.h>

// Define the I2C address and register addresses
#define I2C_ADDRESS 0x0E
#define DEVICE_ID_REGISTER 0x00
#define MAG_X_REGISTER 0x01
#define MAG_Y_REGISTER 0x02
#define MAG_Z_REGISTER 0x03

// Scale factor for converting raw 16-bit values to mT for 50 mT range
#define LSB_TO_MILLI_TESLA 50

// Function prototypes
void handleInterrupt(int signum);
void initPigpio();
void initI2C();
void readMagneticSensors();
void writeDeviceID();
void writeMagneticValues(uint16_t x, uint16_t y, uint16_t z);
void cleanupResources();

int main() {
    // Initialize pigpio
    if (pigpioSetup(0) == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpioError());
        return EXIT_FAILURE;
    }

    // Register signal handler for clean exit
    signal(SIGINT, handleInterrupt);
    signal(SIGTERM, handleInterrupt);

    // Initialize I2C
    if (initI2C() == -1) {
        fprintf(stderr, "Failed to initialize I2C: %s\n", pigpioError());
        pigpioTerminate();
        return EXIT_FAILURE;
    }

    // Check device ID at startup
    if (writeDeviceID() != 0) {
        fprintf(stderr, "Failed to write device ID: %s\n", pigpioError());
        cleanupResources();
        return EXIT_FAILURE;
    }

    // Check if 'magnetic_log.csv' exists, if not, write header
    FILE *magnetic_log = fopen("magnetic_log.csv", "a+");
    if (magnetic_log == NULL) {
        fprintf(stderr, "Failed to open 'magnetic_log.csv' for writing: %s\n", strerror(errno));
        fclose(magnetic_log);
        cleanupResources();
        return EXIT_FAILURE;
    }
    if (fseek(magnetic_log, 0, SEEK_SET) == -1) {
        fprintf(stderr, "Failed to seek to beginning of 'magnetic_log.csv': %s\n", strerror(errno));
        fclose(magnetic_log);
        cleanupResources();
        return EXIT_FAILURE;
    }
    if (fprintf(magnetic_log, "Timestamp,X,Y,Z\n") == -1) {
        fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
        fclose(magnetic_log);
        cleanupResources();
        return EXIT_FAILURE;
    }
    fclose(magnetic_log);

    // Main loop
    while (1) {
        // Read magnetic field values
        uint16_t x, y, z;
        if (readMagneticSensors(&x, &y, &z) != 0) {
            fprintf(stderr, "Failed to read magnetic sensor values: %s\n", pigpioError());
            continue;
        }

        // Convert raw values to mT
        x *= LSB_TO_MILLI_TESLA;
        y *= LSB_TO_MILLI_TESLA;
        z *= LSB_TO_MILLI_TESLA;

        // Write values to CSV
        if (writeMagneticValues(x, y, z) == -1) {
            fprintf(stderr, "Failed to write magnetic values to CSV: %s\n", pigpioError());
            continue;
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up resources on interrupt
    handleInterrupt(SIGINT);
    handleInterrupt(SIGTERM);

    return EXIT_SUCCESS;
}

// SIGINT/SIGTERM handler
void handleInterrupt(int signum) {
    // Clean up resources
    cleanupResources();
    exit(0);
}

// Initialize pigpio
void initPigpio() {
    if (pigpioInit() == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpioError());
        return;
    }
}

// Initialize I2C
int initI2C() {
    int i2c_fd = pigpioI2COpen(1, I2C_ADDRESS);
    if (i2c_fd == -1) {
        fprintf(stderr, "Failed to open I2C bus 1: %s\n", pigpioError());
        return -1;
    }

    return i2c_fd;
}

// Read magnetic sensor values
int readMagneticSensors(uint16_t *x, uint16_t *y, uint16_t *z) {
    int ret = pigpioI2CWrite(i2c_fd, DEVICE_ID_REGISTER, 0x8D); // Expected value 0x8D
    if (ret != 0) {
        fprintf(stderr, "Failed to write to device ID register: %s\n", pigpioError());
        return -1;
    }

    ret = pigpioI2CWrite(i2c_fd, MAG_X_REGISTER, 0); // Read X
    if (ret != 0) {
        fprintf(stderr, "Failed to read X magnetic value: %s\n", pigpioError());
        return -1;
    }
    *x = pigpioI2CRead(i2c_fd, MAG_X_REGISTER);

    ret = pigpioI2CWrite(i2c_fd, MAG_Y_REGISTER, 0); // Read Y
    if (ret != 0) {
        fprintf(stderr, "Failed to read Y magnetic value: %s\n", pigpioError());
        return -1;
    }
    *y = pigpioI2CRead(i2c_fd, MAG_Y_REGISTER);

    ret = pigpioI2CWrite(i2c_fd, MAG_Z_REGISTER, 0); // Read Z
    if (ret != 0) {
        fprintf(stderr, "Failed to read Z magnetic value: %s\n", pigpioError());
        return -1;
    }
    *z = pigpioI2CRead(i2c_fd, MAG_Z_REGISTER);

    return 0;
}

// Write device ID to the sensor
int writeDeviceID() {
    int ret = pigpioI2CWrite(i2c_fd, DEVICE_ID_REGISTER, 0x8D);
    if (ret != 0) {
        fprintf(stderr, "Failed to write device ID: %s\n", pigpioError());
        return -1;
    }

    return 0;
}

// Write magnetic values to CSV
int writeMagneticValues(uint16_t x, uint16_t y, uint16_t z) {
    FILE *magnetic_log = fopen("magnetic_log.csv", "a+");
    if (magnetic_log == NULL) {
        fprintf(stderr, "Failed to open 'magnetic_log.csv' for appending: %s\n", strerror(errno));
        return -1;
    }

    // Write ISO-8601 timestamp and values
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char timestamp[50];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(magnetic_log, "%s,%d,%d,%d\n", timestamp, x, y, z);

    fclose(magnetic_log);
    return 0;
}

// Cleanup resources
void cleanupResources() {
    // Close I2C handle
    pigpioI2CClose(i2c_fd);

    // Close CSV file
    fclose(magnetic_log);

    // Terminate pigpio
    pigpioTerminate();
}

