#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define PI_GPIO_NUM 23 // GPIO 23
#define ALERT_FILE "flood_log.txt"
#define ALERT_FORMAT " ALERT: Water detected"

// Function prototypes
void handleSIGINTSIGTERM(void);
void initializePigpio(void);
void readWaterLevelSensor(void);
void writeAlertToLog(const char *message, const time_t *timestamp);
void cleanupResources(void);

// Global variables
pigpio *pi;
FILE *alertLogFile;
char alertMessage[100];

int main(void) {
    signal(SIGINT, handleSIGINTSIGTERM);
    signal(SIGTERM, handleSIGINTSIGTERM);

    // Attempt to initialize pigpio
    initializePigpio();
    if (pi == NULL) {
        fprintf(stderr, "Failed to initialize pigpio. Retrying in 60 seconds...\n");
        sleep(60);
        initializePigpio();
        if (pi == NULL) {
            fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
            exit(EXIT_FAILURE);
        }
    }

    // Main loop
    while (1) {
        readWaterLevelSensor();
        sleep(2); // Poll every 2 seconds
    }

    // Clean up resources on exit
    cleanupResources();

    return 0;
}

// Function to handle SIGINT and SIGTERM signals
void handleSIGINTSIGTERM(void) {
    fprintf(stderr, "Shutting down due to SIGINT/SIGTERM signal.\n");
    fclose(alertLogFile);
    cleanupResources();
    exit(EXIT_SUCCESS);
}

// Function to initialize pigpio
void initializePigpio(void) {
    pi = pigpioOpen();
    if (pi == NULL) {
        fprintf(stderr, "Failed to open pigpio.\n");
        return;
    }

    // Set GPIO 23 as input with pull-down
    if (pigpioGpioMode(pi, PI_GPIO_NUM, pigpioInputPullDown) == -1) {
        fprintf(stderr, "Failed to set GPIO %d to input with pull-down.\n", PI_GPIO_NUM);
        pigpioClose(pi);
        initializePigpio(); // Retry after 60 seconds
    }
}

// Function to read the water level sensor
void readWaterLevelSensor(void) {
    int level = pigpioDigitalRead(pi, PI_GPIO_NUM);

    if (level == 1) { // Water detected (logic HIGH)
        sprintf(alertMessage, ALERT_FORMAT, time(NULL));
        writeAlertToLog(alertMessage, &time(NULL));
        fprintf(stderr, "Water detected at %s\n", alertMessage);
    } else {
        fprintf(stderr, "No water detected.\n");
    }
}

