int setup_pigpio_and_gpio(struct pigpio *pgpio) {
    if (pgpio == NULL) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return -1;
    }

    if (piGPIOSetMode(pgpio, SENSOR_PIN, PI_INPUT) == -1) {
        fprintf(stderr, "Failed to set GPIO %d to input mode\n", SENSOR_PIN);
        return -1;
    }

    if (piGPIOSetPullUp(pgpio, SENSOR_PIN) == -1) {
        fprintf(stderr, "Failed to enable internal pull-up resistor on GPIO %d\n", SENSOR_PIN);
        return -1;
    }

    return 0;
}

// Function to handle GPIO interrupt
void handle_rising_edge(struct pigpio *pgpio, void *data) {
    static unsigned long pulses = 0;
    unsigned long now = time(NULL);
    unsigned long interval = 1000; // 1 second

    if (now - pulses >= interval) {
        // Count pulses in the last second
        pulses++;

        // Compute RPM
        double rpm = (double)pulses * 60;
        printf("RPM: %.1f\n", rpm);

        // Log to file
        char timestamp[23];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        FILE *file = fopen("rpm_log.txt", "a");
        if (file) {
            fprintf(file, "%s %f\n", timestamp, rpm);
            fclose(file);
        } else {
            fprintf(stderr, "Failed to open rpm_log.txt for writing\n");
        }

        // Reset pulse counter for the next second
        pulses = now;
    }
}

// Main function
