    struct pigpio *pgpio;
    int ret;

    // Initialize pigpio
    ret = pigpioOpen(&pgpio, 0);
    if (ret == -1) {
        fprintf(stderr, "Failed to open pigpio: %s\n", pigpioError(pgpio));
        return EXIT_FAILURE;
    }

    // Set up GPIO and interrupt handler
    if (setup_pigpio_and_gpio(pgpio) != 0) {
        pigpioClose(pgpio);
        return EXIT_FAILURE;
    }

    // Install signal handlers
    struct sigaction sigint_action, sigterm_action;
    sigemptyset(&sigint_action.sa_mask);
    sigint_action.sa_handler = signal_handler;
    sigint_action.sa_flags = 0;
    if (sigaction(SIGINT, &sigint_action, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler\n");
        return EXIT_FAILURE;
    }

    sigemptyset(&sigterm_action.sa_mask);
    sigterm_action.sa_handler = signal_handler;
    sigterm_action.sa_flags = 0;
    if (sigaction(SIGTERM, &sigterm_action, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler\n");
        return EXIT_FAILURE;
    }

    // Start timer and interrupt handler
    if (piGPIOInterruptAttach(pgpio, handle_rising_edge, SENSOR_PIN, PI_RISING, 0) == -1) {
        fprintf(stderr, "Failed to attach GPIO interrupt\n");
        pigpioClose(pgpio);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        sleep(1); // Sleep for 1 second
    }

    // Clean up on SIGINT/SIGTERM
    void signal_handler(int signum) {
        printf("Interrupt received, stopping...\n");
        pigpioStopTimer(pgpio, -1); // Stop the timer
        piGPIOInterruptDetach(pgpio, SENSOR_PIN); // Detach interrupt handler
        fclose(stderr); // Close stderr (if it was opened for some reason)
        pigpioClose(pgpio); // Close pigpio
        exit(0); // Exit cleanly
    }

    return EXIT_SUCCESS;
}

