#include <unistd.h>
#include <syslog.h>
#include <gpiod.h>

#define TOUCH_SENSOR_GPIO 23
#define LED_GPIO 18
#define TOUCH_SENSOR_LINE 0
#define TOUCH_THRESHOLD 100

volatile sig_atomic_t should_exit = 0;

void handle_signal(int signum) {
    should_exit = 1;
}

int main() {
    // Initialize logging
    openlog("touch_sensor_app", LOG_PID, LOG_USER);
    syslog(LOG_INFO, "Application started.");

    // Check if GPIO chip is available
    struct gpiod_chip *chip;
    int ret = gpiod_chip_open(&chip, GPIOD_CHIPS_ALL, GPIOD_OPEN_BY_NAME);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %s", gpiod_error_str(ret));
        return EXIT_FAILURE;
    }
    syslog(LOG_INFO, "GPIO chip opened successfully.");

    // Initialize GPIO pins
    int ret_touch_sensor = gpiod_direction_output(chip, TOUCH_SENSOR_GPIO, 0);
    int ret_led = gpiod_direction_output(chip, LED_GPIO, 1);

    if (ret_touch_sensor < 0 || ret_led < 0) {
        syslog(LOG_ERR, "Failed to configure GPIO pins: %s", gpiod_error_str(ret_touch_sensor) " " gpiod_error_str(ret_led));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    syslog(LOG_INFO, "GPIO pins configured successfully.");

    // Signal handlers for graceful shutdown
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!should_exit) {
        // Poll the touch sensor
        int value = 0;
        ret = gpiod_read(chip, TOUCH_SENSOR_LINE, &value);
        if (ret < 0) {
            syslog(LOG_ERR, "Error reading touch sensor: %s", gpiod_error_str(ret));
            continue;
        }

        // Check if the sensor is touched
        if (value > TOUCH_THRESHOLD) {
            syslog(LOG_INFO, "Sensor touched.");
            // Turn on the LED
            gpiod_write(chip, LED_GPIO, 1);
        } else {
            // Turn off the LED
            gpiod_write(chip, LED_GPIO, 0);
        }

        // Sleep for 50 ms to avoid busy-waiting
        usleep(50000);
    }

    syslog(LOG_INFO, "Application shutting down.");
    gpiod_chip_close(chip);

    // Clean up logging
    closelog();

    return EXIT_SUCCESS;
}

