#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <libgpiod/gpiod.h>

#define TOUCH_GPIO 17
#define LED_GPIO 18

volatile sig_atomic_t should_exit = 0;

void handle_signal(int signum) {
    should_exit = 1;
}

int main() {
    // Initialize libgpiod
    if (gpiod_chip_open(GPIOD_CHIP_RASPBERRY_PI_3) < 0) {
        fprintf(stderr, "Error: Failed to open Raspberry Pi 3 chip.\n");
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    if (gpiod_line_request_one(GPIOD_LINE_TO_GPIO(TOUCH_GPIO), GPIOD_DIR_OUT_INIT_LOW | GPIODedge_NONE) < 0) {
        fprintf(stderr, "Error: Failed to request GPIO %u.\n", TOUCH_GPIO);
        gpiod_chip_close(GPIOD_CHIP_RASPBERRY_PI_3);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_one(GPIOD_LINE_TO_GPIO(LED_GPIO), GPIOD_DIR_OUT_INIT_LOW) < 0) {
        fprintf(stderr, "Error: Failed to request GPIO %u.\n", LED_GPIO);
        gpiod_line_release(GPIOD_LINE_TO_GPIO(TOUCH_GPIO));
        gpiod_chip_close(GPIOD_CHIP_RASPBERRY_PI_3);
        return EXIT_FAILURE;
    }

    // Configure GPIO lines
    if (gpiod_set_data_direction(GPIOD_LINE_TO_GPIO(TOUCH_GPIO), GPIOD_DATA_IN) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %u direction to input.\n", TOUCH_GPIO);
        gpiod_line_release(GPIOD_LINE_TO_GPIO(LED_GPIO));
        gpiod_line_release(GPIOD_LINE_TO_GPIO(TOUCH_GPIO));
        gpiod_chip_close(GPIOD_CHIP_RASPBERRY_PI_3);
        return EXIT_FAILURE;
    }

    if (gpiod_set_data_direction(GPIOD_LINE_TO_GPIO(LED_GPIO), GPIOD_DATA_OUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %u direction to output.\n", LED_GPIO);
        gpiod_line_release(GPIOD_LINE_TO_GPIO(TOUCH_GPIO));
        gpiod_chip_close(GPIOD_CHIP_RASPBERRY_PI_3);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!should_exit) {
        // Wait for touch event
        if (gpiod_event_wait(GPIOD_LINE_TO_GPIO(TOUCH_GPIO), GPIOD_EVENT_RISING_EDGE) < 0) {
            fprintf(stderr, "Error: Failed to wait for touch event.\n");
            break;
        }

        // Debounce (approx. 50ms)
        usleep(50000);

        // Toggle LED on touch detection
        if (gpiod_write(GPIOD_LINE_TO_GPIO(LED_GPIO), 1) < 0) {
            fprintf(stderr, "Error: Failed to write to LED GPIO.\n");
        } else {
            fprintf(stderr, "Touched: LED toggled.\n");
        }

        // Release the line after use
        gpiod_line_release(GPIOD_LINE_TO_GPIO(LED_GPIO));
    }

    // Clean up
    gpiod_line_release(GPIOD_LINE_TO_GPIO(TOUCH_GPIO));
    gpiod_chip_close(GPIOD_CHIP_RASPBERRY_PI_3);

    // Exit on signal
    if (should_exit) {
        printf("Exiting gracefully...\n");
        exit(EXIT_SUCCESS);
    }

    return EXIT_SUCCESS;
}

