#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define BUFFER_SIZE 100
#define TOUCH_SENSOR_GPIO 4
#define LED_GPIO_27 27
#define OTHER_LED_GPIO 22
#define TOUCH_SENSOR_GPIO_OTHER 17

volatile int touchEvents[BUFFER_SIZE];
volatile int touchEventIndex = 0;
volatile int overflowCount = 0;
int bufferFull = 0;

pigpio *pi;

// Function prototypes
void initialisePigpio();
void setupLEDs();
void handleSignals(int signum);
void pollSensors();
void logEvent(int sensor, int state);
void shutdownGracefully();

int main() {
    // Initialize pigpio
    pi = NULL;
    initialisePigpio();

    // Setup LEDs
    setupLEDs();

    // Install signal handlers
    signal(SIGINT, handleSignals);
    signal(SIGTERM, handleSignals);

    // Main loop
    while (1) {
        pollSensors();
        if (bufferFull) {
            overflowCount++;
            if (overflowCount >= BUFFER_SIZE) {
                printf("Overflow occurred, wrapping buffer.\n");
                overflowCount = 0;
            }
        }
        if (touchEventIndex == BUFFER_SIZE) {
            touchEventIndex = 0;
            bufferFull = 1;
        }
    }

    // Graceful shutdown on SIGINT or SIGTERM
    shutdownGracefully();

    // Clean up
    gpioTerminate(pi);
    free(pi);

    return 0;
}

// Function to initialize pigpio
void initialisePigpio() {
    pi = pigpioOpen();
    if (pi == NULL) {
        fprintf(stderr, "Failed to open pigpio: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }

    if (gpioInitialise(pi) == -1) {
        fprintf(stderr, "Failed to initialise GPIO: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }
}

// Function to setup LEDs
void setupLEDs() {
    if (gpioSetMode(GPIO_LED_27, GPIO_MODE_OUTPUT) == -1) {
        fprintf(stderr, "Failed to set GPIO 27 mode: %s\n", pigpioError());
    }
    gpioWrite(GPIO_LED_27, 1); // Turn on LED connected to GPIO 27

    if (gpioSetMode(GPIO_LEDOther, GPIO_MODE_OUTPUT) == -1) {
        fprintf(stderr, "Failed to set GPIO 22 mode: %s\n", pigpioError());
    }
    gpioWrite(GPIO_LEDOther, 0); // Turn off LED connected to GPIO 22
}

// Function to handle signals
void handleSignals(int signum) {
    shutdownGracefully();
    exit(EXIT_SUCCESS);
}

// Function to poll sensors
void pollSensors() {
    int touchSensorState = gpioRead(TOUCH_SENSOR_GPIO) ? 1 : 0;
    int otherTouchSensorState = gpioRead(TOUCH_SENSOR_GPIO_OTHER) ? 1 : 0;

    if (touchSensorState != otherTouchSensorState) {
        logEvent(TOUCH_SENSOR_GPIO, touchSensorState);
        if (touchSensorState == 1) {
            gpioWrite(GPIO_LED_27, 1); // Turn on LED for GPIO 27
        } else {
            gpioWrite(GPIO_LED_27, 0); // Turn off LED for GPIO 27
        }

        if (otherTouchSensorState == 1) {
            gpioWrite(GPIO_LEDOther, 1); // Turn on LED for GPIO 22
        } else {
            gpioWrite(GPIO_LEDOther, 0); // Turn off LED for GPIO 22
        }
    }
}

// Function to log an event
void logEvent(int sensor, int state) {
    touchEvents[touchEventIndex++] = sensor;
    touchEvents[touchEventIndex++] = state;
    if (touchEventIndex == BUFFER_SIZE) {
        touchEventIndex = 0;
        bufferFull = 1;
    }
}

// Function to gracefully shut down
void shutdownGracefully() {
    for (int i = 0; i < BUFFER_SIZE; i++) {
        printf("%d: %d\n", touchEvents[i], (touchEvents[i] ? "Touched" : "Released"));
    }
    printf("Overflow count: %d\n", overflowCount);

    gpioWrite(GPIO_LED_27, 0); // Turn off LED for GPIO 27
    gpioWrite(GPIO_LEDOther, 0); // Turn off LED for GPIO 22

    gpioTerminate(pi);
    free(pi);
}

