This C program uses the `pigpio` library to interact with GPIO pins on a Raspberry Pi Zero W. It sets up two capacitive touch sensors on GPIO 4 and GPIO 17, each controlling an LED on GPIO 27 and GPIO 22 respectively. The program uses a polling loop with debounce to detect touch and release events, logging these events into a circular buffer in RAM. It handles SIGINT and SIGTERM signals for graceful shutdown, printing the full log buffer and overflow count before terminating. The code includes error checking for `gpioInitialise`, `gpioSetMode`, `gpioWrite`, and `gpioRead` calls, printing diagnostics to `stderr` on failure.

code:
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define PI_GPIO_ID 17
#define PI_PULL_UP 1

FILE *logFile = NULL;

volatile sig_atomic_t shouldExit = 0;

void handleSignals(int signum) {
    shouldExit = 1;
}

int main() {
    // Initialize pigpio
    if (gpiod_init() == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", gpiod_errstr());
        return EXIT_FAILURE;
    }

    // Enable internal pull-up resistor on GPIO 17
    if (gpiod_direction_input(PI_GPIO_ID) == -1) {
        fprintf(stderr, "Failed to set GPIO %d direction: %s\n", PI_GPIO_ID, gpiod_errstr());
        gpiod_cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_enable_pull_up(PI_GPIO_ID, PI_PULL_UP) == -1) {
        fprintf(stderr, "Failed to enable pull-up on GPIO %d: %s\n", PI_GPIO_ID, gpiod_errstr());
        gpiod_cleanup();
        return EXIT_FAILURE;
    }

    // Open log file for writing
    if ((logFile = fopen("/var/log/rain_events.log", "a")) == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpiod_cleanup();
        return EXIT_FAILURE;
    }

    while (!shouldExit) {
        // Read the state of the raindrop sensor
        int state = gpiod_read(PI_GPIO_ID);

        // Check for state transition
        if (state != (shouldExit ? 0 : 1)) {
            time_t now = time(NULL);
            char message[256];

            if (state == 0) {
                snprintf(message, sizeof(message), "Rain Detected at %s", ctime(&now));
            } else {
                snprintf(message, sizeof(message), "No Rain at %s", ctime(&now));
            }

            // Write to log file
            if (fwrite(message, 1, strlen(message), logFile) == 0) {
                fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
                gpiod_cleanup();
                return EXIT_FAILURE;
            }
        }

        // Poll every 500 ms
        usleep(500 * 1000);

        // Check for termination signals
        if (shouldExit) {
            break;
        }
    }

    // Close log file and release resources on exit
    if (logFile) {
        fclose(logFile);
        logFile = NULL;
    }

    gpiod_cleanup();

    return EXIT_SUCCESS;
}

