    while (!shouldExit) {
        // Read the state of the raindrop sensor
        int state = gpiod_read(PI_GPIO_ID);

        // Check for state transition
        if (state != (shouldExit ? 0 : 1)) {
            time_t now = time(NULL);
            char message[256];

            if (state == 0) {
                snprintf(message, sizeof(message), "Rain Detected at %s", ctime(&now));
            } else {
                snprintf(message, sizeof(message), "No Rain at %s", ctime(&now));
            }

            // Write to log file
            if (fwrite(message, 1, strlen(message), logFile) == 0) {
                fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
                gpiod_cleanup();
                return EXIT_FAILURE;
            }
        }

        // Poll every 500 ms
        usleep(500 * 1000);

        // Check for termination signals
        if (shouldExit) {
            break;
        }
    }

    // Close log file and release resources on exit
    if (logFile) {
        fclose(logFile);
        logFile = NULL;
    }

    gpiod_cleanup();

    return EXIT_SUCCESS;
}
