#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define PI_GPIO_NUM_17 17
#define PI_GPIO_NUM_18 18
#define DEBOUNCE_MS 5
#define PULSES_PER_REVOLUTION 2

volatile int sensor1_state = 0;
volatile int sensor2_state = 0;
int last_sensor1_time = 0;
int last_sensor2_time = 0;
FILE *log_file = NULL;

void setup_pigpio() {
    if (pigpioSetup() == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }
}

void setup_gpio() {
    if (pigpioWriteFuncSet(PI_GPIO_NUM_17, PI_OUTPUT_ON_HIGH) == -1 ||
        pigpioWriteFuncSet(PI_GPIO_NUM_18, PI_OUTPUT_ON_HIGH) == -1) {
        fprintf(stderr, "Failed to set GPIO pins to output: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }
}

void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    pigpioFinish();
}

void handle_signal(int signum) {
    cleanup();
    exit(EXIT_FAILURE);
}

int main() {
    setup_pigpio();
    setup_gpio();

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    while (1) {
        time_t now = time(NULL);
        if ((now - last_sensor1_time) > DEBOUNCE_MS) {
            sensor1_state = pigpioRead(PI_GPIO_NUM_17);
            last_sensor1_time = now;
        }

        if ((now - last_sensor2_time) > DEBOUNCE_MS) {
            sensor2_state = pigpioRead(PI_GPIO_NUM_18);
            last_sensor2_time = now;
        }

        if (sensor1_state && !sensor2_state) {
            fprintf(log_file, "%ld,%d,0\n", (long)now, sensor1_state);
        } else if (sensor2_state && !sensor1_state) {
            fprintf(log_file, "%ld,0,%d\n", (long)now, sensor2_state);
        } else {
            fprintf(log_file, "%ld,0,0\n", (long)now);
        }

        if (sensor1_state && sensor2_state) {
            int rpm = (PULSES_PER_REVOLUTION * 60) / (now - last_sensor1_time);
            printf("RPM: %.1f\n", rpm);
            fflush(stdout);
        }

        last_sensor1_time = now;
        last_sensor2_time = now;
    }

    return 0;
}

