#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>

#define PIGPIO_ID 0  // ID of the pigpio instance
#define SI1182_ADDRESS 0x28  // I2C address of the Si1182 sensor
#define SI1182_PART_ID_REG 0x00  // PART_ID register address
#define SI1182_CONFIG_REG 0x30  // CONFIG register address
#define SI1182_HEART_RATE_REG 0x02  // Heart rate register address
#define SI1182_SPO2_REG 0x04  // SpO2 register address

// Function prototypes
void handleSIGINT(int signum);
int i2cRead(uint8_t address, uint8_t reg, uint8_t* data);
int i2cWrite(uint8_t address, uint8_t reg, uint8_t data);

int main() {
    // Initialize pigpio
    if (pigpioSetup(PIGPIO_ID) == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpioError());
        return EXIT_FAILURE;
    }

    // Open I2C bus 1
    if (pigpioI2COpen(1) == -1) {
        fprintf(stderr, "Failed to open I2C bus 1: %s\n", pigpioError());
        pigpioTerminate(PIGPIO_ID);
        return EXIT_FAILURE;
    }

    // Verify sensor presence by reading PART_ID register
    uint8_t partId;
    if (i2cRead(SI1182_ADDRESS, SI1182_PART_ID_REG, &partId) != 0) {
        fprintf(stderr, "Failed to read PART_ID register: %s\n", pigpioError());
        pigpioI2CClose(1);
        pigpioTerminate(PIGPIO_ID);
        return EXIT_FAILURE;
    }

    // Configure the sensor for continuous measurement
    if (i2cWrite(SI1182_ADDRESS, SI1182_CONFIG_REG, 0x01) != 0) {
        fprintf(stderr, "Failed to write to CONFIG register: %s\n", pigpioError());
        pigpioI2CClose(1);
        pigpioTerminate(PIGPIO_ID);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Get current time
        time_t now = time(NULL);
        struct tm* timeinfo = localtime(&now);
        char timestamp[50];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S,", timeinfo);
        timestamp[strlen(timestamp)] = '\0'; // Null-terminate the string

        // Read heart rate and SpO2
        uint8_t heartRateData;
        uint8_t spo2Data;
        if (i2cRead(SI1182_ADDRESS, SI1182_HEART_RATE_REG, &heartRateData) != 0 ||
            i2cRead(SI1182_ADDRESS, SI1182_SPO2_REG, &spo2Data) != 0) {
            fprintf(stderr, "Failed to read heart rate or SpO2 data: %s\n", pigpioError());
            continue;
        }

        // Log the readings
        FILE* logFile = fopen("biometric_log.txt", "a+");
        if (logFile == NULL) {
            fprintf(stderr, "Failed to open log file for append: %s\n", strerror(errno));
            fclose(logFile);
            continue;
        }

        fprintf(logFile, "%s, Heart Rate: %u BPM, SpO2: %u%%\n", timestamp, heartRateData, spo2Data);
        fclose(logFile);

        // Handle SIGINT (Ctrl+C)
        if (signal(SIGINT, handleSIGINT) == SIG_ERR) {
            fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        }
    }

    // Graceful shutdown
    handleSIGINT(SIGINT);

    // Close I2C bus and terminate pigpio
    pigpioI2CClose(1);
    pigpioTerminate(PIGPIO_ID);

    return EXIT_SUCCESS;
}

// SIGINT handler
void handleSIGINT(int signum) {
    fprintf(stderr, "Received SIGINT, terminating...\n");
    exit(EXIT_FAILURE);
}

