#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define ALARM_GPIO 27

FILE *logFile = NULL;
pigpio *pi = NULL;

const char *timestampFormat = "%Y-%m-%dT%H:%M:%S";

void setup_pigpio() {
    if (pigpio_init() == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_errstr());
        exit(EXIT_FAILURE);
    }

    pi = pigpio_new();
    if (pi == NULL) {
        fprintf(stderr, "Failed to create pigpio instance: %s\n", pigpio_errstr());
        pigpio_free();
        exit(EXIT_FAILURE);
    }

    if (gpio_mode(SENSOR_1_GPIO, GPIO_INPUT) == -1) {
        fprintf(stderr, "Failed to set GPIO %d to input: %s\n", SENSOR_1_GPIO, pigpio_errstr());
        pigpio_free();
        exit(EXIT_FAILURE);
    }
    if (gpio_set_pull(SENSOR_1_GPIO, GPIO_PULLDOWN) == -1) {
        fprintf(stderr, "Failed to set pull-down resistor on GPIO %d: %s\n", SENSOR_1_GPIO, pigpio_errstr());
        pigpio_free();
        exit(EXIT_FAILURE);
    }

    if (gpio_mode(SENSOR_2_GPIO, GPIO_INPUT) == -1) {
        fprintf(stderr, "Failed to set GPIO %d to input: %s\n", SENSOR_2_GPIO, pigpio_errstr());
        pigpio_free();
        exit(EXIT_FAILURE);
    }
    if (gpio_set_pull(SENSOR_2_GPIO, GPIO_PULLDOWN) == -1) {
        fprintf(stderr, "Failed to set pull-down resistor on GPIO %d: %s\n", SENSOR_2_GPIO, pigpio_errstr());
        pigpio_free();
        exit(EXIT_FAILURE);
    }

    if (gpio_mode(ALARM_GPIO, GPIO_OUTPUT) == -1) {
        fprintf(stderr, "Failed to set GPIO %d to output: %s\n", ALARM_GPIO, pigpio_errstr());
        pigpio_free();
        exit(EXIT_FAILURE);
    }
    if (gpio_write(ALARM_GPIO, 0) == -1) {
        fprintf(stderr, "Failed to set GPIO %d to LOW: %s\n", ALARM_GPIO, pigpio_errstr());
        pigpio_free();
        exit(EXIT_FAILURE);
    }
}

void cleanup() {
    if (pi != NULL) {
        pigpio_free(pi);
        pi = NULL;
    }

    if (logFile != NULL) {
        fclose(logFile);
        logFile = NULL;
    }
}

void alarm_on() {
    if (gpio_write(ALARM_GPIO, 1) == -1) {
        fprintf(stderr, "Failed to set GPIO %d to HIGH: %s\n", ALARM_GPIO, pigpio_errstr());
    }
}

void alarm_off() {
    if (gpio_write(ALARM_GPIO, 0) == -1) {
        fprintf(stderr, "Failed to set GPIO %d to LOW: %s\n", ALARM_GPIO, pigpio_errstr());
    }
}

void poll_sensors() {
    struct timespec now;
    time_get(&now, TIME_NOW);

    int sensor1 = gpio_read(SENSOR_1_GPIO);
    int sensor2 = gpio_read(SENSOR_2_GPIO);

    if (sensor1 && sensor2) {
        alarm_on();
        fprintf(logFile, "%sT%s: Both sensors exceeded threshold\n", timestampFormat, now);
    } else if (sensor1) {
        alarm_on();
        fprintf(logFile, "%sT%s: Sensor 1 exceeded threshold\n", timestampFormat, now);
    } else if (sensor2) {
        alarm_on();
        fprintf(logFile, "%sT%s: Sensor 2 exceeded threshold\n", timestampFormat, now);
    } else {
        alarm_off();
        fprintf(logFile, "%sT%s: Both sensors returned to normal\n", timestampFormat, now);
    }

    usleep(100000); // Poll every 100 ms
}

void handle_signals(int signum) {
    switch (signum) {
        case SIGINT:
        case SIGTERM:
            alarm_off();
            cleanup();
            break;
        default:
            fprintf(stderr, "Unknown signal received: %d\n", signum);
            exit(EXIT_FAILURE);
    }
}

int main() {
    setup_pigpio();

    logFile = fopen("bridge_integrity.log", "a+");
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    while (1) {
        poll_sensors();
        usleep(100000); // 100 ms delay
    }

    handle_signals(SIGINT);
    handle_signals(SIGTERM);

    cleanup();

    return 0;
}

