#define PIGPIO_ID 0  // Use the default pigpio ID
#define SEISMIC_ADDR 0x1D  // Omron D7S-A0011 I2C address
#define SEISMIC_CTRL1_REG 0x1F
#define SEISMIC_DATA_REG_START 0x28
#define SEISMIC_DATA_REG_END 0x2D
#define THRESHOLD_VALUE 500
#define LED_GPIO 17
#define LOG_FILE "seismic_events.log"

// Function prototypes
