void compute_vibration_magnitude(const uint8_t *data) {
    // Assuming data is in little-endian format and correctly aligned
    double x_accel = *(double *)(&data[0]);
    double y_accel = *(double *)(&data[2]);
    double z_accel = *(double *)(&data[4]);

    double magnitude_squared = x_accel * x_accel + y_accel * y_accel + z_accel * z_accel;
    double vibration_magnitude = sqrt(magnitude_squared);
}

