#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_NUM_INfrared1 4
#define GPIO_NUM_Infrared2 17
#define GPIO_NUM_Infrared3 27
#define GPIO_NUM_Infrared4 22
#define GPIO_NUM_LED        18

volatile sig_atomic_t should_exit = 0;

void setup_gpios(void) {
    struct gpiod_dir gpio_dir[5];
    struct gpiod_csn gpio_csn[5];
    struct gpiod_pad gpio_pad[5];

    gpio_dir[0].value = GPIOD_DIR_IN;
    gpio_dir[1].value = GPIOD_DIR_IN;
    gpio_dir[2].value = GPIOD_DIR_IN;
    gpio_dir[3].value = GPIOD_DIR_IN;
    gpio_dir[4].value = GPIOD_DIR_OUT;

    gpio_csn[0].value = GPIOD_CSN_DISABLE;
    gpio_csn[1].value = GPIOD_CSN_DISABLE;
    gpio_csn[2].value = GPIOD_CSN_DISABLE;
    gpio_csn[3].value = GPIOD_CSN_DISABLE;
    gpio_csn[4].value = GPIOD_CSN_DISABLE;

    gpio_pad[0].base = gpiod_get_device_by_name("gpiochip0");
    gpio_pad[1].base = gpiod_get_device_by_name("gpiochip0");
    gpio_pad[2].base = gpiod_get_device_by_name("gpiochip0");
    gpio_pad[3].base = gpiod_get_device_by_name("gpiochip0");
    gpio_pad[4].base = gpiod_get_device_by_name("gpiochip0");

    if (gpiod_request(gpio_pad[0].base) < 0) {
        perror("Failed to request GPIO pad 0");
        exit(EXIT_FAILURE);
    }

    if (gpiod_request(gpio_pad[1].base) < 0) {
        perror("Failed to request GPIO pad 1");
        gpiod_release(gpio_pad[0].base);
        exit(EXIT_FAILURE);
    }

    if (gpiod_request(gpio_pad[2].base) < 0) {
        perror("Failed to request GPIO pad 2");
        gpiod_release(gpio_pad[1].base);
        gpiod_release(gpio_pad[0].base);
        exit(EXIT_FAILURE);
    }

    if (gpiod_request(gpio_pad[3].base) < 0) {
        perror("Failed to request GPIO pad 3");
        gpiod_release(gpio_pad[2].base);
        gpiod_release(gpio_pad[1].base);
        gpiod_release(gpio_pad[0].base);
        exit(EXIT_FAILURE);
    }

    if (gpiod_request(gpio_pad[4].base) < 0) {
        perror("Failed to request GPIO pad 4");
        gpiod_release(gpio_pad[3].base);
        gpiod_release(gpio_pad[2].base);
        gpiod_release(gpio_pad[1].base);
        gpiod_release(gpio_pad[0].base);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < 5; i++) {
        if (gpiod_csn[i].base == NULL) {
            perror("Failed to get CSN for GPIO");
            gpiod_release(gpio_pad[i].base);
            for (int j = i + 1; j < 5; j++) {
                gpiod_release(gpio_pad[j].base);
            }
            gpiod_release(gpio_pad[i].base);
            exit(EXIT_FAILURE);
        }

        if (gpiod_set_data_direction(gpio_pad[i].base, gpio_dir[i].value) < 0) {
            perror("Failed to set direction for GPIO");
            gpiod_release(gpio_pad[i].base);
            for (int j = i + 1; j < 5; j++) {
                gpiod_release(gpio_pad[j].base);
            }
            gpiod_release(gpio_pad[i].base);
            exit(EXIT_FAILURE);
        }

        if (gpiod_set_cs(gpio_pad[i].base, gpio_csn[i].value) < 0) {
            perror("Failed to set CS for GPIO");
            gpiod_release(gpio_pad[i].base);
            for (int j = i + 1; j < 5; j++) {
                gpiod_release(gpio_pad[j].base);
            }
            gpiod_release(gpio_pad[i].base);
            exit(EXIT_FAILURE);
        }
    }

    printf("GPIOs initialized successfully.\n");
}

void read_sensors_and_control_led(void) {
    struct gpiod_value in_values[4];
    struct gpiod_value out_value;

    while (1) {
        for (int i = 0; i < 4; i++) {
            if (gpiod_get_value(gpio_pad[i].base, in_values + i) < 0) {
                perror("Failed to read GPIO value");
                break;
            }
            if (in_values[i].actual == 1) {
                // Object detected on GPIO %d
                out_value.value = 1;
            } else {
                out_value.value = 0;
            }
        }

        if (gpiod_write(gpio_pad[4].base, &out_value) < 0) {
            perror("Failed to write to GPIO");
            break;
        }

        usleep(50000); // Poll every 50 ms
    }
}

void cleanup_and_exit(int sig) {
    should_exit = 1;
    printf("SIGINT received, exiting...\n");
    // Release all GPIOs
    for (int i = 0; i < 5; i++) {
        if (gpio_pad[i].base) {
            gpiod_release(gpio_pad[i].base);
        }
    }

    exit(sig);
}

int main(void) {
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    setup_gpios();

    printf("Starting obstacle detection and LED control...\n");

    if (pthread_create(&thread_id, NULL, &read_sensors_and_control_led, NULL) == 0) {
        pthread_detach(thread_id); // Detach to avoid zombie processes
    } else {
        perror("Failed to create thread");
        exit(EXIT_FAILURE);
    }

    while (!should_exit) {
        // No-op
    }

    printf("Exiting gracefully...\n");
    return 0;
}

