#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_SENSORS 5
#define DEBOUNCE_MS 50
#define LOG_FILE "/var/log/flame_events.log"
#define LOG_FACILITY LOG_USER
#define LOG_ID "flame_monitor"

volatile sig_atomic_t shutdown_flag = 0;

// GPIO pins for flame sensors
const int gpios[NUM_SENSORS] = {2, 3, 4, 17, 27};

// Line descriptors for GPIO lines
gpiod_line_t lines[NUM_SENSORS];

// Sensor IDs for logging
const char *sensor_ids[NUM_SENSORS] = {"Sensor 1", "Sensor 2", "Sensor 3", "Sensor 4", "Sensor 5"};

void setup_lines() {
    int rc;
    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_get_line_by_index(gpios[i]);
        if (IS_ERR(lines[i])) {
            syslog(LOG_ERR, "Failed to acquire line %d (GPIO %d)", i, gpios[i]);
            continue;
        }
        rc = gpiod_request_lines(1, &lines[i]);
        if (rc != 0) {
            syslog(LOG_ERR, "Failed to request line %d (GPIO %d)", i, gpios[i]);
            gpiod_line_release(lines[i]);
            lines[i] = GPIOD_LINE_NULL;
            continue;
        }
    }
    if (gpiod_is_chip_open()) {
        syslog(LOG_INFO, "Flame sensor chip successfully opened.");
    } else {
        syslog(LOG_ERR, "Failed to open GPIO chip.");
        exit(EXIT_FAILURE);
    }
}

void poll_sensors() {
    struct timespec timestamp;
    time_t now = time(NULL);
    struct tm timeinfo;
    char timestamp_str[50];

    // Convert time to ISO 8601 UTC format
    localtime_r(&now, &timeinfo);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%SZ", &timeinfo);
    strptime(timestamp_str, "%Y-%m-%dT%H:%M:%SZ", &timestamp);

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (lines[i] == GPIOD_LINE_NULL) {
            continue;
        }

        int value;
        if (gpiod_line_request_one(lines[i], GPIOD_INPUT_RISING, DEBOUNCE_MS * 1000) < 0) {
            syslog(LOG_WARNING, "Failed to request rising edge for sensor %d (GPIO %d)", i, gpios[i]);
            continue;
        }

        // Wait for the event
        if (gpiod_line_read(lines[i]) < 0) {
            syslog(LOG_WARNING, "Failed to read sensor %d (GPIO %d)", i, gpios[i]);
            continue;
        }

