        if (IS_ERR(lines[i])) {
            syslog(LOG_ERR, "Failed to acquire line %d (GPIO %d)", i, gpios[i]);
            continue;
        }
        rc = gpiod_request_lines(1, &lines[i]);
        if (rc != 0) {
            syslog(LOG_ERR, "Failed to request line %d (GPIO %d)", i, gpios[i]);
            gpiod_line_release(lines[i]);
            lines[i] = GPIOD_LINE_NULL;
            continue;
        }
    }
    if (gpiod_is_chip_open()) {
        syslog(LOG_INFO, "Flame sensor chip successfully opened.");
    } else {
        syslog(LOG_ERR, "Failed to open GPIO chip.");
        exit(EXIT_FAILURE);
    }
}

