#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <string.h>
#include <unistd.h>

#define TOUCH_SENSOR_GPIO_PINS {
    BCM_GPIO_5, BCM_GPIO_6, BCM_GPIO_13, BCM_GPIO_19, BCM_GPIO_26,
    BCM_GPIO_12, BCM_GPIO_16, BCM_GPIO_20
}

#define TOUCH_SENSOR_COUNT sizeof(TOUCH_SENSOR_GPIO_PINS) / sizeof(TOUCH_SENSOR_GPIO_PINS[0])

struct touch_state {
    int state;
    time_t timestamp;
};

void setup_gpiod(void) {
    int ret;

    /* Initialize libgpiod */
    ret = gpiod_init();
    if (ret < 0) {
        fprintf(stderr, "gpiod_init failed: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    /* Initialize GPIO chip */
    ret = gpiod_chchip_select(GPIOD_CHCHIP_BCM, GPIOD_CHCONF_DEFAULT);
    if (ret < 0) {
        fprintf(stderr, "gpiod_chchip_select failed: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void cleanup_gpiod(void) {
    /* Release resources */
    gpiod_exit();
}

void poll_touch_sensors(void) {
    struct touch_state states[TOUCH_SENSOR_COUNT];
    int i;
    time_t now;

    /* Get current time */
    now = time(NULL);

    /* Bulk line request for all GPIO pins */
    ret = gpiod_line_bulk_request(TOUCH_SENSOR_GPIO_PINS, TOUCH_SENSOR_COUNT, GPIOD_LINE_REQUEST_READ);
    if (ret < 0) {
        fprintf(stderr, "gpiod_line_bulk_request failed: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    /* Read states */
    ret = gpiod_line_bulk_read(TOUCH_SENSOR_GPIO_PINS, TOUCH_SENSOR_COUNT, states);
    if (ret < 0) {
        fprintf(stderr, "gpiod_line_bulk_read failed: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    /* Check for state changes */
    for (i = 0; i < TOUCH_SENSOR_COUNT; i++) {
        struct touch_state old = states[i];
        struct touch_state new = states[i];

        if (old.state != new.state) {
            char buffer[256];
            time_t timestamp = now;

            snprintf(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S.%03zu, GPIO %d (%d)",
                     gmtime(&timestamp).tm_year + 1900,
                     gmtime(&timestamp).tm_mon + 1,
                     gmtime(&timestamp).tm_day,
                     gmtime(&timestamp).tm_hour,
                     gmtime(&timestamp).tm_min,
                     gmtime(&timestamp).tm_sec,
                     states[i].state == 1 ? "detected" : "released",
                     TOUCH_SENSOR_GPIO_PINS[i], BCM_GPIO_NUM_TO_BCM(states[i].gpio)));

            printf("Touch state change: %s\n", buffer);
        }
    }
}

void handle_signal(int signum) {
    /* Graceful shutdown on SIGINT */
    cleanup_gpiod();
    exit(EXIT_SUCCESS);
}

int main(void) {
    struct sigaction sa;
    setup_gpiod();

    /* Set up signal handler for SIGINT */
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    while (1) {
        poll_touch_sensors();
        usleep(50000); /* Poll every 50 milliseconds */
    }

    return 0;
}

