#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pigpio.h>
#include <stdint.h>

#define PIGPIO_ID 0  // Use the default pigpio ID
#define VEML7700_ADDR 0x10
#define VEML7700_CONFIG_REG 0x00
#define VEML7700_ALS_REG 0x04
#define GPIO_PIN 18

// Function prototypes
void setup_pigpio();
void setup_i2c();
void configure_sensor();
void read_als();
void set_brightness(uint16_t lux);
void log_sample(uint16_t lux, int brightness);
void cleanup();

int main() {
    setup_pigpio();
    setup_i2c();
    configure_sensor();
    while (1) {
        read_als();
        set_brightness((uint16_t) (100 * lux / 1000)); // Convert lux to percentage
        log_sample((uint16_t) lux, set_brightness((uint16_t) lux));
        usleep(1000000); // Sleep for 1 second
    }
    cleanup();
    return 0;
}

// Function: setup_pigpio
void setup_pigpio() {
    if (pgpio_init() == -1) {
        fprintf(stderr, "Error initializing pigpio: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }
}

// Function: setup_i2c
void setup_i2c() {
    if (pgpio_i2c_open(1) == -1) {
        fprintf(stderr, "Error opening I2C bus: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }
}

// Function: configure_sensor
void configure_sensor() {
    uint16_t config_value = 0x0000; // ALS gain 1/8 and integration time 100 ms

    if (pgpio_i2c_write(VEML7700_ADDR, VEML7700_CONFIG_REG, &config_value, 2) == -1) {
        fprintf(stderr, "Error writing to VEML7700 config register: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }
}

// Function: read_als
void read_als() {
    uint16_t raw_lux;

    if (pgpio_i2c_read(VEML7700_ADDR, VEML7700_ALS_REG, &raw_lux, 2) == -1) {
        fprintf(stderr, "Error reading from VEML7700 ALS register: %s\n", pigpio_error());
        return;
    }

    // Convert raw lux to lux
    float lux = raw_lux * 0.0576;
    printf("Lux: %f\n", lux);
}

// Function: set_brightness
void set_brightness(uint16_t lux) {
    if (lux < 100) {
        pigpio_set_PWM_range(GPIO_PIN, 100);
    } else if (lux < 500) {
        pigpio_set_PWM_range(GPIO_PIN, 75);
    } else if (lux < 1000) {
        pigpio_set_PWM_range(GPIO_PIN, 50);
    } else {
        pigpio_set_PWM_range(GPIO_PIN, 25);
    }

    pigpio_set_PWM_duty(GPIO_PIN, lux);
}

// Function: log_sample
void log_sample(uint16_t lux, int brightness) {
    char timestamp[50];
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *file = fopen("grow_log.txt", "a+");
    if (!file) {
        fprintf(stderr, "Error opening grow_log.txt for appending: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    fprintf(file, "%s: Lux: %d, Brightness: %d, Error: 0\n", timestamp, lux, brightness);
    fflush(file);
}

// Function: cleanup
void cleanup() {
    pigpio_close();
    pgpio_i2c_close();
    fclose("grow_log.txt");
}

