// Function prototypes
void init_pigpio();
void setup_i2c();
void read_light_data();
void write_config_word(uint16_t word);
void handle_sigint(int signum);
void log_light_data(double lux);
void cleanup();

int main() {
    // Initialize pigpio
    if (pigpioSetup(0) == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }

    // Setup I2C
    setup_i2c();

    // Main loop
    while (1) {
        read_light_data();
        sleep(1); // Read once per second
    }

    // Clean up on SIGINT
    SIGINTHandler signal_handler = handle_sigint;
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Run the main loop until interrupted
    while (1) {
        sleep(1);
    }

    // Clean up
    cleanup();

    return 0;
}

// Function to initialize pigpio
void init_pigpio() {
    if (pigpioSetup(0) == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }
}

// Function to setup I2C
void setup_i2c() {
    int i2c_fd;
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) == -1) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (pigpioI2COpen(i2c_fd, 1) == -1) {
        fprintf(stderr, "Failed to open I2C with pigpio: %s\n", pigpioError());
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

// Function to read light data from the OPT3001
void read_light_data() {
    uint16_t config_word;
    double lux;

    // Convert configuration word to big-endian
    config_word = ((uint16_t)(CONFIG_WORD & 0xFF)) | (((uint16_t)(CONFIG_WORD >> 8)) << 8);

    // Write configuration word to OPT3001
    if (pigpioI2CWriteWordData(i2c_fd, 0x44, &config_word, 1) == -1) {
        fprintf(stderr, "Failed to write configuration word: %s\n", pigpioError());
        return;
    }

    // Wait at least 100 ms for conversion
    usleep(100000);

    // Read result register
    uint16_t result;
    if (pigpioI2CReadWordData(i2c_fd, 0x44, &result, 1) == -1) {
        fprintf(stderr, "Failed to read result register: %s\n", pigpioError());
        return;
    }

    // Byte-swap the result to big-endian
    result = ((uint16_t)(result >> 8)) | (uint16_t)(result << 8);

    // Compute lux value
    lux = (result & 0x3FF) * 0.01 * (1.0 << (result >> 12));

    // Log the light data
    time_t now = time(NULL);
    char log_entry[256];
    strftime(log_entry, sizeof(log_entry), "%Y-%m-%d %H:%M:%S,", localtime(&now));
    sprintf(log_entry + strlen("%Y-%m-%d %H:%M:%S, "), "%.2f", lux);
    FILE *log_file = fopen("light_data.txt", "a+");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file for writing: %s\n", strerror(errno));
        fclose(log_file);
        return;
    }
    fprintf(log_file, "%s", log_entry);
    fclose(log_file);

    // Print lux value to stdout
    printf("Lux: %.2f\n", lux);
}

// Function to write a configuration word to the OPT3001
void write_config_word(uint16_t word) {
    uint16_t big_endian_word;
    // Convert to big-endian
    big_endian_word = ((uint16_t)(word & 0xFF)) | ((uint16_t)(word >> 8) << 8);
    pigpioI2CWriteWordData(i2c_fd, 0x44, &big_endian_word, 1);
}

// SIGINT handler for clean shutdown
void handle_sigint(int signum) {
    // Close I2C handle
    pigpioI2CClose(i2c_fd);

    // Terminate pigpio
    pigpioTerminate();

    // Exit the program
    exit(EXIT_SUCCESS);
}

// Function to clean up resources
void cleanup() {
    // Close log file
    fclose(log_file);

    // Close I2C handle
    close(i2c_fd);

    // Terminate pigpio
    pigpioTerminate();
}

