// Global variables
pigpio *pi;
FILE *logFile;
time_t lastLogTime = 0;
int flameDetected = 0;

// Main function
int main() {
    // Initialize pigpio
    setupPigpio();

    // Install SIGINT handler
    signal(SIGINT, handleSIGINT);

    while (1) {
        // Poll the sensor every 500 milliseconds
        struct timespec timeout = { .tv_sec = 0, .tv_nsec = 500000 };
        if (pi == NULL) {
            fprintf(stderr, "Failed to initialize pigpio.\n");
            exit(EXIT_FAILURE);
        }

        if (!pigpioWaitTimeout(pi, -1, &timeout)) {
            fprintf(stderr, "Error waiting for GPIO operations: %s\n", pigpioError(pi));
            continue;
        }

        // Read GPIO 4 (BCM 17)
        int gpio4 = pigpioRead(pi, 17);

        // Check if flame is detected
        if (gpio4 == 0) {
            flameDetected = 1;
            // Alert by setting GPIO 17 HIGH for 1 second
            pigpioWrite(pi, 17, 1);
            sleep(1);
            pigpioWrite(pi, 17, 0);
        }

        // Log the reading with timestamp
        time_t now = time(NULL);
        writeToLog("Flame sensor reading: %d at %s", gpio4, ctime(&now));

        // Reset flame detected flag
        flameDetected = 0;

        // Check for SIGINT (Ctrl+C)
        if (flameDetected) {
            // If flame detected during SIGINT, handle it here
            printf("SIGINT caught while flame detected. Cleaning up.\n");
            cleanupResources();
            exit(EXIT_SUCCESS);
        }
    }

    // Clean up on normal exit
    cleanupResources();

    return 0;
}

