    pi = pigpioOpen();
    if (pi == NULL) {
        fprintf(stderr, "Failed to open pigpio.\n");
        exit(EXIT_FAILURE);
    }

    // Set GPIO 17 as output for alert
    pigpioWrite(pi, 17, 0);

    // Open log file for appending
    logFile = fopen("fire_events.log", "a+");
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        exit(EXIT_FAILURE);
    }
}

// Cleanup resources
void cleanupResources() {
    // Close log file
    if (logFile != NULL) {
        fclose(logFile);
        logFile = NULL;
    }

    // Reset all GPIOs to default state
    for (int i = 0; i < 32; i++) {
        pigpioWrite(pi, i, 0);
    }

    // Close pigpio
    pigpioClose(pi);
    pi = NULL;
}

