void read_touch_events();
void handle_signal(int signum);
void cleanup();

int main() {
    // Initialize signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Setup touch sensor
    if (setup_touch_sensor() != 0) {
        fprintf(stderr, "Error setting up touch sensor.\n");
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        read_touch_events();
        usleep(DEBOUNCE_MS * 1000); // Wait for debounce interval
    }

