    cleanup();

    return EXIT_SUCCESS;
}

// Function to setup the touch sensor
void setup_touch_sensor() {
    struct gpiod_chip *chip;
    struct gpiod_pin *pin;
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open(GPIOD_CHIPS_ALL, GPIOD_OPEN_BY_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip.\n");
        gpiod_chip_close(chip);
        return -1;
    }

    // Open the GPIO pin with pull-down configuration
    pin = gpiod_pin_open(chip, TOUCH_SENSOR_GPIO, GPIOD_PIN_INPUT_PULLDOWN);
    if (!pin) {
        fprintf(stderr, "Failed to open GPIO pin %d.\n", TOUCH_SENSOR_GPIO);
        gpiod_chip_close(chip);
        return -1;
    }

    // Configure the pin as input
    ret = gpiod_pin_config(pin, GPIOD_PIN_INPUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to configure GPIO pin %d as input.\n", TOUCH_SENSOR_GPIO);
        gpiod_pin_close(pin);
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_pin_close(pin);
    gpiod_chip_close(chip);

    // Successfully initialized touch sensor
    printf("Touch sensor initialized successfully.\n");
}

