void read_touch_events() {
    struct timespec ts;
    struct gpiod_value value;
    int ret;
    char timestamp[50];
    FILE *log_file;

    // Get current time
    clock_gettime(CLOCK_REALTIME, &ts);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &ts);

    // Open log file for appending
    log_file = fopen(TOUCH_LOG_FILE, "a+");
    if (!log_file) {
        printf("Failed to open log file for writing.\n");
        return;
    }

    // Poll the GPIO pin
    ret = gpiod_pin_get_value(chip, pin, &value);
    if (ret < 0) {
        fprintf(stderr, "Failed to read GPIO pin value.\n");
        fclose(log_file);
        return;
    }

    // Check for touch event
    if (value.value == 1) {
        // Touch detected
        fprintf(log_file, "%s: Touch Detected\n", timestamp);
        fflush(log_file);
