        // Touch released
        fprintf(log_file, "%s: Touch Released\n", timestamp);
        fflush(log_file);
    }

    // Close the log file
    fclose(log_file);

    // Release resources on exit or signal
    handle_signal(SIGINT);
    handle_signal(SIGTERM);
}

