#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <pigpio.h>
#include <stdint.h>

#define PIGPIO_ID 0  // Use the default pigpio ID

// Constants for SLF3S-1300F sensor
#define SLF3S_ADDR 0x08
#define SLF3S_READ_LEN 3
#define SLF3S_CMD 0x36
#define SLF3S_READ_DELAY_MS 2
#define SLF3S_CRC_POLYNOMIAL 0x31
#define SLF3S_CRC_INIT 0xFF
#define SLF3S_RAW_TO_ML_MIN 90.0

// Function prototypes
void initialize_pigpio();
void initialize_i2c();
void read_flow_sensor(uint8_t address, uint8_t* data, size_t len);
void validate_crc(uint8_t* data, size_t len, uint8_t crc_init);
void convert_raw_to_ml_min(float raw_value);
void write_to_cooling_log(const char* timestamp, float flow_rate, const char* status);
void handle_sigint(int signum);

int main() {
    // Initialize pigpio
    initialize_pigpio();

    // Initialize I2C
    initialize_i2c();

    // Main loop
    while (1) {
        uint8_t data[SLF3S_READ_LEN];
        float flow_rate_ml_min = 0.0;

        // Send command to sensor
        pigpio_write(SLF3S_ADDR, SLF3S_CMD, 2);

        // Wait for at least 2 ms
        usleep(SLF3S_READ_DELAY_MS * 1000);

        // Read sensor data
        if (i2c_smbus_read_i2c(SLF3S_ADDR, SLF3S_READ_LEN, data) < 0) {
            fprintf(stderr, "I2C read failed\n");
            continue;
        }

        // Validate CRC
        uint8_t crc = validate_crc(data, SLF3S_READ_LEN, SLF3S_CRC_INIT);
        if (crc != data[SLF3S_READ_LEN - 1]) {
            fprintf(stderr, "CRC failed\n");
            continue;
        }

        // Convert raw value to ml/min
        convert_raw_to_ml_min(data[0]);

        // Write to log file
        write_to_cooling_log(strftime("%F %T"), flow_rate_ml_min, "OK");

        // Handle SIGINT
        if (signal(SIGINT, handle_sigint) == SIG_ERR) {
            fprintf(stderr, "Failed to install SIGINT handler\n");
            exit(EXIT_FAILURE);
        }
    }

    // Cleanup on exit
    close(i2c_fd);
    pigpio_stop();
    exit(EXIT_SUCCESS);
}

// Function to initialize pigpio
void initialize_pigpio() {
    if (pigpio_open(PIGPIO_ID) == -1) {
        fprintf(stderr, "Failed to open pigpio\n");
        exit(EXIT_FAILURE);
    }
}

// Function to initialize I2C
void initialize_i2c() {
    int i2c_fd = -1;
    struct pigpio *pi = pigpio_open(PIGPIO_ID);

    if (pi == NULL) {
        fprintf(stderr, "Failed to open pigpio\n");
        exit(EXIT_FAILURE);
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        pigpio_close(pi);
        exit(EXIT_FAILURE);
    }

    if (i2c_smbus_start(i2c_fd, SLF3S_ADDR) < 0) {
        fprintf(stderr, "Failed to start I2C communication with sensor\n");
        close(i2c_fd);
        pigpio_close(pi);
        exit(EXIT_FAILURE);
    }

    // No need to stop I2C communication explicitly as we handle errors
}

// Function to read the flow sensor
void read_flow_sensor(uint8_t address, uint8_t* data, size_t len) {
    if (i2c_smbus_read_i2c(address, len, data) < 0) {
        fprintf(stderr, "I2C read failed\n");
        // Attempt recovery by re-initializing I2C handle
        close(i2c_fd);
        initialize_i2c();
    }
}

// Function to validate CRC
uint8_t validate_crc(uint8_t* data, size_t len, uint8_t crc_init) {
    uint8_t crc = crc_init;
    for (size_t i = 0; i < len; i++) {
        crc = (crc << 1) ^ (static_cast<uint8_t>(data[i]) & 0x80);
        crc ^= (static_cast<uint8_t>(data[i]) & 0x7F);
        if (crc == 0) {
            crc = 0xFF; // Reset to init value if zero
        }
    }
    return crc;
}

// Function to convert raw value to ml/min
void convert_raw_to_ml_min(float raw_value) {
    if (raw_value < 0.0 || raw_value > 100.0) {
        fprintf(stderr, "Invalid flow rate, out of range [0.0, 100.0] ml/min\n");
        return;
    }

    flow_rate_ml_min = raw_value / SLF3S_RAW_TO_ML_MIN;
}

// Function to write to cooling log file
void write_to_cooling_log(const char* timestamp, float flow_rate, const char* status) {
    char log_line[256];
    snprintf(log_line, sizeof(log_line), "%s,%.1f, %s", timestamp, flow_rate, status);

    FILE* cooling_log = fopen("cooling_log.csv", "a");
    if (!cooling_log) {
        fprintf(stderr, "Failed to open or append to cooling_log.csv\n");
        return;
    }

    fprintf(cooling_log, "%s\n", log_line);
    fclose(cooling_log);
}

// Function to handle SIGINT
void handle_sigint(int signum) {
    fprintf(stderr, "SIGINT received, shutting down gracefully...\n");

    // Close I2C handle
    close(i2c_fd);

    // Stop pigpio
    pigpio_close(pi);

    // Exit the program
    exit(EXIT_SUCCESS);
}

