#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

#define GPIO17 17
#define GPIO27 27
#define GPIO22 22

#define SENSORS_COUNT 3
#define POLL_INTERVAL_MS 50

// Function prototypes
bool open_and_init_gpiod();
void poll_sensors_and_write_to_file();
void cleanup_and_exit();

int main() {
    // Initialize GPIO
    if (!open_and_init_gpiod()) {
        fprintf(stderr, "Failed to initialize GPIO.\n");
        return EXIT_FAILURE;
    }

    // Main loop
    while (true) {
        poll_sensors_and_write_to_file();
        usleep(POLL_INTERVAL_MS * 1000); // Convert milliseconds to microseconds
    }

    // Clean up on SIGINT
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    return EXIT_SUCCESS;
}

// Function to open and initialize libgpiod
bool open_and_init_gpiod() {
    int gpiochip_fd;
    struct gpiod_chip *chip;

    // Open the GPIO chip
    gpiochip_fd = open("/dev/gpiochip0", O_RDONLY);
    if (gpiochip_fd == -1) {
        perror("Failed to open GPIO chip");
        return false;
    }

    // Request the GPIO chip
    chip = gpiod_chip_open(gpiochip_fd);
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(gpiochip_fd);
        return false;
    }

    // Check if GPIO lines are available as input
    for (int i = 0; i < SENSORS_COUNT; ++i) {
        const char *gpio_name = (i == 0 ? "GPIO17" : (i == 1 ? "GPIO27" : "GPIO22"));
        struct gpiod_pin *pin = gpiod_chip_find_pin(chip, gpio_name);

        if (!pin) {
            fprintf(stderr, "Pin %s not found on the GPIO chip.\n", gpio_name);
            gpiod_chip_close(chip);
            close(gpiochip_fd);
            return false;
        }

        if (gpiod_pin_direction(pin, GPIOD_DIR_IN) != 0) {
            fprintf(stderr, "Failed to set pin %s direction to input.\n", gpio_name);
            gpiod_chip_close(chip);
            close(gpiochip_fd);
            return false;
        }
    }

    return true;
}

