#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <gpiod.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>

#define GPIO_NUM 4  // GPIO4 on Raspberry Pi 5 (BCM numbering)
#define FLAME_SENSOR_LINE "gpiochip0:gpio4"

int main() {
    // Initialize libgpiod
    int ret;
    ret = gpiod_chip_open("gpiochip0", GPIOD_OPEN_READONLY);
    if (ret < 0) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request the GPIO line
    ret = gpiod_line_request_active_low(GPIO_NUM, FLAME_SENSOR_LINE);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close("gpiochip0");
        return EXIT_FAILURE;
    }

    // Configure the GPIO line for falling edge detection
    ret = gpiod_line_config_input(GPIO_NUM, GPIOD_INPUT_PULLDOWN);
    if (ret < 0) {
        perror("Failed to configure GPIO line");
        gpiod_line_release(GPIO_NUM);
        gpiod_chip_close("gpiochip0");
        return EXIT_FAILURE;
    }

    // Main loop to monitor for falling edge events
    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);

        // Poll for falling edge events
        ret = gpiod_line_event_poll(GPIO_NUM, GPIOD_LINE_EVENT_FALLING);
        if (ret < 0) {
            perror("Failed to poll for events");
            break; // Exit on error
        }

        // Check if a falling edge was detected
        if (ret > 0) {
            // Print alert with timestamp
            printf("Flame detected at %s\n", ctime(&ts.tv_sec));

            // Log the event to flame_events.txt
            FILE *file = fopen("flame_events.txt", "a+");
            if (file == NULL) {
                perror("Failed to open flame_events.txt");
                break;
            }
            fprintf(file, "Timestamp: %s\n", ctime(&ts.tv_sec));
            fclose(file);

            // Release the GPIO line
            gpiod_line_release(GPIO_NUM);
        }

        // Cleanup on SIGINT or SIGTERM
        if (ret == 0) {
            // Normal exit
            break;
        }
    }

    // Clean up resources
    gpiod_line_release(GPIO_NUM);
    gpiod_chip_close("gpiochip0");

    return EXIT_SUCCESS;
}

