#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <gpiod.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>

#define TOUCH_GPIO 23
#define LED_GPIO 24

// Function prototypes
void setup_gpios();
void handle_touch_event(int rising_edge);
void cleanup();
void signal_handler(int signum);

int main() {
    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Attempt to open GPIO chip /dev/gpiochip4
    int gpiochip_fd = open("/dev/gpiochip4", O_RDWR);
    if (gpiochip_fd == -1) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request GPIO lines
    struct gpiod_dir gpio_dir;
    gpio_dir.direction = GPIOD_DIR_IN for TOUCH_GPIO;
    gpio_dir.direction = GPIOD_DIR_OUT for LED_GPIO;
    if (gpiod_request(gpiochip_fd, &gpio_dir, 2) < 0) {
        perror("Failed to request GPIO lines");
        close(gpiochip_fd);
        exit(EXIT_FAILURE);
    }

    // Setup LED GPIO as output
    struct gpiod_set_config config;
    config.value = 1; // Set LED GPIO to high (LED off)
    if (gpiod_set_config(gpiochip_fd, LED_GPIO, &config) < 0) {
        perror("Failed to configure LED GPIO");
        gpiod_release(gpiochip_fd, 2);
        close(gpiochip_fd);
        exit(EXIT_FAILURE);
    }

    // Setup touch sensor GPIO as input
    struct gpiod_get_config config;
    if (gpiod_get_config(gpiochip_fd, TOUCH_GPIO, &config) < 0) {
        perror("Failed to get config for touch sensor GPIO");
        gpiod_release(gpiochip_fd, 2);
        close(gpiochip_fd);
        exit(EXIT_FAILURE);
    }

    // Open log file for writing
    char log_path[100] = "touch_log.txt";
    FILE *log_file = fopen(log_path, "a+");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpiod_release(gpiochip_fd, 2);
        close(gpiochip_fd);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Poll GPIO line events with 1-second timeout
        struct gpiod_line_event event;
        ssize_t events_read = gpiod_line_event_poll(gpiochip_fd, TOUCH_GPIO, 1000, &event);
        if (events_read < 0) {
            perror("Failed to poll GPIO line events");
            break; // Exit on error
        }
        if (events_read == 0) {
            // No events in the timeout period
            continue;
        }

        // Handle rising edge event
        handle_touch_event(event.rising_edge);

        // Toggle LED state
        config.value = !config.value; // Toggle LED state
        if (gpiod_set_config(gpiochip_fd, LED_GPIO, &config) < 0) {
            perror("Failed to toggle LED");
            break; // Exit on error
        }
    }

    // Cleanup
    cleanup();

    // Close log file and release GPIO resources
    fclose(log_file);
    gpiod_release(gpiochip_fd, 2);
    close(gpiochip_fd);

    return 0;
}

// Function to handle a touch event
void handle_touch_event(int rising_edge) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    char timestamp[50];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%fZ", &ts);

    char new_led_state;
    if (rising_edge) {
        new_led_state = 1; // LED on
    } else {
        new_led_state = 0; // LED off
    }

    fprintf(log_file, "Touch detected at %s, LED state: %c\n", timestamp, new_led_state);
}

// Function to cleanup resources
void cleanup() {
    // Close log file
    fclose(log_file);

    // Release GPIO lines
    gpiod_release(gpiochip_fd, 2);
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    // Log signal received
    fprintf(stderr, "Signal %d received, shutting down gracefully...\n", signum);

    // Perform cleanup
    cleanup();
    exit(EXIT_SUCCESS);
}

