#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>

#define BUZZER_GPIO 18
#define FLAME_SENSOR_GPIO 17

FILE *log_file = NULL;
gpiod_chip *chip;
gpiod_line *flame_sensor_line;
gpiod_line *buzzer_line;

void setup_system() {
    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0", GPIOD_OPEN_BY_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Request the flame sensor line
    flame_sensor_line = gpiod_chip_get_line(chip, FLAME_SENSOR_GPIO);
    if (flame_sensor_line == NULL) {
        fprintf(stderr, "Error getting flame sensor line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request the buzzer line
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_GPIO);
    if (buzzer_line == NULL) {
        fprintf(stderr, "Error getting buzzer line: %s\n", strerror(errno));
        gpiod_line_put(flame_sensor_line, GPIOD_LINE_STATE_HIGH); // Ensure buzzer is off
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Log system start
    time_t now = time(NULL);
    char buffer[256];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(log_file, "System started at %s\n", buffer);
}

void handle_shutdown_signal(int signum) {
    // Turn off the buzzer
    gpiod_line_put(buzzer_line, GPIOD_LINE_STATE_LOW);

    // Release the lines
    gpiod_line_put(flame_sensor_line, GPIOD_LINE_STATE_HIGH);
    gpiod_line_put(buzzer_line, GPIOD_LINE_STATE_HIGH);

    // Close the chip and log file
    gpiod_chip_close(chip);
    fclose(log_file);

    // Exit cleanly
    exit(EXIT_SUCCESS);
}

void poll_and_check_flame() {
    time_t now = time(NULL);
    char buffer[256];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&now));

    // Check flame sensor
    int flame_sensor_value = gpiod_line_get_value(flame_sensor_line);
    if (flame_sensor_value == 0) { // LOW indicates flame detected
        fprintf(log_file, "Flame detected at %s\n", buffer);
        // Activate buzzer for 2 seconds
        gpiod_line_set_value(buzzer_line, GPIOD_LINE_STATE_HIGH);
        sleep(2);
        gpiod_line_set_value(buzzer_line, GPIOD_LINE_STATE_LOW);

        // Log system event
        fprintf(log_file, "Buzzer activated for 2 seconds at %s\n", buffer);
    }

    // Poll every 500ms
    struct timespec timeout = { .tv_sec = 0, .tv_nsec = 500000 };
    if (nanosleep(&timeout, NULL) == -1) {
        perror("nanosleep");
        exit(EXIT_FAILURE);
    }
}

int main() {
    signal(SIGINT, handle_shutdown_signal);
    signal(SIGTERM, handle_shutdown_signal);

    setup_system();

    // Main loop
    while (1) {
        poll_and_check_flame();
        usleep(100000); // Sleep for 100ms to break into 100ms slices
    }

    return 0;
}
