#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TOUCH_GPIO 4
#define LED_GPIO 17
#define DEBOUNCE_MS 200
#define POLL_MS 10
#define TOUCH_LOG_FILE "touch_log.txt"

FILE *touch_log_file;

volatile int touch_rising_edge = 0;

void setup_pigpio();
void cleanup_pigpio();
void setup_gpio();
void cleanup_gpio();
void handle_signal(int signum);
void toggle_led();
void debounce();
void log_touch_event(const char *timestamp);

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_pigpio();
    setup_gpio();
    touch_log_file = fopen(TOUCH_LOG_FILE, "a+");

    if (touch_log_file == NULL) {
        fprintf(stderr, "Error: Unable to open %s for writing.\n", TOUCH_LOG_FILE);
        exit(EXIT_FAILURE);
    }

    while (1) {
        debounce();
        if (pigpio_wait_for_rising_edge(TOUCH_GPIO)) {
            touch_rising_edge = 1;
            toggle_led();
            log_touch_event((char *)ctime(&time(0)));
        }
    }

    cleanup_gpio();
    cleanup_pigpio();

    fclose(touch_log_file);

    return 0;
}

void setup_pigpio() {
    if (piOpen() < 0) {
        fprintf(stderr, "Error: Failed to open GPIO.\n");
        exit(EXIT_FAILURE);
    }
}

void cleanup_pigpio() {
    if (piClose() < 0) {
        fprintf(stderr, "Error: Failed to close GPIO.\n");
    }
}

void setup_gpio() {
    if (gpioMode(LED_GPIO, GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d to output.\n", LED_GPIO);
        exit(EXIT_FAILURE);
    }

    if (gpioMode(TOUCH_GPIO, GPIO_INPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d to input.\n", TOUCH_GPIO);
        exit(EXIT_FAILURE);
    }
}

void cleanup_gpio() {
    if (gpioMode(LED_GPIO, GPIO_INPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d to input.\n", LED_GPIO);
    }

    if (gpioMode(TOUCH_GPIO, GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d to output.\n", TOUCH_GPIO);
    }
}

void handle_signal(int signum) {
    toggle_led();
    fclose(touch_log_file);
    cleanup_pigpio();
    exit(EXIT_SUCCESS);
}

void toggle_led() {
    int state = gpioRead(LED_GPIO);
    gpioWrite(LED_GPIO, !state);
}

void debounce() {
    static int last_rising_edge_time = 0;
    static int debounce_count = 0;

    if (pigpio_get_time() - last_rising_edge_time > DEBOUNCE_MS) {
        debounce_count = 0;
    } else {
        debounce_count++;
    }

    if (debounce_count > 200) {
        debounce_count = 0;
        touch_rising_edge = 0;
    }
}

void log_touch_event(const char *timestamp) {
    fprintf(touch_log_file, "%s\n", timestamp);
}

