#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the TMAG5110A1 Hall-effect sensors
#define GPIO4  17
#define GPIO17 4
#define GPIO27 22

// Function prototypes
void setup_pigpio();
void setup_gpios();
void read_sensors();
void handle_signal(int signum);
void cleanup();

// Main program entry point
int main() {
    // Initialize pigpio
    setup_pigpio();

    // Set up GPIO pins
    setup_gpios();

    // Start the main loop
    while (1) {
        // Read sensors
        read_sensors();

        // Delay for 100 ms
        usleep(100000);
    }

    // Clean up on exit
    cleanup();

    return 0;
}

// Function to initialize pigpio
void setup_pigpio() {
    if (pigpioSetup() == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }
}

// Function to set up GPIO pins
void setup_gpios() {
    // Initialize GPIO
    if (gpioInit() == -1) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", gpioError());
        exit(EXIT_FAILURE);
    }

    // Set GPIO4, GPIO17, and GPIO27 as inputs with pull-up enabled
    if (gpioMode(GPIO4, GPIO_INPUT_PULLUP) == -1) {
        fprintf(stderr, "Failed to set GPIO4 mode: %s\n", gpioError());
        exit(EXIT_FAILURE);
    }
    if (gpioMode(GPIO17, GPIO_INPUT_PULLUP) == -1) {
        fprintf(stderr, "Failed to set GPIO17 mode: %s\n", gpioError());
        exit(EXIT_FAILURE);
    }
    if (gpioMode(GPIO27, GPIO_INPUT_PULLUP) == -1) {
        fprintf(stderr, "Failed to set GPIO27 mode: %s\n", gpioError());
        exit(EXIT_FAILURE);
    }

    // Verify each GPIO mode and pull-up call
    if (gpioRead(GPIO4) != 1) {
        fprintf(stderr, "GPIO4 mode or pull-up failed.\n");
        exit(EXIT_FAILURE);
    }
    if (gpioRead(GPIO17) != 1) {
        fprintf(stderr, "GPIO17 mode or pull-up failed.\n");
        exit(EXIT_FAILURE);
    }
    if (gpioRead(GPIO27) != 1) {
        fprintf(stderr, "GPIO27 mode or pull-up failed.\n");
        exit(EXIT_FAILURE);
    }
}

// Function to read sensors
void read_sensors() {
    // Read sensor states
    int state_g4 = gpioRead(GPIO4);
    int state_g17 = gpioRead(GPIO17);
    int state_g27 = gpioRead(GPIO27);

    // Log initial state without falsely logging a transition
    if (state_g4 == 1 && state_g17 == 1 && state_g27 == 1) {
        fprintf(stderr, "Initial state logged: No magnet detected on any sensor.\n");
    } else {
        // Log state changes with ISO-8601 timestamp and sensor identifier
        char timestamp[50];
        time_t now = time(NULL);
        char buffer[23];
        strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", localtime(&now));
        fprintf(stderr, "Sensor %c: %d\n", buffer, (state_g4 ? 'G4' : 'G17') : (state_g27 ? 'G27' : 'N/A'));
    }

    // Handle sensor read errors gracefully
    if (state_g4 == -1 || state_g17 == -1 || state_g27 == -1) {
        fprintf(stderr, "Error reading sensor states. Continuing...\n");
    }
}

// Signal handler for SIGINT and SIGTERM
void handle_signal(int signum) {
    // Close the log file
    fclose(stderr);

    // Clean shutdown: call gpioTerminate()
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

// Function to clean up resources
void cleanup() {
    // Close the stderr file stream
    fclose(stderr);

    // Terminate pigpio
    pigpioTerminate();
}

