#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>

#define PI_GPIO_ID 0
#define SI1182_ADDR 0x4A
#define SI1182_PART_ID_REG 0x00
#define SI1182_HW_REV_REG 0x01
#define SI1182_LED_CURRENT_REG 0x3F
#define SI1182_AVERAGING_REG 0x04
#define SI1182_ENABLE_REG 0x01
#define SI1182_HEART_RATE_REG 0x2A

// Function prototypes
void handleSIGINT(int signum);
int i2cWriteWord(uint8_t addr, uint16_t reg, uint16_t value);
int i2cReadWordData(uint8_t addr, uint16_t reg, uint16_t *data);
double rawToBPM(uint16_t raw);
void movingAverage(uint16_t *data, int size, uint16_t *avg);

// Main function
int main() {
    // Initialize pigpio
    if (pigpioSetup(PI_GPIO_ID) == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpioError());
        return EXIT_FAILURE;
    }

    // Open I2C bus 1
    if (pigpioI2COpen(1) == -1) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", pigpioError());
        pigpioTerminate();
        return EXIT_FAILURE;
    }

    // Check if sensor is present and correct
    uint16_t partId;
    uint16_t hwRev;
    if (i2cReadWordData(SI1182_ADDR, SI1182_PART_ID_REG, &partId) != 0) {
        fprintf(stderr, "Failed to read PART_ID: %s\n", pigpioError());
        pigpioI2CClose(1);
        pigpioTerminate();
        return EXIT_FAILURE;
    }
    if (partId != 0x02) {
        fprintf(stderr, "Invalid PART_ID: 0x%04X\n", partId);
        pigpioI2CClose(1);
        pigpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cReadWordData(SI1182_ADDR, SI1182_HW_REV_REG, &hwRev) != 0) {
        fprintf(stderr, "Failed to read HW_REV: %s\n", pigpioError());
        pigpioI2CClose(1);
        pigpioTerminate();
        return EXIT_FAILURE;
    }
    if (hwRev != 0x01) {
        fprintf(stderr, "Invalid HW_REV: 0x%04X\n", hwRev);
        pigpioI2CClose(1);
        pigpioTerminate();
        return EXIT_FAILURE;
    }

    // Configure the sensor
    if (i2cWriteWord(SI1182_ADDR, SI1182_LED_CURRENT_REG, 0x7F) == -1 ||
        i2cWriteWord(SI1182_ADDR, SI1182_AVERAGING_REG, 0x03) == -1 ||
        i2cWriteWord(SI1182_ADDR, SI1182_ENABLE_REG, 0x01) == -1) {
        fprintf(stderr, "Failed to configure sensor: %s\n", pigpioError());
        pigpioI2CClose(1);
        pigpioTerminate();
        return EXIT_FAILURE;
    }

    // Main loop
    uint16_t heartRate;
    FILE *heart_rate_file = fopen("heart_rate.csv", "a+");
    if (heart_rate_file == NULL) {
        fprintf(stderr, "Failed to open heart_rate.csv for appending: %s\n", strerror(errno));
        pigpioI2CClose(1);
        pigpioTerminate();
        return EXIT_FAILURE;
    }

    while (1) {
        // Read heart rate
        if (i2cReadWordData(SI1182_ADDR, SI1182_HEART_RATE_REG, &heartRate) == -1) {
            fprintf(stderr, "Failed to read heart rate: %s\n", pigpioError());
            // Retry after a short delay
            sleep(1);
            continue;
        }

        double bpm = rawToBPM(heartRate);
        movingAverage(&heartRate, 5, &bpm);

        // Validate BPM
        if (bpm < 30 || bpm > 220) {
            fprintf(stderr, "Invalid BPM: %f\n", bpm);
            continue;
        }

        // Log valid reading
        char timestamp[50];
        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
