#include <signal.h>
#include <libgpiod/gpiod.h>
#include <unistd.h>

#define GPIO_NUM 17
#define FLAME_LOG_FILE "flame_log.txt"

volatile sig_atomic_t is_interrupted = 0;

void handle_interrupt(int signum) {
    is_interrupted = 1;
}

int main() {
    // Initialize libgpiod
    if (gpiod_chip_open(GPIOD_CHIP_BCM2835) < 0) {
        perror("Failed to open BCM2835 chip");
        return EXIT_FAILURE;
    }

    // Open GPIO line 17 with internal pull-up
    if (gpiod_line_open(GPIOD_LINE_BCM2835_GPIO17, GPIOD_OPEN_MODE_INPUT_PULLUP) < 0) {
        perror("Failed to open GPIO line 17");
        gpiod_chip_close(GPIOD_CHIP_BCM2835);
        return EXIT_FAILURE;
    }

    // Set up signal handler for SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = handle_interrupt;
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        // Poll GPIO line
        if (gpiod_line_get_value(GPIOD_LINE_BCM2835_GPIO17) == 0) {
            // Falling edge detected (LOW to HIGH)
            printf("FLAME DETECTED\n");
            time_t now = time(NULL);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &now);
            fprintf(stderr, "%s FLAME DETECTED\n", timestamp);
            fprintf(FLAME_LOG_FILE, "%s FLAME DETECTED\n", timestamp);
            fflush(stderr);
            fflush(FLAME_LOG_FILE);
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up on SIGINT/SIGTERM
    if (is_interrupted) {
        // Release GPIO line
        gpiod_line_close(GPIOD_LINE_BCM2835_GPIO17);
        // Close the GPIO chip
        gpiod_chip_close(GPIOD_CHIP_BCM2835);
        // Close the log file
        fclose(FLAME_LOG_FILE);
    }

    return EXIT_SUCCESS;
}

