#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define TOUCH_SENSOR_GPIO_PINS {5, 6, 7, 8, 9, 10, 11, 12} // BCM GPIO numbers
#define OUTPUT_DISPLAY_GPIO {17, 18, 19, 20, 21, 22, 23, 24} // BCM GPIO numbers for counter display
#define TOUCH_SENSOR_LINE_COUNT 8
#define TOUCH_STABILIZATION_MS 200

// Function prototypes
void setup_gpiod();
void handle_signal(int signum);
void read_touch_sensor();
void update_output_display(uint8_t counter);
void log_touch_event(const char *channel, uint8_t counter);
void cleanup();

int main() {
    struct gpiod_chip *chip;
    int rc;

    // Setup GPIO
    setup_gpiod();

    // Handle signals
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Stabilization delay
    usleep(TOUCH_STABILIZATION_MS * 1000);

    uint8_t counter = 0;
    time_t now;
    char touch_log_line[256];

    while (1) {
        // Read touch sensor
        read_touch_sensor();

        // Update counter and display
        update_output_display(counter);

        // Log touch event
        now = time(NULL);
        strftime(touch_log_line, sizeof(touch_log_line), "%F %T", localtime(&now));
        log_touch_event(TOUCH_SENSOR_LINE_COUNT - 1 - counter, counter);

        // Check for Ctrl+C or Ctrl+Z
        if (counter == 0 && (rc = read(STDIN, &counter, 1)) == 1) {
            break;
        }
    }

    // Cleanup
    cleanup();

    return 0;
}

// Function to initialize libgpiod
void setup_gpiod() {
    struct gpiod_chip *chip;
    rc = gpiod_chip_open(&chip, "pico", GPIOD_OPEN_BY_NAME);
    if (rc) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Request lines for TTP226 outputs
    for (int i = 0; i < TOUCH_SENSOR_LINE_COUNT; ++i) {
        struct gpiod_line *line;
        rc = gpiod_chip_request_lines(chip, TOUCH_SENSOR_GPIO_PINS + i);
        if (rc) {
            fprintf(stderr, "Error requesting line %d: %s\n", i, strerror(errno));
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
        line = gpiod_chip_get_line(chip, TOUCH_SENSOR_GPIO_PINS + i);
        rc = gpiod_line_request_get_value(line);
        if (rc) {
            fprintf(stderr, "Error reading line %d: %s\n", i, strerror(errno));
            gpiod_line_release(line);
            gpiod_chip_release_lines(chip, TOUCH_SENSOR_GPIO_PINS + i);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
    }

    // Request lines for output display
    for (int i = 0; i < OUTPUT_DISPLAY_GPIO_COUNT; ++i) {
        struct gpiod_line *line;
        rc = gpiod_chip_request_lines(chip, OUTPUT_DISPLAY_GPIO + i);
        if (rc) {
            fprintf(stderr, "Error requesting line for output display: %s\n", strerror(errno));
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
        line = gpiod_chip_get_line(chip, OUTPUT_DISPLAY_GPIO + i);
        rc = gpiod_line_request_set_value(line, 0); // Set initial value to 0
        if (rc) {
            fprintf(stderr, "Error setting line for output display: %s\n", strerror(errno));
            gpiod_line_release(line);
            gpiod_chip_release_lines(chip, OUTPUT_DISPLAY_GPIO + i);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
    }

    gpiod_chip_close(chip);
}

// Function to handle signals
void handle_signal(int signum) {
    // Reset all output pins to 0
    for (int i = 0; i < OUTPUT_DISPLAY_GPIO_COUNT; ++i) {
        struct gpiod_line *line = gpiod_chip_get_line(gpiod_chip_get_default_chip(), OUTPUT_DISPLAY_GPIO + i);
        rc = gpiod_line_request_set_value(line, 0);
        if (rc) {
            fprintf(stderr, "Error resetting output display GPIO: %s\n", strerror(errno));
        } else {
            gpiod_line_release(line);
        }
    }

    // Release all libgpiod resources
    gpiod_chip_close(gpiod_chip_get_default_chip());

    // Exit cleanly
    exit(EXIT_SUCCESS);
}

// Function to read the touch sensor
void read_touch_sensor() {
    struct gpiod_line *lines[TOUCH_SENSOR_LINE_COUNT];
    uint8_t prev_state[TOUCH_SENSOR_LINE_COUNT];

    // Request lines for reading
    for (int i = 0; i < TOUCH_SENSOR_LINE_COUNT; ++i) {
        lines[i] = gpiod_chip_get_line(gpiod_chip_get_default_chip(), TOUCH_SENSOR_GPIO_PINS + i);
        rc = gpiod_line_request_get_value(lines[i]);
        if (rc) {
            fprintf(stderr, "Error reading line %d: %s\n", i, strerror(errno));
            return;
        }
        prev_state[i] = gpiod_line_get_value(lines[i]);
    }

    // Check for rising edges (inactive-to-active)
    for (int i = 0; i < TOUCH_SENSOR_LINE_COUNT; ++i) {
        if (prev_state[i] && !lines[i]->value) {
            // Rising edge detected
            uint8_t new_channel = TOUCH_SENSOR_LINE_COUNT - 1 - i;
            log_touch_event(TOUCH_SENSOR_LINE_COUNT - 1 - new_channel, counter);
            counter++;
            if (counter == 255) {
                counter = 0;
            }
        }
        prev_state[i] = lines[i]->value;
    }

    // Release lines
    for (int i = 0; i < TOUCH_SENSOR_LINE_COUNT; ++i) {
        gpiod_line_release(lines[i]);
    }
}

// Function to update output display
void update_output_display(uint8_t counter) {
    for (int i = 0; i < OUTPUT_DISPLAY_GPIO_COUNT; ++i) {
        struct gpiod_line *line = gpiod_chip_get_line(gpiod_chip_get_default_chip(), OUTPUT_DISPLAY_GPIO + i);
        rc = gpiod_line_request_set_value(line, counter % 8 + 17);
        if (rc) {
            fprintf(stderr, "Error setting output display GPIO: %s\n", strerror(errno));
        } else {
            gpiod_line_release(line);
        }
    }
}

// Function to log touch event
void log_touch_event(const char *channel, uint8_t counter) {
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%F %T", localtime(&time(NULL)));

    FILE *log_file = fopen("touch_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Warning: Unable to open touch_log.txt for appending.\n");
    } else {
        fprintf(log_file, "%s, Channel: %d, Counter: %u\n", timestamp, channel, counter);
        fclose(log_file);
    }
}

// Function to cleanup resources
void cleanup() {
    // Release all lines and close chip
    for (int i = 0; i < TOUCH_SENSOR_LINE_COUNT; ++i) {
        gpiod_line_release(gpiod_chip_get_line(gpiod_chip_get_default_chip(), TOUCH_SENSOR_GPIO_PINS + i));
    }
    gpiod_chip_close(gpiod_chip_get_default_chip());
}

