    // Check for rising edges (inactive-to-active)
    for (int i = 0; i < TOUCH_SENSOR_LINE_COUNT; ++i) {
        if (prev_state[i] && !lines[i]->value) {
            // Rising edge detected
            uint8_t new_channel = TOUCH_SENSOR_LINE_COUNT - 1 - i;
            log_touch_event(TOUCH_SENSOR_LINE_COUNT - 1 - new_channel, counter);
            counter++;
            if (counter == 255) {
                counter = 0;
            }
        }
        prev_state[i] = lines[i]->value;
    }

    // Release lines
    for (int i = 0; i < TOUCH_SENSOR_LINE_COUNT; ++i) {
        gpiod_line_release(lines[i]);
    }
}

// Function to update output display
void update_output_display(uint8_t counter) {
    for (int i = 0; i < OUTPUT_DISPLAY_GPIO_COUNT; ++i) {
        struct gpiod_line *line = gpiod_chip_get_line(gpiod_chip_get_default_chip(), OUTPUT_DISPLAY_GPIO + i);
        rc = gpiod_line_request_set_value(line, counter % 8 + 17);
        if (rc) {
            fprintf(stderr, "Error setting output display GPIO: %s\n", strerror(errno));
        } else {
            gpiod_line_release(line);
        }
    }
}

// Function to log touch event
void log_touch_event(const char *channel, uint8_t counter) {
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%F %T", localtime(&time(NULL)));

    FILE *log_file = fopen("touch_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Warning: Unable to open touch_log.txt for appending.\n");
    } else {
        fprintf(log_file, "%s, Channel: %d, Counter: %u\n", timestamp, channel, counter);
        fclose(log_file);
    }
}

// Function to cleanup resources
void cleanup() {
    // Release all lines and close chip
    for (int i = 0; i < TOUCH_SENSOR_LINE_COUNT; ++i) {
        gpiod_line_release(gpiod_chip_get_line(gpiod_chip_get_default_chip(), TOUCH_SENSOR_GPIO_PINS + i));
    }
    gpiod_chip_close(gpiod_chip_get_default_chip());
}

