#include <csv.h>

#define GPIO_NUM_17  17
#define GPIO_NUM_18  18
#define GPIO_NUM_27  27
#define GPIO_NUM_22  22

#define SENSORS_COUNT 4

const char *sensor_pins[] = { "GPIO17", "GPIO18", "GPIO27", "GPIO22" };

int main() {
    // Initialize libgpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod: %s\n", gpiod_errstr(gpiod_get_error()));
        return EXIT_FAILURE;
    }

    // Open the GPIO lines in input mode
    for (int i = 0; i < SENSORS_COUNT; ++i) {
        const char *pin_name = sensor_pins[i];
        int gpio_num = GPIO_NUM_*(pin_name);

        if (gpiod_line_request_input(gpio_num) < 0) {
            fprintf(stderr, "Failed to configure GPIO %s as input: %s\n", pin_name, gpiod_errstr(gpiod_get_error()));
            continue;
        }
    }

    // Open CSV file for writing
    FILE *csv_file = fopen("tracking_log.csv", "a");
    if (!csv_file) {
        fprintf(stderr, "Failed to open CSV file for writing: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Header row if the file is new
    if (fseek(csv_file, 0, SEEK_SET) == 0 && feof(csv_file) == 0) {
        fprintf(csv_file, "timestamp,sensor1,sensor2,sensor3,sensor4\n");
    }

    // Main loop
    while (1) {
        // Poll sensors
        for (int i = 0; i < SENSORS_COUNT; ++i) {
            int value = 0;
            if (gpiod_line_get_value(sensor_pins[i]) < 0) {
                fprintf(stderr, "Failed to read value from GPIO %s: %s\n", sensor_pins[i], gpiod_errstr(gpiod_get_error()));
                continue;
            }
            value = gpiod_line_get_value(sensor_pins[i]) ? 1 : 0;
        }

        // Timestamp and write to CSV
        time_t timestamp = time(NULL);
        struct tm *timeinfo = localtime(&timestamp);
        char timestamp_str[50];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        fprintf(csv_file, "%s,%d,%d,%d,%d\n", timestamp_str, value, value, value, value);

        // Flush the file to prevent data loss on abrupt termination
        fflush(csv_file);
    }

    // Handle SIGINT and SIGTERM
    if (signal(SIGINT, SIG_IGN) == SIG_ERR) {
        fprintf(stderr, "Failed to ignore SIGINT: %s\n", strerror(errno));
    }
    if (signal(SIGTERM, SIG_IGN) == SIG_ERR) {
        fprintf(stderr, "Failed to ignore SIGTERM: %s\n", strerror(errno));
    }

    // Clean up on exit
    for (int i = 0; i < SENSORS_COUNT; ++i) {
        gpiod_line_release(sensor_pins[i]);
    }
    gpiod_exit();

    // Close the CSV file
    fclose(csv_file);

    return EXIT_SUCCESS;
}

