void setup_tilt_sensors() {
    struct gpiod_chip *chip;
    struct gpiod_pin *pin1, *pin2;

    chip = gpiod_chip_get(GPIOD_CHIPS_RASPBERRY_PI_5);

    // Request GPIO lines with active-low pull-up
    pin1 = gpiod_pin_request(chip, SENSOR_1_GPIO, GPIOD_PIN_INPUT | GPIOD_PIN_PULL_UP);
    if (pin1 == NULL) {
        fprintf(stderr, "Failed to request GPIO %d.\n", SENSOR_1_GPIO);
        gpiod_chip_close(chip);
        return;
    }

    pin2 = gpiod_pin_request(chip, SENSOR_2_GPIO, GPIOD_PIN_INPUT | GPIOD_PIN_PULL_UP);
    if (pin2 == NULL) {
        fprintf(stderr, "Failed to request GPIO %d.\n", SENSOR_2_GPIO);
        gpiod_pin_free(pin1);
        gpiod_chip_close(chip);
        return;
    }

    // Enable interrupts for edge detection
    gpiod_pin_set_mode(pin1, GPIOD_PIN_MODE_INT_EDGE_RISING);
    gpiod_pin_set_mode(pin2, GPIOD_PIN_MODE_INT_EDGE_RISING);
}

