    struct gpiod_event *events[2];

    events[0] = gpiod_pin_get_events(pin1, &timeout);
    events[1] = gpiod_pin_get_events(pin2, &timeout);

    if (events[0] && events[0]->flags & GPIOD_EVENT_INT) {
        handle_tilt_event(1);
    }

    if (events[1] && events[1]->flags & GPIOD_EVENT_INT) {
        handle_tilt_event(2);
    }

    gpiod_event_free(events[0]);
    gpiod_event_free(events[1]);
