#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <gpiod.h>

#define GPIO17 17
#define GPIO27 27
#define GPIO22 22

// Function prototypes
void setup_gpios(void);
void read_sensors_and_handle_led(int sensor1, int sensor2);
void handle_sigint(int signum);
void cleanup(void);

int main(void) {
    srand(time(NULL));

    // Setup GPIOs
    setup_gpios();

    // Main loop
    while (1) {
        read_sensors_and_handle_led(GPIO_READ(sensor GPIO17), GPIO_READ(sensor GPIO27));
        usleep(100000); // 100 ms delay
    }

    // Graceful shutdown on SIGINT
    handle_sigint(SIGINT);

    // Cleanup
    cleanup();

    return 0;
}

// Function to initialize GPIOs
void setup_gpios(void) {
    struct gpiod_chip *chip;
    struct gpiod_dir *dir;
    struct gpiod_pad *pad;

    chip = gpiod_chip_open("gpiochip0", GPIOD_OPEN_READONLY);
    if (chip == NULL) {
        fprintf(stderr, "Error: GPIO chip 'gpiochip0' not found\n");
        exit(EXIT_FAILURE);
    }

    // Initialize GPIOs as inputs
    for (int i = GPIO17; i <= GPIO27; i++) {
        dir = gpiod_dir_request(chip, i, GPIOD_DIR_IN);
        if (dir == NULL) {
            fprintf(stderr, "Error: Failed to request direction for GPIO %d\n", i);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
        pad = gpiod_pad_request(dir);
        if (pad == NULL) {
            fprintf(stderr, "Error: Failed to request pad for GPIO %d\n", i);
            gpiod_dir_release(dir);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
    }

    // Initialize GPIO as output
    dir = gpiod_dir_request(chip, GPIO22, GPIOD_DIR_OUT_LOW);
    if (dir == NULL) {
        fprintf(stderr, "Error: Failed to request direction for GPIO %d\n", GPIO22);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    pad = gpiod_pad_request(dir);
    if (pad == NULL) {
        fprintf(stderr, "Error: Failed to request pad for GPIO %d\n", GPIO22);
        gpiod_dir_release(dir);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_pad_config(pad, GPIOD_PIN_OUTPUT_LOW);
    gpiod_pad_release(pad);
    gpiod_dir_release(dir);
}

// Function to read sensors and handle LED state
void read_sensors_and_handle_led(int sensor1, int sensor2) {
    int led_state = 0; // LED off initially

    if (sensor1 == 0 && sensor2 == 0) {
        led_state = 1; // LED on when both sensors detect an obstacle
    }

    // Log data
    char timestamp[50];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    char log_line[256] = "{\"timestamp\":\"" "\"%s\", \"sensor1\":%d, \"sensor2\":%d, \"led_state\":%d}", timestamp, sensor1, sensor2, led_state);

    FILE *log_file = fopen("obstacle_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open 'obstacle_log.csv' for appending\n");
        return;
    }

    fprintf(log_file, "%s", log_line);
    fprintf(log_file, "\n");
    fclose(log_file);

    // Reset LED state for next iteration
    led_state = 0;
}

// Function to handle SIGINT (Ctrl+C)
void handle_sigint(int signum) {
    // Turn off the LED
    gpiod_set_value(GPIO22, 0);

    // Release all line resources
    for (int i = GPIO17; i <= GPIO27; i++) {
        gpiod_pad_release(gpiod_pad_request(gpiod_dir_request(gpiod_chip_open("gpiochip0", GPIOD_OPEN_READONLY), i, GPIOD_DIR_IN)));
    }
    gpiod_pad_release(gpiod_pad_request(gpiod_dir_request(gpiod_chip_open("gpiochip0", GPIOD_OPEN_READONLY), GPIO22, GPIOD_DIR_OUT_LOW)));

    // Close the chip
    gpiod_chip_close(gpiod_chip_open("gpiochip0", GPIOD_OPEN_READONLY));

    // Close the log file
    fclose("obstacle_log.csv");
}

// Function to cleanup resources
void cleanup(void) {
    // Close the log file
    fclose("obstacle_log.csv");

    // Release GPIO resources
    gpiod_chip_close(gpiod_chip_open("gpiochip0", GPIOD_OPEN_READONLY));
}

