void setup_gpios(void) {
    // Check if GPIO library initialization fails
    if (gpiod_init() < 0) {
        perror("gpiod_init");
        exit(EXIT_FAILURE);
    }

    // Iterate over each GPIO pin
    for (int i = 0; i < 3; i++) {
        // Open GPIO pin
        int gpio = (i == 0 ? GPIO_LEFT : (i == 1 ? GPIO_CENTER : GPIO_RIGHT));
        if (gpiod_open(gpio) < 0) {
            perror("gpiod_open");
            exit(EXIT_FAILURE);
        }

        // Configure GPIO pin as active-low with pull-up
        if (gpiod_direction_input(gpio, GPIO_ACTIVE_LOW | GPIO_PULL_UP) < 0) {
            perror("gpiod_direction_input");
            gpiod_close(gpio);
            exit(EXIT_FAILURE);
        }

        // Close the GPIO pin after configuration
        gpiod_close(gpio);
    }
}

