        if (gpiod_open(gpio) < 0) {
            perror("gpiod_open");
            return;
        }

        // Read the GPIO value
        int value = gpiod_get_value(gpio);
        gpiod_close(gpio);

        // Print the sensor state
        if (value) {
            printf("Sensor %d: High (IR not detected)\n", i + 1);
        } else {
            printf("Sensor %d: Low (IR detected)\n", i + 1);
        }
    }
}

