    // Close all open GPIO devices
    for (int i = 0; i < 3; i++) {
        int gpio = (i == 0 ? GPIO_LEFT : (i == 1 ? GPIO_CENTER : GPIO_RIGHT));
        if (gpiod_open(gpio) >= 0) {
            gpiod_close(gpio);
        }
    }

    // Final cleanup after all GPIO operations
    gpiod_exit();
}

// Signal handler to gracefully exit on SIGINT or SIGTERM
void handle_signal(int signum) {
    // Clean up GPIOs
    cleanup_gpios();

    // Exit the program
    exit(EXIT_SUCCESS);
}

