#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_BUS_NUM 1
#define SI1175_ADDR 0x49
#define ALS_VISIBLE_LSB_REG 0x24
#define ALS_VISIBLE_MSB_REG 0x25

volatile sig_atomic_t should_exit = 0;

void handle_signal(int signum) {
    should_exit = 1;
}

int main() {
    int fd;
    unsigned int raw_value;
    struct i2c_msg msg[2];

    // Open the I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd == -1) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Initialize I2C control block
    memset(&i2c_smbus, 0, sizeof(i2c_smbus));
    i2c_smbus.mode = I2C_SMBUS_BLOCK_TRANSFER;

    // Prepare I2C messages
    msg[0].addr = SI1175_ADDR;
    msg[0].len = sizeof(unsigned int);
    msg[0].buf = &raw_value;

    msg[1].addr = SI1175_ADDR;
    msg[1].len = sizeof(unsigned int);
    msg[1].buf = &raw_value;

    while (!should_exit) {
        // Write to LSB register
        if (ioctl(fd, I2C_SMBUS_WRITE, msg[0]) < 0) {
            perror("Failed to write to LSB register");
            break;
        }

        // Read from LSB register
        if (ioctl(fd, I2C_SMBUS_READ, &msg[0]) < 0) {
            perror("Failed to read from LSB register");
            break;
        }

        raw_value = msg[0].buf[0];

        // Write to MSB register
        if (ioctl(fd, I2C_SMBUS_WRITE, msg[1]) < 0) {
            perror("Failed to write to MSB register");
            break;
        }

        // Read from MSB register
        if (ioctl(fd, I2C_SMBUS_READ, &msg[1]) < 0) {
            perror("Failed to read from MSB register");
            break;
        }

        raw_value = (raw_value << 8) | msg[1].buf[0];

        // Print raw value
        printf("Raw heart rate: 0x%X\n", raw_value);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Close the I2C device
    if (fd > 0) {
        close(fd);
    }

    return EXIT_SUCCESS;
}

