#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

// Function prototypes
void handle_signal(int signum);

int main() {
    // Signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, handle_signal);

    // Attempt to open the GPIO chip
    struct gpiod_chip *chip;
    int ret = gpiod_chip_open_default(&chip, "bcm2835-gpio", GPIOD_OPEN_BY_NAME);
    if (ret < 0) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", gpiod_strerror(ret));
        return EXIT_FAILURE;
    }

    // GPIO lines for Keywish 3-Way Tracking Sensor
    int left_pin = 2;
    int middle_pin = 3;
    int right_pin = 4;

    // Polling loop
    while (1) {
        // Request input lines
        ret = gpiod_line_request_input(chip, left_pin, GPIOD_LINE_REQUEST_INPUT);
        if (ret < 0) {
            fprintf(stderr, "Error requesting input on left pin: %s\n", gpiod_strerror(ret));
            break;
        }

        ret = gpiod_line_request_input(chip, middle_pin, GPIOD_LINE_REQUEST_INPUT);
        if (ret < 0) {
            fprintf(stderr, "Error requesting input on middle pin: %s\n", gpiod_strerror(ret));
            break;
        }

        ret = gpiod_line_request_input(chip, right_pin, GPIOD_LINE_REQUEST_INPUT);
        if (ret < 0) {
            fprintf(stderr, "Error requesting input on right pin: %s\n", gpiod_strerror(ret));
            break;
        }

        // Read line values
        uint8_t left_value = gpiod_line_get_value(chip, left_pin);
        uint8_t middle_value = gpiod_line_get_value(chip, middle_pin);
        uint8_t right_value = gpiod_line_get_value(chip, right_pin);

        // Output sensor values
        printf("L:%s M:%s R:%s\n", left_value ? "1" : "0", middle_value ? "1" : "0", right_value ? "1" : "0");

        // Release lines
        gpiod_line_release(chip, left_pin);
