    int lines[8] = {5, 6, 13, 19, 26, 12, 16, 20};
    for (int i = 0; i < 8; ++i) {
        int ret = gpiod_line_request_direction(chip, lines[i], GPIOD_DIRECTION_INPUT);
        if (ret < 0) {
            fprintf(stderr, "Error requesting line %d as input: %s\n", lines[i], gpiod_error_string());
            gpiod_chip_free(chip);
            return 1;
        }
    }

    // Main loop
    while (1) {
        // Get current monotonic time
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);

        // Format and print channel states
        char buffer[256];
        sprintf(buffer, "[%ld.s] CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d",
                (long)ts.tv_sec * 1000000 + ts.tv_nsec / 1000,
                gpiod_line_get_value(chip, lines[0]) ? 1 : 0,
                gpiod_line_get_value(chip, lines[1]) ? 1 : 0,
                gpiod_line_get_value(chip, lines[2]) ? 1 : 0,
                gpiod_line_get_value(chip, lines[3]) ? 1 : 0,
                gpiod_line_get_value(chip, lines[4]) ? 1 : 0,
                gpiod_line_get_value(chip, lines[5]) ? 1 : 0,
                gpiod_line_get_value(chip, lines[6]) ? 1 : 0,
                gpiod_line_get_value(chip, lines[7]) ? 1 : 0);

        // Print to stdout
        printf("%s\n", buffer);

        // Sleep for 200ms
        usleep(200000);
    }

    // Release all resources on exit
    gpiod_chip_free(chip);
    gpiod_exit();

    return 0;
}

