#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_RED   17
#define GPIO_GREEN 18
#define GPIO_BLUE  27

#define PWM_FREQ  1000
#define INTERPOLATION_STEPS 50

// Function to convert HSV to RGB
void hsvToRgb(float h, float s, float v, int16_t *r, int16_t *g, int16_t *b) {
    float c = v * s;
    float x = c * (1 - abs((h / 60) - int(h / 60)));
    float m = v - c * abs((h / 60) - int(h / 60));

    *r = int(c * (1.0f * (h / 60.0f) + x));
    *g = int(c * (1.0f - (h / 60.0f)) + x);
    *b = int(m * (1.0f + x));
}

// Main function
int main() {
    // Initialize syslog
    openlog("mood_lamp", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    pigpio *pi = NULL;
    if (pigpio_init() == -1) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        return EXIT_FAILURE;
    }
    pi = pigpio_new();

    if (pi == NULL) {
        syslog(LOG_ERR, "Failed to create pigpio instance");
        pigpio_free(pi);
        return EXIT_FAILURE;
    }

    // Set GPIO modes for PWM
    int red_mode = gpioSetMode(GPIO_RED, GPIO_MODE_PWM1);
    int green_mode = gpioSetMode(GPIO_GREEN, GPIO_MODE_PWM1);
    int blue_mode = gpioSetMode(GPIO_BLUE, GPIO_MODE_PWM1);

    if (red_mode == -1 || green_mode == -1 || blue_mode == -1) {
        syslog(LOG_ERR, "Failed to set GPIO modes for PWM");
        pigpio_free(pi);
        return EXIT_FAILURE;
    }

    // Seed random number generator with /dev/urandom
    int fd = open("/dev/urandom", O_RDONLY);
    if (fd == -1) {
        syslog(LOG_ERR, "Failed to open /dev/urandom");
        close(fd);
        pigpio_free(pi);
        return EXIT_FAILURE;
    }
    srand(fd);

    // Signal handlers
    struct sigaction int_handler, term_handler;
    sigemptyset(&int_handler.sa_mask);
    int_handler.sa_handler = SIG_IGN;
    sigaction(SIGINT, &int_handler, NULL);
    sigemptyset(&term_handler.sa_mask);
    term_handler.sa_handler = cleanup;
    sigaction(SIGTERM, &term_handler, NULL);

    // Main loop
    while (1) {
        // Random hue selection
        float h = (float)rand() / (float)RAND_MAX * 360.0;
        h = fmod(h, 1.0) * 360.0; // Clamp to [0, 1)
        float s = 1.0; // Full saturation
        float v = 1.0; // Full value

        // Convert hue to RGB
        int16_t r, g, b;
        hsvToRgb(h, s, v, &r, &g, &b);

        // Invert duty cycles for common-anode LED
        int red_duty = 255 - r;
        int green_duty = 255 - g;
        int blue_duty = 255 - b;

        // Apply 50-step linear interpolation
        int red_interpolated = (red_duty + (INTERPOLATION_STEPS * (rand() % 101 - 50))) / INTERPOLATION_STEPS;
        int green_interpolated = (green_duty + (INTERPOLATION_STEPS * (rand() % 101 - 50))) / INTERPOLATION_STEPS;
        int blue_interpolated = (blue_duty + (INTERPOLATION_STEPS * (rand() % 101 - 50))) / INTERPOLATION_STEPS;

        // Ensure values are within [0, 255]
        red_interpolated = clamp(red_interpolated, 0, 255);
        green_interpolated = clamp(green_interpolated, 0, 255);
        blue_interpolated = clamp(blue_interpolated, 0, 255);

        // Set PWM duty cycles
        gpioWritePWM(GPIO_RED, red_interpolated);
        gpioWritePWM(GPIO_GREEN, green_interpolated);
        gpioWritePWM(GPIO_BLUE, blue_interpolated);

        // Sleep for 5 seconds
        usleep(5000000);
    }

    // Cleanup on SIGINT or SIGTERM
    void cleanup() {
        // Turn off the LED
        gpioWritePWM(GPIO_RED, 0);
        gpioWritePWM(GPIO_GREEN, 0);
        gpioWritePWM(GPIO_BLUE, 0);

        // Release resources
        pigpio_free(pi);

        // Close syslog
        closelog();
    }

    return EXIT_SUCCESS;
}

// Helper function to clamp value within a range
int clamp(int value, int min, int max) {
    return value > max ? max : (value < min ? min : value);
}

