        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpiod_close(gpio_fd);
        return EXIT_FAILURE;
    }

    // Power on the sensor
    buf[0] = PON_REG;
    buf[1] = 1;
    status = write(i2c_fd, buf, 2);
    if (status != 2) {
        fprintf(stderr, "Error powering on sensor: %s\n", strerror(errno));
        close(i2c_fd);
        gpiod_close(gpio_fd);
        return EXIT_FAILURE;
    }

    // Enable RGBC mode
    buf[0] = AEN_REG;
    buf[1] = 0x01;
    status = write(i2c_fd, buf, 2);
    if (status != 2) {
        fprintf(stderr, "Error enabling RGBC mode: %s\n", strerror(errno));
        close(i2c_fd);
        gpiod_close(gpio_fd);
        return EXIT_FAILURE;
    }

    // Set integration time to approximately 154 ms (ATIME=0x00)
    buf[0] = ATIME_REG;
    buf[1] = 0x00;
    status = write(i2c_fd, buf, 2);
    if (status != 2) {
        fprintf(stderr, "Error setting integration time: %s\n", strerror(errno));
        close(i2c_fd);
        gpiod_close(gpio_fd);
        return EXIT_FAILURE;
    }

    // Set gain to 1x (CONTROL=0x00)
    buf[0] = CONTROL_REG;
    buf[1] = 0x00;
    status = write(i2c_fd, buf, 2);
    if (status != 2) {
        fprintf(stderr, "Error setting gain: %s\n", strerror(errno));
        close(i2c_fd);
        gpiod_close(gpio_fd);
        return EXIT_FAILURE;
    }

    // Verify sensor ID
    buf[0] = SENSOR_ID_REG;
    status = read(i2c_fd, buf, 1);
    if (status != 1 || buf[0] != 0x44) {
        fprintf(stderr, "Sensor ID verification failed: %s\n", strerror(errno));
        close(i2c_fd);
        gpiod_close(gpio_fd);
        return EXIT_FAILURE;
    }

    // Read channel values
    buf[0] = CLEAR_CHANNEL_REG;
    status = read(i2c_fd, buf, 1);
    clear = (buf[0] << 8) | buf[1];
    buf[0] = RED_CHANNEL_REG;
    status = read(i2c_fd, buf, 1);
    red = (buf[0] << 8) | buf[1];
    buf[0] = GREEN_CHANNEL_REG;
    status = read(i2c_fd, buf, 1);
    green = (buf[0] << 8) | buf[1];
    buf[0] = BLUE_CHANNEL_REG;
    status = read(i2c_fd, buf, 1);
    blue = (buf[0] << 8) | buf[1];

    // Apply calibration and display values
    printf("Clear: %d, Red: %d, Green: %d, Blue: %d\n", clear, red, green, blue);

    // Poll the sensor every 200 ms
    while (1) {
        usleep(200000);

        // Check red value and control LED
        if (red > threshold) {
            gpio_set_value(gpio_fd, GPIO17, 1);
        } else {
            gpio_set_value(gpio_fd, GPIO17, 0);
        }
    }

    // Clean up resources
    gpio_set_value(gpio_fd, GPIO17, 0); // Turn off LED
    gpiod_close(gpio_fd); // Release GPIO
    close(i2c_fd); // Release I2C

    return EXIT_SUCCESS;
}
