    // Wait for approximately 180 ms
    struct timespec timeout = { .tv_sec = 0, .tv_nsec = 180000000 };
    if (nanosleep(&timeout, NULL) == -1) {
        fprintf(stderr, "Failed to wait for BH1750: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

// Function to handle brightness based on lux readings
void handle_brightness(int lux) {
    // Implement a logarithmic mapping for brightness
    // Example mapping: brightness = log2(lux + 1) * 255 / log2(1000 + 1)
    int mapped_brightness = (int)(log2(lux + 1) * 255 / log2(1000 + 1));

