    // Convert raw data to lux
    uint16_t raw_data = (wiringPiI2CRead(BH1750_ADDRESS, 0x00, 1) << 8) | wiringPiI2CRead(BH1750_ADDRESS, 0x00, 0);
    int lux = (raw_data >> 8) * 0.125; // BH1750 datasheet specifies a scaling factor of 1/8

    // Handle I2C errors and retry if necessary
    if (lux == 0) {
        fprintf(stderr, "Failed to read light level from BH1750, retrying...\n");
        sleep(1); // Simple retry mechanism
        read_bh1750_light();
    }
}

