#define I2C_DEVICE "/dev/i2c-1"

// BH1750 register addresses
#define BH1750_REG_HIGH_RES_CMD 0x20
#define BH1750_REG_DATA_H 0x00
#define BH1750_REG_DATA_L 0x01

// BH1750 to lux conversion factor
#define BH1750_TO_LUX_FACTOR 1.2

// APA102 LED strip control constants
#define APA102_START_FRAME 0xE0
#define APA102_END_FRAME 0xFF
#define APA102_LEDS_PER_STRIP 32

// Global variables
int spi_fd;
int i2c_fd;
uint8_t bh1750_data[2];
int lux;
uint8_t apa102_brightness[APA102_LEDS_PER_STRIP];

void setup_io() {
    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd == -1) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C device");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
}

void cleanup_io() {
    close(spi_fd);
    close(i2c_fd);
}

void handle_signal(int signum) {
    // Catch SIGINT and clean up
    printf("SIGINT received, shutting down...\n");
    cleanup_io();
    exit(EXIT_SUCCESS);
}

void initialize_bh1750() {
    uint8_t cmd = BH1750_REG_HIGH_RES_CMD;
    write(i2c_fd, &cmd, 1);
    usleep(120000); // Wait approximately 120 ms for conversion
    read(i2c_fd, bh1750_data, 2);
}

void read_lux() {
    lux = (bh1750_data[0] << 8) | bh1750_data[1];
    lux *= BH1750_TO_LUX_FACTOR;
    printf("Measured lux: %d\n", lux);
}

