    for (int i = 0; i < APA102_LEDS_PER_STRIP; ++i) {
        apa102_brightness[i] = (uint8_t)(brightness * 31 / 300.0 + 0.5);
    }
    // Send APA102 frames
    for (int i = 0; i < APA102_LEDS_PER_STRIP; ++i) {
        uint32_t frame = APA102_START_FRAME | (apa102_brightness[i] << 8) | 0x00 | 0x00;
        write(spi_fd, &frame, 4);
    }
    write(spi_fd, &APA102_END_FRAME, 1);
}

