    setup_io();
    signal(SIGINT, handle_signal);

    initialize_bh1750();

    while (1) {
        read_lux();
        set_apa102_brightness(lux / 300.0);
        usleep(100000); // Sleep for 100 ms
    }

    return 0;
}

