#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <wiringPiI2C.h>

// Define constants
#define PIGPIO_ID 0  // Use the default pigpio instance
#define BH1750_LOW_ADDR 0x23
#define BH1750_HIGH_ADDR 0x5C
#define APA102_SPI_PORT 0  // SPI port on Raspberry Pi 3 Model B+
#define APA102_CS_PIN 18   // GPIO 18 as Chip Select for APA102
#define APA102_MOSI_PIN 10 // GPIO 10 as MOSI
#define APA102_SCLK_PIN 11 // GPIO 11 as SCLK

// Function prototypes
void setup_pigpio();
void setup_spi();
void setup_i2c();
void handle_signal(int signum);
void read_bh1750_lux(int addr);
void calculate_brightness(int lux);
void set_apa102_brightness(uint8_t brightness);
void fade_apa102(uint8_t target_brightness, uint8_t current_brightness);

int main() {
    // Initialize pigpio
    setup_pigpio();

    // Set up SPI
    setup_spi();

    // Set up I2C
    setup_i2c();

    // Signal handler for SIGINT
    signal(SIGINT, handle_signal);

    uint8_t avg_lux = 0;
    uint8_t current_brightness = 31; // Start at full brightness

    while (1) {
        // Read lux from BH1750 sensors
        avg_lux = read_bh1750_lux(BH1750_LOW_ADDR);
        if (avg_lux != 0) {
            avg_lux += read_bh1750_lux(BH1750_HIGH_ADDR);
        }

        // Calculate and set brightness
        calculate_brightness(avg_lux);
        set_apa102_brightness(current_brightness);

        // Fade to new brightness
        fade_apa102(current_brightness, current_brightness);

        // Delay for 100 ms
        usleep(100000);
    }

    // Clean up on exit
    handle_signal(SIGINT);

    return 0;
}

// SIGINT handler
void handle_signal(int signum) {
    printf("Received SIGINT, cleaning up...\n");
    // Turn off APA102 strip
    pigpio_write(APA102_CS_PIN, 0);

    // Close I2C handles
    i2c_close();

    // Close SPI handle
    spi_close();

    // Stop pigpio
    pigpio_stop();

    exit(0);
}

// Function to initialize pigpio
void setup_pigpio() {
    if (pi_pigpio_init() == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_errstr());
        exit(EXIT_FAILURE);
    }
}

// Function to setup SPI
void setup_spi() {
    if (wiringPiSPISetup(PIGPIO_ID, APA102_SPI_PORT, SPI_MODE0) == -1) {
        fprintf(stderr, "Failed to setup SPI: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

// Function to setup I2C
void setup_i2c() {
    if (wiringPiI2CSetup(1) == -1) {
        fprintf(stderr, "Failed to setup I2C: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

// Function to read lux from BH1750 at given address
int read_bh1750_lux(int addr) {
    uint8_t data1, data2;
    int lux;

    // Send One-Time High-Resolution Mode 2 command (0x21)
    if (wiringPiI2CWrite(addr, 0x21) != 2) {
        fprintf(stderr, "Failed to write to BH1750 at address 0x%X: %s\n", addr, wiringPiI2CGetErrorStr());
        return 0; // Return 0 if sensor is not present
    }

    // Read two bytes of data
    if (wiringPiI2CRead(addr, 2, &data1, &data2) != 2) {
        fprintf(stderr, "Failed to read from BH1750 at address 0x%X: %s\n", addr, wiringPiI2CGetErrorStr());
        return 0; // Return 0 if sensor is not present
    }

    // Calculate lux from the two bytes
    lux = (data1 << 8) | data2;
    return lux;
}

// Function to calculate brightness based on average lux
void calculate_brightness(int lux) {
    // Map lux to brightness (0-31)
    // This is a simplistic mapping; adjust as needed
    uint8_t brightness = 31 - (lux * 2); // Lower light -> higher brightness
    if (brightness < 0) brightness = 0; // Ensure brightness is non-negative
}

// Function to set APA102 strip brightness
void set_apa102_brightness(uint8_t brightness) {
    if (pigpio_write(APA102_SCLK_PIN, 0) == -1 || pigpio_write(APA102_MOSI_PIN, 0) == -1) {
        fprintf(stderr, "Failed to set APA102 pins: %s\n", pigpio_errstr());
        return;
    }

    // Send brightness command
    pigpio_write(APA102_CS_PIN, 1);
    pigpio_write(0, brightness); // Set brightness
    pigpio_write(APA102_CS_PIN, 0);
}

// Function to fade APA102 strip brightness
void fade_apa102(uint8_t target_brightness, uint8_t current_brightness) {
    // Calculate steps needed to reach target brightness
    uint8_t steps = target_brightness - current_brightness;

    // Fade over 500 ms
    for (uint8_t i = 0; i < steps; i++) {
        // Smoothly increase brightness
