void setup_gpios() {
    int ret;

    // Initialize GPIO lines
    ret = gpiod_open(GPIOD, "gpiochip-bcm2708", GPIOD_OPEN_RWS);
    if (ret < 0) {
        fprintf(stderr, "Failed to open GPIO: %s\n", gpiod_error_string(ret));
        exit(EXIT_FAILURE);
    }

    ret = gpiod_request_line(GPIO4, GPIOD_LINE_IN, GPIOD_DIR_IN);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO4: %s\n", gpiod_error_string(ret));
        gpiod_release_line(GPIO4);
        gpiod_close(GPIOD);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_request_line(GPIO17, GPIOD_LINE_OUT_LOW, GPIOD_DIR_OUT_LOW);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO17: %s\n", gpiod_error_string(ret));
        gpiod_release_line(GPIO17);
        gpiod_release_line(GPIO4);
        gpiod_close(GPIOD);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_request_line(GPIO18, GPIOD_LINE_OUT, GPIOD_DIR_OUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO18: %s\n", gpiod_error_string(ret));
        gpiod_release_line(GPIO18);
        gpiod_release_line(GPIO17);
        gpiod_release_line(GPIO4);
        gpiod_close(GPIOD);
        exit(EXIT_FAILURE);
    }

    // Set initial states
    ret = gpiod_write(GPIO4, 0); // Set flame sensor input to LOW for self-test
    if (ret < 0) {
        fprintf(stderr, "Failed to write to GPIO4: %s\n", gpiod_error_string(ret));
        gpiod_release_line(GPIO4);
        gpiod_release_line(GPIO18);
        gpiod_release_line(GPIO17);
        gpiod_close(GPIOD);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_write(GPIO17, 0); // Set buzzer output to LOW
    if (ret < 0) {
        fprintf(stderr, "Failed to write to GPIO17: %s\n", gpiod_error_string(ret));
        gpiod_release_line(GPIO17);
        gpiod_release_line(GPIO4);
        gpiod_release_line(GPIO18);
        gpiod_close(GPIOD);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_write(GPIO18, 1); // Set LED output to HIGH
    if (ret < 0) {
        fprintf(stderr, "Failed to write to GPIO18: %s\n", gpiod_error_string(ret));
        gpiod_release_line(GPIO18);
        gpiod_release_line(GPIO17);
        gpiod_release_line(GPIO4);
        gpiod_close(GPIOD);
        exit(EXIT_FAILURE);
    }
}

void self_test() {
    int i;
    struct timespec ts;

    // Blink LED twice for self-test
    for (i = 0; i < 2; i++) {
        clock_gettime(CLOCK_REALTIME, &ts);
        ts.tv_sec += SELF_TEST_BLINK_TIME_MS / 1000;
        ts.tv_nsec += (SELF_TEST_BLINK_TIME_MS % 1000) * 1000000;
        gpiod_write(GPIO18, 1); // Turn LED on
        usleep(ts.tv_sec * 1000000 + ts.tv_nsec);
        gpiod_write(GPIO18, 0); // Turn LED off
        usleep(SELF_TEST_BLINK_TIME_MS / 2);
    }

    // Read flame sensor 5 times with 100 ms interval
    for (i = 0; i < 5; i++) {
        gpiod_read(GPIO4, &value);
        if (value == 0) {
            printf("Flame detected at %s\n", ctime(&ts));
            break;
        }
        usleep(100 * 1000);
    }

    // If all reads were LOW, treat it as a sensor fault
    if (i == 5) {
        printf("Sensor fault detected. Self-test failed.\n");
        self_test_failed_signal_handler(SIGINT); // Signal self-test failure
    } else {
        printf("Self-test passed.\n");
    }
}

int main() {
    setup_gpios();

    // Install signal handler for SIGINT
    signal(SIGINT, self_test_failed_signal_handler);

    // Run self-test
    self_test();

    while (1) {
        // Poll flame sensor
        gpiod_read(GPIO4, &value);
        if (value == 0) {
            printf("Flame detected at %s\n", ctime(&ts));
            gpiod_write(GPIO17, 1); // Activate buzzer
            gpiod_write(GPIO18, 1); // Activate LED
        } else {
            gpiod_write(GPIO17, 0); // Deactivate buzzer
            gpiod_write(GPIO18, 0); // Deactivate LED
        }

        usleep(SAMPLE_INTERVAL_MS);
    }

    // Clean up GPIOs on exit
    gpiod_release_line(GPIO4);
    gpiod_release_line(GPIO17);
    gpiod_release_line(GPIO18);
    gpiod_close(GPIOD);

    return should_exit ? EXIT_FAILURE : EXIT_SUCCESS;
}
