#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <stdint.h>
#include <sys/mman.h>

#define BH1750_ADDR 0x23
#define I2C_DEVICE "/dev/i2c-1"
#define GPIO_NUM 17
#define MAX_READINGS 60

// BH1750 register settings for continuous high-resolution mode
#define REG_CONTINUOUS_HIGH_RES 0x10

// BH1750 raw value to lux conversion factor
#define RAW_TO_LUX_FACTOR 1.2

// Blink rate mapping
#define BLINK_MIN_RATE 0.5
#define BLINK_MAX_RATE 5.0
#define RATE_INCREMENT 4.5

// Circular buffer size
#define BUFFER_SIZE 60

// Global variables
int i2c_fd;
uint8_t buffer[BUFFER_SIZE];
int buffer_index = 0;
int avg_lux = 0;
int blink_rate = BLINK_MIN_RATE;

// Signal handler for graceful shutdown
void sigint_handler(int signum) {
    printf("Received SIGINT, cleaning up...\n");
    close(i2c_fd);
    // Unexport GPIO (assuming pigpio sysfs interface for simplicity)
    char gpio_path[100];
    snprintf(gpio_path, sizeof(gpio_path), "/sys/class/gpio/export");
    FILE *fp = fopen(gpio_path, "w");
    if (fp) {
        fprintf(fp, "%d", GPIO_NUM);
        fclose(fp);
        snprintf(gpio_path, sizeof(gpio_path), "/sys/class/gpio/unexport/%d", GPIO_NUM);
        fp = fopen(gpio_path, "w");
        if (fp) {
            fprintf(fp, "\n");
            fclose(fp);
        }
    }
    exit(0);
}

// Function to read BH1750 sensor
int read_bh1750(int fd) {
    uint16_t raw_value;
    int ret = ioctl(fd, I2C_SLAVE, BH1750_ADDR);
    if (ret < 0) {
        perror("Failed to change I2C slave address");
        return -1;
    }

    ret = ioctl(fd, I2C_READ, &raw_value);
    if (ret < 0) {
        perror("Failed to read BH1750");
        return -1;
    }

    avg_lux += raw_value;
    avg_lux /= BUFFER_SIZE;

    // Convert raw value to lux
    double lux = (double)raw_value / RAW_TO_LUX_FACTOR;

    // Update blink rate
    blink_rate = BLINK_MIN_RATE + (avg_lux / 1000.0) * RATE_INCREMENT;

    // Clamp blink rate
    blink_rate = fminf(blink_rate, BLINK_MAX_RATE);
    blink_rate = fmaxf(blink_rate, BLINK_MIN_RATE);

    // Store the reading in the circular buffer
    buffer[buffer_index++] = lux;
    if (buffer_index >= BUFFER_SIZE) {
        buffer_index = 0;
    }

    return 0;
}

// Main program
int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(1);
    }

    // Map buffer memory
    void *buffer_map = mmap(NULL, BUFFER_SIZE * sizeof(double), PROT_WRITE | PROT_READ, MAP_SHARED, i2c_fd, 0);
    if (buffer_map == MAP_FAILED) {
        perror("mmap failed");
        close(i2c_fd);
        exit(1);
    }

    // Initialize circular buffer
    for (int i = 0; i < BUFFER_SIZE; ++i) {
        buffer_map[i] = 0.0;
    }

    // Start reading loop
    while (1) {
        read_bh1750(i2c_fd);
        usleep(1000000); // 1 second delay
    }

    // Clean up on exit
    close(i2c_fd);
    return 0;
}

