#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>

#define SEVEN_SEGMENT_DATA_PIN 17
#define SEVEN_SEGMENT_CLOCK_PIN 18
#define SEVEN_SEGMENT_LATCH_PIN 27

#define SEGMENTS_ORDER {7, 4, 5, 6, 1, 2, 3, 0} // Q7, Q4, Q5, Q6, Q1, Q2, Q3, Q0

int main() {
    // Initialize libgpiod
    int ret;
    struct gpiod_chip *seven_segment_chip;
    ret = gpiod_chip_open(&seven_segment_chip, SEVEN_SEGMENT_LATCH_PIN, GPIOD_OPEN_RWD);
    if (ret < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", gpiod_error_str(ret));
        return EXIT_FAILURE;
    }

    // Set pins as outputs
    for (int i = 0; i < 3; ++i) {
        ret = gpiod_set_direction(seven_segment_chip, SEVEN_SEGMENT_DATA_PIN + i, GPIOD_DIR_OUT);
        if (ret < 0) {
            fprintf(stderr, "Failed to set direction for pin %d: %s\n", SEVEN_SEGMENT_DATA_PIN + i, gpiod_error_str(ret));
            gpiod_chip_close(seven_segment_chip);
            return EXIT_FAILURE;
        }
    }

    // Function to shift out data to 74HC595
    void shift_out(uint8_t data) {
        uint8_t bits = 0;
        for (int i = 0; i < 8; ++i) {
            bits |= (1 << (SEGMENTS_ORDER[i] - 1));
            gpiod_set_value(seven_segment_chip, SEVEN_SEGMENT_DATA_PIN, bits);
            gpiod_delay_us(5); // Clock delay
            gpiod_set_value(seven_segment_chip, SEVEN_SEGMENT_CLOCK_PIN, !gpiod_get_value(seven_segment_chip, SEVEN_SEGMENT_CLOCK_PIN));
            gpiod_delay_us(5); // Clock pulse
        }
        gpiod_set_value(seven_segment_chip, SEVEN_SEGMENT_LATCH_PIN, 1);
        gpiod_delay_us(5); // Latch delay
    }

    // Blink '5' on the display
    while (1) {
        // Shift out the '5' pattern
        uint8_t pattern = 0b00010010; // Corresponds to segments a, d, and g lit up
        shift_out(pattern);

        // Wait for 500 ms
        usleep(500000);

        // Shift out the 'off' pattern (all segments off)
        pattern = 0;
        shift_out(pattern);

        // Wait for another 500 ms
        usleep(500000);
    }

    // Cleanup: Release lines and close the chip
    for (int i = 0; i < 3; ++i) {
        gpiod_set_direction(seven_segment_chip, SEVEN_SEGMENT_DATA_PIN + i, GPIOD_DIR_IN);
    }
    gpiod_chip_close(seven_segment_chip);

    return EXIT_SUCCESS;
}

