    rc = gpiod_line_request_by_name(button_line, "gpio%d_in", BUTTON_PIN);
    if (rc < 0) {
        fprintf(stderr, "Error requesting button line: %s\n", gpiod_error_string(rc));
        gpiod_line_free(led_line);
        gpiod_chip_close(0);
        return EXIT_FAILURE;
    }

    // Set LED line as output initially low
    rc = gpiod_line_set_value(led_line, 0);
    if (rc < 0) {
        fprintf(stderr, "Error setting LED line value: %s\n", gpiod_error_string(rc));
        gpiod_line_free(led_line);
        gpiod_line_free(button_line);
        gpiod_chip_close(0);
        return EXIT_FAILURE;
    }

    // Request falling-edge events on button line with internal pull-up
    rc = gpiod_line_event_request(button_line, GPIOD_LINE_EVENT_FALLING, GPIOD_LINE_EVENT_TYPE_EDGE, GPIOD_LINE_EVENT_FLAG_PULL_UP);
    if (rc < 0) {
        fprintf(stderr, "Error requesting button line events: %s\n", gpiod_error_string(rc));
        gpiod_line_free(led_line);
        gpiod_line_free(button_line);
        gpiod_chip_close(0);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!should_exit) {
        // Toggle LED state
        int led_value = !gpiod_line_get_value(led_line);
        rc = gpiod_line_set_value(led_line, led_value);
        if (rc < 0) {
            fprintf(stderr, "Error setting LED value: %s\n", gpiod_error_string(rc));
            break;
        }

        // Wait for button event with 1-second timeout
        struct gpiod_line_event event;
        rc = gpiod_line_event_wait(button_line, &event, 1000);
        if (rc < 0) {
            fprintf(stderr, "Error waiting for button event: %s\n", gpiod_error_string(rc));
            break;
        }

        // Check if it's a falling-edge event
        if (event.type == GPIOD_LINE_EVENT_TYPE_EDGE && event.flags & GPIOD_LINE_EVENT_FLAG_PULL_UP) {
            printf("Button pressed, stopping LED blink and exiting...\n");
            should_exit = 1;
        }
    }

    // Release resources on exit
    gpiod_line_free(led_line);
    gpiod_line_free(button_line);
    gpiod_chip_close(0);

    // Clean up signal handler
    signal(SIGINT, signal_handler);

    return EXIT_SUCCESS;
}
