#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

#define LED_GPIO 24
#define BUTTON_GPIO 22

int main() {
    // Initialize signal handlers for Ctrl+C
    signal(SIGINT, handler);
    signal(SIGTERM, handler);

    // Attempt to open the GPIO chip
    struct gpio_chip *chip;
    int rc = gpiod_chip_open(&chip, "gpiochip0", GPIOD_OPEN_READONLY);
    if (rc != 0) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", gpiod_error_string(rc));
        return EXIT_FAILURE;
    }

    // Check if GPIO lines are available
    int rc_get_line = gpiod_get_line(chip, LED_GPIO);
    if (rc_get_line != 0) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", LED_GPIO, gpiod_error_string(rc_get_line));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int rc_set_direction = gpiod_set_direction(chip, LED_GPIO, GPIOD_OUT_LOW);
    if (rc_set_direction != 0) {
        fprintf(stderr, "Error setting direction of GPIO %d: %s\n", LED_GPIO, gpiod_error_string(rc_set_direction));
        gpiod_put_line(chip, LED_GPIO, 0); // Reset the line to low
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    rc_get_line = gpiod_get_line(chip, BUTTON_GPIO);
    if (rc_get_line != 0) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", BUTTON_GPIO, gpiod_error_string(rc_get_line));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set button GPIO as input with internal pull-down
    rc_set_direction = gpiod_set_direction(chip, BUTTON_GPIO, GPIOD_IN_PULLDOWN);
    if (rc_set_direction != 0) {
        fprintf(stderr, "Error setting direction of GPIO %d: %s\n", BUTTON_GPIO, gpiod_error_string(rc_set_direction));
        gpiod_put_line(chip, BUTTON_GPIO, 0); // Reset the line to low
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Read button state
        int button_value = gpiod_get_value(chip, BUTTON_GPIO);
        if (button_value) {
            // Button is pressed, blink the LED
            for (int i = 0; i < 10; i++) { // 10 cycles of 500ms on, 500ms off
                gpiod_set_value(chip, LED_GPIO, 1); // Turn LED on
                usleep(500000); // Wait 500ms
                gpiod_set_value(chip, LED_GPIO, 0); // Turn LED off
                usleep(500000); // Wait 500ms
            }
        } else {
            // Button is released, turn LED off
            gpiod_set_value(chip, LED_GPIO, 0);
        }
    }

    // Release resources on exit
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

// Signal handler for SIGINT and SIGTERM
void handler(int signum) {
    fprintf(stderr, "Received signal %d, exiting...\n", signum);
    exit(EXIT_FAILURE);
}

