#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>

// Define GPIO pin for impact indication
#define IMPACT_PIN 17

// Define I2C bus and address for LSM303DLHC
#define I2C_BUS 1
#define I2C_ADDRESS 0x19

// Define configuration registers and values
#define CTRL_REG1_A 0x28
#define CTRL_REG1_A_VALUE 0x27 // Enable all axes, 100 Hz
#define CTRL_REG4_A 0x2B
#define CTRL_REG4_A_VALUE 0x00 // 2G full-scale, sensitivity 16384 LSB/G

// Define data registers and auto-increment bit
#define OUT_X_L_A 0x28
#define OUT_X_H_A 0x29
#define OUT_Y_L_A 0x2A
#define OUT_Y_H_A 0x2B
#define OUT_Z_L_A 0x2C
#define OUT_Z_H_A 0x2D

// G-force threshold
#define THRESHOLD_G 2.0

// Function prototypes
void setup_pigpio();
void setup_i2c();
void configure_sensor();
void read_accelerometer_data();
void handle_impact();
void cleanup_resources();
void signal_handler(int signum);

int main(int argc, char **argv) {
    // Initialize pigpio library
    setup_pigpio();

    // Check for required command-line argument
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    // Parse threshold from command-line argument
    double threshold = atof(argv[1]);

    // Setup I2C and configure the sensor
    setup_i2c();
    configure_sensor();

    // Main loop
    while (1) {
        // Poll accelerometer at 10 Hz
        read_accelerometer_data();

        // Check for impact
        if (calculate_g_force() > threshold) {
            handle_impact();
        }
    }

    // Clean up resources on exit
    cleanup_resources();

    return 0;
}

// Function to setup pigpio library
void setup_pigpio() {
    if (pigpioSetup(0) < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpioError());
        exit(1);
    }
}

// Function to setup I2C
void setup_i2c() {
    if (gpiodI2CSetup(I2C_BUS, 400000) < 0) {
        fprintf(stderr, "Failed to setup I2C: %s\n", gpiodErrorString());
        exit(1);
    }
}

// Function to configure the sensor
void configure_sensor() {
    uint8_t reg_value = CTRL_REG1_A_VALUE;
    uint8_t reg_addr = CTRL_REG1_A;

    // Write CTRL_REG1_A
    if (gpiodI2CWrite(reg_addr, &reg_value, 1) < 0) {
        fprintf(stderr, "Failed to write CTRL_REG1_A: %s\n", gpiodErrorString());
        exit(1);
    }

    reg_value = CTRL_REG4_A_VALUE;
    reg_addr = CTRL_REG4_A;

    // Write CTRL_REG4_A
    if (gpiodI2CWrite(reg_addr, &reg_value, 1) < 0) {
        fprintf(stderr, "Failed to write CTRL_REG4_A: %s\n", gpiodErrorString());
        exit(1);
    }
}

// Function to read accelerometer data
void read_accelerometer_data() {
    uint16_t x_low, x_high, y_low, y_high, z_low, z_high;

    // Read OUT_X_L_A (0x28)
    if (gpiodI2CRead(OUT_X_L_A, &x_low, 1) < 0) {
        fprintf(stderr, "Failed to read OUT_X_L_A: %s\n", gpiodErrorString());
        return;
    }

    // Read OUT_X_H_A (0x29)
    if (gpiodI2CRead(OUT_X_H_A, &x_high, 1) < 0) {
        fprintf(stderr, "Failed to read OUT_X_H_A: %s\n", gpiodErrorString());
        return;
    }

    // Read OUT_Y_L_A (0x2A)
    if (gpiodI2CRead(OUT_Y_L_A, &y_low, 1) < 0) {
        fprintf(stderr, "Failed to read OUT_Y_L_A: %s\n", gpiodErrorString());
        return;
    }

    // Read OUT_Y_H_A (0x2B)
    if (gpiodI2CRead(OUT_Y_H_A, &y_high, 1) < 0) {
        fprintf(stderr, "Failed to read OUT_Y_H_A: %s\n", gpiodErrorString());
        return;
    }

    // Read OUT_Z_L_A (0x2C)
    if (gpiodI2CRead(OUT_Z_L_A, &z_low, 1) < 0) {
        fprintf(stderr, "Failed to read OUT_Z_L_A: %s\n", gpiodErrorString());
        return;
    }

    // Read OUT_Z_H_A (0x2D)
    if (gpiodI2CRead(OUT_Z_H_A, &z_high, 1) < 0) {
        fprintf(stderr, "Failed to read OUT_Z_H_A: %s\n", gpiodErrorString());
        return;
    }

    // Calculate G-force magnitude
    int16_t x_g = (x_high << 8) | x_low;
    int16_t y_g = (y_high << 8) | y_low;
    int16_t z_g = (z_high << 8) | z_low;

    int g_force_magnitude = sqrt(x_g * x_g + y_g * y_g + z_g * z_g);

    // Log timestamped data if impact detected
    if (g_force_magnitude > THRESHOLD_G) {
        fprintf(stderr, "Impact detected at %ld G\n", g_force_magnitude);
        // Write to 'impact_log.txt'
        FILE *log_file = fopen("impact_log.txt", "a+");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open 'impact_log.txt' for writing: %s\n", strerror(errno));
            fclose(log_file);
            return;
        }
        fprintf(log_file, "Timestamp: %ld, G-force: %ld\n", (long)time(NULL), g_force_magnitude);
        fclose(log_file);
    }
}

// Function to handle impact
void handle_impact() {
    // Pulse GPIO17 HIGH for 50 ms
    if (gpiodDigitalWrite(IMPACT_PIN, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO17 HIGH: %s\n", gpiodErrorString());
        return;
    }
    usleep(50000); // 50 ms delay
    if (gpiodDigitalWrite(IMPACT_PIN, 0) < 0) {
        fprintf(stderr, "Failed to set GPIO17 LOW: %s\n", gpiodErrorString());
    }
