    while (1) {
        // Read acceleration data
        read_acceleration_data();

        // Check for impact
        detect_impact();

        // Sleep for 50 ms
        usleep(50000);
    }

    // Graceful shutdown on SIGINT
    if (PIGPIO_ID != PIGPIO_ERROR) {
        gpioTerminate(PIGPIO_ID);
    }

    exit(0);
}

// Function to setup pigpio
void setup_pigpio() {
    if (pigpioSetup() == PIGPIO_ERROR) {
        fprintf(stderr, "Failed to setup pigpio: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }

    PIPIO_ID = pigpioOpen();
    if (PIPIO_ID == PIGPIO_ERROR) {
        fprintf(stderr, "Failed to open GPIO: %s\n", pigpioError());
        exit(EXIT_FAILURE);
