    // Write WHO_AM_I register to verify sensor
    if (pigpioI2CWrite(PIPIO_ID, I2C_ADDRESS, WHO_AM_I_REG, 0xC7, 1) != 1) {
        fprintf(stderr, "Error reading WHO_AM_I: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }

