    if (pigpioI2CWrite(PIPIO_ID, I2C_ADDRESS, CTRL_REG1, 0x04, 1) != 1) {
        fprintf(stderr, "Error writing to CTRL_REG1: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }

    // Configure XYZ_DATA_CFG for ±2g mode
    if (pigpioI2CWrite(PIPIO_ID, I2C_ADDRESS, XYZ_DATA_CFG_REG, 0x00, 1) != 1) {
        fprintf(stderr, "Error writing to XYZ_DATA_CFG: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }

