#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS_NUM 1
#define GYRO_ADDRESS 0x69
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_Y_L 0x2A
#define OUT_Z_H 0x2C

#define SENSITIVITY 0.00875 // dps/LSB
#define MAX_DEGREES_PER_SECOND 50
#define SAMPLES_FOR_CALIBRATION 100

// Structure to hold gyro data
typedef struct {
    int16_t x, y, z;
} gyro_data_t;

// Function prototypes
void gyro_init(void);
void gyro_read_data(gyro_data_t *data);
void print_warning(const char *msg);
void write_to_log(const char *msg);
void close_resources(void);

int main(void) {
    int fd;
    gyro_data_t data;
    int i;
    struct timespec start_time, elapsed_time;
    char gyro_log_file[100] = "gyro_log.txt";
    sigset_t sigset;

    // Initialize signal handling
    sigemptyset(&sigset);
    sigaddset(&sigset, SIGINT);
    sigaddset(&sigset, SIGTERM);
    sigprocmask(SIG_BLOCK, &sigset, NULL);

    // Open I2C bus
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd == -1) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Initialize gyro
    gyro_init();

    // Main loop
    while (1) {
        // Get current time
        clock_gettime(CLOCK_REALTIME, &start_time);

        // Read gyro data
        gyro_read_data(&data);

        // Calculate elapsed time
        clock_gettime(CLOCK_REALTIME, &elapsed_time);
        struct timespec diff;
        clock_sub(&diff, &elapsed_time, &start_time);
        long usec = diff.tv_nsec / 1000000 + diff.tv_sec * 1000000;

        // Write to log if necessary
        if (data.x > MAX_DEGREES_PER_SECOND || data.y > MAX_DEGREES_PER_SECOND || data.z > MAX_DEGREES_PER_SECOND) {
            print_warning("Gyro exceeding threshold: %d %d %d", data.x, data.y, data.z);
            write_to_log("Gyro exceeded threshold at %f\n", elapsed_time.tv_sec * 1000 + usec);
        } else {
            write_to_log("Gyro reading at %f: X=%d Y=%d Z=%d\n", elapsed_time.tv_sec * 1000 + usec, data.x, data.y, data.z);
        }

        // Sleep for 50ms
        usleep(50000);
    }

    // Close resources on exit
    close_resources();

    // Restore signal mask
    sigprocmask(SIG_SETMASK, &sigset, NULL);

    return 0;
}

// Function to initialize the gyro
void gyro_init() {
    int ret;

    // Write to CTRL_REG1 to set normal mode
    ret = ioctl(fd, I2C_SLAVE, GYRO_ADDRESS);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }
    ret = ioctl(fd, IOCTL_GYR_CTRL_REG1, CTRL_REG1);
    if (ret < 0) {
        perror("Failed to write to CTRL_REG1");
        exit(EXIT_FAILURE);
    }

    // Write to CTRL_REG4 to set full-scale range
    ret = ioctl(fd, IOCTL_GYR_CTRL_REG4, CTRL_REG4);
    if (ret < 0) {
        perror("Failed to write to CTRL_REG4");
        exit(EXIT_FAILURE);
    }

    // Perform 100-sample calibration
    for (int i = 0; i < SAMPLES_FOR_CALIBRATION; i++) {
        gyro_read_data(&data);
        // Store zero-rate offsets for calibration
    }

    // Read WHO_AM_I register to verify sensor presence
    ret = ioctl(fd, IOCTL_GYR_WHO_AM_I, NULL);
    if (ret != GYRO_ADDRESS) {
        perror("Sensor not detected");
        exit(EXIT_FAILURE);
    }
}

// Function to read gyro data
void gyro_read_data(gyro_data_t *data) {
    int ret;

    // Read OUT_X_L, OUT_Y_L, OUT_Z_H with auto-increment
    ret = ioctl(fd, IOCTL_GYR_OUT_X_L_H, OUT_X_L);
    if (ret < 0) {
        perror("Failed to read gyro data");
        exit(EXIT_FAILURE);
    }

    data->x = (int16_t)(((data->x << 8) | (data->y >> 8))) * SENSITIVITY;
    data->y = (int16_t)data->y * SENSITIVITY;
    data->z = (int16_t)(((data->z << 8) | (data->x >> 8))) * SENSITIVITY;
}

// Function to print warning message to stderr
void print_warning(const char *msg) {
    fprintf(stderr, "%s\n", msg);
}

// Function to write to the log file
void write_to_log(const char *msg) {
    FILE *log_file = fopen(gyro_log_file, "a+");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    fprintf(log_file, "%s\n", msg);
    fclose(log_file);
}

// Function to close resources and release file descriptors
void close_resources(void) {
    close(fd);
    // Optionally, remove the log file
    unlink(gyro_log_file);
}

