#include <pigpio.h>
#include <stdint.h>

// Define GPIO pin for LED
#define LED_PIN 17

// Define I2C bus and address for ADXL345
#define I2C_BUS 1
#define ADXL345_ADDRESS 0x53

// Define full-scale range and resolution for ADXL345
#define FULL_SCALE 2.0
#define RESOLUTION (1024.0 / FULL_SCALE)

// Function prototypes
void setup_pigpio();
void setup_i2c();
void read_acceleration_data(uint8_t *data);
void handle_signal(int signum);
void cleanup();

int main() {
    // Initialize global variables
    FILE *accel_log = NULL;
    pigpio *pi = NULL;
    uint8_t data[6];
    int led_state = 0;

    // Register signal handler for SIGINT and SIGTERM
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main program loop
    while (1) {
        // Check for termination signal
        if (pi != NULL) {
            if (handle_signal(SIGINT) || handle_signal(SIGTERM)) {
                break;
            }
        }

        // Attempt to read acceleration data
        if (read_acceleration_data(data)) {
            // Process data and handle LED control
            float x = (float)data[0] * RESOLUTION;
            float y = (float)data[1] * RESOLUTION;
            float z = (float)data[2] * RESOLUTION;

            // Check for acceleration exceeding 2.0g on any axis
            if (sqrt(x * x + y * y + z * z) > 2.0) {
                led_state = !led_state; // Toggle LED state
            }

            // Write to log file
            if (accel_log != NULL) {
                fprintf(accel_log, "%f,%f,%f\n", x, y, z);
            }

            // Update LED state
            if (led_state) {
                gpio_write(LED_PIN, 1);
            } else {
                gpio_write(LED_PIN, 0);
            }
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up resources
    cleanup();

    return 0;
}

// Function to setup pigpio
void setup_pigpio() {
    pi = pigpio_open();
    if (pi == NULL) {
        fprintf(stderr, "Failed to open pigpio\n");
        exit(EXIT_FAILURE);
    }

    // Set up GPIO 17 for LED control
    if (gpio_mode(LED_PIN, GPIO_OUTPUT_ON_HIGH) == -1) {
        fprintf(stderr, "Failed to set GPIO %d to output\n", LED_PIN);
        exit(EXIT_FAILURE);
    }
}

// Function to setup I2C
void setup_i2c() {
    if (pigpio_i2c_init(I2C_BUS) == -1) {
        fprintf(stderr, "Failed to initialize I2C bus %d\n", I2C_BUS);
        exit(EXIT_FAILURE);
    }

    // Write to ADXL345 DEVID register to verify device
    if (pigpio_i2c_write(I2C_BUS, ADXL345_ADDRESS, 0x00, 0xE5) == -1) {
        fprintf(stderr, "Failed to write to ADXL345 DEVID register\n");
        exit(EXIT_FAILURE);
    }

    // Configure ADXL345 for full resolution and ±2g range
    if (pigpio_i2c_write(I2C_BUS, ADXL345_ADDRESS, 0x2D, 0x01) == -1 ||
        pigpio_i2c_write(I2C_BUS, ADXL345_ADDRESS, 0x2E, 0x00) == -1) {
        fprintf(stderr, "Failed to configure ADXL345\n");
        exit(EXIT_FAILURE);
    }
}

// Function to read acceleration data from ADXL345
int read_acceleration_data(uint8_t *data) {
    int bytes_read = pigpio_i2c_read(I2C_BUS, ADXL345_ADDRESS, 0x32, 6, data);
    if (bytes_read != 6) {
        fprintf(stderr, "Failed to read acceleration data from ADXL345\n");
        return 0;
    }

    return 1;
}

// Function to handle SIGINT and SIGTERM
void handle_signal(int signum) {
    // Close log file
    if (accel_log != NULL) {
        fclose(accel_log);
        accel_log = NULL;
    }

    // Release resources
    cleanup();

    // Exit the program
    exit(EXIT_SUCCESS);
}

// Function to cleanup resources
void cleanup() {
    // Close log file if it's open
    if (accel_log != NULL) {
        fclose(accel_log);
        accel_log = NULL;
    }

    // Release pigpio handle
    if (pi != NULL) {
        pigpio_close(pi);
        pi = NULL;
    }

    // Release I2C bus handle
    pigpio_i2c_free();
}

