        setup_pigpio();
        setup_accelerometer();
        setup_magnetometer();
        file = fopen("compass_log.txt", "a+");
        while (1) {
            read_sensors(&last_data);
            calculate_tilt_compensated_heading(last_data.acceleration.x, last_data.acceleration.y, last_data.acceleration.z);
            log_data_to_file(HEADER "\n" 
