                             , (double)clock() / CLOCKS_PER_SEC 
                             , last_data.acceleration.x 
                             , last_data.acceleration.y 
                             , last_data.acceleration.z 
                             , last_data.magnetic_field.x 
                             , last_data.magnetic_field.y 
                             , last_data.magnetic_field.z);
            usleep(SAMPLE_INTERVAL_MS * 1000);
        }
