    uint8_t reg_val = 0x00;
    if (pigpio_i2c_write(pi, I2C_BUS, MAG_ADDR, MAG_REG_MR_M, &reg_val, 1) != 1) {
        fprintf(stderr, "Failed to set magnetometer MR_REG_M\n");
        exit(EXIT_FAILURE);
    }
}

void read_sensors(struct sensor_data *data) {
    uint8_t accel_data[6];
    pigpio_i2c_read(pi, I2C_BUS, ACCEL_ADDR, ACCEL_REG_OUT_X_L_A, accel_data, 6);
    data->acceleration = (float)accel_data[0] / 16384.0; // Convert to g
    data->magnetic_field.x = (float)accel_data[1] / 1024.0; // Convert to gauss
    data->magnetic_field.y = (float)accel_data[2] / 1024.0;
    data->magnetic_field.z = (float)accel_data[3] / 1024.0;

