    // Implement tilt compensation algorithm here
    // For simplicity, let's assume a basic tilt compensation using the accelerometer data
    float atan2_yx = atan2(y, x);
    float compensated_heading = atan2(z, sqrt(x * x + y * y));
    return compensated_heading;
}

