    pi = NULL;
    cleanup();
    exit(EXIT_SUCCESS);
}

void cleanup() {
    if (pi != NULL) {
        pigpio_close(pi);
        pi = NULL;
    }
}

// Sensor data structure
typedef struct sensor_data {
    float acceleration[3];
    float magnetic_field[3];
} sensor_data;

