#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include "Adafruit_VL6180X.h"

// Define GPIO pin for interrupt (if needed)
#define INT_PIN 18

// Global variables
FILE *distance_log;
Adafruit_VL6180X vl6180x;
pigpio *gp;

// Function prototypes
void initialize_sensor();
void read_distance();
void handle_signal(int signum);
void cleanup();

int main() {
    // Initialize GPIO and I2C
    gp = pigpioOpen();
    if (gp == NULL) {
        fprintf(stderr, "Failed to open GPIO\n");
        return 1;
    }

    distance_log = fopen("distance_log.txt", "a+");
    if (distance_log == NULL) {
        fprintf(stderr, "Failed to open distance log file\n");
        pigpioClose(gp);
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, handle_signal);

    // Initialize the sensor
    initialize_sensor();

    while (1) {
        read_distance();
        fprintf(distance_log, "%s\n", vl6180x.getDistance() < 100 ? "DOOR_OPEN" : "DOOR_CLOSED");
        fflush(distance_log);
        usleep(100000); // Sleep for 100 ms
    }

    // Clean up on exit
    cleanup();

    pigpioClose(gp);
    fclose(distance_log);

    return 0;
}

// Function to initialize the VL6180X sensor
void initialize_sensor() {
    vl6180x.begin();
    if (!vl6180x.begin()) {
        fprintf(stderr, "Failed to initialize VL6180X sensor\n");
        return;
    }

    // Perform mandatory initialization sequence
    uint8_t reg_val;
    reg_val = vl6180x.readRegister(0x16);
    if (reg_val != 0x01) {
        fprintf(stderr, "VL6180X initialization failed at register 0x16\n");
        vl6180x.end();
        return;
    }

    vl6180x.writeRegister(0x00, 0x20);
    vl6180x.writeRegister(0x01, 0x07);
    vl6180x.writeRegister(0x02, 0x00);
    vl6180x.writeRegister(0x03, 0x00);
    vl6180x.writeRegister(0x04, 0x00);
    vl6180x.writeRegister(0x05, 0x00);
    vl6180x.writeRegister(0x06, 0x00);
    vl6180x.writeRegister(0x07, 0x00);
    vl6180x.writeRegister(0x08, 0x00);
    vl6180x.writeRegister(0x09, 0x00);
    vl6180x.writeRegister(0x0a, 0x00);
    vl6180x.writeRegister(0x0b, 0x00);
    vl6180x.writeRegister(0x0c, 0x00);
    vl6180x.writeRegister(0x0d, 0x00);
    vl6180x.writeRegister(0x0e, 0x00);
    vl6180x.writeRegister(0x0f, 0x00);

    if (vl6180x.begin() == false) {
        fprintf(stderr, "VL6180X initialization failed after sequence\n");
        vl6180x.end();
        return;
    }
}

// Function to read distance from the sensor
