    uint16_t distance;
    if (vl6180x.readDistance(&distance) == Adafruit_VL6180X_ERROR) {
        fprintf(stderr, "Error reading distance from VL6180X\n");
        initialize_sensor(); // Attempt re-initialization
        return;
    }

    if (distance < 100) {
        fprintf(distance_log, "DOOR_OPEN\n");
    } else {
        fprintf(distance_log, "DOOR_CLOSED\n");
    }
}

// Signal handler for SIGINT (Ctrl+C)
void handle_signal(int signum) {
    fprintf(stderr, "SIGINT received, cleaning up...\n");
    cleanup();
    exit(0);
}

// Function to clean up resources
void cleanup() {
    vl6180x.end();
    pigpioClose(gp);
    fclose(distance_log);
}

