#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>
#include <unistd.h>

// Define I2C addresses for the sensors
#define SENSOR1_ADDRESS 0x68
#define SENSOR2_ADDRESS 0x69

// Control register write value to enable continuous measurement
#define ENABLE_CONTINUOUS_MEASUREMENT 0x80

// Function prototypes
void setup_pigpio();
void setup_i2c(int bus);
void read_sensors(uint16_t *data);
void timestamp_and_log(uint16_t sensor_data, uint64_t timestamp);
void handle_signal(int signum);

// Global variables
pigpio *pi;
FILE *audio_log;
int i2c_bus = 1;

// Main function
int main() {
    // Initialize pigpio and setup I2C
    setup_pigpio();
    setup_i2c(i2c_bus);

    uint16_t sensor1_data, sensor2_data;
    uint64_t timestamp;

    // Signal handler for SIGINT
    signal(SIGINT, handle_signal);

    while (1) {
        // Attempt to read from sensors
        read_sensors(&sensor1_data, &sensor2_data);

        // If either sensor fails, log the error and continue
        if (sensor1_data == 0 || sensor2_data == 0) {
            fprintf(audio_log, "%lu,%lu,0,0,-1\n", (unsigned long)clock(), (unsigned long)clock());
            continue;
        }

        // Timestamp the samples
        timestamp = clock();

        // Log the data
        timestamp_and_log(sensor1_data, timestamp);
        timestamp_and_log(sensor2_data, timestamp);

        // Sleep for 10 ms
        usleep(10000);
    }

    // Clean up resources on exit
    handle_signal(SIGINT);

    return 0;
}

// Function to setup pigpio
void setup_pigpio() {
    pi = pigpioOpen();
    if (pi == NULL) {
        fprintf(stderr, "Failed to open pigpio\n");
        exit(1);
    }
}

// Function to setup I2C on the specified bus
void setup_i2c(int bus) {
    if (pigpioI2CSetup(pi, bus) == 0) {
        fprintf(stderr, "Failed to setup I2C on bus %d\n", bus);
        exit(1);
    }
}

// Function to read data from the sensors
void read_sensors(uint16_t *data1, uint16_t *data2) {
    // Write to control register to enable continuous measurement
    pigpioI2CWrite(pi, SENSOR1_ADDRESS, 0x00, ENABLE_CONTINUOUS_MEASUREMENT);
    pigpioI2CWrite(pi, SENSOR2_ADDRESS, 0x00, ENABLE_CONTINUOUS_MEASUREMENT);

    // Read data from sensors
    pigpioI2CRead(pi, SENSOR1_ADDRESS, 0x01, data1);
    pigpioI2CRead(pi, SENSOR2_ADDRESS, 0x01, data2);

    // Reset control registers to disable continuous measurement
    pigpioI2CWrite(pi, SENSOR1_ADDRESS, 0x00, 0x00);
    pigpioI2CWrite(pi, SENSOR2_ADDRESS, 0x00, 0x00);
}

// Function to timestamp and log sensor data
void timestamp_and_log(uint16_t sensor_data, uint64_t timestamp) {
    fprintf(audio_log, "%lu,%lu,%u,%u,%u\n",
            (unsigned long)timestamp,
            (unsigned long)(timestamp % 1e9),
            sensor_data,
            sensor_data >> 8,
            -((sensor_data - sensor2_data) >> 8));
}

// Signal handler for SIGINT
void handle_signal(int signum) {
    // Close log file and release resources
    fclose(audio_log);
    pigpioClose(pi);
    pigpioI2CStopAll(pi);

    // Exit the program
    exit(0);
}

// Ensure the program releases resources properly on exit
// SIGINT handler is already set up to handle clean exit

// Main program execution starts here
int main()
{
    // ... (rest of the code as provided above)
    return 0;
}

