#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define GPIO_CE0 8
#define SPI_SPEED_MHZ 1
#define SPI_MODE 3
#define SPI_FLAGS 0b11000000000
#define ADIS16488A_REG_X_GYRO 0x04
#define ADIS16488A_REG_Y_GYRO 0x06
#define ADIS16488A_REG_Z_GYRO 0x08
#define ADIS16488A_REG_X_ACCEL 0x0A
#define ADIS16488A_REG_Y_ACCEL 0x0C
#define ADIS16488A_REG_Z_ACCEL 0x0E
#define GYRO_SENSITIVITY 0.005
#define ACCEL_SENSITIVITY 0.00025

// Function prototypes
void cleanup(void);
void read_imu_data(void);
void handle_signals(int signum);

// Global variables
FILE* csv_file;
pigpio *pi;
int spi_fd;

// Function to initialize GPIO and SPI
int init_resources() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing GPIO: %s\n", strerror(errno));
        return -1;
    }

    if (spiOpen(SPI_CHANNEL, GPIO_CE0, SPI_SPEED_MHZ, SPI_MODE, SPI_FLAGS) < 0) {
        fprintf(stderr, "Error opening SPI: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to cleanup SPI and GPIO resources
void cleanup(void) {
    if (csv_file != NULL) {
        fclose(csv_file);
        csv_file = NULL;
    }

    if (pi != NULL) {
        pigpio_free(pi);
        pi = NULL;
    }

    if (spi_fd != -1) {
        close(spi_fd);
        spi_fd = -1;
    }

    atexit(cleanup);
}

// Function to handle signals and perform cleanup
void handle_signals(int signum) {
    if (pi != NULL) {
        pigpio_stop(pi);
        pigpio_free(pi);
        pi = NULL;
    }

    exit(signum);
}

// Main function
int main() {
    // Initialize resources
    if (init_resources() < 0) {
        fprintf(stderr, "Initialization failed.\n");
        return 1;
    }

    // Open CSV file for writing
    csv_file = fopen("imu_data.csv", "a+");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        return 1;
    }

    // Start pigpio daemon
    pi = pigpio_open();
    if (pi == NULL) {
        fprintf(stderr, "Failed to open pigpio daemon: %s\n", pigpio_error());
        return 1;
    }

    // Register signal handler
    signal(SIGINT, handle_signals);
    signal(SIGTERM, handle_signals);

    // Main loop
    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);

        // Write header if first run
        if (csv_file == NULL || ftell(csv_file) == 0) {
            fprintf(csv_file, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");
        }

        // Read IMU data
        read_imu_data();

        // Delay for 100 ms
        ts.tv_sec += 1;
        ts.tv_nsec += 100000000;
        nanosleep(&ts, NULL);

        // Check if we should exit
        if (pi == NULL) {
            break;
        }
    }

    // Cleanup on exit
    cleanup();

    return 0;
}

// Function to read IMU data
void read_imu_data() {
    int gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;
    struct timeval tv;

    // Read gyroscope data
    spiXfer(spi_fd, (pigpio_spi_transfer_t *) &ADIS16488A_REG_X_GYRO, 1, 0);
    spiXfer(spi_fd, (pigpio_spi_transfer_t *) &ADIS16488A_REG_X_GYRO, 1, 0); // Dummy read/stall
    gettimeofday(&tv, NULL);
    gyro_x = (tv.tv_sec * 1000 * GYRO_SENSITIVITY) + (tv.tv_usec * GYRO_SENSITIVITY / 1000000);

    // Read other gyroscope data
    spiXfer(spi_fd, (pigpio_spi_transfer_t *) &ADIS16488A_REG_Y_GYRO, 1, 0);
    spiXfer(spi_fd, (pigpio_spi_transfer_t *) &ADIS16488A_REG_Y_GYRO, 1, 0); // Dummy read/stall
    gyro_y = (tv.tv_sec * 1000 * GYRO_SENSITIVITY) + (tv.tv_usec * GYRO_SENSITIVITY / 1000000);

    // Read other gyroscope data
    spiXfer(spi_fd, (pigpio_spi_transfer_t *) &ADIS16488A_REG_Z_GYRO, 1, 0);
    spiXfer(spi_fd, (pigpio_spi_transfer_t *) &ADIS16488A_REG_Z_GYRO, 1, 0); // Dummy read/stall
    gyro_z = (tv.tv_sec * 1000 * GYRO_SENSITIVITY) + (tv.tv_usec * GYRO_SENSITIVITY / 1000000);

    // Read accelerometer data
    spiXfer(spi_fd, (pigpio_spi_transfer_t *) &ADIS16488A_REG_X_ACCEL, 1, 0);
    spiXfer(spi_fd, (pigpio_spi_transfer_t *) &ADIS16488A_REG_X_ACCEL, 1, 0); // Dummy read/stall
    accel_x = (tv.tv_sec * 1000 * ACCEL_SENSITIVITY) + (tv.tv_usec * ACCEL_SENSITIVITY / 1000000);

    // Read other accelerometer data
    spiXfer(spi_fd, (pigpio_spi_transfer_t *) &ADIS16488A_REG_Y_ACCEL, 1, 0);
    spiXfer(spi_fd, (pigpio_spi_transfer_t *) &ADIS16488A_REG_Y_ACCEL, 1, 0); // Dummy read/stall
    accel_y = (tv.tv_sec * 1000 * ACCEL_SENSITIVITY) + (tv.tv_usec * ACCEL_SENSITIVITY / 1000000);

    // Read other accelerometer data
    spiXfer(spi_fd, (pigpio_spi_transfer_t *) &ADIS16488A_REG_Z_ACCEL, 1, 0);
    spiXfer(spi_fd, (pigpio_spi_transfer_t *) &ADIS16488A_REG_Z_ACCEL, 1, 0); // Dummy read/stall
    accel_z = (tv.tv_sec * 1000 * ACCEL_SENSITIVITY) + (tv.tv_usec * ACCEL_SENSITIVITY / 1000000);

    // Write data to CSV file
    fprintf(csv_file, "%ld,%f,%f,%f,%f,%f,%f\n", tv.tv_sec, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
}

