This C program initializes GPIO and SPI resources, opens a CSV file for logging, and continuously reads gyroscope and accelerometer data from the Analog Devices ADIS16488A IMU over SPI on a Raspberry Pi 4 Model B using the pigpio library. It handles SPI transfers, implements a delay between request and data retrieval, and logs each sample with a timestamp to a CSV file. The program gracefully handles errors and resources are cleaned up on exit or when a signal is received.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CS_GPIO 8
#define SPI_SPEED 1000000
#define ADIS16448_REG_XGYRO 0x04
#define ADIS16448_REG_YGYRO 0x06
#define ADIS16448_REG_ZGYRO 0x08
#define ADIS16448_REG_XACCL 0x0A
#define ADIS16448_REG_YACCL 0x0C
#define ADIS16448_REG_ZACCL 0x0E

#define SCALE_FACTOR_GYRO 0.02
#define SCALE_FACTOR_ACCEL 0.00025

volatile sig_atomic_t should_exit = 0;

void handle_signal(int signum) {
    should_exit = 1;
}

int main() {
    // Initialize libgpiod for GPIO 8 (CS pin)
    int cs_gpio_fd = gpiod_get_fd(CS_GPIO);
    if (cs_gpio_fd < 0) {
        perror("Failed to open GPIO 8");
        return EXIT_FAILURE;
    }

    // Open SPI device
    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        gpiod_release_cs(cs_gpio_fd);
        return EXIT_FAILURE;
    }

    // Set SPI mode 3 (CPOL=0, CPHA=1)
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_SPEED) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        gpiod_release_cs(cs_gpio_fd);
        return EXIT_FAILURE;
    }

    // Set chip select GPIO 8 to active low
    if (gpiod_set_value(cs_gpio_fd, GPIOD_VALUE_LOW) < 0) {
        perror("Failed to set CS GPIO to low");
        close(spi_fd);
        gpiod_release_cs(cs_gpio_fd);
        return EXIT_FAILURE;
    }

    // Handle SIGINT and SIGTERM
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!should_exit) {
        // Read gyroscope X, Y, Z
        uint16_t x_gyro = read_gyro(spi_fd, ADIS16448_REG_XGYRO);
        uint16_t y_gyro = read_gyro(spi_fd, ADIS16448_REG_YGYRO);
        uint16_t z_gyro = read_gyro(spi_fd, ADIS16448_REG_ZGYRO);

        // Read accelerometer X, Y, Z
        uint16_t x_accel = read_accel(spi_fd, ADIS16448_REG_XACCL);
        uint16_t y_accel = read_accel(spi_fd, ADIS16448_REG_YACCL);
        uint16_t z_accel = read_accel(spi_fd, ADIS16448_REG_ZACCL);

        // Scale and print values
        float x_gyro_scaled = (float)x_gyro * SCALE_FACTOR_GYRO;
        float y_gyro_scaled = (float)y_gyro * SCALE_FACTOR_GYRO;
