#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>

// Define SPI constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0

// ADIS16448 register addresses for gyroscope and accelerometer data
#define X_GYRO_OUT 0x04
#define Y_GYRO_OUT 0x06
#define Z_GYRO_OUT 0x08
#define X_ACCL_OUT 0x0A
#define Y_ACCL_OUT 0x0C
#define Z_ACCL_OUT 0x0E

// Scaling factors
#define GYRO_SCALE 0.05
#define ACCEL_SCALE 0.00025

// Function prototypes
void setup_pigpio();
void setup_spi();
void read_imu_data();
void cleanup();

// Global variables
pigpio *gp;
uint8_t spi_channel;
uint32_t spi_speed;
uint8_t spi_mode;

// Signal handler for Ctrl+C
void signal_handler(int signum) {
    printf("Interrupted, cleaning up...\n");
    cleanup();
    exit(0);
}

int main() {
    // Initialize pigpio
    setup_pigpio();

    // Set up SPI
    setup_spi();

    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        read_imu_data();
        usleep(100000); // 100 ms delay
    }

    // Clean up
    cleanup();

    return 0;
}

// Function to setup pigpio
void setup_pigpio() {
    if (gp == NULL) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return;
    }

    // Ensure GPIO 8 is configured as CE0
    if (gpioMode(GPIO_NUM_8, GPIO_OUTPUT) == -1) {
        fprintf(stderr, "Failed to set GPIO 8 as output\n");
        return;
    }

    // Set GPIO 8 to high (CE0 active)
    if (gpioWrite(GPIO_NUM_8, 1) == -1) {
        fprintf(stderr, "Failed to set GPIO 8 high\n");
        return;
    }
}

// Function to setup SPI
void setup_spi() {
    if (gp == NULL) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return;
    }

    // Open SPI device
    if ((spi_channel = openSpi(SPI_CHANNEL, SPI_SPEED, SPI_MODE)) == -1) {
        fprintf(stderr, "Failed to open SPI channel %d\n", SPI_CHANNEL);
        return;
    }

    // Ensure CE0 is configured as output
    if (gpioMode(GPIO_NUM_8, GPIO_OUTPUT) == -1) {
        fprintf(stderr, "Failed to set GPIO 8 as output\n");
        close(spi_channel);
        return;
    }

    // Set GPIO 8 to high (CE0 active)
    if (gpioWrite(GPIO_NUM_8, 1) == -1) {
        fprintf(stderr, "Failed to set GPIO 8 high\n");
        close(spi_channel);
        return;
    }
}

// Function to read IMU data
void read_imu_data() {
    // Send read command to ADIS16448
    uint16_t read_cmd = (X_GYRO_OUT | 0x8000); // Bit 15 set for read command

    // Send dummy 0x0000 to clock out data
    uint16_t dummy = 0x0000;

    // Perform two-cycle SPI read
    if (writeSpi(spi_channel, read_cmd) != 2 || writeSpi(spi_channel, dummy) != 1) {
        fprintf(stderr, "SPI transfer failed\n");
        return;
    }

    // Wait for stall time
    usleep(40000); // 40 microseconds

    // Read gyroscope data
    uint16_t gyro_x = readSpi16(spi_channel, X_GYRO_OUT);
    float gyro_x_degps = (float)gyro_x * GYRO_SCALE;

    // Read gyroscope y and z data
    uint16_t gyro_y = readSpi16(spi_channel, Y_GYRO_OUT);
    float gyro_y_degps = (float)gyro_y * GYRO_SCALE;
    uint16_t gyro_z = readSpi16(spi_channel, Z_GYRO_OUT);
    float gyro_z_degps = (float)gyro_z * GYRO_SCALE;

    // Read accelerometer data
    uint16_t accel_x = readSpi16(spi_channel, X_ACCL_OUT);
    float accel_x_g = (float)accel_x * ACCEL_SCALE;
    uint16_t accel_y = readSpi16(spi_channel, Y_ACCL_OUT);
    float accel_y_g = (float)accel_y * ACCEL_SCALE;
    uint16_t accel_z = readSpi16(spi_channel, Z_ACCL_OUT);
    float accel_z_g = (float)accel_z * ACCEL_SCALE;

    // Print formatted values
    printf("Gyro: X=%5.2f deg/s, Y=%5.2f deg/s, Z=%5.2f deg/s\n", gyro_x_degps, gyro_y_degps, gyro_z_degps);
    printf("Accel: X=%5.2f g, Y=%5.2f g, Z=%5.2f g\n", accel_x_g, accel_y_g, accel_z_g);
}

// Function to cleanup resources
void cleanup() {
    // Close SPI device
    close(spi_channel);

    // Set GPIO 8 to low (CE0 inactive)
    gpioWrite(GPIO_NUM_8, 0);

    // Terminate pigpio
    gpioTerminate(gp);
    pigpioTerminate(gp);
}

