#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <stdint.h>
#include <errno.h>
#include <string.h>
#include <termios.h>

#define I2C_DEVICE_PATH "/dev/i2c-1"
#define IMU_ADDRESS 0x68
#define WHO_AM_I_REG 0x75
#define PWR_MGMT_1_REG 0x06
#define ACCEL_CONFIG_REG 0x1C
#define GYRO_CONFIG_REG 0x1B

#define I2C_SLAVE_FILE "/dev/i2c-1"
#define I2C_SLAVE_FD -1

// Sensor registers
#define MPU6886_WHO_AM_I 0x75
#define MPU6886_PWR_MGMT_1 0x06
#define MPU6886_ACCEL_CONFIG 0x1C
#define MPU6886_GYRO_CONFIG 0x1B

// Accelerometer and Gyroscope data registers
#define MPU6886_ACCEL_DATA_REG_START 0x3B
#define MPU6886_ACCEL_DATA_REG_COUNT 6
#define MPU6886_GYRO_DATA_REG_START 0x43
#define MPU6886_GYRO_DATA_REG_COUNT 6

// Function prototypes
void check_i2c_error(int fd);
void read_reg(int fd, uint8_t reg, uint8_t *data, size_t len);
void write_reg(int fd, uint8_t reg, uint8_t value);
void initialize_imu();
void read_sensors_and_print();
void cleanup();

int main() {
    // Initialize I2C slave file descriptor
    I2C_SLAVE_FD = open(I2C_SLAVE_FILE, O_RDWR);
    if (I2C_SLAVE_FD == -1) {
        perror("Failed to open I2C slave file");
        exit(EXIT_FAILURE);
    }

    // Check if the sensor is present
    uint8_t who_am_i;
    if (read_reg(I2C_SLAVE_FD, MPU6886_WHO_AM_I, &who_am_i, 1) == 0) {
        if (who_am_i != 0x86) {
            fprintf(stderr, "Sensor WHO_AM_I register did not return 0x86\n");
            exit(EXIT_FAILURE);
        }
    } else {
        perror("Failed to read WHO_AM_I register");
        exit(EXIT_FAILURE);
    }

    // Initialize the IMU
    initialize_imu();

    // Main loop to read and print sensor data
    while (1) {
        read_sensors_and_print();
        usleep(50000); // Sleep for 50 ms
    }

    // Clean up resources
    cleanup();

    return 0;
}

// Function to check I2C errors
void check_i2c_error(int fd) {
    if (errno == ENODEV || errno == ENXIO) {
        fprintf(stderr, "I2C device not found or not accessible\n");
        exit(EXIT_FAILURE);
    }
    if (errno) {
        perror("I2C error");
        exit(EXIT_FAILURE);
    }
}

// Function to read a register
void read_reg(int fd, uint8_t reg, uint8_t *data, size_t len) {
    int bytes_read;
    do {
        bytes_read = read(I2C_SLAVE_FD, data, len);
    } while (bytes_read != len && --tries > 0);
    if (bytes_read != len) {
        check_i2c_error(fd);
    }
}

// Function to write a register
void write_reg(int fd, uint8_t reg, uint8_t value) {
    int bytes_written;
    do {
        bytes_written = write(I2C_SLAVE_FD, &reg, 1);
        if (bytes_written != 1) {
            perror("Failed to write register address");
            exit(EXIT_FAILURE);
        }
        bytes_written = write(I2C_SLAVE_FD, &value, 1);
        if (bytes_written != 1) {
            perror("Failed to write register value");
            exit(EXIT_FAILURE);
        }
    } while (bytes_written != 1 && --tries > 0);
}

// Function to initialize the IMU
void initialize_imu() {
    // Wake up the IMU
    write_reg(I2C_SLAVE_FD, PWR_MGMT_1_REG, 0x00);

    // Set ACCEL_CONFIG and GYRO_CONFIG to 0x00 for +-2g and +-250 dps ranges
    write_reg(I2C_SLAVE_FD, ACCEL_CONFIG_REG, 0x00);
    write_reg(I2C_SLAVE_FD, GYRO_CONFIG_REG, 0x00);
}

// Function to read sensors and print
void read_sensors_and_print() {
    uint8_t accel_data[6];
    uint8_t gyro_data[6];

    // Read accelerometer data
    for (int i = 0; i < MPU6886_ACCEL_DATA_REG_COUNT; i++) {
        read_reg(I2C_SLAVE_FD, MPU6886_ACCEL_DATA_REG_START + i, accel_data + i, 1);
        printf("Accelerometer X: %d, Y: %d, Z: %d\n", (int)accel_data[i], (int)accel_data[i + 1], (int)accel_data[i + 2]);
    }

    // Read gyroscope data
    for (int i = 0; i < MPU6886_GYRO_DATA_REG_COUNT; i++) {
        read_reg(I2C_SLAVE_FD, MPU6886_GYRO_DATA_REG_START + i, gyro_data + i, 1);
        printf("Gyroscope X: %d, Y: %d, Z: %d\n", (int)gyro_data[i], (int)gyro_data[i + 1], (int)gyro_data[i + 2]);
    }
}

// Function to cleanup resources
void cleanup() {
    if (I2C_SLAVE_FD != -1) {
        close(I2C_SLAVE_FD);
        I2C_SLAVE_FD = -1;
    }
}

