    if (errno == ENODEV || errno == ENXIO) {
        fprintf(stderr, "I2C device not found or not accessible\n");
        exit(EXIT_FAILURE);
    }
    if (errno) {
        perror("I2C error");
        exit(EXIT_FAILURE);
    }
}

// Function to read a register
void read_reg(int fd, uint8_t reg, uint8_t *data, size_t len) {
    int bytes_read;
    do {
        bytes_read = read(I2C_SLAVE_FD, data, len);
    } while (bytes_read != len && --tries > 0);
    if (bytes_read != len) {
        check_i2c_error(fd);
    }
}

// Function to write a register
void write_reg(int fd, uint8_t reg, uint8_t value) {
    int bytes_written;
    do {
        bytes_written = write(I2C_SLAVE_FD, &reg, 1);
        if (bytes_written != 1) {
            perror("Failed to write register address");
            exit(EXIT_FAILURE);
        }
        bytes_written = write(I2C_SLAVE_FD, &value, 1);
        if (bytes_written != 1) {
            perror("Failed to write register value");
            exit(EXIT_FAILURE);
        }
    } while (bytes_written != 1 && --tries > 0);
}

