#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>

#define PIGPIO_ID 0
#define I2C_BUS 1
#define ADXL345_ADDRESS 0x53
#define FULL_RES_SCALE 256
#define RED_LED_GPIO 17

// ADXL345 register addresses
#define REG_ID 0x00
#define REG_CONFIG 0x31
#define REG_DATA_X_L 0x32
#define REG_DATA_X_H 0x33
#define REG_DATA_Y_L 0x34
#define REG_DATA_Y_H 0x35
#define REG_DATA_Z_L 0x36
#define REG_DATA_Z_H 0x37

// Impact threshold in g
#define IMPACT_THRESHOLD 2.5

// Function prototypes
void setup_pigpio();
void setup_i2c();
void read_adxl345(uint8_t reg);
void handle_impact(float magnitude, float x, float y, float z);
void cleanup();

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    setup_pigpio();
    setup_i2c();

    while (1) {
        float magnitude = 0.0;
        float x = 0.0, y = 0.0, z = 0.0;

        // Read ADXL345 ID register
        read_adxl345(REG_ID);

        // Check if the device is ADXL345
        if (read_adxl345(REG_ID) != 0xE5) {
            printf("Device at 0x53 is not an ADXL345!\n");
            continue;
        }

        // Read data registers
        read_adxl345(REG_DATA_X_L);
        read_adxl345(REG_DATA_X_H);
        read_adxl345(REG_DATA_Y_L);
        read_adxl345(REG_DATA_Y_H);
        read_adxl345(REG_DATA_Z_L);
        read_adxl345(REG_DATA_Z_H);

        // Calculate magnitude
        magnitude = sqrt((float)(((uint16_t)REG_DATA_X_H << 8) | REG_DATA_X_L) * (uint16_t)FULL_RES_SCALE * (uint16_t)FULL_RES_SCALE +
                          ((uint16_t)REG_DATA_Y_H << 8) | REG_DATA_Y_L) * ((uint16_t)REG_DATA_Y_L * (uint16_t)FULL_RES_SCALE) +
                          ((uint16_t)REG_DATA_Z_H << 8) | REG_DATA_Z_L) * ((uint16_t)REG_DATA_Z_L * (uint16_t)FULL_RES_SCALE);

        // Check for impact
        if (magnitude > IMPACT_THRESHOLD) {
            handle_impact(magnitude, (float)REG_DATA_X_H / FULL_RES_SCALE, (float)REG_DATA_X_L / FULL_RES_SCALE,
                          (float)REG_DATA_Y_H / FULL_RES_SCALE, (float)REG_DATA_Y_L / FULL_RES_SCALE,
                          (float)REG_DATA_Z_H / FULL_RES_SCALE, (float)REG_DATA_Z_L / FULL_RES_SCALE);
        }

        // Poll every 10 ms
        usleep(10000);

        // Handle SIGINT/SIGTERM
        if (WIFSIGNALED(getpid(), SIGINT) || WIFSIGNALED(getpid(), SIGTERM)) {
            cleanup();
            break;
        }
    }

    return 0;
}

// Function to setup pigpio
void setup_pigpio() {
    pigpio *pi = NULL;
    int rc;

    // Initialize pigpio
    rc = pigpio_init(PIGPIO_ID);
    if (rc == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }

    pi = pigpio_new();
    if (pi == NULL) {
        fprintf(stderr, "Failed to create pigpio instance: %s\n", pigpio_error());
        pigpio_free(pi);
        exit(EXIT_FAILURE);
    }

    // Set up GPIO 17 as output
    rc = pigpio_set_mode(pi, RED_LED_GPIO, pigpioOUTPUT);
    if (rc == -1) {
        fprintf(stderr, "Failed to set GPIO %d as output: %s\n", RED_LED_GPIO, pigpio_error());
        pigpio_free(pi);
        exit(EXIT_FAILURE);
    }

    // Start pigpio daemon in the background
    rc = pigpio_start(pi);
    if (rc == -1) {
        fprintf(stderr, "Failed to start pigpio daemon: %s\n", pigpio_error());
        pigpio_free(pi);
        exit(EXIT_FAILURE);
    }
}

// Function to setup I2C
void setup_i2c() {
    int rc;

    // Initialize I2C
    rc = pigpio_i2c_init(PIGPIO_ID, I2C_BUS);
    if (rc == -1) {
        fprintf(stderr, "Failed to initialize I2C: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }

    // Set I2C address and enable
    rc = pigpio_i2c_address_set(PIGPIO_ID, I2C_BUS, ADXL345_ADDRESS);
    if (rc == -1) {
        fprintf(stderr, "Failed to set I2C address: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }

    // Enable I2C
    rc = pigpio_i2c_enable(PIGPIO_ID, I2C_BUS);
    if (rc == -1) {
        fprintf(stderr, "Failed to enable I2C: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }
}

// Function to read an ADXL345 register
void read_adxl345(uint8_t reg) {
    uint8_t data[2];

    // Read register
    pigpio_i2c_read(PIGPIO_ID, I2C_BUS, ADXL345_ADDRESS, reg, data, 2);

    // Check for I2C errors
    if (data[0] != reg || data[1] != 0) {
        fprintf(stderr, "I2C read error: 0x%X\n", data[0]);
        exit(EXIT_FAILURE);
    }
}

// Function to handle impact
void handle_impact(float magnitude, float x, float y, float z) {
    char timestamp[50];
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *log_file = fopen("impact_log.txt", "a+");
    if (!log_file) {
        fprintf(stderr, "Failed to open impact_log.txt for writing: %s\n", strerror(errno));
        return;
    }

    fprintf(log_file, "Impact detected at %s: Magnitude %f g, Components: X=%f g, Y=%f g, Z=%f g\n", timestamp, magnitude, x, y, z);
    fclose(log_file);

    // Turn on the red LED for 500 ms
    pigpio_write(pi, RED_LED_GPIO, 1);
    usleep(500000);
    pigpio_write(pi, RED_LED_GPIO, 0);
}

// Function to cleanup resources
void cleanup() {
    // Stop pigpio daemon
    pigpio_stop(pi);

    // Free pigpio instance
    pigpio_free(pi);

    // Close log file
    fclose(log_file);

    // Release I2C resources
    pigpio_i2c_disable(PIGPIO_ID, I2C_BUS);
    pigpio_i2c_free(PIGPIO_ID, I2C_BUS);

    // Release GPIO
    pigpio_set_mode(pi, RED_LED_GPIO, pigpioINPUT);
    pigpio_free(pi);
}

