    msg[X_REG].buf = (uint8_t *) "RR";

    msg[Y_REG].addr = TMAG5273_ADDR;
    msg[Y_REG].len = 2;
    msg[Y_REG].buf = (uint8_t *) "RR";

    msg[Z_REG].addr = TMAG5273_ADDR;
    msg[Z_REG].len = 2;
    msg[Z_REG].buf = (uint8_t *) "RR";

    if (ioctl(i2c_fd, I2C_SLAVE, TMAG5273_ADDR) < 0) {
        perror("Failed to change I2C slave address");
        close(i2c_fd);
        return;
    }

    // Perform 3 consecutive 16-bit reads
    for (int reg = X_REG; reg <= Z_REG; reg++) {
        msg[reg].len = 2;
        if (read(i2c_fd, msg + reg, 2) != 3) {
            fprintf(stderr, "Error reading from TMAG5273 register 0x%02X\n", reg);
        }
    }
}

// Function to read magnetic field data from the sensor
int readMagneticFields(int i2c_fd) {
    int bytes_read;

    // Read X register (16-bit little-endian)
    if ((bytes_read = read(i2c_fd, (char *)&(X_REG_data), 2)) != 2) {
        return -1;
    }

    // Read Y register (16-bit little-endian)
    if ((bytes_read = read(i2c_fd, (char *)&(Y_REG_data), 2)) != 2) {
        return -1;
    }

    // Read Z register (16-bit little-endian)
    if ((bytes_read = read(i2c_fd, (char *)&(Z_REG_data), 2)) != 2) {
        return -1;
    }

    return 0;
