#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <fcntl.h>
#include <unistd.h>
#include <poll.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE_PATH "/dev/i2c-1"
#define I2C_ADDR 0x53
#define GPIO_FALLING_EDGE 17
#define ADXL345_INT1_PIN 11

#define THRESH_FF 0x0A
#define TIME_FF 0x20
#define INT_ENABLE 0x2E
#define INT_MAP 0x2F
#define POWER_CTL 0x2D

#define FREEFALL_THRESHOLD 300
#define FREEFALL_TIME_MS 100

#define DATAX0_REG 0x32
#define INT_SOURCE_REG 0x30

#define LOG_FILE_PATH "freefall_log.csv"

struct adxl345_data {
    int fd;
    int gpio_fd;
    int int_status;
    unsigned int int_source;
    float x, y, z;
};

void open_resources() {
    int i2c_fd;
    struct gpiod_dir gpio_dir;
    struct gpiod_cbs gpio_cbs;
    struct adxl345_data adxl345_data;

    // Open I2C device
    i2c_fd = open(I2C_DEVICE_PATH, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Open GPIO pin for falling edge detection
    gpio_dir.direction = GPIO_DIR_IN;
    gpio_dir.function = GPIO_FUNC_GPIO;
    gpio_dir.gpio = GPIO_FALLING_EDGE;
    gpio_fd = gpiod_open(I2C_DEVICE_PATH, &gpio_dir);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO pin");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Set up GPIO callback
    memset(&gpio_cbs, 0, sizeof(gpio_cbs));
    gpio_cbs.cb = freefall_interrupt_handler;
    gpio_cbs.data = &adxl345_data;
    gpiod_cbs_set(gpio_fd, &gpio_cbs);

    adxl345_data.fd = i2c_fd;
    adxl345_data.gpio_fd = gpio_fd;
    adxl345_data.int_status = 0;
    adxl345_data.int_source = 0;
    adxl345_data.x = 0;
    adxl345_data.y = 0;
    adxl345_data.z = 0;

    // Check if ADXL345 is present
    if (i2c_smbus_read_word_data(i2c_fd, 0x00) != 0xE5) {
        fprintf(stderr, "ADXL345 not detected at address 0x53\n");
        close(i2c_fd);
        close(gpio_fd);
        exit(EXIT_FAILURE);
    }
}

void close_resources() {
    if (adxl345_data.fd != -1) {
        close(adxl345_data.fd);
    }
    if (adxl345_data.gpio_fd != -1) {
        gpiod_cbs_stop(adxl345_data.gpio_fd);
        gpiod_close(adxl345_data.gpio_fd);
    }
}

void freefall_interrupt_handler(void *data) {
    struct adxl345_data *adxl345 = data;
    int int_status = adxl345->int_status;

    if (int_status) {
        // Read INT_SOURCE to clear interrupt and check for freefall
        i2c_smbus_read_word_data(adxl345->fd, INT_SOURCE_REG, &adxl345->int_source);
        if ((adxl345->int_source & 0x04) == 0) {
            // Freefall detected
            float timestamp = time(NULL);
            float ms = (float)((time(NULL) - timestamp) * 1000.0);
            char timestamp_str[20];
            sprintf(timestamp_str, "%d.%03d", (int)timestamp, ms);

            // Write to log file
            FILE *log_file = fopen(LOG_FILE_PATH, "a+");
            if (log_file) {
                fprintf(log_file, "%s,%f,%f,%f\n", timestamp_str, adxl345->x, adxl345->y, adxl345->z);
                fclose(log_file);
            } else {
                perror("Failed to open log file");
            }

            // Reset INT_SOURCE to continue monitoring
            adxl345->int_source = 0;
        }
    }
}

void configure_adxl345() {
    unsigned int threshold = THRESH_FF;
    unsigned int time_constant = TIME_FF;

    // Set threshold and time constant
    i2c_smbus_write_word_data(adxl345_data.fd, POWER_CTL, POWER_CTL & ~0x07);
    i2c_smbus_write_word_data(adxl345_data.fd, THRESH_FF, threshold);
    i2c_smbus_write_word_data(adxl345_data.fd, TIME_FF, time_constant);

    // Enable freefall interrupt
    unsigned int int_enable = INT_ENABLE;
    int_enable |= 0x02; // Set bit 2 for INT1
    i2c_smbus_write_word_data(adxl345_data.fd, INT_ENABLE, int_enable);

    // Map INT1 to interrupt
    unsigned int int_map = INT_MAP;
    int_map &= ~0x0F; // Clear lower bits
    i2c_smbus_write_word_data(adxl345_data.fd, INT_MAP, int_map);

    // Enter measurement mode
    i2c_smbus_write_byte_data(adxl345_data.fd, POWER_CTL, POWER_CTL | 0x08);
}

void standby_mode() {
    unsigned int standby = 0x01;
    i2c_smbus_write_byte_data(adxl345_data.fd, 0x00, standby);
}

void poll_loop() {
    struct pollfd i2c_pollfd;
    struct pollfd gpio_pollfd;

    i2c_pollfd.fd = adxl345_data.fd;
    i2c_pollfd.events = POLLIN;

    gpio_pollfd.fd = adxl345_data.gpio_fd;
    gpio_pollfd.events = POLLIN;

    while (1) {
        int i2c_poll_res = poll(&i2c_pollfd, 1, -1);
        int gpio_poll_res = poll(&gpio_pollfd, 1, -1);

        if (i2c_poll_res > 0 && i2c_pollfd.revents & POLLIN) {
            // Read data from ADXL345
            unsigned int data[6];
            i2c_smbus_read_i2c_block_data(adxl345_data.fd, DATAX0_REG, 6, data);
            adxl345_data.x = data[0];
            adxl345_data.y = data[1];
            adxl345_data.z = data[2];
        }

        if (gpio_poll_res > 0 && gpio_pollfd.revents & POLLIN) {
            freefall_interrupt_handler(&adxl345_data);
        }
    }
}

int main() {
    open_resources();
    configure_adxl345();
    standby_mode();

    // Start polling loop
    poll_loop();

    // Handle SIGINT/SIGTERM
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    return 0;
}

void cleanup() {
    close_resources();
    printf("Exiting due to SIGINT/SIGTERM\n");
    exit(EXIT_SUCCESS);
}

