This C program initializes the ADXL345 accelerometer on a Raspberry Pi 4 Model B, sets up a falling-edge interrupt on GPIO17 for detecting freefall events, and logs the X, Y, and Z acceleration values during such events to a CSV file. It uses libgpiod for GPIO management and the Linux i2c-dev interface for I2C communication. The program handles initialization errors, resource cleanup, and gracefully exits on SIGINT or SIGTERM signals.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <pigpio.h>
#include <stdint.h>

// Define constants
#define PIGPIO_ID 0  // Assuming pigpiod is running as the default ID
#define I2C_BUS 1    // I2C bus number
#define IMU_ADDRESS 0x6A // ST LSM6DSR IMU address
#define FREEFALL_THRESHOLD 0.2
#define IMPACT_THRESHOLD 2.5
#define FALL_DURATIONS_1SEC 1000 // 1.0 seconds in milliseconds

// Structure for IMU data
typedef struct {
    int16_t ax;
    int16_t ay;
    int16_t az;
    int16_t gx;
    int16_t gy;
    int16_t gz;
} imu_data_t;

// Function prototypes
void setup_pigpio();
void handle_signal(int signum);
void read_imu_data(imu_data_t *data);
void process_imu_data(imu_data_t *data);
void write_to_log(const char *message);
void fall_detection(imu_data_t *data);

int main() {
    // Initialize pigpio
    setup_pigpio();

    // Signal handler for SIGINT and SIGTERM
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    imu_data_t imu_data;
    int i = 0;
    while (1) {
        // Read IMU data
        if (read_imu_data(&imu_data) == -1) {
            fprintf(stderr, "Error reading IMU data\n");
            break;
        }

        // Process IMU data
        process_imu_data(&imu_data);

        // Check for fall detection
        if (fall_detection(&imu_data)) {
            write_to_log("Fall detected.\n");
        }

        // Log IMU data
        write_to_log("Timestamp,ax,ay,az,gx,gy,gz\n");
        write_to_log(strftime("%F %T", &time_t{}) ",%d,%d,%d,%d,%d,%d\n", imu_data.ax, imu_data.ay, imu_data.az, imu_data.gx, imu_data.gy, imu_data.gz);

        // Sleep to maintain 104 Hz ODR
        usleep(10000);
    }

    // Clean up resources
    close_pigpio();

    return 0;
}

// Function to setup pigpio
void setup_pigpio() {
    if (pi_pigpio_error() != PIGPIO_OK) {
        fprintf(stderr, "Error initializing pigpio: %s\n", pi_pigpio_error_string());
        exit(EXIT_FAILURE);
    }

    // Set GPIO pins for I2C
    int gpio_sda = pigpio_open(GPIO2, PIGPIO_MODE_OUTPUT);
    if (gpio_sda == -1) {
        fprintf(stderr, "Error opening GPIO2: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }

    int gpio scl = pigpio_open(GPIO3, PIGPIO_MODE_OUTPUT);
    if (gpio_scl == -1) {
        fprintf(stderr, "Error opening GPIO3: %s\n", pigpio_error());
        pigpio_close(gpio_sda);
        exit(EXIT_FAILURE);
    }

    // Set SDA and SCL pins to output
    pigpio_write(gpio_sda, 1);
    pigpio_write(gpio_scl, 1);

    // Enable I2C bus 1
    if (pigpio_i2c_start(I2C_BUS) == -1) {
        fprintf(stderr, "Error starting I2C bus %d: %s\n", I2C_BUS, pigpio_error());
        pigpio_close(gpio_sda);
        pigpio_close(gpio_scl);
        exit(EXIT_FAILURE);
    }

    // Check IMU WHO_AM_I
    if (pigpio_i2c_write(I2C_BUS, IMU_ADDRESS, 0x0D) == -1) {
        fprintf(stderr, "Error writing to IMU: %s\n", pigpio_error());
        pigpio_i2c_stop(I2C_BUS);
        pigpio_close(gpio_sda);
        pigpio_close(gpio_scl);
        exit(EXIT_FAILURE);
    }

    // Set IMU range and ODR
    if (pigpio_i2c_write(I2C_BUS, IMU_ADDRESS, 0x19) == -1) {
        fprintf(stderr, "Error setting IMU range: %s\n", pigpio_error());
        pigpio_i2c_stop(I2C_BUS);
        pigpio_close(gpio_sda);
        pigpio_close(gpio_scl);
        exit(EXIT_FAILURE);
    }

    pigpio_i2c_stop(I2C_BUS);
    pigpio_close(gpio_sda);
    pigpio_close(gpio_scl);
}

// Signal handler function
void handle_signal(int signum) {
    // Clean up resources on SIGINT/SIGTERM
    close_pigpio();
    exit(EXIT_SUCCESS);
}

// Function to read IMU data
int read_imu_data(imu_data_t *data) {
    int ret = pigpio_i2c_read(I2C_BUS, IMU_ADDRESS, 0x3B, data, sizeof(imu_data_t));
    if (ret != sizeof(imu_data_t)) {
        fprintf(stderr, "Error reading IMU data: %d bytes read\n", ret);
        return -1;
    }

    return 0;
}

// Function to process IMU data
void process_imu_data(imu_data_t *data) {
    // Calculate acceleration magnitude
    float acc_magnitude = sqrt(data->ax * data->ax + data->ay * data->ay + data->az * data->az);

    // Check for freefall and impact
    if (acc_magnitude < FREEFALL_THRESHOLD) {
        // Freefall detected
        fall_detection(data);
    } else if (acc_magnitude > IMPACT_THRESHOLD) {
        // Impact detected
        fall_detection(data);
    }
}

// Function to write to log file
void write_to_log(const char *message) {
    FILE *file = fopen("motion_log.txt", "a+");
    if (!file) {
        fprintf(stderr, "Error opening motion_log.txt for append: %s\n", strerror(errno));
        return;
    }

    fprintf(file, "%s\n", message);
    fclose(file);
}

// Function to detect fall
void fall_detection(imu_data_t *data) {
    static int freefall_duration = 0;
    static int impact_duration = 0;

    // Check for freefall condition
    if (acc_magnitude < FREEFALL_THRESHOLD && freefall_duration < FALL_DURATIONS_1SEC) {
        freefall_duration++;
        if (freefall_duration >= FALL_DURATIONS_1SEC) {
            // Freefall detected
            fprintf(stderr, "Freefall detected.\n");
            // Implement appropriate action here (e.g., send alert)
        }
    }

    // Check for impact condition
    if (acc_magnitude > IMPACT_THRESHOLD && impact_duration < FALL_DURATIONS_1SEC) {
        impact_duration++;
        if (impact_duration >= FALL_DURATIONS_1SEC) {
            // Impact detected
            fprintf(stderr, "Impact detected.\n");
            // Implement appropriate action here (e.g., stop recording)
        }
