#define GYRO_ADDRESS 0x69
#define CTRL_REG1 0x1D
#define CTRL_REG4 0x1E
#define OUT_X_L 0x28
#define SENSITIVITY 114.285

// Function prototypes
void setup_gyro();
void read_gyro_data(uint8_t *data);
void convert_dps_to_degps(uint16_t raw_value);
void write_reg(uint8_t reg, uint8_t value);
