    signal(SIGINT, handle_signal);
    setup_gyro();
    while (1) {
        uint8_t data[6];
        read_gyro_data(data);
        for (int i = 0; i < 3; ++i) {
            convert_dps_to_degps(data[0]);
            convert_dps_to_degps(data[1]);
            convert_dps_to_degps(data[2]);
            printf("%f,%f,%f\n", (double)data[0] / SENSITIVITY, (double)data[1] / SENSITIVITY, (double)data[2] / SENSITIVITY);
        }
        usleep(10000); // Sleep for 10ms
    }
    gpioTerminate();
    return 0;
}

// Function to setup the gyroscope
void setup_gyro() {
    pigpio *gp = NULL;
    FILE *file = NULL;
    int i2c_fd = -1;
    uint8_t ctrl_reg1_value = 0x0F;
    uint8_t ctrl_reg4_value = 0x00;

    // Initialize pigpio
    if ((gp = pigpio_open()) == NULL) {
        fprintf(stderr, "Failed to open pigpio\n");
        exit(1);
    }

    // Open I2C bus
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) == -1) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        pigpio_close(gp);
        exit(1);
    }

    // Write CTRL_REG1 to enable all axes
    if (write_reg(CTRL_REG1, ctrl_reg1_value) < 3) {
        fprintf(stderr, "Failed to write CTRL_REG1\n");
        close(i2c_fd);
        pigpio_close(gp);
        exit(1);
    }

    // Write CTRL_REG4 for +-250 dps range
    if (write_reg(CTRL_REG4, ctrl_reg4_value) < 3) {
        fprintf(stderr, "Failed to write CTRL_REG4\n");
        close(i2c_fd);
        pigpio_close(gp);
        exit(1);
    }

    // Check WHO_AM_I register
    if (i2c_smbus_read_word_data(i2c_fd, GYRO_ADDRESS) != 0xD3) {
        fprintf(stderr, "Invalid gyroscope ID (WHO_AM_I != 0xD3)\n");
        close(i2c_fd);
        pigpio_close(gp);
        exit(1);
    }

    // Open file for logging
    if ((file = fopen("gyro_log.csv", "a")) == NULL) {
        fprintf(stderr, "Failed to open gyro_log.csv for writing\n");
        close(i2c_fd);
        pigpio_close(gp);
        exit(1);
    }

    // Close resources on SIGINT
    signal(SIGINT, handle_signal);
}

// Function to read gyroscope data
void read_gyro_data(uint8_t *data) {
    int bytes_read;
    pigpio_i2c_transfer(gp, GYRO_ADDRESS, I2C_WRITE, CTRL_REG1, 1, ctrl_reg1_value);
    pigpio_i2c_transfer(gp, GYRO_ADDRESS, I2C_WRITE, CTRL_REG4, 1, ctrl_reg4_value);
    pigpio_i2c_transfer(gp, GYRO_ADDRESS, I2C_READ, OUT_X_L, 6, data);

    if (bytes_read != 6) {
        fprintf(stderr, "Failed to read gyroscope data\n");
        fclose(file);
        close(i2c_fd);
        pigpio_close(gp);
        exit(1);
    }
}

// Function to convert raw values to degrees per second
void convert_dps_to_degps(uint16_t raw_value) {
    return raw_value / SENSITIVITY;
}

// Function to write a register value
void write_reg(uint8_t reg, uint8_t value) {
    pigpio_i2c_transfer(gp, GYRO_ADDRESS, I2C_WRITE, reg, 1, &value);
}

// Signal handler for graceful termination
void handle_signal(int signum) {
    fprintf(stderr, "Received SIGINT, terminating gracefully...\n");
    fclose(file);
    close(i2c_fd);
    pigpio_close(gp);
    exit(0);
}

