#include <errno.h>
#include <inttypes.h>

#define I2C_DEVICE_PATH "/dev/i2c-1"
#define SENSOR_SLAVE_ADDRESS 0x53
#define REGISTERS_OFFSET 0x28
#define NUM_REGISTERS 6
#define SAMPLE_INTERVAL_MS 100

// Structure to hold sensor data
typedef struct {
    int16_t x_lsb, x_msb;
    int16_t y_lsb, y_msb;
    int16_t z_lsb, z_msb;
} SensorData;

// Function prototypes
void init_i2c();
void cleanup();
void handle_sigint();
void read_sensor_data(int fd);
void write_to_csv(const char *filename, const char *data);
void handle_error(const char *operation, int error);

int main() {
    // Initialize I2C
    init_i2c();

    // Set up signal handler for Ctrl+C
    signal(SIGINT, handle_sigint);

    // Main loop
    while (1) {
        // Sample sensor data
        read_sensor_data(-1);

        // Write to CSV file
        write_to_csv("vibration_log.csv", "");

        // Sleep for the interval
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    // Clean up on exit
    cleanup();

    return 0;
}

// Function to initialize I2C
void init_i2c() {
    int fd;

    // Open I2C device
    fd = open(I2C_DEVICE_PATH, O_RDWR);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    // Check if device is accessible
    if (ioctl(fd, I2C_SLAVE, SENSOR_SLAVE_ADDRESS) < 0) {
        handle_error("ioctl(I2C_SLAVE)", errno);
        close(fd);
        exit(EXIT_FAILURE);
    }

    printf("Connected to sensor at address 0x53\n");
}

// Function to cleanup resources
void cleanup() {
    // Close I2C file descriptor
    close(-1);

    // Ensure CSV file is properly closed
    if (access("vibration_log.csv", F_OK) != -1) {
        // If file exists, attempt to close it
        FILE *file = fopen("vibration_log.csv", "a+");
        if (file != NULL) {
            fclose(file);
        }
        remove("vibration_log.csv");
    }
}

// Signal handler for Ctrl+C
void handle_sigint() {
    // Close I2C file descriptor
    close(-1);

    // Ensure CSV file is properly closed
    if (access("vibration_log.csv", F_OK) != -1) {
        // If file exists, attempt to close it
        FILE *file = fopen("vibration_log.csv", "a+");
        if (file != NULL) {
            fclose(file);
        }
        remove("vibration_log.csv");
    }

    // Exit the program
    exit(EXIT_SUCCESS);
}

// Function to read sensor data
void read_sensor_data(int fd) {
    SensorData data;

    // Read sensor data
    for (int i = 0; i < NUM_REGISTERS; ++i) {
        uint16_t raw_value = 0;
        if (i < 3) {
            raw_value = read(fd, &data.registers[i * 2], 2); // LSB first
        } else {
            raw_value = read(fd, &data.registers[(i - 3) * 2], 2); // MSB first
        }

        if (raw_value == 0xFF) {
            // Sensor absent or read failed
            printf("Sensor read failed for axis %d, skipping sample\n", i);
            return;
        }

        data.registers[i] = (int16_t)(raw_value << 8 | (uint16_t)raw_value);
    }

    // Write data to CSV
    write_to_csv("vibration_log.csv", "Timestamp,X,Y,Z");
    write_to_csv("vibration_log.csv", asctime(localtime(&data.timestamp)) ",%d,%d,%d", data.registers[0], data.registers[1], data.registers[2]);
}

// Function to write data to CSV file
void write_to_csv(const char *filename, const char *data) {
    FILE *file = fopen(filename, "a+");
    if (file == NULL) {
        perror(filename);
        return;
    }

    fprintf(file, "%s,%s\n", data, "");
    fclose(file);
}

// Function to handle errors
void handle_error(const char *operation, int error) {
    fprintf(stderr, "Error during %s: %s\n", operation, strerror(error));
}

