#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <libgpiod/gpiod.h>
#include <unistd.h>
#include <signal.h>

#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 27

// GPIO descriptors for the sensors
struct gpiod_chip *chip;
struct gpiod_line *sensor1_line;
struct gpiod_line *sensor2_line;

// Function prototypes
void setup_gpios();
void read_sensors_and_log();
void handle_signals(int signum);
void cleanup();

int main() {
    // Initialize the GPIO chip and lines
    setup_gpios();

    // Set up signal handlers
    signal(SIGINT, handle_signals);
    signal(SIGTERM, handle_signals);

    // Main loop
    while (1) {
        read_sensors_and_log();
        usleep(50000); // Sleep for 50 ms
    }

    // Clean up on exit
    cleanup();

    return 0;
}

// Function to setup GPIO chip and lines
void setup_gpios() {
    // Open the GPIO chip
    chip = gpiod_chip_open(GPIOD_CHIP_RASPBERRY_PI_4);
    if (chip == NULL) {
        perror("gpiod_chip_open");
        exit(EXIT_FAILURE);
    }

    // Open the lines for the sensors
    sensor1_line = gpiod_line_request_by_label(chip, "gpio" GPIO_NUM_17, GPIOD_LINE_FLAG_BIAS_PULL_UP);
    if (sensor1_line == NULL) {
        perror("gpiod_line_request_by_label");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    sensor2_line = gpiod_line_request_by_label(chip, "gpio" GPIO_NUM_27, GPIOD_LINE_FLAG_BIAS_PULL_UP);
    if (sensor2_line == NULL) {
        perror("gpiod_line_request_by_label");
        gpiod_line_release(sensor1_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_direction(sensor1_line, GPIOD_LINE_DIR_INPUT);
    gpiod_line_set_direction(sensor2_line, GPIOD_LINE_DIR_INPUT);

    gpiod_line_set_bias(sensor1_line, GPIOD_LINE_BIAS_PULL_UP);
    gpiod_line_set_bias(sensor2_line, GPIOD_LINE_BIAS_PULL_UP);

    printf("Sensors initialized successfully.\n");
}

// Function to read sensors and log
void read_sensors_and_log() {
    // Read sensor states
    int sensor1_state = gpiod_line_read(sensor1_line);
    int sensor2_state = gpiod_line_read(sensor2_line);

    // Check if both sensors are triggered
    if (sensor1_state == 1 && sensor2_state == 1) {
        printf("Conveyor halt: Both sensors triggered.\n");
    } else {
        printf("Conveyor running: Sensors %d and %d state.\n", sensor1_state, sensor2_state);
    }

    // Log timestamp and sensor states to file
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char buffer[100];
    sprintf(buffer, "%ld.%06ld SENSOR1: %d SENSOR2: %d\n", ts.tv_sec, (unsigned long)ts.tv_nsec, sensor1_state, sensor2_state);
    fprintf(stderr, "%s", buffer);

    // Flush the buffer to disk
    fflush(stderr);
}

// Signal handler to handle SIGINT and SIGTERM
void handle_signals(int signum) {
    printf("Received signal %d, shutting down...\n", signum);
    // Clean up GPIO and exit
    cleanup();
    exit(EXIT_SUCCESS);
}

// Function to cleanup resources
void cleanup() {
    // Release GPIO lines
    gpiod_line_release(sensor2_line);
    gpiod_line_release(sensor1_line);

    // Close the GPIO chip
    gpiod_chip_close(chip);

    // Reset any other resources if necessary
    // Example: fclose(stderr);
}

