        return;
    }

    // Clear bit 0 (standby to active mode) and set data rate bits
    uint8_t ctrl_reg1 = 0x4A; // 0b01000010 (Clear bit 0, set bits 3-5 to 0)
    if (write(i2c_fd, &ctrl_reg1, 1) != 1) {
        perror("Failed to write to CTRL_REG1");
        return;
