#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <stdint.h>

#define LIS3MDL_ADDR 0x1E
#define WHO_AM_I_REG 0x0F
#define CTRL_REG1 0x01
#define CTRL_REG4 0x04
#define CTRL_REG3 0x03
#define MAG_X_REG 0x28
#define MAG_Y_REG 0x29
#define MAG_Z_REG 0x2A

#define MAX_ATTEMPTS 3
#define THRESHOLD_MAGNETIC_FIELD 800.0
#define SENSITIVITY 0.146  // mG/LSB

// Calibration constants (offset and scale)
const int16_t offset[3] = {0, 0, 0};
const int16_t scale[3] = {1, 1, 1};

// Function prototypes
void init_lis3mdl();
void read_magnetic_fields(int fd);
void write_control_registers(int fd, uint8_t reg, uint8_t value);
void handle_interrupt_signals();
void cleanup();

int main() {
    int fd;
    int attempts = 0;
    char magnetic_log_path[100] = "magnetic_log.txt";
    char line[256];

    // Attempt to open I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd == -1) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Attempt initialization up to 3 times
    while (attempts < MAX_ATTEMPTS) {
        init_lis3mdl(fd);
        attempts++;
        if (attempts == MAX_ATTEMPTS) {
            fprintf(stderr, "Failed to initialize LIS3MDL after %d attempts\n", MAX_ATTEMPTS);
            close(fd);
            return EXIT_FAILURE;
        }
        // Check WHO_AM_I register
        uint8_t who_am_i;
        read_reg(fd, WHO_AM_I_REG, &who_am_i);
        if (who_am_i != 0x3D) {
            fprintf(stderr, "WHO_AM_I register failed: 0x%X\n", who_am_i);
            close(fd);
            return EXIT_FAILURE;
        }
        // Enable continuous conversion mode and high-performance mode
        write_control_registers(fd, CTRL_REG1, 0x70);
        write_control_registers(fd, CTRL_REG4, 0x0C);
        write_control_registers(fd, CTRL_REG3, 0x00);
    }

    // Open log file for appending
    FILE *log_file = fopen(magnetic_log_path, "a+");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        read_magnetic_fields(fd);
        // Convert and calculate total magnetic field magnitude
        float x_mg = (float)read_reg(fd, MAG_X_REG) * scale[0] - offset[0];
        float y_mg = (float)read_reg(fd, MAG_Y_REG) * scale[1] - offset[1];
        float z_mg = (float)read_reg(fd, MAG_Z_REG) * scale[2] - offset[2];
        float total_magnetic_field = sqrt(x_mg * x_mg + y_mg * y_mg + z_mg * z_mg);
        if (total_magnetic_field > THRESHOLD_MAGNETIC_FIELD) {
            fprintf(stderr, "Metal detector alert: Total field magnitude exceeds %f mG\n", THRESHOLD_MAGNETIC_FIELD);
        }
        // Append X, Y, Z values to log file
        sprintf(line, "%f,%f,%f,", x_mg, y_mg, z_mg);
        fprintf(log_file, line);
        fflush(log_file);
    }

    // Handle SIGINT/SIGTERM
    handle_interrupt_signals();

    // Cleanup
    cleanup();

    return EXIT_SUCCESS;
}

// Function to initialize LIS3MDL
void init_lis3mdl(int fd) {
    uint8_t reg;
    // Write to CTRL_REG1 to enable continuous conversion mode
    write_control_registers(fd, CTRL_REG1, 0x70);
    // Write to CTRL_REG4 to enable high-performance mode
    write_control_registers(fd, CTRL_REG4, 0x0C);
    // Write to CTRL_REG3 to set continuous conversion mode
    write_control_registers(fd, CTRL_REG3, 0x00);
}

// Function to write a register value
void write_control_registers(int fd, uint8_t reg, uint8_t value) {
    if (ioctl(fd, I2C_SLAVE, LIS3MDL_ADDR) < 0) {
        perror("Failed to change I2C slave address");
        return;
    }
    if (ioctl(fd, I2C_WRITE, (char *)&reg) < 0) {
        perror("Failed to write register address");
        return;
    }
    if (ioctl(fd, I2C_WRITE, &value) < 0) {
        perror("Failed to write register value");
        return;
    }
}

// Function to read a register value
uint8_t read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (ioctl(fd, I2C_READ, (char *)&reg) < 0) {
        perror("Failed to read register address");
        return 0;
    }
    if (ioctl(fd, I2C_READ, value) < 0) {
        perror("Failed to read register value");
        return 0;
    }
    return *value;
}

// Function to handle SIGINT and SIGTERM
void handle_interrupt_signals() {
    struct sigaction sa;
    sa.sa_handler = SIG_IGN;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

// Function to cleanup resources
void cleanup() {
    if (fd != -1) {
        close(fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

// Helper function to print error messages
void perror(const char *msg) {
    fprintf(stderr, "%s\n", msg);
}

