#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <pigpio.h>
#include <stdint.h>

#define SPI_CHANNEL 0
#define SPI_CLOCK_SPEED 1000000
#define SPI_MODE 0
#define ADXL354B_RESET_REG 0x1F
#define ADXL354B_STATUS_REG 0x04
#define ADXL354B_POWER_CTL_REG 0x2D
#define ADXL354B_XDATA_REG 0x08
#define ADXL354B_YDATA_REG 0x0B
#define ADXL354B_ZDATA_REG 0x0E
#define ADXL354B_PARTID_REG 0x01

#define SPI_READ_BITMASK (1 << 7) // Read bit
#define SPI_MULTI_BYTE_BITMASK (1 << 6) // Multi-byte read bit

// Constants for ADXL354B
#define ADXL354B_SENSITIVITY 0.0000039 // g/LSB
#define ADXL354B_RANGE +-2G

// Function prototypes
void handle_signal(int signum);
void reset_and_configure_accelerometer(pigpio *pi);
void read_accelerometer_data(pigpio *pi);
void write_reg(pigpio *pi, uint8_t reg, uint8_t value);
void read_reg(pigpio *pi, uint8_t reg, uint8_t *value);
void log_acceleration_data(float x, float y, float z, double timestamp);
void cleanup_resources(pigpio *pi);

int main() {
    pigpio *pi = NULL;
    uint8_t partid;
    uint8_t xdata, ydata, zdata;
    double timestamp;
    int retries = 3;
    int status;

    // Initialize pigpio
    if ((pi = pigpio_open()) == NULL) {
        fprintf(stderr, "Failed to open pigpio: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }

    // Reset and configure the accelerometer
    reset_and_configure_accelerometer(pi);

    // Handle signals for graceful shutdown
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        // Read accelerometer data
        if ((status = read_accelerometer_data(pi)) != 0) {
            fprintf(stderr, "Error reading accelerometer data: %d\n", status);
            break;
        }

        // Log data
        log_acceleration_data((float)xdata / ADXL354B_SENSITIVITY, (float)ydata / ADXL354B_SENSITIVITY, (float)zdata / ADXL354B_SENSITIVITY, timestamp);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up resources
    cleanup_resources(pi);

    // Close pigpio
    pigpio_close(pi);

    return 0;
}

// Function to reset and configure the accelerometer
void reset_and_configure_accelerometer(pigpio *pi) {
    // Write RESET command
    write_reg(pi, ADXL354B_RESET_REG, 0x52);
    usleep(1000); // Wait 1 ms

    // Configure measurement mode
    write_reg(pi, ADXL354B_POWER_CTL_REG, 0x00); // Clear RUN bit
    while (read_reg(pi, ADXL354B_STATUS_REG) & (1 << 7)); // Wait for STABLE bit

    // Set RUN bit
