#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdint.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD_RATE 1000000
#define SPI_MODE 3
#define ADIS16362_REG_X_GYRO 0x04
#define ADIS16362_REG_Y_GYRO 0x06
#define ADIS16362_REG_Z_GYRO 0x08
#define ADIS16362_REG_X_ACCL 0x0A
#define ADIS16362_REG_Y_ACCL 0x0C
#define ADIS16362_REG_Z_ACCL 0x0E
#define SCALE_GYRO 0.05
#define SCALE_ACCL 0.0025
#define SAMPLE_RATE_HZ 100
#define DELAY_MS 10

// Function prototypes
void handle_signal(int signum);
void read_imu_data();
void write_to_csv(const char *data);
void close_resources_gracefully();

// Global variables
pigpio *pi;
FILE *csv_file;
uint16_t gyro_data[3];
uint16_t accel_data[3];

// Main function
int main() {
    // Initialize pigpio
    if (pi == NULL) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    // Open SPI channel 0
    if (pigpio_spi_open(pi, SPI_CHANNEL, SPI_BAUD_RATE, SPI_MODE) == -1) {
        fprintf(stderr, "Failed to open SPI channel %d\n", SPI_CHANNEL);
        pigpio_close(pi);
        return EXIT_FAILURE;
    }

    // Signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, handle_signal);

    // Open CSV file for writing
    if ((csv_file = fopen("imu_log.csv", "a")) == NULL) {
        fprintf(stderr, "Failed to open CSV file for writing\n");
        pigpio_spi_close(pi, SPI_CHANNEL);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Read IMU data
        read_imu_data();

        // Delay for 10 ms
        usleep(SAMPLE_RATE_HZ * 1000);

        // Write data to CSV file
        write_to_csv(gyro_data, accel_data);

        // Check for Ctrl+C
        if (pi_is_running(pi)) {
            break;
        }
    }

    // Close resources gracefully on SIGINT
    handle_signal(SIGINT);

    return EXIT_SUCCESS;
}

// Function to read IMU data
void read_imu_data() {
    uint16_t address;
    uint16_t dummy;

    // Read gyroscope data
    address = ADIS16362_REG_X_GYRO;
    spiXfer(pi, 0x01, // Write MSB of address
            address, // Address
            0x00,    // Dummy byte
            &dummy); // Receive dummy byte

    gyro_data[0] = (dummy << 8) | spiXfer(pi, 0x03, // Read 16-bit data
                                             0x00, // Register address
                                             NULL); // No dummy byte

    address = ADIS16362_REG_Y_GYRO;
    spiXfer(pi, 0x01, address, 0x00, &dummy);
    gyro_data[1] = (dummy << 8) | spiXfer(pi, 0x03, 0x06, NULL);

    address = ADIS16362_REG_Z_GYRO;
    spiXfer(pi, 0x01, address, 0x00, &dummy);
    gyro_data[2] = (dummy << 8) | spiXfer(pi, 0x03, 0x08, NULL);

    // Read accelerometer data
    address = ADIS16362_REG_X_ACCL;
    spiXfer(pi, 0x01, address, 0x00, &dummy);
    accel_data[0] = (dummy << 8) | spiXfer(pi, 0x03, 0x0A, NULL);

    address = ADIS16362_REG_Y_ACCL;
    spiXfer(pi, 0x01, address, 0x00, &dummy);
    accel_data[1] = (dummy << 8) | spiXfer(pi, 0x03, 0x0C, NULL);

    address = ADIS16362_REG_Z_ACCL;
    spiXfer(pi, 0x01, address, 0x00, &dummy);
    accel_data[2] = (dummy << 8) | spiXfer(pi, 0x03, 0x0E, NULL);
}

// Function to write data to CSV file
void write_to_csv(const char *gyro_data_str, const char *accel_data_str) {
    char timestamp[50];
    time_t timestamp_seconds = time(NULL);
    struct timespec timestamp_nanoseconds;
    clock_gettime(CLOCK_REALTIME, &timestamp_nanoseconds);

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%ns", &timestamp_seconds);

    // Write header
    if (fwrite("Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n", 1, sizeof(timestamp), csv_file) < 0) {
        fprintf(stderr, "Failed to write to CSV file\n");
        fclose(csv_file);
        return;
    }

    // Write data
    if (fwrite(gyro_data_str, 1, strlen(gyro_data_str), csv_file) < 0 ||
        fwrite(accel_data_str, 1, strlen(accel_data_str), csv_file) < 0) {
        fprintf(stderr, "Failed to write data to CSV file\n");
        fclose(csv_file);
        return;
    }
}

// Function to close resources gracefully
void close_resources_gracefully() {
    // Close SPI channel
    pigpio_spi_close(pi, SPI_CHANNEL);

    // Close CSV file
    fclose(csv_file);

    // Terminate GPIO
    pigpioTerminate(pi);
}

// Signal handler for SIGINT
void handle_signal(int signum) {
    close_resources_gracefully();
    exit(EXIT_SUCCESS);
}

