    }

    // Open the GPIO line for GPIO17
    if (gpiod_line_open(CHIP_NAME, GPIO_PIN) < 0) {
        fprintf(stderr, "Error opening GPIO line: %s\n", gpiod_error_string(gpiod_last_error()));
        gpiod_chip_close(CHIP_NAME);
        return EXIT_FAILURE;
    }

    // Request the line for input direction
    if (gpiod_line_request_input(CHIP_NAME, GPIO_PIN) < 0) {
        fprintf(stderr, "Error requesting input direction: %s\n", gpiod_error_string(gpiod_last_error()));
        gpiod_line_close(CHIP_NAME, GPIO_PIN);
        gpiod_chip_close(CHIP_NAME);
        return EXIT_FAILURE;
    }

    // Main loop to poll the sensor
    while (1) {
        // Read the GPIO line value
        int value = gpiod_line_get_value(CHIP_NAME, GPIO_PIN);
        if (value == DETECTION_THRESHOLD) {
            // Obstacle detected
            selfParkingSequenceStarted("Self-parking sequence started at " __TIME__);
            // Simulate self-parking logic here
            // For simplicity, just print a completion message after a delay
            sleep(1);
            selfParkingSequenceCompleted();
        }

        // Poll every second
        sleep(1);
    }

    // Clean up on SIGINT (Ctrl+C)
    struct sigaction sa;
    sa.sa_handler = SIG_IGN; // Ignore SIGINT for demonstration; normally handle gracefully
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Close the line and chip
    gpiod_line_close(CHIP_NAME, GPIO_PIN);
    gpiod_chip_close(CHIP_NAME);

    return EXIT_SUCCESS;
}

