#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <gpiod.h>

#define GPIO17 11
#define GPIO27 13

int main(void) {
    struct gpio_chip *chip;
    struct gpiod_line *lines[2];
    int ret, i;
    unsigned int values[2];
    time_t timestamp;

    // Initialize libgpiod
    if ((ret = gpiod_chip_lookup("gpiochip-bcm2708", &chip)) != 0) {
        fprintf(stderr, "Error: Could not find the GPIO chip.\n");
        return EXIT_FAILURE;
    }

    // Request GPIO lines for input
    if ((ret = gpiod_line_request(chip, GPIO17, GPIOD_LINE_INPUT) < 0) ||
        (ret = gpiod_line_request(chip, GPIO27, GPIOD_LINE_INPUT) < 0)) {
        fprintf(stderr, "Error: Could not request GPIO lines.\n");
        gpiod_chip_free(chip);
        return EXIT_FAILURE;
    }

    lines[0] = gpiod_line_get(chip, GPIO17);
    lines[1] = gpiod_line_get(chip, GPIO27);

    // Bulk-read GPIO lines
    while (1) {
        // Request values
        if ((ret = gpiod_line_request_get_values(lines, 2, values)) != 2) {
            fprintf(stderr, "Error: Failed to read GPIO values.\n");
            // Release lines and chip here before exiting
            for (i = 0; i < 2; i++) {
                gpiod_line_put(lines[i], GPIOD_LINE_UNINIT);
            }
            gpiod_chip_free(chip);
            return EXIT_FAILURE;
        }

        // Read values
        for (i = 0; i < 2; i++) {
            if (values[i] == 0) {
                printf("Obstacle detected on GPIO %u at %s\n", GPIO17 + 1, ctime(&timestamp));
            } else {
                printf("Clear path on GPIO %u at %s\n", GPIO17 + 1, ctime(&timestamp));
            }
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    for (i = 0; i < 2; i++) {
        gpiod_line_put(lines[i], GPIOD_LINE_UNINIT);
    }
    gpiod_chip_free(chip);

    return EXIT_SUCCESS;
}

