#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <gpiod.h>
#include <spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 3
#define SPI_CLOCK_FREQ_HZ 1000000
#define ADIS16266_CS_LINE GPIO_NUM_8

// ADIS16266 register addresses
#define MSC_CTRL_REG 0x24
#define X_RATE_REG 0x04
#define Y_RATE_REG 0x06
#define Z_RATE_REG 0x08

// Scale factor for converting raw data to angular rates
#define SCALE_FACTOR 0.02

// Function prototypes
void setup_spi_and_cs();
void read_gyroscope_data(uint16_t* x_rate, uint16_t* y_rate, uint16_t* z_rate);
void cleanup();
void handle_signal(int signum);

int main() {
    // Initialize signal handler for SIGINT
    signal(SIGINT, handle_signal);

    // Main loop
    while (1) {
        // Perform SPI and CS setup
        setup_spi_and_cs();

        // Read gyroscope data
        uint16_t x_rate_data, y_rate_data, z_rate_data;
        read_gyroscope_data(&x_rate_data, &y_rate_data, &z_rate_data);

        // Convert raw data to angular rates and log
        float x_rate_degps = (float)x_rate_data * SCALE_FACTOR;
        float y_rate_degps = (float)y_rate_data * SCALE_FACTOR;
        float z_rate_degps = (float)z_rate_data * SCALE_FACTOR;
        printf("X: %.4f deg/s, Y: %.4f deg/s, Z: %.4f deg/s\n", x_rate_degps, y_rate_degps, z_rate_degps);

        // Wait for 100 ms
        usleep(100000);

        // Cleanup resources
        cleanup();
    }
}

// Function to setup SPI and CS line
void setup_spi_and_cs() {
    int spi_fd;
    struct spi_device *spi;
    gpiod_set_data_direction(GPIO_NUM_8, GPIODIRECTION_OUT_INIT_LOW);

    // Open SPI device
    if ((spi_fd = open(SPI_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    // Initialize SPI device
    if (spidev_open(spi_fd, SPI_MODE) < 0) {
        perror("Failed to open SPI device");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    spi = spidev_open(spi_fd, SPI_MODE);
    if (!spi) {
        perror("Failed to open SPI device");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set SPI clock frequency
    if (spidev_set_clock(spi, SPI_CLOCK_FREQ_HZ) < 0) {
        perror("Failed to set SPI clock frequency");
        spidev_close(spi);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Enable chip select line
    if (gpiod_set_value(GPIO_NUM_8, GPIODIRECTION_OUTPUT, 1) < 0) {
        perror("Failed to set CS line high");
        spidev_close(spi);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
}

// Function to read gyroscope data using ADIS16266 two-transfer read protocol
void read_gyroscope_data(uint16_t* x_rate, uint16_t* y_rate, uint16_t* z_rate) {
    uint16_t address = (MSC_CTRL_REG << 8) | 0x01; // Set MSB and enable data ready mode

    // Write to MSC_CTRL register
    if (spidev_write16(spi, address) < 0) {
        perror("Failed to write to MSC_CTRL");
        return;
    }

    // Read X rate data
    if (spidev_read16(spi, X_RATE_REG) < 0) {
        perror("Failed to read X rate");
        return;
    }
    *x_rate = spidev_readw(spi, X_RATE_REG);

    // Read Y rate data
    if (spidev_read16(spi, Y_RATE_REG) < 0) {
        perror("Failed to read Y rate");
        return;
    }
    *y_rate = spidev_readw(spi, Y_RATE_REG);

    // Read Z rate data
    if (spidev_read16(spi, Z_RATE_REG) < 0) {
        perror("Failed to read Z rate");
        return;
    }
    *z_rate = spidev_readw(spi, Z_RATE_REG);
}

// Function to cleanup resources
void cleanup() {
    // Release SPI device
    spidev_close(spi);
    close(spi_fd);

    // Release CS line
    gpiod_set_value(GPIO_NUM_8, GPIODIRECTION_OUTPUT, 0);
}

// Signal handler for SIGINT
void handle_signal(int signum) {
    // Clean up resources
    cleanup();
    exit(EXIT_SUCCESS);
}

