This C program initializes SPI communication and a GPIO line for chip select (CS) on a Raspberry Pi 4 Model B using the `libgpiod` and `spidev` libraries. It communicates with an Analog Devices ADIS16266 gyroscope over SPI0 (CE0 on GPIO8) configured for SPI Mode 3, MSB first, at a 1 MHz clock speed. The program periodically reads the gyroscope's X, Y, and Z angular rate registers, converts the raw data to angular rates using a scale factor, and logs the results to the console every 100 ms. It includes robust error handling and ensures resources are released properly on exit, including in response to a SIGINT signal.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>

// Define the sensitivity constants
#define GYRO_SENSITIVITY 0.00875 // mdps/LSB
#define ACCEL_SENSITIVITY 0.000061 // mg/LSB

// Function prototypes
void handleInterrupt(int signum);
void read_sensors(struct pigpio *gp);
void cleanup(struct pigpio *gp);

// Global variables
struct pigpio *gp;
uint8_t i2c_addr = 0x6B;
uint8_t i2c_bus = 1;

// SIGINT handler
void handleInterrupt(int signum) {
    fprintf(stderr, "Interrupt received, shutting down...\n");
    cleanup(gp);
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (pigpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error());
        return EXIT_FAILURE;
    }

    // Install SIGINT handler
    signal(SIGINT, handleInterrupt);

    // Open I2C bus
    if (pigpio_i2c_open(i2c_bus, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", pigpio_error());
        pigpio_exit();
        return EXIT_FAILURE;
    }

    // Verify sensor presence
    uint8_t who_am_i;
    if (pigpio_i2c_read(i2c_bus, i2c_addr, &who_am_i, 1) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register: %s\n", pigpio_error());
        pigpio_i2c_close(i2c_bus);
        pigpio_exit();
        return EXIT_FAILURE;
    }
    if (who_am_i != 0x6B) {
        fprintf(stderr, "WHO_AM_I register mismatch (expected 0x6B)\n");
        pigpio_i2c_close(i2c_bus);
        pigpio_exit();
        return EXIT_FAILURE;
    }

    // Configure the sensor
    if (pigpio_i2c_write(i2c_bus, i2c_addr, 0x00, 1) < 0) {
        fprintf(stderr, "Failed to write CTRL_REG1_XL: %s\n", pigpio_error());
        pigpio_i2c_close(i2c_bus);
        pigpio_exit();
        return EXIT_FAILURE;
    }
    if (pigpio_i2c_write(i2c_bus, i2c_addr, 0x01, 1) < 0) {
        fprintf(stderr, "Failed to write CTRL_REG2_G: %s\n", pigpio_error());
        pigpio_i2c_close(i2c_bus);
        pigpio_exit();
        return EXIT_FAILURE;
    }

    // Configure CTRL1_XL for +-2g full-scale
    if (pigpio_i2c_write(i2c_bus, i2c_addr, 0x42, 1) < 0) {
        fprintf(stderr, "Failed to write CTRL1_XL: %s\n", pigpio_error());
        pigpio_i2c_close(i2c_bus);
        pigpio_exit();
        return EXIT_FAILURE;
    }

    // Configure CTRL2_G for +-250 dps
    if (pigpio_i2c_write(i2c_bus, i2c_addr, 0x42, 1) < 0) {
        fprintf(stderr, "Failed to write CTRL2_G: %s\n", pigpio_error());
        pigpio_i2c_close(i2c_bus);
        pigpio_exit();
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Read sensors
        read_sensors(gp);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    cleanup(gp);

    return EXIT_SUCCESS;
}

// Function to read sensors
void read_sensors(struct pigpio *gp) {
    uint8_t data[12];
    int bytes_read;

    // Read data from the sensor
    if (pigpio_i2c_read(gp, i2c_bus, i2c_addr, 0x22, data, sizeof(data)) < 0) {
        fprintf(stderr, "Failed to read data: %s\n", pigpio_error());
        return;
    }
    if (bytes_read != sizeof(data)) {
        fprintf(stderr, "Short or failed burst read\n");
        return;
    }

    // Convert data to physical units
    float gyro_x = (data[0] * GYRO_SENSITIVITY) - 500.0; // Subtract 500 for zero-rate output
    float gyro_y = (data[1] * GYRO_SENSITIVITY) - 500.0;
    float gyro_z = (data[2] * GYRO_SENSITIVITY) - 500.0;

    float accel_x = (data[3] * ACCEL_SENSITIVITY) - 500.0; // Subtract 500 for zero-rate output
    float accel_y = (data[4] * ACCEL_SENSITIVITY) - 500.0;
    float accel_z = (data[5] * ACCEL_SENSITIVITY) - 500.0;

    // Print sensor data
    fprintf(stdout, "Gyro X: %.2f dps, Gyro Y: %.2f dps, Gyro Z: %.2f dps, Accel X: %.2f g, Accel Y: %.2f g, Accel Z: %.2f g\n",
            gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);

    // Check for interrupt signal
    if (signal_pending(SIGINT)) {
        fprintf(stderr, "SIGINT received, exiting...\n");
        break;
    }
}

// Function to cleanup resources
void cleanup(struct pigpio *gp) {
    // Close I2C bus
    pigpio_i2c_close(i2c_bus);

    // Terminate pigpio library
    pigpioTerminate(gp);
}

