// Function to initialize the sensor
void initialize_sensor(pigpio *pi) {
    // Check if I2C bus is available
    if (pigpio_i2c_available(I2C_BUS) == 0) {
        fprintf(stderr, "I2C bus not available.\n");
        exit(EXIT_FAILURE);
    }

    // Open I2C bus
    int i2c_handle = pigpio_i2c_open(I2C_BUS);
    if (i2c_handle == -1) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }

    // Check if sensor is present
    uint8_t who_am_i;
    if (pigpio_i2c_read(i2c_handle, I2C_ADDRESS, WHO_AM_I, 1, &who_am_i) != 1) {
        fprintf(stderr, "Sensor not found (WHO_AM_I = %02X)\n", who_am_i);
        pigpio_i2c_close(i2c_handle);
        exit(EXIT_FAILURE);
