        fprintf(stderr, "Unexpected WHO_AM_I value: %02X\n", who_am_i);
        pigpio_i2c_close(i2c_handle);
        exit(EXIT_FAILURE);
    }

    // Configure CTRL_REG1 and CTRL_REG2 for hybrid mode
    uint8_t ctrl_reg1 = 0x00; // Hybrid mode
    uint8_t ctrl_reg2 = 0x00; // Continuous output

    if (pigpio_i2c_write(i2c_handle, I2C_ADDRESS, CTRL_REG1, 1, &ctrl_reg1) != 1) {
        fprintf(stderr, "Failed to write to CTRL_REG1: %s\n", pigpio_error());
        pigpio_i2c_close(i2c_handle);
        exit(EXIT_FAILURE);
    }
    if (pigpio_i2c_write(i2c_handle, I2C_ADDRESS, CTRL_REG2, 1, &ctrl_reg2) != 1) {
        fprintf(stderr, "Failed to write to CTRL_REG2: %s\n", pigpio_error());
        pigpio_i2c_close(i2c_handle);
        exit(EXIT_FAILURE);
    }

