    uint8_t m_ctrl_reg1 = 0x00; // Continuous output
    uint8_t m_ctrl_reg2 = 0x00; // High resolution

    if (pigpio_i2c_write(i2c_handle, I2C_ADDRESS, M_CTRL_REG1, 1, &m_ctrl_reg1) != 1) {
        fprintf(stderr, "Failed to write to M_CTRL_REG1: %s\n", pigpio_error());
        pigpio_i2c_close(i2c_handle);
        exit(EXIT_FAILURE);
    }
    if (pigpio_i2c_write(i2c_handle, I2C_ADDRESS, M_CTRL_REG2, 1, &m_ctrl_reg2) != 1) {
        fprintf(stderr, "Failed to write to M_CTRL_REG2: %s\n", pigpio_error());
        pigpio_i2c_close(i2c_handle);
        exit(EXIT_FAILURE);
    }
}

