void read_sensor_data(pigpio *pi) {
    // Read OUT_X_MSB register
    uint8_t out_x_MSB[2];
    if (pigpio_i2c_read(pi->i2c, I2C_ADDRESS, OUT_X_MSB, 2, out_x_MSB) != 2) {
        fprintf(stderr, "Failed to read OUT_X_MSB: %s\n", pigpio_error());
        return;
    }

    // Extract accelerometer data
    int16_t ax = (out_x_MSB[0] << 8) | out_x_MSB[1];
    int16_t ay = 0;
    int16_t az = 0;

    // Extract magnetometer data
    int16_t mx = (out_x_MSB[2] << 8) | out_x_MSB[3];
    int16_t my = (out_x_MSB[4] << 8) | out_x_MSB[5];
    int16_t mz = (out_x_MSB[6] << 8) | out_x_MSB[7];

    // Log sensor data
    printf("Accelerometer: X=%d, Y=%d, Z=%d\n", ax, ay, az);
    printf("Magnetometer: X=%d, Y=%d, Z=%d\n", mx, my, mz);
}

// Function to cleanup resources
void cleanup_resources(pigpio *pi) {
    // Close I2C handle
    pigpio_i2c_close(pi->i2c);

    // Terminate pigpio
    pigpio_free(pi);
}

// Signal handler to catch SIGINT and SIGTERM
void handle_signal(int signum) {
    // Clean up resources
    cleanup_resources(NULL);
    exit(EXIT_FAILURE); // Or handle graceful shutdown if desired
}

