This C program initializes the FXOS8700 accelerometer and magnetometer sensor on a Raspberry Pi 4 Model B using the pigpio library. It reads the combined data block every 100 ms, logs the raw X, Y, and Z values for both sensors, and handles I2C communication errors robustly. On receiving SIGINT or SIGTERM, it cleans up resources and exits.

code:
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <math.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDR 0x53
#define REG_X 0x32
#define REG_Y 0x33
#define REG_Z 0x34
#define THRESHOLD_ANGLE 30.0
#define EVENT_LOG_PATH "/var/log/tilt_events.log"

// Function prototypes
void i2c_init();
void i2c_read(uint8_t reg, int16_t *data);
void calculate_tilt_angles(int16_t x, int16_t y, int16_t z, double *angles);
void log_tilt_event(double angle);
void cleanup();

int main() {
    // Initialize I2C
    i2c_init();

    // Main loop
    while (1) {
        // Read accelerometer data
        int16_t x_data, y_data, z_data;
        i2c_read(REG_X, &x_data);
        i2c_read(REG_Y, &y_data);
        i2c_read(REG_Z, &z_data);

        // Calculate tilt angles
        double x_angle, y_angle, z_angle;
        calculate_tilt_angles(x_data, y_data, z_data, &x_angle);
        calculate_tilt_angles(x_data, y_data, z_data, &y_angle);
        calculate_tilt_angles(x_data, y_data, z_data, &z_angle);

        // Check tilt angles and log events
        if (x_angle > THRESHOLD_ANGLE || y_angle > THRESHOLD_ANGLE || z_angle > THRESHOLD_ANGLE) {
            log_tilt_event(x_angle);
            log_tilt_event(y_angle);
            log_tilt_event(z_angle);
        }

        // Sleep for 100 ms
        usleep(100000);

        // Handle Ctrl+C
        if (signal(SIGINT, SIG_IGN) == SIG_ERR) {
            perror("Failed to ignore SIGINT");
            exit(EXIT_FAILURE);
        }
    }

    // Clean up resources
    cleanup();

    return 0;
}

// Function to initialize I2C
void i2c_init() {
    int fd;
    struct i2c_dev *i2c_dev;

    // Open I2C device
    fd = open(I2C_DEVICE, O_RDWR);
    if (fd == -1) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Get I2C device structure
    i2c_dev = i2c_get_device(fd);
    if (!i2c_dev) {
        perror("Failed to get I2C device");
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Set I2C address
    i2c_set_address(i2c_dev, I2C_ADDR);
}

// Function to read data from specified register
void i2c_read(uint8_t reg, int16_t *data) {
    uint8_t buf[2];
    int ret;

    // Write register address
    buf[0] = reg;
    ret = i2c_smbus_write_byte_data(i2c_dev, buf);

    // Read data
    ret = i2c_smbus_read_i2c_block_data(i2c_dev, reg, 2, buf);
    if (ret != 2) {
        perror("Failed to read data from register");
        exit(EXIT_FAILURE);
    }

    *data = (buf[1] << 8) | buf[0];
}

// Function to calculate tilt angles using atan2
void calculate_tilt_angles(int16_t x, int16_t y, int16_t z, double *angles) {
    *angles = atan2(x, sqrt(y*y + z*z));
}

// Function to log tilt event with timestamp
void log_tilt_event(double angle) {
    char log_entry[256];
    time_t now;
    struct tm *timeinfo;
    FILE *log_file;

    now = time(NULL);
    timeinfo = localtime(&now);

    sprintf(log_entry, "%s %f\n", asctime(timeinfo), angle);

    // Open log file
    log_file = fopen(EVENT_LOG_PATH, "a+");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    // Write to log file
    if (fwrite(log_entry, sizeof(char), strlen(log_entry), log_file) != strlen(log_entry)) {
        perror("Failed to write to log file");
        fclose(log_file);
        return;
    }

    fclose(log_file);
}

// Function to cleanup resources
void cleanup() {
    // Close I2C device
    if (i2c_dev) {
        i2c_put_device(i2c_dev);
        i2c_dev = NULL;
    }

    // Close I2C device file descriptor
    if (fd > 0) {
        close(fd);
        fd = -1;
    }
}

