    pigpio *pi = NULL;
    if (gpioInitialise(&pi) == -1) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", pigpioErrorToString(pigpioError()));
        return EXIT_FAILURE;
    }

    // Set GPIO mode
    if (gpioSetMode(pi, GPIO_PIN, GPIO_INPUT) == -1) {
