    int gpio17_fd = gpiod_open(GPIOD_DEV, "gpio17", "out");
    if (gpio17_fd >= 0) {
        gpiod_set_value(gpio17_fd, 0); // Lock Door A (LOW)
        close(gpio17_fd);
    }

    int gpio27_fd = gpiod_open(GPIOD_DEV, "gpio27", "out");
    if (gpio27_fd >= 0) {
        gpiod_set_value(gpio27_fd, 0); // Lock Door B (LOW)
        close(gpio27_fd);
    }

    // Close any open GPIO chip
    int gpio_chip_fd = gpiod_open(GPIOD_DEV, "gpiochip0", "r");
    if (gpio_chip_fd >= 0) {
        gpiod_close(gpio_chip_fd);
    }
}

