#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <unistd.h>
#include <stdint.h>
#include <signal.h>

#define BH1750_ADDR 0x23
#define BH1750_WRITE_CMD 0x21
#define BH1750_READ_CMD 0x00
#define BH1750_MAX_CONVERSION_TIME_MS 180

// Function prototypes
void handle_signal(int signum);
int open_i2c_bus(int bus_num);
void close_i2c_bus(int bus_fd);
int write_i2c(int bus_fd, uint8_t addr, uint8_t command);
int read_i2c(int bus_fd, uint8_t addr, uint8_t command, uint8_t* data, size_t len);
double calculate_lux(uint16_t raw_value);

// Main function
int main() {
    // Signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, handle_signal);

    // Variables
    int bus_fd = -1;
    uint8_t write_cmd = BH1750_WRITE_CMD;
    uint8_t read_cmd = BH1750_READ_CMD;
    uint8_t data[2];
    uint16_t raw_value;
    char timestamp[50];
    double lux_value;
    FILE* log_file = NULL;
    time_t now;
    struct tm* timeinfo;
    int interval = 5; // Seconds

    // Open I2C bus 1
    bus_fd = open_i2c_bus(1);
    if (bus_fd == -1) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Initialize log file
    log_file = fopen("light_log.txt", "a+");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close_i2c_bus(bus_fd);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Get current time
        now = time(NULL);
        timeinfo = localtime(&now);

        // Format timestamp
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Write command to sensor
        if (write_i2c(bus_fd, BH1750_ADDR, write_cmd) != 2) {
            fprintf(log_file, "Error writing to BH1750 at %s\n", timestamp);
            continue;
        }

        // Wait for conversion
        usleep(BH1750_MAX_CONVERSION_TIME_MS * 1000);

        // Read data from sensor
        if (read_i2c(bus_fd, BH1750_ADDR, read_cmd, data, 2) != 2) {
            fprintf(log_file, "Error reading from BH1750 at %s\n", timestamp);
            continue;
        }

        // Calculate lux value
        raw_value = (data[0] << 8) | data[1];
        lux_value = calculate_lux(raw_value);

        // Write to log file
        fprintf(log_file, "Timestamp: %s, Lux: %.2f\n", timestamp, lux_value);

        // Sleep for interval seconds
        sleep(interval);
    }

    // Close resources
    close_i2c_bus(bus_fd);
    fclose(log_file);

    return 0;
}

// Signal handler for SIGINT
void handle_signal(int signum) {
    fprintf(stderr, "Interrupted by signal %d\n", signum);
    // Clean up resources
    close_i2c_bus(-1);
    fclose(log_file);
    exit(EXIT_FAILURE);
}

// Function to open I2C bus
int open_i2c_bus(int bus_num) {
    int fd;
    if ((fd = open("/dev/i2c-1", O_RDWR)) == -1) {
        perror("open /dev/i2c-1");
        return -1;
    }
    return fd;
}

