void setup_pigpio() {
    pi = pigpioOpen();
    if (pi == NULL) {
        fprintf(stderr, "Failed to open pigpio\n");
        exit(EXIT_FAILURE);
    }
    pigpioSetOverVoltage(pi, 1); // Enable overvoltage protection
}

// Function: setup_mpr121
void setup_mpr121() {
    gpiod_channel *channel;
    channel = gpiod_channel_open(GPIOD_CHANNEL pwm_channel, GPIOD_DIR_OUT_PP);
    if (channel == NULL) {
        fprintf(stderr, "Failed to open GPIO channel for PWM\n");
        exit(EXIT_FAILURE);
    }
    gpiod_set_data(channel, PWM_PIN, 1); // Set pin as output

    // Initialize MPR121
    if (gpiod_i2c_write(MPR121_I2C_ADDR, 0x0D, 0x00) != 2) {
        fprintf(stderr, "Failed to write to MPR121\n");
        exit(EXIT_FAILURE);
    }

    // Soft reset and electrode configuration
    if (gpiod_i2c_write(MPR121_I2C_ADDR, 0x0D, 0x01) != 2) {
        fprintf(stderr, "Failed to soft reset MPR121\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < MAX_ELECTRODES; i++) {
        if (gpiod_i2c_write(MPR121_I2C_ADDR, 0x0D, (i + 0x08) & 0x0F) != 2) {
            fprintf(stderr, "Failed to configure electrode %d\n", i);
            exit(EXIT_FAILURE);
        }
    }
}

// Function: handle_touch_data
void handle_touch_data(uint16_t data) {
    if (data > last_touch_data + TOUCH_THRESHOLD) {
        play_tone(mapTouchToFrequency(data), 5000);
        fprintf(stderr, "Touch detected: %d\n", data);
        fwrite(&data, sizeof(uint16_t), 1, stdout); // Log to frequency_log.txt
        last_touch_data = data;
    }
}

// Function: play_tone
void play_tone(float frequency, int duration) {
    int period = 1000000 / frequency; // Calculate period in microseconds
    int duty_cycle = 500; // 50% duty cycle for a sine-like wave
    for (int i = 0; i < duration * 1000; i++) {
        gpiod_set_data(pwm_channel, PWM_PIN, (period / 2) + (duty_cycle / 2));
        usleep(period / 2);
        gpiod_set_data(pwm_channel, PWM_PIN, duty_cycle);
        usleep(duty_cycle);
    }
}

// Function: cleanup
