void signal_handler(int signum) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    setup_pigpio();
    setup_mpr121();

    // Initialize GPIO channel for PWM
    pthread_create(&touch_thread, NULL, &handle_touch_data, NULL);

    // TCP server setup
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(PORT);
    server_addr.sin_addr.s_addr = INADDR_ANY;

    socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd == -1) {
        fprintf(stderr, "Failed to create socket\n");
        exit(EXIT_FAILURE);
    }

    if (bind(socket_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) == -1) {
        fprintf(stderr, "Failed to bind socket\n");
        exit(EXIT_FAILURE);
    }

    if (listen(socket_fd, 5) == -1) {
        fprintf(stderr, "Failed to listen on socket\n");
        exit(EXIT_FAILURE);
    }

    addr_len = sizeof(server_addr);
    struct sockaddr_client client_addr;
    int client_fd = accept(socket_fd, (struct sockaddr *)&client_addr, &addr_len);
    if (client_fd == -1) {
        fprintf(stderr, "Failed to accept client connection\n");
        exit(EXIT_FAILURE);
    }

    while (1) {
        if (fgets(buffer, 256, stdin) != NULL && buffer[0] == 'M' && strcmp(buffer + 1, SECRET_KEY) == 0) {
            uint16_t data;
            if (gpiod_i2c_read(MPR121_I2C_ADDR, 0x0A, &data, 1) != 1) {
                fprintf(stderr, "Failed to read from MPR121\n");
                break;
            }
            handle_touch_data(data);
        } else {
            break;
        }
    }

    // Close client socket and cleanup
    close(client_fd);
    cleanup();

    return 0;
}

