This C program uses `pigpio` for GPIO and I2C operations and `gpiod` for direct I2C communication with the MPR121 capacitive touch sensor. It sets up a TCP server listening on port 12345 and processes commands from clients that start with 'MOTION_DETECTED:' followed by the shared secret 'MySecretKey'. Upon receiving such a command, it reads touch data from the MPR121, maps the data to a frequency, and plays the tone for 5 seconds using hardware PWM on GPIO18. The program logs touch data to `frequency_log.txt` and handles errors gracefully. On receiving a signal (SIGINT or SIGTERM), it cleans up resources and terminates.

code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>

#define I2C_DEVICE_PATH "/dev/i2c-1"
#define MAGNETOMETER_ADDRESS 0x1E
#define CTRL_REG1_M_OFFSET 0x20
#define OUT_X_L_M_OFFSET 0x08
#define LED_GPIO_NUM 17
#define PWM_FREQ_HZ 1000000

// Constants for LSM303DLHC register addresses
#define CTRL_REG1_M 0x20

// Function prototypes
void setup_i2c();
void setup_pwm();
void read_magnetometer_data(uint8_t *data);
void compute_magnitude_and_adjust_led(uint16_t z_magnitude);
void handle_signal(int signum);
void cleanup();

int main() {
    // Initialize signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Setup I2C and PWM
    setup_i2c();
    setup_pwm();

    // Main loop
    while (1) {
        // Read magnetometer data
        uint8_t data[6];
        if (ioctl(I2C_DEVICE_PATH, I2C_SLAVE, MAGNETOMETER_ADDRESS) < 0) {
            fprintf(stderr, "Error: Failed to access I2C bus.\n");
            continue;
        }
        if (read_magnetometer_data(data) < 0) {
            fprintf(stderr, "Error: Failed to read from LSM303DLHC.\n");
            continue;
        }

        // Compute magnitude and adjust LED
        compute_magnitude_and_adjust_led(data[3]);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up on exit
    cleanup();

    return 0;
}

// Function to setup I2C
void setup_i2c() {
    int i2c_fd = open(I2C_DEVICE_PATH, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    // Enable I2C clock stretching
    if (ioctl(i2c_fd, I2C_SLAVE, MAGNETOMETER_ADDRESS) < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }
}

// Function to setup PWM on GPIO17
void setup_pwm() {
    struct gpiod_dir_config dir_config;
    dir_config.direction = GPIOD_DIR_OUT;
    dir_config.function = LED_GPIO_NUM;
    if (gpiod_direction_output(LED_GPIO_NUM, 0) < 0) {
        perror("gpiod_direction_output");
        exit(EXIT_FAILURE);
    }

    struct gpiod_set_config set_config;
    set_config.value = 0; // Start with LED off
    if (gpiod_set_config(LED_GPIO_NUM, &set_config) < 0) {
        perror("gpiod_set_config");
        exit(EXIT_FAILURE);
    }
}

// Function to read magnetometer data
int read_magnetometer_data(uint8_t *data) {
    uint8_t cmd = 0x18; // CTRL_REG1_M command to set 10 Hz continuous conversion

    // Write command to CTRL_REG1_M
    if (write(I2C_DEVICE_PATH, &cmd, 1) != 1) {
        perror("write to CTRL_REG1_M");
        return -1;
    }

    // Read 6 bytes of data starting from OUT_X_L_M
    if (ioctl(I2C_DEVICE_PATH, I2C_BLOCK, OUT_X_L_M_OFFSET) < 0) {
        perror("I2C_BLOCK read");
        return -1;
    }

    // Read data from I2C
    if (read(I2C_DEVICE_PATH, data, 6) != 6) {
        perror("read from I2C");
        return -1;
    }

    return 0;
}

// Function to compute magnitude and adjust LED
void compute_magnitude_and_adjust_led(uint16_t z_magnitude) {
    // Assuming Z-axis magnitude is directly proportional to LED brightness
    // Normalize the range to 0-1023 (PWM value range)
    uint16_t adjusted_brightness = (z_magnitude * 1023) / 65535;

    // Set LED brightness using hardware PWM
    gpiod_set_value(LED_GPIO_NUM, adjusted_brightness);
}

// Signal handler to release resources on SIGINT/SIGTERM
void handle_signal(int signum) {
    // Release resources
    gpiod_release(LED_GPIO_NUM);
    close(I2C_DEVICE_PATH);
    // Close any log files (if opened)
    // Example: fclose(stderr);
    exit(EXIT_FAILURE);
}

// Function to cleanup resources
void cleanup() {
    // Release the PWM
    gpiod_release(LED_GPIO_NUM);

    // Close the I2C file descriptor
    close(I2C_DEVICE_PATH);

    // Close any log files (if opened)
    // Example: fclose(stderr);
}

