    dir_config.direction = GPIOD_DIR_OUT;
    dir_config.function = LED_GPIO_NUM;
    if (gpiod_direction_output(LED_GPIO_NUM, 0) < 0) {
        perror("gpiod_direction_output");
        exit(EXIT_FAILURE);
    }

    struct gpiod_set_config set_config;
    set_config.value = 0; // Start with LED off
    if (gpiod_set_config(LED_GPIO_NUM, &set_config) < 0) {
        perror("gpiod_set_config");
        exit(EXIT_FAILURE);
    }
}

// Function to read magnetometer data
int read_magnetometer_data(uint8_t *data) {
    uint8_t cmd = 0x18; // CTRL_REG1_M command to set 10 Hz continuous conversion

    // Write command to CTRL_REG1_M
    if (write(I2C_DEVICE_PATH, &cmd, 1) != 1) {
        perror("write to CTRL_REG1_M");
        return -1;
    }

    // Read 6 bytes of data starting from OUT_X_L_M
    if (ioctl(I2C_DEVICE_PATH, I2C_BLOCK, OUT_X_L_M_OFFSET) < 0) {
        perror("I2C_BLOCK read");
        return -1;
    }

    // Read data from I2C
    if (read(I2C_DEVICE_PATH, data, 6) != 6) {
        perror("read from I2C");
        return -1;
    }

    return 0;
}

