    // Normalize the range to 0-1023 (PWM value range)
    uint16_t adjusted_brightness = (z_magnitude * 1023) / 65535;

    // Set LED brightness using hardware PWM
    gpiod_set_value(LED_GPIO_NUM, adjusted_brightness);
