void signal_handler(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    cleanup_resources();
    exit(0);
}

int main() {
    // Initialize pigpio
    setup_pigpio();

    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup I2C
    setup_i2c();

    // Main loop
    while (1) {
        // Read magnetometer data with 8-sample averaging
        read_magnetometer(8);

        // Apply hard-iron offsets and print corrected values
        apply_hard_iron_offsets(&HMC5883L_MAG_X, &HMC5883L_MAG_Y, &HMC5883L_MAG_Z);
        print_offsets_corrected_values(HMC5883L_MAG_X, HMC5883L_MAG_Y, HMC5883L_MAG_Z);

        // Sleep for 500ms
        usleep(500000);
    }

    return 0;
