void setup_pigpio() {
    if (pi_pigpio_error() != PI_NO_ERROR) {
        fprintf(stderr, "Error initializing pigpio: %s\n", pi_pigpio_error_string());
        exit(EXIT_FAILURE);
    }
}

// Function to setup I2C
void setup_i2c() {
    if (gpiod_i2c_open(I2C_BUS_NUMBER) < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", gpiod_error_string());
        exit(EXIT_FAILURE);
    }

    if (gpiod_i2c_write(HMC5883L_ADDRESS, CONFIG_REGISTER_A, (uint8_t)GAIN_SETTING) < 0 ||
        gpiod_i2c_write(HMC5883L_ADDRESS, CONFIG_REGISTER_B, (uint8_t)0x20) < 0 ||
        gpiod_i2c_write(HMC5883L_ADDRESS, MODE_REGISTER, (uint8_t)0x00) < 0) {
        fprintf(stderr, "Error writing to magnetometer: %s\n", gpiod_error_string());
        gpiod_i2c_close(I2C_BUS_NUMBER);
        exit(EXIT_FAILURE);
    }
}

// Function to read magnetometer data
void read_magnetometer(uint8_t num_samples) {
    float raw_data[3];

    for (int i = 0; i < num_samples; i++) {
        if (gpiod_i2c_read(HMC5883L_ADDRESS, HMC5883L_RAW_X_REG, raw_data) < 0 ||
            gpiod_i2c_read(HMC5883L_ADDRESS, HMC5883L_RAW_Y_REG, raw_data + 1) < 0 ||
            gpiod_i2c_read(HMC5883L_ADDRESS, HMC5883L_RAW_Z_REG, raw_data + 2) < 0) {
            fprintf(stderr, "Error reading from magnetometer: %s\n", gpiod_error_string());
            break;
        }
    }

    // Apply hard-iron offsets
    apply_hard_iron_offsets(raw_data, raw_data, raw_data);
}

// Function to apply hard-iron offsets
void apply_hard_iron_offsets(float *raw_x, float *raw_y, float *raw_z) {
    float x = raw_x[0];
    float y = raw_y[0];
    float z = raw_z[0];

    x -= hx[(hx_index % 100)];
    y -= hy[(hy_index % 100)];
    z -= hz[(hz_index % 100)];

    *raw_x = x;
    *raw_y = y;
    *raw_z = z;
}

// Function to print offset-corrected values
void print_offsets_corrected_values(float x, float y, float z) {
    printf("Corrected X: %.2f Gauss, Corrected Y: %.2f Gauss, Corrected Z: %.2f Gauss\n",
           x, y, z);
}

// Function to cleanup resources
void cleanup_resources() {
    // Close I2C
    gpiod_i2c_close(I2C_BUS_NUMBER);

    // Shutdown pigpio
    pigpiod_stop();
}

// Index variables for hard-iron offset running average
volatile size_t hx_index = 0;
volatile size_t hy_index = 0;
volatile size_t hz_index = 0;

