#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_DEVICE_PATH "/dev/i2c-1"
#define LSM303D_I2C_ADDRESS 0x1D
#define LSM303D_INT1_GPIO 23

// LSM303D Registers
#define CTRL_REG1 0x0B
#define CTRL_REG4 0x0C
#define INT1_CFG 0x19
#define OUT_X_L_A 0x28

// Constants
#define BUFFER_SIZE 64
#define SAMPLE_RATE_MS 10
#define THRESHOLD_MG 2000
#define THRESHOLD_VALUE (THRESHOLD_MG / 16)
#define INT1_CFG_VALUE 0x7D

// Structure for LSM303D configuration
struct lsm303d_config {
    uint8_t ctrl_reg1;
    uint8_t ctrl_reg4;
    uint8_t int1_cfg;
};

// Function prototypes
void setup_lsm303d(void);
void read_acceleration_data(uint8_t *data);
void handle_interrupt(void);
void print_samples(uint8_t *samples, int count);
void cleanup_lsm303d(void);
int main(void) {
    struct lsm303d_config config;
    uint8_t data[BUFFER_SIZE];
    int i2c_fd;
    int gpio_fd;
    int sample_index = 0;
    int samples_taken = 0;
    sigset_t sigset;
    struct timespec timestamp;

    // Initialize signal mask for SIGINT handling
    sigemptyset(&sigset);
    sigaddset(&sigset, SIGINT);
    sigprocmask(SIG_BLOCK, &sigset, NULL);

    // Setup LSM303D
    setup_lsm303d();

    // Main loop
    while (1) {
        // Handle SIGINT
        if (sigpending(&sigset) != 0) {
            if (sigismember(&sigset, SIGINT)) {
                printf("SIGINT received, exiting...\n");
                cleanup_lsm303d();
                exit(0);
            }
        }

        // Poll for accelerometer data
        if (samples_taken < BUFFER_SIZE) {
            // Read acceleration data
            read_acceleration_data(data);

            // Check for INT1 interrupt
            handle_interrupt();

            // Print last 10 samples if an interrupt occurred
            if (samples_taken > 0) {
                print_samples(data, samples_taken);
            }

            // Increment sample index
            sample_index = (sample_index + 1) % BUFFER_SIZE;
        }

        // Sleep for 10 ms
        usleep(SAMPLE_RATE_MS * 1000);

        // Check for SIGINT again
        if (sigpending(&sigset) != 0) {
            if (sigismember(&sigset, SIGINT)) {
                printf("SIGINT received, exiting...\n");
                cleanup_lsm303d();
                exit(0);
            }
        }
    }

    // Clean up resources
    cleanup_lsm303d();

    return 0;
}

// Function to setup LSM303D
void setup_lsm303d() {
    struct lsm303d_config config;

    // Check WHO_AM_I register
    if (i2c_smbus_read_byte_data(I2C_DEVICE_PATH, LSM303D_I2C_ADDRESS, 0x0F) != 0x49) {
        fprintf(stderr, "Error: LSM303D WHO_AM_I register did not return 0x49\n");
        exit(1);
    }

    // Configure CTRL_REG1 for 50 Hz ODR
    config.ctrl_reg1 = 0x57;

    // Configure CTRL_REG4 for full-scale +-2g
    config.ctrl_reg4 = 0x00;

    // Configure INT1_CFG for threshold interrupt
    config.int1_cfg = INT1_CFG_VALUE;

    // Write configuration to LSM303D
    if (i2c_smbus_write_byte_data(I2C_DEVICE_PATH, LSM303D_I2C_ADDRESS, CTRL_REG1, config.ctrl_reg1) != 1 ||
        i2c_smbus_write_byte_data(I2C_DEVICE_PATH, LSM303D_I2C_ADDRESS, CTRL_REG4, config.ctrl_reg4) != 1 ||
        i2c_smbus_write_byte_data(I2C_DEVICE_PATH, LSM303D_I2C_ADDRESS, INT1_CFG, config.int1_cfg) != 1) {
        fprintf(stderr, "Error writing to LSM303D registers\n");
        exit(1);
    }

    // Enable INT1 interrupt
    if (gpiod_enable_interrupt(LSM303D_INT_GPIO) < 0) {
        fprintf(stderr, "Error enabling INT1 interrupt\n");
        exit(1);
    }

    printf("LSM303D configured successfully\n");
}

// Function to read acceleration data
void read_acceleration_data(uint8_t *data) {
    int bytes_read;
    uint8_t reg_addr = OUT_X_L_A | 0x80; // Set MSB for auto-increment

    // Read 6 bytes of data (3 samples)
    bytes_read = i2c_smbus_read_i2c_block_data(I2C_DEVICE_PATH, LSM303D_I2C_ADDRESS, reg_addr, data, 6);

    if (bytes_read != 6) {
        fprintf(stderr, "Error reading from LSM303D: %d bytes read\n", bytes_read);
        return;
    }

    // Increment register address for next read
    reg_addr = (reg_addr & 0x7F) | 0x80; // Clear MSB for auto-increment
}

// Function to handle INT1 interrupt
void handle_interrupt() {
    struct timespec now;
    clock_gettime(CLOCK_REALTIME, &now);

    // Check if interrupt occurred
    if (gpiod_get_value(LSM303D_INT_GPIO) == GPIOD_INPUT_HIGH) {
        printf("Interrupt detected at %fs\n", now.tv_sec * 1e9 + now.tv_nsec / 1e9);
        print_samples(data + sample_index, 10);
    }
}

// Function to print last 10 samples
void print_samples(uint8_t *samples, int count) {
    for (int i = 0; i < count; i++) {
        printf("Sample %d: %d\n", i + 1, samples[i]);
    }
}

// Function to cleanup resources
void cleanup_lsm303d() {
    // Disable INT1 interrupt
    gpiod_disable_interrupt(LSM303D_INT_GPIO);

    // Close I2C file descriptor
    close(I2C_DEVICE_PATH);

    // Release GPIO resource
    gpiod_remove(LSM303D_INT_GPIO);
}

