#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <poll.h>
#include <pigpio.h>

#define GPIO17 17
#define GPIO27 27

// Constants
#define SERIAL_BAUD_RATE 9600
#define SERIAL_TIMEOUT 5000
#define EXPECTED_CODE "123456"

// Function prototypes
void setup_pigpio();
void setup_serial(int fd);
void read_serial(int fd, char buffer[6], int *received_code);
void handle_signal(int signum);
void unlock_doors();
void lock_doors();
void cleanup();

int main() {
    // Signal handler for SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize pigpio
    setup_pigpio();

    // Set up serial ports
    int serial0_fd = open("/dev/serial0", O_RDWR | O_NOCTTY);
    if (serial0_fd == -1) {
        fprintf(stderr, "Error: Failed to open /dev/serial0\n");
        exit(EXIT_FAILURE);
    }
    setup_serial(serial0_fd);

    int serial1_fd = open("/dev/serial1", O_RDWR | O_NOCTTY);
    if (serial1_fd == -1) {
        fprintf(stderr, "Error: Failed to open /dev/serial1\n");
        exit(EXIT_FAILURE);
    }
    setup_serial(serial1_fd);

    // Main loop
    while (1) {
        // Poll for serial input
        struct pollfd fds[2];
        fds[0].fd = serial0_fd;
        fds[0].events = POLLIN;
        fds[1].fd = serial1_fd;
        fds[1].events = POLLIN;

        int result = poll(fds, 2, SERIAL_TIMEOUT);

        if (result == -1) {
            fprintf(stderr, "Error: Poll failed\n");
            break;
        }

        if (fds[0].revents & POLLIN) {
            read_serial(serial0_fd, buffer, &received_code_0);
        }

        if (fds[1].revents & POLLIN) {
            read_serial(serial1_fd, buffer, &received_code_1);
        }

        // Check if both codes match and match the expected code
        if (strcmp(received_code_0, received_code_1) == 0 && strcmp(received_code_0, EXPECTED_CODE) == 0) {
            unlock_doors();
            sleep(2); // Keep doors unlocked for 2 seconds
        } else {
            lock_doors();
        }
    }

    // Clean up on exit
    cleanup();

    return 0;
}

// Function to initialize pigpio
void setup_pigpio() {
    if (gpioInitialise() == -1) {
        fprintf(stderr, "Error: Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }
    gpioMode(GPIO17, GPIO_OUTPUT);
    gpioMode(GPIO27, GPIO_OUTPUT);
    gpioWrite(GPIO17, 0); // Lock
    gpioWrite(GPIO27, 0); // Lock
}

// Function to set up serial port
void setup_serial(int fd) {
    struct termios options;
    tcgetattr(fd, &options);

    // Set baud rate, 8N1
    cfsetispeed(&options, B9600);
    cfsetospeed(&options, B9600);

    // Set other parameters (e.g., no parity, 1 stop bit)
    options.c_cflag = (options.c_cflag & ~CSIZE) | CS8;

    // Set non-blocking mode
    options.fcntl = FNDELAY;

    // Set new options
    tcsetattr(fd, TCSANOW, &options);

    // Reset input buffer
    if (tcflush(fd, TCIOFLUSH) == -1) {
        fprintf(stderr, "Error: Failed to reset serial input buffer\n");
    }
}

// Function to read a 6-digit code from a serial port
void read_serial(int fd, char buffer[6], int *received_code) {
    char c;
    int count = 0;

    while (count < 6 && (c = fgetc(fd)) != EOF) {
        if (isdigit(c)) {
            buffer[count++] = c;
        } else {
            tcflush(fd, TCIOFLUSH); // Reset input buffer
        }
    }

    if (count == 6) {
        *received_code = strncat(received_code, buffer, 6);
    } else {
        fprintf(stderr, "Error: Timeout reading from serial port\n");
    }
}

// Signal handler to ensure clean shutdown
void handle_signal(int signum) {
    // Unlock doors
    unlock_doors();

    // Close serial ports
    close(serial0_fd);
    close(serial1_fd);

    // Terminate pigpio
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

// Function to unlock both doors
void unlock_doors() {
    gpioWrite(GPIO17, 1); // Unlock
    gpioWrite(GPIO27, 1); // Unlock
}

// Function to lock both doors
void lock_doors() {
    gpioWrite(GPIO17, 0); // Lock
    gpioWrite(GPIO27, 0); // Lock
}

// Function to clean up and exit
void cleanup() {
    // Clean up resources
    gpioTerminate();
    // No need to close serial ports as they are closed in handle_signal
}

