#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <gpiod.h>

#define PIR_GPIO 4
#define RELAY_GPIO 17
#define PIR_THRESHOLD 10000  // 10 seconds in milliseconds

// Function prototypes
void setup_gpiod();
void handle_motion();
void handle_relay();
void handle_failsafe();
void cleanup();
void signal_handler(int signum);

int main() {
    // Initialize signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup logging to syslog
    openlog("motion_detector", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize libgpiod
    setup_gpiod();

    while (1) {
        // Poll PIR sensor
        if (handle_motion()) {
            // Relay on
            handle_relay();
            // Fail-safe check after 10 seconds
            if (handle_failsafe()) {
                // Relay off and log warning
                handle_relay();
                syslog(LOG_WARNING, "Potential PIR sensor malfunction detected.");
            }
        }
    }

    // Clean up on exit
    cleanup();

    closelog();
    return 0;
}

// Function to initialize libgpiod
void setup_gpiod() {
    int ret;

    // Open the GPIO chip
    ret = gpiod_chip_open("gpiochip0", GPIOD_OPEN_BY_NAME);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %s", gpiod_strerror(ret));
        exit(EXIT_FAILURE);
    }

    // Request input line for PIR sensor
    ret = gpiod_line_request_input(PIR_GPIO, GPIOD_LINE_REQUEST_INPUT);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request PIR GPIO as input: %s", gpiod_strerror(ret));
        gpiod_chip_close("gpiochip0");
        exit(EXIT_FAILURE);
    }

    // Request output line for relay
    ret = gpiod_line_request_output(RELAY_GPIO, GPIOD_LINE_REQUEST_OUTPUT);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request relay GPIO as output: %s", gpiod_strerror(ret));
        gpiod_line_release(PIR_GPIO);
        gpiod_line_release(RELAY_GPIO);
        gpiod_chip_close("gpiochip0");
        exit(EXIT_FAILURE);
    }
}

// Function to handle motion detection
int handle_motion() {
    int ret;
    unsigned int value;

    ret = gpiod_line_get_value(PIR_GPIO, &value);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to read PIR GPIO value: %s", gpiod_strerror(ret));
        return 0;  // Assume no motion
    }

    if (value > 0) {
        syslog(LOG_INFO, "Motion detected, energizing relay.");
        handle_relay();
        return 1;  // Motion detected
    }

    return 0;  // No motion detected
}

// Function to handle relay control
void handle_relay() {
    int ret;

    ret = gpiod_line_set_value(RELAY_GPIO, 1);  // HIGH
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set relay GPIO HIGH: %s", gpiod_strerror(ret));
        return;
    }

    sleep(1);  // Strike duration of 1 second

    ret = gpiod_line_set_value(RELAY_GPIO, 0);  // LOW
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set relay GPIO LOW: %s", gpiod_strerror(ret));
        return;
    }

    syslog(LOG_INFO, "Relay de-energized.");
}

// Function to handle failsafe
int handle_failsafe() {
    int ret;
    unsigned int value;

    ret = gpiod_line_get_value(PIR_GPIO, &value);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to read PIR GPIO value: %s", gpiod_strerror(ret));
        return 0;  // Assume no continuous HIGH
    }

    if (value > 0 && (millis() - last_motion_time) >= PIR_THRESHOLD) {
        syslog(LOG_WARNING, "PIR sensor HIGH for more than %d seconds. De-energizing relay.", PIR_THRESHOLD);
        handle_relay();
        return 1;  // Failsafe triggered
    }

    last_motion_time = millis();
    return 0;  // No failsafe trigger
}

// Last motion time for failsafe check
unsigned long last_motion_time = 0;

// Function to cleanup resources
void cleanup() {
    gpiod_line_release(PIR_GPIO);
    gpiod_line_release(RELAY_GPIO);
    gpiod_chip_close("gpiochip0");
    closelog();
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    // Clean up before exiting
    cleanup();
    exit(EXIT_SUCCESS);
}

