#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>

#define RELAY_GPIO_PINS {4, 17, 27, 22}
#define NUM_RELAYS (sizeof(RELAY_GPIO_PINS) / sizeof(RELAY_GPIO_PINS[0]))

volatile sig_atomic_t should_exit = 0;

// Internal state machine variables
int current_action = 0;
unsigned long last_action_time = 0;

// Function prototypes
void handle_signals(int signum);
void relay_control(int index);
void log_action(char *action, unsigned long timestamp);
void setup_irrigation_system();
void cleanup_irrigation_system();

int main() {
    // Initialize logging
    openlog("irrigation_system", LOG_PID, LOG_USER);

    // Setup GPIO and irrigation system
    setup_irrigation_system();

    // Main loop
    while (!should_exit) {
        // Check for signals
        handle_signals(SIGINT);
        handle_signals(SIGTERM);

        // Update current action based on state machine
        if (current_action == 0) {
            // Activate relay
            relay_control(0);
            last_action_time = time(NULL);
        } else if (current_action == 1) {
            // Wait for 1 minute (60 seconds)
            sleep(60);
            last_action_time = time(NULL);
            if (current_action == 2) {
                // Deactivate relay
                relay_control(0);
                current_action = 0; // Loop back to activation
            } else {
                // Move to next relay
                current_action++;
                if (current_action >= NUM_RELAYS) {
                    current_action = 0; // Loop back to the 1st relay
                }
            }
        } else {
            // Pause for 1 minute (60 seconds)
            sleep(60);
            last_action_time = time(NULL);
        }

        // Check if it's time to change the action
        if (current_action == 0 && (time(NULL) - last_action_time) >= 300) {
            // Deactivate relay after 5 minutes
            relay_control(0);
            last_action_time = time(NULL);
            current_action = 1; // Move to wait state
        }
    }

    // Cleanup
    cleanup_irrigation_system();

    // Close syslog
    closelog();

    return 0;
}

// Signal handler to catch SIGINT and SIGTERM
void handle_signals(int signum) {
    should_exit = 1;
}

// Control a single relay
void relay_control(int index) {
    if (pigpioErr(pigpioWrite(RELAY_GPIO_PINS[index], 0))) {
        syslog(LOG_ERR, "Error writing to GPIO %d: %s", RELAY_GPIO_PINS[index], pigpioError());
        exit(EXIT_FAILURE);
    }

    log_action("activated", time(NULL));
}

// Log an action with timestamp to syslog
void log_action(char *action, unsigned long timestamp) {
    syslog(LOG_INFO, "Relay %d: %s at %lu", RELAY_GPIO_PINS[current_action], action, timestamp);
}

// Setup the irrigation system
void setup_irrigation_system() {
    if (pigpioErr(gpioInitialise())) {
        syslog(LOG_ERR, "Error initializing pigpio: %s", pigpioError());
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < NUM_RELAYS; ++i) {
        if (pigpioErr(gpioSetMode(RELAY_GPIO_PINS[i], pigpioOutputMode))) {
            syslog(LOG_ERR, "Error setting GPIO %d to output: %s", RELAY_GPIO_PINS[i], pigpioError());
            exit(EXIT_FAILURE);
        }
        if (pigpioErr(gpioWrite(RELAY_GPIO_PINS[i], 1))) {
            syslog(LOG_ERR, "Error setting GPIO %d to HIGH: %s", RELAY_GPIO_PINS[i], pigpioError());
            exit(EXIT_FAILURE);
        }
    }

    // Initialize timer for 60 seconds
    if (pigpioErr(gpioSetTimerFuncEx(0, 60000, NULL))) {
        syslog(LOG_ERR, "Error setting timer: %s", pigpioError());
        exit(EXIT_FAILURE);
    }

    current_action = 0;
}

// Cleanup GPIO and logging resources
void cleanup_irrigation_system() {
    for (int i = 0; i < NUM_RELAYS; ++i) {
        if (pigpioErr(gpioWrite(RELAY_GPIO_PINS[i], 1))) {
            syslog(LOG_ERR, "Error setting GPIO %d to HIGH: %s", RELAY_GPIO_PINS[i], pigpioError());
        }
    }

    gpioTerminate();

    closelog();
}

