#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/time.h>
#include <unistd.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <sys/mman.h>

#define I2C_DEVICE_PATH "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define BUFFER_SIZE 1024
#define ACCEL_XOUT_H 0x3B
#define ACCEL_XOUT_L 0x3C
#define ACCEL_YOUT_H 0x3D
#define ACCEL_YOUT_L 0x3E
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_ZOUT_L 0x40

#define BUFFER_OFFSET 0

typedef struct {
    int fd;
    struct gpiod_device *i2c_dev;
    uint8_t *buffer;
    size_t buffer_index;
    size_t buffer_head;
    size_t buffer_tail;
} MPU6050Data;

void initialize_MPUs6050(MPU6050Data *mpu_data) {
    int i2c_fd;
    struct gpiod_cdev *i2c_cdev;
    struct i2c_msg msg[2];

    i2c_fd = open(I2C_DEVICE_PATH, O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    i2c_cdev = gpiod_cdev_from_fd(i2c_fd);
    if (!i2c_cdev) {
        perror("Failed to get GPIOD device");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Wake up the MPU6050
    msg[0].addr = MPU6050_ADDR;
    msg[0].len = 1;
    msg[0].buf = (uint8_t) PWR_MGMT_1;
    msg[0].buf[0] = 0x00; // PWR_MGMT_1 register, bit 7 set to 0 (device enabled)

    msg[1].addr = MPU6050_ADDR;
    msg[1].len = 1;
    msg[1].buf = (uint8_t) 0x00; // No data to write back

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (write(i2c_fd, msg, sizeof(msg)) != sizeof(msg)) {
        perror("Failed to write to MPU6050");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Set accelerometer range to +-2g
    msg[0].addr = MPU6050_ADDR;
    msg[0].len = 2;
    msg[0].buf = (uint8_t *) &ACCEL_CONFIG;
    msg[0].buf[0] = 0x00; // ACCEL_CONFIG register, bits 6:4 set to 000 (range +-2g)

    msg[1].addr = MPU6050_ADDR;
    msg[1].len = 0; // No data to write back

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (write(i2c_fd, msg, sizeof(msg)) != sizeof(msg)) {
        perror("Failed to write to MPU6050");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Initialize circular buffer
    mpu_data->buffer = (uint8_t *) mmap(NULL, BUFFER_SIZE * sizeof(uint8_t), PROT_READ | PROT_WRITE, MAP_SHARED, i2c_fd, BUFFER_OFFSET);
    if (mpu_data->buffer == MAP_FAILED) {
        perror("Failed to map buffer");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    mpu_data->buffer_index = 0;
    mpu_data->buffer_head = 0;
    mpu_data->buffer_tail = BUFFER_SIZE - 1;
}

void read_acceleration_data(MPU6050Data *mpu_data) {
    struct timeval start, end;
    uint8_t data[6];

    gettimeofday(&start, NULL);

    // Read acceleration data
    if (ioctl(mpu_data->fd, I2C_RDWR, (void *) msg) < 0) {
        perror("Failed to read from MPU6050");
        return;
    }

    msg[0].addr = ACCEL_XOUT_H;
    msg[0].len = 1;
    msg[0].buf = (uint8_t *) &data[0];

    msg[1].addr = ACCEL_YOUT_H;
    msg[1].len = 1;
    msg[1].buf = (uint8_t *) &data[1];

    msg[2].addr = ACCEL_ZOUT_H;
    msg[2].len = 1;
    msg[2].buf = (uint8_t *) &data[2];

    if (write(mpu_data->fd, msg, sizeof(msg)) != sizeof(msg)) {
        perror("Failed to read from MPU6050");
        return;
    }

    // Scale raw values by 16384.0 to get g
    double x_accel = (data[0] << 8) | data[1] * 16384.0;
    double y_accel = (data[2] << 8) | data[3] * 16384.0;
    double z_accel = (data[4] << 8) | data[5] * 16384.0;

    gettimeofday(&end, NULL);

    // Update circular buffer
    mpu_data->buffer[mpu_data->buffer_index++] = (uint8_t)x_accel;
    mpu_data->buffer[mpu_data->buffer_index++] = (uint8_t)(y_accel & 0xFF);
    mpu_data->buffer[mpu_data->buffer_index++] = (uint8_t)(y_accel >> 8);
    mpu_data->buffer[mpu_data->buffer_index++] = (uint8_t)z_accel;
    mpu_data->buffer[mpu_data->buffer_index++] = (uint8_t)(z_accel >> 8);

    if (mpu_data->buffer_index >= BUFFER_SIZE) {
        mpu_data->buffer_index = 0;
        mpu_data->buffer_head = mpu_data->buffer_tail = BUFFER_OFFSET;
    }

    // Provide data through sysfs
    char path[256];
    snprintf(path, sizeof(path), "/sys/kernel/mpu6050_accel/latest");
    if (write(STDOUT_FILENO, mpu_data->buffer[mpu_data->buffer_head], 6) != 6) {
        perror("Failed to write to sysfs");
    }
}

void cleanup_MPUs6050(MPU6050Data *mpu_data) {
    if (mpu_data->buffer) {
        munmap(mpu_data->buffer, BUFFER_SIZE * sizeof(uint8_t));
        mpu_data->buffer = NULL;
    }

    if (mpu_data->i2c_dev) {
        gpiod_cdev_put(mpu_data->i2c_dev);
        mpu_data->i2c_dev = NULL;
    }

    close(mpu_data->fd);
    mpu_data->fd = -1;
}

int main() {
    MPU6050Data mpu_data;
    initialize_MPUs6050(&mpu_data);

    struct sigaction sa;
    sa.sa_handler = SIG_IGN;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        read_acceleration_data(&mpu_data);
        usleep(100000); // Sleep for 100 ms
    }

    cleanup_MPUs6050(&mpu_data);

    return 0;
}

