// Prime number intervals in seconds for relay toggling
#define INTERVALS [2, 3, 5, 7]

// Function prototypes
void setup_gpios(void);
void toggle_relay(int index, int interval);
void cleanup_gpios(void);
void handle_signal(int signum);

int main(void) {
    // Initialize signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Setup GPIO
    setup_gpios();

    // Main loop
    while (1) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            toggle_relay(i, INTERVALS[i]);
        }
        // Sleep for a short period to avoid excessive CPU usage
        usleep(10000);
    }

    // Cleanup GPIO on exit
    cleanup_gpios();

    return 0;
}

// Function to setup GPIO pins
void setup_gpios(void) {
    // Iterate over each relay pin
    for (int i = 0; i < NUM_RELAYS; i++) {
        // Open GPIO device
        int ret = gpiod_open(GPIOD, "gpiochip-bcm2708", "r");
        if (ret < 0) {
            perror("gpiod_open");
            exit(EXIT_FAILURE);
        }

        // Request the GPIO line
        ret = gpiod_request_line(GPIOD, RELAY_PIN_BCM[i], GPIOD_OUT_INIT_LOW);
        if (ret < 0) {
            perror("gpiod_request_line");
            gpiod_release(GPIOD);
            exit(EXIT_FAILURE);
        }

        // Set the GPIO line as output
        ret = gpiod_direction_output(GPIOD, RELAY_PIN_BCM[i], 1);
        if (ret < 0) {
            perror("gpiod_direction_output");
            gpiod_release(GPIOD);
            exit(EXIT_FAILURE);
        }
    }

    // Close the GPIO device
    gpiod_release(GPIOD);
}

// Function to toggle a relay based on the interval
void toggle_relay(int index, int interval) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);

    // Calculate the next toggle time
    ts.tv_sec += interval;
    ts.tv_nsec += 1000000000; // 1 second in nanoseconds

    // Schedule the next toggle
    if (nanosleep(&ts, NULL) == -1) {
        perror("nanosleep");
        exit(EXIT_FAILURE);
    }
}

// Function to cleanup GPIO resources
void cleanup_gpios(void) {
    // Iterate over each GPIO line
    for (int i = 0; i < NUM_RELAYS; i++) {
        // Release the GPIO line
        ret = gpiod_release_line(GPIOD, RELAY_PIN_BCM[i]);
        if (ret < 0) {
            perror("gpiod_release_line");
        }
    }

    // Close the GPIO device
    gpiod_release(GPIOD);
}

// Signal handler to cleanup and exit on SIGINT or SIGTERM
void handle_signal(int signum) {
    // Clean up GPIO
    cleanup_gpios();

    // Exit the program
    exit(EXIT_SUCCESS);
}

