#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define SOUND_SENSOR_GPIO 17
#define RELAY_GPIO 27

// Debounce timeout in milliseconds
#define DEBOUNCE_TIMEOUT 50

// File path for logging
#define ALARM_LOG_PATH "alarm_log.txt"

// Function prototypes
void setup_pigpio();
void cleanup_pigpio();
void monitor_sound();
void handle_signal(int signum);
void activate_relay();
void deactivate_relay();
void log_alarm(const char *message);

int main() {
    // Signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize pigpio
    setup_pigpio();

    // Main loop
    while (1) {
        // Poll sound sensor
        monitor_sound();

        // Check debounce
        if (!is_active) {
            // No recent activation, check sound sensor again
            continue;
        }

        // Sound detected, check if not already active
        if (!is_active) {
            // Activate relay
            activate_relay();
            is_active = true;
            log_alarm("Alarm triggered at: %s", ctime(&now));
        }

        // Wait for debounce timeout
        usleep(DEBOUNCE_TIMEOUT * 1000);

        // Check if relay needs deactivation
        if (is_active) {
            // Deactivate relay
            deactivate_relay();
            is_active = false;
        }
    }

    // Cleanup on exit
    cleanup_pigpio();

    return 0;
}

// Function to initialize pigpio
void setup_pigpio() {
    if (pigpio_error() != PI_NO_ERROR) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_errstr(pigpio_error()));
        exit(EXIT_FAILURE);
    }

    // Set GPIO pins
    if (pigpio_set_mode(PIN-relay_gpio, pigpioOUTPUT) != PI_NO_ERROR) {
        fprintf(stderr, "Failed to set GPIO %d to output: %s\n", RELAY_GPIO, pigpio_errstr(pigpio_error()));
        exit(EXIT_FAILURE);
    }

    if (pigpio_set_mode(PIN-sound_sensor_gpio, pigpioINPUT) != PI_NO_ERROR) {
        fprintf(stderr, "Failed to set GPIO %d to input: %s\n", SOUND_SENSOR_GPIO, pigpio_errstr(pigpio_error()));
        exit(EXIT_FAILURE);
    }
}

// Function to cleanup pigpio
void cleanup_pigpio() {
    pigpio_free();
}

// Function to monitor the sound sensor
void monitor_sound() {
    int sound_detected = pigpio_read(PIN-sound_sensor_gpio);

    if (sound_detected) {
        // Debounce mechanism
        if (!is_active) {
            is_active = true;
            usleep(DEBOUNCE_TIMEOUT);
        }
    } else {
        is_active = false;
    }
}

// Function to handle signals
void handle_signal(int signum) {
    // Graceful shutdown
    cleanup_pigpio();
    exit(EXIT_SUCCESS);
}

// Function to activate the relay
void activate_relay() {
    pigpio_write(PIN-relay_gpio, 1);
    usleep(3000); // Keep relay active for 3 seconds
}

// Function to deactivate the relay
void deactivate_relay() {
    pigpio_write(PIN-relay_gpio, 0);
}

// Function to log an alarm message
void log_alarm(const char *message) {
    FILE *file = fopen(ALARM_LOG_PATH, "a+");
    if (file == NULL) {
        fprintf(stderr, "Failed to open %s for writing: %s\n", ALARM_LOG_PATH, strerror(errno));
        return;
    }

    fprintf(file, "%s\n", message);
    fclose(file);
}

