#define I2C_DEVICE_PATH "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x43
#define GYRO_YOUT_H 0x44
#define GYRO_YOUT_L 0x44
#define GYRO_ZOUT_H 0x45
#define GYRO_ZOUT_L 0x45
#define PWR_MGMT_1_REG 0x6B
#define WHO_AM_I_REG 0x75

#define GYRO_SENSITIVITY 131.0
#define THRESHOLD_ANGLE 50.0

typedef struct {
    uint8_t data[6];
    float x_velocity;
    float y_velocity;
    float z_velocity;
    float magnitude;
} GyroData;

void initialize_sensor() {
    int fd;
    fd = open(I2C_DEVICE_PATH, O_RDWR);
    if (fd == -1) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        exit(EXIT_FAILURE);
    }
}

void wake_sensor() {
    uint8_t power_mgmt_1;
    if (ioctl(fd, I2C_WRITE, (void *) &power_mgmt_1, PWR_MGMT_1_REG) < 0) {
        perror("Failed to write to PWR_MGMT_1");
        close(fd);
        exit(EXIT_FAILURE);
    }
    power_mgmt_1 &= ~0x08; // Clear sleep bit
    if (ioctl(fd, I2C_WRITE, (void *) &power_mgmt_1, PWR_MGMT_1_REG) < 0) {
        perror("Failed to write to PWR_MGMT_1");
        close(fd);
        exit(EXIT_FAILURE);
    }
}

bool verify_device() {
    uint8_t who_am_i;
    if (ioctl(fd, I2C_READ, (void *) &who_am_i, WHO_AM_I_REG) < 0) {
        perror("Failed to read WHO_AM_I");
        close(fd);
        return false;
    }
    if (who_am_i != MPU6050_ADDR) {
        perror("Incorrect WHO_AM_I value");
        close(fd);
        return false;
    }
    return true;
}

void read_gyroscope_data() {
    GyroData data;
    for (int i = 0; i < 100; i++) {
        uint8_t x_high = 0, x_low = 0, y_high = 0, y_low = 0, z_high = 0, z_low = 0;
        if (ioctl(fd, I2C_READ, (void *)&x_high, GYRO_XOUT_H) < 0 ||
            ioctl(fd, I2C_READ, (void *)&x_low, GYRO_XOUT_L) < 0 ||
            ioctl(fd, I2C_READ, (void *)&y_high, GYRO_YOUT_H) < 0 ||
            ioctl(fd, I2C_READ, (void *)&y_low, GYRO_YOUT_L) < 0 ||
            ioctl(fd, I2C_READ, (void *)&z_high, GYRO_ZOUT_H) < 0 ||
            ioctl(fd, I2C_READ, (void *)&z_low, GYRO_ZOUT_L) < 0) {
            perror("Failed to read gyroscope data");
            close(fd);
            return;
        }

        data.data[0] = x_high;
        data.data[1] = x_low;
        data.data[2] = y_high;
        data.data[3] = y_low;
        data.data[4] = z_high;
        data.data[5] = z_low;

        data.x_velocity = (data.data[0] + data.data[1]) * GYRO_SENSITIVITY / 131.0;
        data.y_velocity = (data.data[2] + data.data[3]) * GYRO_SENSITIVITY / 131.0;
        data.z_velocity = (data.data[4] + data.data[5]) * GYRO_SENSITIVITY / 131.0;

        float magnitude = sqrt(data.x_velocity * data.x_velocity +
                               data.y_velocity * data.y_velocity +
                               data.z_velocity * data.z_velocity);

        if (magnitude > THRESHOLD_ANGLE) {
            callback_function(data);
        }
    }
}

void callback_function(const GyroData *data) {
    // Implement user-defined callback logic here
    printf("Angular velocity exceeds threshold: %f degrees/second\n", data->magnitude);
}

void cleanup() {
    if (fd != -1) {
        close(fd);
    }
}

int main() {
    initialize_sensor();
    if (!verify_device()) {
        fprintf(stderr, "Sensor verification failed\n");
        return EXIT_FAILURE;
    }

    wake_sensor();
    read_gyroscope_data();

    signal(SIGINT, SIG_IGN); // Ignore Ctrl+C for clean exit
    while (1) {
        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}
