#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/stat.h>

#define CO2_SENSOR_READ_COMMAND "\xFF\x01\x86\x00\x00\x00\x00\x00\x79"
#define CO2_RESPONSE_CHECKSUM_OFFSET 8

// Function prototypes
void initialize_pigpio_and_serial();
void send_read_command();
void read_co2_response();
void validate_co2_response();
void append_to_co2_log(const char *timestamp, uint16_t ppm, int error);
void handle_interrupts();
void cleanup();

// Global variables
pigpio *pi;
int serial_fd;
FILE *co2_log_fp;
FILE *co2_error_fp;

// Main function
int main() {
    initialize_pigpio_and_serial();
    co2_log_fp = fopen("co2_log.json", "a+");
    co2_error_fp = fopen("co2_error.log", "a+");

    while (1) {
        send_read_command();
        read_co2_response();
        validate_co2_response();
        append_to_co2_log(get_timestamp(), (uint16_t)(response[2] << 8 | response[3]), 0);
        printf("%s\n", "{\"timestamp\": \"\\%" PRId64 "\", \"ppm\": %u, \"error\": 0}\n", get_timestamp(), (uint32_t)(response[2] << 8 | response[3]));

        usleep(5000000); // Sleep for 5 seconds
    }

    handle_interrupts();
    cleanup();

    return 0;
}

// Utility functions

// Initializes pigpio and opens the serial port
void initialize_pigpio_and_serial() {
    pi = pigpioOpen();
    if (pi == NULL) {
        fprintf(co2_error_fp, "Failed to open pigpio: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }

    serial_fd = open("/dev/serial0", O_RDWR | O_NOCTTY);
    if (serial_fd == -1) {
        fprintf(co2_error_fp, "Failed to open /dev/serial0: %s\n", strerror(errno));
        pigpioClose(pi);
        exit(EXIT_FAILURE);
    }

    struct termios options;
    tcgetattr(serial_fd, &options);
    // Configure serial port settings (9600 baud, 8N1)
    cfsetispeed(&options, B9600);
    cfsetospeed(&options, B9600);
    tcsetattr(serial_fd, TCSANOW, &options);

    // No need to configure TXD/RXD as GPIO manually, pigpio handles it
}

// Sends the read command to the sensor
void send_read_command() {
    if (serWrite(serial_fd, CO2_SENSOR_READ_COMMAND, 9) != 9) {
        fprintf(co2_error_fp, "Failed to write command to sensor: %s\n", strerror(errno));
        return;
    }
    usleep(100000); // Wait about 100 ms
}

// Reads the response from the sensor
void read_co2_response() {
    char buffer[10];
    while (serDataAvailable(serial_fd) > 0) {
        if (serRead(serial_fd, buffer, sizeof(buffer)) < 0) {
            if (errno == EINTR) {
                continue; // Retry on EINTR
            } else {
                fprintf(co2_error_fp, "Failed to read from sensor: %s\n", strerror(errno));
                return;
            }
        }

        if (serDataAvailable(serial_fd) == 0) {
            // Timeout after 1 second
            fprintf(co2_error_fp, "Timeout reading from sensor\n");
            return;
        }

        // Read partial response and accumulate
        response = (char *)malloc(9);
        memcpy(response, buffer, serRead(serial_fd, response + serDataAvailable(serial_fd), serDataAvailable(serial_fd)));
        response[serDataAvailable(serial_fd)] = 0; // Null-terminate the string

        // Check if we have the full response
        if (strlen(response) == 9) {
            break;
        }
    }
}

// Validates the CO2 response checksum
void validate_co2_response() {
    uint8_t checksum = response[CO2_RESPONSE_CHECKSUM_OFFSET] - ((response[1] + response[2] + response[3] + response[4] + response[5] + response[6] + response[7]) & 0xFF) - 1;

    if (checksum != response[7]) {
        fprintf(co2_error_fp, "Invalid CO2 response checksum: expected %d, got %d\n", response[7], checksum);
        return;
    }
}

// Appends a JSON object to the co2_log.json file
void append_to_co2_log(const char *timestamp, uint16_t ppm, int error) {
    char json_str[256];
    sprintf(json_str, "{\"timestamp\": \"%s\", \"ppm\": %u, \"error\": %d}", timestamp, ppm, error);
    if (fwrite(json_str, 1, strlen(json_str), co2_log_fp) != strlen(json_str)) {
        fprintf(co2_error_fp, "Failed to write to co2_log.json: %s\n", strerror(errno));
    }
    fflush(co2_log_fp);
}

// Handles SIGINT and SIGTERM signals
void handle_interrupts() {
    pigpioCleanup(pi);
    fclose(co2_log_fp);
    fclose(co2_error_fp);
    pi = NULL;
    serial_fd = -1;
}

// Cleans up resources
void cleanup() {
    if (pi != NULL) {
        pigpioClose(pi);
        pi = NULL;
    }
    if (serial_fd != -1) {
        close(serial_fd);
        serial_fd = -1;
    }
    if (co2_log_fp != NULL) {
        fclose(co2_log_fp);
        co2_log_fp = NULL;
    }
    if (co2_error_fp != NULL) {
        fclose(co2_error_fp);
        co2_error_fp = NULL;
    }
}

// Utility function to generate a timestamp string
char *get_timestamp() {
    time_t now = time(NULL);
    char timestamp[23];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%06u", localtime(&now));
    return timestamp;
}

