// Define the buffer size for the circular buffer
#define BUFFER_SIZE 100

// Magnetometer pre-calibrated offsets
#define X_OFFSET 100
#define Y_OFFSET -50

// Target heading in degrees
#define TARGET_HEADING 90.0

// GPIO pin for indicating heading deviation
#define GPIO_PIN 17

// Function prototypes
void setup_pigpio();
void setup_hmc5883l();
void read_magnetometer_data(uint8_t* data);
void compensate_heading(uint16_t raw_x, uint16_t raw_z, uint16_t raw_y);
void handle_heading_deviation(uint16_t compensated_heading);
void handle_signal(int signum);
void print_buffer();

// Global variables
pigpio *pi;
uint8_t hmc_data[BUFFER_SIZE];
int buffer_index = 0;

// Main function
int main() {
    // Initialize pigpio
    setup_pigpio();

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (1) {
        // Read magnetometer data
        read_magnetometer_data(hmc_data);

        // Compensate and handle heading deviation
        compensate_heading(hmc_data[0], hmc_data[1], hmc_data[2]);
        handle_heading_deviation(compensated_heading);

        // Log compensated heading to buffer
        print_buffer();

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up resources on exit
    cleanup();

    return 0;
}

// Function to setup pigpio
void setup_pigpio() {
    pi = pigpioOpen();
    if (pi == NULL) {
        fprintf(stderr, "Failed to open pigpio\n");
        exit(EXIT_FAILURE);
    }
}

// Function to setup HMC5883L
void setup_hmc5883l() {
    uint8_t config_a = 0x70;
    uint8_t config_b = 0x20;
    uint8_t mode = 0x00;

    // Write configuration registers
    pigpioI2CWrite(pi, 1, 0x1E, config_a);
    pigpioI2CWrite(pi, 1, 0x1F, config_b);
    pigpioI2CWrite(pi, 1, 0x20, mode);

    // Read data from register 0x03 in a single burst transaction
    uint8_t command = 0x03;
    pigpioI2CWrite(pi, 1, 0x1E, command);
    pigpioI2CRead(pi, 1, 0x1E, 6, hmc_data);

    // Compensate for hard-iron distortion
    hmc_data[0] -= X_OFFSET;
    hmc_data[1] += Y_OFFSET;
}

// Function to read magnetometer data
void read_magnetometer_data(uint8_t* data) {
    // Write command to start continuous measurement
    pigpioI2CWrite(pi, 1, 0x1E, 0x00);

    // Wait for the measurement to complete
    while (pigpioI2CRead(pi, 1, 0x1E, 1, &data[0]) != 0x03) {
        // Handle I2C errors by retrying
        // Insert retry logic here
    }
}

// Function to compensate heading
void compensate_heading(uint16_t raw_x, uint16_t raw_z, uint16_t raw_y) {
    // Compensated heading calculation (X, Y, Z to magnitude and angle)
    // Assuming a simple 2D plane for simplicity
    uint16_t compensated_x = raw_x - X_OFFSET;
    uint16_t compensated_y = raw_y - Y_OFFSET;
    float magnitude = sqrt(compensated_x * compensated_x + compensated_y * compensated_y);
    float heading = atan2(compensated_y, compensated_x) * 180 / M_PI;

    // Adjust heading to match target
    heading -= TARGET_HEADING;
    if (heading < 0) {
        heading += 360;
    }

    // Check deviation from target heading
    if (abs(heading - TARGET_HEADING) > 10) {
        // Drive GPIO high if deviation is greater than 10 degrees
        pigpioWrite(pi, GPIO_PIN, 1);
    } else {
        // Drive GPIO low otherwise
        pigpioWrite(pi, GPIO_PIN, 0);
    }
}

// Function to handle signals
void handle_signal(int signum) {
    // Clean up resources on SIGINT and SIGTERM
    cleanup();
    exit(EXIT_SUCCESS);
}

// Function to print the circular buffer
void print_buffer() {
    if (buffer_index >= BUFFER_SIZE) {
        buffer_index = 0; // Wrap around
    }

    printf("Compensated Heading: %f degrees\n", hmc_data[buffer_index]);
}

// Function to cleanup resources
void cleanup() {
    // Close pigpio connection
    pigpioClose(pi);

    // No explicit buffer cleanup needed as it's in-memory and will be freed
}

