#include <sys/ioctl.h>
#include <unistd.h>

#define RELAY_RED   17
#define RELAY_GREEN 27
#define RELAY_BLUE  22
#define BH1750_ADDR 0x23
#define HIGH_RES_MODE 0x10

#define LUX_THRESHOLD_RED 50
#define LUX_THRESHOLD_GREEN 50
#define LUX_THRESHOLD_BLUE 150
#define LUX_THRESHOLD_ALL 300

FILE *logging_file = NULL;

int main() {
    int fd, ret;
    struct gpiod_dir *gpios;
    struct gpiod_cdev *red_cdev, *green_cdev, *blue_cdev;
    unsigned int lux;
    time_t timestamp;
    char buffer[256];

    // Initialize GPIO
    gpios = gpiod_get_dir(NULL, GPIOD_DIR_ALL);
    if (!gpios) {
        perror("gpiod_get_dir");
        return EXIT_FAILURE;
    }

    red_cdev = gpiod_get_cdev(gpios, RELAY_RED);
    green_cdev = gpiod_get_cdev(gpios, RELAY_GREEN);
    blue_cdev = gpiod_get_cdev(gpios, RELAY_BLUE);

    // Initialize BH1750 I2C
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd == -1) {
        perror("open /dev/i2c-1");
        gpiod_put(gpios);
        return EXIT_FAILURE;
    }

    ret = ioctl(fd, I2C_SLAVE, BH1750_ADDR);
    if (ret < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        gpiod_put(gpios);
        return EXIT_FAILURE;
    }

    // Initialize logging
    logging_file = fopen("lighting_log.txt", "a+");
    if (!logging_file) {
        perror("fopen lighting_log.txt");
        close(fd);
        gpiod_put(gpios);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Read BH1750 lux value
        ret = ioctl(fd, I2C_RDWR, (char *) &HIGH_RES_MODE | (BH1750_ADDR << 1) | 0x00);
        if (ret < 0) {
            fprintf(stderr, "Error reading from BH1750: %s\n", strerror(errno));
            close(fd);
            gpiod_put(gpios);
            break;
        }

        // Wait for conversion
        usleep(120000);

        // Read lux value
        ret = ioctl(fd, I2C_READ, (char *) &lux);
        if (ret < 0) {
            fprintf(stderr, "Error reading lux value: %s\n", strerror(errno));
            close(fd);
            gpiod_put(gpios);
            break;
        }

        lux /= 1.2;

        // Determine relay states
        if (lux < LUX_THRESHOLD_RED) {
            gpiod_set_value(red_cdev, GPIOD_VALUE_ON);
            gpiod_set_value(green_cdev, GPIOD_VALUE_OFF);
            gpiod_set_value(blue_cdev, GPIOD_VALUE_OFF);
        } else if (lux >= LUX_THRESHOLD_RED && lux <= LUX_THRESHOLD_GREEN) {
            gpiod_set_value(red_cdev, GPIOD_VALUE_OFF);
            gpiod_set_value(green_cdev, GPIOD_VALUE_ON);
            gpiod_set_value(blue_cdev, GPIOD_VALUE_OFF);
        } else if (lux >= LUX_THRESHOLD_GREEN && lux <= LUX_THRESHOLD_BLUE) {
            gpiod_set_value(red_cdev, GPIOD_VALUE_OFF);
            gpiod_set_value(green_cdev, GPIOD_VALUE_OFF);
            gpiod_set_value(blue_cdev, GPIOD_VALUE_ON);
        } else if (lux > LUX_THRESHOLD_BLUE) {
            gpiod_set_value(red_cdev, GPIOD_VALUE_OFF);
            gpiod_set_value(green_cdev, GPIOD_VALUE_OFF);
            gpiod_set_value(blue_cdev, GPIOD_VALUE_ON);
        }

        // Log data
        timestamp = time(NULL);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S ", &timestamp);
        fprintf(logging_file, "%s Lux: %lu Relays: RED=%d GREEN=%d BLUE=%d\n", buffer, lux, gpiod_get_value(red_cdev) ? 1 : 0, gpiod_get_value(green_cdev) ? 1 : 0, gpiod_get_value(blue_cdev) ? 1 : 0);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Cleanup
    gpiod_put(gpios);
    close(fd);
    fclose(logging_file);

    return EXIT_SUCCESS;
}

void gpiod_put(struct gpiod_cdev *cdev) {
    if (cdev) {
        gpiod_cdev_put(cdev);
    }
}

void gpiod_get(struct gpiod_dir *gpios) {
    if (gpios) {
        gpiod_dir_put(gpios);
    }
}

