                        pigpio_write(relay_pins[relay_index], 1); // Turn on
                    } else {
                        pigpio_write(relay_pins[relay_index], 0); // Turn off
                    }
                }
            }
        }

        // Update current time
        current_time = time(NULL);

        // Check for signals
        handle_signals(SIGINT);
        handle_signals(SIGTERM);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Clean up
    fclose(schedule_file_ptr);
    pigpio_free(pi);
    return 0;
