                transition_start = hour * 3600 + minute * 60 + second;
                transition_end = transition_start + 1800; // 30 minutes transition
                transition_duty = 50; // Initial duty cycle for transition
            } else {
                fprintf(stderr, "Invalid relay number in schedule file.\n");
            }
        }
    }
}

