        exit(EXIT_FAILURE);
    }

    // Set GPIO pins
    if (pigpioWrite(TRIGGER_PIN, 1) == -1 || pigpioWrite(ECHO_PIN, 0) == -1 || pigpioWrite(BUZZER_PIN, 0) == -1) {
        fprintf(stderr, "Failed to set GPIO pins: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }
}

