    // Silence the buzzer
    pigpioWrite(BUZZER_PIN, 0);

    // Deinitialize pigpio
    pigpioShutdown();
}

// Function to measure distance using HC-SR04
void measure_distance() {
    // Send trigger pulse
    pigpioDelay(10); // 10 microseconds

    // Wait for echo pulse
    unsigned long start = pigpioGetTick();
    while (pigpioDigitalRead(ECHO_PIN) == 0) {
        // No-op
    }

    unsigned long echo_time = pigpioGetTick() - start;

    // Check if the echo was detected within a reasonable time
    if (echo_time > 1000000) { // 1 second timeout
        fprintf(stderr, "Timeout waiting for echo.\n");
        return;
    }

    // Calculate distance
    float distance = (echo_time / 58.0) - 29.0; // 58 microseconds per cm
    if (distance < 0) {
        distance = 0.0; // Clamp to non-negative
    }
}

