void map_distance_to_freq(float distance) {
    if (distance < MIN_DISTANCE_CM) {
        frequency = MIN_FREQ_HZ; // Clamp to minimum frequency
    } else if (distance > MAX_DISTANCE_CM) {
        frequency = MAX_FREQ_HZ; // Clamp to maximum frequency
    } else {
        frequency = MIN_FREQ_HZ + (distance - MIN_DISTANCE_CM) * (MAX_FREQ_HZ - MIN_FREQ_HZ) / (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
    }
}

