void set_buzzer_frequency(int frequency) {
    int duty_cycle = (frequency / 1000.0) * 100; // Convert Hz to duty cycle percentage

    if (duty_cycle < 0 || duty_cycle > 100) {
        fprintf(stderr, "Invalid frequency, clamping duty cycle to 0-100.\n");
        duty_cycle = 0;
    }

    pigpioWrite(BUZZER_PIN, duty_cycle);
}

// Function to cleanup resources
void cleanup() {
    // Stop the buzzer
    pigpioWrite(BUZZER_PIN, 0);

    // Deinitialize pigpio
    pigpioShutdown();
}

