#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <inttypes.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE_PATH "/dev/i2c-1"
#define MPU6050_ADDRESS 0x68
#define PWR_MGMT_1_REG 0x6B
#define GYRO_XOUT_H_REG 0x43
#define GYRO_XOUT_L_REG 0x43 + 1
#define GYRO_YOUT_H_REG 0x44
#define GYRO_YOUT_L_REG 0x44 + 1
#define GYRO_ZOUT_H_REG 0x45
#define GYRO_ZOUT_L_REG 0x45 + 1
#define SENSITIVITY 131.0

// Function prototypes
void init_gyro();
void read_gyro_data(int fd);
void write_power_management(int fd, uint8_t value);
void convert_lsb_to_degrees(int16_t lsb);
void log_gyro_data(int fd, int16_t x, int16_t y, int16_t z, const char *timestamp);
void cleanup();

int main() {
    int fd;
    struct timeval start, diff;
    char gyro_log_path[] = "gyro_log.txt";
    char buffer[8];

    // Initialize the gyro
    if ((fd = open(I2C_DEVICE_PATH, O_RDWR)) < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    init_gyro(fd);

    while (1) {
        // Read power management register to wake the sensor
        if (write_power_management(fd, 0x00) != 2) {
            perror("write_power_management");
            break;
        }

        // Read gyro data
        if (read_gyro_data(fd, buffer) != 6) {
            perror("read_gyro_data");
            break;
        }

        // Convert LSB to degrees/second
        convert_lsb_to_degrees(buffer[0], &buffer[1]);
        convert_lsb_to_degrees(buffer[2], &buffer[3]);
        convert_lsb_to_degrees(buffer[4], &buffer[5]);

        // Log the data
        if (log_gyro_data(fd, buffer[0], buffer[1], buffer[2], "Gyro X, Y, Z: ")) != 0) {
            perror("log_gyro_data");
            break;
        }

        // Sleep for 100 ms
        gettimeofday(&start, NULL);
        usleep(100000);
        gettimeofday(&diff, NULL);
        printf("Time elapsed: %ld us\n", (long)(diff.tv_sec * 1000000 + diff.tv_usec - start.tv_sec * 1000000 - start.tv_usec));

        // Check for interrupt signals
        if (signal(SIGINT) == SIG_IGN) {
            signal(SIGINT, SIG_DFL);
        }
        if (signal(SIGTERM) == SIG_IGN) {
            signal(SIGTERM, SIG_DFL);
        }
    }

    // Clean up
    cleanup();

    return 0;
}

// Function to initialize the gyro
void init_gyro(int fd) {
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDRESS) < 0) {
        perror("ioctl: i2c slave");
        close(fd);
        exit(EXIT_FAILURE);
    }
}

// Function to read gyro data from the specified file descriptor
void read_gyro_data(int fd, uint8_t *data) {
    if (ioctl(fd, I2C_READ, (char *)data) != 6) {
        perror("ioctl: i2c read");
        close(fd);
        exit(EXIT_FAILURE);
    }
}

// Function to write to the power management register
void write_power_management(int fd, uint8_t value) {
    if (ioctl(fd, I2C_WRITE, &value) != 2) {
        perror("ioctl: i2c write");
        close(fd);
        exit(EXIT_FAILURE);
    }
}

// Function to convert 16-bit signed value from LSB to degrees/second
void convert_lsb_to_degrees(int16_t lsb, int16_t *degrees) {
    *degrees = lsb * SENSITIVITY / 32768.0;
}

// Function to log gyro data with a timestamp
int log_gyro_data(int fd, int16_t x, int16_t y, int16_t z, const char *timestamp) {
    FILE *file = fopen(gyro_log_path, "a+");
    if (!file) {
        perror("fopen gyro_log.txt");
        return -1;
    }

    fprintf(file, "%s: X=%d, Y=%d, Z=%d\n", timestamp, x, y, z);
    fclose(file);

    return 0;
}

// Function to clean up resources and exit
void cleanup() {
    close(fd);
    printf("Gyro data logging stopped.\n");
    exit(EXIT_SUCCESS);
}

