    if (!playing) {
        playing = 1;
        debounce_count = 0;
        printf("Button pressed, starting melody...\n");
    } else {
        playing = 0;
        printf("Melody stopped due to button press during playback.\n");
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", pigpioError());
        return EXIT_FAILURE;
    }

    // Set GPIO17 as input with internal pull-up, active-low
    if (gpioSetMode(BUTTON_GPIO, GPIO_INPUT | GPIO_PULLUP | GPIO_ACTIVE_LOW) < 0) {
        fprintf(stderr, "Failed to set GPIO %d mode: %s\n", BUTTON_GPIO, pigpioError());
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set GPIO18 as output for PWM
    if (gpioSetMode(BUZZER_GPIO, GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d mode: %s\n", BUZZER_GPIO, pigpioError());
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Configure GPIO18 for hardware PWM with 50% duty cycle
    if (gpioSetFuncEx(BUZZER_GPIO, GPIO Hardware PWM, 1, 50) < 0) {
        fprintf(stderr, "Failed to set GPIO %d for hardware PWM: %s\n", BUZZER_GPIO, pigpioError());
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up the ISR for button press
    if (gpioSetISRFuncEx(BUTTON_GPIO, GPIO_RISING, button_ISR, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR for GPIO %d: %s\n", BUTTON_GPIO, pigpioError());
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Signal handlers for graceful shutdown
    struct sigaction int_handler, term_handler;
    sigemptyset(&int_handler.sa_mask);
    int_handler.sa_handler = SIG_IGN;
    sigaction(SIGINT, &int_handler, NULL);
    sigemptyset(&term_handler.sa_mask);
    term_handler.sa_handler = cleanup;
    sigaction(SIGTERM, &term_handler, NULL);

    // Main loop
    while (1) {
        // Debounce the button
        if (debounce_count < 50) {
            sleep(1);
            debounce_count++;
        } else {
            debounce_count = 0;
        }

        if (playing) {
            // Play the melody
            for (int i = 0; i < sizeof(melody) / sizeof(melody[0]); i++) {
                int duration = melody[i];
                gpioHardwarePWM(BUZZER_GPIO, duration);
                sleep(100); // Small delay to avoid rapid frequency changes
            }
        }
    }

    // Cleanup function for SIGINT or SIGTERM
    void cleanup() {
        playing = 0;
        gpioHardwarePWM(BUZZER_GPIO, 0); // Stop PWM
        gpioTerminate(); // Clean shutdown
        printf("Exiting cleanly...\n");
    }

    return EXIT_SUCCESS;
}

