#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>
#include <sys/stat.h>
#include <fcntl.h>

#define GPIO_NUM 17
#define FILE_NAME "vibration_events.log"
#define WINDOW_SIZE 5
#define DEFAULT_POLL_MS 1000

volatile sig_atomic_t sigIntFlag = 0;

void sigHandler(int signum) {
    sigIntFlag = 1;
}

int main(int argc, char **argv) {
    struct gpiod_line *line;
    int fd;
    char buffer[128];
    time_t now;
    struct tm *timeinfo;
    int events_count = 0;
    int earthquake_detected = 0;
    int poll_ms = DEFAULT_POLL_MS;

    if (argc > 1) {
        poll_ms = atoi(argv[1]);
    }

    if ((fd = open(FILE_NAME, O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR)) == -1) {
        perror("Error opening log file");
        exit(EXIT_FAILURE);
    }

    line = gpiod_line_request_one(GPIO_NUM, GPIOD_LINE_IN, GPIOD_DIR_IN);
    if (!line) {
        perror("Error requesting GPIO line");
        close(fd);
        exit(EXIT_FAILURE);
    }

    while (!sigIntFlag) {
        now = time(NULL);
        timeinfo = localtime(&now);

        // Check for rising edge
        if (gpiod_line_event_wait(line, GPIOD_EDGE_RISING, poll_ms) == 0) {
            snprintf(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S.%03u HIGH\n", timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_day, timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec, (unsigned int)(now - (time_t *)(&timeinfo))));
            if (write(fd, buffer, strlen(buffer)) != strlen(buffer)) {
                perror("Error writing to log file");
                gpiod_line_release(line);
                close(fd);
                exit(EXIT_FAILURE);
            }
            events_count++;
            if (earthquake_detected && events_count >= WINDOW_SIZE) {
                printf("EARTHQUAKE ALERT at %s\n", buffer);
            }
            earthquake_detected = 0;
        }

        // Check for falling edge
        if (gpiod_line_event_wait(line, GPIOD_EDGE_FALLING, poll_ms) == 0) {
            snprintf(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S.%03u LOW\n", timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_day, timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec, (unsigned int)(now - (time_t *)(&timeinfo))));
            if (write(fd, buffer, strlen(buffer)) != strlen(buffer)) {
                perror("Error writing to log file");
                gpiod_line_release(line);
                close(fd);
                exit(EXIT_FAILURE);
            }
            events_count++;
            if (!earthquake_detected && events_count < WINDOW_SIZE) {
                earthquake_detected = 1;
            }
        }

        // Release the line if signal received
        if (sigIntFlag) {
            gpiod_line_release(line);
            close(fd);
            exit(EXIT_SUCCESS);
        }

        // Flush the log file buffer
        fflush(fd);

        // Implement sliding window logic
        if (events_count >= WINDOW_SIZE) {
            events_count = 0;
            earthquake_detected = 0;
        }
    }

    // Release the line on exit
    gpiod_line_release(line);

    // Close the log file
    close(fd);

    return 0;
}

