    fprintf(csv_file, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading\n");
    fflush(csv_file);

    // Main loop
    while (1) {
        // Read magnetometer data
        read_magnetometer();

        // Apply calibration and compute heading
        apply_calibration(&magnetometerData);
        compute_heading(&magnetometerData.X, &magnetometerData.Y);

        // Write to CSV and print direction
        write_to_csv(format_csv_line());
        printf("Heading: %s %f°\n", compassDirections[(int)compute_compass_direction()], compute_compass_direction() * 180.0 / M_PI);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Cleanup
    cleanup();

    return EXIT_SUCCESS;
}

// Function to setup I2C
void setup_i2c() {
    struct i2c_dev *i2c_dev;
    int ret;

    // Open I2C device
    ret = i2c_open(I2C_DEVICE_PATH, &i2c_dev);
    if (ret < 0) {
        perror("i2c_open");
        return;
    }

    // Set SDA and SCL GPIOs
    ret = gpio_export(SDA_GPIO, GPIO_EXPORT_DIR_OUT);
    if (ret < 0) {
        perror("gpio_export SDA");
        i2c_close(i2c_dev);
        return;
    }
    ret = gpio_export(SCL_GPIO, GPIO_EXPORT_DIR_OUT);
    if (ret < 0) {
        perror("gpio_export SCL");
        gpio_unexport(SDA_GPIO);
        gpio_unexport(SCL_GPIO);
        i2c_close(i2c_dev);
        return;
    }

    // Write I2C address and enable I2C interface
    ret = i2c_smbus_write_i2c_address(i2c_dev, MAGNETOMETER_ADDRESS);
    if (ret < 0) {
        perror("i2c_smbus_write_i2c_address");
        gpio_unexport(SDA_GPIO);
        gpio_unexport(SCL_GPIO);
        i2c_close(i2c_dev);
        return;
    }
    ret = i2c_set_bit(i2c_dev, I2C_MST_SDA);
    if (ret < 0) {
        perror("i2c_set_bit SDA");
        gpio_unexport(SDA_GPIO);
        gpio_unexport(SCL_GPIO);
        i2c_close(i2c_dev);
        return;
    }
    ret = i2c_set_bit(i2c_dev, I2C_MST_SCL);
    if (ret < 0) {
        perror("i2c_set_bit SCL");
        gpio_unexport(SDA_GPIO);
        gpio_unexport(SCL_GPIO);
        i2c_close(i2c_dev);
        return;
    }

    // Close GPIO resources
    gpio_unexport(SDA_GPIO);
    gpio_unexport(SCL_GPIO);
}

// Function to read magnetometer data
void read_magnetometer() {
    int ret;

    // Write to enable continuous conversion mode
    ret = i2c_smbus_write_word_data(i2c_dev, CONTINUOUS_CONVERSION_REG, 0x00);
    if (ret < 0) {
        perror("i2c_smbus_write_word_data continuous conversion");
        return;
    }

    // Write to set data rate to 15 Hz
    ret = i2c_smbus_write_byte_data(i2c_dev, DATA_RATE_REG, 0x14);
    if (ret < 0) {
        perror("i2c_smbus_write_byte_data data rate");
        return;
    }

    // Read magnetometer data registers
    for (int reg = MAG_REG_OFFSET; reg <= CALIB_REG_OFFSET + 1; reg++) {
        ret = i2c_smbus_read_word_data(i2c_dev, reg);
        if (ret < 0) {
            perror("i2c_smbus_read_word_data magnetometer register");
            return;
        }

        // Store raw data
        magnetometerData.registers[reg - MAG_REG_OFFSET] = ret;
    }
}

// Function to apply hard-iron calibration
void apply_calibration(float *data) {
    data[MAG_REG_OFFSET] += X_OFFSET;
    data[MAG_REG_OFFSET + 1] -= Y_OFFSET;
    data[MAG_REG_OFFSET + 2] += Z_OFFSET;
}

// Function to compute compass heading
void compute_heading(float x, float y) {
    float heading = atan2f(y, x);
    heading = fmod(heading * 180.0 / M_PI, 360.0);
    if (heading < 0) {
        heading += 360.0;
    }
    return heading;
}

// Function to write to CSV file
void write_to_csv(const char *line) {
    if (fwrite(line, 1, strlen(line), csv_file) != 1) {
        perror("fwrite to CSV file");
        fclose(csv_file);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

// Function to cleanup resources
void cleanup() {
    // Close I2C device
    i2c_close(i2c_dev);
    // Unexport GPIOs
    gpio_unexport(SDA_GPIO);
    gpio_unexport(SCL_GPIO);

    // Close CSV file
    fclose(csv_file);
    // Close I2C device file descriptor
    close(i2c_fd);
}

// Format a line for CSV
char *format_csv_line() {
    static char line[256];
    sprintf(line, "%f,%f,%f,%f,%f", magnetometerData.X, magnetometerData.Y, magnetometerData.Z, compute_compass_direction(), compute_compass_direction() * 180.0 / M_PI);
    return line;
}

// Compute compass direction from heading
int compute_compass_direction() {
    float heading = compute_heading(magnetometerData.X, magnetometerData.Y);
    for (int i = 0; i < NUM_COMPASS_DIRECTIONS; ++i) {
        if (heading >= (i * 45.0) && heading < ((i + 1) * 45.0)) {
            return i;
        }
    }
    return NUM_COMPASS_DIRECTIONS; // Handle edge cases
}

