volatile int touch_detected = 0;

// Function to debounce touch using a simple timer
static void debounce_touch() {
    static struct timeval last_touch_time;
    struct timeval now;

    gettimeofday(&now, NULL);

    if (now.tv_sec - last_touch_time.tv_sec >= 200 || (now.tv_usec - last_touch_time.tv_usec >= 200000)) {
        touch_detected = !touch_detected; // Toggle the relay state
        if (touch_detected) {
            // Turn relay ON
            pigpio_write(RELAY_PIN, 1);
        } else {
            // Turn relay OFF
            pigpio_write(RELAY_PIN, 0);
        }

        // Append to the log file
        char timestamp[32];
        time_t rawtime = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&rawtime));
        char relay_state[5];
        snprintf(relay_state, sizeof(relay_state), "%s", touch_detected ? "ON" : "OFF");

        FILE *log_file = fopen("relay_log.json", "a+");
        if (log_file) {
            fprintf(log_file, "{\"timestamp\":\"%s\",\"relay_state\":\"%s\"}\n", timestamp, relay_state);
            fclose(log_file);
        }
    }

    last_touch_time = now;
}

// GPIO ISR callback function
