        pigpioTerminate(pg);
        return EXIT_FAILURE;
    }

    // Set up ISR for GPIO4
    if (pigpioSetISRFunc(pg, TOUCH_SENSOR_PIN, touch_isr_callback, NULL) == -1) {
        fprintf(stderr, "Failed to set ISR for GPIO4: %s\n", pigpio_error());
        pigpioTerminate(pg);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        sleep(1); // Simple polling loop for demonstration; replace with a proper event loop in a real application
