#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <gpiod.h>

#define RELAY_GPIO_PINS {17, 23, 24, 25}
#define NUM_RELAYS (sizeof(RELAY_GPIO_PINS) / sizeof(RELAY_GPIO_PINS[0]))

// Function prototypes
void setup_gpios();
void activate_relay(int relay, int moisture);
void deactivate_relay(int relay);
void log_activation(char* timestamp, int relay, int moisture);
void cleanup();

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Initialize GPIO and log file
    setup_gpios();
    FILE* log_file = fopen("irrigation_log.txt", "a+");
    if (log_file == NULL) {
        perror("Failed to open irrigation_log.txt");
        exit(EXIT_FAILURE);
    }

    // Signal handlers for graceful shutdown
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        // Simulate soil moisture level
        int moisture = rand() % 101; // Random value from 0 to 100

        // Check moisture level
        if (moisture < 30) {
            for (int i = 0; i < NUM_RELAYS; i++) {
                activate_relay(i, moisture);
                usleep(5000); // 5 seconds
                deactivate_relay(i);
                usleep(1000); // 1 second gap
            }
        }

        // Log activation
        char timestamp[32];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
        log_activation(timestamp, rand() % NUM_RELAYS, moisture);

        // Sleep for 10 seconds
        usleep(10000 * 1000);
    }

    // Clean up on SIGINT or SIGTERM
    return 0;
}

// Function to setup GPIO pins
void setup_gpios() {
    int fd;
    struct gpiod_chip *chip;

    // Open the GPIO chip
    fd = open("/dev/gpiom", O_RDWR);
    if (fd == -1) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request the GPIO lines as outputs with inactive drive of 1
    chip = gpiod_chip_open(fd);
    if (!chip) {
        perror("Failed to open GPIO chip");
        gpiod_chip_close(chip);
        close(fd);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        struct gpiod_pin_desc desc;
        desc.direction = GPIOD_DIR_OUT_INIT_LOW;
        desc.value = 1; // Initial inactive state (high)

        if (gpiod_pin_request(chip, RELAY_GPIO_PINS[i], &desc) < 0) {
            perror("Failed to request GPIO pin");
            gpiod_chip_close(chip);
            close(fd);
            exit(EXIT_FAILURE);
        }
    }

    gpiod_chip_close(chip);
    close(fd);
}

// Function to activate a relay
void activate_relay(int relay, int moisture) {
    int fd;
    struct gpiod_pin_desc desc;

    // Open the specific GPIO pin
    fd = open("/dev/gpiom", O_RDWR);
    if (fd == -1) {
        perror("Failed to open GPIO pin");
        return;
    }

    // Set the GPIO pin to low (activate relay)
    desc.direction = GPIOD_DIR_OUT_INIT_LOW;
    desc.value = 0;

    if (gpiod_pin_write(fd, RELAY_GPIO_PINS[relay], &desc) < 0) {
        perror("Failed to write to GPIO pin");
        close(fd);
        return;
    }

    // Keep the relay activated for 5 seconds
    usleep(5000 * 1000);

    // Deactivate the relay
    desc.value = 1;
    if (gpiod_pin_write(fd, RELAY_GPIO_PINS[relay], &desc) < 0) {
        perror("Failed to deactivate GPIO pin");
        close(fd);
        return;
    }

    close(fd);
}

// Function to deactivate a relay
void deactivate_relay(int relay) {
    int fd;
    struct gpiod_pin_desc desc;

    // Open the specific GPIO pin
    fd = open("/dev/gpiom", O_RDWR);
    if (fd == -1) {
        perror("Failed to open GPIO pin");
        return;
    }

    // Set the GPIO pin to high (deactivate relay)
    desc.direction = GPIOD_DIR_OUT_INIT_LOW;
    desc.value = 1;

    if (gpiod_pin_write(fd, RELAY_GPIO_PINS[relay], &desc) < 0) {
        perror("Failed to write to GPIO pin");
        close(fd);
        return;
    }

    close(fd);
}

// Function to log activation with ISO-8601 timestamp
void log_activation(char* timestamp, int relay, int moisture) {
    char log_message[256];
    snprintf(log_message, sizeof(log_message), "%s, Relay %d, Moisture: %d", timestamp, relay, moisture);

    if (fwrite(log_message, sizeof(log_message), 1, log_file) != 1) {
        perror("Failed to write to log file");
        exit(EXIT_FAILURE);
    }
    fflush(log_file);
}

// Function to clean up and exit on SIGINT or SIGTERM
void cleanup() {
    // Deactivate all relays
    for (int i = 0; i < NUM_RELAYS; i++) {
        deactivate_relay(i);
    }

    // Close the log file
    fclose(log_file);

    // Release the GPIO chip
    gpiod_chip_close(gpiod_chip_open("/dev/gpiom"));
    close("/dev/gpiom");

    // Exit cleanly
    exit(EXIT_SUCCESS);
}

