#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define I2C_DEVICE_PATH "/dev/i2c-1"
#define MPU6050_ADDRESS 0x68
#define PWR_MGMT_1_REG 0x6B
#define GYRO_XOUT_H_REG 0x43
#define GYRO_XOUT_L_REG 0x43
#define GYRO_YOUT_H_REG 0x44
#define GYRO_YOUT_L_REG 0x44
#define GYRO_ZOUT_H_REG 0x45
#define GYRO_ZOUT_L_REG 0x45

#define SENSITIVITY 131.0
#define SAMPLE_RATE_HZ 10

volatile sig_atomic_t should_exit = 0;

void write_reg(uint8_t reg, uint8_t value) {
    int fd = open(I2C_DEVICE_PATH, O_RDWR);
    if (fd == -1) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    struct i2c_msg msg = {
        .addr = MPU6050_ADDRESS,
        .flags = 0,
        .len = 1,
        .buf = (uint8_t *) &value
    };

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDRESS) < 0) {
        perror("Failed to change I2C address");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (write(fd, &msg, sizeof(msg)) != sizeof(msg)) {
        perror("Failed to write to I2C device");
        close(fd);
        exit(EXIT_FAILURE);
    }
}

void read_gyro_data(uint8_t *data) {
    int fd = open(I2C_DEVICE_PATH, O_RDWR);
    if (fd == -1) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    struct i2c_msg msg1 = {
        .addr = MPU6050_ADDRESS,
        .flags = 0,
        .len = 6,
        .buf = data
    };

    struct i2c_msg msg2[2] = {
        { .addr = MPU6050_ADDRESS, .flags = I2C_M_RD, .len = 1, .buf = NULL },
        { .addr = MPU6050_ADDRESS, .flags = I2C_M_RD, .len = 1, .buf = NULL }
    };

    if (ioctl(fd, I2C_transfer, msg2) != 2) {
        perror("Failed to read from I2C device");
        close(fd);
        exit(EXIT_FAILURE);
    }

    close(fd);
}

void convert_gyro_data(uint16_t raw_x, uint16_t raw_y, uint16_t raw_z) {
    double x_deg_per_s = (raw_x * SENSITIVITY) / 32768.0;
    double y_deg_per_s = (raw_y * SENSITIVITY) / 32768.0;
    double z_deg_per_s = (raw_z * SENSITIVITY) / 32768.0;

    printf("X: %.2f, Y: %.2f, Z: %.2f deg/s\n", x_deg_per_s, y_deg_per_s, z_deg_per_s);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!should_exit) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);

        uint8_t power_management_1_data;
        read_reg(PWR_MGMT_1_REG, 0x00);

        uint16_t gyro_data[6];
        read_gyro_data(gyro_data);

        convert_gyro_data(gyro_data[0], gyro_data[1], gyro_data[2]);

        char timestamp[50];
        snprintf(timestamp, sizeof(timestamp), "%ld.%06ld", (long)ts.tv_sec, (long)(ts.tv_nsec / 1000000));

        FILE *log_file = fopen("gyro_log.txt", "a+");
        if (!log_file) {
            perror("Failed to open gyro_log.txt");
            continue;
        }

        fprintf(log_file, "%s, %f, %f, %f\n", timestamp, gyro_data[0] / 1000.0, gyro_data[1] / 1000.0, gyro_data[2] / 1000.0);
        fclose(log_file);

        usleep(SAMPLE_RATE_HZ * 1000);
    }

    printf("Exiting gracefully...\n");

    return 0;
}

void handle_signal(int signum) {
    should_exit = 1;
}

