#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// GPIO pins for Raspberry Pi
#define BCM_GPIO24   18
#define BCM_GPIO23   22
#define BCM_GPIO4    7
#define BCM_GPIO17   11
#define BCM_GPIO27   13
#define BCM_GPIO22   15

// GPIO mode constants
#define GPIO_MODE_OUT  1

// Motor step count for a quarter turn
#define STEPS_PER_QUARTER_TURN 512

// Function prototypes
void initialise_pigpio();
void cleanup_pigpio();
void handle_button_press(int button);
void rotate_motor(int direction, int steps);
void debounce_button(int button);
void handle_signal(int signum);

int main() {
    // Initialize pigpio library
    if (gpioInitialise() == -1) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", gpioError());
        return EXIT_FAILURE;
    }

    // Set GPIO modes and pull-up configurations
    if (gpioSetMode(BCM_GPIO24, GPIO_MODE_OUT) == -1 ||
        gpioSetMode(BCM_GPIO23, GPIO_MODE_OUT) == -1 ||
        gpioSetMode(BCM_GPIO4, GPIO_MODE_OUT) == -1 ||
        gpioSetMode(BCM_GPIO17, GPIO_MODE_OUT) == -1 ||
        gpioSetMode(BCM_GPIO27, GPIO_MODE_OUT) == -1 ||
        gpioSetMode(BCM_GPIO22, GPIO_MODE_OUT) == -1 ||
        gpioSetPullUpDown(BCM_GPIO24, GPIO_PULLUP) == -1 ||
        gpioSetPullUpDown(BCM_GPIO23, GPIO_PULLUP) == -1 ||
        gpioSetPullUpDown(BCM_GPIO4, GPIO_NOPULL) == -1 ||
        gpioSetPullUpDown(BCM_GPIO17, GPIO_NOPULL) == -1 ||
        gpioSetPullUpDown(BCM_GPIO27, GPIO_NOPULL) == -1 ||
        gpioSetPullUpDown(BCM_GPIO22, GPIO_NOPULL) == -1) {
        fprintf(stderr, "Failed to configure GPIO pins: %s\n", gpioError());
        cleanup_pigpio();
        return EXIT_FAILURE;
    }

    // Signal handler for SIGINT
    signal(SIGINT, handle_signal);

    // Main loop
    while (1) {
        debounce_button(BCM_GPIO23); // Debounce UNLOCK button
        if (gpioRead(BCM_GPIO23) == 0) {
            rotate_motor(-1, STEPS_PER_QUARTER_TURN); // Counter-clockwise
        }

        debounce_button(BCM_GPIO24); // Debounce LOCK button
        if (gpioRead(BCM_GPIO24) == 0) {
            rotate_motor(1, STEPS_PER_QUARTER_TURN); // Clockwise
        }

        // Short delay for debounce
        usleep(50);
    }

    // Cleanup
    cleanup_pigpio();

    return EXIT_SUCCESS;
}

// Function to initialise pigpio
void initialise_pigpio() {
    if (gpioInitialise() == -1) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", gpioError());
        exit(EXIT_FAILURE);
    }
}

// Function to cleanup pigpio
void cleanup_pigpio() {
    gpioTerminate();
}

// Function to handle button press
void handle_button_press(int button) {
    if (gpioRead(button) == 0) {
        printf("Button pressed: %s\n", (button == BCM_GPIO24) ? "LOCK" : "UNLOCK");
    }
}

// Function to rotate the motor
void rotate_motor(int direction, int steps) {
    int i;
    for (i = 0; i < steps; i++) {
        gpioWrite(BCM_GPIO4, direction);
        gpioWrite(BCM_GPIO17, direction);
        gpioWrite(BCM_GPIO27, direction);
        gpioWrite(BCM_GPIO22, direction);

        usleep(3000); // 3 ms delay between steps

        // De-energize coils after each quarter turn
        if (i % (steps / 4) == 0) {
            gpioWrite(BCM_GPIO4, 0);
            gpioWrite(BCM_GPIO17, 0);
            gpioWrite(BCM_GPIO27, 0);
            gpioWrite(BCM_GPIO22, 0);
        }
    }
}

// Function to debounce button reads
void debounce_button(int button) {
    int state = gpioRead(button);
    if (state != gpioRead(button)) {
        usleep(50); // Short delay for debounce
        handle_button_press(button);
    }
}

// Function to handle SIGINT
void handle_signal(int signum) {
    printf("SIGINT received, de-energizing coils...\n");
    gpioWrite(BCM_GPIO4, 0);
    gpioWrite(BCM_GPIO17, 0);
    gpioWrite(BCM_GPIO27, 0);
    gpioWrite(BCM_GPIO22, 0);
    exit(EXIT_SUCCESS); // Exit cleanly
}

