#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>
#include <sys/time.h>

#define TRIGGER_GPIO 17
#define ECHO_GPIO 18

#define TIMEOUT_MS 50000
#define GUARD_MS 60000

// Constants for distance calculation
#define SPEED_OF_SOUND 343.0
#define CM_PER_M 0.01

// Function prototypes
void initialize_gpios();
void send_trigger_pulse();
void measure_echo();
void handle_signal(int signum);
void cleanup();

int main() {
    // Initialize GPIOs
    initialize_gpios();

    // Signal handler for SIGINT and SIGTERM
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (1) {
        // Measure distance
        measure_echo();
        usleep(GUARD_MS * 1000); // Enforce guard time

        // Log the distance
        FILE *log_file = fopen("distance_log.txt", "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file for append.\n");
            continue;
        }

        fprintf(log_file, "%lu\n", measure_distance_cm());
        fclose(log_file);

        // Check if we should exit
        if (measure_distance_us() == TIMEOUT_MS) {
            fprintf(stderr, "Timeout error, distance measurement failed.\n");
            break;
        }
    }

    // Clean up
    cleanup();

    return 0;
}

// Function to initialize GPIOs
void initialize_gpios() {
    struct gpiod_dir_config dir_config;
    struct gpiod_set_config set_config;

    // Set GPIO17 as output
    dir_config.direction = GPIOD_DIR_OUT_INIT_HIGH;
    set_config.direction = dir_config;
    if (gpiod_set_config(TRIGGER_GPIO, &set_config) < 0) {
        fprintf(stderr, "Failed to configure GPIO %u as output.\n", TRIGGER_GPIO);
        exit(EXIT_FAILURE);
    }

    // Set GPIO18 as input
    dir_config.direction = GPIOD_DIR_IN;
    set_config.direction = dir_config;
    if (gpiod_set_config(ECHO_GPIO, &set_config) < 0) {
        fprintf(stderr, "Failed to configure GPIO %u as input.\n", ECHO_GPIO);
        exit(EXIT_FAILURE);
    }
}

// Function to send a trigger pulse
void send_trigger_pulse() {
    struct gpiod_value value;
    value.value = 1; // High pulse
    gpiod_write_value(TRIGGER_GPIO, &value, 10); // 10 microseconds
}

// Function to measure the echo pulse width
void measure_echo() {
    struct timespec timeout;
    struct timespec start, end;
    long duration_us;

    // Initialize timeout
    timeout.tv_sec = 0;
    timeout.tv_nsec = TIMEOUT_MS * 1000000;

    // Start timer
    clock_gettime(CLOCK_MONOTONIC, &start);

    // Busy-wait for echo pulse
    while (true) {
        if (gpiod_read_value(ECHO_GPIO, &value) && value.value) {
            // Echo detected, stop the timer
            clock_gettime(CLOCK_MONOTONIC, &end);
            duration_us = (end.tv_sec * 1000000000 + end.tv_nsec) - (start.tv_sec * 1000000000 + start.tv_nsec);
            if (duration_us > 0) {
                // Convert microseconds to centimeters
                float distance_cm = duration_us * CM_PER_M * SPEED_OF_SOUND / 1000000.0;
                return distance_cm; // Return distance in cm
            }
        }

        // Check if we timed out
        if (clock_gettime(CLOCK_MONOTONIC, &start) - start >= timeout) {
            fprintf(stderr, "Timeout error, no echo detected.\n");
            return -1; // Log -1 for timeout
        }
    }
}

// Signal handler function
void handle_signal(int signum) {
    // Clean up GPIOs and close log file
    cleanup();
}

// Function to clean up resources
void cleanup() {
    gpiod_remove(TRIGGER_GPIO);
    gpiod_remove(ECHO_GPIO);
    fclose("distance_log.txt");
}

