#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <gpiod.h>

#define VL53L1X_I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define VL53L1X_REG_RESET 0x0000
#define VL53L1X_REG_RANGING_MODE 0x0080
#define VL53L1X_REG_CONTINUOUS_RANGING 0x01
#define VL53L1X_REG_DATA_READY 0x0044
#define VL53L1X_REG_DISTANCE_MSB 0x0096
#define VL53L1X_REG_DISTANCE_LSB 0x0097
#define BCM_GPIO18 18

volatile int door_open = 0;

// Function prototypes
void setup_vl53l1x();
void poll_vl53l1x();
void handle_signal(int signum);

int main() {
    // Initialize pigpio
    if (pigpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error());
        return EXIT_FAILURE;
    }

    // Open I2C bus 1
    if (gpiod_i2c_open(VL53L1X_I2C_BUS) < 0) {
        fprintf(stderr, "Failed to open I2C bus %d: %s\n", VL53L1X_I2C_BUS, gpiod_error());
        pigpio_cleanup(); // Close pigpio
        return EXIT_FAILURE;
    }

    // Setup VL53L1X
    setup_vl53l1x();

    // Signal handler for SIGINT
    signal(SIGINT, handle_signal);

    // Main loop
    while (1) {
        poll_vl53l1x();
        usleep(100000); // 100 ms delay
    }

    // Clean up on SIGINT
    handle_signal(SIGINT);

    // Close I2C handle and release resources
    gpiod_i2c_close(VL53L1X_I2C_BUS);

    // Shutdown pigpio
    pigpio_cleanup();

    return EXIT_SUCCESS;
}

// Function to reset the VL53L1X
void setup_vl53l1x() {
    if (gpiod_i2c_write(VL53L1X_I2C_BUS, VL53L1X_ADDR, &VL53L1X_REG_RESET, 1, 0) < 0) {
        fprintf(stderr, "Failed to reset VL53L1X: %s\n", gpiod_error());
        return;
    }
}

// Function to poll the VL53L1X
void poll_vl53l1x() {
    int data_ready = 0;
    if (gpiod_i2c_read(VL53L1X_I2C_BUS, VL53L1X_ADDR, &VL53L1X_REG_DATA_READY, 1, &data_ready) < 0) {
        fprintf(stderr, "Failed to read data ready register: %s\n", gpiod_error());
        return;
    }

    if (data_ready) {
        uint16_t distance = 0;
        if (gpiod_i2c_read(VL53L1X_I2C_BUS, VL53L1X_ADDR, &VL53L1X_REG_DISTANCE_MSB, 1, &distance) < 0 ||
            gpiod_i2c_read(VL53L1X_I2C_BUS, VL53L1X_ADDR, &VL53L1X_REG_DISTANCE_LSB, 1, &distance) < 0) {
            fprintf(stderr, "Failed to read distance: %s\n", gpiod_error());
            return;
        }

        // Convert 16-bit distance to cm
        distance = (distance << 8) | (gpiod_i2c_read(VL53L1X_I2C_BUS, VL53L1X_ADDR, &VL53L1X_REG_DISTANCE_LSB, 1, NULL) << 8);

        // Log distance
        printf("Distance: %u cm\n", distance);

        // Control the relay
        if (distance <= 50) {
            door_open = 1;
            if (gpiod_set_data(BCM_GPIO18, GPIO_ACTIVE_HIGH) < 0) {
                fprintf(stderr, "Failed to set GPIO18 HIGH: %s\n", gpiod_error());
            } else {
                printf("Door opened.\n");
            }
        } else {
            door_open = 0;
            if (gpiod_set_data(BCM_GPIO18, GPIO_ACTIVE_LOW) < 0) {
                fprintf(stderr, "Failed to set GPIO18 LOW: %s\n", gpiod_error());
            } else {
                printf("Door closed.\n");
            }
        }
    }
}

// Handle SIGINT
void handle_signal(int signum) {
    fprintf(stderr, "SIGINT received, cleaning up...\n");
    door_open = 0;
    gpiod_set_data(BCM_GPIO18, GPIO_ACTIVE_LOW); // Set relay LOW
    pigpio_cleanup(); // Shutdown pigpio
}

