#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>

#define I2C_DEVICE "/dev/i2c-1"
#define MPU6050_ADDRESS 0x68
#define PWR_MGMT_1_REG 0x6B
#define GYRO_CONFIG_REG 0x1B
#define GYRO_DATA_REG 0x43

#define SENSITIVITY 131.0 // LSB per dps

volatile sig_atomic_t should_exit = 0;

void handle_signal(int signum) {
    should_exit = 1;
}

int main() {
    // Set up signal handler for SIGINT and SIGTERM
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open I2C device
    int i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Check if device is accessible
    struct i2c_device_id ids[] = {
        { "mpu6050", I2C_DEVICE },
        { }
    };
    int num_ids = ARRAY_SIZE(ids);
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDRESS) < 0) {
        perror("Failed to access I2C slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Wake up the sensor
    uint8_t wake_up_cmd = 0x08;
    if (write(i2c_fd, &wake_up_cmd, 1) != 1) {
        perror("Failed to wake up sensor");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Set gyroscope full-scale range to ±250 dps
    uint8_t config_cmd = 0x00;
    if (write(i2c_fd, &config_cmd, 1) != 1) {
        perror("Failed to set gyroscope config");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop until SIGINT/SIGTERM received
    while (!should_exit) {
        // Read gyroscope data
        uint8_t data[6];
        if (read(i2c_fd, data, 6) != 6) {
            perror("Failed to read gyroscope data");
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        // Convert raw data to degrees/second
        float x_dps = (data[0] * SENSITIVITY) / 32768.0;
        float y_dps = (data[1] * SENSITIVITY) / 32768.0;
        float z_dps = (data[2] * SENSITIVITY) / 32768.0;

        // Print axis readings
        printf("Gyro X: %.2f dps, Gyro Y: %.2f dps, Gyro Z: %.2f dps\n",
               x_dps, y_dps, z_dps);

        // Delay for smooth output (adjust as needed)
        usleep(100000);
    }

    // Close I2C device
    close(i2c_fd);

    return EXIT_SUCCESS;
}

