void setup_pigpio() {
    pi = NULL;
    if (gpioInitialise() == -1) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", gpioError());
        exit(EXIT_FAILURE);
    }
    pi = pigpioOpen();
    if (pi == NULL) {
        fprintf(stderr, "Failed to open pigpio: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }
