        exit(EXIT_FAILURE);
    }
}

// Function to setup relay GPIO pins
void setup_relays() {
    for (int i = 0; i < 4; i++) {
        if (gpioMode(pi, relay_pins[i], GPIO_OUTPUT_PWM) == -1) {
            fprintf(stderr, "Failed to set GPIO %d to PWM output: %s\n", relay_pins[i], gpioError());
            exit(EXIT_FAILURE);
        }
        duty_cycles[i] = 0; // Initialize duty cycle to 0
    }
    fprintf(log_file, "Relay setup complete at %s\n", ctime(&time(NULL)));
}

// Function to start the sunrise simulation
void start_sunrise() {
    struct timespec interval;
    interval.tv_sec = 1; // 1 second interval
    interval.tv_nsec = 0; // No nanoseconds

    for (int duty = 0; duty <= 255; duty++) {
        for (int i = 0; i < 4; i++) {
            gpioWritePWM(pi, relay_pins[i], duty_cycles[i], 1000); // 1 kHz PWM frequency
        }

        fprintf(log_file, "Duty cycle %d at %s\n", duty, ctime(&time(NULL)));

        sleep(1); // Wait 1 second before incrementing duty cycle
    }

    fprintf(log_file, "Sunrise simulation complete at %s\n", ctime(&time(NULL)));
}

// Function to handle signals (SIGINT, SIGTERM)
void handle_signals(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        fprintf(log_file, "Received signal %d at %s, shutting down...\n", signum, ctime(&time(NULL)));
        cleanup();
        exit(EXIT_SUCCESS);
    }
}

// Function to cleanup resources
void cleanup() {
    for (int i = 0; i < 4; i++) {
        gpioFreePWM(pi, relay_pins[i]);
    }
    gpioClose(pi);
    pigpioClose(pi);
    fclose(log_file);
}

