#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>

// Define the I2C address and GPIO pins for the MPU-6050
#define I2C_ADDRESS 0x68
#define SDA_GPIO 2
#define SCL_GPIO 3
#define LED_GPIO 17

// Register addresses for MPU-6050 configuration
#define PWR_MGMT_1_REG 0x6B
#define SMPLRT_DIV_REG 0x19
#define GYRO_CONFIG_REG 0x1B
#define WHO_AM_I_REG 0x75
#define GYRO_XOUT_H_REG 0x43

// Full-scale range for gyroscope (131 LSB/deg/s)
#define GYRO_FULL_SCALE 131

// Circular buffer size
#define BUFFER_SIZE 100

// Structure to hold gyroscope data
typedef struct {
    int timestamp;
    int16_t x;
    int16_t y;
    int16_t z;
} GyroData;

// Function prototypes
void init_pigpio();
void init_i2c();
void configure_mpu();
void read_gyro_data();
void handle_gyro_data();
void cleanup();
void signal_handler(int signum);

int main() {
    // Initialize pigpio
    init_pigpio();

    // Signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Attempt to initialize I2C up to 3 times
    int i2c_init_attempts = 0;
    while (i2c_init_attempts < 3) {
        init_i2c();
        break;
    }

    if (i2c_init_attempts == 3) {
        fprintf(stderr, "Failed to initialize I2C after 3 attempts.\n");
        exit(EXIT_FAILURE);
    }

    // Configure the MPU-6050
    configure_mpu();

    // Main loop
    while (1) {
        read_gyro_data();
        handle_gyro_data();
    }

    // Clean up on exit
    cleanup();

    return 0;
}

// Function to initialize pigpio
void init_pigpio() {
    if (pigpioSetup(0) == -1) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        exit(EXIT_FAILURE);
    }
}

// Function to initialize I2C
void init_i2c() {
    if (pigpioI2CSetup(1, SDA_GPIO, SCL_GPIO) == -1) {
        fprintf(stderr, "Failed to initialize I2C.\n");
        exit(EXIT_FAILURE);
    }
}

// Function to configure the MPU-6050
void configure_mpu() {
    // Write to PWR_MGMT_1 to wake the sensor
    if (pigpioI2CWrite(1, I2C_ADDRESS, (uint8_t *) &PWR_MGMT_1_REG, 1, 0x00) == -1) {
        fprintf(stderr, "Failed to write to PWR_MGMT_1.\n");
        exit(EXIT_FAILURE);
    }

    // Write to SMPLRT_DIV for 1 kHz sample rate
    if (pigpioI2CWrite(1, I2C_ADDRESS, (uint8_t *) &SMPLRT_DIV_REG, 1, 0x07) == -1) {
        fprintf(stderr, "Failed to write to SMPLRT_DIV.\n");
        exit(EXIT_FAILURE);
    }

    // Write to GYRO_CONFIG for ±250 deg/s range
    if (pigpioI2CWrite(1, I2C_ADDRESS, (uint8_t *) &GYRO_CONFIG_REG, 1, 0x00) == -1) {
        fprintf(stderr, "Failed to write to GYRO_CONFIG.\n");
        exit(EXIT_FAILURE);
    }

    // Verify WHO_AM_I register
    if (pigpioI2CRead(1, I2C_ADDRESS, (uint8_t *) &WHO_AM_I_REG, 1) != 0x68) {
