        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Setup SPI
    spi_fd = spidev_open(SPI_DEVICE, SPI_MODE);
    if (spi_fd == -1) {
        fprintf(stderr, "Failed to open SPI device.\n");
        gpiod_set_data_direction(chip, GPIO8, GPIOD_DIR_IN);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Setup SPI parameters
    if (spidev_setup(SPI_FD, SPI_SPEED, SPI_BITS, SPI_PHASE) < 0) {
        fprintf(stderr, "Failed to set up SPI.\n");
        close(spi_fd);
        gpiod_set_data_direction(chip, GPIO8, GPIOD_DIR_IN);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
