                handle_errors(errno);
                retry_count++;
                continue;
            }

            // Read gyro data
            if (read(spi_fd, spi_transfer + 3, 6) != 6) {
                fprintf(stderr, "SPI read error.\n");
                handle_errors(errno);
                retry_count++;
                continue;
            }

            // Convert raw data to degrees per second
            read_gyro_data(spi_transfer + 3);
            convert_gyro_data(gyro_data, &x_rate, &y_rate, &z_rate);

