// Function to read raw gyro data from SPI
void read_gyro_data(uint8_t *data) {
    // Read 6 bytes (2 for command, 4 for data)
    // Assuming 16-bit two's complement for each axis
    uint16_t x_data = (data[0] << 8) | data[1];
    uint16_t y_data = (data[2] << 8) | data[3];
    uint16_t z_data = (data[4] << 8) | data[5];

    // Convert 16-bit two's complement to positive value
    x_data = (x_data & 0x0000FFFF) + ((x_data >> 16) & 0x00000001) * 0xFFFF;
    y_data = (y_data & 0x0000FFFF) + ((y_data >> 16) & 0x00000001) * 0xFFFF;
    z_data = (z_data & 0x0000FFFF) + ((z_data >> 16) & 0x00000001) * 0xFFFF;
}

// Function to convert raw gyro data to degrees per second
void convert_gyro_data(uint16_t *data, double *rates) {
    *rates = (*data / SCALE_FACTOR);
}

