void write_to_log_file(const char *timestamp, double x_rate, double y_rate, double z_rate) {
    char log_entry[256];
    snprintf(log_entry, sizeof(log_entry), "%s,%.9f,%.9f,%.9f\n",
             timestamp, x_rate, y_rate, z_rate);
    if (fwrite(log_entry, 1, sizeof(log_entry), fopen("gyro_log.txt", "a")) != sizeof(log_entry)) {
        fprintf(stderr, "Error writing to log file.\n");
    }
}

// Handle errors and retry if possible
void handle_errors(int error) {
    if (retry_count < MAX_RETRIES) {
        fprintf(stderr, "SPI communication error. Retrying...\n");
        retry_count++;
    } else {
        fprintf(stderr, "Persistent SPI communication error. Giving up.\n");
    }
}

