    // Close SPI device
    close(spi_fd);

    // Release GPIO line
    gpiod_set_data_direction(chip, GPIO8, GPIOD_DIR_IN);
    gpiod_chip_close(chip);

    // Ensure log file is closed
    fclose(stderr);
}

