void spi_setup();
void spi_transfer(uint8_t* data, size_t len);
void read_gyro_data(uint16_t* x, uint16_t* y, uint16_t* z);
void blink_led(int gpio);
void print_buffer();
void cleanup();

int main() {
    // Initialize GPIO and SPI
    if (gpiod_direction_output(CE_GPIO, 1) != 0 || spidev_open(0, 0) < 0) {
        fprintf(stderr, "Failed to initialize hardware.\n");
        return EXIT_FAILURE;
    }

    // Setup SPI
    spi_setup(SPI_SPEED, SPI_MODE);

    // Blink LED initialization
    blink_led(LED_GPIO);

    uint8_t tx_buf[3] = {0x00, 0x43, 0x00}; // Command to read X high byte
    uint8_t rx_buf[2];
    uint16_t x_high;

    while (1) {
        // Read gyroscope X high byte
        if (spi_transfer(tx_buf, 3) != 3) {
            fprintf(stderr, "SPI transfer failed.\n");
            break;
        }
        if (spi_transfer(rx_buf, 2) != 2) {
            fprintf(stderr, "SPI read failed.\n");
            break;
        }
        x_high = (rx_buf[0] << 8) | rx_buf[1];
        read_gyro_data(&x_high, NULL, NULL); // Only read X for simplicity

        // Check for exceeding thresholds
        if (abs(x_high) > 200) {
            blink_led(LED_GPIO);
        } else {
            blink_led(0); // Turn off LED
        }

        // Check for Ctrl+C
        if (signal(SIGINT) == SIG_IGN) {
            signal(SIGINT, SIG_TERM); // Catch Ctrl+C
        }
        if (wait(NULL) == -1 && errno == EINTR) continue;
        if (wait(NULL) != 0) {
            break; // Ctrl+C received
        }

        // Store data in buffer
        buffer[buffer_index++] = (uint32_t)(x_high * LSB_TO_DEGREES);
        if (buffer_index == BUFFER_SIZE) {
            buffer_index = 0; // Circular buffer
        }

        // Print buffer on Ctrl+C
        if (buffer_index > 0) {
            print_buffer();
        }
    }

    // Cleanup
    cleanup();

    return EXIT_SUCCESS;
}

// SPI setup function
void spi_setup(uint32_t speed, uint8_t mode) {
    struct spidev_fd *spi = spidev_open(0, 0);
    if (!spi) {
        fprintf(stderr, "Failed to open SPI device.\n");
        return;
    }

    if (ioctl(spi->fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed.\n");
        close(spi->fd);
        return;
    }

    if (ioctl(spi->fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode.\n");
        close(spi->fd);
        return;
    }
    close(spi->fd);
}

// SPI transfer function
void spi_transfer(uint8_t* data, size_t len) {
    struct spi_ioc_transfer tx[] = {
        SPI_IOC.Transfer(spidev_fd, data, len),
        SPI_IOC.Transfer(spidev_fd, NULL, 0),
    };

    if (ioctl(spidev_fd, SPI_IOC_MESSAGE(1), tx) < 0) {
        fprintf(stderr, "SPI transfer failed.\n");
    }
}

// Read gyroscope data function
void read_gyro_data(uint16_t* x, uint16_t* y, uint16_t* z) {
    uint8_t tx_buf[3] = {0x00, MPU6050_REG_X_H, 0x00}; // Read X high byte
    uint8_t rx_buf[2];

    spi_transfer(tx_buf, 3);
    if (spi_transfer(rx_buf, 2) != 2) {
        fprintf(stderr, "SPI read failed.\n");
        return;
    }

    *x = (rx_buf[0] << 8) | rx_buf[1];
    tx_buf[0] = 0x00; // Reset register address
    tx_buf[1] = MPU6050_REG_Y_H; // Read Y high byte
    spi_transfer(tx_buf, 2);
    if (spi_transfer(rx_buf, 2) != 2) {
        fprintf(stderr, "SPI read failed.\n");
        return;
    }
    *y = (rx_buf[0] << 8) | rx_buf[1];

    tx_buf[0] = 0x00;
    tx_buf[1] = MPU6050_REG_Z_H; // Read Z high byte
    spi_transfer(tx_buf, 2);
    if (spi_transfer(rx_buf, 2) != 2) {
        fprintf(stderr, "SPI read failed.\n");
        return;
    }
    *z = (rx_buf[0] << 8) | rx_buf[1];
}

// Blink LED function
void blink_led(int gpio) {
    while (1) {
        gpiod_write(gpio, 1); // Turn on LED
        usleep(500000); // Wait 500 ms
        gpiod_write(gpio, 0); // Turn off LED
        usleep(500000); // Wait 500 ms
    }
}

// Print buffer function
void print_buffer() {
    printf("Timestamp,X,Y,Z\n");
    for (size_t i = 0; i < buffer_index; i++) {
        printf("%lu,%d,%d,%d\n", (unsigned long)time(NULL), buffer[i] / LSB_TO_DEGREES, (buffer[i] >> 8) / LSB_TO_DEGREES, buffer[i] % LSB_TO_DEGREES);
    }
}

// Cleanup function
void cleanup() {
    // Release GPIO
    gpiod_set_value(CE_GPIO, 0);
    gpiod_cleanup();

    // Release SPI
    close(spidev_fd);
}

