#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>

// Define GPIO pin for LED
#define LED_PIN 21

// Define I2C bus and address for MPU-6050
#define I2C_BUS 1
#define MPU_ADDRESS 0x68

// Define registers for power management and accelerometer configuration
#define PWR_MGMT_1_REG 0x6B
#define ACCEL_CONFIG_REG 0x1C

// Define accelerometer data registers
#define ACC_X_REG 0x3B
#define ACC_Y_REG 0x3D
#define ACC_Z_REG 0x3F

// Function prototypes
void setup_pigpio();
void setup_i2c();
void read_accelerometer_data(uint8_t *data);
void compute_angles(uint16_t x, uint16_t y, uint16_t z, float *roll, float *pitch);
void handle_signal(int signum);
void cleanup();

int main() {
    // Initialize global variables
    FILE *tilt_log = NULL;
    pid_t pigpiod;
    int roll = 0, pitch = 0;
    uint8_t data[6];
    float timestamp;

    // Signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, handle_signal);

    // Setup pigpio
    setup_pigpio();

    // Setup I2C
    setup_i2c();

    // Main loop
    while (1) {
        // Read accelerometer data
        if (pigpio_i2c_read(I2C_BUS, MPU_ADDRESS, ACC_X_REG, data + 0, 1) != 1) {
            fprintf(stderr, "Error reading ACC_X\n");
            continue;
        }
        if (pigpio_i2c_read(I2C_BUS, MPU_ADDRESS, ACC_Y_REG, data + 1, 1) != 1) {
            fprintf(stderr, "Error reading ACC_Y\n");
            continue;
        }
        if (pigpio_i2c_read(I2C_BUS, MPU_ADDRESS, ACC_Z_REG, data + 2, 1) != 1) {
            fprintf(stderr, "Error reading ACC_Z\n");
            continue;
        }

        // Compute angles
        compute_angles(data[0], data[1], data[2], &roll, &pitch);

        // Check angles and control LED
        if (abs(roll) > 45 || abs(pitch) > 45) {
            pigpio_write(LED_PIN, 1); // Turn on LED
        } else {
            pigpio_write(LED_PIN, 0); // Turn off LED
        }

        // Log data to file
        timestamp = time(NULL);
        char timestamp_str[50];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&timestamp));
        fprintf(tilt_log, "%s,%f,%f\n", timestamp_str, roll, pitch);

        // Print roll and pitch to console
        printf("Roll: %.2f degrees\nPitch: %.2f degrees\n", roll * 180.0 / M_PI, pitch * 180.0 / M_PI);

        // Delay for 100 ms
        usleep(100000);
    }

    // Cleanup on SIGINT
    handle_signal(SIGINT);

    // Close I2C handle and cleanup
    pigpio_i2c_close();
    cleanup();

    return 0;
}

// Function to setup pigpio
void setup_pigpio() {
    pigpiod = pigpio_open();
    if (pigpiod == -1) {
        fprintf(stderr, "Failed to open pigpio\n");
        exit(EXIT_FAILURE);
    }
    pigpio_set_mode(pigpiod, PIGPIO_MODE_ON);
}

// Function to setup I2C
void setup_i2c() {
    int rc;
    rc = pigpio_i2c_init(I2C_BUS, 1000); // 1000 kHz clock
    if (rc != 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        exit(EXIT_FAILURE);
    }
}

// Function to read accelerometer data
void read_accelerometer_data(uint8_t *data) {
    uint8_t power_management = 0;
    pigpio_i2c_write(I2C_BUS, MPU_ADDRESS, PWR_MGMT_1_REG, &power_management, 1);
    if (power_management != 0x00) {
        fprintf(stderr, "Failed to wake sensor\n");
        return;
    }

    pigpio_i2c_write(I2C_BUS, MPU_ADDRESS, ACCEL_CONFIG_REG, &power_management, 1);
    if (power_management != 0x00) {
        fprintf(stderr, "Failed to set accelerometer range\n");
        return;
    }

    // Read accelerometer data
    pigpio_i2c_read(I2C_BUS, MPU_ADDRESS, ACC_X_REG, data, 1);
    pigpio_i2c_read(I2C_BUS, MPU_ADDRESS, ACC_Y_REG, data + 1, 1);
    pigpio_i2c_read(I2C_BUS, MPU_ADDRESS, ACC_Z_REG, data + 2, 1);
}

// Function to compute angles from accelerometer data
void compute_angles(uint16_t x, uint16_t y, uint16_t z, float *roll, float *pitch) {
    *roll = atan2f(y, z) * 180.0 / M_PI;
    *pitch = atan2f(-x, sqrtf(y * y + z * z)) * 180.0 / M_PI;
}

// Signal handler for SIGINT
void handle_signal(int signum) {
    // Turn off LED
    pigpio_write(LED_PIN, 0);

    // Close I2C handle
    pigpio_i2c_close();

    // Shutdown pigpio
    pigpio_close(pigpiod);
}

// Cleanup function
void cleanup() {
    fclose(tilt_log);
    pigpio_close(pigpiod);
}

