#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_DEVICE_PATH "/dev/i2c-1"
#define SENSOR_ADDRESS 0x5A
#define AMBIENT_LIGHT_REGISTER 0x20
#define PROXIMITY_REGISTER 0x22
#define MAX_RETRIES 3
#define DELAY_MS 10

#define GPIO_NUM 17

void i2c_write(uint8_t slave_addr, uint8_t reg, uint16_t data) {
    int fd = open(I2C_DEVICE_PATH, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    struct i2c_msg msg = {
        .addr = slave_addr,
        .flags = 0,
        .len = sizeof(uint16_t),
        .buf = (void *)data
    };

    for (int retry = 0; retry < MAX_RETRIES; ++retry) {
        if (ioctl(fd, I2C_SLAVE, slave_addr) < 0) {
            perror("Failed to change I2C slave address");
            close(fd);
            exit(EXIT_FAILURE);
        }

        if (write(fd, &msg, sizeof(msg)) != sizeof(msg)) {
            perror("Failed to write to I2C device");
