#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO constants
#define CE0_GPIO 8

// ADXRS290 SPI constants
#define SPI_CHANNEL 0
#define SPI_MODE 0
#define SPI_SPEED_MHZ 1
#define ADXRS290_READ_ADDRESS 0x80

// Sensitivity conversion factor
#define LSB_TO_DEGREES_PER_S 200

// GPIO setup and cleanup functions
void setup_spi_and_gpio(void);
void cleanup_spi_and_gpio(void);

// Function to read a single axis from the gyroscope
int16_t read_axis(int axis, pigpio *pgpio) {
    int16_t high_byte, low_byte;
    pigpio_spi_transfer(pgpio, SPI_CHANNEL, SPI_MODE, SPI_SPEED_MHZ, axis | ADXRS290_READ_ADDRESS, 0x00, &high_byte, &low_byte);
    return (high_byte << 8) | low_byte;
}

// Main function
int main(void) {
    // Signal handler for SIGINT (Ctrl+C)
    struct sigaction sa;
    sa.sa_handler = cleanup_spi_and_gpio;
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Initialize global pigpio instance
    pigpio *pgpio = NULL;
    if ((pgpio = gpioInitialise()) == NULL) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", gpioError(pgpio));
        return EXIT_FAILURE;
    }

    // Setup SPI and GPIO
    setup_spi_and_gpio();

    // Main loop
    while (1) {
        // Sample gyroscope
        int16_t x_rate, y_rate;
        struct timespec timestamp;

        // Get current time
        clock_gettime(CLOCK_MONOTONIC, &timestamp);

        // Read X and Y axis data
        x_rate = read_axis(0, pgpio);
        y_rate = read_axis(1, pgpio);

        // Convert LSB to degrees per second
        x_rate *= LSB_TO_DEGREES_PER_S;
        y_rate *= LSB_TO_DEGREES_PER_S;

        // Log data to file
        char filename[] = "gyro_data.csv";
        FILE *file = fopen(filename, "a+");
        if (file == NULL) {
            fprintf(stderr, "Failed to open file %s for writing: %s\n", filename, strerror(errno));
            break; // Exit on file open failure
        }

        // Format and write data
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S.%06lu", &timestamp);
        fprintf(file, "%s,%d,%d\n", timestamp_str, x_rate, y_rate);

        // Close file and flush data
        fclose(file);

        // Delay for 10 ms
        usleep(10000);

        // Check for SIGINT and clean up
        if (sigpending(&sa.sa_mask) && (sa.sa_flags & SA_SIGINFO) && SA_SIGINFO == sa.sa_flags) {
            // Handle SIGINT
            siglongjmp(sigjmp_buf(), 1);
        }
    }

    // Cleanup on SIGINT or normal exit
    cleanup_spi_and_gpio();

    // Free pigpio
    gpioFree(pgpio);

    return EXIT_SUCCESS;
}

// SPI and GPIO setup function
void setup_spi_and_gpio(void) {
    // Set CE0 as output for SPI chip select
    if (gpioMode(CE0_GPIO, GPIO_OUTPUT) == -1) {
        fprintf(stderr, "Failed to set CE0 as output: %s\n", gpioError());
        exit(EXIT_FAILURE);
    }

    // Open SPI channel 0
    if (spiOpen(SPI_CHANNEL, SPI_MODE, SPI_SPEED_MHZ) == -1) {
        fprintf(stderr, "Failed to open SPI channel: %s\n", spiError());
        exit(EXIT_FAILURE);
    }
}

// SPI and GPIO cleanup function
void cleanup_spi_and_gpio(void) {
    // Close SPI channel
    spiClose();

    // Set CE0 back to input (optional, depending on reuse)
    if (gpioMode(CE0_GPIO, GPIO_INPUT) != 0) {
        fprintf(stderr, "Failed to set CE0 back to input: %s\n", gpioError());
    }

    // Close pigpio
    gpioFree(NULL);
}

