// GPIO pins for tilt sensors and alert
#define GPIO_TILT1 23
#define GPIO_TILT2 24
#define GPIO_ALERT 17

// Duration in milliseconds for continuous HIGH detection
#define DETECTION_DURATION_MS 500

// Function to handle SIGINT and SIGTERM signals
void handleSignals(int signum) {
    if (pigpio_running()) {
        fprintf(stderr, "Stopping pigpio...\n");
        pigpio_stop();
    }
    fclose(logfile);
    gpio_write(GPIO_ALERT, 0); // Set alert pin LOW
    exit(0);
}

int main() {
    // Initialize pigpio
    if (pigpio_init() == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_errstr());
        return EXIT_FAILURE;
    }

    // Open log file for writing
    FILE *logfile = fopen("seismic_events.txt", "a+");
    if (!logfile) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        pigpio_stop();
        return EXIT_FAILURE;
    }

    // Set up GPIO pins
    if (gpio_mode(GPIO_TILT1, GPIO_INPUT) == -1 || gpio_mode(GPIO_TILT2, GPIO_INPUT) == -1) {
        fprintf(stderr, "Failed to set GPIO pins to input mode: %s\n", pigpio_errstr());
        fclose(logfile);
        pigpio_stop();
        return EXIT_FAILURE;
    }

    // Set up alert GPIO pin
    if (gpio_mode(GPIO_ALERT, GPIO_OUTPUT) == -1) {
        fprintf(stderr, "Failed to set GPIO pin to output mode: %s\n", pigpio_errstr());
        fclose(logfile);
        pigpio_stop();
        return EXIT_FAILURE;
    }

    // Register edge-triggered callbacks for both GPIO pins
    if (pigpio_callback_add_rising(GPIO_TILT1, callback_rising, NULL) == -1 ||
        pigpio_callback_add_falling(GPIO_TILT1, callback_falling, NULL) == -1 ||
        pigpio_callback_add_rising(GPIO_TILT2, callback_rising, NULL) == -1 ||
        pigpio_callback_add_falling(GPIO_TILT2, callback_falling, NULL) == -1) {
        fprintf(stderr, "Failed to add GPIO callbacks: %s\n", pigpio_errstr());
        fclose(logfile);
        pigpio_stop();
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Check for seismic event
        if (gpio_read(GPIO_TILT1) && gpio_read(GPIO_TILT2)) {
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            char timestamp[50];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S ", &ts);

            fprintf(logfile, "%s - Seismic event detected!\n", timestamp);
            // Set alert pin HIGH for 2 seconds
            gpio_write(GPIO_ALERT, 1);
            sleep(2000);
            gpio_write(GPIO_ALERT, 0);

            // Reset GPIO pins
            gpio_write(GPIO_TILT1, 0);
            gpio_write(GPIO_TILT2, 0);
        }
    }

    // Close log file and clean up
    fclose(logfile);

    // Register signal handlers
    signal(SIGINT, handleSignals);
    signal(SIGTERM, handleSignals);

    // Keep the program running indefinitely
    while (1) {
        // Sleep to conserve CPU
        sleep(1);
    }

    return EXIT_SUCCESS;
}

// Callback functions for GPIO edge triggers
void callback_rising(int pin, void *data) {
    gpio_read(pin); // Clear the edge trigger
}

void callback_falling(int pin, void *data) {
    gpio_read(pin); // Clear the edge trigger
}

