        fprintf(stderr, "Failed to initialize SPI\n");
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
int read_gyroscope_data() {
    uint16_t rate_xl, rate_xh;

    // Set MSB of address to 1 for read operation
    rate_xl_address = RATE_XL_ADDRESS | 0x80;
    rate_xh_address = RATE_XH_ADDRESS | 0x80;

    if (pigpio_spi_transfer(spi_bus, spi_channel, rate_xl_address, &rate_xl, 1) != 1) {
        fprintf(stderr, "Failed to read RATE_XL\n");
        return -1;
    }

    if (pigpio_spi_transfer(spi_bus, spi_channel, rate_xh_address, &rate_xh, 1) != 1) {
        fprintf(stderr, "Failed to read RATE_XH\n");
        return -1;
    }

    rate_xl = (rate_xl << 8) | rate_xh;
    angular_velocity = (rate_xl / 200.0); // Convert LSB to degrees per second

    return 0;
}

