        }
        reading_index = 0;
    }

    if (pi_gpio_init(GPIO17, GPIO_OUTPUT_LOW)) {
        fprintf(stderr, "Failed to reset GPIO17 to low on exit\n");
    }
}

int main() {
    // Initialize SPI and GPIO
    if (initialize_spi_and_gpio() != 0) {
        fprintf(stderr, "Initialization failed\n");
        return EXIT_FAILURE;
    }

    // Start the gyro reading thread
    gyro_thread_id = pthread_create(&pthread_info, NULL, &gyro_thread, NULL);
    if (gyro_thread_id == NULL) {
        fprintf(stderr, "Failed to create gyro thread\n");
        return EXIT_FAILURE;
    }

    // Wait for the thread to complete or receive a signal
    while (1) {
        if (pthread_join(gyro_thread_id, NULL) == 0) {
            break; // Thread completed normally
        }

        if (handle_signal(SIGINT) || handle_signal(SIGTERM)) {
            break; // Exit due to signal
        }
    }

    // Clean up resources
    cleanup_resources();

    return EXIT_SUCCESS;
}

