#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Function prototypes
void setup_pigpio();
void handle_signal(int signum);
void fade_lamp(int gpio, int duration);
void cleanup();

int main(int argc, char *argv[]) {
    // Check if the argument is provided and valid
    if (argc != 2 || atoi(argv[1]) < 1 || atoi(argv[1]) > 3600) {
        fprintf(stderr, "Usage: %s <fade_duration_in_seconds>\n", argv[0]);
        return EXIT_FAILURE;
    }

    // Initialize pigpio
    setup_pigpio();

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Start fading lamps
    fade_lamp(17, atoi(argv[1]));
    fade_lamp(18, atoi(argv[1]));
    fade_lamp(27, atoi(argv[1]));

    // Wait for all fades to complete before exiting
    while (pigpio_in_use()) {}

    // Clean up
    cleanup();

    return EXIT_SUCCESS;
}

// Function to initialize pigpio
void setup_pigpio() {
    if (pigpio_init() == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_errstr());
        return;
    }

    printf("Raspberry Pi Sunset Simulator v1.0\n");
    printf("Starting fade sequence with duration: %d seconds\n", atoi(argv[1]));
}

// Function to handle SIGINT and SIGTERM
void handle_signal(int signum) {
    printf("Received signal %d, shutting down...\n", signum);
    fade_lamp(17, 0); // Immediately turn off all lamps
    cleanup();
    pigpio_free(); // Release pigpio resources
    exit(0);
}

// Function to fade a lamp
void fade_lamp(int gpio, int duration) {
    int step = duration / 255; // Step size for each PWM adjustment
    int current_duty = 255; // Start at full brightness

    printf("Starting fade for lamp on GPIO %d with duration %d seconds\n", gpio, duration);

    while (current_duty > 0) {
        pigpio_set_PWM(gpio, current_duty, 100); // Set PWM duty cycle

        sleep(step); // Wait for a short period

        current_duty -= step; // Decrease duty cycle
    }

    printf("Lamp on GPIO %d fade complete\n", gpio);
}

// Function to clean up resources
void cleanup() {
    pigpio_free(); // Release pigpio resources
    printf("Cleanup complete\n");
}

