#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

#define RED_GPIO 17
#define YELLOW_GPIO 22
#define GREEN_GPIO 23
#define YELLOW2_GPIO 24

#define RED_PIN 0
#define YELLOW_PIN 1
#define GREEN_PIN 2
#define YELLOW2_PIN 3

volatile sig_atomic_t should_exit = 0;

void handle_signal(int signum) {
    should_exit = 1;
}

int main() {
    // Initialize libgpiod
    if (gpiod_chip_open(&gpiod_ch, "bcm2835") < 0) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    if (gpiod_line_request(gpiod_ch, RED_GPIO, GPIOD_OUT_LOW) < 0 ||
        gpiod_line_request(gpiod_ch, YELLOW_GPIO, GPIOD_OUT_LOW) < 0 ||
        gpiod_line_request(gpiod_ch, GREEN_GPIO, GPIOD_OUT_LOW) < 0 ||
        gpiod_line_request(gpiod_ch, YELLOW2_GPIO, GPIOD_OUT_LOW) < 0) {
        perror("gpiod_line_request");
        gpiod_chip_close(&gpiod_ch);
        return EXIT_FAILURE;
    }

    // Set initial state
    gpiod_set_value(gpiod_ch, RED_GPIO, GPIOD_OUTPUT_LOW);
    gpiod_set_value(gpiod_ch, YELLOW_GPIO, GPIOD_OUTPUT_LOW);
    gpiod_set_value(gpiod_ch, GREEN_GPIO, GPIOD_OUTPUT_LOW);
    gpiod_set_value(gpiod_ch, YELLOW2_GPIO, GPIOD_OUTPUT_LOW);

    while (!should_exit) {
        // Red light
        gpiod_set_value(gpiod_ch, RED_GPIO, GPIOD_OUTPUT_LOW);
        printf("Red light on for 10 seconds...\n");
        usleep(10000000);

        // Red + Yellow transition
        gpiod_set_value(gpiod_ch, YELLOW_GPIO, GPIOD_OUTPUT_LOW);
        gpiod_set_value(gpiod_ch, GREEN_GPIO, GPIOD_OUTPUT_LOW);
        gpiod_set_value(gpiod_ch, YELLOW2_GPIO, GPIOD_OUTPUT_LOW);
        printf("Red and Yellow transition for 2 seconds...\n");
        usleep(2000000);

        // Green light
        gpiod_set_value(gpiod_ch, RED_GPIO, GPIOD_OUTPUT_HIGH);
        gpiod_set_value(gpiod_ch, YELLOW_GPIO, GPIOD_OUTPUT_LOW);
        gpiod_set_value(gpiod_ch, GREEN_GPIO, GPIOD_OUTPUT_LOW);
        gpiod_set_value(gpiod_ch, YELLOW2_GPIO, GPIOD_OUTPUT_LOW);
        printf("Green light on for 10 seconds...\n");
        usleep(10000000);

        // Yellow light
        gpiod_set_value(gpiod_ch, RED_GPIO, GPIOD_OUTPUT_LOW);
        gpiod_set_value(gpiod_ch, YELLOW_GPIO, GPIOD_OUTPUT_LOW);
        gpiod_set_value(gpiod_ch, GREEN_GPIO, GPIOD_OUTPUT_LOW);
        gpiod_set_value(gpiod_ch, YELLOW2_GPIO, GPIOD_OUTPUT_LOW);
        printf("Yellow light on for 3 seconds...\n");
        usleep(3000000);

        // Wait for a bit before next cycle
        usleep(1000000);
    }

    // Release GPIO lines on exit
    for (int i = 0; i < 4; ++i) {
        gpiod_line_release(gpiod_ch, i);
    }

    gpiod_chip_close(&gpiod_ch);

    return EXIT_SUCCESS;
}

