uint8_t touch_threshold = 0x0A;
uint8_t release_threshold = 0x08;
uint8_t debounce = 0x21;
uint8_t charge_time = 0x0D;

// Touch status registers
uint8_t touch_status_lsb;
uint8_t touch_status_msb;

// Touch relay state
int relay_state = LOW;

// Signal handlers
void signal_handler(int signum) {
    switch (signum) {
        case SIGINT:
        case SIGTERM:
            cleanup();
            break;
    }
}

int main() {
    // Initialize logging
    char log_filename[] = "touch_relay.log";
    if ((log_file = fopen(log_filename, "a")) == NULL) {
        fprintf(stderr, "Error: Unable to open log file %s\n", log_filename);
        exit(EXIT_FAILURE);
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    setup_pigpio();

    // Initialize I2C
    setup_i2c();

    // Main loop
    while (1) {
        // Check for touch event
        handle_touch_event();

        // Sleep for 10 ms
        usleep(10000);

        // Debounce touch event with 100 ms delay
        if (time(NULL) + 100000 > time(NULL)) {
            continue;
        }
    }

    // Clean up on exit
    cleanup();

    return 0;
}

// Function to setup pigpio
void setup_pigpio() {
    if (pi == NULL) {
        fprintf(log_file, "Error: Unable to initialize pigpio.\n");
        exit(EXIT_FAILURE);
    }

    // Set GPIO17 as output, default LOW
    if (pigpio_direction(pi, GPIO17, pigpioOUTPUT) == -1) {
        fprintf(log_file, "Error: Unable to set GPIO17 as output.\n");
        exit(EXIT_FAILURE);
    }

    // Set GPIO17 to LOW initially
    if (pigpio_write(pi, GPIO17, LOW) == -1) {
        fprintf(log_file, "Error: Unable to set GPIO17 to LOW.\n");
        exit(EXIT_FAILURE);
    }
}

// Function to setup I2C
void setup_i2c() {
    if (wiringPiI2CSetup(1) == -1) {
        fprintf(log_file, "Error: Unable to setup I2C bus 1.\n");
        exit(EXIT_FAILURE);
    }

    if (wiringPiI2CWrite(1, MPR121_ADDRESS, 0x80, 0x63) == -1) {
        fprintf(log_file, "Error: Unable to write reset command to MPR121.\n");
        exit(EXIT_FAILURE);
    }

    if (wiringPiI2CWrite(1, MPR121_ADDRESS, 0x5E, 0x00) == -1) {
        fprintf(log_file, "Error: Unable to write stop mode command to MPR121.\n");
        exit(EXIT_FAILURE);
    }

    if (wiringPiI2CWrite(1, MPR121_ADDRESS, 0x5D, 0x01) == -1) {
        fprintf(log_file, "Error: Unable to enable electrode 0 on MPR121.\n");
        exit(EXIT_FAILURE);
    }

    if (wiringPiI2CWrite(1, MPR121_ADDRESS, 0x41, touch_threshold) == -1) {
        fprintf(log_file, "Error: Unable to write touch threshold to MPR121.\n");
        exit(EXIT_FAILURE);
    }

    if (wiringPiI2CWrite(1, MPR121_ADDRESS, 0x42, release_threshold) == -1) {
        fprintf(log_file, "Error: Unable to write release threshold to MPR121.\n");
        exit(EXIT_FAILURE);
    }

    if (wiringPiI2CWrite(1, MPR121_ADDRESS, 0x5B, debounce) == -1) {
        fprintf(log_file, "Error: Unable to write debounce value to MPR121.\n");
        exit(EXIT_FAILURE);
    }

    if (wiringPiI2CWrite(1, MPR121_ADDRESS, 0x5C, charge_time) == -1) {
        fprintf(log_file, "Error: Unable to write charge time to MPR121.\n");
        exit(EXIT_FAILURE);
    }

    if (wiringPiI2CWrite(1, MPR121_ADDRESS, 0x5E, run_mode) == -1) {
        fprintf(log_file, "Error: Unable to write run mode command to MPR121.\n");
        exit(EXIT_FAILURE);
    }

    // Read touch status from registers 0x00 and 0x01
    if (wiringPiI2CRead(1, MPR121_ADDRESS, 0x00, &touch_status_lsb) == -1 ||
        wiringPiI2CRead(1, MPR121_ADDRESS, 0x01, &touch_status_msb) == -1) {
        fprintf(log_file, "Error: Unable to read touch status from MPR121.\n");
        exit(EXIT_FAILURE);
    }
}

// Function to handle touch event
void handle_touch_event() {
    uint8_t touch_detected = (touch_status_lsb & 0x01) != 0;

    if (touch_detected) {
        if (relay_state == LOW) {
            // Toggle relay state
            relay_state = HIGH;
            if (pigpio_write(pi, GPIO17, HIGH) == -1) {
                fprintf(log_file, "Error: Unable to set GPIO17 to HIGH.\n");
                exit(EXIT_FAILURE);
            }
        } else {
            // Toggle relay state back to LOW
            relay_state = LOW;
            if (pigpio_write(pi, GPIO17, LOW) == -1) {
                fprintf(log_file, "Error: Unable to set GPIO17 to LOW.\n");
                exit(EXIT_FAILURE);
            }
        }
    }

    // Log touch event
    fprintf(log_file, "Touch detected: %s\n", touch_detected ? "ON" : "OFF");
}

// Function to cleanup resources
void cleanup() {
    // Close I2C handle
    if (i2c != NULL) {
        wiringPiI2CStop(1);
        wiringPiI2CRelease(i2c);
        i2c = NULL;
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    // Close pigpio handle
    if (pi != NULL) {
        pigpio_close(pi);
        pi = NULL;
    }
}

