#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <gpiod.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>

#define BUZZER_GPIO 18
#define LED_GPIO 23
#define FLAME_SENSOR_GPIO 17
#define FLAME_LOG_FILE "/home/pi/flame_log.txt"

volatile int flame_detected = 0;
int debounce_count = 0;

void setup_gpios(void) {
    int error;

    // Initialize GPIO controller
    gpiod_init();

    // Open GPIO pins
    int buzzer_fd = open("/dev/gpiochip0", O_RDWR);
    int led_fd = open("/dev/gpiochip0", O_RDWR);
    int flame_sensor_fd = open("/dev/gpiochip0", O_RDWR);

    if (buzzer_fd == -1 || led_fd == -1 || flame_sensor_fd == -1) {
        fprintf(stderr, "Error opening GPIO controller: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Set buzzer and LED GPIOs to output
    error = gpiod_direction_output(buzzer_fd, BUZZER_GPIO, 1);
    if (error != 0) {
        fprintf(stderr, "Error setting buzzer GPIO as output: %s\n", gpiod_get_name(error));
        close(buzzer_fd);
        close(led_fd);
        close(flame_sensor_fd);
        exit(EXIT_FAILURE);
    }

    error = gpiod_direction_output(led_fd, LED_GPIO, 1);
    if (error != 0) {
        fprintf(stderr, "Error setting LED GPIO as output: %s\n", gpiod_get_name(error));
        close(buzzer_fd);
        close(led_fd);
        close(flame_sensor_fd);
        exit(EXIT_FAILURE);
    }

    // Set flame sensor GPIO to input
    error = gpiod_direction_input(flame_sensor_fd, FLAME_SENSOR_GPIO);
    if (error != 0) {
        fprintf(stderr, "Error setting flame sensor GPIO as input: %s\n", gpiod_get_name(error));
        close(buzzer_fd);
        close(led_fd);
        close(flame_sensor_fd);
        exit(EXIT_FAILURE);
    }

    // Set debounce counter and initial state
    debounce_count = 0;
    flame_detected = 0;
}

void handle_flame_detection() {
    if (debounce_count >= 3) {
        flame_detected = 1;
        printf("Flame Detected at %s\n", ctime(&time(NULL)));
        fprintf(FLAME_LOG_FILE, "Flame Detected at %s\n", ctime(&time(NULL)));
    }

    debounce_count = 0;
}

void cleanup_resources(void) {
    close(flame_sensor_fd);
    close(led_fd);
    close(buzzer_fd);
    gpiod_cleanup();
}

void signal_handler(int signum) {
    // Graceful cleanup on SIGINT/SIGTERM
    printf("Received signal %d, cleaning up...\n", signum);
    cleanup_resources();
    exit(EXIT_SUCCESS);
}

int main(void) {
    struct sigaction sa;
    setup_gpios();

    // Set up signal handler
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting signal handler: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    while (1) {
        // Debounce flame sensor reading
        if (gpiod_read(flame_sensor_fd, FLAME_SENSOR_GPIO, &debounce_count) < 0) {
            fprintf(stderr, "Error reading flame sensor: %s\n", gpiod_get_name(errno));
            continue;
        }

        handle_flame_detection();

        // Sleep for 50 ms
        usleep(50000);
    }

    return 0;
}

