    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to install SIGINT handler.\n");
        return 1;
    }

    // Main loop
    while (1) {
        dispense_cycle();
        usleep(5000000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup_and_exit(0);

    return 0;
}

// Function to initialize pigpio and configure GPIO pins
int init_pigpio_and_gpio() {
    // Initialize pigpio
    if (pi == NULL) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    // Configure GPIO pins as outputs
    if (gpio_mode_pi(17, GPIO_OUTPUT_PP) == -1) {
        fprintf(stderr, "Failed to set GPIO 17 as output.\n");
        return 1;
    }
    if (gpio_mode_pi(27, GPIO_OUTPUT_PP) == -1) {
        fprintf(stderr, "Failed to set GPIO 27 as output.\n");
        return 1;
    }

    return 0;
}

// Function to perform a dispense cycle
int dispense_cycle() {
    // Prepare dispense log message
    sprintf(dispense_log_message, "Dispense at %s: GPIO17: %dms, GPIO27: %dms", ctime(&time(NULL)), 500, 500);

    // Open dispense log file, handle errors
    if ((dispense_log = fopen("dispense_log.txt", "a")) == NULL) {
        fprintf(stderr, "Failed to open dispense log file.\n");
        return 1;
    }

    // Activate solenoid 1 for half the cycle
    gpio_write(pi, 17, 1);
    usleep(500000); // 500 milliseconds

    // Deactivate solenoid 1 and activate solenoid 2 for the remaining half
    gpio_write(pi, 17, 0);
    usleep(500000); // 500 microseconds delay
    gpio_write(pi, 27, 1);

    // Deactivate both solenoids
    gpio_write(pi, 27, 0);
    gpio_write(pi, 17, 0);

    // Close dispense log file
    fclose(dispense_log);

    // Write log message to file
    if (fwrite(dispense_log_message, sizeof dispense_log_message, 1, dispense_log) == 0) {
        fprintf(stderr, "Failed to write to dispense log file.\n");
        return 1;
    }

    return 0;
}

