int cleanup_and_exit(int signum) {
    // Deactivate solenoids
    gpio_write(pi, 17, 0);
    gpio_write(pi, 27, 0);

    // Shutdown pigpio
    pigpio_cleanup(pi);

    // Close dispense log file
    fclose(dispense_log);

    // Exit
    exit(0);
}

