// Function prototypes
void setup_pigpio();
void handle_touch();
void debounce();
void cleanup();

// Global variables
pigpio *pi;
volatile sig_atomic_t should_exit = 0;

// GPIO pins
#define RELAY_GPIO 17
#define TOUCH_SENSOR_GPIO 4

// Main function
int main() {
    // Initialize pigpio
    setup_pigpio();

    // Install signal handler for Ctrl+C
    signal(SIGINT, SIG_IGN);
    signal(SIGTERM, SIG_IGN);

    while (!should_exit) {
        // Check for touch
        handle_touch();

        // Debounce touch
        debounce();

        // Toggle relay based on touch status
        if (touched) {
            toggle_relay();
        }
    }

    // Clean up resources
    cleanup();

    return 0;
}

// Function to initialize pigpio
void setup_pigpio() {
    pi = pigpioOpen();

    if (pi == NULL) {
        fprintf(stderr, "Failed to open pigpio: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }

    pigpioSetMode(pi, PIGPIO_MODE_LOWPOWER);
    pigpioSetOverTemp(pi, 80); // Set over-temperature shutdown threshold

    // Configure GPIO4 (TOUCH_SENSOR_GPIO) with internal pull-down
    if (pigpioWriteReg(pi, GPIO_BASE + GPIO_PUD, GPIO_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set GPIO4 pull-down: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }

    // Configure GPIO17 (RELAY_GPIO) as output
    if (pigpioSetMode(pi, RELAY_GPIO, PIGPIO_MODE_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO17 mode: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }
}

// Function to handle touch detection
void handle_touch() {
    int touched = 0;

    // Read GPIO4 (TOUCH_SENSOR_GPIO)
    if (pigpioRead(pi, TOUCH_SENSOR_GPIO) == 1) {
        touched = 1;
    }

    // Debounce logic is handled in debounce() function
}

// Function to debounce touch input
void debounce() {
    static time_t last_touch = time(NULL);
    static int debounce_count = 0;

    if (time(NULL) - last_touch >= 50) { // Debounce delay
        debounce_count = 0;
        last_touch = time(NULL);
    }

    if (pigpioRead(pi, TOUCH_SENSOR_GPIO) == 1) {
        debounce_count++;
        if (debounce_count > 5) { // Debounce threshold
            touched = 1;
            debounce_count = 0;
        }
    }
}

