#define RGB_GPIO 17
#define GREEN_GPIO 18
#define BLUE_GPIO 27

#define SAMPLE_RATE 8000
#define SAMPLE_SIZE 2
#define CHANNELS 1
#define BUFFER_SIZE (1024 * CHANNELS * SAMPLE_SIZE)

#define SENSITIVITY_DEFAULT 1.0
#define SENSITIVITY_MIN 0.1
#define SINE_WAVE_FREQ 440

// Non-linear transition function for RMS to PWM
double map_rms_to_pwm(double rms) {
    double normalized_rms = (rms / SENSITIVITY_DEFAULT) * 255.0;
    return normalized_rms < 128.0 ? normalized_rms : 255.0 - normalized_rms;
}

// Function to compute RMS amplitude from samples
double compute_rms(short *samples, int count) {
    double sum = 0.0;
    for (int i = 0; i < count; i++) {
        sum += samples[i] * samples[i];
    }
    return sqrt(sum / count);
}

// ALSA audio capture setup and tear-down
int alsa_device = -1;
snd_pcm_t *alsa_handle = NULL;

void alsa_init() {
    alsa_device = snd_pcm_open_alloca(&alsa_handle, "default", SND_PCM_STREAM_CAPTURE, 0);
    if (alsa_device < 0) {
        fprintf(stderr, "Failed to open ALSA device: %s\n", snd_strerror(alsa_device));
        exit(EXIT_FAILURE);
    }
