// Define the I2C address and register offsets for TCS34725
#define TCS34725_ADDRESS 0x29
#define CLEAR_LOW_BYTE_REG 0x14
#define CLEAR_HIGH_BYTE_REG 0x15
#define RED_LOW_BYTE_REG 0x16
#define RED_HIGH_BYTE_REG 0x17
#define GREEN_LOW_BYTE_REG 0x18
#define GREEN_HIGH_BYTE_REG 0x19
#define BLUE_LOW_BYTE_REG 0x1A
#define BLUE_HIGH_BYTE_REG 0x1B

// Integration time value in hex for 154 ms
#define INTEGRATION_TIME 0xD5

// Function prototypes
void initialize_sensor(pigpio *pi);
void read_sensor_values(pigpio *pi);
void handle_interrupts(int signum);
void cleanup_resources(pigpio *pi);

int main() {
    // Initialize global variables
    FILE *color_data_file = NULL;
    pigpio *pi = NULL;
    int clear_value = 0, red_value = 0, green_value = 0, blue_value = 0;

    // Register signal handlers
    signal(SIGINT, handle_interrupts);
    signal(SIGTERM, handle_interrupts);

    // Attempt to open the I2C bus and initialize the sensor
    if ((pi = pigpio_open()) == NULL) {
        fprintf(stderr, "Failed to open GPIO: %s\n", pigpio_error());
        return EXIT_FAILURE;
    }

    // Initialize the sensor
    initialize_sensor(pi);

    // Main loop until interrupted
    while (1) {
        // Read sensor values
        read_sensor_values(pi);

        // Write data to CSV file
        if (color_data_file == NULL) {
            color_data_file = fopen("color_data.csv", "a+");
            if (color_data_file == NULL) {
                fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
                break;
            }
        }
        fprintf(color_data_file, "%lld,%d,%d,%d,%d\n",
                (long long)time(NULL), clear_value, red_value, green_value, blue_value);
        fflush(color_data_file);

        // Delay for 500 ms
        usleep(500000);
    }

    // Cleanup resources on exit
    cleanup_resources(pi);

    return EXIT_SUCCESS;
}

// Function to initialize the sensor
void initialize_sensor(pigpio *pi) {
    // Set I2C bus and address
    int i2c_bus = 1;
    int i2c_dev = pigpio_i2c_open(pi, i2c_bus, TCS34725_ADDRESS);

    if (i2c_dev == -1) {
        fprintf(stderr, "Failed to open I2C device: %s\n", pigpio_error());
        return;
    }

    // Power on and set RGBC enable
    uint8_t power_on = 0x01;
    uint8_t rgbc_enable = 0x03;
    pigpio_i2c_write(i2c_dev, power_on);
    pigpio_i2c_write(i2c_dev, rgbc_enable);

    // Set integration time
    pigpio_i2c_write(i2c_dev, INTEGRATION_TIME);

    // Release I2C device
    pigpio_i2c_close(i2c_dev);
}

// Function to read sensor values
void read_sensor_values(pigpio *pi) {
    // Open I2C device again
    int i2c_dev = pigpio_i2c_open(pi, 1, TCS34725_ADDRESS);

    if (i2c_dev == -1) {
        fprintf(stderr, "Failed to open I2C device: %s\n", pigpio_error());
        return;
    }

    // Write to clear registers
    uint8_t clear_low = 0x00;
    uint8_t clear_high = 0x00;
    pigpio_i2c_write(i2c_dev, CLEAR_LOW_BYTE_REG, clear_low);
    pigpio_i2c_write(i2c_dev, CLEAR_HIGH_BYTE_REG, clear_high);

    // Read clear values
    clear_value = (pigpio_i2c_read(i2c_dev, CLEAR_LOW_BYTE_REG) << 8) | pigpio_i2c_read(i2c_dev, CLEAR_HIGH_BYTE_REG);

    // Write to red registers
    uint8_t red_low = 0x00;
    uint8_t red_high = 0x00;
    pigpio_i2c_write(i2c_dev, RED_LOW_BYTE_REG, red_low);
    pigpio_i2c_write(i2c_dev, RED_HIGH_BYTE_REG, red_high);

    // Read red values
    red_value = (pigpio_i2c_read(i2c_dev, RED_LOW_BYTE_REG) << 8) | pigpio_i2c_read(i2c_dev, RED_HIGH_BYTE_REG);

    // Write to green registers
    uint8_t green_low = 0x00;
    uint8_t green_high = 0x00;
    pigpio_i2c_write(i2c_dev, GREEN_LOW_BYTE_REG, green_low);
    pigpio_i2c_write(i2c_dev, GREEN_HIGH_BYTE_REG, green_high);

    // Read green values
    green_value = (pigpio_i2c_read(i2c_dev, GREEN_LOW_BYTE_REG) << 8) | pigpio_i2c_read(i2c_dev, GREEN_HIGH_BYTE_REG);

    // Write to blue registers
    uint8_t blue_low = 0x00;
    uint8_t blue_high = 0x00;
    pigpio_i2c_write(i2c_dev, BLUE_LOW_BYTE_REG, blue_low);
    pigpio_i2c_write(i2c_dev, BLUE_HIGH_BYTE_REG, blue_high);

    // Read blue values
    blue_value = (pigpio_i2c_read(i2c_dev, BLUE_LOW_BYTE_REG) << 8) | pigpio_i2c_read(i2c_dev, BLUE_HIGH_BYTE_REG);

    // Close I2C device
    pigpio_i2c_close(i2c_dev);
}

// Signal handler for SIGINT and SIGTERM
void handle_interrupts(int signum) {
    // Close the I2C handle and the CSV file
    if (pi != NULL) {
        pigpio_close(pi);
        pi = NULL;
    }
    if (color_data_file != NULL) {
        fclose(color_data_file);
        color_data_file = NULL;
    }
    // Exit the program
    exit(0);
}

