void setup_gpios(void) {
    gpiod_chip *chip;
    int i;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Error: Failed to open GPIO chip '%s'.\n", CHIP_NAME);
        exit(EXIT_FAILURE);
    }

    // Request output for each relay pin
    for (i = 0; i < TOTAL_RELAYS; i++) {
        gpiod_line *line = gpiod_line_get(chip, RELAY_PINS[i]);
        if (gpiod_line_request_output(line) < 0) {
            fprintf(stderr, "Error: Failed to configure GPIO line %d as output.\n", RELAY_PINS[i]);
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
        gpiod_line_release(line);
    }

    gpiod_chip_close(chip);
}

void simulate_sunrise_sunset(int phase, int duration_ms) {
    int i;
    int period = 1000; // 1 Hz PWM simulation

    for (i = 0; i < duration_ms / period; i++) {
        // Gradually increase duty cycle during sunrise
        if (phase == 0) {
            int duty_cycle = i * 100 / (duration_ms / period);
            duty_cycle = (duty_cycle * 100) / 255; // Normalize to 0-255 range
            gpiod_line_set_value(chip->lines[RELAY_PINS[0]], duty_cycle);
        }
        // Full brightness during daytime
        else if (phase == 1) {
            gpiod_line_set_value(chip->lines[RELAY_PINS[0]], 255);
        }
        // Gradually decrease duty cycle during sunset
        else if (phase == 2) {
            int duty_cycle = (255 - i * 100 / (duration_ms / period));
            duty_cycle = duty_cycle / 255; // Normalize to 0-1 range
            gpiod_line_set_value(chip->lines[RELAY_PINS[0]], duty_cycle);
        }
        // Off during nighttime
        else {
            gpiod_line_set_value(chip->lines[RELAY_PINS[0]], 0);
        }

        usleep(period); // Wait for 1ms
    }
}

void daytime_phase() {
    simulate_sunrise_sunset(1, 3600000); // 6 hours in ms
}

void sunset_phase() {
    simulate_sunrise_sunset(2, 3600000); // 1 hour in ms
}

void nighttime_phase() {
    // No need to simulate anything, just keep off
}

void handle_signal(int signum) {
    // Turn off all relays and release GPIO resources on SIGINT or SIGTERM
    for (int i = 0; i < TOTAL_RELAYS; i++) {
        gpiod_line *line = gpiod_line_get(chip->lines, RELAY_PINS[i]);
        if (line) {
            gpiod_line_set_value(line, 0);
            gpiod_line_release(line);
        }
    }

    gpiod_chip_close(chip);
    printf("GPIO resources released on signal.\n");
}

int main(void) {
    setup_gpios();

    // Main loop
    while (1) {
        // Daytime phase
        daytime_phase();

        // Sunset phase
        sunset_phase();

        // Nighttime phase
        nighttime_phase();

        // Sleep for 1 hour (3600000 ms) to simulate nighttime
        sleep(3600000);
    }

    // Handle signals
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    return 0;
}

