        exit(EXIT_FAILURE);
    }
    pi = pigpio_open();
    if (pi == NULL) {
        fprintf(stderr, "Failed to open pigpio: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }
}

void setup_gpio() {
    if (pigpio_set_mode(GPIO_PIN, pigpioOUTPUT) == -1) {
        fprintf(stderr, "Failed to set GPIO mode: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }
    if (pigpio_write(GPIO_PIN, 0) == -1) {
        fprintf(stderr, "Failed to write to GPIO: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }
}

void debounced_motion_detected() {
    struct timespec timestamp;
    time(&timestamp);

    char filename[100];
    strftime(filename, sizeof(filename), "%Y%m%d_%H%M%S", &timestamp);

    FILE *video_log = fopen("/home/pi/videos/%s.h264", "w+");
    if (video_log == NULL) {
        fprintf(stderr, "Failed to open video log file: %s\n", strerror(errno));
