#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <stdint.h>

// Constants
#define PIGPIO_ADDR 0
#define MPU6050_ADDRESS 0x68
#define REINIT_ATTEMPTS 3
#define SAMPLE_RATE_DIVIDER 125
#define FULL_SCALE_GYRO 250.0
#define LSB_PER_DEGREE_PER_S 131.0
#define GYRO_REGISTERS {0x43, 0x44, 0x45, 0x46, 0x47, 0x48}

// Function prototypes
void gyro_init(void);
int gyro_read(void);
void handle_signal(int signum);
void log_data(double x_degps, double y_degps, double z_degps, double timestamp);

int main(void) {
    // Signal handler for SIGINT and SIGTERM
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // I2C handle
    int i2c_handle = i2cOpen(PIGPIO_ADDR, PIGPIO_I2C_MODE);

    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Attempt to initialize the gyroscope
    int reinit_count = 0;
    while (reinit_count < REINIT_ATTEMPTS) {
        gyro_init();
        if (gyro_read() >= 0) {
            break;
        }
        reinit_count++;
    }

    if (reinit_count == REINIT_ATTEMPTS) {
        fprintf(stderr, "Failed to initialize gyroscope after %d attempts.\n", REINIT_ATTEMPTS);
    }

    // Main loop
    while (1) {
        // Get current time
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        double timestamp = (double)ts.tv_sec * 1000 + ts.tv_nsec / 1000000.0;

        // Read gyroscope data
        int result = gyro_read();
        if (result < 0) {
            fprintf(stderr, "Failed to read gyroscope data: %s\n", strerror(errno));
            continue;
        }

        // Convert raw values to degrees per second
        double x_degps = (result[0] * LSB_PER_DEGREE_PER_S) / FULL_SCALE_GYRO;
        double y_degps = (result[1] * LSB_PER_DEGREE_PER_S) / FULL_SCALE_GYRO;
        double z_degps = (result[2] * LSB_PER_DEGREE_PER_S) / FULL_SCALE_GYRO;

        // Log data
        log_data(x_degps, y_degps, z_degps, timestamp);

        // Sleep for 10 ms
        usleep(10000);
    }

    // Clean up on SIGINT/SIGTERM
    handle_signal(SIGINT);
    handle_signal(SIGTERM);

    // Close I2C handle
    i2cClose(i2c_handle);

    // Release resources
    gpioTerminate();

    return EXIT_SUCCESS;
}

// Function to initialize the gyroscope
void gyro_init(void) {
    // Write to wake the sensor
    uint8_t wake_cmd = 0x00;
    i2cWriteByteData(i2c_handle, MPU6050_ADDRESS, 0x6B, &wake_cmd, 1);

    // Set sample rate divider
    uint8_t sample_rate_cmd = (SAMPLE_RATE_DIVIDER / 32) & 0x07;
    i2cWriteByteData(i2c_handle, MPU6050_ADDRESS, 0x19, &sample_rate_cmd, 1);

    // Set full-scale range
    uint8_t full_scale_cmd = 0x00;
    i2cWriteByteData(i2c_handle, MPU6050_ADDRESS, 0x1B, &full_scale_cmd, 1);
}

// Function to read gyroscope data
int gyro_read(void) {
    // Write to start measurement
    uint8_t start_cmd = 0x01;
    i2cWriteByteData(i2c_handle, MPU6050_ADDRESS, 0x6B, &start_cmd, 1);

    // Wait for measurement to complete
    usleep(5 * 1000); // 5 ms

    // Read gyroscope data
    uint8_t cmd = 0x3B; // Read 6 bytes from registers 0x43-0x48
    uint8_t data[6];
    i2cReadI2CBlockData(i2c_handle, MPU6050_ADDRESS, cmd, data, 6);

    // Convert raw data to degrees per second
    double x_degps = (data[0] * LSB_PER_DEGREE_PER_S) / FULL_SCALE_GYRO;
    double y_degps = (data[1] * LSB_PER_DEGREE_PER_S) / FULL_SCALE_GYRO;
    double z_degps = (data[2] * LSB_PER_DEGREE_PER_S) / FULL_SCALE_GYRO;

    return 0; // Success
}

// Function to handle SIGINT and SIGTERM
void handle_signal(int signum) {
    // Close the log file
    fclose(stderr);

    // Release the I2C handle
    i2cClose(i2c_handle);

    // Exit the program
    exit(EXIT_FAILURE);
}

// Function to log data
void log_data(double x_degps, double y_degps, double z_degps, double timestamp) {
    // Format data for CSV
    char csv_line[256];
    sprintf(csv_line, "%f,%f,%f,%f\n", timestamp, x_degps, y_degps, z_degps);

    // Append to gyro_log.csv
    FILE *log_file = fopen("gyro_log.csv", "a+");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open gyro_log.csv for appending: %s\n", strerror(errno));
        return;
    }

    // Write to file
    fwrite(csv_line, sizeof(char), strlen(csv_line), log_file);

    // Close file
    fclose(log_file);
}

