    // Install signal handler for SIGINT
    signal(SIGINT, handle_signal);

    // Attempt to initialize pigpio
    if (pi == NULL) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }

    // Attempt to open irrigation log file
    if ((irrigation_log = fopen("irrigation_log.txt", "a+")) == NULL) {
        fprintf(stderr, "Failed to open irrigation log file.\n");
        cleanup_pigpio();
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Simulate moisture sensor readings
        srand(time(NULL));
        moisture_levels[0] = rand() % 101;
        moisture_levels[1] = rand() % 101;
        moisture_levels[2] = rand() % 101;
        moisture_levels[3] = rand() % 101;

        // Irrigate zones based on moisture levels
        irrigate_zone(0, moisture_levels[0]);
        irrigate_zone(1, moisture_levels[1]);
        irrigate_zone(2, moisture_levels[2]);
        irrigate_zone(3, moisture_levels[3]);

