        append_log("Moisture: 0:%d, 1:%d, 2:%d, 3:%d\n",
                   moisture_levels[0], moisture_levels[1], moisture_levels[2], moisture_levels[3],
                   time(NULL));

        // Sleep for 5 seconds
        sleep(5);
    }

    // Cleanup on exit
    cleanup_pigpio();

    return EXIT_SUCCESS;
}

// Function to irrigate a zone based on moisture level
void irrigate_zone(int zone, int moisture_level) {
    int relay_state;

    // Check if moisture level is below 30 to activate the relay
    if (moisture_level < 30) {
        // Drive the relay LOW (active-low)
        relay_state = 0;
    } else {
        // Drive the relay HIGH (inactive)
        relay_state = 1;
    }

    // Check GPIO pin initialization and set the relay state
    if (pi == NULL || zone_relays[zone] == -1) {
        fprintf(stderr, "GPIO pin %d not initialized or invalid.\n", zone_relays[zone]);
        return;
    }

    if (pigpio_write(pi, zone_relays[zone], relay_state) == -1) {
        fprintf(stderr, "Error writing to GPIO pin %d.\n", zone_relays[zone]);
    }
}

// Function to append a message with timestamp to the irrigation log file
void append_log(char *message, time_t timestamp) {
    time_t now = time(NULL);
    struct tm timeinfo;
    char log_entry[256];

    // Format the timestamp
    localtime_r(&now, &timeinfo);
    strftime(log_entry, sizeof(log_entry), "%Y-%m-%d %H:%M:%S", &timeinfo);

    // Append the message to the log file
    if (fputs(log_entry "\t" message, irrigation_log) == NULL) {
        fprintf(stderr, "Error writing to irrigation log file.\n");
    }
}

// Function to setup pigpio
void setup_pigpio() {
    if (pigpio_init() == -1) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO pins for relay modules
    for (int i = 0; i < 4; i++) {
        if (pigpio_direction(pi, zone_relays[i], pigpio OUTPUT) == -1) {
            fprintf(stderr, "Failed to set GPIO pin %d to output.\n", zone_relays[i]);
            exit(EXIT_FAILURE);
        }
    }
}

// Function to cleanup pigpio and resources
void cleanup_pigpio() {
    // Deactivate all relays by driving them HIGH
    for (int i = 0; i < 4; i++) {
        if (pigpio_write(pi, zone_relays[i], 1) == -1) {
            fprintf(stderr, "Error deactivating GPIO pin %d.\n", zone_relays[i]);
        }
    }

    // Close the irrigation log file
    if (irrigation_log != NULL) {
        fclose(irrigation_log);
        irrigation_log = NULL;
    }

    // Shutdown pigpio
    pigpio_cleanup(pi);
    pi = NULL;
}

// Signal handler for SIGINT
void handle_signal(int signum) {
    // Deactivate all relays and cleanup
    cleanup_pigpio();
    exit(EXIT_FAILURE);
}

