#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>

// Constants
#define PIGPIO_ID 0  // Assuming pigpio is the default device
#define I2C_ADDR 0x53
#define DATA_FORMAT_REG 0x31
#define POWER_CTL_REG 0x2D
#define DATAX0_REG 0x32
#define FREEFALL_THRESHOLD 0.2
#define FREEFALL_DURATION_MS 500
#define ALARM_GPIO 27
#define CSV_HEADER "Timestamp, X, Y, Z"

// Function prototypes
void setup_pigpio();
void setup_i2c();
void read_accelerometer_data(uint16_t *data);
void handle_freefall(uint16_t *data, int count);
void freefall_alarm();
void cleanup();
void sigint_handler(int signum);

int main() {
    // Initialize global variables
    pidpi *pi = NULL;
    int i2c_fd = -1;
    uint16_t accelerometer_data[3];
    int freefall_detected = 0;
    struct sigaction sa;

    // SIGINT handler setup
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    // Main program loop
    setup_pigpio();
    setup_i2c();
    while (1) {
        // Read accelerometer data
        read_accelerometer_data(accelerometer_data);

        // Check for freefall
        handle_freefall(accelerometer_data, 0);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    cleanup();

    return 0;
}

// SIGINT handler
void sigint_handler(int signum) {
    printf("SIGINT received, closing I2C and setting GPIO low.\n");
    close(i2c_fd);
    gpio_write(GPIO_ID_B, GPIO_PIN_LOW);
    exit(0);
}

// Function to setup pigpio
void setup_pigpio() {
    pi = pigpio_open(PIGPIO_ID, 0);
    if (pi == NULL) {
        fprintf(stderr, "Failed to open pigpio\n");
        exit(1);
    }
}

// Function to setup I2C
void setup_i2c() {
    i2c_fd = i2c_open(I2C_ADDR, 0);
    if (i2c_fd == -1) {
        fprintf(stderr, "Failed to open I2C device at address 0x53\n");
        return;
    }

    // Write to DATA_FORMAT register
    uint8_t data_format = 0x0B;
    if (i2c_write(i2c_fd, I2C_ADDR, DATA_FORMAT_REG, &data_format, 1) != 1) {
        fprintf(stderr, "Failed to write to DATA_FORMAT register\n");
    }

    // Write to POWER_CTL register
    if (i2c_write(i2c_fd, I2C_ADDR, POWER_CTL_REG, &0x08, 1) != 1) {
        fprintf(stderr, "Failed to write to POWER_CTL register\n");
    }
}

// Function to read accelerometer data
void read_accelerometer_data(uint16_t *data) {
    int count = 3;
    for (int i = 0; i < count; i++) {
        data[i] = i2c_read(i2c_fd, I2C_ADDR, DATAX0_REG + i * 2, 2);
        if (data[i] == 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            return;
        }
    }
}

// Function to handle freefall detection
void handle_freefall(uint16_t *data, int count) {
    for (int i = 0; i < count; i++) {
        if (abs(data[i]) < FREEFALL_THRESHOLD) {
            freefall_detected = 1;
            if (freefall_detected && !freefall_in_progress) {
                freefall_in_progress = 1;
                time_t now = time(NULL);
                char timestamp[50];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &now);
                FILE *file = fopen("freefall.log", "a");
                if (file) {
                    fprintf(file, "%s, %03.3f, %03.3f, %03.3f\n", timestamp,
                            (double)data[0] / 256.0, (double)data[1] / 256.0, (double)data[2] / 256.0);
                    fclose(file);
                }
                freefall_alarm();
                freefall_in_progress = 0;
            }
        }
    }
}

// Function to simulate alarm for freefall
void freefall_alarm() {
    gpio_write(GPIO_ID_B, GPIO_PIN_HIGH);
    sleep(5000);
    gpio_write(GPIO_ID_B, GPIO_PIN_LOW);
}

// Function to cleanup resources
void cleanup() {
    if (pi != NULL) {
        pigpio_close(pi);
        pi = NULL;
    }
    if (i2c_fd != -1) {
        i2c_close(i2c_fd);
        i2c_fd = -1;
    }
}

