#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>

// Define GPIO and I2C constants
#define PI_GPIO_Buzzer 17
#define PI_I2C_BUS 1
#define LIS3DH_ADDRESS 0x18
#define LIS3DH_REG_OUT_X_L 0x28

// Define thresholds for freefall and impact detection
#define FREEFALL_THRESHOLD 0.2
#define IMPACT_THRESHOLD 1.5

// Function prototypes
void initialize_pigpio();
void initialize_i2c();
void configure_lis3dh();
void read_acceleration_data(uint16_t *data);
void detect_freefall(uint16_t *data);
void detect_impact(uint16_t *data);
void activate_buzzer();
void cleanup();

// Signal handler for SIGINT
void signal_handler(int signum) {
    printf("Received SIGINT, cleaning up...\n");
    cleanup();
    exit(0);
}

int main(int argc, char **argv) {
    // Initialize pigpio
    initialize_pigpio();

    // Check if user provided thresholds
    if (argc > 1) {
        if (strcmp(argv[1], "--freefall-threshold") == 0) {
            FREEFALL_THRESHOLD = atof(argv[2]);
        } else if (strcmp(argv[1], "--impact-threshold") == 0) {
            IMPACT_THRESHOLD = atof(argv[3]);
        } else {
            fprintf(stderr, "Usage: %s [freefall-threshold] [impact-threshold]\n", argv[0]);
            return EXIT_FAILURE;
        }
    }

    // Initialize I2C
    initialize_i2c();

    // Configure LIS3DH
    configure_lis3dh();

    // Main loop
    uint16_t acceleration_data[1];
    while (1) {
        read_acceleration_data(acceleration_data);

        if (detect_freefall(acceleration_data)) {
            printf("Freefall detected\n");
            activate_buzzer();
        } else if (detect_impact(acceleration_data)) {
            printf("Impact detected\n");
            activate_buzzer();
        }
    }

    // Clean up on SIGINT
    signal(SIGINT, signal_handler);

    return EXIT_SUCCESS;
}

// Function to initialize pigpio
void initialize_pigpio() {
    if (pigpio_init() == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error());
        return;
    }
}

// Function to initialize I2C
void initialize_i2c() {
    if (pigpio_i2c_open(PI_I2C_BUS) == -1) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", pigpio_error());
        return;
    }
}

// Function to configure LIS3DH
void configure_lis3dh() {
    uint8_t ctrl_reg1 = 0x77; // Set to 100 Hz and ±2g full scale
    uint8_t ctrl_reg4 = 0x00;

    if (pigpio_i2c_write(PI_I2C_BUS, LIS3DH_ADDRESS, ctrl_reg1, 1) == -1) {
        fprintf(stderr, "Failed to write to CTRL_REG1: %s\n", pigpio_error());
        return;
    }

    if (pigpio_i2c_write(PI_I2C_BUS, LIS3DH_ADDRESS, ctrl_reg4, 1) == -1) {
        fprintf(stderr, "Failed to write to CTRL_REG4: %s\n", pigpio_error());
        return;
    }
}

// Function to read acceleration data
void read_acceleration_data(uint16_t *data) {
    if (pigpio_i2c_read(PI_I2C_BUS, LIS3DH_ADDRESS, LIS3DH_REG_OUT_X_L, 1, data, 1) == -1) {
        fprintf(stderr, "Failed to read OUT_X_L: %s\n", pigpio_error());
        return;
    }
}

// Function to detect freefall
void detect_freefall(uint16_t *data) {
    float acceleration = (float)data[0] / 16384.0; // Convert to g

    if (acceleration < FREEFALL_THRESHOLD) {
        printf("Detected freefall\n");
    }
}

// Function to detect impact
void detect_impact(uint16_t *data) {
    float acceleration = (float)data[0] / 16384.0; // Convert to g

    if (acceleration > IMPACT_THRESHOLD) {
        printf("Detected impact\n");
    }
}

// Function to activate buzzer
void activate_buzzer() {
    if (pigpio_write(PI_GPIO_Buzzer, 1) == -1) {
        fprintf(stderr, "Failed to activate buzzer: %s\n", pigpio_error());
        return;
    }
    sleep(1); // Activate for 1 second
    pigpio_write(PI_GPIO_Buzzer, 0);
}

// Function to cleanup resources
void cleanup() {
    pigpio_i2c_close(PI_I2C_BUS);
    pigpio_close();
}

