#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the stepper motors
#define GPIO_X1 4
#define GPIO_X2 17
#define GPIO_X3 27
#define GPIO_X4 22
#define GPIO_Y1 5
#define GPIO_Y2 6
#define GPIO_Y3 13
#define GPIO_Y4 19

// Step delay in microseconds
#define STEP_DELAY 1000

// Conversion factor from steps to mm
#define STEPS_PER_MM 10

// Motor control constants
#define STEPS_PER_REVOLUTION 2048
#define COILS_PER_REVOLUTION 4

// Function prototypes
void setup_pigpio();
void set_motor_direction(int motor, int direction);
void step_motor(int motor, int steps);
void draw_square(int steps_per_side);
void cleanup();

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signum) {
    printf("Interrupt received, stopping motors...\n");
    cleanup();
    exit(0);
}

int main() {
    // Initialize pigpio
    setup_pigpio();

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Set GPIO pins as outputs
    if (gpioWrite(GPIO_X1, 1) != 1 || gpioWrite(GPIO_X2, 1) != 1 ||
        gpioWrite(GPIO_X3, 1) != 1 || gpioWrite(GPIO_X4, 1) != 1 ||
        gpioWrite(GPIO_Y1, 1) != 1 || gpioWrite(GPIO_Y2, 1) != 1 ||
        gpioWrite(GPIO_Y3, 1) != 1 || gpioWrite(GPIO_Y4, 1) != 1) {
        fprintf(stderr, "Failed to set GPIO pins as outputs\n");
        return EXIT_FAILURE;
    }

    // Set motor directions
    set_motor_direction(0, 1); // Clockwise for X-axis
    set_motor_direction(1, -1); // Counter-clockwise for Y-axis

    // Draw the square
    draw_square(STEPS_PER_SIDE);

    // Cleanup
    cleanup();

    return EXIT_SUCCESS;
}

// Function to initialize pigpio
void setup_pigpio() {
    if (pigpioSetup(0) == -1) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return;
    }
}

// Function to set motor direction
void set_motor_direction(int motor, int direction) {
    int pin_sequence[] = {GPIO_X1, GPIO_X2, GPIO_X3, GPIO_X4};
    int inverted_sequence[] = {GPIO_Y1, GPIO_Y2, GPIO_Y3, GPIO_Y4};

    if (direction) {
        // Clockwise sequence
        gpioWrite(pin_sequence[0], 1);
        gpioWrite(pin_sequence[1], 0);
        gpioWrite(pin_sequence[2], 1);
        gpioWrite(pin_sequence[3], 0);
    } else {
        // Counter-clockwise sequence
        gpioWrite(pin_sequence[0], 0);
        gpioWrite(pin_sequence[1], 1);
        gpioWrite(pin_sequence[2], 0);
        gpioWrite(pin_sequence[3], 1);
    }

    // Invert for Y-axis
    if (motor == 1) {
        for (int i = 0; i < 4; i++) {
            gpioWrite(inverted_sequence[i], !gpioRead(inverted_sequence[i]));
        }
    }
}

// Function to step the motor
void step_motor(int motor, int steps) {
    int delay = STEPS_PER_REVOLUTION / steps * STEP_DELAY;

    for (int i = 0; i < steps; i++) {
        // Apply 4-step wave drive sequence
        int coil_sequence[] = {0, 1, 2, 3};
        for (int j = 0; j < COILS_PER_REVOLUTION; j++) {
            gpioWrite(coil_sequence[j % 4], 1);
            usleep(delay);
            gpioWrite(coil_sequence[j % 4], 0);
            usleep(delay);
        }
    }
}

// Function to draw a square
void draw_square(int steps_per_side) {
    int total_steps = steps_per_side * 4; // 4 sides of the square

    for (int i = 0; i < total_steps; i += 100) {
        step_motor(0, i / 100); // X-axis
        step_motor(1, i % 100); // Y-axis
    }
}

// Function to cleanup and release resources
void cleanup() {
    // Stop both motors
    step_motor(0, 0);
    step_motor(1, 0);

    // Set all GPIO pins low
    for (int i = GPIO_X1; i <= GPIO_Y4; i++) {
        gpioWrite(i, 0);
    }

    // Shutdown pigpio
    pigpioShutdown();
}

