#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <pigpio.h>
#include <stdint.h>

#define LIS3DH_ADDR_DEFAULT 0x18
#define LIS3DH_ADDR_MIN 0x08
#define LIS3DH_ADDR_MAX 0x77
#define THRESHOLD_DEFAULT 2.0

// Function prototypes
void handleSIGINT(int signum);
int checkAddressRange(const char *address);
int checkThreshold(float threshold);
void shutdownSystemNow();

// Main function
int main(int argc, char **argv) {
    // Command line arguments
    float threshold = THRESHOLD_DEFAULT;
    char addressStr[5];

    // Parse command line arguments
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <LIS3DH address> <threshold in g>\n", argv[0]);
        return 1;
    }

    // Extract address and threshold from arguments
    if (sscanf(argv[1], "%4s", addressStr) != 1 || sscanf(argv[2], "%f", &threshold) != 1) {
        fprintf(stderr, "Invalid arguments.\n");
        return 1;
    }

    // Validate address range
    if (checkAddressRange(addressStr)) {
        fprintf(stderr, "Invalid I2C address: %s\n", addressStr);
        return 1;
    }

    // Validate threshold
    if (checkThreshold(threshold)) {
        fprintf(stderr, "Invalid threshold: must be greater than 0\n");
        return 1;
    }

    // Initialize pigpio
    pigpio *pi = NULL;
    if (pigpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    // Open I2C
    int i2c_fd = -1;
    if (i2cOpen(&i2c_fd, LIS3DH_ADDR_DEFAULT) < 0) {
        fprintf(stderr, "Failed to open I2C.\n");
        pigpio_cleanup(pi);
        return 1;
    }

    // Configure LIS3DH
    uint8_t configReg1 = 0x57; // High resolution, 12-bit left justified, ±2g range
    uint8_t configReg4 = 0x88; // 100 Hz output data rate

    if (i2cWriteByteData(i2c_fd, LIS3DH_ADDR_DEFAULT, configReg1) != 1 || i2cWriteByteData(i2c_fd, LIS3DH_ADDR_DEFAULT, configReg4) != 1) {
        fprintf(stderr, "Failed to configure LIS3DH.\n");
        i2cClose(i2c_fd);
        pigpio_cleanup(pi);
        return 1;
    }

    // SIGINT handler
    signal(SIGINT, handleSIGINT);

    // Main loop
    while (1) {
        // Read acceleration data
        uint16_t rawAccel[3];
        if (i2cReadI2CBlockData(i2c_fd, LIS3DH_ADDR_DEFAULT, 0x0D, 3, rawAccel, 3) < 3) {
            // Handle read error by returning zeros
            for (int i = 0; i < 3; i++) {
                rawAccel[i] = 0;
            }
        }

        // Compute g values
        float gValues[3];
        for (int i = 0; i < 3; i++) {
            gValues[i] = (float)rawAccel[i] >> 4 * 0.0009765625;
        }

        // Check for high acceleration
        if (gValues[0] > threshold || gValues[1] > threshold || gValues[2] > threshold) {
            // Log high acceleration event
            char logMessage[256];
            sprintf(logMessage, "High acceleration detected on %d axis at %f g at %s", i, gValues[i], ctime(&time(NULL)));
            FILE *logFile = fopen("/var/log/high_acceleration.log", "a");
            if (logFile) {
                fprintf(logFile, "%s\n", logMessage);
                fclose(logFile);
            }

            // Shutdown the system
            shutdownSystemNow();
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    i2cClose(i2c_fd);
    pigpio_cleanup(pi);

    return 0;
}

// SIGINT handler
void handleSIGINT(int signum) {
    fprintf(stderr, "SIGINT received, closing I2C and terminating pigpio.\n");
    i2cClose(-1);
    pigpio_cleanup(NULL);
    exit(0); // Graceful exit
}

// Check if address is within valid range
int checkAddressRange(const char *address) {
    if (sscanf(address, "%hhu", &addressValue) != 1 || addressValue < LIS3DH_ADDR_MIN || addressValue > LIS3DH_ADDR_MAX) {
        return 0;
    }
    return 1;
}

// Check if threshold is valid (greater than 0)
int checkThreshold(float threshold) {
    if (threshold <= 0) {
        return 0;
    }
    return 1;
}

// Function to immediately shutdown the system
void shutdownSystemNow() {
    // Use system() to execute the shutdown command
    system("sudo shutdown -h now");
}

