#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <libgpiod/gpiod.h>
#include <stdbool.h>
#include <unistd.h>
#include <sys/time.h>

#define BUFFER_SIZE 5
#define ALERT_GPIO 22
#define LEFT_PIN 4
#define CENTER_PIN 17
#define RIGHT_PIN 27

volatile bool alert_triggered = false;
volatile bool running = true;

struct sensor_reading {
    int left;
    int center;
    int right;
};

struct sensor_readings buffer[BUFFER_SIZE];

void initialize_libgpiod() {
    if (gpiod_open() < 0) {
        perror("gpiod_open");
        exit(EXIT_FAILURE);
    }

    if (gpiod_request_line(GPIO4) < 0 || gpiod_request_line(GPIO17) < 0 || gpiod_request_line(GPIO27) < 0 || gpiod_request_line(ALERT_GPIO) < 0) {
        perror("gpiod_request_line");
        gpiod_close();
        exit(EXIT_FAILURE);
    }
}

void cleanup_libgpiod() {
    for (int i = 0; i < BUFFER_SIZE; i++) {
        free(buffer[i].left);
        free(buffer[i].center);
        free(buffer[i].right);
    }

    gpiod_unrequest_line(GPIO4);
    gpiod_unrequest_line(GPIO17);
    gpiod_unrequest_line(GPIO27);
    gpiod_unrequest_line(ALERT_GPIO);
    gpiod_close();
}

void read_sensors() {
    struct sensor_reading readings;
    readings.left = gpiod_get_value_input_raw(GPIO4);
    readings.center = gpiod_get_value_input_raw(GPIO17);
    readings.right = gpiod_get_value_input_raw(GPIO27);

    buffer[buffer_index++] = readings;
    if (buffer_index == BUFFER_SIZE) {
        buffer_index = 0;
    }
}

void handle_alert() {
    if (alert_triggered) {
        sleep(2);
        alert_triggered = false;
    }
}

void line_following_logic() {
    bool move_forward = false;
    bool turn_left = false;
    bool turn_right = false;

    for (int i = 0; i < BUFFER_SIZE; i++) {
        struct sensor_reading reading = buffer[i];

        if (reading.center == 0) {
            move_forward = true;
        } else if (reading.left == 0) {
            turn_left = true;
        } else if (reading.right == 0) {
            turn_right = true;
        }

        if (move_forward && reading.center != 0 && turn_left && reading.left != 0 && turn_right && reading.right != 0) {
            // All conditions met, stop the robot
            move_forward = false;
            turn_left = false;
            turn_right = false;
        }
    }

    // Update motor control functions here with actual logic
    // Example: move_forward_control(), turn_left_control(), turn_right_control()
}

void signal_handler(int signum) {
    running = false;
    handle_alert();
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    initialize_libgpiod();

    struct timeval start_time, elapsed_time;
    gettimeofday(&start_time, NULL);

    while (running) {
        read_sensors();
        line_following_logic();

        // Check for alert condition
        if (buffer_index == BUFFER_SIZE && !alert_triggered) {
            for (int i = 0; i < BUFFER_SIZE; i++) {
                if (buffer[i].center == 1) {
                    alert_triggered = true;
                    break;
                }
            }
        }

        gettimeofday(&elapsed_time, NULL);
        if (elapsed_time.tv_sec - start_time.tv_sec > 2) {
            running = false; // Stop after 2 seconds of execution
        }

        usleep(10000); // Poll every 10 ms
    }

    cleanup_libgpiod();

    return 0;
}

