#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>

#define PI_GPIO 17
#define SENSOR_ADDR 0x30
#define THRESHOLD 5.0
#define SAMPLE_INTERVAL_MS 100
#define MAX_POLL_ATTEMPTS 50

// Function prototypes
void handleSIGINT(int signum);
int i2cReadSensor(struct pigpio *gp);
int relayControl(struct pigpio *gp, int state);
void logEvent(const char *msg, double field_mT);
void cleanup(struct pigpio *gp);

// Global variables
struct pigpio *gp;
uint8_t i2cResult;
int relayState = 0;
double field_mT = 0.0;
int pollCount = 0;

// Main function
int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Open I2C bus 1
    if (i2cOpen(1) < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioFree(gpio);
        return EXIT_FAILURE;
    }

    // Install SIGINT handler
    signal(SIGINT, handleSIGINT);

    // Main loop
    while (1) {
        // Start measurement
        i2cWriteByteData(1, SENSOR_ADDR, 0xC1, 0x01);
        pollCount = 0;
        while (i2cReadByte(1, SENSOR_ADDR, 0xC1) != 0x00 && pollCount < MAX_POLL_ATTEMPTS) {
            pollCount++;
            usleep(1000); // Wait 1 ms between polls
        }

        // Check if conversion completed
        if (i2cReadByte(1, SENSOR_ADDR, 0xC1) == 0x00) {
            // Read field strength data
            i2cReadByteData(1, SENSOR_ADDR, 0xC0, 2);
            uint16_t field_raw = (i2cReadByteData(1, SENSOR_ADDR, 0xC0, 1) << 8) | i2cReadByteData(1, SENSOR_ADDR, 0xC0, 0);

            // Convert to milliTesla
            double field_mT = field_raw * 25.0 / 1000.0;

            // Check threshold
            if (field_mT > THRESHOLD * 100) {
                // Activate relay if field strength exceeds threshold
                relayState = relayControl(gp, 1);

                // Log event
                logEvent("Field strength exceeded threshold: %f mT", field_mT);

                // Update field strength
                field_mT = 0.0;
            } else {
                // Log normal reading
                logEvent("Field strength: %f mT", field_mT);
            }

            // Handle timeout error
            if (pollCount == MAX_POLL_ATTEMPTS) {
                logEvent("Timeout error: Conversion not completed after %d attempts", MAX_POLL_ATTEMPTS);
                break;
            }
        } else {
            // Log error if conversion not started
            logEvent("Error: Conversion not started after %d attempts", MAX_POLL_ATTEMPTS);
            break;
        }

        // Log relay state change
        logEvent("Relay state: %d", relayState ? "ON" : "OFF");

        // Close I2C handle and cleanup
        cleanup(gp);

        // Sleep for the next sample interval
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    // Shutdown
    printf("Shutting down...\n");
    return EXIT_SUCCESS;
}

// SIGINT handler
void handleSIGINT(int signum) {
    fprintf(stderr, "SIGINT received, shutting down...\n");
    cleanup(gp);
    pigpioTerminate(gp);
    exit(EXIT_SUCCESS);
}

// Function to read from the sensor
int i2cReadSensor(struct pigpio *gp) {
    uint8_t result;
    i2cWriteByteData(1, SENSOR_ADDR, 0xC1, 0x01);
    do {
        usleep(100); // Small delay between reads
        result = i2cReadByte(1, SENSOR_ADDR, 0xC1);
    } while (result != 0x00);
    return result;
}

// Function to control the relay
int relayControl(struct pigpio *gp, int state) {
    int ret = gpioModeSet(GPIO_PIN, GPIO_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO %d mode: %s\n", PI_GPIO, strerror(errno));
        return -1;
    }

    if (state) {
        ret = gpioWriteSet(GPIO_PIN);
    } else {
        ret = gpioWriteClear(GPIO_PIN);
    }

    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO %d state: %s\n", PI_GPIO, strerror(errno));
        gpioModeSet(GPIO_PIN, GPIO_INPUT);
        return -1;
    }

    return 0;
}

// Cleanup function
void cleanup(struct pigpio *gp) {
    i2cClose(1);
    gpioFree(gp);
    pigpioTerminate(gp);
}

// Function to log an event with timestamp
void logEvent(const char *msg, double field_mT) {
    char buffer[256];
    time_t now = time(NULL);
    struct tm tm_now;
    localtime_r(&now, &tm_now);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", &tm_now);

    FILE *file = fopen("magnetic_events.txt", "a");
    if (file) {
        fprintf(file, "%s: Field strength: %.2f mT, Relay: %s\n", buffer, field_mT, relayState ? "ON" : "OFF");
        fclose(file);
    } else {
        fprintf(stderr, "Failed to open magnetic_events.txt for writing: %s\n", strerror(errno));
    }
}

