    if (i2cOpen(1) < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioFree(gpio);
        return EXIT_FAILURE;
    }

    // Install SIGINT handler
    signal(SIGINT, handleSIGINT);

    // Main loop
    while (1) {
        // Start measurement
        i2cWriteByteData(1, SENSOR_ADDR, 0xC1, 0x01);
        pollCount = 0;
        while (i2cReadByte(1, SENSOR_ADDR, 0xC1) != 0x00 && pollCount < MAX_POLL_ATTEMPTS) {
            pollCount++;
            usleep(1000); // Wait 1 ms between polls
        }

        // Check if conversion completed
        if (i2cReadByte(1, SENSOR_ADDR, 0xC1) == 0x00) {
            // Read field strength data
            i2cReadByteData(1, SENSOR_ADDR, 0xC0, 2);
            uint16_t field_raw = (i2cReadByteData(1, SENSOR_ADDR, 0xC0, 1) << 8) | i2cReadByteData(1, SENSOR_ADDR, 0xC0, 0);

            // Convert to milliTesla
            double field_mT = field_raw * 25.0 / 1000.0;

            // Check threshold
            if (field_mT > THRESHOLD * 100) {
                // Activate relay if field strength exceeds threshold
                relayState = relayControl(gp, 1);

                // Log event
                logEvent("Field strength exceeded threshold: %f mT", field_mT);

                // Update field strength
                field_mT = 0.0;
            } else {
                // Log normal reading
                logEvent("Field strength: %f mT", field_mT);
            }

            // Handle timeout error
            if (pollCount == MAX_POLL_ATTEMPTS) {
                logEvent("Timeout error: Conversion not completed after %d attempts", MAX_POLL_ATTEMPTS);
                break;
            }
        } else {
            // Log error if conversion not started
            logEvent("Error: Conversion not started after %d attempts", MAX_POLL_ATTEMPTS);
            break;
        }

        // Log relay state change
        logEvent("Relay state: %d", relayState ? "ON" : "OFF");

        // Close I2C handle and cleanup
        cleanup(gp);

        // Sleep for the next sample interval
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    // Shutdown
    printf("Shutting down...\n");
    return EXIT_SUCCESS;
}

// SIGINT handler
void handleSIGINT(int signum) {
    fprintf(stderr, "SIGINT received, shutting down...\n");
    cleanup(gp);
    pigpioTerminate(gp);
    exit(EXIT_SUCCESS);
}

