int i2cReadSensor(struct pigpio *gp) {
    uint8_t result;
    i2cWriteByteData(1, SENSOR_ADDR, 0xC1, 0x01);
    do {
        usleep(100); // Small delay between reads
        result = i2cReadByte(1, SENSOR_ADDR, 0xC1);
    } while (result != 0x00);
    return result;
}

// Function to control the relay
int relayControl(struct pigpio *gp, int state) {
    int ret = gpioModeSet(GPIO_PIN, GPIO_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO %d mode: %s\n", PI_GPIO, strerror(errno));
        return -1;
    }

    if (state) {
        ret = gpioWriteSet(GPIO_PIN);
    } else {
        ret = gpioWriteClear(GPIO_PIN);
    }

    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO %d state: %s\n", PI_GPIO, strerror(errno));
        gpioModeSet(GPIO_PIN, GPIO_INPUT);
        return -1;
    }

    return 0;
}

// Cleanup function
void cleanup(struct pigpio *gp) {
    i2cClose(1);
    gpioFree(gp);
    pigpioTerminate(gp);
}

