void logEvent(const char *msg, double field_mT) {
    char buffer[256];
    time_t now = time(NULL);
    struct tm tm_now;
    localtime_r(&now, &tm_now);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", &tm_now);

    FILE *file = fopen("magnetic_events.txt", "a");
    if (file) {
        fprintf(file, "%s: Field strength: %.2f mT, Relay: %s\n", buffer, field_mT, relayState ? "ON" : "OFF");
