int main() {
    // Initialize pigpio
    if (pgpio_init() == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error());
        return EXIT_FAILURE;
    }

    // Open log file for appending
    FILE *log_file = fopen(LOG_FILE, "a+");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        pgpio_cleanup();
        return EXIT_FAILURE;
    }

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Create TCP socket
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd == -1) {
        fprintf(stderr, "Failed to create socket: %s\n", strerror(errno));
        fclose(log_file);
        pgpio_cleanup();
        return EXIT_FAILURE;
    }

    // Set socket options
    if (setsockopt(sockfd, SOL_SOCKET, SO_REUSEADDR, &1, sizeof(int)) == -1) {
        fprintf(stderr, "Failed to set socket option: %s\n", strerror(errno));
        close(sockfd);
        fclose(log_file);
        pgpio_cleanup();
        return EXIT_FAILURE;
    }

    // Create server socket
    struct sockaddr_in addr;
    addr.sin_family = AF_INET;
    addr.sin_port = htons(PORT);
    addr.sin_addr.s_addr = INADDR_ANY;

    if (bind(sockfd, (struct sockaddr *)&addr, sizeof(addr)) == -1) {
        fprintf(stderr, "Failed to bind socket: %s\n", strerror(errno));
        close(sockfd);
        fclose(log_file);
        pgpio_cleanup();
        return EXIT_FAILURE;
    }

    if (listen(sockfd, 5) == -1) {
        fprintf(stderr, "Failed to listen on socket: %s\n", strerror(errno));
        close(sockfd);
        fclose(log_file);
        pgpio_cleanup();
        return EXIT_FAILURE;
    }

    // Accept loop
    char buffer[256];
    while (1) {
        int client_fd = accept(sockfd, (struct sockaddr *)&addr, (socklen_t*)&sizeof(addr));
        if (client_fd == -1) {
            fprintf(stderr, "Failed to accept connection: %s\n", strerror(errno));
            continue; // Continue listening for other connections
        }

        // Process commands from client
        while (fgets(buffer, sizeof(buffer), stdin) != NULL) {
            char *command = strtok(buffer, "\n");
            if (strcmp(command, "ON") == 0 || strcmp(command, "off") == 0) {
                gpio_control(RELAY_PIN, command == "ON" ? "ON" : "OFF");
                log_event("Command received: " + command);
            } else {
                log_event("Invalid command received: " + command);
            }

            // Close client socket after processing command
            close(client_fd);
        }

        // Close client socket
        close(client_fd);
    }

    // Shutdown and cleanup
    fclose(log_file);
    pgpio_cleanup();

    return EXIT_SUCCESS;
}

// Signal handler to gracefully shut down the server
void handle_signal(int signum) {
    fprintf(stderr, "Received signal %d, shutting down...\n", signum);
    // Stop accepting new connections
    close(sockfd);

    // Close log file
    fclose(log_file);

    // Turn off the relay
    gpio_control(RELAY_PIN, "OFF");

    // Clean up pigpio
    pgpio_cleanup();

    // Exit the program
    exit(EXIT_FAILURE);
}

