    if (pgpio_mode(pin, pigpio OUTPUT) == -1) {
        fprintf(stderr, "Failed to set GPIO %d to output: %s\n", pin, pigpio_error());
        return;
    }

    if (pgpio_write(pin, action[0] == '1') == -1) {
        fprintf(stderr, "Failed to set GPIO %d: %s\n", pin, pigpio_error());
        pgpio_mode(pin, pigpio INPUT);
    }
}

