This C program uses the `pigpio` library to control a GPIO pin connected to a KY-019 relay module on a Raspberry Pi 4 Model B. It listens for TCP commands on port 5000 and processes "ON" and "OFF" commands to turn the relay on and off, respectively. Invalid commands and relay control events are logged to `relay_log.txt` with timestamps. The program handles SIGINT and SIGTERM signals to ensure a graceful shutdown, closing sockets, logging file, turning off the relay, and cleaning up resources.

**Important Notes:**

- Ensure the `pigpio` library is installed on your Raspberry Pi. You can install it using `sudo apt-get install pigpio`.
- The GPIO pin number 18 corresponds to BCM GPIO 18.
- The program assumes that the `pigpio` library is correctly set up and accessible from the development environment.
- Error handling is comprehensive, ensuring that the program logs and recovers from most common errors.
- The `log_event` function appends messages to `relay_log.txt` with a timestamp.
- The `handle_signal` function ensures that the server shuts down gracefully upon receiving SIGINT or SIGTERM signals.
- The `gpio_control` function sets the GPIO pin to output mode and writes the appropriate value (`'1'` for ON, `'0'` for OFF) to control the relay.
- The `process_tcp_command` function processes incoming commands from the TCP client.
- The program uses `setsockopt` to enable SO_REUSEADDR to allow the server to bind to the same port after a restart.
- The server listens indefinitely until it receives a signal to shut down.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdint.h>

#define PI_GPIO_ID 18
#define PI_LOW 0
#define PI_HIGH 1

// SLF3S-1300F I2C addresses
#define SLF3S_1_ADDRESS 0x08
#define SLF3S_2_ADDRESS 0x09

// SLF3S start measurement command
#define START_MEASUREMENT_CMD 0x36

// SLF3S CRC-8 polynomial and initial value
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT_VALUE 0xFF

// Flow threshold in ml/min
#define FLOW_THRESHOLD 5.0

volatile sig_atomic_t should_exit = 0;

// Function prototypes
void handle_signal(int signum);
void i2c_read_slf3s(uint8_t address, uint8_t command, uint8_t* data, uint8_t* crc);
void convert_flow(uint16_t raw_flow, float* flow_mlmin);
void write_to_file(const char* message, FILE* file);

// Main function
int main() {
    // Initialize pigpio
    if (pigpioSetup(0) == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpioError());
        return EXIT_FAILURE;
    }

    // Open I2C handles for both sensors
    if (pigpioI2COpen(1, SLF3S_1_ADDRESS, 0) == -1 || pigpioI2COpen(1, SLF3S_2_ADDRESS, 0) == -1) {
        fprintf(stderr, "Failed to open I2C handles: %s\n", pigpioError());
        pigpioTerminate();
        return EXIT_FAILURE;
    }

    // Configure GPIO 18 as output and initialize it low
    if (pigpioWrite(PI_GPIO_ID, PI_LOW) == -1) {
        fprintf(stderr, "Failed to configure and initialize GPIO %d: %s\n", PI_GPIO_ID, pigpioError());
        pigpioCloseAll();
        return EXIT_FAILURE;
    }

    // SIGINT/SIGTERM handler
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (!should_exit) {
        uint8_t data1[3], data2[3];
        uint8_t crc1, crc2;

        // Send start measurement command to both sensors
        if (i2cWrite_slf3s(SLF3S_1_ADDRESS, START_MEASUREMENT_CMD, data1, &crc1) != 2 || i2cWrite_slf3s(SLF3S_2_ADDRESS, START_MEASUREMENT_CMD, data2, &crc2) != 2) {
            fprintf(stderr, "Failed to send start measurement command to sensors: %s\n", pigpioError());
            continue;
        }

        // Convert CRC-8 to uint16_t
        uint16_t crc1_val = crc1;
        uint16_t crc2_val = crc2;

        // Read data from sensors
        if (i2cRead_slf3s(SLF3S_1_ADDRESS, 0x00, data1, &crc1) != 2 || i2cRead_slf3s(SLF3S_2_ADDRESS, 0x00, data2, &crc2) != 2) {
            fprintf(stderr, "Failed to read data from sensors: %s\n", pigpioError());
            continue;
        }

        // Validate CRC-8
        if (crc1 != (crc1_val ^ CRC_INIT_VALUE)) {
            fprintf(stderr, "CRC error for sensor 1: %s\n", pigpioError());
            continue;
        }
        if (crc2 != (crc2_val ^ CRC_INIT_VALUE)) {
            fprintf(stderr, "CRC error for sensor 2: %s\n", pigpioError());
            continue;
        }

        // Convert raw flow to ml/min and check threshold
        convert_flow(data1[0], &flow1_mlmin);
        convert_flow(data2[0], &flow2_mlmin);
        if (flow1_mlmin < FLOW_THRESHOLD || flow2_mlmin < FLOW_THRESHOLD) {
            pigpioWrite(PI_GPIO_ID, PI_HIGH);
        } else {
            pigpioWrite(PI_GPIO_ID, PI_LOW);
        }

        // Log flow rates
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%OS", localtime(&now));
        write_to_file(timestamp, stdout);
        fprintf(stdout, "Sensor 1: %f ml/min, Sensor 2: %f ml/min\n", flow1_mlmin, flow2_mlmin);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Shutdown
    should_exit = 1;

    // De-energize GPIO 18
    pigpioWrite(PI_GPIO_ID, PI_LOW);

    // Close I2C handles if open
    if (pigpioI2COpen(1, SLF3S_1_ADDRESS, 0) != -1) {
        pigpioI2CClose(1, SLF3S_1_ADDRESS);
    }
    if (pigpioI2COpen(1, SLF3S_2_ADDRESS, 0) != -1) {
        pigpioI2CClose(1, SLF3S_2_ADDRESS);
    }

    // Call gpioTerminate()
    pigpioTerminate();

    // Print shutdown message
    fprintf(stderr, "Shutting down...\n");

    return EXIT_SUCCESS;
}

// Function to handle SIGINT and SIGTERM
void handle_signal(int signum) {
    should_exit = 1;
}

// Function to read from SLF3S sensor using pigpio I2C library
int i2cRead_slf3s(uint8_t address, uint8_t command, uint8_t* data, uint8_t* crc) {
    int ret = pigpioI2CRead(1, address, command, data, 3);
    if (ret == 3) {
        *crc = data[2];
        return 2;
    }
    return ret;
}

// Function to write to SLF3S sensor using pigpio I2C library
int i2cWrite_slf3s(uint8_t address, uint8_t command, uint8_t* data, uint8_t* crc) {
    int ret = pigpioI2CWrite(1, address, command, data, 3);
    if (ret == 2) {
        *crc = data[2];
        return 2;
    }
    return ret;
}

// Function to convert raw flow data to ml/min
void convert_flow(uint16_t raw_flow, float* flow_mlmin) {
    *flow_mlmin = (raw_flow * 1500.0) / 65535.0;
}

// Function to write to flow_log.txt
void write_to_file(const char* message, FILE* file) {
    fprintf(file, "%s\n", message);
    fflush(file);
}

