    if (gpioMode(BUTTON_LOCK, GPIO_INPUT_PULLUP) == -1) {
        fprintf(stderr, "Failed to set BUTTON_LOCK mode: %s\n", gpioError());
        exit(EXIT_FAILURE);
    }
