        fprintf(stderr, "Failed to set BUTTON_UNLOCK mode: %s\n", gpioError());
        exit(EXIT_FAILURE);
    }

    // Set SERVO_PIN to output
    if (gpioMode(SERVO_PIN, GPIO_OUTPUT) == -1) {
