void check_buttons() {
    int button_lock = gpioRead(BUTTON_LOCK);
    int button_unlock = gpioRead(BUTTON_UNLOCK);

    // Debounce logic
    if (button_lock && !locked) {
        // Wait for debounce
        sleep(DEBOUNCE_MS);
        locked = 1;
    } else if (!button_lock && locked) {
        // Wait for debounce
        sleep(DEBOUNCE_MS);
        locked = 0;
    }

    if (button_unlock && !unlocked) {
        // Wait for debounce
        sleep(DEBOUNCE_MS);
        unlocked = 1;
    } else if (!button_unlock && unlocked) {
        // Wait for debounce
        sleep(DEBOUNCE_MS);
        unlocked = 0;
    }

    printf("Button lock: %d, Button unlock: %d\n", button_lock, button_unlock);
}

