#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define PIR_PIN 4
#define FLOODLIGHT_PIN 17
#define LOG_FILENAME "security_log.txt"

FILE *log_file = NULL;

volatile sig_atomic_t is_running = 1;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        fprintf(stderr, "Stopping due to signal.\n");
        pigpio_stop();
        fclose(log_file);
        is_running = 0;
    }
}

int main() {
    // Initialize pigpio library
    if (pigpio_init() == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_errstr());
        pigpio_free();
        return 1;
    }

    // Set up GPIO pins
    if (gpioSetMode(PIR_PIN, GPIO_INPUT) == -1) {
        fprintf(stderr, "Failed to set PIR_PIN to input: %s\n", pigpio_errstr());
        pigpio_free();
        return 1;
    }
    if (gpioSetMode(FLOODLIGHT_PIN, GPIO_OUTPUT) == -1) {
        fprintf(stderr, "Failed to set FLOODLIGHT_PIN to output: %s\n", pigpio_errstr());
        pigpio_free();
        return 1;
    }

    // Open log file for appending
    if ((log_file = fopen(LOG_FILENAME, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILENAME);
        pigpio_free();
        return 1;
    }

    // SIGINT/SIGTERM handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (is_running) {
        // Poll PIR pin
        if (gpioRead(PIR_PIN) == 1) {
            // Motion detected
            time_t now = time(NULL);
            struct tm timeinfo;
            char timestamp[50];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));

            fprintf(log_file, "Motion detected at: %s\n", timestamp);

            // Activate floodlight
            if (gpioWrite(FLOODLIGHT_PIN, 1) == -1) {
                fprintf(stderr, "Failed to turn on floodlight: %s\n", pigpio_errstr());
                pigpio_free();
                return 1;
            }

            // Wait for 60 seconds
            sleep(60);

            // Turn off floodlight
            if (gpioWrite(FLOODLIGHT_PIN, 0) == -1) {
                fprintf(stderr, "Failed to turn off floodlight: %s\n", pigpio_errstr());
                pigpio_free();
                return 1;
            }

            time_t now_off = time(NULL);
            struct tm timeinfo_off;
            char timestamp_off[50];
            strftime(timestamp_off, sizeof(timestamp_off), "%Y-%m-%dT%H:%M:%S", localtime(&now_off));

            fprintf(log_file, "Floodlight turned off after %d seconds at: %s\n", 60, timestamp_off);

            // Close log file and exit on error
            fclose(log_file);
            pigpio_free();
            return 1;
        }

        // Poll at 100 ms interval
        usleep(100000);
    }

    // Clean up on exit
    if (log_file != NULL) fclose(log_file);
    pigpio_free();

    return 0;
}

