        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILENAME);
        pigpio_free();
        return 1;
    }

    // SIGINT/SIGTERM handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (is_running) {
        // Poll PIR pin
        if (gpioRead(PIR_PIN) == 1) {
            // Motion detected
            time_t now = time(NULL);
            struct tm timeinfo;
            char timestamp[50];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));

            fprintf(log_file, "Motion detected at: %s\n", timestamp);

            // Activate floodlight
            if (gpioWrite(FLOODLIGHT_PIN, 1) == -1) {
                fprintf(stderr, "Failed to turn on floodlight: %s\n", pigpio_errstr());
                pigpio_free();
                return 1;
            }

            // Wait for 60 seconds
            sleep(60);

            // Turn off floodlight
            if (gpioWrite(FLOODLIGHT_PIN, 0) == -1) {
                fprintf(stderr, "Failed to turn off floodlight: %s\n", pigpio_errstr());
                pigpio_free();
                return 1;
            }

            time_t now_off = time(NULL);
            struct tm timeinfo_off;
            char timestamp_off[50];
            strftime(timestamp_off, sizeof(timestamp_off), "%Y-%m-%dT%H:%M:%S", localtime(&now_off));

            fprintf(log_file, "Floodlight turned off after %d seconds at: %s\n", 60, timestamp_off);

            // Close log file and exit on error
            fclose(log_file);
            pigpio_free();
            return 1;
        }

        // Poll at 100 ms interval
        usleep(100000);
    }

    // Clean up on exit
    if (log_file != NULL) fclose(log_file);
    pigpio_free();

    return 0;
}
