#define MPR121_ADDRESS 0x5A
#define ELECTRODE_0_MASK 0x01

// Global variables
pigpio *pi;
wiringPiI2C *i2c;
int relayState = 0; // 0 for OFF, 1 for ON

// Function prototypes
void setup_pigpio();
void setup_i2c();
void cleanup_resources();
void handle_signal(int signum);

int main() {
    // Initialize pigpio and setup I2C
    setup_pigpio();
    setup_i2c();

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (1) {
        // Check for touch on electrode 0
        int touch_status = read_mpr121_touch_status();
        if (touch_status & ELECTRODE_0_MASK) {
            // Fresh touch detected on electrode 0
            toggle_relay();
        }

        // Sleep for a short period to avoid excessive CPU usage
        usleep(10000);
    }

    // Clean up resources on exit
    cleanup_resources();

    return 0;
}

// Function to initialize pigpio
void setup_pigpio() {
    pi = pigpioOpen();
    if (pi == NULL) {
        fprintf(stderr, "Failed to open pigpio: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }

    pigpioSetMode(pi, PIGPIO_MODE_ON);
    pigpioWriteReg(pi, RELAY_PIN, relayState ? 1 : 0); // Set relay state to OFF on startup
}

// Function to initialize I2C and configure MPR121
void setup_i2c() {
    i2c = wiringPiI2CSetup(1, MPR121_ADDRESS);
    if (i2c == NULL) {
        fprintf(stderr, "Failed to setup I2C: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // MPR121 Initialization
    // Soft-reset
    pigpioI2CWrite(i2c, 0, 0x06, 0x00); // Command to reset

    // Configure baseline filtering
    pigpioI2CWrite(i2c, 0, 0x07, 0x00); // MHD (Medium High Density)
    pigpioI2CWrite(i2c, 0, 0x08, 0x00); // NHD (Normal High Density)
    pigpioI2CWrite(i2c, 0, 0x09, 0x00); // NCL (Normal Closest Layer)
    pigpioI2CWrite(i2c, 0, 0x0A, 0x00); // FDL (Full Dynamic Range)

    // Set debounce
    pigpioI2CWrite(i2c, 0, 0x5B, 0x03); // 200 ms debounce

    // Set FFI/SFI/CDT
    pigpioI2CWrite(i2c, 0, 0x2C, 0x01); // Enable FFI and SFI, disable CDT

    // Set auto-config
    pigpioI2CWrite(i2c, 0, 0x7B, 0x01); // Enable auto-config
    pigpioI2CWrite(i2c, 0, 0x7C, 0x01); // Enable auto-config
    pigpioI2CWrite(i2c, 0, 0x7D, 0x01); // Enable auto-config

    // Enable 12 electrodes
    pigpioI2CWrite(i2c, 0, 0x5E, 0x0C);

    // Enable interrupts
    pigpioI2CWrite(i2c, 0, 0x01, 0x01);
}

// Function to clean up resources
void cleanup_resources() {
    if (i2c != NULL) {
        wiringPiI2CRelease(i2c);
        i2c = NULL;
    }

    if (pi != NULL) {
        pigpioClose(pi);
        pi = NULL;
    }
}

// Signal handler to clean up resources on SIGINT/SIGTERM
void handle_signal(int signum) {
    cleanup_resources();
    exit(EXIT_FAILURE);
}

// Function to read touch status from MPR121
int read_mpr121_touch_status() {
    uint8_t command = 0x00;
    uint16_t touch_status;

    pigpioI2CWrite(i2c, 0, 0x00, &command); // Read touch status command
    pigpioI2CRead(i2c, 0, 0x00, &touch_status, 2); // Read 16-bit touch status

    return touch_status;
}

// Function to toggle the relay
void toggle_relay() {
    if (relayState == 0) {
        pigpioWriteReg(pi, RELAY_PIN, 1); // Turn relay ON
        relayState = 1;
    } else {
        pigpioWriteReg(pi, RELAY_PIN, 0); // Turn relay OFF
        relayState = 0;
    }
}

