int main() {
    // Initialize GPIO with libgpiod
    setup_gpiod();

    // Set up signal handlers
    struct sigaction int_handler, term_handler;
    sigemptyset(&int_handler.sa_mask);
    int_handler.sa_handler = shutdown_gracefully;
    sigaction(SIGINT, &int_handler, NULL);
    int_handler.sa_handler = shutdown_graceful;
    sigaction(SIGTERM, &int_handler, NULL);

    // Create TCP socket
    int socket = socket(AF_INET, SOCK_STREAM, 0);
    if (socket == -1) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

