        if ((bytes_received = recv(client_socket, buffer, sizeof(buffer), 0)) == -1) {
            perror("recv");
            close(client_socket);
            exit(EXIT_FAILURE);
        }

        // Parse and handle command
        parse_and_handle_tcp_command(client_socket);

