        time_t now = time(NULL);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S ", localtime(&now));
        log_message("%s %s", timestamp, (bytes_received > 0) ? "Command received" : "Connection closed");

