#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>

// Define constants
#define BH1750_ADDR 0x23
#define I2C1_GPIO_SDA 2
#define I2C1_GPIO_SCL 3
#define RELAY_GPIO 23

// Function prototypes
void setup_pigpio();
void setup_i2c();
void read_lux();
void handle_signals(int signum);
void cleanup();

int main() {
    // Initialize global variables
    FILE *grow_log = NULL;
    int lux;
    pid_t pid = 0;
    int i2c_fd = -1;
    int relay_state = 0;

    // Signal handlers
    struct sigaction int_handler, term_handler;

    // Initialize pigpio
    setup_pigpio();

    // Set up I2C
    setup_i2c();

    // Main loop
    while (1) {
        // Check for signals
        if (waitpid(pid, &status, 0) == -1) {
            perror("waitpid");
            exit(EXIT_FAILURE);
        }

        handle_signals(SIGINT);
        handle_signals(SIGTERM);

        // Read lux
        if (read_lux()) {
            // Log lux value
            fprintf(grow_log, "%s %d\n", asctime(localtime()), lux);
        }

        // Check relay state based on lux
        if (lux < 150) {
            if (!relay_state) {
                // Activate relay
                gpioMode(RELAY_GPIO, GPIO_OUTPUT);
                gpioWrite(RELAY_GPIO, 1);
                relay_state = 1;
            }
        } else {
            // Deactivate relay
            if (relay_state) {
                gpioWrite(RELAY_GPIO, 0);
                relay_state = 0;
            }
        }

        // Sleep for 2 seconds
        sleep(2);
    }

    // Clean up
    cleanup();

    return 0;
}

// Function to setup pigpio
void setup_pigpio() {
    if (pigpioSetup(0) == -1) {
        fprintf(stderr, "Failed to setup pigpio: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }
}

// Function to setup I2C
void setup_i2c() {
    if (i2cOpen(I2C1_GPIO_SDA, I2C1_GPIO_SCL, 100000) == -1) {
        fprintf(stderr, "Failed to open I2C: %s\n", i2cError());
        exit(EXIT_FAILURE);
    }
}

// Function to read lux from BH1750
int read_lux() {
    int result = 0;

    // Send command for high-resolution mode
    if (i2cWriteByte(BH1750_ADDR, 0x20) == -1) {
        fprintf(stderr, "Failed to write command to BH1750: %s\n", i2cError());
        return 0;
    }

    // Wait for conversion
    usleep(120000);

    // Read the 2-byte result
    if (i2cReadDevice(BH1750_ADDR, 2, &result) == -1) {
        fprintf(stderr, "Failed to read from BH1750: %s\n", i2cError());
        return 0;
    }

    // Convert raw value to lux
    lux = result / 1.2;
    return 1;
}

// Signal handler for SIGINT and SIGTERM
void handle_signals(int signum) {
    if (signum == SIGINT) {
        printf("Caught SIGINT, exiting gracefully...\n");
    } else if (signum == SIGTERM) {
        printf("Caught SIGTERM, exiting gracefully...\n");
    }

    // Clean up and exit
    cleanup();
    exit(EXIT_SUCCESS);
}

// Function to cleanup resources
void cleanup() {
    // Close I2C handle
    if (i2cClose() == -1) {
        fprintf(stderr, "Failed to close I2C: %s\n", i2cError());
    }

    // Close log file
    if (grow_log != NULL) {
        fclose(grow_log);
        grow_log = NULL;
    }

    // Deactivate relay
    if (relay_state) {
        gpioWrite(RELAY_GPIO, 0);
        relay_state = 0;
    }

    // Terminate pigpio
    if (pigpioTerminate() == -1) {
        fprintf(stderr, "Failed to terminate pigpio: %s\n", pigpioError());
    }
}

