#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <gpiod.h>
#include <hx711.h>

#define GPIO23 16
#define GPIO24 18
#define GPIO25 22

#define TAL220B_DOUT_GPIO 23
#define TAL220B_SCK_GPIO 24
#define SOLENOID_GPIO 25

#define MAX_READINGS 5
#define THRESHOLD 1000
#define SCALE_FACTOR 1.0
#define DURATION_MS 200
#define TIMEOUT_MS 1000
#define MAX_RETRIES 3

// HX711 configuration
#define HX711_CHANNEL_A 0x01

// GPIO descriptors
static const struct gpiod_desc gpio_descs[] = {
    GPIOD_DESC(GPIO23, GPIOD_IN, "TAL220B_DOUT"),
    GPIOD_DESC(GPIO24, GPIOD_OUT_LOW, "TAL220B_SCK"),
    GPIOD_DESC(GPIO25, GPIOD_OUT_HIGH, "SOLENOID"),
    { .label = NULL }
};

// HX711 instance
hx711_t hx711;

// Tare offset
int tare_offset = 0;

// Main function
int main(int argc, char **argv) {
    // Initialize libgpiod
    if (gpiod_init() < 0) {
        perror("gpiod_init");
        return EXIT_FAILURE;
    }

    // Open GPIO descriptors
    int douts_fd = -1, scks_fd = -1, solenoid_fd = -1;
    for (int i = 0; gpio_descs[i].label; i++) {
        douts_fd = gpiod_open(gpio_descs[i].dev, GPIOD_OPEN_RWD);
        if (douts_fd < 0) {
            perror("gpiod_open DOUT");
            break;
        }

        scks_fd = gpiod_open(gpio_descs[i + 1].dev, GPIOD_OPEN_RWD);
        if (scks_fd < 0) {
            perror("gpiod_open SCK");
            gpiod_close(douts_fd);
            break;
        }

        solenoid_fd = gpiod_open(gpio_descs[i + 2].dev, GPIOD_OPEN_RWD);
        if (solenoid_fd < 0) {
            perror("gpiod_open SOLENOID");
            gpiod_close(scks_fd);
            gpiod_close(douts_fd);
            break;
        }
    }

    if (douts_fd < 0 || scks_fd < 0 || solenoid_fd < 0) {
        fprintf(stderr, "Failed to open GPIOs\n");
        return EXIT_FAILURE;
    }

    // Initialize HX711
    if (hx711_init(douts_fd, scks_fd) < 0) {
        perror("hx711_init");
        gpiod_close(douts_fd);
        gpiod_close(scks_fd);
        gpiod_close(solenoid_fd);
        return EXIT_FAILURE;
    }

    // Set up GPIO for solenoid
    int solenoid_state = LOW;
    while (1) {
        // Check for SIGINT or SIGTERM
        if (signal(SIGINT, SIG_IGN) == SIG_ERR || signal(SIGTERM, SIG_IGN) == SIG_ERR) {
            perror("signal");
            break;
        }

        signal(SIGINT, SIG_DFL);
        signal(SIGTERM, SIG_DFL);

        // Poll weight and trigger solenoid if threshold exceeded
        int avg_weight = 0;
        for (int i = 0; i < MAX_READINGS; i++) {
            int raw_weight = hx711_read_24bit();
            avg_weight += raw_weight;
        }
        avg_weight /= MAX_READINGS;

        if (avg_weight - tare_offset > THRESHOLD) {
            solenoid_state = HIGH;
            usleep(DURATION_MS);
            solenoid_state = LOW;
        }

        // Set solenoid GPIO
        if (gpiod_set_value(solenoid_fd, solenoid_state) < 0) {
            perror("gpiod_set_value SOLENOID");
            break;
        }

        // Check for DOUT timeout
        if (hx711_is_ready() == 0) {
            if (MAX_RETRIES == 0) {
                break;
            } else {
                usleep(TIMEOUT_MS);
                if (hx711_is_ready() == 0) {
                    fprintf(stderr, "Failed to read from load cell, retrying...\n");
                    --MAX_RETRIES;
                } else {
                    fprintf(stderr, "Load cell read successful after %d retries\n", MAX_RETRIES);
                }
            }
        } else {
            fprintf(stderr, "Load cell read successful\n");
        }
    }

    // Shutdown
    hx711_stop();
    gpiod_close(douts_fd);
    gpiod_close(scks_fd);
    gpiod_close(solenoid_fd);

    // Close syslog
    closelog();

    return EXIT_SUCCESS;
}

// Helper function to convert 24-bit raw reading to signed 32-bit integer
int hx711_read_24bit() {
    int raw = hx711_read();
    return (raw << 8) | hx711_read();
}

// HX711 initialization function
int hx711_init(int douts_fd, int scks_fd) {
    hx711_config_t config = {
        .channel = HX711_CHANNEL_A,
        .gain = 128,
        .dout_pin = douts_fd,
        .sck_pin = scks_fd
    };

    if (hx711_init(&config) < 0) {
        perror("hx711_init");
        return -1;
    }

    return 0;
}

// HX711 read 24-bit function
int hx711_read() {
    int raw = 0;
    while (!hx711_is_ready()) {
        // Wait for DOUT to go LOW
    }

    // Clock out 24 bits MSB-first
    for (int i = 0; i < 24; i++) {
        if (gpiod_get_value(scks_fd) == LOW) {
            raw <<= 1;
            if (gpiod_get_value(scks_fd) == HIGH) {
                break;
            }
        }
    }

    // Send one additional clock pulse to select Channel A / Gain 128
    gpiod_set_value(scks_fd, HIGH);
    usleep(1);
    gpiod_set_value(scks_fd, LOW);

    return raw;
}

// Utility functions for GPIO management
void gpiod_close(int fd) {
    gpiod_unlink(fd);
    close(fd);
}

int gpiod_set_value(int fd, int value) {
    return gpiod_set_value(fd, value) ? 0 : -1;
}

int gpiod_get_value(int fd) {
    return gpiod_get_value(fd) ? 1 : 0;
}

// SIGINT and SIGTERM handlers
void sigint_handler(int signum) {
    fprintf(stderr, "SIGINT received, shutting down gracefully...\n");
    exit(EXIT_FAILURE);
}

void sigterm_handler(int signum) {
    sigint_handler(signum);
}

// Tare operation by averaging 10 readings
void tare() {
    for (int i = 0; i < 10; i++) {
        int raw_weight = hx711_read_24bit();
        tare_offset += raw_weight;
    }
    tare_offset /= 10;
}

// Error handling for libgpiod calls
void handle_error(const char *operation, int fd) {
    if (gpiod_get_value(fd) != 1) {
        fprintf(stderr, "Error during %s operation on GPIO %d\n", operation, fd);
    }
}

