#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <libmosquitto.h>
#include <pigpio.h>

#define MQTT_TOPIC "home/lights/control"
#define MQTT_BROKER "localhost"
#define MQTT_PORT "1883"
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_KEEPALIVE 60
#define GPIO_PIN 17

// MQTT callback function
void on_message(const struct mosquitto_message *msg) {
    char *payload = msg->payload;
    int payload_len = msg->payload_length;

    if (payload_len == 0 || strcmp(payload, "ON") != 0 && strcmp(payload, "OFF") != 0) {
        syslog(LOG_ERR, "Received invalid MQTT message: %s", payload);
        return;
    }

    if (strcmp(payload, "ON") == 0) {
        pigpio_write(GPIO_PIN, 1); // HIGH
    } else if (strcmp(payload, "OFF") == 0) {
        pigpio_write(GPIO_PIN, 0); // LOW
    }

    syslog(LOG_INFO, "Received MQTT message: %s", payload);
}

int main() {
    // Initialize pigpio
    if (pigpio_init() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio: %s", pigpio_error());
        return EXIT_FAILURE;
    }

    // Configure GPIO17 as output
    if (pigpio_direction(GPIO_PIN, PIGPIO_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to configure GPIO17 as output: %s", pigpio_error());
        pigpio_cleanup();
        return EXIT_FAILURE;
    }

    // Initialize libmosquitto
    if (mosquitto_connect(NULL, MQTT_BROKER, MQTT_PORT, MQTT_CLIENT_ID, 0, NULL, 60, 1, on_connect, on_message, NULL) < 0) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_last_error());
        return EXIT_FAILURE;
    }

    // Handle connection success
    void on_connect(const struct mosquitto_connect_state *con) {
        syslog(LOG_INFO, "Connected to MQTT broker with session %lu", con->session);
        if (mosquitto_subscribe(con->client, MQTT_TOPIC, 0, NULL) < 0) {
            syslog(LOG_ERR, "Failed to subscribe to topic: %s", mosquitto_last_error());
            return;
        }
        syslog(LOG_INFO, "Subscribed to topic %s", MQTT_TOPIC);
    }

    // Handle disconnection
    void on_disconnect(const struct mosquitto_client *client, int rc) {
        syslog(LOG_INFO, "Disconnected from MQTT broker with reason: %s", mosquitto_last_error());
        // Wait 5 seconds before reconnecting
        sleep(5);
        reconnect();
    }

    // Handle SIGINT and SIGTERM
    struct sigaction sigIntAction, sigTermAction;
    sigIntAction.sa_handler = SIG_IGN;
    sigTermAction.sa_handler = SIG_IGN;

    sigaction(SIGINT, &sigIntAction, NULL);
    sigaction(SIGTERM, &sigTermAction, NULL);

    // Main MQTT loop
    while (1) {
        if (mosquitto_loop() < 0) {
            syslog(LOG_ERR, "Error in MQTT loop: %s", mosquitto_last_error());
            break;
        }
    }

    // Graceful shutdown
    pigpio_write(GPIO_PIN, 0); // LOW
    mosquitto_disconnect(NULL);
    mosquitto_lib_cleanup();
    pigpio_cleanup();
    closelog();

    return EXIT_SUCCESS;
}

// Function to attempt reconnecting after a disconnection
void reconnect() {
    if (mosquitto_connect(NULL, MQTT_BROKER, MQTT_PORT, MQTT_CLIENT_ID, 0, NULL, MQTT_KEEPALIVE, 1, on_connect, on_message, NULL) < 0) {
        syslog(LOG_ERR, "Failed to reconnect to MQTT broker: %s", mosquitto_last_error());
    }
}

