#include <stdio.h>
#include <pigpio.h>

int main() {
    // Initialize pigpio library and check for errors
    int rc = pigpio_init();
    if (rc == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error());
        return 1;
    }

    // Define the GPIO pins for the servos
    const int servoPins[] = {7, 8, 9, 10, 11};

    // Define the target pulse widths in microseconds
    const unsigned int pulseWidths[] = {1000, 1500, 2000, 500, 2500};

    // Set the PWM frequency to 50 Hz (20 ms period)
    for (int i = 0; i < 5; ++i) {
        // Initialize GPIO pin for PWM output
        int rc = pigpio_pwm_init(servoPins[i], 50);
        if (rc == -1) {
            fprintf(stderr, "Failed to initialize PWM on pin %d: %s\n", servoPins[i], pigpio_error());
            pigpio_cleanup(); // Clean up and exit on error
            return 1;
        }

        // Set the PWM range to 500-2500 microseconds
        rc = pigpio_pwm_range(servoPins[i], 500, 2500);
        if (rc == -1) {
            fprintf(stderr, "Failed to set PWM range on pin %d: %s\n", servoPins[i], pigpio_error());
            pigpio_cleanup(); // Clean up and exit on error
            return 1;
        }

        // Apply the pulse widths and hold for 3 seconds
        pigpio_pwm_set(servoPins[i], pulseWidths[i]);
        sleep(3); // Hold for 3 seconds
    }

    // Stop PWM and release resources
    for (int i = 0; i < 5; ++i) {
        pigpio_pwm_stop(servoPins[i]);
        pigpio_pwm_deinit(servoPins[i]);
    }

    // Clean up pigpio library
    pigpio_cleanup();

    // Exit with success
    return 0;
}

