#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <atomic>

// Constants
#define PI_CONTROLLER_KP 0.5
#define PI_CONTROLLER_KI 0.05
#define PWM_FREQ 10000
#define PWM_MIN 0
#define PWM_MAX 255
#define TARGET_RPM 50
#define ENCODER_TICKS_PER_REVOLUTION 64
#define STALL_TIMEOUT_MS 2000
#define ISR_PERIOD_MS 100

// GPIO pins
#define GPIO_A_IN1 17
#define GPIO_A_IN2 18
#define GPIO_B_IN3 22
#define GPIO_B_IN4 23
#define GPIO_A_ENC_A 4
#define GPIO_A_ENC_B 5
#define GPIO_B_ENC_A 6
#define GPIO_B_ENC_B 12

// Motor control variables
volatile int motor_a_pwm;
volatile int motor_b_pwm;
volatile int encoder_a_count;
volatile int encoder_b_count;
int motor_a_direction = 1; // Forward
int motor_b_direction = 1; // Forward

// Encoder counters (atomic for thread safety)
std::atomic<int> encoder_a_count_atomic;
std::atomic<int> encoder_b_count_atomic;

// PI controller variables
float error_a;
float error_b;
float integral_a;
float integral_b;
float kp = PI_CONTROLLER_KP;
float ki = PI_CONTROLLER_KI;
float last_error_a = 0;
float last_error_b = 0;
float last_integral_a = 0;
float last_integral_b = 0;

// Function prototypes
void setup_motors_and_encoders();
void setup_pi_controller();
void handle_encoder_counts();
void apply_motor_control();
void cleanup();
void sigint_handler(int signum);

int main() {
    // Initialize pigpio
    if (pigpioSetup() == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }

    // Set up GPIO pins
    setup_motors_and_encoders();

    // Setup PI controller
    setup_pi_controller();

    // Signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Main loop
    while (1) {
        apply_motor_control();
        usleep(ISR_PERIOD_MS * 1000); // Wait for ISR period
    }

    // Clean up
    cleanup();

    return 0;
}

// Function: setup_motors_and_encoders
void setup_motors_and_encoders() {
    if (pigpioPinMode(GPIO_A_IN1, pigpio OUTPUT) == -1 ||
        pigpioPinMode(GPIO_A_IN2, pigpio OUTPUT) == -1 ||
        pigpioPinMode(GPIO_B_IN3, pigpio OUTPUT) == -1 ||
        pigpioPinMode(GPIO_B_IN4, pigpio OUTPUT) == -1) {
        fprintf(stderr, "Failed to set GPIO pins to required mode: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }

    if (pigpioWriteDigital(GPIO_A_IN2, motor_a_direction) == -1 ||
        pigpioWriteDigital(GPIO_B_IN4, motor_b_direction) == -1) {
        fprintf(stderr, "Failed to set motor directions: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }
}

// Function: setup_pi_controller
void setup_pi_controller() {
    error_a = 0;
    error_b = 0;
    integral_a = 0;
    integral_b = 0;

    // Register ISR for encoder ticks
    if (pigpioISRSetup(GPIO_A_ENC_A, GPIO_A_ENC_B, handle_encoder_counts, ISR_PERIOD_MS) == -1 ||
        pigpioISRSetup(GPIO_B_ENC_A, GPIO_B_ENC_B, handle_encoder_counts, ISR_PERIOD_MS) == -1) {
        fprintf(stderr, "Failed to set up encoder interrupts: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }
}

// Function: handle_encoder_counts
void handle_encoder_counts() {
    int encoder_a_count_now = pigpioWaitForEdge(GPIO_A_ENC_A, 0);
    int encoder_b_count_now = pigpioWaitForEdge(GPIO_B_ENC_A, 0);

    // Increment counters atomically
    encoder_a_count_atomic.fetch_add(encoder_a_count_now, std::memory_order_relaxed);
    encoder_b_count_atomic.fetch_add(encoder_b_count_now, std::memory_order_relaxed);

    // Check for encoder stall
    if (encoder_a_count_now == 0 && encoder_b_count_now == 0) {
        fprintf(stderr, "Encoder stall detected on motor A/B.\n");
        // Implement appropriate stall handling here (e.g., stop motors)
    }
}

// Function: apply_motor_control
void apply_motor_control() {
    int encoder_a_count = encoder_a_count_atomic.load();
    int encoder_b_count = encoder_b_count_atomic.load();

    // Calculate RPM
    float rpm_a = (TARGET_RPM * ENCODER_TICKS_PER_REVOLUTION) / (encoder_a_count / 64.0);
    float rpm_b = (TARGET_RPM * ENCODER_TICKS_PER_REVOLUTION) / (encoder_b_count / 64.0);

    // Print RPM and PWM duty cycle
    printf("Motor A RPM: %.1f, PWM: %d\n", rpm_a, motor_a_pwm);
    printf("Motor B RPM: %.1f, PWM: %d\n", rpm_b, motor_b_pwm);

    // PI controller calculations
    float error_a = rpm_a - TARGET_RPM;
    float error_b = rpm_b - TARGET_RPM;

    float new_integral_a = integral_a + (error_a * ki);
    float new_integral_b = integral_b + (error_b * ki);

    integral_a = error_a;
    integral_b = error_b;

    // Apply PI control
    if (error_a > 0) {
        motor_a_pwm = (int)((kp * error_a) + 0.5 * (new_integral_a - last_integral_a));
        if (motor_a_pwm < PWM_MIN) motor_a_pwm = PWM_MIN;
        if (motor_a_pwm > PWM_MAX) motor_a_pwm = PWM_MAX;
    } else {
        motor_a_pwm = 0; // Stop motor if undershoot
    }

    if (error_b > 0) {
        motor_b_pwm = (int)((kp * error_b) + 0.5 * (new_integral_b - last_integral_b));
        if (motor_b_pwm < PWM_MIN) motor_b_pwm = PWM_MIN;
        if (motor_b_pwm > PWM_MAX) motor_b_pwm = PWM_MAX;
    } else {
        motor_b_pwm = 0; // Stop motor if undershoot
    }

    last_error_a = error_a;
    last_integral_a = new_integral_a;
    last_error_b = error_b;
    last_integral_b = new_integral_b;
}

// Function: cleanup
void cleanup() {
    // Stop motors
    pigpioWriteDigital(GPIO_A_IN2, 0);
    pigpioWriteDigital(GPIO_B_IN4, 0);

    // Unregister ISRs
    pigpioUnregisterISR(GPIO_A_ENC_A, handle_encoder_counts);
    pigpioUnregisterISR(GPIO_B_ENC_A, handle_encoder_counts);

    // Close pigpio
    pigpioClose();
}

// Function: sigint_handler
void sigint_handler(int signum) {
    // Stop motors and release resources
    pigpioWriteDigital(GPIO_A_IN2, 0);
    pigpioWriteDigital(GPIO_B_IN4, 0);

    // Unregister ISRs
    pigpioUnregisterISR(GPIO_A_ENC_A, handle_encoder_counts);
    pigpioUnregisterISR(GPIO_B_ENC_A, handle_encoder_counts);

    // Clean up
    cleanup();

    // Exit cleanly
    exit(EXIT_SUCCESS);
}

