    if (encoder_a_count_now == 0 && encoder_b_count_now == 0) {
        fprintf(stderr, "Encoder stall detected on motor A/B.\n");
        // Implement appropriate stall handling here (e.g., stop motors)
    }
}

// Function: apply_motor_control
void apply_motor_control() {
    int encoder_a_count = encoder_a_count_atomic.load();
    int encoder_b_count = encoder_b_count_atomic.load();

    // Calculate RPM
    float rpm_a = (TARGET_RPM * ENCODER_TICKS_PER_REVOLUTION) / (encoder_a_count / 64.0);
    float rpm_b = (TARGET_RPM * ENCODER_TICKS_PER_REVOLUTION) / (encoder_b_count / 64.0);

    // Print RPM and PWM duty cycle
    printf("Motor A RPM: %.1f, PWM: %d\n", rpm_a, motor_a_pwm);
    printf("Motor B RPM: %.1f, PWM: %d\n", rpm_b, motor_b_pwm);

    // PI controller calculations
    float error_a = rpm_a - TARGET_RPM;
    float error_b = rpm_b - TARGET_RPM;

    float new_integral_a = integral_a + (error_a * ki);
    float new_integral_b = integral_b + (error_b * ki);

    integral_a = error_a;
    integral_b = error_b;

    // Apply PI control
    if (error_a > 0) {
        motor_a_pwm = (int)((kp * error_a) + 0.5 * (new_integral_a - last_integral_a));
        if (motor_a_pwm < PWM_MIN) motor_a_pwm = PWM_MIN;
        if (motor_a_pwm > PWM_MAX) motor_a_pwm = PWM_MAX;
    } else {
        motor_a_pwm = 0; // Stop motor if undershoot
    }

    if (error_b > 0) {
        motor_b_pwm = (int)((kp * error_b) + 0.5 * (new_integral_b - last_integral_b));
        if (motor_b_pwm < PWM_MIN) motor_b_pwm = PWM_MIN;
        if (motor_b_pwm > PWM_MAX) motor_b_pwm = PWM_MAX;
    } else {
        motor_b_pwm = 0; // Stop motor if undershoot
    }

    last_error_a = error_a;
    last_integral_a = new_integral_a;
    last_error_b = error_b;
    last_integral_b = new_integral_b;
}

// Function: cleanup
void cleanup() {
    // Stop motors
    pigpioWriteDigital(GPIO_A_IN2, 0);
    pigpioWriteDigital(GPIO_B_IN4, 0);

    // Unregister ISRs
    pigpioUnregisterISR(GPIO_A_ENC_A, handle_encoder_counts);
    pigpioUnregisterISR(GPIO_B_ENC_A, handle_encoder_counts);

    // Close pigpio
    pigpioClose();
}

// Function: sigint_handler
void sigint_handler(int signum) {
    // Stop motors and release resources
    pigpioWriteDigital(GPIO_A_IN2, 0);
    pigpioWriteDigital(GPIO_B_IN4, 0);

    // Unregister ISRs
    pigpioUnregisterISR(GPIO_A_ENC_A, handle_encoder_counts);
    pigpioUnregisterISR(GPIO_B_ENC_A, handle_encoder_counts);

    // Clean up
    cleanup();

    // Exit cleanly
    exit(EXIT_SUCCESS);
}

