#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <wiringPiI2C.h>

#define RELAY_PIN 17
#define BH1750_ADDR 0x23
#define MIN_LUX 50
#define MAX_LUX 200
#define HYSTHERESIS 10
#define LOG_FILE "chicken_coop_log.txt"

FILE *log_file;
pigpio *pi;
wiringPiI2C *i2c;

void setup_pigpio() {
    if (pigpioSetup() == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }
    pi = pigpioOpen();
    if (pi == NULL) {
        fprintf(stderr, "Failed to open pigpio: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }
}

void setup_i2c() {
    if (wiringPiI2CSetup(1) == -1) {
        fprintf(stderr, "Failed to setup I2C bus: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    i2c = wiringPiI2CNew(1, BH1750_ADDR);
    if (i2c == NULL) {
        fprintf(stderr, "Failed to create I2C device: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void cleanup_resources() {
    if (i2c != NULL) {
        wiringPiI2CDelete(i2c);
        i2c = NULL;
    }
    if (pi != NULL) {
        pigpioClose(pi);
        pi = NULL;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

void read_lux() {
    if (i2c == NULL) {
        fprintf(stderr, "I2C device not initialized.\n");
        return;
    }

    int command = 0x21; // One-Time High-Resolution Mode 2
    if (wiringPiI2CWrite(i2c, &command, 1) == -1) {
        fprintf(stderr, "Error writing to BH1750: %s\n", strerror(errno));
        return;
    }

    // Wait at least 180 ms for the BH1750 to respond
    usleep(180000);

    if (wiringPiI2CRead(i2c, 2, NULL) == -1) {
        fprintf(stderr, "Error reading from BH1750: %s\n", strerror(errno));
        return;
    }

    uint16_t raw_lux = (wiringPiI2CRead(i2c, 2, NULL)[0] << 8) | wiringPiI2CRead(i2c, 2, NULL)[1];
    raw_lux /= 1.2; // Convert raw lux to actual lux

    fprintf(log_file, "%s: Lux = %d, Relay = %s\n", ctime(&time(NULL)), raw_lux, (raw_lux < MIN_LUX + HYSTHERESIS) ? "OFF" : "ON");

    if (raw_lux < MIN_LUX + HYSTHERESIS) {
        activate_relay();
    } else {
        deactivate_relay();
    }
}

void activate_relay() {
    if (digitalWriteHigh(pi, RELAY_PIN) == -1) {
        fprintf(stderr, "Error activating relay: %s\n", pigpioError());
    }
}

void deactivate_relay() {
    if (digitalWriteLow(pi, RELAY_PIN) == -1) {
        fprintf(stderr, "Error deactivating relay: %s\n", pigpioError());
    }
}

void poll_and_control() {
    while (1) {
        read_lux();
        usleep(5000000); // Poll every 5 seconds
    }
}

int main(int argc, char **argv) {
    setup_pigpio();
    setup_i2c();

    log_file = fopen(LOG_FILE, "a+");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, SIG_IGN); // Ignore SIGINT
    signal(SIGTERM, cleanup_resources); // Clean up on SIGTERM

    poll_and_control();

    return 0;
}

