#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define RELAY_GPIO 17
#define TOUCH_SENSOR_GPIO 4

volatile int touchDetected = 0;
int lastTouchState = LOW;
int debounceDelay = 50; // in milliseconds
int debounceWindow = 10; // in milliseconds

pigpiodHandle gpio;

void setup_pigpio() {
    if (gpioInitialise() == -1) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", pigpiodError());
        exit(EXIT_FAILURE);
    }
    gpio = pigpiodOpen();

    if (gpioSetMode(gpio, RELAY_GPIO, GPIO_OUTPUT) == -1) {
        fprintf(stderr, "Failed to set GPIO %d to output: %s\n", RELAY_GPIO, pigpiodError());
        pigpiodClose(gpio);
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(gpio, TOUCH_SENSOR_GPIO, GPIO_INPUT) == -1) {
        fprintf(stderr, "Failed to set GPIO %d to input: %s\n", TOUCH_SENSOR_GPIO, pigpiodError());
        pigpiodClose(gpio);
        exit(EXIT_FAILURE);
    }
}

void handle_touch() {
    if (gpioRead(gpio, TOUCH_SENSOR_GPIO) == HIGH) {
        touchDetected = 1;
        lastTouchState = HIGH;
        printf("Touch detected at %s\n", asctime(localtime(&lastTouchTime)));
    }
}

void toggle_relay() {
    if (touchDetected && lastTouchState == HIGH && (millis() - lastTouchTime) >= debounceDelay) {
        if (lastTouchState == HIGH) {
            gpioWrite(gpio, RELAY_GPIO, HIGH);
            printf("Relay turned ON at %s\n", asctime(localtime(&lastRelayTime)));
        } else {
            gpioWrite(gpio, RELAY_GPIO, LOW);
            printf("Relay turned OFF at %s\n", asctime(localtime(&lastRelayTime)));
        }
        lastTouchState = LOW;
        touchDetected = 0;
        lastRelayTime = millis();
    }
}

void debouncing() {
    while (millis() - lastTouchTime < debounceWindow) {
        // Wait for debounce stabilization
        usleep(debounceDelay * 1000);
    }
}

void cleanup_pigpio() {
    gpioWrite(gpio, RELAY_GPIO, LOW); // Turn off relay on SIGINT
    pigpiodClose(gpio);
}

void signal_handler(int signum) {
    printf("Received SIGINT, shutting down...\n");
    cleanup_pigpio();
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, signal_handler);

    setup_pigpio();
    lastTouchTime = millis();
    lastRelayTime = millis();

    while (1) {
        handle_touch();
        debouncing();
        toggle_relay();
        usleep(10000); // 10 ms sleep
    }

    return 0;
}

