#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <pigpio.h>

#define GPIO_FLOW_SENSOR 17
#define GPIO_SOLENOID Valve_GPIO // Assuming GPIO 27 for the solenoid
#define PULSE_PER_LITER 450.0
#define Hysteresis 0.5
#define LOG_FILENAME "water_flow.log"

pthread_mutex_t pulse_counter_mutex = PTHREAD_MUTEX_INITIALIZER;

volatile uint32_t flow_sensor_pulses = 0;

void initialize_pigpio() {
    int rc = gpioInitialise();
    if (rc != PI_GPIO_OK) {
        fprintf(stderr, "Failed to initialize pigpio: %d\n", rc);
        exit(EXIT_FAILURE);
    }
    fprintf(stderr, "pigpio initialized successfully\n");
}

void set_gpio_mode_and_initialise_isr() {
    int rc = gpioSetMode(GPIO_FLOW_SENSOR, GPIO_INPUT);
    if (rc != PI_GPIO_OK) {
        fprintf(stderr, "Failed to set GPIO %d mode: %d\n", GPIO_FLOW_SENSOR, rc);
        exit(EXIT_FAILURE);
    }
    rc = gpioSetISRFuncEx(GPIO_FLOW_SENSOR, GPIO_RISING, 1, 1000, flow_sensor_isr, NULL);
    if (rc != PI_GPIO_OK) {
        fprintf(stderr, "Failed to set ISR for GPIO %d: %d\n", GPIO_FLOW_SENSOR, rc);
        exit(EXIT_FAILURE);
    }
    fprintf(stderr, "Flow sensor ISR initialized with 1s debounce timeout\n");
}

void flow_sensor_isr(void *arg) {
    uint32_t pulses = ++flow_sensor_pulses;
    pthread_mutex_lock(&pulse_counter_mutex);
    if (pulses > 0) {
        pthread_mutex_unlock(&pulse_counter_mutex);
        compute_lpm_and_control_solenoid();
    }
    pthread_mutex_lock(&pulse_counter_mutex);
    if (pulses == 0) {
        // Reset pulse counter after computation
        flow_sensor_pulses = 0;
    }
    pthread_mutex_unlock(&pulse_counter_mutex);
}

void compute_lpm_and_control_solenoid() {
    double lpm = (flow_sensor_pulses / PULSE_PER_LITER) * 60.0;
    if (lpm > 5.0) {
        fprintf(stderr, "Flow rate exceeds 5.0 L/min, closing solenoid.\n");
        gpioWrite(GPIO_SOLENOID, 0);
    } else if (lpm < 4.5) {
        fprintf(stderr, "Flow rate below 4.5 L/min, reopening solenoid.\n");
        gpioWrite(GPIO_SOLENOID, 1);
    }

    // Implement hysteresis
    if (lpm >= 4.5) {
        fprintf(stderr, "Flow rate increased to 4.5 L/min or above, closing solenoid.\n");
        gpioWrite(GPIO_SOLENOID, 0);
    }

    fprintf(stderr, "Current LPM: %.2f\n", lpm);
}

void log_lpm_and_solenoid_state() {
    time_t now = time(NULL);
    char buffer[256];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(stderr, "%s - LPM: %.2f, Solenoid: %d\n", buffer, lpm, gpioRead(GPIO_SOLENOID));
    fflush(stderr);
}

void cleanup_resources() {
    gpioTerminate();
    fprintf(stderr, "Resources cleaned up\n");
    exit(EXIT_SUCCESS);
}

int main() {
    initialize_pigpio();
    set_gpio_mode_and_initialise_isr();

    while (1) {
        sleep(1); // Sample every second
        log_lpm_and_solenoid_state();
    }

    // Handle SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    return 0;
}

void sig_handler(int signum) {
    fprintf(stderr, "Received signal %d, reopening solenoid and cleaning up.\n", signum);
    cleanup_resources();
}

