    double lpm = (flow_sensor_pulses / PULSE_PER_LITER) * 60.0;
    if (lpm > 5.0) {
        fprintf(stderr, "Flow rate exceeds 5.0 L/min, closing solenoid.\n");
        gpioWrite(GPIO_SOLENOID, 0);
    } else if (lpm < 4.5) {
        fprintf(stderr, "Flow rate below 4.5 L/min, reopening solenoid.\n");
        gpioWrite(GPIO_SOLENOID, 1);
    }

    // Implement hysteresis
    if (lpm >= 4.5) {
        fprintf(stderr, "Flow rate increased to 4.5 L/min or above, closing solenoid.\n");
        gpioWrite(GPIO_SOLENOID, 0);
    }

    fprintf(stderr, "Current LPM: %.2f\n", lpm);
}

void log_lpm_and_solenoid_state() {
    time_t now = time(NULL);
    char buffer[256];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(stderr, "%s - LPM: %.2f, Solenoid: %d\n", buffer, lpm, gpioRead(GPIO_SOLENOID));
    fflush(stderr);
}

void cleanup_resources() {
    gpioTerminate();
    fprintf(stderr, "Resources cleaned up\n");
    exit(EXIT_SUCCESS);
}

int main() {
    initialize_pigpio();
    set_gpio_mode_and_initialise_isr();

    while (1) {
        sleep(1); // Sample every second
        log_lpm_and_solenoid_state();
    }

    // Handle SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    return 0;
}

