static void send_response_to_client(int server_socket, char *response) {
    struct sockaddr_in client_addr;
    socklen_t client_addr_size = sizeof(client_addr);

    int client_socket = accept(server_socket, (struct sockaddr *)&client_addr, &client_addr_size);
    if (client_socket == -1) {
        fprintf(stderr, "Error: Failed to accept client connection: %s\n", strerror(errno));
        return;
    }

    // Send response to client
    if (send(client_socket, response, strlen(response), 0) != strlen(response)) {
        fprintf(stderr, "Error: Failed to send response to client: %s\n", strerror(errno));
        close(client_socket);
        return;
    }

    // Close client socket
    close(client_socket);
}

