        fprintf(stderr, "Error: Failed to create TCP server socket: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    struct sockaddr_in server_address;
    server_address.sin_family = AF_INET;
    server_address.sin_port = htons(server_port);
    server_address.sin_addr.s_addr = inet_addr(server_ip);

    if (bind(server_socket, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        fprintf(stderr, "Error: Failed to bind TCP server socket: %s\n", strerror(errno));
        close(server_socket);
        return EXIT_FAILURE;
    }

    if (listen(server_socket, 5) < 0) {
        fprintf(stderr, "Error: Failed to listen on TCP server socket: %s\n", strerror(errno));
        close(server_socket);
        return EXIT_FAILURE;
    }

    int client_socket = accept(server_socket, NULL, NULL);
    if (client_socket == -1) {
        fprintf(stderr, "Error: Failed to accept client connection: %s\n", strerror(errno));
        close(server_socket);
        return EXIT_FAILURE;
    }

    // Handle client connection
    char target_weight_str[16];
    if (fgets(target_weight_str, 16, client_socket) == NULL) {
        fprintf(stderr, "Error: Client disconnection before receiving target weight\n");
        close(client_socket);
        return EXIT_FAILURE;
    }

    if (parse_weight_target(target_weight_str) < 0) {
        fprintf(stderr, "Error: Invalid target weight string received from client\n");
        close(client_socket);
        return EXIT_FAILURE;
    }

    dispense_ingredient(target_weight);

    // Close client socket
    close(client_socket);

    // Run the main loop
    while (1) {
        // Implement a proper loop logic here if needed
        // For simplicity, this example just runs indefinitely
    }

    return EXIT_SUCCESS;
