#include <pigpio.h>

#define SERVO_PIN 18
#define SERVO_MAX_ANGLE 180
#define STEP_ANGLE 10
#define PWM_PERIOD 20000 // 50 Hz
#define PWM_MIN_WIDTH 500
#define PWM_MAX_WIDTH 2500

volatile int angle = 90; // Initial angle in microseconds (1500 µs)
volatile int step = STEP_ANGLE;

// Function to handle SIGINT (Ctrl-C)
void signal_handler(int signum) {
    printf("Stopping servo...\n");
    gpioStop(SERVO_PIN);
    gpioTerminate();
    // Restore terminal settings
    struct termios old, new;
    tcgetattr(STDIN_FILENO, &old);
    cfmakeraw(&new);
    new.c_lflag &= ~(ICANON | ECHO);
    tcsetattr(STDIN_FILENO, TCSANOW, &new);
    printf("Terminal settings restored.\n");
    exit(0);
}

int main() {
    // Initialize pigpio library
    int rc = gpioInitialise();
    if (rc != PI_ERROR_OK) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", pigpioErrorString(rc));
        exit(1);
    }

    // Set up GPIO 18 as a servo output
    int rc2 = gpioMode(SERVO_PIN, GPIO_MODE_SERVO);
    if (rc2 != PI_ERROR_OK) {
        fprintf(stderr, "Failed to set GPIO %d to servo mode: %s\n", SERVO_PIN, pigpioErrorString(rc2));
        gpioTerminate();
        exit(1);
    }

    // Install SIGINT handler
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Main loop
    while (1) {
        char key;
        // Read a character without waiting for Enter
        if ((key = getchar()) != '\n') {
            switch (key) {
            case '+':
                angle += STEP_ANGLE;
                break;
            case '-':
                angle -= STEP_ANGLE;
                break;
            case 'q':
                printf("Quitting...\n");
                // Stop servo and terminate
                gpioStop(SERVO_PIN);
                gpioTerminate();
                break;
            default:
                // No action for other keys
                break;
            }

            // Validate pulse width
            if (angle < PWM_MIN_WIDTH || angle > PWM_MAX_WIDTH) {
                angle = 90; // Clamp to safe range
            }

            // Compute PWM duty cycle
            int duty_cycle = (angle * 1000) / SERVO_MAX_ANGLE;

            // Set servo angle
            gpioServo(SERVO_PIN, duty_cycle);

            // Print current angle
            printf("Current angle: %d°\n", angle);
        }
    }

    // Clean up on normal exit
    gpioStop(SERVO_PIN);
    gpioTerminate();

    // Restore terminal settings
    struct termios old, new;
    tcgetattr(STDIN_FILENO, &old);
    cfmakeraw(&new);
    new.c_lflag &= ~(ICANON | ECHO);
    tcsetattr(STDIN_FILENO, TCSANOW, &new);
    printf("Terminal settings restored.\n");

    return 0;
}

