// Function to setup GPIO using libgpiod
void setup_gpiod() {
    int ret;

    // Open the GPIO chip
    ret = gpiod_chip_open(&gpiod, "gpiochip0", GPIOD_OPEN_BY_NAME);
    if (ret < 0) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", gpiod_errstr(ret));
        exit(EXIT_FAILURE);
    }

    // Get the line for GPIO 17
    ret = gpiod_chip_get_line(&gpiod, GPIO_PIN, "gpio%d_in", GPIOD_LINE_BY_NUMBER);
    if (ret < 0) {
        fprintf(stderr, "Error getting GPIO line: %s\n", gpiod_errstr(ret));
        gpiod_chip_close(&gpiod);
        exit(EXIT_FAILURE);
    }

    // Request the line as input with pull-up enabled
    ret = gpiod_line_request_input_flags(&gpiod, GPIO_PIN, GPIOD_LINE_REQUEST_INPUT,
                                         GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        fprintf(stderr, "Error requesting line input with pull-up: %s\n", gpiod_errstr(ret));
        gpiod_line_release(&gpiod, GPIO_PIN);
        gpiod_chip_close(&gpiod);
        exit(EXIT_FAILURE);
    }

    printf("Motor RPM monitoring started on GPIO %d\n", GPIO_PIN);
}

// Function to handle signals (SIGINT, SIGTERM)
