// Function to read pulses from the A3144 Hall-effect sensor
void read_pulses() {
    struct timespec ts;
    struct timespec ts_start;
    long pulses = 0;
    int ret;

    // Clear any pending events
    ret = gpiod_line_event_clear(&gpiod, GPIO_PIN);
    if (ret < 0) {
        fprintf(stderr, "Error clearing events: %s\n", gpiod_errstr(ret));
        return;
    }

    // Start monotonic timer
    clock_gettime(CLOCK_MONOTONIC, &ts_start);

    while (1) {
        // Wait for an edge-triggered event with debounce
        ret = gpiod_line_event_wait(&gpiod, GPIO_PIN, DEBOUNCE_MS);
        if (ret < 0) {
            fprintf(stderr, "Error waiting for events: %s\n", gpiod_errstr(ret));
            break;
        }

        // Increment pulse count
        pulses++;

        // Check for debounce
        if (clock_gettime(CLOCK_MONOTONIC, &ts) - ts_start < DEBOUNCE_MS) {
            continue;
        }

        // Stop if SIGINT or SIGTERM received
        if (sigpending(&blocked_signals) && (blocked_signals & (SIGINT | SIGTERM))) {
            break;
        }
    }

    // Compute RPM and write to log
    write_rpm_to_log(pulses / SAMPLE_INTERVAL_MS * 60.0);
}

