                                         GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        fprintf(stderr, "Error requesting line input with pull-up: %s\n", gpiod_errstr(ret));
        gpiod_line_release(&gpiod, GPIO_PIN);
        gpiod_chip_close(&gpiod);
        exit(EXIT_FAILURE);
    }

    printf("Motor RPM monitoring started on GPIO %d\n", GPIO_PIN);
}

// Function to handle signals (SIGINT, SIGTERM)
void handle_signal(int signum) {
    // Stop the main loop
    stop_pulses();

    // Release the GPIO line
    gpiod_line_release(&gpiod, GPIO_PIN);

    // Close the GPIO chip
    gpiod_chip_close(&gpiod);

    // Close the log file
    fclose(logfile);

    // Exit cleanly
    exit(EXIT_SUCCESS);
}

// Function to read pulses from the A3144 Hall-effect sensor
void read_pulses() {
    struct timespec ts;
    struct timespec ts_start;
    long pulses = 0;
    int ret;

    // Clear any pending events
    ret = gpiod_line_event_clear(&gpiod, GPIO_PIN);
    if (ret < 0) {
        fprintf(stderr, "Error clearing events: %s\n", gpiod_errstr(ret));
        return;
    }

    // Start monotonic timer
    clock_gettime(CLOCK_MONOTONIC, &ts_start);

    while (1) {
        // Wait for an edge-triggered event with debounce
        ret = gpiod_line_event_wait(&gpiod, GPIO_PIN, DEBOUNCE_MS);
        if (ret < 0) {
            fprintf(stderr, "Error waiting for events: %s\n", gpiod_errstr(ret));
            break;
        }

        // Increment pulse count
        pulses++;

        // Check for debounce
        if (clock_gettime(CLOCK_MONOTONIC, &ts) - ts_start < DEBOUNCE_MS) {
            continue;
        }

        // Stop if SIGINT or SIGTERM received
        if (sigpending(&blocked_signals) && (blocked_signals & (SIGINT | SIGTERM))) {
            break;
        }
    }

    // Compute RPM and write to log
    write_rpm_to_log(pulses / SAMPLE_INTERVAL_MS * 60.0);
}

// Function to write RPM to the log file in CSV format
void write_rpm_to_log(double rpm) {
    char timestamp[32];
    char line[256];

    // Format timestamp in ISO 8601
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.", localtime(&now));

    // Build the CSV line
    snprintf(line, sizeof(line), "%s,%f", timestamp, rpm);

    // Append to the log file and flush
    fprintf(logfile, "%s\n", line);
    fflush(logfile);
}

// Function to clean up resources
void cleanup() {
    // Close the log file
    fclose(logfile);

    // Release the GPIO line
    gpiod_line_release(&gpiod, GPIO_PIN);

    // Close the GPIO chip
    gpiod_chip_close(&gpiod);
}

