volatile sig_atomic_t should_exit = 0;

// Function prototypes
void handleSignals(int signum);
void cleanup();

int main() {
    // Initialize pigpio library
    if (gpioInitialise() == PI_ERROR) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", gpioErrorString());
        exit(EXIT_FAILURE);
    }

    // Set up signal handlers
    signal(SIGINT, handleSignals);
    signal(SIGTERM, handleSignals);

    // GPIO setup
    if (gpioSetMode(GPIO_NUM_4, GPIO_IN) == PI_ERROR) {
        fprintf(stderr, "Failed to set GPIO 4 mode: %s\n", gpioErrorString());
        exit(EXIT_FAILURE);
    }
    if (gpioSetMode(GPIO_NUM_17, GPIO_OUT) == PI_ERROR) {
        fprintf(stderr, "Failed to set GPIO 17 mode: %s\n", gpioErrorString());
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO 4 for reading
    if (gpioSetFunction(GPIO_NUM_4, GPIO_F Falling) == PI_ERROR) {
        fprintf(stderr, "Failed to set GPIO 4 function: %s\n", gpioErrorString());
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (!should_exit) {
        // Poll GPIO 4 every 50 ms
        if (gpioRead(GPIO_NUM_4) == PI_HIGH) {
            // Relay is OFF, toggle ON if touched
            if (gpioWrite(GPIO_NUM_17, PI_HIGH) == PI_ERROR) {
                fprintf(stderr, "Failed to write to GPIO 17: %s\n", gpioErrorString());
                exit(EXIT_FAILURE);
            }
        } else {
            // Relay is ON, toggle OFF if not touched
            if (gpioWrite(GPIO_NUM_17, PI_LOW) == PI_ERROR) {
                fprintf(stderr, "Failed to write to GPIO 17: %s\n", gpioErrorString());
                exit(EXIT_FAILURE);
            }
        }

        // Check for continuous HIGH state for more than 10 seconds
        struct timespec timeout = { 10 * 1000 * 1000, 0 }; // 10 seconds
        if (clock_gettime(CLOCK_REALTIME, &timeout) == -1) {
            fprintf(stderr, "Failed to get current time: %s\n", strerror(errno));
            exit(EXIT_FAILURE);
        }
        if (gpioRead(GPIO_NUM_4) == PI_HIGH) {
            if (clock_gettime(CLOCK_REALTIME, &timeout) - (struct timespec){ timeout.tv_sec, timeout.tv_nsec } > 0) {
                // Sensor has been HIGH for more than 10 seconds
                gpioWrite(GPIO_NUM_17, PI_LOW); // Force relay OFF
                should_exit = 1;
            }
        }
    }

    // Clean up
    cleanup();

    return 0;
}

// Signal handler to set the volatile flag
void handleSignals(int signum) {
    should_exit = 1;
}

// Function to perform cleanup
void cleanup() {
    // Set relay OFF
    gpioWrite(GPIO_NUM_17, PI_LOW);

    // Terminate pigpio library
    gpioTerminate();
}

