#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_18 18 // BCM 18, hardware PWM 0
#define GPIO_23 23 // BCM 23, active-high enable/direction
#define GPIO_24 24 // BCM 24, rising-edge pulse counter for flow sensor

// YF-S201 calibration: 450 pulses per liter
#define PULSES_PER_LITER 450

// Proportional gain
#define KP 1.0

// PWM duty cycle range
#define PWM_MIN 0
#define PWM_MAX 255

// File path for logging
#define LOG_FILE_PATH "flow_log.csv"

// Global variables
pigpio *gp;
FILE *log_file;
unsigned long pulses_count = 0;
float flow_rate = 0.0;
float target_flow_rate;
int valve_position = 0;

// Function prototypes
void setup_pigpio();
void setup_gpio();
void initialize_pulses_counter();
void cleanup();
void proportional_control(float current_rate);
void handle_signal(int signum);
void write_to_log_file(float timestamp_ms, float flow_rate, int valve_position);

int main(int argc, char **argv) {
    // Check if the target flow rate is provided as a command-line argument
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <target_flow_rate_L/min>\n", argv[0]);
        return 1;
    }
    target_flow_rate = atof(argv[1]);

    // Initialize global variables
    gp = NULL;
    log_file = NULL;

    // Signal handler for SIGINT and SIGTERM
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main program logic
    setup_pigpio();
    setup_gpio();
    initialize_pulses_counter();
    while (1) {
        // Sample flow rate
        float current_rate = calculate_flow_rate_from_pulses(pulses_count);
        proportional_control(current_rate);

        // Log data
        write_to_log_file(time(NULL), current_rate, valve_position);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up on exit
    cleanup();

    return 0;
}

// Function to setup pigpio
void setup_pigpio() {
    if (gp == NULL) {
        gp = pigpioOpen();
        if (gp == NULL) {
            fprintf(stderr, "Failed to open pigpio: %s\n", pigpioError());
            exit(1);
        }
    }
}

// Function to setup GPIO pins
void setup_gpio() {
    if (gp == NULL) return;

    // Set GPIO 23 (enable/direction) to output high
    if (pigpioPinMode(gp, GPIO_23, pigpioOUTPUT) == -1) {
        fprintf(stderr, "Failed to set GPIO 23 mode: %s\n", pigpioError());
        exit(1);
    }
    pigpioWrite(gp, GPIO_23, 1);

    // Set GPIO 18 (PWM) to output
    if (pigpioPinMode(gp, GPIO_18, pigpioOUTPUT) == -1) {
        fprintf(stderr, "Failed to set GPIO 18 mode: %s\n", pigpioError());
        exit(1);
    }

    // Set GPIO 24 (interrupt) to input
    if (pigpioPinMode(gp, GPIO_24, pigpioINPUT) == -1) {
        fprintf(stderr, "Failed to set GPIO 24 mode: %s\n", pigpioError());
        exit(1);
    }
}

// Function to initialize the pulses counter on GPIO 24
void initialize_pulses_counter() {
    if (gp == NULL) return;

    // Register interrupt for GPIO 24 (rising edge)
    if (pigpioInterruptRegister(gp, GPIO_24, pigpioRISING_EDGE, interrupt_handler, NULL) == -1) {
        fprintf(stderr, "Failed to register GPIO 24 interrupt: %s\n", pigpioError());
        exit(1);
    }
}

// Interrupt handler for GPIO 24
void interrupt_handler(pigpio *gp, void *data) {
    pulses_count++;
    pigpioWait(1); // Ensure the main thread can process the increment
}

// Function to cleanup resources
void cleanup() {
    if (gp != NULL) {
        pigpioClose(gp);
        gp = NULL;
    }

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

// Function to calculate flow rate from pulses
float calculate_flow_rate_from_pulses(unsigned long pulses) {
    return (pulses / PULSES_PER_LITER) * target_flow_rate;
}

// Proportional control function
void proportional_control(float current_rate) {
    float error = target_flow_rate - current_rate;
    valve_position = (error * KP) + (valve_position * (1.0 - KP));

    // Clamp the valve position to the valid range
    if (valve_position < 0) valve_position = 0;
    if (valve_position > 255) valve_position = 255;

    // Update PWM duty cycle
    int pwm_value = (valve_position + 127) / 256 * 255; // Map to 0-255 range
    pigpioWrite(gp, GPIO_18, pwm_value);
}

// Function to write to the log file
void write_to_log_file(float timestamp_ms, float flow_rate, int valve_position) {
    char log_line[256];
    sprintf(log_line, "%ld,%f,%d", timestamp_ms, flow_rate, valve_position);
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", log_line);
    }
}

// Signal handler for SIGINT and SIGTERM
void handle_signal(int signum) {
    // Clean up on SIGINT/SIGTERM
    cleanup();
    exit(0);
}

