#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>

#define LOCK_GPIO_17 17
#define LOCK_GPIO_27 27
#define RFID_SPI_CHANNEL 0
#define VALID_TAG {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A}

// Function prototypes
void sigHandler(int signum);
int gpioInitialise(void);
int spiOpen(void);
int spiXfer(uint8_t* buffer, int len);
int gpioWrite(int gpio, int value);
void logAccessAttempt(const char* message, const time_t* timestamp);
void releaseLocksAndCloseResources(void);

// Global variables
pigpio *pi;
FILE *logFile;
int lockState[2] = {1, 1}; // 1 for engaged, 0 for disengaged

// Main function
int main(void) {
    // Initialize GPIO and SPI
    if (gpioInitialise() != 0) {
        fprintf(stderr, "Error initializing GPIO.\n");
        return EXIT_FAILURE;
    }
    if (spiOpen() != 0) {
        fprintf(stderr, "Error opening SPI.\n");
        gpioTerminate(); // Clean up and exit
        return EXIT_FAILURE;
    }

    // Install signal handler
    struct sigaction sa;
    sa.sa_handler = sigHandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        // Check RFID tag
        uint8_t tagBytes[10];
        int spiResult = spiXfer(tagBytes, sizeof(tagBytes));
        if (spiResult < 0) {
            logAccessAttempt("SPI read failure", NULL);
            continue;
        }

        // Check if valid RFID tag
        if (memcmp(tagBytes, VALID_TAG, sizeof(VALID_TAG)) != 0) {
            logAccessAttempt("Invalid RFID tag", NULL);
            continue;
        }

        // Check button press
        int buttonState = gpioRead(22);
        if (buttonState == 0) { // Active-low, so 0 indicates button press
            logAccessAttempt("Button press detected", NULL);
        } else {
            logAccessAttempt("No button press", NULL);
            continue;
        }

        // Successful authentication
        releaseLocksAndCloseResources();

        // Re-engage locks
        gpioWrite(LOCK_GPIO_17, 1);
        gpioWrite(LOCK_GPIO_27, 1);

        // Exit main loop on error or termination signal
        if (siginterrupt(SIGINT, 1) == 0) {
            printf("Exiting on SIGINT...\n");
            break;
        }
    }

    // Clean up on SIGINT/SIGTERM
    sigHandler(SIGINT);
    sigHandler(SIGTERM);

    return EXIT_SUCCESS;
}

// Signal handler for clean shutdown
void sigHandler(int signum) {
    releaseLocksAndCloseResources();
    exit(EXIT_SUCCESS);
}

// Function to initialize GPIO
int gpioInitialise(void) {
    int rc = 0;
    pi = pigpioOpen();
    if (pi == NULL) {
        fprintf(stderr, "Failed to open pigpio.\n");
        rc = -1;
    }
    return rc;
}

// Function to open SPI
int spiOpen(void) {
    int rc = 0;
    if (pigpioSpiOpen(pi, RFID_SPI_CHANNEL, 100000) == -1) {
        fprintf(stderr, "Failed to open SPI channel %d.\n", RFID_SPI_CHANNEL);
        rc = -1;
    }
    return rc;
}

// Function to transfer data via SPI
int spiXfer(uint8_t* buffer, int len) {
