    }

    // Stop motors, release resources, and close log file
    stop_motors();
    release_resources();
    fclose(log_file);

    return 0;
}

// Function to stop motors
void stop_motors() {
    gpiod_set_value_direct(ena_pwm, 0);
    gpiod_set_value_direct(enb_pwm, 0);
    gpiod_line_release(ena_ena);
    gpiod_line_release(enb_enb);
    gpiod_line_release(enc_a1);
