#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <stdint.h>

// Define GPIO and I2C constants
#define RELAY_GPIO 17
#define MPR121_I2C_BUS 1
#define MPR121_ADDRESS 0x5A

// MPR121 touch thresholds
#define TOUCH_THRESHOLD 10
#define RELEASE_THRESHOLD 5

// Function prototypes
void mpr121_init(void);
void relay_control(bool active);
void handle_signal(int signum);

int main() {
    // Initialize pigpio
    if (pigpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error());
        return EXIT_FAILURE;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, handle_signal);

    // Open I2C bus
    if (gpiod_i2c_open(MPR121_I2C_BUS) < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", gpiod_error());
        pigpio_cleanup();
        return EXIT_FAILURE;
    }

    // MPR121 initialization
    mpr121_init();

    // Main loop
    while (1) {
        // Poll MPR121 touch status registers
        uint8_t touch_status = 0;
        if (gpiod_i2c_read(MPR121_I2C_BUS, MPR121_ADDRESS, 0x00, &touch_status, 1) < 0) {
            fprintf(stderr, "Failed to read MPR121 touch status: %s\n", gpiod_error());
            break;
        }

        uint8_t release_status = 0;
        if (gpiod_i2c_read(MPR121_I2C_BUS, MPR121_ADDRESS, 0x01, &release_status, 1) < 0) {
            fprintf(stderr, "Failed to read MPR121 release status: %s\n", gpiod_error());
            break;
        }

        // Toggle relay based on touch status
        relay_control(touch_status > TOUCH_THRESHOLD && release_status <= RELEASE_THRESHOLD);

        // Log relay state change
        time_t now = time(NULL);
        char buffer[256];
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(stderr, "Relay state changed at %s\n", buffer);
        fprintf(stderr, "Touch status: 0x%X Release status: 0x%X\n", touch_status, release_status);

        // Sleep for 50ms
        usleep(50000);
    }

    // Clean up on exit
    relay_control(false); // Deactivate relay
    gpiod_i2c_close(MPR121_I2C_BUS); // Close I2C bus
    pigpio_cleanup(); // Clean up pigpio

    return EXIT_SUCCESS;
}

// Function to initialize MPR121
void mpr121_init() {
    // Soft reset
    if (gpiod_i2c_write(MPR121_I2C_BUS, MPR121_ADDRESS, 0x0F, 0x00, 1) < 0) {
        fprintf(stderr, "Failed to soft reset MPR121: %s\n", gpiod_error());
        return;
    }

    // Configure filtering
    if (gpiod_i2c_write(MPR121_I2C_BUS, MPR121_ADDRESS, 0x0E, 0x01, 1) < 0) {
        fprintf(stderr, "Failed to configure filtering: %s\n", gpiod_error());
        return;
    }

    // Set touch and release thresholds for all 12 electrodes
    for (uint8_t electrode = 0; electrode < 12; electrode++) {
        if (gpiod_i2c_write(MPR121_I2C_BUS, MPR121_ADDRESS, 0x0D, electrode << 4 | TOUCH_THRESHOLD, 1) < 0) {
            fprintf(stderr, "Failed to set touch threshold for electrode %u: %s\n", electrode, gpiod_error());
            return;
        }

        if (gpiod_i2c_write(MPR121_I2C_BUS, MPR121_ADDRESS, 0x0D, electrode << 4 | RELEASE_THRESHOLD, 1) < 0) {
            fprintf(stderr, "Failed to set release threshold for electrode %u: %s\n", electrode, gpiod_error());
            return;
        }
    }

    // Enable run mode
    if (gpiod_i2c_write(MPR121_I2C_BUS, MPR121_ADDRESS, 0x0C, 0x01, 1) < 0) {
        fprintf(stderr, "Failed to enable run mode: %s\n", gpiod_error());
        return;
    }
}

// Function to control the relay
void relay_control(bool active) {
    if (gpiod_set_mode(RELAY_GPIO, GPIO_MODE_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %u mode: %s\n", RELAY_GPIO, gpiod_error());
        return;
    }

    if (active) {
        if (gpiod_write(RELAY_GPIO, 1) < 0) {
            fprintf(stderr, "Failed to set GPIO %u HIGH: %s\n", RELAY_GPIO, gpiod_error());
        }
    } else {
        if (gpiod_write(RELAY_GPIO, 0) < 0) {
            fprintf(stderr, "Failed to set GPIO %u LOW: %s\n", RELAY_GPIO, gpiod_error());
        }
    }
}

// Signal handler for SIGINT
void handle_signal(int signum) {
    fprintf(stderr, "SIGINT received, shutting down...\n");
    // Deactivate relay
    relay_control(false);
    // Close I2C bus
    gpiod_i2c_close(MPR121_I2C_BUS);
    // Clean up pigpio
    pigpio_cleanup();
    exit(0); // Exit cleanly
}

