#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>

#define VALVE_1_GPIO 17
#define VALVE_2_GPIO 18

#define LOG_FILE_PATH "valve_log.txt"
#define LOG_EVENT_FORMAT "%Y-%m-%dT%H:%M:%S.%f %s\n"

int main(void) {
    // Initialize GPIO
    int gpio1_fd, gpio2_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line1, *line2;

    // Signal handlers
    struct sigaction int_handler, term_handler;

    // Initialize signal actions
    int_handler.sa_handler = SIG_IGN;
    sigemptyset(&int_handler.sa_mask);
    int_handler.sa_flags = 0;
    sigaction(SIGINT, &int_handler, NULL);

    int_handler.sa_handler = cleanup;
    sigemptyset(&int_handler.sa_mask);
    int_handler.sa_flags = 0;
    sigaction(SIGTERM, &int_handler, NULL);

    // Attempt to open the GPIO chip
    chip = gpiod_get_chip_by_name("bcm2835-gpio");
    if (chip == NULL) {
        fprintf(stderr, "Error: Could not find BCM2835 GPIO chip.\n");
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    line1 = gpiod_request_line(chip, GPIO_NUM_17, GPIOD_OUT_INIT_LOW);
    if (IS_ERR(line1)) {
        fprintf(stderr, "Error: Failed to request GPIO %d.\n", VALVE_1_GPIO);
        gpiod_free_line(line1);
        gpiod_put_chip(chip);
        return EXIT_FAILURE;
    }

    line2 = gpiod_request_line(chip, GPIO_NUM_18, GPIOD_OUT_INIT_LOW);
    if (IS_ERR(line2)) {
        fprintf(stderr, "Error: Failed to request GPIO %d.\n", VALVE_2_GPIO);
        gpiod_free_line(line2);
        gpiod_put_chip(chip);
        return EXIT_FAILURE;
    }

    // Open log file for writing
    int log_fd = open(LOG_FILE_PATH, O_WRONLY | O_CREAT, 0644);
    if (log_fd == -1) {
        fprintf(stderr, "Error: Failed to open %s for writing.\n", LOG_FILE_PATH);
        gpiod_free_line(line1);
        gpiod_free_line(line2);
        gpiod_put_chip(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Activate Valve 1
        time_t now = time(NULL);
        struct tm tm_now;
        localtime_r(&now, &tm_now);
        char event_str[100];
        strftime(event_str, sizeof(event_str), LOG_EVENT_FORMAT, &tm_now);
        fprintf(log_fd, "%s\n", event_str);

        gpiod_set_value(line1, 1); // HIGH to activate Valve 1
        usleep(500000); // 500 ms
        gpiod_set_value(line1, 0); // LOW to deactivate Valve 1

        // Pause for 5 seconds
        sleep(5);

        // Activate Valve 2
        time_t now = time(NULL);
        struct tm tm_now;
        localtime_r(&now, &tm_now);
        char event_str[100];
        strftime(event_str, sizeof(event_str), LOG_EVENT_FORMAT, &tm_now);
        fprintf(log_fd, "%s\n", event_str);

        gpiod_set_value(line2, 1); // HIGH to activate Valve 2
        usleep(1000000); // 1000 ms
        gpiod_set_value(line2, 0); // LOW to deactivate Valve 2

        // Pause for 10 seconds
        sleep(10);
    }

    // Cleanup on SIGINT or SIGTERM
    cleanup();

    // Close log file and release GPIO lines
    gpiod_free_line(line1);
    gpiod_free_line(line2);
    gpiod_put_chip(chip);

    close(log_fd);

    return EXIT_SUCCESS;
}

// Function to handle clean-up and GPIO release
void cleanup(void) {
    // Release GPIO lines
    gpiod_free_line(line1);
    gpiod_free_line(line2);
    gpiod_put_chip(chip);

    // Close log file
    close(log_fd);
}

