#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <wiringPiI2C.h>

// Define GPIO pins
#define RELAY_PIN 17
#define SDA_GPIO 2
#define SCL_GPIO 3

// MPR121 I2C address
#define MPR121_ADDRESS 0x5A

// Touch thresholds
#define TOUCH_THRESHOLD 0x10
#define RELEASE_THRESHOLD 0x0A

// Filter/charge time and electrode current
#define FILTER_TIME 0x20
#define ELECTRODE_CURRENT 0x01

// GPIO mode constants
#define GPIO_MODE_OUTPUT 1
#define GPIO_DIR_OUTPUT 2

// SIGINT and SIGTERM handlers
void signal_handler(int signum) {
    printf("Shutting down due to signal: %d\n", signum);
    // Close I2C bus
    wiringPiI2CClose(0);
    // Stop pigpio
    pigpioStop();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (pigpioSetup() == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpioError());
        return EXIT_FAILURE;
    }

    // Open I2C bus
    if (wiringPiI2COpen(0) == -1) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        pigpioShutdown();
        return EXIT_FAILURE;
    }

    // Set GPIO17 as output
    if (gpioMode(RELAY_PIN, GPIO_MODE_OUTPUT) == -1) {
        fprintf(stderr, "Failed to set GPIO17 as output: %s\n", strerror(errno));
        wiringPiI2CClose(0);
        pigpioShutdown();
        return EXIT_FAILURE;
    }

    // Initialize MPR121
    if (mpr121Init(0, MPR121_ADDRESS, TOUCH_THRESHOLD, RELEASE_THRESHOLD, FILTER_TIME, ELECTRODE_CURRENT) == -1) {
        fprintf(stderr, "Failed to initialize MPR121: %s\n", mpr121Error());
        gpioFree(RELAY_PIN);
        wiringPiI2CClose(0);
        pigpioShutdown();
        return EXIT_FAILURE;
    }

    // Wait for stabilization
    if (sleep(100) == -1) {
        fprintf(stderr, "Failed to sleep for 100 ms: %s\n", strerror(errno));
        mpr121Deinit();
        gpioFree(RELAY_PIN);
        wiringPiI2CClose(0);
        pigpioShutdown();
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Read touch status
