            fprintf(stderr, "Failed to sleep for 100 ms: %s\n", strerror(errno));
            break;
        }
    }

    // Close I2C bus on exit
    wiringPiI2CClose(0);

    // Stop pigpio and exit
    pigpioStop();
    exit(0);

