        if (handle_motion_detection()) {
            // Activate relay if motion detected and rate limiting allows
            if (handle_relay_activation()) {
                // Implement rate limiting
                handle_rate_limiting();
            }
        }
        usleep(50000); // Poll every 50 ms
    }

    // Clean up on exit
    cleanup();

    return 0;
}

// Function: setup_pigpio
void setup_pigpio() {
    pi = pigpioOpen();
    if (pi == NULL) {
        fprintf(stderr, "Failed to open pigpio. Error: %s\n", pigpioError());
        return;
    }
}

// Function: setup_log_file
void setup_log_file() {
    log_file = fopen(LOG_FILENAME, "a+");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILENAME);
        exit(1);
    }
}

// Function: handle_motion_detection
int handle_motion_detection() {
    int motion_detected = 0;
    int value;

    // Read GPIO 17 (PIR sensor)
    if (pigpioRead(pi, PIR_GPIO, &value) == 0) {
        motion_detected = (value == 1) ? 1 : 0;
    } else {
        fprintf(stderr, "Error reading GPIO %d: %s\n", PIR_GPIO, pigpioError());
        return 0; // Return 0 to indicate error
    }

    if (motion_detected) {
        fprintf(log_file, "Motion detected at %ld\n", (long)time(NULL));
    }

    return motion_detected;
}

// Function: handle_relay_activation
int handle_relay_activation() {
    int relay_state;

    // Set GPIO 18 to output mode
    if (pigpioMode(pi, RELAY_GPIO, pigpioOutput) == 0) {
        fprintf(stderr, "Error setting GPIO %d to output: %s\n", RELAY_GPIO, pigpioError());
        return 0;
    }

    // Activate relay
    if (pigpioWrite(pi, RELAY_GPIO, 1) == 0) {
        fprintf(stderr, "Error writing to GPIO %d: %s\n", RELAY_GPIO, pigpioError());
        return 0;
    } else {
        relay_state = 1;
    }

    // Log relay activation
    if (relay_state) {
        fprintf(log_file, "Door unlocked at %ld\n", (long)time(NULL));
    }

    // Set relay off after 500 ms
    sleep(0.5);
    if (pigpioWrite(pi, RELAY_GPIO, 0) == 0) {
        fprintf(stderr, "Error resetting GPIO %d: %s\n", RELAY_GPIO, pigpioError());
    }

    return 1;
}

// Function: handle_rate_limiting
void handle_rate_limiting() {
    time_t now = time(NULL);
    struct tm *timeinfo;
    char buffer[80];

    timeinfo = localtime(&now);

    // Check if 2 seconds have passed since the last unlock
    if (now - last_unlock_time >= 2) {
        last_unlock_time = now;
        // No rate limiting, proceed with normal operation
        return;
    }

    fprintf(log_file, "Rate limiting triggered at %s\n", ctime(&now));
}

// Function: cleanup
void cleanup() {
    // Close log file
    fclose(log_file);

    // Close pigpio
    pigpioClose(pi);

    // Set GPIOs to default state
    pigpioWrite(pi, RELAY_GPIO, 0); // Set relay off
    pigpioMode(pi, PIR_GPIO, pigpioInput); // Set PIR GPIO back to input with pull-down

    // Free resources
    pi = NULL;
}

