#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Global variables
volatile sig_atomic_t shutdown = 0;
pigpio *pi;
int motor1_pin = 17;
int motor2_pin = 27;
int pattern_index = 0;
int pattern_length_min = 5;
int pattern_length_max = 15;
int duty_cycle_min = 0;
int duty_cycle_max = 255;
int duration_min_ms = 50;
int duration_max_ms = 200;

// Function prototypes
void initialise_pigpio();
void cleanup_pigpio();
void generate_pattern(int length);
void play_pattern();
void handle_signal(int signum);

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Initialise pigpio library
    if (pi == NULL) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    initialise_pigpio();

    // Set GPIO pins to PWM mode
    if (gpioMode(motor1_pin, GPIO_PWM_OUTPUT) != PIGPIO_OK) {
        fprintf(stderr, "Failed to set GPIO pin %d to PWM output\n", motor1_pin);
        cleanup_pigpio();
        exit(EXIT_FAILURE);
    }
    if (gpioMode(motor2_pin, GPIO_PWM_OUTPUT) != PIGPIO_OK) {
        fprintf(stderr, "Failed to set GPIO pin %d to PWM output\n", motor2_pin);
        cleanup_pigpio();
        exit(EXIT_FAILURE);
    }

    // Handle SIGINT (Ctrl+C)
    signal(SIGINT, handle_signal);

    while (!shutdown) {
        generate_pattern(rand() % (pattern_length_max - pattern_length_min + 1) + pattern_length_min);
        play_pattern();
    }

    // Clean up and exit
    cleanup_pigpio();
    exit(EXIT_SUCCESS);
}

// Function to initialise pigpio and GPIO settings
void initialise_pigpio() {
    if (pi == NULL) {
        pi = pigpioOpen();
        if (pi == NULL) {
            fprintf(stderr, "Failed to open pigpio\n");
            exit(EXIT_FAILURE);
        }
    }
}

// Function to cleanup resources
void cleanup_pigpio() {
    if (pi != NULL) {
        pigpioClose(pi);
        pi = NULL;
    }
}

// Function to generate a random pattern length
void generate_pattern(int length) {
    int duty_cycles[2] = {rand() % (duty_cycle_max - duty_cycle_min + 1) + duty_cycle_min,
                          rand() % (duty_cycle_max - duty_cycle_min + 1) + duty_cycle_min};
    int durations[2] = {rand() % (duration_max_ms - duration_min_ms + 1) + duration_min_ms,
                        rand() % (duration_max_ms - duration_min_ms + 1) + duration_min_ms};

    pattern_length = length;
    motor_duty_cycles[0] = duty_cycles[0];
    motor_duty_cycles[1] = duty_cycles[1];
    motor_durations[0] = durations[0];
    motor_durations[1] = durations[1];
}

// Function to play a pattern
void play_pattern() {
    while (pattern_index < pattern_length) {
        // Set PWM duty cycles
        gpioPWMSet(pi, motor1_pin, motor_duty_cycles[0]);
        gpioPWMSet(pi, motor2_pin, motor_duty_cycles[1]);

        // Delay for the duration
        usleep(motor_durations[pattern_index] * 1000);

        // Increment pattern index
        pattern_index++;
    }

    // Reset GPIO pins to default mode
    gpioMode(motor1_pin, GPIO_INPUT);
    gpioMode(motor2_pin, GPIO_INPUT);
}

// Function to handle SIGINT and gracefully shut down
void handle_signal(int signum) {
    shutdown = 1;
    // Stop the motors and cleanup
    play_pattern();
    cleanup_pigpio();
}

