    char line[256];
    FILE* calFile = fopen(CALIBRATION_FILE_PATH, "r");
    if (calFile == NULL) {
        printf("Error: Unable to open calibration file.\n");
        fclose(calFile);
        return 1;
    }

    while (fgets(line, sizeof(line), calFile) != NULL) {
        if (sscanf(line, "%lf %lf", &scale_factor, &offset) == 2) {
            fclose(calFile);
            break;
        }
    }

    fclose(calFile);

