    pigpioTerminate();
}

void setup_gpio() {
    if (gpioMode(GPIO23, GPIO_OUTPUT_PP) == -1) {
        fprintf(stderr, "Failed to set GPIO23 as output: %s\n", gpioError());
        exit(EXIT_FAILURE);
    }
    if (gpioMode(GPIO24, GPIO_INPUT) == -1) {
        fprintf(stderr, "Failed to set GPIO24 as input: %s\n", gpioError());
        exit(EXIT_FAILURE);
    }
    if (gpioWrite(GPIO23, 0) == -1) {
        fprintf(stderr, "Failed to set GPIO23 low: %s\n", gpioError());
        exit(EXIT_FAILURE);
    }
}

void cleanup_gpio() {
    gpioFree();
}

void activate_solenoid() {
    if (gpioWrite(GPIO17, 1) == -1) {
        fprintf(stderr, "Failed to set GPIO17 high: %s\n", gpioError());
        exit(EXIT_FAILURE);
    }
    sleep(5);
    gpioWrite(GPIO17, 0);
}

void log_activation_event(const char *timestamp) {
    time_t now = time(NULL);
    char buffer[100];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(stock_events_file, "Activation event at %s, weight below %d grams\n", buffer, MIN_WEIGHT);
}

void monitor_weight() {
    while (!should_exit) {
        if (pigpioWaitForEvent(0) == PI_ERROR_TIMEOUT) {
            // Timeout, assume the system is busy or the load cell is not connected
            continue;
        }

        if (pigpioReadGPIO(GPIO24) == 0) {
            // SCK line is high, indicating a valid reading
            int weight = hx711Read();
            if (weight < MIN_WEIGHT) {
                log_activation_event((char *)(&weight));
                activate_solenoid();
            }
        } else {
            // SCK line is low, data-line-stuck-high condition
            fprintf(stderr, "Data line stuck high, retrying...\n");
            continue;
        }
    }
}

int hx711Read() {
    int data = 0;
    for (int i = 0; i < 1000; i++) {
        if (pigpioWrite(GPIO23, 1) == -1) {
            fprintf(stderr, "Failed to set GPIO23 high: %s\n", gpioError());
            return -1; // Error writing to DT line
        }
        pigpioWait(1);
        if (pigpioReadGPIO(GPIO24) == 0) {
            pigpioWait(1);
            data <<= 1;
            if (pigpioReadGPIO(GPIO24) == 1) {
                data |= 1;
            }
        }
    }
    return data;
}

int main() {
    setup_pigpio();
    setup_gpio();
    stock_events_file = fopen("stock_events.txt", "a+");
    if (stock_events_file == NULL) {
        fprintf(stderr, "Failed to open stock_events.txt for writing: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, SIG_IGN); // Ignore SIGINT to prevent immediate exit
    signal(SIGTERM, SIG_DFL); // Restore default action for SIGTERM

    pid_t pid = fork();
    if (pid == -1) {
        fprintf(stderr, "Failed to fork: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    } else if (pid == 0) {
        // Child process
        monitor_weight();
        exit(EXIT_SUCCESS);
    } else {
        // Parent process
        // Wait for the child to exit
        wait(NULL);
        // Clean up
        cleanup_gpio();
        fclose(stock_events_file);
        cleanup_pigpio();
        should_exit = 1;
    }

    return 0;
}
