#include <unistd.h>
#include <string.h>
#include <ctype.h>

#define CHIP_NAME "bcm2835-gpio"
#define SENSOR_GPIO 16 // GPIO16 (BCM)
#define RELAY_GPIO 20 // GPIO20 (BCM)
#define LOG_FILE_PATH "relay_events.log"

// Function prototypes
void initialize_gpios();
void handle_sensors();
void toggle_relay(int state);
void log_event(const char *message, int relay_state);
void cleanup();

int main() {
    // Initialize GPIOs
    initialize_gpios();

    // Main loop
    while (1) {
        // Monitor sensor
        handle_sensors();

        // Sleep for a short period to avoid excessive CPU usage
        usleep(10000);
    }

    // Clean up GPIOs and log file
    cleanup();

    return 0;
}

// Function to initialize GPIOs
void initialize_gpios() {
    // Open the GPIO chip
    gpiod_chip *chip;
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Error: Could not open GPIO chip '%s'.\n", CHIP_NAME);
        exit(EXIT_FAILURE);
    }

    // Request GPIO lines
    gpiod_line *sensor_line;
    gpiod_line *relay_line;

    sensor_line = gpiod_chip_get_line(chip, SENSOR_GPIO);
    if (sensor_line == NULL) {
        fprintf(stderr, "Error: Could not get GPIO line for sensor at %d.\n", SENSOR_GPIO);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (relay_line == NULL) {
        fprintf(stderr, "Error: Could not get GPIO line for relay at %d.\n", RELAY_GPIO);
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set sensor line as input and relay line as output
    if (gpiod_line_request_bulk_inputs(sensor_line, 1) < 0) {
        fprintf(stderr, "Error: Failed to request input for sensor GPIO.\n");
        gpiod_line_release(sensor_line);
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_bulk_outputs(relay_line, 1) < 0) {
        fprintf(stderr, "Error: Failed to request output for relay GPIO.\n");
        gpiod_line_release(sensor_line);
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Release sensor line after use
    gpiod_line_release(sensor_line);

    // Keep relay line until cleanup
    gpiod_line_release = NULL; // Prevent double free
}

// Function to handle the sensor
void handle_sensors() {
    int sensor_value;

    // Read sensor value
    if (gpiod_line_get_value(relay_line) < 0) {
        fprintf(stderr, "Error: Failed to read value from sensor GPIO.\n");
        return;
    }

    sensor_value = gpiod_line_get_value(relay_line);

    // Sensor is active-low, so an obstacle is detected when the value is LOW (0)
    if (sensor_value == 0) {
        toggle_relay(1 - (gpiod_line_get_value(relay_line) == 0)); // Toggle relay state
    }

    // Log the event
    log_event("Obstacle detected", gpiod_line_get_value(relay_line) == 0);
}

// Function to toggle the relay state
void toggle_relay(int state) {
    if (gpiod_line_set_value(relay_line, state) < 0) {
        fprintf(stderr, "Error: Failed to set value on relay GPIO.\n");
    }
}

// Function to log an event with timestamp
void log_event(const char *message, int state) {
    time_t timestamp;
    struct tm *timeinfo;
    char log_message[256];

    // Get current time
    timestamp = time(NULL);
    timeinfo = localtime(&timestamp);

    // Format timestamp in ISO 8601 format
    strftime(log_message, sizeof(log_message), "%Y-%m-%dT%H:%M:%S", timeinfo);

    // Append the message and relay state
    sprintf(log_message + strlen(log_message), "%s: Relay state: %d", message, state);

    // Open log file for appending
    int log_fd = fopen(LOG_FILE_PATH, "a+");
    if (log_fd == -1) {
        fprintf(stderr, "Error: Could not open log file '%s' for writing.\n", LOG_FILE_PATH);
        return;
    }

    // Write the log message
    if (fwrite(log_message, 1, strlen(log_message), log_fd) != strlen(log_message)) {
        fprintf(stderr, "Error: Failed to write to log file '%s'.\n", LOG_FILE_PATH);
        fclose(log_fd);
        return;
    }

    fclose(log_fd);
}

// Function to cleanup GPIOs and log file
void cleanup() {
    // Close the log file
    fclose(log_fd);

    // Release the relay line
    if (gpiod_line_release != NULL) {
        gpiod_line_release(relay_line);
        gpiod_line_release = NULL;
    }

    // Close the GPIO chip
    gpiod_chip_close(chip);
    chip = NULL;
}

