#define BUZZER_TRANSISTOR_PIN 2 // Assuming a transistor is used on GPIO2 for the buzzer

// Function prototypes
void setup_gpios();
void handle_motion();
void cleanup();

int main() {
    // Initialize gpiod
    if (gpiod_chip_open(GPIOD_CHIP_RASPBERRY_PI_4, GPIOD_OPEN_BY_NAME) < 0) {
        fprintf(stderr, "Error opening gpiod: %s\n", gpiod_get_name());
        exit(EXIT_FAILURE);
    }

    // Set up PIR sensor GPIO
    setup_gpios();

    // Set up buzzer GPIO and transistor
    setup_gpios();

    // Main loop
    while (1) {
        // Check for motion
        if (gpiod_line_get_value(PIR_GPIO) == 1) {
            // Motion detected
            handle_motion();
        }

        // Sleep for a short period to avoid CPU hogging
        usleep(10000);
    }

    // Cleanup on SIGINT or SIGTERM
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    return 0;
}

// Function to set up GPIOs
void setup_gpios() {
    // PIR sensor setup
    if (gpiod_line_request_input(PIR_GPIO) < 0) {
        fprintf(stderr, "Error requesting input on PIR GPIO: %s\n", gpiod_get_name());
        exit(EXIT_FAILURE);
    }

    // Buzzer setup
    if (gpiod_line_request_output(BUZZER_GPIO) < 0) {
        fprintf(stderr, "Error requesting output on buzzer GPIO: %s\n", gpiod_get_name());
        exit(EXIT_FAILURE);
    }

    // Transistor setup for buzzer
    if (gpiod_line_set_direction(BUZZER_TRANSISTOR_PIN, GPIOD_DIR_OUTPUT) < 0) {
        fprintf(stderr, "Error setting buzzer transistor GPIO direction: %s\n", gpiod_get_name());
        exit(EXIT_FAILURE);
    }

    // Set buzzer GPIO to high initially
    if (gpiod_line_set_value(BUZZER_GPIO, 1) < 0) {
        fprintf(stderr, "Error setting buzzer GPIO high: %s\n", gpiod_get_name());
        exit(EXIT_FAILURE);
    }
}

// Function to handle motion
void handle_motion() {
    // Get current timestamp
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char timestamp[50];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Write timestamp to motion_log.txt
    FILE *log_file = fopen("motion_log.txt", "a+");
    if (!log_file) {
        fprintf(stderr, "Error opening motion log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    fprintf(log_file, "%s\n", timestamp);
    fclose(log_file);

    // Activate buzzer for 2 seconds
    gpiod_line_set_value(BUZZER_GPIO, 1);
    usleep(2000000); // 2 seconds
    gpiod_line_set_value(BUZZER_GPIO, 0);

    // Release buzzer GPIO
    gpiod_line_release(BUZZER_GPIO);
}

// Function to cleanup and release resources
void cleanup() {
    // Turn off buzzer
    gpiod_line_set_value(BUZZER_GPIO, 0);

    // Release all GPIOs
    gpiod_line_release(PIR_GPIO);
    gpiod_line_release(BUZZER_GPIO);
    gpiod_line_release(BUZZER_TRANSISTOR_PIN);

    // Close gpiod chip
    gpiod_chip_close();
}

