#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// GPIO pins for the Keywish 3-Way Infrared Sensor and L298N motor driver
#define GPIO_IR_LEFT  4
#define GPIO_IR_MIDDLE 17
#define GPIO_IR_RIGHT 27
#define GPIO_PWM_LEFT  22
#define GPIO_PWM_RIGHT 23
#define GPIO_PWM_DIR_LEFT 24
#define GPIO_PWM_DIR_RIGHT 25

// Motor control constants
#define BASE_SPEED 150
#define HALVE_SPEED 127

// Function prototypes
void setup_pigpio();
void read_ir_sensors(int *left, int *middle, int *right);
void control_motors(int left_speed, int right_speed);
void handle_signal(int signum);
void cleanup();

int main() {
    // Initialize pigpio with error checking
    if (pi_perror("pi_popen")) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pi_perror());
        return EXIT_FAILURE;
    }

    // Signal handler for SIGINT
    signal(SIGINT, handle_signal);

    // Initialize variables
    int left_speed = BASE_SPEED;
    int right_speed = BASE_SPEED;
    int left_sensor;
    int middle_sensor;
    int right_sensor;

    // Main loop
    while (1) {
        // Read IR sensors
        read_ir_sensors(&left_sensor, &middle_sensor, &right_sensor);

        // Apply control law
        if (middle_sensor == 0) {
            control_motors(left_speed, right_speed);
        } else if (left_sensor == 0) {
            left_speed = HALVE_SPEED;
            control_motors(left_speed, right_speed);
        } else if (right_sensor == 0) {
            right_speed = HALVE_SPEED;
            control_motors(left_speed, right_speed);
        } else {
            left_speed = 0;
            right_speed = 0;
        }

        // Log control cycle
        char timestamp[50];
        time_t now = time(NULL);
        char buffer[50];
        strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", localtime(&now));
        sprintf(timestamp, "%s: left_sensor=%d, middle_sensor=%d, right_sensor=%d, left_speed=%d, right_speed=%d", buffer, left_sensor, middle_sensor, right_sensor, left_speed, right_speed);

        FILE *log_file = fopen("trace_log.txt", "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
            break; // Exit on log file open error
        }
        fprintf(log_file, "%s\n", timestamp);
        fclose(log_file);

        // Sleep to control loop frequency
        usleep(10000);
    }

    // Cleanup on SIGINT
    handle_signal(SIGINT);

    // Close log file and release resources
    cleanup();

    return EXIT_SUCCESS;
}

// Function to set up pigpio
void setup_pigpio() {
    int ret;
    ret = pi_open(0);
    if (ret != PI_OK) {
        fprintf(stderr, "pi_open failed: %s\n", pi_perror());
        exit(EXIT_FAILURE);
    }

    ret = pi_set_mode(GPIO_IR_LEFT, PI_OUTPUT);
    if (ret != PI_OK) {
        fprintf(stderr, "pi_set_mode(GPIO_IR_LEFT) failed: %s\n", pi_perror());
        exit(EXIT_FAILURE);
    }

    ret = pi_set_mode(GPIO_IR_MIDDLE, PI_INPUT);
    if (ret != PI_OK) {
        fprintf(stderr, "pi_set_mode(GPIO_IR_MIDDLE) failed: %s\n", pi_perror());
        exit(EXIT_FAILURE);
    }

    ret = pi_set_mode(GPIO_IR_RIGHT, PI_INPUT);
    if (ret != PI_OK) {
        fprintf(stderr, "pi_set_mode(GPIO_IR_RIGHT) failed: %s\n", pi_perror());
        exit(EXIT_FAILURE);
    }

    ret = pi_set_mode(GPIO_PWM_LEFT, PI_OUTPUT);
    if (ret != PI_OK) {
        fprintf(stderr, "pi_set_mode(GPIO_PWM_LEFT) failed: %s\n", pi_perror());
        exit(EXIT_FAILURE);
    }

    ret = pi_set_mode(GPIO_PWM_RIGHT, PI_OUTPUT);
    if (ret != PI_OK) {
        fprintf(stderr, "pi_set_mode(GPIO_PWM_RIGHT) failed: %s\n", pi_perror());
        exit(EXIT_FAILURE);
    }

    ret = pi_set_mode(GPIO_PWM_DIR_LEFT, PI_OUTPUT);
    if (ret != PI_OK) {
        fprintf(stderr, "pi_set_mode(GPIO_PWM_DIR_LEFT) failed: %s\n", pi_perror());
        exit(EXIT_FAILURE);
    }

    ret = pi_set_mode(GPIO_PWM_DIR_RIGHT, PI_OUTPUT);
    if (ret != PI_OK) {
        fprintf(stderr, "pi_set_mode(GPIO_PWM_DIR_RIGHT) failed: %s\n", pi_perror());
        exit(EXIT_FAILURE);
    }

    // Set GPIO PWM frequency to 1 kHz
    ret = pi_pwm_freq(1000);
    if (ret != PI_OK) {
        fprintf(stderr, "pi_pwm_freq(1000) failed: %s\n", pi_perror());
        exit(EXIT_FAILURE);
    }
}

// Function to read IR sensors
void read_ir_sensors(int *left, int *middle, int *right) {
    int left_sensor_value = 0;
    int middle_sensor_value = 0;
    int right_sensor_value = 0;

    // Read GPIO values
    left_sensor_value = pi_pigpio_read(GPIO_IR_LEFT);
    middle_sensor_value = pi_pigpio_read(GPIO_IR_MIDDLE);
    right_sensor_value = pi_pigpio_read(GPIO_IR_RIGHT);

    *left = (left_sensor_value == 0);
    *middle = (middle_sensor_value == 0);
    *right = (right_sensor_value == 0);
}

// Function to control the motors
void control_motors(int left_speed, int right_speed) {
    int left_pwm = (left_speed * 255) / BASE_SPEED;
    int right_pwm = (right_speed * 255) / BASE_SPEED;

    // Set PWM duty cycles
    pi_pwm_write(GPIO_PWM_LEFT, left_pwm);
    pi_pwm_write(GPIO_PWM_RIGHT, right_pwm);
}

// Signal handler for SIGINT
void handle_signal(int signum) {
    // Stop motors
    control_motors(0, 0);

    // Close log file and release resources
    cleanup();
}

// Cleanup function
void cleanup() {
    // Stop pigpio
    pi_close();

    // Release GPIOs
    pi_free_all();

    // Close log file
    if (FILE *log_file = fopen("trace_log.txt", "r+"); log_file != NULL) {
        fclose(log_file);
    }
}

