// Function to set up pigpio
void setup_pigpio() {
    int ret;
    ret = pi_open(0);
    if (ret != PI_OK) {
        fprintf(stderr, "pi_open failed: %s\n", pi_perror());
        exit(EXIT_FAILURE);
    }

    ret = pi_set_mode(GPIO_IR_LEFT, PI_OUTPUT);
    if (ret != PI_OK) {
        fprintf(stderr, "pi_set_mode(GPIO_IR_LEFT) failed: %s\n", pi_perror());
        exit(EXIT_FAILURE);
    }

    ret = pi_set_mode(GPIO_IR_MIDDLE, PI_INPUT);
    if (ret != PI_OK) {
        fprintf(stderr, "pi_set_mode(GPIO_IR_MIDDLE) failed: %s\n", pi_perror());
        exit(EXIT_FAILURE);
    }

    ret = pi_set_mode(GPIO_IR_RIGHT, PI_INPUT);
    if (ret != PI_OK) {
        fprintf(stderr, "pi_set_mode(GPIO_IR_RIGHT) failed: %s\n", pi_perror());
        exit(EXIT_FAILURE);
    }

    ret = pi_set_mode(GPIO_PWM_LEFT, PI_OUTPUT);
    if (ret != PI_OK) {
        fprintf(stderr, "pi_set_mode(GPIO_PWM_LEFT) failed: %s\n", pi_perror());
        exit(EXIT_FAILURE);
    }

    ret = pi_set_mode(GPIO_PWM_RIGHT, PI_OUTPUT);
    if (ret != PI_OK) {
        fprintf(stderr, "pi_set_mode(GPIO_PWM_RIGHT) failed: %s\n", pi_perror());
        exit(EXIT_FAILURE);
    }

    ret = pi_set_mode(GPIO_PWM_DIR_LEFT, PI_OUTPUT);
    if (ret != PI_OK) {
        fprintf(stderr, "pi_set_mode(GPIO_PWM_DIR_LEFT) failed: %s\n", pi_perror());
        exit(EXIT_FAILURE);
    }

    ret = pi_set_mode(GPIO_PWM_DIR_RIGHT, PI_OUTPUT);
    if (ret != PI_OK) {
        fprintf(stderr, "pi_set_mode(GPIO_PWM_DIR_RIGHT) failed: %s\n", pi_perror());
        exit(EXIT_FAILURE);
    }

    // Set GPIO PWM frequency to 1 kHz
    ret = pi_pwm_freq(1000);
    if (ret != PI_OK) {
        fprintf(stderr, "pi_pwm_freq(1000) failed: %s\n", pi_perror());
        exit(EXIT_FAILURE);
    }
}

// Function to read IR sensors
void read_ir_sensors(int *left, int *middle, int *right) {
    int left_sensor_value = 0;
    int middle_sensor_value = 0;
    int right_sensor_value = 0;

    // Read GPIO values
    left_sensor_value = pi_pigpio_read(GPIO_IR_LEFT);
    middle_sensor_value = pi_pigpio_read(GPIO_IR_MIDDLE);
    right_sensor_value = pi_pigpio_read(GPIO_IR_RIGHT);

    *left = (left_sensor_value == 0);
    *middle = (middle_sensor_value == 0);
    *right = (right_sensor_value == 0);
}

// Function to control the motors
void control_motors(int left_speed, int right_speed) {
    int left_pwm = (left_speed * 255) / BASE_SPEED;
    int right_pwm = (right_speed * 255) / BASE_SPEED;

    // Set PWM duty cycles
    pi_pwm_write(GPIO_PWM_LEFT, left_pwm);
    pi_pwm_write(GPIO_PWM_RIGHT, right_pwm);
}

// Signal handler for SIGINT
void handle_signal(int signum) {
    // Stop motors
    control_motors(0, 0);

    // Close log file and release resources
    cleanup();
}

