void cleanup() {
    // Stop pigpio
    pi_close();

    // Release GPIOs
    pi_free_all();

    // Close log file
    if (FILE *log_file = fopen("trace_log.txt", "r+"); log_file != NULL) {
        fclose(log_file);
    }
}
