#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <time.h>
#include <pigpio.h>

#define PIGPIO_PORT 0  // Use the default pigpio port
#define BH1750_ADDR 0x23
#define I2C_BUS 1
#define RELAY_GPIO 23

// Function prototypes
void initialize_pigpio();
void initialize_i2c();
void read_illuminance();
void handle_relay();
void log_event(const char *msg, uint32_t timestamp);
void cleanup();

int main() {
    // Initialize pigpio
    initialize_pigpio();

    // Initialize I2C
    initialize_i2c();

    uint32_t timestamp;
    while (1) {
        // Read illuminance
        read_illuminance();

        // Handle relay based on lux reading
        handle_relay();

        // Log events
        log_event("Lux: ", lux);
        log_event("Relay state: ", (gpioReadPin(RELAY_GPIO) == GPIO_HIGH ? "ON" : "OFF"));

        // Sleep for 180 ms to match the BH1750 measurement delay
        usleep(180000);
    }

    // Clean up on SIGINT
    SIGINTHandler signal_handler;
    signal(SIGINT, signal_handler);

    signal_handler = NULL; // Reset the signal handler

    // Clean up resources
    cleanup();

    return 0;
}

// Function to initialize pigpio
void initialize_pigpio() {
    if (pigpioSetup(PIGPIO_PORT) == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpioError());
        exit(EXIT_FAILURE);
    }
}

// Function to initialize I2C
void initialize_i2c() {
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    struct i2c_msg msg = {
        .addr = BH1750_ADDR,
        .flags = 0,
        .len = sizeof(uint16_t)
    };

    if (i2c_smbus_write_i2c_block_data(i2c_fd, BH1750_ADDR, 0x10, &msg) != 2) {
        fprintf(stderr, "Failed to set BH1750 to high-resolution mode: %s\n", i2c_get_error_str(i2c_fd));
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

// Function to read illuminance from BH1750
void read_illuminance() {
    struct i2c_msg read_msg = {
        .addr = BH1750_ADDR,
        .flags = 0,
        .len = sizeof(uint16_t)
    };

    if (i2c_smbus_read_i2c_block_data(i2c_fd, BH1750_ADDR, 0x00, &read_msg) != 2) {
        fprintf(stderr, "Failed to read illuminance: %s\n", i2c_get_error_str(i2c_fd));
        return;
    }

    lux = read_msg.data[0];
}

// Function to handle the relay based on lux reading
void handle_relay() {
    if (lux < 150) {
        gpioModeSet(RELAY_GPIO, GPIO_OUTPUT);
        gpioWritePin(RELAY_GPIO, GPIO_HIGH);
    } else {
        gpioModeSet(RELAY_GPIO, GPIO_INPUT);
        gpioWritePin(RELAY_GPIO, GPIO_LOW);
    }
}

// Function to log an event with timestamp
void log_event(const char *msg, uint32_t timestamp) {
    char log_line[256];
    sprintf(log_line, "%s @ %ldms", msg, timestamp);
    FILE *log_file = fopen("grow_log.txt", "a+");
    if (log_file) {
        fprintf(log_file, "%s\n", log_line);
        fclose(log_file);
    }
}

// Function to clean up resources
void cleanup() {
    gpioFree();
    i2c_close(i2c_fd);
    pigpioTerminate();
}

// SIGINT signal handler
void SIGINTHandler(int signum) {
    printf("Received SIGINT, cleaning up...\n");
    cleanup();
    exit(EXIT_SUCCESS);
}

