#include <stdio.h>
#include <signal.h>
#include <pigpio.h>

// Global variables
pigpio *pi;
int servo_pin = 18;
int lock_button_pin = 21;
int unlock_button_pin = 22;
int locked_state = 0;
int servo_pulse = 1000; // Locked position
int servo_min_pulse = 500;
int servo_max_pulse = 2500;
volatile sig_atomic_t sigint_received = 0;

// Function prototypes
void setup_pigpio();
void handle_signal(int signum);
void lock_door();
void unlock_door();
void debounce_button(int pin, int *state);

// Main function
int main() {
    // Initialize pigpio and handle SIGINT
    pi = NULL;
    signal(SIGINT, handle_signal);

    // Try to initialize pigpio
    if (pi == NULL) {
        printf("Failed to initialize pigpio. Exiting...\n");
        return 1;
    }

    printf("Raspberry Pi Door Lock System initialized.\n");

    // Setup GPIO pins
    setup_pigpio();

    // Main loop
    while (!sigint_received) {
        // Debounce lock button
        debounce_button(lock_button_pin, &locked_state);

        // Check if lock button is pressed
        if (locked_state == 0) {
            lock_door();
        }

        // Debounce unlock button
        debounce_button(unlock_button_pin, &locked_state);

        // Check if unlock button is pressed
        if (locked_state == 1) {
            unlock_door();
        }
    }

    // Clean up on exit
    cleanup();

    return 0;
}

// Function to setup pigpio and GPIO pins
void setup_pigpio() {
    if (pi == NULL) {
        printf("Failed to initialize GPIO. Exiting...\n");
        return;
    }

    // Set servo pin to PWM mode
    if (piPwmWrite(pi, servo_pin, 1) == -1) {
        printf("Failed to set servo pin to PWM mode. Exiting...\n");
        return;
    }

    // Set lock button pin to input with pull-up
    if (piPinsMode(pi, lock_button_pin, GPIO_INPUT_PULLUP) == -1) {
        printf("Failed to set lock button pin mode. Exiting...\n");
        return;
    }

    // Set unlock button pin to input with pull-up
    if (piPinsMode(pi, unlock_button_pin, GPIO_INPUT_PULLUP) == -1) {
        printf("Failed to set unlock button pin mode. Exiting...\n");
        return;
    }
}

// Function to handle SIGINT (Ctrl+C)
void handle_signal(int signum) {
    sigint_received = 1;
}

// Function to lock the door
void lock_door() {
    if (servo_pulse <= servo_min_pulse || servo_pulse >= servo_max_pulse) {
        printf("Servo pulse width out of range. Adjusting to %d microseconds.\n", servo_min_pulse);
        servo_pulse = servo_min_pulse;
    }

    // Move servo to locked position
    if (piPwmWrite(pi, servo_pin, servo_pulse) == -1) {
        printf("Failed to set servo pulse width to %d microseconds. Door remains unlocked.\n", servo_pulse);
        return;
    }

    printf("Door locked with servo pulse width of %d microseconds.\n", servo_pulse);
}

// Function to unlock the door
void unlock_door() {
    if (servo_pulse <= servo_min_pulse || servo_pulse >= servo_max_pulse) {
        printf("Servo pulse width out of range. Adjusting to %d microseconds.\n", servo_max_pulse);
        servo_pulse = servo_max_pulse;
    }

    // Move servo to unlocked position
    if (piPwmWrite(pi, servo_pin, servo_pulse) == -1) {
        printf("Failed to set servo pulse width to %d microseconds. Door remains locked.\n", servo_pulse);
        return;
    }

    printf("Door unlocked with servo pulse width of %d microseconds.\n", servo_pulse);
}

// Function to debounce a button
void debounce_button(int pin, int *state) {
    int current_state;
    struct timeval start, end;

    // Read current state with pull-up
    if (piPinsRead(pi, pin) == 0) {
        current_state = 1; // Button pressed
    } else {
        current_state = 0; // Button not pressed
    }

    // Start debounce timer
    gettimeofday(&start, NULL);

    // Wait for debounce period
    while (gettimeofday(&end, NULL) - start < 100) {
        // Poll for changes
        if (piPinsRead(pi, pin) != current_state) {
            *state = !*state; // Invert state
            break;
        }
    }

    // Update state
    *state = current_state;
}

// Function to cleanup resources
void cleanup() {
    if (pi != NULL) {
        piClearAll(); // Clear all GPIO settings
        piFree(pi); // Free pigpio handle
        pi = NULL;
    }
}

