This C program uses the `pigpio` library to control a servo motor connected to GPIO18 for locking and unlocking a door. It also handles two push buttons for locking and unlocking the door, using internal pull-ups to detect active-low signals. The program debounces button presses to avoid multiple activations from a single press. It gracefully handles initialization failures and cleans up resources on exit, including releasing the `pigpio` handle and clearing all GPIO settings. The servo pulse width is constrained to a safe range of 500-2500 microseconds to prevent damage to the servo motor.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO17 17
#define GPIO27 27

// Function prototypes
void setup_hardware(void);
void pulse_motor(int gpio, int duration_ms);
void cleanup_hardware(void);
void handle_signal(int signum);

// Main function
int main(int argc, char **argv) {
    // Initialize GPIO lines
    setup_hardware();

    // Signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (1) {
        pulse_motor(GPIO17, 200);
        pulse_motor(GPIO27, 300);
    }

    // Cleanup on exit
    cleanup_hardware();

    return 0;
}

// Function to setup hardware
void setup_hardware(void) {
    // Request GPIO lines
    if (gpiod_line_request_output(GPIO17, GPIOD_OUT_HIGH) < 0) {
        fprintf(stderr, "Error requesting GPIO %u: %s\n", GPIO17, gpiod_error_string(-1));
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(GPIO27, GPIOD_OUT_HIGH) < 0) {
        fprintf(stderr, "Error requesting GPIO %u: %s\n", GPIO27, gpiod_error_string(-1));
        gpiod_line_release(GPIO17);
        exit(EXIT_FAILURE);
    }

    // Set initial state to low (off)
    if (gpiod_line_set_value(GPIO17, 0) < 0) {
        fprintf(stderr, "Error setting value of GPIO %u: %s\n", GPIO17, gpiod_error_string(-1));
        gpiod_line_release(GPIO17);
        gpiod_line_release(GPIO27);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_set_value(GPIO27, 0) < 0) {
        fprintf(stderr, "Error setting value of GPIO %u: %s\n", GPIO27, gpiod_error_string(-1));
        gpiod_line_release(GPIO17);
        gpiod_line_release(GPIO27);
        exit(EXIT_FAILURE);
    }
}

// Function to pulse a motor
void pulse_motor(int gpio, int duration_ms) {
    struct gpiod_line *line;
    int ret;

    // Request output line
    line = gpiod_line_request_output(gpio, GPIOD_OUT_HIGH);
    if (line == NULL) {
        fprintf(stderr, "Error requesting output line for GPIO %u: %s\n", gpio, gpiod_error_string(-1));
        return;
    }

    // Set line high (on) and wait
    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting value of GPIO %u: %s\n", gpio, gpiod_error_string(-1));
        gpiod_line_release(line);
        return;
    }

    // Wait for the duration
    usleep(duration_ms * 1000);

