        int start = pigpio_get_tsc();
        while (pigpio_read(GPIO_PIN) == 0) { // Wait for mark
            // Do nothing
        }
        int mark_duration = pigpio_get_tsc() - start;

        // Wait for space
        while (pigpio_read(GPIO_PIN) == 1) {
            // Do nothing
        }
        int space_duration = pigpio_get_tsc() - start;

        // Calculate bit value based on duration
        if (mark_duration < 560 && space_duration > 1690) {
            frame.address |= (1U << (mark_duration % 560)); // Logic 0
        } else {
            frame.address |= (1U << (space_duration % 560)); // Logic 1
        }

        // Repeat for remaining bits
        for (int i = 0; i < 12; ++i) {
            if (pigpio_read(GPIO_PIN) == 0) {
                // Mark
                mark_duration = pigpio_get_tsc() - start;
                frame.address |= (1U << (mark_duration % 560));
            } else {
                // Space
                space_duration = pigpio_get_tsc() - start;
                frame.address &= ~(1U << (space_duration % 560));
            }
        }

        // Check NEC checksum
        uint8_t checksum = 0;
        for (int i = 0; i < 12; ++i) {
            checksum ^= frame.address >> (i * 8);
        }
        if (frame.address != (frame.address ^ checksum)) {
            // Invalid checksum
            return;
        }

        // Decode command
        frame.command = pigpio_read(GPIO_PIN); // Read command bit

        // Publish to MQTT
        MQTTMessage mqttMsg = { MQTT_TOPIC, "{\"address\":0x"PRIx32", \"command\":0x"PRIx8"}" };
        mqtt_publish(&mqtt, MQTT_BROKER, &mqttMsg);

        // Log to syslog
        syslog(LOG_INFO, "NEC frame decoded: address 0x%X, command 0x%X", frame.address, frame.command);
    }
}

int main() {
    // Initialize pigpio
    if (pigpio_init() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    // Initialize MQTT client
    MQTTClient *mqtt = NULL;
    if ((mqtt = mqtt_connect(NULL, MQTT_BROKER, 1883, 0)) == NULL) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker");
        pigpio_cleanup(); // Clean up pigpio resources
        return EXIT_FAILURE;
    }

    // Register signal handlers
    struct sigaction intHandler;
    sigemptyset(&intHandler.sa_mask);
    intHandler.sa_handler = SIG_IGN; // Ignore SIGINT
    sigaction(SIGINT, &intHandler, NULL);
    sigemptyset(&intHandler.sa_mask);
    intHandler.sa_handler = sigterm_handler; // Handle SIGTERM
    sigaction(SIGTERM, &intHandler, NULL);

    // Set GPIO pin mode and enable interrupts
    if (pigpio_mode(GPIO_PIN, pigpioOUTPUT) < 0 || pigpio_set_pull_up_down(GPIO_PIN, pigpioPUD_UP) < 0) {
        syslog(LOG_ERR, "Failed to configure GPIO pin");
        pigpio_disconnect(mqtt); // Clean up MQTT resources
        mqtt_disconnect(mqtt); // Disconnect MQTT client
        return EXIT_FAILURE;
    }

    // Set up pigpio alert for falling edge
    if (pigpio_add_event(GPIO_PIN, pigpio Falling, onFallingEdge, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set up pigpio alert");
        pigpio_disconnect(mqtt); // Clean up MQTT resources
        mqtt_disconnect(mqtt); // Disconnect MQTT client
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        pigpio_wait(); // Wait for events
    }

    // Clean up resources on exit
    sigterm_handler(); // Handle SIGTERM
    pigpio_disconnect(mqtt); // Clean up MQTT resources
    mqtt_disconnect(mqtt); // Disconnect MQTT client
    pigpio_cleanup(); // Clean up pigpio resources

    return EXIT_SUCCESS;
}

// SIGTERM handler to ensure all resources are released
void sigterm_handler() {
    syslog(LOG_INFO, "Received SIGTERM, shutting down...");
    pigpio_disconnect(mqtt); // Clean up MQTT resources
    mqtt_disconnect(mqtt); // Disconnect MQTT client
    pigpio_cleanup(); // Clean up pigpio resources
    exit(EXIT_FAILURE); // Exit the program
}
