#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <netinet/in.h>
#include <net/if.h>
#include <linux/i2c-dev.h>

#define BH1750_ADDR_0X23 0x23
#define BH1750_ADDR_0X24 0x24
#define BH1750_ADDR_0X25 0x25
#define BH1750_ADDR_0X26 0x26

#define I2C_DEVICE "/dev/i2c-1"
#define UDP_MULTICAST_ADDR "239.255.255.250"
#define UDP_PORT 5005
#define UDP_MESSAGE_FORMAT "%d,%f"

int main() {
    int i2c_fd;
    struct sockaddr_in multicast_addr;
    struct ifreq ifr;
    int sock;
    char buffer[256];
    unsigned int sensor_id;
    float lux;
    int exit_flag = 0;

    // Initialize I2C file descriptor
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Prepare multicast address structure
    multicast_addr.sin_family = AF_INET;
    multicast_addr.sin_addr.s_addr = inet_addr(UDP_MULTICAST_ADDR);
    multicast_addr.sin_port = htons(UDP_PORT);

    // Get the network interface index for the multicast address
    if (ioctl(sock, SIOCGIFINDEX, &ifr) == -1) {
        perror("Failed to get interface index");
        close(sock);
        exit(EXIT_FAILURE);
    }

    // Open UDP socket
    sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock == -1) {
        perror("Failed to create UDP socket");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (!exit_flag) {
        // Read light levels from sensors
        for (sensor_id = 1; sensor_id <= 4; sensor_id++) {
            unsigned char addr = BH1750_ADDR_0X23 + sensor_id; // Adjust for different addresses if needed

            if (ioctl(i2c_fd, I2C_SLAVE, addr) == -1) {
                printf("Failed to set slave address for sensor %d\n", sensor_id);
                lux = NAN; // Mark as failed
                continue;
            }

            // Send command to enter high-resolution mode
            if (write(i2c_fd, &BH1750_HIGH_RES_MODE, 1) != 1) {
                printf("Failed to write to sensor %d\n", sensor_id);
                lux = NAN; // Mark as failed
                continue;
            }

            // Wait for conversion (180 ms)
            usleep(180000);

            // Read two bytes for light level
            if (read(i2c_fd, &lux, 2) != 2) {
                printf("Failed to read from sensor %d\n", sensor_id);
                lux = NAN; // Mark as failed
                continue;
            }

            // Convert to lux
            lux = ((lux[0] << 8) | lux[1]) / 1.2;
        }

        // Construct and send UDP multicast message
        sprintf(buffer, "%d,%f", 1, lux[0]);
        strcat(buffer, ";");
        strcat(buffer, "%f", lux[1]);
        strcat(buffer, ";");
        strcat(buffer, "%f", lux[2]);
        strcat(buffer, ";");
        strcat(buffer, "%f", lux[3]);

        if (sendto(sock, buffer, strlen(buffer), 0, (struct sockaddr *)&multicast_addr, sizeof(struct sockaddr_in)) == -1) {
            perror("Failed to send UDP message");
            exit_flag = 1; // Set flag to exit on SIGINT/SIGTERM
        }
    }

    // Close resources on exit
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (sock != -1) {
        close(sock);
    }

    return EXIT_SUCCESS;
}

