#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/time.h>
#include <signal.h>

#define I2C_DEVICE_PATH "/dev/i2c-1"
#define SENSOR_ADDRESS 0x28
#define MAX_RETRIES 3
#define DELAY_MS 100

// Function prototypes
void handle_signal(int signum);
int i2c_open_device();
void i2c_close_device();
int i2c_write_zero_bytes(int fd);
int i2c_read_bytes(int fd, uint8_t *data, size_t len);
double convert_raw_to_slpm(uint16_t raw);

// Main function
int main() {
    // Initialize signal handler
    signal(SIGINT, handle_signal);

    // Open I2C device
    int fd = i2c_open_device();

    if (fd == -1) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Log file
    FILE *log_file = fopen("airflow_log.txt", "a+");
    if (log_file == NULL) {
        perror("Failed to open log file");
        fclose(fd);
        return EXIT_FAILURE;
    }

    struct timeval start_time;
    struct timezone tz;
    gettimeofday(&start_time, &tz);

    while (1) {
        // Attempt to read airflow data
        uint16_t raw_flow;
        int retries = 0;

        do {
            if (i2c_write_zero_bytes(fd) < 0) {
                if (retries < MAX_RETRIES) {
                    // Retry with delay
                    sleep(DELAY_MS);
                    retries++;
                } else {
                    perror("Failed to send zero-length write");
                    break;
                }
            }

            if (i2c_read_bytes(fd, &raw_flow, 2) < 0) {
                if (retries < MAX_RETRIES) {
                    // Retry with delay
                    sleep(DELAY_MS);
                    retries++;
                } else {
                    perror("Failed to read airflow data");
                    break;
                }
            }

            // Convert raw flow to SLPM
            double slpm = convert_raw_to_slpm(raw_flow);

            // Log the flow rate
            char buffer[128];
            sprintf(buffer, "%ldus %5.2f SLPM\n", (long unsigned int)(start_time.tv_sec * 1000000 + start_time.tv_usec), slpm);
            fprintf(log_file, "%s", buffer);

            // Reset retries for next iteration
            retries = 0;
        } while (retries < MAX_RETRIES);

        // Close I2C device and flush log file on SIGINT
        handle_signal(SIGINT);
    }

    // Close I2C device and log file
    i2c_close_device();
    fclose(log_file);

    return EXIT_SUCCESS;
}

// SIGINT handler
void handle_signal(int signum) {
    // Close I2C device
    i2c_close_device();

    // Flush log file
    fflush(log_file);
}

// Function to open I2C device
int i2c_open_device() {
    int fd;
    if ((fd = open(I2C_DEVICE_PATH, O_RDWR)) < 0) {
        perror("open");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("ioctl");
        close(fd);
        return -1;
    }
    return fd;
}

// Function to close I2C device
void i2c_close_device() {
    close(fd);
}

// Function to perform zero-length write to the sensor
int i2c_write_zero_bytes(int fd) {
    uint8_t zero = 0;
    if (write(fd, &zero, 1) != 1) {
        perror("write");
        return -1;
    }
    return 0;
}

// Function to read 2 bytes from the sensor
int i2c_read_bytes(int fd, uint8_t *data, size_t len) {
    if (read(fd, data, len) != len) {
        perror("read");
        return -1;
    }
    return len;
}

// Convert raw flow value to SLPM
double convert_raw_to_slpm(uint16_t raw) {
    return (raw - 3277) * 0.1;
}

