#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE_PATH "/dev/i2c-1"
#define AS7341_ADDR 0x39
#define WHO_AM_I_REG 0x24
#define ENABLE_REG 0x80
#define CFG6_REG 0xAF
#define SP_EN_REG 0x81
#define SPECTRAL_CHANNELS_START 0x60

// AS7341 register addresses for spectral channels
#define F1_REG 0x60
#define F2_REG 0x61
#define F3_REG 0x62
#define F4_REG 0x63
#define F5_REG 0x64
#define F6_REG 0x65
#define F7_REG 0x66
#define F8_REG 0x67
#define CLEAR_REG 0x68
#define NIR_REG 0x69

// Simplified lux approximation constants
#define LUX_FACTOR 0.00047

// Function prototypes
void open_i2c_device();
void close_i2c_device();
int i2c_write(uint8_t addr, uint8_t reg, uint8_t data);
int i2c_read(uint8_t addr, uint8_t reg, uint8_t *data);
void compute_lux(uint8_t *data);
void write_to_log_file(const char *message);
void handle_interrupts(int signum);

int main() {
    srand(time(NULL));

    // Open I2C device
    open_i2c_device();

    // Initialization sequence
    if (i2c_write(AS7341_ADDR, WHO_AM_I_REG, 0) != 0) {
        fprintf(stderr, "Error writing to WHO_AM_I register\n");
        return EXIT_FAILURE;
    }
    if (i2c_read(AS7341_ADDR, WHO_AM_I_REG, &data) != 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        close_i2c_device();
        return EXIT_FAILURE;
    }
    if (data != 0x19) {
        fprintf(stderr, "Expected WHO_AM_I register value 0x19, got 0x%X\n", data);
        close_i2c_device();
        return EXIT_FAILURE;
    }

    // Power on the sensor
    if (i2c_write(AS7341_ADDR, ENABLE_REG, 0x20) != 0) {
        fprintf(stderr, "Error writing to ENABLE register\n");
        close_i2c_device();
        return EXIT_FAILURE;
    }

    // Configure SMUX for spectral readings
    if (i2c_write(AS7341_ADDR, CFG6_REG, 0x01) != 0) {
        fprintf(stderr, "Error writing to CFG6 register\n");
        close_i2c_device();
        return EXIT_FAILURE;
    }

    // Enable spectral measurement
    if (i2c_write(AS7341_ADDR, SP_EN_REG, 0x01) != 0) {
        fprintf(stderr, "Error writing to SP_EN register\n");
        close_i2c_device();
        return EXIT_FAILURE;
    }

    // Read spectral channels
    uint8_t spectral_data[10];
    for (int i = 0; i < 10; i++) {
        if (i2c_read(AS7341_ADDR, SPECTRAL_CHANNELS_START + i, spectral_data + i) != 0) {
            fprintf(stderr, "Error reading spectral channel %d\n", i);
            close_i2c_device();
            return EXIT_FAILURE;
        }
    }

    // Compute lux approximation
