#define F1_REG 0x60
#define F2_REG 0x61
#define F3_REG 0x62
#define F4_REG 0x63
#define F5_REG 0x64
#define F6_REG 0x65
#define F7_REG 0x66
#define F8_REG 0x67
#define CLEAR_REG 0x68
#define NIR_REG 0x69

// Simplified lux approximation constants
#define LUX_FACTOR 0.00047

// Function prototypes
