void close_i2c_device();
int i2c_write(uint8_t addr, uint8_t reg, uint8_t data);
int i2c_read(uint8_t addr, uint8_t reg, uint8_t *data);
void compute_lux(uint8_t *data);
void write_to_log_file(const char *message);
void handle_interrupts(int signum);

