    srand(time(NULL));

    // Open I2C device
    open_i2c_device();

    // Initialization sequence
    if (i2c_write(AS7341_ADDR, WHO_AM_I_REG, 0) != 0) {
        fprintf(stderr, "Error writing to WHO_AM_I register\n");
        return EXIT_FAILURE;
    }
    if (i2c_read(AS7341_ADDR, WHO_AM_I_REG, &data) != 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        close_i2c_device();
        return EXIT_FAILURE;
    }
    if (data != 0x19) {
        fprintf(stderr, "Expected WHO_AM_I register value 0x19, got 0x%X\n", data);
        close_i2c_device();
        return EXIT_FAILURE;
    }

    // Power on the sensor
    if (i2c_write(AS7341_ADDR, ENABLE_REG, 0x20) != 0) {
        fprintf(stderr, "Error writing to ENABLE register\n");
        close_i2c_device();
        return EXIT_FAILURE;
    }

    // Configure SMUX for spectral readings
    if (i2c_write(AS7341_ADDR, CFG6_REG, 0x01) != 0) {
        fprintf(stderr, "Error writing to CFG6 register\n");
        close_i2c_device();
        return EXIT_FAILURE;
