            close_i2c_device();
            return EXIT_FAILURE;
        }
    }

    // Compute lux approximation
    compute_lux(spectral_data);

    // Log results
    write_to_log_file("Timestamp,Values\n");
    write_to_log_file(time(NULL) comma_separated_values(spectral_data));

    // Repeat every 5 seconds
    while (1) {
        sleep(5);
        // Handle SIGINT (Ctrl+C)
        if (signal(SIGINT, handle_interrupts) == SIG_ERR) {
