    uint8_t i2c_addr = DEFAULT_ADDR;
    uint8_t interval = DEFAULT_INTERVAL;
    char *output_file = DEFAULT_OUTPUT_FILE;
    int16_t x_low, x_high, y_low, y_high, z_low, z_high;
    double x_g, y_g, z_g;
