            return 1;
        }
    }

    // Open I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd == -1) {
        error_log("Failed to open I2C device: " strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(fd, I2C_SLAVE, i2c_addr) < 0) {
        error_log("Failed to set I2C slave address: " strerror(errno));
        close(fd);
        return 1;
    }

    // Main loop
