        convert_to_g(y_high, &y_g);
        convert_to_g(z_low, &z_g);
        convert_to_g(z_high, &z_g);

        // Log data
        timestamp.tv_sec = time(NULL);
        write_to_csv(strftime("%Y-%m-%d %H:%M:%S", &timestamp), x_g, y_g, z_g);

        // Wait for the interval
