    }

    // Close I2C device and CSV file on exit
    handle_signals(SIGINT);
    handle_signals(SIGTERM);

    close(fd);
    if (output_file != DEFAULT_OUTPUT_FILE) {
        fclose(stdout); // Ensure CSV file is flushed and closed
        free(output_file);
    }

    return 0;
