#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <netinet/in.h>
#include <net/if.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define BH1750_ADDR 0x23
#define BH1750_CMD_POWER_ON 0x01
#define BH1750_CMD_CONT_HIGH_RES 0x10
#define BH1750_I2C_DEVICE "/dev/i2c-1"

// Function prototypes
void handle_signal(int signum);
void send_lux_over_udp(uint16_t raw_lux);
void read_bh1750_light(uint16_t *raw_lux);
void cleanup();

int main() {
    // Initialize signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize I2C device file descriptor
    int i2c_fd = open(BH1750_I2C_DEVICE, O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Initialize UDP socket
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd == -1) {
        perror("Failed to create UDP socket");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    struct sockaddr_in broadcast_addr;
    memset(&broadcast_addr, 0, sizeof(broadcast_addr));
    broadcast_addr.sin_family = AF_INET;
    broadcast_addr.sin_addr.s_addr = INADDR_ANY;
    broadcast_addr.sin_port = htons(5000);

    // Bind the socket to INADDR_ANY and port 5000
    if (bind(sockfd, (struct sockaddr *)&broadcast_addr, sizeof(broadcast_addr)) == -1) {
        perror("Failed to bind UDP socket");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Set the TTL to 1 for the multicast packet
    if (setsockopt(sockfd, IPPROTO_IP, IP_MULTICAST_TTL, &1, sizeof(int)) == -1) {
        perror("Failed to set TTL for UDP socket");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    uint16_t raw_lux;
    while (1) {
        // Send power-on command to BH1750
        if (write(i2c_fd, &BH1750_CMD_POWER_ON, 1) != 1) {
            perror("Failed to write power-on command");
            usleep(1000000); // Wait 1 second before retrying
            continue;
        }

        // Send high-resolution mode command to BH1750
