time_t last_log_time = 0;

// Main function
int main() {
    signal(SIGINT, handle_signals);
    signal(SIGTERM, handle_signals);

    // Setup the UART
    setup_uart("/dev/serial0");

    while (1) {
        fd_set readfds;
        struct timeval tv;

        // Set up the select timeout
        tv.tv_sec = TIMEOUT / 1000;
        tv.tv_usec = (TIMEOUT % 1000) * 1000;

        // Initialize the read set
        FD_ZERO(&readfds);
        FD_SET(uart_fd, &readfds);

        // Perform the select
        if (select(uart_fd + 1, &readfds, NULL, NULL, &tv) == -1) {
            perror("select");
            exit(EXIT_FAILURE);
        }

        if (FD_ISSET(uart_fd, &readfds)) {
            ssize_t bytes_read = read(uart_fd, buffer, BUFFER_SIZE);

            if (bytes_read > 0) {
                // Check if we have a complete line
                if (buffer[bytes_read - 1] == '\n') {
                    parse_radar_line(buffer);
                } else {
                    // Accumulate partial reads
                    strcpy(buffer, "");
                }
            } else if (bytes_read == 0) {
                // Sensor absent or bus error
                printf("Sensor absent or bus error detected.\n");
            } else {
                // Error reading from the UART
                perror("read");
                exit(EXIT_FAILURE);
            }
        }

        // Update the last log time for timestamp calculation
        time_t now = time(NULL);
        if (now > last_log_time) {
            last_log_time = now;
            printf("Timestamp: %s, Range: N/A meters\n", ctime(&last_log_time));
        }
    }

    // Close resources on exit
    close_resources();

    return 0;
}

// Function to setup UART
void setup_uart(const char *device) {
    // Open the UART device
    uart_fd = open(device, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (uart_fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    // Get the current terminal settings
    tcgetattr(uart_fd, &old_tio);

    // Configure the UART for non-canonical mode with 0.5s inter-byte timeout
    struct termios new_tio = old_tio;
    new_tio.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;
    new_tio.c_iflag = IGNPAR | INPCK;
    new_tio.c_lflag = 0;
    new_tio.c_oflag = 0;
    new_tio.c_cc[VTIME] = 50; // 0.5 seconds
    new_tio.c_cc[VDELAY] = 0; // No delay

    if (tcsetattr(uart_fd, TCSANOW, &new_tio) == -1) {
        perror("tcsetattr");
        exit(EXIT_FAILURE);
    }
}

// Function to handle signals
void handle_signals(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Shutting down gracefully...\n");
        close_resources();
        exit(EXIT_SUCCESS);
    }
}

// Function to parse radar line
void parse_radar_line(char *line) {
    char *timestamp_str = strtok(line, ",");
    char *range_str = strtok(NULL, ",");
    double range;

    // Convert range string to double
    if (sscanf(range_str, "%lf", &range) != 1) {
        fprintf(stderr, "Invalid range string format: %s\n", range_str);
        return;
    }

    // Format and print the timestamp
    time_t now = time(NULL);
    char timestamp_str[50];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&now));

    printf("Timestamp: %s, Range: %.2f meters\n", timestamp_str, range);
}

// Function to close resources
void close_resources() {
    if (uart_fd != -1) {
        close(uart_fd);
        uart_fd = -1;
    }

    // Free the parsed line buffer
    if (parsed_line != NULL) {
        free(parsed_line);
        parsed_line = NULL;
    }
}
