int gpio_setup(int gpio, int direction, int pull_up) {
    int rc = 0;
    rc = pigpio_direction(gpio, direction);
    if (rc == -1) {
        fprintf(stderr, "Failed to set GPIO %d direction: %s\n", gpio, pigpio_error());
        return -1;
    }

    rc = pigpio_set_pull_up_down(gpio, pull_up);
    if (rc == -1) {
        fprintf(stderr, "Failed to set GPIO %d pull-up: %s\n", gpio, pigpio_error());
        return -1;
    }

    return rc;
}

// Function to read sensors and update states
void read_sensors(struct sensor_state *states) {
    int left_state = 0, middle_state = 0, right_state = 0;

    // Read GPIO values
    left_state = pigpio_read(gpio, 4);
    middle_state = pigpio_read(gpio, 17);
    right_state = pigpio_read(gpio, 27);

    // Update states
    states->left = (left_state == 0);
    states->middle = (middle_state == 0);
    states->right = (right_state == 0);
}

// Function to print emergency stop message
void emergency_stop(const char *message) {
    FILE *serial_fd = fopen("/dev/ttyAMA0", "w+");
    if (serial_fd == NULL) {
        fprintf(stderr, "Failed to open serial port: %s\n", strerror(errno));
        return;
    }

    fprintf(serial_fd, "%s\n", message);
    fclose(serial_fd);

    // Handle serial write error (if any)
    if (ferror(serial_fd)) {
        fprintf(stderr, "Error writing to serial port: %s\n", strerror(errno));
    }
}

// Function to cleanup resources
void cleanup() {
    // Close GPIO pins
    for (int i = 4; i <= 27; i++) {
        pigpio_close(i);
    }

    // Free pigpio handle
    pigpio_free(NULL);
}

